	   trong đúng một lượt. Nhận cả hai dạng: có thẻ bọc và không. */
	return preg_match( '~<tr[^>]*><td>(?:<a[^>]*>)?' . preg_quote( $ten, '~' )
		. '(?:</a>)?(?:(?!</tr>).)*</tr>~s', $h, $m ) ? $m[0] : '';
}
function vp_o_dau_tien( $h, $ten ) {
	$hang = vp_hang_cua( $h, $ten );
	return ( '' !== $hang && preg_match( '~<td class="oc[^"]*"[^>]*>.*?</td>~s', $hang, $m ) )
		? $m[0] : '';
}

