$o_thuong = vp_o_dau_tien( $h_vp, 'Người VPA' );
t( 'ngày đủ cặp giờ thì KHÔNG đỏ và KHÔNG có dấu ?',
	strpos( $o_thuong, 'hong' ) === false && strpos( $o_thuong, ' ?' ) === false, $o_thuong );
t( 'chú giải nói dấu ? nghĩa là gì',
	strpos( $h_vp, '? = có giờ vào mà THIẾU giờ ra' ) !== false, $h_vp );
/* 🔴 CA ĐÊM QUÊN BẤM RA CŨNG LÀ QUÊN BẤM. Xét mỗi hàng chính là hàng 2 lặng lẽ biến mất — mà
   ca đêm mới là ca dễ quên bấm nhất: người ta về lúc 4 giờ sáng. */
$o_dem = vp_o_dau_tien( $h_vp, 'Người VPF' );
t( 'dựng cảnh: tìm được ô ca đêm quên bấm ra', '' !== $o_dem, substr( $h_vp, 0, 300 ) );
t( '🔴 ca đêm quên bấm ra cũng ĐỎ và có dấu ?',
	strpos( $o_dem, 'class="oc hong' ) !== false
	&& strpos( $o_dem, '<span class="chu-hong"> ?</span>' ) !== false, $o_dem );
t( 'và chú thích nói rõ là HÀNG 2', strpos( $o_dem, 'hàng 2 (ca đêm) có giờ vào' ) !== false, $o_dem );

/* 🔴 HÀNG 2 QUÊN BẤM RA MÀ CA ẤY KHÔNG CHO CÔNG NÀO — dòng vẫn phải còn.
   Cảnh ở lưới trên (VPF) chưa đủ để canh nửa sau của điều kiện giữ dòng: ca đêm quên bấm ra
   luôn kèm `demSangNgay`, còn tăng ca thì `tangCaCong` mặc định 0.5 nên `tong > 0` — cả hai
   đều tự giữ dòng bằng đường khác. Đã phá thử để thấy: bỏ hẳn nhánh `h2vao && !h2ra` mà bộ
   thử vẫn xanh.
   Chỗ nó thật sự cắn: cơ sở khai **tăng ca = 0 công** (nhiều nơi trả tăng ca bằng tiền, không
   quy ra công). Lúc ấy một người vào 18:00 rồi quên bấm ra sẽ cho `tong = 0`, không `caLa`,
   không `demSangNgay` — dòng bị xoá sạch, ô hiện dấu `·` y như ngày NGHỈ. Người quên bấm bị
   coi là người không đi làm.
   Gọi thẳng lõi vì đây là hàm THUẦN — dựng cấu hình riêng cho cơ sở chỉ để thử một số là đắt. */
$cfg_tc0 = VHCC_Luong::vp_cfg( '' );
$cfg_tc0['tangCaCong'] = 0;
$r_tc0 = VHCC_Luong::vp_tinh_nguoi( $cfg_tc0, false, array(
	'2026-07-14' => array( 'dem' => array( VHCC_DB::giay( '18:00:00' ), null ) ),
) );
t( '🔴 tăng ca 0 công + hàng 2 quên bấm ra: NGÀY ẤY VẪN CÒN DÒNG, không bị xoá',
	isset( $r_tc0['2026-07-14'] ), implode( ',', array_keys( $r_tc0 ) ) );
if ( isset( $r_tc0['2026-07-14'] ) ) {
	teq( 'và đúng là 0 công — giữ dòng KHÔNG phải là bịa thêm công',
		0.0, (float) $r_tc0['2026-07-14']['tong'] );
	teq( 'giờ vào hàng 2 còn nguyên để người ta biết bù cho ai',
		'18:00', $r_tc0['2026-07-14']['h2vao'] );
	teq( 'và giờ ra hàng 2 rỗng', '', $r_tc0['2026-07-14']['h2ra'] );
}
/* Ngược lại: hàng 2 ĐỦ CẶP mà 0 công thì không có gì để bù — dòng ấy xoá đi là đúng, giữ lại
   chỉ tổ rác bảng. Không có phép thử này thì "giữ mọi dòng" cũng xanh. */
$r_tc0b = VHCC_Luong::vp_tinh_nguoi( $cfg_tc0, false, array(
	'2026-07-15' => array( 'dem' => array( VHCC_DB::giay( '18:00:00' ), VHCC_DB::giay( '20:00:00' ) ) ),
) );
t( 'hàng 2 đủ cặp mà 0 công thì KHÔNG giữ dòng',
	! isset( $r_tc0b['2026-07-15'] ), implode( ',', array_keys( $r_tc0b ) ) );

/* 🔴 MỘT NGƯỜI = MỘT HÀNG. Còn sót một ô đầu dòng '↳' nghĩa là vẫn còn hàng riêng. */
t( '🔴 không còn hàng ↳ riêng nào trong lưới',
	strpos( $h_vp, 'padding-left:20px">↳' ) === false, $h_vp );

/* 🔴 ĐÊM CÓ LÀM MÀ KHÔNG ĐỦ GIỜ TỐI THIỂU -> 🌙 KÈM SỐ 0, NỀN ĐỎ.
   Đây là ô đắt nhất của cả lưới: người ta ĐÃ thức trắng một đêm mà công không vào. Để nó giống
   hệt một đêm bình thường thì tháng nào cũng có người mất công mà không ai thấy — mà chính chủ
   thì chỉ biết lúc nhận lương.
   ⚠️ Cảnh riêng, THÁNG RIÊNG: mặc định `demToiThieuGio = 0` (không xét) nên tháng 7 ở trên
      không bao giờ chạm nhánh này. Đổi cấu hình chung rồi để đó là mọi phép thử lương phía dưới
      đọc một bộ số khác — nên đặt xong phải TRẢ LẠI ngay. */
VHCC_Luong::dat_vp_cfg( $u_ad_cfg, array( 'demToiThieuGio' => 4 ), '', '' );
teq( 'dựng cảnh: ca đêm nay đòi tối thiểu 4 tiếng', 4.0, (float) VHCC_Luong::vp_cfg()['demToiThieuGio'] );
vhcc_cham( $VP_CS, '2026-09-07', 'VPB', '', '08:30:00', '17:00:00' );
vhcc_cham_dem( $VP_CS, '2026-09-07', 'VPB', '22:00:00', '23:30:00' );   /* 1.5h < 4h */
$h_td = vhcc_web( '135791', array(), array( 'man' => 'vp', 'ccs' => $VP_CS, 'cth' => '2026-09' ) );
t( '🔴 đêm thiếu giờ tối thiểu -> dòng phụ hiện 🌙0 và được tô ĐỎ',
	strpos( $h_td, '<div class="mdem chu-hong">🌙0</div>' ) !== false, $h_td );
t( 'và chú thích nói rõ thiếu bao nhiêu so với mức tối thiểu',
	strpos( $h_td, 'mức tối thiểu' ) !== false, $h_td );
VHCC_Luong::dat_vp_cfg( $u_ad_cfg, array( 'demToiThieuGio' => 0 ), '', '' );
teq( 'trả lại cấu hình chung, kẻo mấy phép thử lương phía dưới đọc một bộ số khác',
	0.0, (float) VHCC_Luong::vp_cfg()['demToiThieuGio'] );
t( 'và chú thích nói ca đêm cho công sang ngày nào',
	strpos( $h_vp, 'cho công vào ngày' ) !== false, $h_vp );

/* Phần chú giải: mỗi màu phải có một câu giải thích, kẻo người đọc chỉ thấy "ô này khác màu". */
foreach ( array( 'có tăng ca', 'có công đêm', 'kế toán chấm chủ nhật', 'có giờ nhưng KHÔNG ra công' ) as $k_vp ) {
	t( 'chú giải có giải thích màu "' . $k_vp . '"', strpos( $h_vp, $k_vp ) !== false, $h_vp );
}
t( 'nói rõ dấu chấm nghĩa là không có dữ liệu',
	strpos( $h_vp, 'không có dữ liệu chấm công' ) !== false );

/* 🔴 Ô đối chiếu: lưới tự cộng lại và so với tổng của phép tính. Lệch thì phải KÊU, không im
   lặng in ra hai con số khác nhau ở hai chỗ. */
/* 🔴 Ô ĐỐI CHIẾU. Lưới tự cộng lại rồi so với tổng của phép tính; lệch thì phải KÊU, không
   im lặng in ra hai con số khác nhau ở hai chỗ trên cùng một trang.
   Chuyện này KHÔNG xảy ra khi engine đúng, nên phải gọi thẳng hàm dựng lưới với dữ liệu cố tình
   lệch — chờ nó tự xảy ra thì phép thử chẳng bao giờ chạy tới nhánh đó. */
function vp_o_ngay( $ma, $ngay, $tong ) {
	return array( 'ma' => $ma, 'ten' => 'Người ' . $ma, 'ngay' => $ngay,
		'congNgay' => $tong, 'congTangCa' => 0.0, 'congDem' => 0.0, 'congBu' => 0.0, 'tong' => $tong,
		'phutNgay' => 480, 'gioNgay' => 8.0, 'khung' => '08:30-17:00',
		'kt7' => false, 'ktCnNghi' => false, 'caLa' => false, 'demTuNgay' => '', 'demSangNgay' => '',
		'demThieuGio' => false, 'demChuaDuCap' => false, 'gioDemThuc' => 0.0, 'buTuNgay' => '',
		'tuCoSo' => '',
		'vao' => '08:30', 'ra' => '17:00', 'h2vao' => '', 'h2ra' => '' );
}
/* ⚠️ Cảnh dựng tay phải mang ĐỦ khoá mà hàm thật nhận — thiếu `station` là PHP kêu
   "Undefined array key" và hàm đọc chuỗi rỗng, tức nó đang chạy trên một cảnh KHÔNG giống
   dữ liệu thật. Cảnh giả mà lệch khuôn thì phép thử đo một thứ khác. */
$b_lech = array( 'month' => '2026-07', 'station' => 'ZZ_CS',
	/* Bảng nói 5 công, mà lưới chỉ có 2 ngày × 1 công = 2. */
	'rows' => array( array( 'ma' => 'ZZ', 'ten' => 'Người ZZ', 'tong' => 5.0, 'laKeToan' => false ) ),
	'detail' => array( vp_o_ngay( 'ZZ', '2026-07-01', 1.0 ), vp_o_ngay( 'ZZ', '2026-07-02', 1.0 ) ) );
ob_start(); vhcc_goi_rieng( 'VHCC_Web', 've_luoi_vp', array( $b_lech ) ); $h_lech = ob_get_clean();
t( 'tổng lưới lệch tổng phép tính -> KÊU LÊN, không im lặng',
	strpos( $h_lech, 'KHÁC tổng của phép' ) !== false, $h_lech );
t( 'và in cả hai con số cạnh nhau để so',
	strpos( $h_lech, '≠ 5' ) !== false, $h_lech );
t( 'còn khi khớp thì nói khớp', strpos( $h_vp, 'Tổng từng người khớp' ) !== false );

/* Tháng không có dữ liệu -> nói rõ, và chỉ đường sang chỗ nạp. */
$h_vp0 = vhcc_web( '135791', array(), array( 'man' => 'vp', 'ccs' => $VP_CS, 'cth' => '2020-01' ) );
t( 'tháng trống thì nói rõ chưa có dữ liệu',
	strpos( $h_vp0, 'chưa có dữ liệu chấm công nào' ) !== false, $h_vp0 );
t( 'và chỉ sang chỗ nạp .csv', strpos( $h_vp0, 'Nạp công từ .csv' ) !== false, $h_vp0 );

/* 🔴 CHÍNH LƯỚI là thứ CHỈ ĐỌC — không có ô nhập giờ nào.
   ⚠️ Canh vào ĐÚNG khối lưới, không quét cả trang: màn đã gộp còn có khối Chấm công bù và khối
   Sửa giờ công, hai khối ấy CÓ ô nhập giờ và có quyền có. Quét cả trang là chốt đỏ oan, mà sửa
   cho xanh bằng cách bỏ chốt thì mất luôn thứ nó đang canh. */
$khoi_luoi = preg_match( '/Lưới cả tháng(.*?)(?=<div class="the" id="bucong")/s', $h_vp, $m_lu )
	? $m_lu[1] : '';
t( 'tìm được khối lưới trong màn đã gộp', '' !== $khoi_luoi, substr( $h_vp, 0, 200 ) );
t( 'lưới KHÔNG có ô nhập giờ nào',
	! preg_match( '/name="(gio_vao|gio_ra|bu_vao|bu_ra|sg_vao|sg_ra)"/', $khoi_luoi ), $khoi_luoi );
/* Và không lộ tiền: khối này nói về CÔNG, tiền là chuyện của màn lương (quyền khác). */
t( 'lưới không in ô tiền nào', strpos( $khoi_luoi, 'đ</td>' ) === false, $khoi_luoi );

/* ---- ĐƠN VỊ CỦA Ô DO BỘ PHẬN QUYẾT, không phải một công thức cho tất cả ---- */
/* Anh Thắng 26/08: *"này là cơ sở mà, nên kiểu chấm khác, tính theo giờ"* — anh mở lưới ở một
   CỬA HÀNG và thấy toàn 0.63 · 0.31 · 0.84, tức công thức Văn phòng (bậc thang theo khung
   08:30–17:00) đem áp lên nơi người ta làm ca gãy. Số vẫn ra, vẫn cộng được, chỉ là vô nghĩa. */
t( 'cơ sở Văn phòng thì ô là SỐ CÔNG', strpos( $h_vp, 'là <b>số công</b>' ) !== false, $h_vp );

$ADMIN_W = array( 'name' => 'Admin Soát Công', 'role' => 'Admin', 'coso' => '' );
$CS_GIO = 'FZ_SC_THU';                                  /* KHÔNG khai bộ phận -> không phải VP */
vhcc_cham( $CS_GIO, '2026-07-01', 'GIO1', '', '08:00:00', '17:30:00' );   /* 9.5h */
vhcc_cham( $CS_GIO, '2026-07-02', 'GIO1', '', '08:00:00', null );         /* thiếu giờ ra */
vhcc_cham( $CS_GIO, '2026-07-01', 'GIO1', 'CD', '21:00:00', '23:00:00' ); /* hàng riêng */
/* 🔴 Hàng ca đêm THẬT: ra 05:30 HÔM SAU, nên `gio_ra_giay` > 86400. Cần đúng ca này để chốt
   rằng phép tách ăn GIÂY THÔ — `vao`/`ra` dạng chữ đã bị `hhmmss` gói về trong một ngày, đọc
   từ đó thì 05:30 hôm sau trông y hệt 05:30 hôm nay và cả ca đêm biến mất. */
vhcc_cham_dem( $CS_GIO, '2026-07-05', 'GIO2', '21:30:00', '05:30:00' );
/* Một lượt nằm GỌN trong một ca — để canh ô chỉ hiện MỘT mã. Mọi lượt khác ở đây đều vắt qua
   hai ca, nên thiếu ca này thì phép thử "một ca thì một mã" không có ô nào để soi. */
vhcc_cham( $CS_GIO, '2026-07-06', 'GIO2', '', '07:00:00', '13:00:00' );
$h_gio = vhcc_web( '135791', array(), array( 'man' => 'vp', 'ccs' => $CS_GIO, 'cth' => '2026-07' ) );

t( 'cơ sở KHÔNG phải Văn phòng thì ô là SỐ GIỜ, không phải số công',
	strpos( $h_gio, 'là <b>số giờ làm</b>' ) !== false, $h_gio );
t( 'và nói rõ vì sao không dùng công thức Văn phòng ở đây',
	strpos( $h_gio, 'ca gãy' ) !== false, $h_gio );
t( 'và chỉ thẳng chỗ đổi cách tính',
	strpos( $h_gio, 'Cách tính công của từng cơ sở' ) !== false, $h_gio );
/* Nói rõ vì sao cơ sở này đang tính kiểu đó — "đã khai thẳng" hay "suy theo bộ phận". Không nói
   thì người ta đổi bộ phận cho gọn báo cáo rồi ngạc nhiên vì bảng công đổi theo. */
t( 'nói rõ vì sao đang tính kiểu đó',
	strpos( $h_gio, 'suy theo bộ phận' ) !== false || strpos( $h_gio, 'đã khai thẳng' ) !== false, $h_gio );
/* 🔴 Số giờ phải là số giờ THẬT, không phải số công lẻ. 08:00 -> 17:30 = 9.5 giờ. */
t( 'ô hiện đúng số giờ làm (9.5)', strpos( $h_gio, '>9.5</b>' ) !== false, $h_gio );
t( 'KHÔNG có ô nào mang số công lẻ kiểu 0.63', strpos( $h_gio, '>0.63<' ) === false, $h_gio );
/* Ba trạng thái, ba ký hiệu — gộp lại là xoá mất đúng ngày cần soi.
   ⚠️ Bóc lớp <a class="o-sua"> ra trước khi soi ô: từ 26/08/2026 mỗi ô là một đường bấm được
   (anh Thắng: *"sửa là sửa trực tiếp trong này luôn nhé"*). Nới chốt thành "có dấu chấm ở đâu
   đó trong trang" thì nó thôi canh KÝ HIỆU CỦA Ô — mà đó mới là thứ đang canh. */
$_boc = function ( $h ) {
	return preg_replace( '#<a class="o-sua"[^>]*>(.*?)</a>#s', '$1', $h );
};
$h_gio_tr = $_boc( $h_gio );
t( 'ngày không đi làm -> dấu chấm', strpos( $h_gio_tr, '<td class="o">·</td>' ) !== false, $h_gio_tr );
t( 'ngày thiếu giờ ra -> dấu hỏi nền đỏ, không phải số 0',
	strpos( $h_gio_tr, '>?</td>' ) !== false, $h_gio_tr );

/* ---- 🔴 BẤM THẲNG VÀO Ô TRONG LƯỚI ĐỂ SỬA ----
   Bắt người ta đọc ô ở dòng 14 cột 22 rồi cuộn xuống gõ lại ngày và mã vào biểu mẫu là bắt
   chép tay một thứ máy đã biết — chép sai một chữ số thì sửa nhầm ngày của người khác, mà màn
   hình vẫn báo "Đã sửa". */
t( 'ô trong lưới là đường bấm được', strpos( $h_gio, 'class="o-sua"' ) !== false, $h_gio );
/* Ô CÓ GIỜ -> khối Sửa giờ (đè lên giờ đã có). Ô TRỐNG -> khối Chấm công bù (điền ô trống).
   Trỏ nhầm đường là bấm vào ngày trống rồi nhận câu "chưa có dòng nào để sửa". */
t( 'ô CÓ GIỜ trỏ sang khối Sửa giờ, mang sẵn ngày + mã',
	preg_match( '/class="o-sua" href="[^"]*sgn=\d{4}-\d{2}-\d{2}[^"]*sgm=[^"]*#suaday"/', $h_gio ) === 1,
	$h_gio );
/* 🔴 Neo `#suaday`, KHÔNG `#bucong` — anh Thắng 29/08/2026: *"bấm sửa giờ hiện bảng đứng yên
   trang nhé, bấm vào là nó bay vị trí khác"*. `#bucong` là id của khối "Sổ nhật ký giờ công"
   (nằm mãi dưới cuối trang) từ hồi biểu mẫu Bù giờ còn tách rời — id="suaday" mới là nơi hàng
   bù thật sự mở ra ngay dưới hàng người, y hệt nhánh Sửa giờ ở trên. */
t( 'ô TRỐNG trỏ sang khối Chấm công bù, neo đúng #suaday (không phải #bucong)',
	preg_match( '/class="o-sua" href="[^"]*gnd=\d{4}-\d{2}-\d{2}[^"]*gma=[^"]*#suaday"/', $h_gio ) === 1,
	$h_gio );
t( 'và màn nói cho biết bấm vào ô thì được gì',
	strpos( $h_gio, 'Bấm thẳng vào' ) !== false, $h_gio );
/* ---- 🔴 SỬA NGAY TRONG LƯỚI, KHÔNG NHẢY ĐI ĐÂU ----
   Anh Thắng 26/08: *"mình có sửa trong khu này luôn được không, hay phải bắt buộc nhảy vào ô
   sửa"*. Bấm một ô là biểu mẫu mở ra NGAY DƯỚI dòng của đúng người đó, trong chính cái lưới. */
$h_iv = vhcc_web( '135791', array(), array( 'man' => 'cham', 'ccs' => 'TUTU_BT', 'cth' => '2026-07',
	'sgn' => '2026-07-06', 'sgm' => 'QTC1' ) );
t( 'bấm ô có giờ -> mở hàng sửa ngay trong lưới',
	strpos( $h_iv, 'class="hang-sua"' ) !== false, $h_iv );
t( 'hàng sửa nằm TRONG bảng lưới (không phải một khối rời phía dưới)',
	preg_match( '#<table class="cc".*?<tr class="hang-sua"#s', $h_iv ) === 1, $h_iv );
t( 'và mang sẵn ngày + mã, khỏi gõ lại',
	strpos( $h_iv, 'name="ngay" value="2026-07-06"' ) !== false
	&& strpos( $h_iv, 'name="ma_nv" value="QTC1"' ) !== false, $h_iv );
$khoi_iv = preg_match( '#<tr class="hang-sua"[^>]*>(.*?)</tr>#s', $h_iv, $m_iv ) ? $m_iv[1] : '';
t( 'tìm được hàng sửa trong lưới', '' !== $khoi_iv, substr( $h_iv, 0, 200 ) );
t( 'gửi đúng việc sua_gio', strpos( $khoi_iv, 'name="viec" value="sua_gio"' ) !== false, $khoi_iv );
t( 'có ô nhập giờ ngay tại đó', strpos( $khoi_iv, 'name="sg_vao"' ) !== false, $khoi_iv );
t( 'và đòi lý do', strpos( $khoi_iv, 'name="ly_do" required' ) !== false, $khoi_iv );
/* 🔴 Ô GIỜ ĐIỀN SẴN GIỜ ĐANG CÓ — anh Thắng 31/08/2026: *"chỗ nào thiếu giờ vào hoặc ra thì
   trống chỗ đó, còn có thì chèn vào luôn, sai mình sửa mà, không cần tách giờ mới giờ cũ"*.
   Bản trước để hai ô TRỐNG và thêm một dòng chữ "đang có: vào 11:43 · ra —" bên cạnh: ô nói
   một đằng, dòng chữ nói một nẻo, và muốn bỏ giờ thì phải tìm cái ô tích thứ ba. */
t( '🔴 ô giờ vào mang sẵn giờ đang có',
	1 === preg_match( '/name="sg_vao"[^>]*value="\d{2}:\d{2}"/', $khoi_iv ), $khoi_iv );
t( 'nhãn ô KHÔNG còn chữ "mới"',
	strpos( $khoi_iv, 'Giờ vào mới' ) === false, $khoi_iv );
t( 'và KHÔNG còn ô tích Xoá trắng — ô trống chính là "không có giờ"',
	strpos( $khoi_iv, 'name="sg_xoa_vao"' ) === false, $khoi_iv );
t( 'kèm ô ẩn chở giá trị cũ để biết người ta động vào đâu',
	strpos( $khoi_iv, 'name="sg_cu"' ) !== false, $khoi_iv );
/* Ô đang mở phải tìm lại được giữa 600 ô. */
t( 'ô đang sửa được tô viền', strpos( $h_iv, 'dang-sua' ) !== false, $h_iv );
/* 🔴 CHỈ MỘT HÀNG. Vẽ sẵn biểu mẫu cho cả 600 ô là 600 biểu mẫu trong một trang. */
teq( 'chỉ mở ĐÚNG MỘT hàng sửa', 1, substr_count( $h_iv, 'class="hang-sua"' ) );
t( 'và có nút Đóng để trả lưới về như cũ', strpos( $h_iv, '>Đóng</a>' ) !== false, $h_iv );

/* 🔴 BẤM DÒNG PHỤ `-CD` CŨNG PHẢI MỞ HÀNG SỬA — và mở cho ĐÚNG hàng `-CD`, không phải hàng
   chính. Từ khi hai hàng gộp làm một, vòng dò "dòng nào đang được sửa" phải xét CẢ hậu tố;
   xét mỗi hàng chính thì bấm dòng phụ ra một trang không có gì đổi, và người ta bấm lại mấy
   lượt rồi bỏ cuộc — không có lỗi nào để mà tra. */
$h_cd = vhcc_web( '135791', array(), array( 'man' => 'vp', 'ccs' => $CS_GIO, 'cth' => '2026-07',
	'sgn' => '2026-07-01', 'sgm' => 'GIO1-CD' ) );
t( 'bấm dòng phụ -CD -> hàng sửa mở ra', strpos( $h_cd, 'class="hang-sua"' ) !== false, $h_cd );
t( '🔴 và mở cho ĐÚNG hàng -CD, không phải hàng chính',
	strpos( $h_cd, 'name="ma_nv" value="GIO1-CD"' ) !== false, $h_cd );
t( 'ô của chính hàng -CD điền sẵn giờ của nó (21:00)',
	strpos( $h_cd, 'value="21:00"' ) !== false, $h_cd );
teq( 'vẫn chỉ mở ĐÚNG MỘT hàng sửa', 1, substr_count( $h_cd, 'class="hang-sua"' ) );

/* Ô TRỐNG -> biểu mẫu BÙ, không phải biểu mẫu sửa. Hai việc khác nhau. */
$h_ib = vhcc_web( '135791', array(), array( 'man' => 'cham', 'ccs' => 'TUTU_BT', 'cth' => '2026-07',
	'gnd' => '2026-07-20', 'gma' => 'QTC1' ) );
t( 'bấm ô trống -> mở hàng BÙ ngay trong lưới',
	strpos( $h_ib, 'class="hang-sua"' ) !== false, $h_ib );
/* ⚠️ Soi ĐÚNG hàng bù, không quét cả trang: khối "Chấm công bù" và khối "Sửa giờ công" ở dưới
   màn cũng có `viec=bu` / ô tích xoá trắng, và có quyền có. Quét cả trang thì bỏ hẳn nhánh phân
   biệt ô-trống / ô-có-giờ đi mà chốt vẫn xanh — đã phá thử để thấy đúng chuyện đó. */
$khoi_ib = preg_match( '#<tr class="hang-sua"[^>]*>(.*?)</tr>#s', $h_ib, $m_ib ) ? $m_ib[1] : '';
t( 'tìm được hàng bù trong lưới', '' !== $khoi_ib, substr( $h_ib, 0, 200 ) );
t( 'và gửi đúng việc bu, không phải sua_gio',
	strpos( $khoi_ib, 'name="viec" value="bu"' ) !== false, $khoi_ib );
t( 'ô bù KHÔNG có tích xoá trắng (chưa có gì để xoá)',
	strpos( $khoi_ib, 'name="sg_xoa_vao"' ) === false, $khoi_ib );

/* 🔴 NGÀY KHÁC THÁNG THÌ KHÔNG MỞ. Bấm một ô ở tháng 7, đổi sang tháng 8, mà hàng sửa vẫn mở
   giữa lưới tháng 8 với một ngày tháng 7 — rồi người ta bấm Lưu. */
/* ⚠️ Phải có dữ liệu tháng 8 cho ĐÚNG người ấy, không thì lưới tháng 8 chẳng vẽ dòng nào của
   QTC1 và chốt xanh vì một lý do khác hẳn (không có dòng thì cũng không có hàng sửa). */
vhcc_cham( 'TUTU_BT', '2026-08-03', 'QTC1', '', '08:00:00', '17:00:00' );
$h_ix = vhcc_web( '135791', array(), array( 'man' => 'cham', 'ccs' => 'TUTU_BT', 'cth' => '2026-08',
	'sgn' => '2026-07-06', 'sgm' => 'QTC1' ) );
t( 'lưới tháng 8 có vẽ dòng của QTC1', strpos( $h_ix, 'Người QTC1' ) !== false, $h_ix );
t( '🔴 ngày lạc tháng thì KHÔNG mở hàng sửa trong lưới',
	strpos( $h_ix, 'class="hang-sua"' ) === false, $h_ix );

/* Cửa hàng trưởng bấm ô CÓ GIỜ: hàng vẫn mở, nhưng nói rõ cần quyền Admin — chứ không im lặng
   bày ra một biểu mẫu bấm Lưu là bị chối. */
VHCC_NguoiDung::luu( '', 'CHT Lưới', '357913', 'Cửa hàng trưởng', 'TUTU_BT' );
$h_ic = vhcc_web( '357913', array(), array( 'man' => 'cham', 'ccs' => 'TUTU_BT', 'cth' => '2026-07',
	'sgn' => '2026-07-06', 'sgm' => 'QTC1' ) );
/* 🔴 NAY BÀY RA Ô NHẬP THẬT. Anh Thắng 28/08/2026 mở `sua_gio` cho Cửa hàng trưởng, nên bấm
   vào ô có giờ phải mở đúng biểu mẫu sửa — chứ không phải một câu chối. */
t( '🔴 cửa hàng trưởng bấm ô có giờ thì mở được ô nhập',
	strpos( $h_ic, 'name="sg_vao"' ) !== false, $h_ic );
t( 'và không còn câu chối cần quyền Admin',
	strpos( $h_ic, 'cần quyền Admin' ) === false, $h_ic );
/* ⚠️ Ô VÌ SAO vẫn bắt buộc — bậc hạ xuống thì cái duy nhất còn tra ngược được là lý do người
   ta gõ vào. Mất nó là bảng công sửa được mà không ai biết vì sao. */
t( '🔴 và vẫn bắt ghi VÌ SAO', strpos( $h_ic, 'name="ly_do"' ) !== false, $h_ic );

/* Hàng -CD là hàng RIÊNG: đường bấm phải mang mã KÈM hậu tố, không thì sửa nhầm sang hàng chính. */
t( '🔴 ô của hàng -CD mang mã KÈM hậu tố',
	preg_match( '/sgm=[A-Za-z0-9_]+-CD/', $h_gio ) === 1
	|| preg_match( '/gma=[A-Za-z0-9_]+-CD/', $h_gio ) === 1, $h_gio );
/* Đường bấm là LIÊN KẾT, không phải script — cả màn này không có lấy một dòng script. */
t( 'ô bấm được KHÔNG dùng JavaScript',
	stripos( $h_gio, '<script' ) === false && ! preg_match( '/\son[a-z]+\s*=\s*"/i', $h_gio ), $h_gio );
t( 'và chú thích nói rõ là quên bấm lúc về',
	strpos( $h_gio, 'quên bấm lúc về' ) !== false, $h_gio );
/* 🔴 HÀNG -CD NAY LÀ DÒNG PHỤ TRONG Ô, cùng luật với lưới CÔNG.
   Anh Thắng 27/08/2026, ngay sau khi chốt kiểu gộp: *"với cơ sở khác ... cũng nhớ ghép lại
   giúp anh"* — "cơ sở khác" là cơ sở tính THEO GIỜ, tức chính lưới này. */
t( '🔴 hàng -CD là dòng phụ ngay trong ô, không phải hàng riêng',
	preg_match( '~<div class="mdem[^"]*"[^>]*>(<a[^>]*>)?<code>-CD</code>~', $h_gio ) === 1, $h_gio );
t( 'và không còn hàng ↳ riêng nào', strpos( $h_gio, '↳ <code>' ) === false, $h_gio );
/* Con số của riêng hàng phụ trước đây nằm ở ô TỔNG của hàng riêng — bỏ hàng ấy thì phải kể
   lại ở đây, kẻo mất hẳn "hàng -CD của người này cả tháng mấy tiếng". */
t( 'ô TỔNG kể ra hậu tố nào mấy tiếng', strpos( $h_gio, '>-CD 2h</div>' ) !== false, $h_gio );
/* 9.5h (hàng chính) + 2h (hàng -CD) = 11h 30m. Lấy CÙNG phép tính với màn Bảng chấm công.
   ⚠️ Soi Ô TỔNG, không soi chuỗi '11h 30m' trần: bảng "Tổng giờ theo ca" ngay dưới lưới cũng
      in đúng con số ấy, nên đo chuỗi trần thì ô TỔNG có ra 0 phép thử vẫn xanh. Đã phá thử để
      thấy đúng chuyện đó. */
/* ⚠️ Và soi ô TỔNG CỦA LƯỚI, không phải ô TỔNG bất kỳ: bảng "Tổng giờ làm theo nhân viên" ngay
   trên lưới cũng có cột TỔNG, cũng ra 11h 30m cho đúng người ấy, cũng dùng `<td class="tong">`.
   Nên phải bám vào thứ CHỈ lưới mới có — dòng kể hậu tố ngay dưới con số. Bản trước của phép
   thử này chỉ soi `<td class="tong"><b>11h 30m</b>` và nó xanh cả khi ô TỔNG của lưới ra 0h. */
t( '🔴 ô TỔNG của LƯỚI cộng cả hai hàng (9.5h + 2h = 11h 30m)',
	strpos( $h_gio, '<b>11h 30m</b><div class="mo" style="font-size:10px">-CD 2h</div>' ) !== false,
	$h_gio );
/* 🔴 BA KÝ HIỆU CHO BA CHUYỆN. Gộp `?` với `—` là xoá mất phân biệt "quên bấm lúc về" (chuyện
   thường, bù là xong) với "giờ ra sớm hơn giờ vào" (dữ liệu ghi sai, phải tra lại nguồn).
   GIO1 ngày 02/07 thiếu giờ ra -> `?`; ô ghi sai -> `—`. */
t( 'ngày thiếu giờ ra hiện dấu hỏi', preg_match( '~>\?</a></td>~', $h_gio ) === 1, $h_gio );
/* Tháng riêng cho cảnh này: nhét một lượt ghi sai vào tháng 7 là mọi phép đếm giờ / tổng theo
   ca ở trên lệch theo, và lúc ấy phép thử đỏ vì cảnh dựng chứ không phải vì mã. */
vhcc_cham( $CS_GIO, '2026-09-02', 'GIO1', '', '17:00:00', '08:00:00' );   /* ra SỚM hơn vào */
$h_sai = vhcc_web( '135791', array(), array( 'man' => 'vp', 'ccs' => $CS_GIO, 'cth' => '2026-09' ) );
t( '🔴 ngày giờ ra SỚM HƠN giờ vào hiện dấu gạch, không phải dấu hỏi',
	preg_match( '~>—</a></td>~', $h_sai ) === 1, $h_sai );
t( 'và chú thích nói đúng chuyện ghi sai, không đổ cho quên bấm',
	strpos( $h_sai, 'giờ ra sớm hơn giờ vào' ) !== false, $h_sai );
/* Nói thẳng chuyện giờ làm khác giờ được trả tiền, đừng để lộ ra lúc đối lương. */
t( 'nói rõ đây là giờ LÀM, không phải giờ được trả tiền',
	strpos( $h_gio, 'không phải giờ được trả tiền' ) !== false, $h_gio );

/* ---- TÁCH CA: làm ca nào · ca đó mấy tiếng · từ ca nào đến ca nào ---- */
/* Anh Thắng 26/08: *"bổ sung phần tách ca, để biết bạn đó làm ca nào, ca đó mấy tiếng, từ ca nào
   đến ca nào"*. Lõi tách ca thử riêng ở kiem-ca.php (47 phép); ở đây canh phần MÀN HÌNH. */
t( 'lưới giờ có bảng Tổng giờ theo ca', strpos( $h_gio, 'Tổng giờ theo ca' ) !== false, $h_gio );
t( 'nói rõ đang dùng khung ca nào', strpos( $h_gio, 'Khung ca đang dùng' ) !== false, $h_gio );
t( 'và chưa ai khai thì nói là đang dùng MẶC ĐỊNH',
	strpos( $h_gio, '<b>mặc định</b>' ) !== false, $h_gio );
foreach ( array( 'C1' => 'Ca 1', 'C2' => 'Ca 2', 'C3' => 'Ca 3' ) as $ma_tc => $tc ) {
	t( 'bảng theo ca có cột "' . $tc . '" kèm mã ngắn ' . $ma_tc,
		strpos( $h_gio, '<b>' . $ma_tc . '</b> ' . $tc ) !== false, $h_gio );
}
t( 'và có cột Ngoài ca', strpos( $h_gio, '<th>Ngoài ca</th>' ) !== false, $h_gio );
/* GIO1 ngày 01/07 có HAI hàng: hàng chính 08:00–17:30 và hàng -CD 21:00–23:00.
     Ca 1 (06–14) = 6h        (08:00→14:00 của hàng chính)
     Ca 2 (14–22) = 4h 30m    (14:00→17:30 hàng chính  +  21:00→22:00 hàng -CD)
     Ca 3 (22–06) = 1h        (22:00→23:00 hàng -CD)
   ⚠️ Em gõ 3h 30m cho Ca 2 vì chỉ nhẩm hàng chính — quên rằng hàng -CD cũng chạm Ca 2. Con số
      dưới đây lấy từ phép tính thật, và tổng 11h 30m khớp với cột TỔNG của lưới ở trên. */
t( 'tách đúng giờ vào Ca 1', strpos( $h_gio, '>6h</b>' ) !== false, $h_gio );
t( 'Ca 2 gom cả hàng chính lẫn phần hàng -CD chạm vào nó',
	strpos( $h_gio, '>4h 30m</b>' ) !== false, $h_gio );
t( 'tổng theo ca khớp tổng giờ làm của lưới (11h 30m)',
	substr_count( $h_gio, '11h 30m' ) >= 2, $h_gio );
/* 🔴 MÃ CA IN THẲNG VÀO Ô. Anh Thắng 26/08: *"hiện sẵn bạn ca nào ca nào luôn nhé, đi rà này
   rất khó"* — một tháng của 21 người là hơn 600 ô, rê chuột từng ô thì không ai rà nổi. */
t( 'ô lưới in sẵn mã ca, không bắt rê chuột mới biết',
	strpos( $h_gio, '<div class="mca">' ) !== false, $h_gio );
t( 'ngày vắt hai ca thì ô hiện cả hai mã',
	strpos( $h_gio, '>C1·C2</div>' ) !== false, $h_gio );
t( 'ngày nằm gọn một ca thì ô chỉ hiện MỘT mã',
	strpos( $h_gio, '>C1</div>' ) !== false, $h_gio );
/* Nền tô theo ca ĂN NHIỀU GIỜ NHẤT — để lướt mắt là thấy cả tháng ai chạy ca nào. */
t( 'ô được tô màu theo ca chính', preg_match( '/class="oc ca[1-4]"/', $h_gio ) === 1, $h_gio );
/* 🔴 Tô theo ca ĂN NHIỀU GIỜ NHẤT, không phải ca ĐẦU TIÊN chạm vào. Lượt 21:30 → 05:30 chạm
   Ca 2 đúng 30 phút rồi nằm trong Ca 3 suốt 7h 30m — tô theo ca đầu là cả tháng ca đêm hiện màu
   ca chiều, và người rà bảng đọc ngược hoàn toàn. */
/* ⚠️ Ca đêm nay nằm ở DÒNG PHỤ trong ô, nên màu và chú thích của nó ở trên thẻ <div> ấy chứ
   không còn trên <td>. Gộp mà bỏ mất hai thứ này là ca đêm mất màu — mà màu theo ca chính là
   thứ để lướt mắt nhận ra ai chạy ca nào, và ca đêm là ca cần nhận ra nhất. */
t( 'ca đêm được tô theo Ca 3 (7h 30m), không theo Ca 2 (30 phút chạm đầu)',
	preg_match( '/class="mdem ca3" title="[^"]*Ca 3 7h 30m/', $h_gio ) === 1, $h_gio );
t( 'và dòng phụ giữ nguyên chú thích giờ vào → giờ ra của riêng nó',
	preg_match( '/class="mdem ca3" title="[^"]*21:30:00 → 05:30:00/', $h_gio ) === 1, $h_gio );
/* Mã trong ô là C1/C2/C3 theo VỊ TRÍ, nên bắt buộc phải có bảng quy đổi ngay dưới lưới. */
t( 'có bảng quy đổi mã ca ngay dưới lưới',
	strpos( $h_gio, 'Mã ca trong ô' ) !== false, $h_gio );
t( 'bảng quy đổi nói C1 là ca nào, khung giờ nào',
	strpos( $h_gio, '<b>C1</b> Ca 1 06:00–14:00' ) !== false, $h_gio );
t( 'và giải thích ô hai mã nghĩa là gì',
	strpos( $h_gio, 'vắt qua hai ca' ) !== false, $h_gio );

/* Chú thích ô nói luôn ngày đó chạy từ ca nào đến ca nào. */
t( 'chú thích ô nói từ ca nào đến ca nào', strpos( $h_gio, 'Ca 1 → Ca 2' ) !== false, $h_gio );
t( 'và nói mỗi ca mấy tiếng kèm khung giờ',
	strpos( $h_gio, 'Ca 1 6h (06:00–14:00)' ) !== false, $h_gio );

/* 🔴 Hàng ca đêm: 21:00–23:00 phải rơi vào Ca 3 (22:00–06:00, qua nửa đêm), không được biến
   mất. Ca qua nửa đêm là chỗ mà phép so ngây thơ `tu <= x && x < den` luôn trượt. */
t( 'hàng ca đêm vẫn được tách vào Ca 3', strpos( $h_gio, '>1h</b>' ) !== false, $h_gio );
/* 🔴 GIO2 làm 21:30 → 05:30 HÔM SAU = 8 tiếng, trong đó Ca 3 (22:00–06:00) ăn trọn 7h 30m và
   Ca 2 (14:00–22:00) ăn 30 phút đầu. Đọc từ chuỗi giờ đã gói về trong ngày thì ra ~0 và cả ca
   đêm này biến mất mà tổng vẫn có số — đúng kiểu hỏng không kêu tiếng nào. */
t( 'ca đêm qua hôm sau tách đúng 7h 30m vào Ca 3',
	strpos( $h_gio, '>7h 30m</b>' ) !== false, $h_gio );
t( 'và 30 phút đầu rơi vào Ca 2', strpos( $h_gio, '>0h 30m</b>' ) !== false, $h_gio );

/* Khối khai ca — Cửa hàng trưởng trở lên.
   ⚠️ Khối này nay ở TAB CẤU HÌNH, không còn trên màn bảng công — nên soi màn cấu hình. */
$h_ch_gio = vhcc_web( '135791', array(),
	array( 'man' => 'cau_hinh', 'ccs' => $CS_GIO, 'cth' => '2026-07' ) );
/* Khối khai ca — Cửa hàng trưởng trở lên. */
t( 'có khối Khai ca làm việc', strpos( $h_ch_gio, 'id="khaica"' ) !== false, $h_ch_gio );
/* 🔴 CHƯA KHAI RIÊNG THÌ PHẢI MỞ SẴN. Anh Thắng 28/08/2026 gửi ảnh bảng Tổng giờ theo ca:
   *"Anh thấy ca làm nó có nè, nhưng nó đang lấy chung từ cửa hàng khác nên bị sai"*. Cửa hàng
   ấy đang mượn khung mặc định, và khối để sửa thì gập kín. Gập kín một việc CHƯA LÀM là cách
   chắc chắn nhất để nó không bao giờ được làm. Khai rồi mới thu gọn — thử cả hai chiều ở dưới. */
t( 'chưa khai riêng thì khối khai ca MỞ SẴN',
	preg_match( '/id="khaica"><details open>/', $h_ch_gio ) === 1, $h_ch_gio );
t( 'và tiêu đề khối nói rõ đang khai cho cơ sở nào',
	strpos( $h_ch_gio, 'Khai ca làm việc của ' . $CS_GIO ) !== false, $h_ch_gio );
t( 'có ô nhập tên ca', strpos( $h_ch_gio, 'name="ca_ten[0]"' ) !== false, $h_ch_gio );
t( 'và ô giờ cuối tuần riêng', strpos( $h_ch_gio, 'name="ca_tuw[0]"' ) !== false, $h_ch_gio );
/* Luôn thừa hai dòng trống để thêm ca mà KHÔNG cần JavaScript — cả màn này không có script. */
t( 'thừa sẵn dòng trống để thêm ca', strpos( $h_ch_gio, 'name="ca_ten[4]"' ) !== false, $h_ch_gio );
t( 'khối khai ca KHÔNG dùng JavaScript', stripos( $h_ch_gio, '<script' ) === false, $h_ch_gio );

/* Lưu ca THẬT rồi xem bảng đổi theo. */
$_POST = array( 'viec' => 'ca', 'ccs' => $CS_GIO,
	'ca_ten'  => array( 'Sáng', 'Chiều' ),
	'ca_tu'   => array( '06:00', '12:00' ),
	'ca_den'  => array( '12:00', '20:00' ),
	'ca_tuw'  => array( '', '' ), 'ca_denw' => array( '', '' ) );
$r_ca = vhcc_goi_rieng( 'VHCC_Web', 'lam_viec', array( 'ca', $ADMIN_W ) );
$_POST = array();
t( 'lưu được ca mới', is_array( $r_ca ) && isset( $r_ca[0]['xong'] ), $r_ca );
$h_ca2 = vhcc_web( '135791', array(), array( 'man' => 'vp', 'ccs' => $CS_GIO, 'cth' => '2026-07' ) );
t( 'bảng đổi theo ca vừa khai', strpos( $h_ca2, '<b>C1</b> Sáng' ) !== false, $h_ca2 );
t( 'và nói là cơ sở này đã có khung ca RIÊNG',
	strpos( $h_ca2, 'khai riêng cho' ) !== false, $h_ca2 );
t( 'ca cũ không còn trong bảng', strpos( $h_ca2, '<b>C1</b> Ca 1' ) === false, $h_ca2 );
/* 08:00–17:30 với ca Sáng 06–12 và Chiều 12–20 -> 4h + 5h 30m. */
t( 'tách lại đúng theo khung ca mới', strpos( $h_ca2, '>4h</b>' ) !== false
	&& strpos( $h_ca2, '>5h 30m</b>' ) !== false, $h_ca2 );
/* 🔴 Hàng ca đêm 21:00–23:00 nay nằm NGOÀI mọi ca -> phải hiện ở cột Ngoài ca, không được nuốt. */
t( 'giờ không thuộc ca nào hiện ở cột Ngoài ca, không bị nuốt',
	strpos( $h_ca2, 'oc vang' ) !== false, $h_ca2 );
t( 'và nói rõ đó là dấu hiệu khung ca khai chưa khớp',
	strpos( $h_ca2, 'khung ca khai chưa khớp' ) !== false, $h_ca2 );

/* ==================================================================================
   KHAI CA NGAY TRÊN MÀN BẢNG CÔNG — việc của CỬA HÀNG TRƯỞNG

   Anh Thắng 28/08/2026 gửi ảnh bảng Tổng giờ theo ca của một cửa hàng, chú "Khung ca đang
   dùng: mặc định (chưa ai khai)": *"Anh thấy ca làm nó có nè, nhưng nó đang lấy chung từ cửa
   hàng khác nên bị sai"*.

   🔴 GỐC RỄ KHÔNG PHẢI Ở BẢNG, MÀ Ở CHỖ KHAI. Khối "Khai ca làm việc" vốn chỉ có ở màn Cấu
      hình, mà màn ấy gác `ngoai_coso` (bậc Quản lý). Cửa hàng trưởng — đúng người biết cửa
      hàng mình vào ca mấy giờ — KHÔNG có cửa nào để khai, nên mọi cửa hàng cứ chạy bằng khung
      mặc định và bảng nào cũng ra số sai một cách im lặng. Anh Thắng 27/08 đã giao thẳng:
      *"Cho qua bên Tài khoản cửa hàng trưởng tự set giờ ca vào ra của cửa hàng"*.

   Thêm CHỖ VẼ, không nới quyền: chốt bên trong khối vẫn là `lich_lam` + `co_quyen_coso`.
   ================================================================================== */
$cs_ca_cht = 'FZ_SC_CATEST';
$_COOKIE = array();
$h_cham_cht = vhcc_web_nhu2( 'CHTCA1', 'CUA_HANG_TRUONG', $cs_ca_cht,
	array( 'man' => 'cham', 'ccs' => $cs_ca_cht, 'cth' => '2026-07' ) );
t( 'Cửa hàng trưởng khai ca được NGAY trên màn Bảng công',
	strpos( $h_cham_cht, 'id="khaica"' ) !== false, $h_cham_cht );
t( 'và khối ấy mở sẵn vì cửa hàng chưa khai riêng',
	preg_match( '/id="khaica"><details open>/', $h_cham_cht ) === 1, $h_cham_cht );
t( 'có ô nhập giờ vào ca ngay tại đó',
	strpos( $h_cham_cht, 'name="ca_tu[0]"' ) !== false, $h_cham_cht );
/* Bảng vẫn ra số đẹp nên nhìn qua tưởng đúng — phải có khối VÀNG nói thẳng là đang mượn khung. */
t( 'bảng Tổng giờ theo ca kêu lên rằng cửa hàng chưa có khung ca riêng',
	strpos( $h_cham_cht, 'chưa có khung ca riêng' ) !== false, $h_cham_cht );
t( 'và nói rõ hậu quả: số ở đây sai',
	strpos( $h_cham_cht, 'số ở đây sai' ) !== false, $h_cham_cht );
t( 'cảnh báo ấy là khối vàng, không phải chữ xám',
	preg_match( '/class="bao canh"[^>]*><b>' . preg_quote( $cs_ca_cht, '/' ) . ' chưa có/', $h_cham_cht ) === 1,
	$h_cham_cht );
t( 'và chỉ đường xuống thẳng khối khai ca',
	strpos( $h_cham_cht, 'href="#khaica"' ) !== false, $h_cham_cht );

/* 🔴 THÊM CHỖ VẼ THÌ THÊM CỬA — HAI CHỐT PHẢI ĐỨNG NGAY TẠI KHỐI, VÀ PHẢI SOI THẲNG VÀO KHỐI.
   Soi qua cả trang thì KHÔNG phân biệt được: mã cơ sở lạ bị `ds_coso_xem` lọc mất từ tầng
   trên, nên trang chẳng vẽ tới đây, và bỏ chốt đi phép thử vẫn xanh — đúng kiểu mã tương
   đương. Gọi thẳng `the_khai_ca` là cách duy nhất hỏi được chính nó: *mày có tự giữ cửa
   không, hay đang sống nhờ hàng rào của người khác?* Hàng rào tầng trên có ngày bị dời. */
$cht_ca = array( 'name' => 'CHT ca', 'role' => 'CUA_HANG_TRUONG', 'coso' => $cs_ca_cht );
$nv_ca  = array( 'name' => 'NV ca',  'role' => 'NHAN_VIEN',       'coso' => $cs_ca_cht );

ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_khai_ca', array( $cs_ca_cht, '2026-07', $cht_ca ) );
$k_minh = ob_get_clean();
t( 'gọi thẳng: Cửa hàng trưởng khai được ca cửa hàng MÌNH',
	strpos( $k_minh, 'id="khaica"' ) !== false, $k_minh );

ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_khai_ca', array( $CS_GIO, '2026-07', $cht_ca ) );
$k_lac = ob_get_clean();
t( 'gọi thẳng: Cửa hàng trưởng KHÔNG bày được khung ca của cửa hàng KHÁC',
	'' === trim( $k_lac ), $k_lac );

ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_khai_ca', array( '', '2026-07', $cht_ca ) );
t( 'gọi thẳng: cơ sở rỗng thì không vẽ gì', '' === trim( ob_get_clean() ) );

ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_khai_ca', array( $cs_ca_cht, '2026-07', $nv_ca ) );
$k_nv = ob_get_clean();
t( 'gọi thẳng: nhân viên thường không khai ca được, dù đúng cửa hàng mình',
	'' === trim( $k_nv ), $k_nv );

/* 🔴 HAI CHỐT CÙNG CHẶN MỘT CA THÌ KHÔNG PHÉP THỬ NÀO PHÂN BIỆT ĐƯỢC.
   `lich_lam` và `cong_coso` (cửa của `co_quyen_coso`) cùng đứng ở bậc Cửa hàng trưởng, nên
   nhân viên bị chặn hai lần và bỏ đi một chốt vẫn không lộ ra — phá thử gọi đó là mã tương
   đương, và mã tương đương là chỗ chốt chết âm thầm về sau. Dựng đúng một người ở giữa: MỞ
   `cong_coso` cho họ (qua được cửa cơ sở) nhưng KHOÁ `lich_lam`. Ai lọt tới ô khai ca lúc này
   là do chốt `lich_lam` đã mất. */
$ma_giua = 'CAGIUA1';
VHCC_Vai::dat_ngoai_le( $ADMIN_W, 'nv:' . $ma_giua, 'cong_coso', 'mo' );
VHCC_Vai::dat_ngoai_le( $ADMIN_W, 'nv:' . $ma_giua, 'lich_lam', 'khoa' );
$u_giua = array( 'name' => 'Người giữa', 'role' => 'NHAN_VIEN',
	'coso' => $cs_ca_cht, 'ma_nv' => $ma_giua );
t( 'người giữa QUA được cửa cơ sở', VHCC_NhanSu::co_quyen_coso( $u_giua, $cs_ca_cht ), $u_giua );
t( 'nhưng KHÔNG có quyền khai ca', ! VHCC_Vai::duoc( $u_giua, 'lich_lam' ), $u_giua );
ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_khai_ca', array( $cs_ca_cht, '2026-07', $u_giua ) );
$k_giua = ob_get_clean();
t( 'nên khối khai ca vẫn không vẽ cho người ấy', '' === trim( $k_giua ), $k_giua );
VHCC_Vai::dat_ngoai_le( $ADMIN_W, 'nv:' . $ma_giua, 'cong_coso', '' );
VHCC_Vai::dat_ngoai_le( $ADMIN_W, 'nv:' . $ma_giua, 'lich_lam', '' );

/* Và trên trang thật cũng vậy — nhân viên thấy bảng, không thấy ô khai. */
$h_cham_nv = vhcc_web_nhu2( 'NVCA1', 'NHAN_VIEN', $cs_ca_cht,
	array( 'man' => 'cham', 'ccs' => $cs_ca_cht, 'cth' => '2026-07' ) );
t( 'nhân viên thường không thấy khối khai ca',
	strpos( $h_cham_nv, 'id="khaica"' ) === false, $h_cham_nv );

/* Khai xong thì khối thu gọn lại — màn Bảng công vốn đã dài. */
$r_ca_cht = VHCC_Ca::luu( array( 'name' => 'CHT ca', 'role' => 'CUA_HANG_TRUONG', 'coso' => $cs_ca_cht ),
	$cs_ca_cht, array( array( 'ten' => 'Ca sáng', 'tu' => '08:00', 'den' => '16:00', 'tuW' => '', 'denW' => '' ) ) );
t( 'Cửa hàng trưởng LƯU được ca của chính cửa hàng mình', ! empty( $r_ca_cht['ok'] ), $r_ca_cht );
$h_cham_cht2 = vhcc_web_nhu2( 'CHTCA1', 'CUA_HANG_TRUONG', $cs_ca_cht,
	array( 'man' => 'cham', 'ccs' => $cs_ca_cht, 'cth' => '2026-07' ) );
t( 'khai rồi thì khối khai ca thu gọn lại',
	preg_match( '/id="khaica"><details>/', $h_cham_cht2 ) === 1, $h_cham_cht2 );
t( 'và khối vàng "chưa có khung ca riêng" biến mất',
	strpos( $h_cham_cht2, 'chưa có khung ca riêng' ) === false, $h_cham_cht2 );

/* ---- CÔNG TẮC: cơ sở nào tính THEO GIỜ, cơ sở nào THEO CÔNG ---- */
/* Anh Thắng 26/08: *"bổ sung phần cấu hình để phân biệt cơ sở nào tính theo giờ, cơ sở nào tính
   theo công"*.

   🔴 Trước đây chuyện này SUY RA TỪ BỘ PHẬN, và đó là chỗ sai: nó buộc hai câu hỏi khác nhau vào
      một ô dữ liệu — "cơ sở thuộc bộ phận nào" (để lọc, gom báo cáo) và "cơ sở trả công thế nào"
      (để ra tiền). Đổi bộ phận cho gọn báo cáo là lặng lẽ đổi cách tính tiền của cả một cơ sở. */

/* Chưa khai gì -> vẫn theo luật cũ, để cơ sở đang chạy không đổi kết quả sau khi cài bản mới. */
t( 'chưa khai thì suy theo bộ phận', ! VHCC_Luong::cach_tinh_da_khai( $CS_GIO ) );
teq( 'cơ sở không phải Văn phòng -> theo giờ', 'gio', VHCC_Luong::cach_tinh( $CS_GIO ) );
teq( 'cơ sở Văn phòng -> theo công', 'cong', VHCC_Luong::cach_tinh( $VP_CS ) );

/* Khai thẳng thì công tắc thắng bộ phận — cả hai chiều. */
$r_ct = VHCC_Luong::dat_cach_tinh( $ADMIN_W, array( $CS_GIO => 'cong', $VP_CS => 'gio' ) );
t( 'lưu được cách tính', ! empty( $r_ct['ok'] ), $r_ct );
teq( 'khai thẳng THEO CÔNG thắng bộ phận', 'cong', VHCC_Luong::cach_tinh( $CS_GIO ) );
teq( 'và khai thẳng THEO GIỜ cũng thắng bộ phận Văn phòng', 'gio', VHCC_Luong::cach_tinh( $VP_CS ) );
t( 'đánh dấu là đã khai thẳng', VHCC_Luong::cach_tinh_da_khai( $CS_GIO ) );
/* Màn đọc theo công tắc, không đọc bộ phận nữa. */
$h_ct = vhcc_web( '135791', array(), array( 'man' => 'cau_hinh', 'ccs' => $CS_GIO, 'cth' => '2026-07' ) );
/* ⚠️ Câu "mỗi ô là số công" nằm ở LƯỚI CẢ THÁNG, tức màn Bảng công — không phải màn Cấu
   hình. Soi nhầm màn thì phép thử đỏ vì lý do chẳng liên quan gì tới cái công tắc. */
$h_ct_bc = vhcc_web( '135791', array(), array( 'man' => 'cham', 'ccs' => $CS_GIO, 'cth' => '2026-07' ) );
t( 'bảng đổi sang SỐ CÔNG theo công tắc', strpos( $h_ct_bc, 'là <b>số công</b>' ) !== false, $h_ct_bc );
t( 'và nói rõ là do khai thẳng', strpos( $h_ct_bc, 'đã khai thẳng' ) !== false, $h_ct_bc );

/* Để rỗng = BỎ khai, quay về suy theo bộ phận — KHÔNG phải "cơ sở này không có cách tính nào". */
VHCC_Luong::dat_cach_tinh( $ADMIN_W, array( $CS_GIO => '', $VP_CS => '' ) );
t( 'để rỗng là bỏ khai', ! VHCC_Luong::cach_tinh_da_khai( $CS_GIO ) );
/* Và XOÁ HẲN khoá, không để lại một ô rỗng. Giữ lại thì sổ cấu hình cứ phình ra theo mỗi lượt
   bấm Lưu, đầy những cơ sở "đã khai là không khai gì" — đọc lại chẳng ai hiểu. */
$bd_ct = VHCC_Luong::ban_do_cach_tinh();
t( 'và xoá hẳn khoá khỏi sổ cấu hình, không để lại ô rỗng',
	! array_key_exists( $CS_GIO, $bd_ct ) && ! array_key_exists( $VP_CS, $bd_ct ), $bd_ct );
teq( 'và quay về suy theo bộ phận', 'gio', VHCC_Luong::cach_tinh( $CS_GIO ) );
teq( 'Văn phòng cũng quay về theo công', 'cong', VHCC_Luong::cach_tinh( $VP_CS ) );

/* Khối cấu hình trên màn. */
t( 'có khối Cách tính công của từng cơ sở', strpos( $h_ch_gio, 'id="cachtinh"' ) !== false, $h_ch_gio );
t( 'khối ấy liệt kê CẢ danh sách cơ sở, không chỉ cơ sở đang xem',
	substr_count( $h_ch_gio, 'name="ct[' ) > 1, $h_ch_gio );
t( 'mỗi cơ sở có ba lựa chọn', strpos( $h_ch_gio, '— theo bộ phận —' ) !== false
	&& strpos( $h_ch_gio, '>Theo giờ<' ) !== false && strpos( $h_ch_gio, '>Theo công<' ) !== false, $h_ch_gio );
t( 'có cột Đang dùng cho biết luật hiện ra kết quả gì',
	strpos( $h_ch_gio, '<th>Đang dùng</th>' ) !== false, $h_ch_gio );
/* Nói rõ đổi công tắc KHÔNG sửa giờ chấm — kẻo người ta sợ không dám bấm. */
t( 'nói rõ đổi cách tính không sửa giờ chấm nào',
	strpos( $h_ch_gio, 'không sửa một giờ chấm nào' ) !== false, $h_ch_gio );
/* Và trỏ sang công thức tính công của khối Văn phòng — đó là màn khác, nhiều ô hơn hẳn. */
t( 'trỏ sang công thức tính công của khối Văn phòng',
	strpos( $h_ch_gio, 'công thức tính công của khối Văn phòng' ) !== false
	|| strpos( $h_ch_gio, 'công thức '  ) !== false, $h_ch_gio );

/* Gác cửa: đổi cách tính là đổi con số ra tiền, không phải việc trong phạm vi một cửa hàng. */
foreach ( array( 'Nhân viên', 'Cửa hàng trưởng' ) as $vt_ct ) {
	$r_c = VHCC_Luong::dat_cach_tinh(
		array( 'name' => 'X', 'role' => $vt_ct, 'coso' => $CS_GIO ), array( $CS_GIO => 'cong' ) );
	t( $vt_ct . ' KHÔNG đổi được cách tính', empty( $r_c['ok'] ), $r_c );
}
$h_ct_ch = vhcc_web( '357913', array(), array( 'man' => 'cau_hinh', 'ccs' => 'TUTU_BT', 'cth' => '2026-07' ) );
t( 'Cửa hàng trưởng không thấy khối cấu hình', strpos( $h_ct_ch, 'id="cachtinh"' ) === false, $h_ct_ch );
/* Ẩn khối không phải là gác cửa — POST thẳng cũng phải bị chối. */
$_POST = array( 'viec' => 'cach_tinh', 'ct' => array( $CS_GIO => 'cong' ) );
$r_ct_p = vhcc_goi_rieng( 'VHCC_Web', 'lam_viec',
	array( 'cach_tinh', array( 'name' => 'CHT', 'role' => 'Cửa hàng trưởng', 'coso' => $CS_GIO ) ) );
$_POST = array();
t( 'và POST thẳng cũng bị chối', is_array( $r_ct_p ) && ! isset( $r_ct_p[0]['xong'] ), $r_ct_p );
teq( 'cách tính KHÔNG bị đổi', 'gio', VHCC_Luong::cach_tinh( $CS_GIO ) );

/* ---- XUẤT EXCEL: chi tiết ca đó từ mấy giờ đến mấy giờ ---- */
/* Anh Thắng 26/08: *"bổ sung tính năng xuất excel, khi xuất thì nó sẽ chi tiết ca đó từ mấy h
   đến mấy h"*. */
t( 'màn có nút Xuất Excel', strpos( $h_gio, 'Xuất Excel' ) !== false, $h_gio );
t( 'nút mang sẵn cơ sở và tháng đang xem',
	strpos( $h_gio, 'xuat=ca' ) !== false && strpos( $h_gio, 'cth=2026-07' ) !== false, $h_gio );

$b_xuat = VHCC_Cham::bang_cham_cong( $ADMIN_W, $CS_GIO, '2026-07' );
$to_x   = VHCC_Ca::to_xuat( $b_xuat, $CS_GIO );
teq( 'xuất ra ĐÚNG ba trang tính', 3, count( $to_x ) );
teq( 'trang đầu là Chi tiết ca', 'Chi tiết ca', $to_x[0]['ten'] );
teq( 'trang hai là Tổng theo ca', 'Tổng theo ca', $to_x[1]['ten'] );
teq( 'trang ba là Từng lượt chấm', 'Từng lượt chấm', $to_x[2]['ten'] );

/* 🔴 Trang Chi tiết ca: MỖI CA MỘT DÒNG, không phải mỗi ngày một dòng. Gộp lại là mất đúng thứ
   anh Thắng cần — giờ nào thuộc ca nào. */
$dau_x = $to_x[0]['hang'][0];
foreach ( array( 'Ca', 'Ca bắt đầu', 'Ca kết thúc', 'Giờ trong ca' ) as $c_x ) {
	t( 'trang Chi tiết ca có cột "' . $c_x . '"', in_array( $c_x, $dau_x, true ), $dau_x );
}
/* GIO1 ngày 01/07 làm 08:00–17:30, vắt Ca 1 và Ca 2 -> phải ra HAI dòng cho một ngày. */
$dong_gio1 = array();
foreach ( array_slice( $to_x[0]['hang'], 1 ) as $d_x ) {
	if ( '2026-07-01' === $d_x[0] && 'chính' === $d_x[4] ) { $dong_gio1[] = $d_x; }
}
teq( 'một ngày vắt hai ca thì ra HAI dòng', 2, count( $dong_gio1 ) );
/* ⚠️ Ca ở đây là ca ĐANG KHAI cho cơ sở này ("Sáng" 06–12 · "Chiều" 12–20, khai ở mục trên),
   KHÔNG phải bộ mặc định Ca 1/Ca 2. Lượt 08:00–17:30 -> Sáng 4h, Chiều 5h30. Em gõ Ca 1/Ca 2
   theo trí nhớ và trượt — con số dưới đây lấy từ chính phép tính. */
$ca_cua = array();
foreach ( $dong_gio1 as $d_x ) { $ca_cua[ $d_x[8] ] = array( $d_x[9], $d_x[10], $d_x[11] ); }
teq( 'dòng ca đầu ghi rõ khung ca và số giờ trong ca',
	array( '06:00', '12:00', 4.0 ), isset( $ca_cua['Sáng'] ) ? $ca_cua['Sáng'] : $ca_cua );
teq( 'dòng ca sau cũng vậy',
	array( '12:00', '20:00', 5.5 ), isset( $ca_cua['Chiều'] ) ? $ca_cua['Chiều'] : $ca_cua );

/* Ngày thiếu giờ ra vẫn phải có dòng, kèm ghi chú — bỏ đi là bảng xuất ra trông như người ta
   nghỉ hôm đó. */
$co_thieu = false;
foreach ( array_slice( $to_x[0]['hang'], 1 ) as $d_x ) {
	if ( false !== strpos( (string) $d_x[12], 'THIẾU GIỜ RA' ) ) { $co_thieu = true; }
}
t( 'ngày thiếu giờ ra vẫn có dòng, kèm ghi chú', $co_thieu, $to_x[0]['hang'] );

/* Mã NV phải ghi là CHỮ. Mã kiểu `0029` để Excel tự đoán là mất số 0 ở đầu. */
$o_ma = $to_x[0]['hang'][1][2];
t( 'mã NV được bọc thành chữ, không để Excel đoán',
	is_array( $o_ma ) && isset( $o_ma['chu'] ), $o_ma );

/* Dựng tệp thật rồi MỞ LẠI bằng máy — không tin "dựng xong là đúng". */
$noi_x = VHCC_Xuat::xlsx( $to_x );
t( 'dựng được tệp .xlsx', is_string( $noi_x ) && 'PK' === substr( $noi_x, 0, 2 ) );
$tep_x = sys_get_temp_dir() . '/vhcc-xuat-' . getmypid() . '.xlsx';
file_put_contents( $tep_x, $noi_x );
$z_x = new ZipArchive();
t( 'mở lại được tệp vừa dựng', true === $z_x->open( $tep_x ) );
foreach ( array( 1, 2, 3 ) as $i_x ) {
	$xml_x = $z_x->getFromName( 'xl/worksheets/sheet' . $i_x . '.xml' );
	t( 'trang tính ' . $i_x . ' là XML hợp lệ', false !== simplexml_load_string( (string) $xml_x ) );
}
$s1_x = $z_x->getFromName( 'xl/worksheets/sheet1.xml' );
$wb_x = $z_x->getFromName( 'xl/workbook.xml' );
$z_x->close();
@unlink( $tep_x );
t( 'tên ba trang tính nằm trong workbook',
	false !== strpos( $wb_x, 'Chi tiết ca' ) && false !== strpos( $wb_x, 'Tổng theo ca' )
	&& false !== strpos( $wb_x, 'Từng lượt chấm' ), $wb_x );
/* Khung ca của cơ sở này là Sáng 06:00–12:00 · Chiều 12:00–20:00 (khai ở mục trên), không phải
   bộ mặc định — đây chính là thứ anh Thắng hỏi: "chi tiết ca đó từ mấy h đến mấy h". */
t( 'trang Chi tiết ca in ra khung giờ ca thật (06:00 và 12:00)',
	false !== strpos( $s1_x, '>06:00<' ) && false !== strpos( $s1_x, '>12:00<' ), substr( $s1_x, 0, 600 ) );
t( 'và in cả tên ca', false !== strpos( $s1_x, '>Sáng<' ), substr( $s1_x, 0, 600 ) );
t( 'và tên có dấu không bị vỡ', false !== strpos( $s1_x, 'Người GIO1' ), substr( $s1_x, 0, 400 ) );

/* Gác cửa của đường tải tệp — hỏi hàm THUẦN, không gọi `xuat_tep` (hàm đó luôn `exit`, gọi
   trong bộ thử là giết luôn cả lượt chạy và phần gác cửa vĩnh viễn không có phép thử nào). */
teq( 'Admin xuất được', '',
	VHCC_Web::vi_sao_khong_xuat( $ADMIN_W, 'ca', $CS_GIO ) );
foreach ( array( 'Nhân viên' ) as $vt_x ) {
	$c_x = VHCC_Web::vi_sao_khong_xuat( array( 'name' => 'X', 'role' => $vt_x, 'coso' => $CS_GIO ),
		'ca', $CS_GIO );
	t( $vt_x . ' KHÔNG tải được tệp',
		'' !== $c_x && false !== strpos( $c_x, 'Cửa hàng trưởng' ), $c_x );
}
t( 'chưa chọn cơ sở -> chối', '' !== VHCC_Web::vi_sao_khong_xuat( $ADMIN_W, 'ca', '' ) );
t( 'kiểu xuất lạ -> chối', '' !== VHCC_Web::vi_sao_khong_xuat( $ADMIN_W, 'linh_tinh', $CS_GIO ) );
/* Cửa hàng trưởng chỉ tải được cơ sở MÌNH — ẩn cái nút không phải là gác cửa. */
$c_x2 = VHCC_Web::vi_sao_khong_xuat(
	array( 'name' => 'CHT', 'role' => 'Cửa hàng trưởng', 'coso' => 'TUTU_BT' ), 'ca', $CS_GIO );
t( 'Cửa hàng trưởng không tải được cơ sở của người khác', '' !== $c_x2, $c_x2 );

/* Nhân viên không khai ca được, kể cả POST thẳng. */
$h_ca_nv = vhcc_web( '864202', array(), array( 'man' => 'vp', 'ccs' => $CS_GIO, 'cth' => '2026-07' ) );
t( 'Nhân viên không thấy khối khai ca', strpos( $h_ca_nv, 'id="khaica"' ) === false, $h_ca_nv );
$_POST = array( 'viec' => 'ca', 'ccs' => $CS_GIO, 'ca_ten' => array( 'Lậu' ),
	'ca_tu' => array( '00:00' ), 'ca_den' => array( '23:00' ) );
$r_ca_nv = vhcc_goi_rieng( 'VHCC_Web', 'lam_viec',
	array( 'ca', array( 'name' => 'NV', 'role' => 'Nhân viên', 'coso' => $CS_GIO ) ) );
$_POST = array();
t( 'và POST thẳng việc khai ca cũng bị chối',
	is_array( $r_ca_nv ) && ! isset( $r_ca_nv[0]['xong'] ), $r_ca_nv );

/* ---- ô ẩn chở bộ lọc KHÔNG được đè lên cơ sở màn đang hiện ---- */
/* `o_loc()` cũng chở `ccs`, nên form có hai ô cùng tên và ô SAU thắng. Chọn một bộ phận mà cơ sở
   cũ rơi ra ngoài thì `$cs` thành rỗng, trong khi `?ccs=` trên thanh địa chỉ vẫn giữ cơ sở cũ —
   để o_loc thắng là bù giờ vào một cơ sở mà màn hình không hề đang hiện. */
function vhcc_ccs_cuoi( $html, $sau ) {
	$i = strpos( $html, $sau );
	if ( false === $i ) { return null; }
	$het = strpos( $html, '</form>', $i );
	$than = ( false === $het ) ? substr( $html, $i ) : substr( $html, $i, $het - $i );
	return preg_match_all( '/name="ccs" value="([^"]*)"/', $than, $m ) ? end( $m[1] ) : null;
}
$h_bu_loc = vhcc_web( '135791', array(), array( 'man' => 'cham', 'ccs' => 'TUTU_BT',
	'cth' => '2026-07', 'cbp' => 'Bộ phận không tồn tại' ) );
/* Bộ lọc gạt hết cơ sở -> màn không vẽ bảng, nên cũng không được vẽ hàng bù mang cơ sở cũ. */
t( 'lọc rỗng thì không vẽ hàng bù mang cơ sở cũ',
	strpos( $h_bu_loc, 'value="bu"' ) === false, $h_bu_loc );
/* Còn ở hàng bù nội tuyến: ô ccs cuối cùng trong form phải là cơ sở ĐANG HIỆN. */
teq( 'hàng bù gửi đúng cơ sở đang hiện', 'TUTU_BT',
	vhcc_ccs_cuoi( $h_o_bu, 'value="bu"' ) );
/* ⚠️ MỐC PHẢI LÀ `name="viec" value="ca"`, KHÔNG PHẢI `value="ca"` TRẦN. Từ khi khối Cách tính
   công có thêm lựa chọn "Theo khung ca", trên cùng màn ấy còn một `<option value="ca">` đứng
   TRƯỚC — mốc trần bắt trúng nó, rồi cắt tới `</form>` của form KHÁC, và phép thử đỏ oan về một
   chỗ chẳng có gì sai. Cùng cái bẫy "soi cả trang, bắt nhầm chuỗi ở khối khác". */
teq( 'form khai ca gửi đúng cơ sở đang hiện', $CS_GIO,
	vhcc_ccs_cuoi( $h_ch_gio, 'name="viec" value="ca"' ) );
/* 🔴 Ca phân biệt được "ô nào thắng": địa chỉ mang tiền tố `CS_` (app cũ viết vậy). `$cs` đã
   qua `chuan_coso()` nên là `FZ_SC_THU`, còn `o_loc()` chở nguyên `CS_FZ_SC_THU`. Ô của MÀN phải
   thắng — để o_loc thắng là khai ca cho một chuỗi cơ sở không tồn tại, và bảng công vẫn dùng ca
   mặc định mãi mà không ai hiểu vì sao lưu rồi không ăn. */
$h_tien_to = vhcc_web( '135791', array(),
	array( 'man' => 'cau_hinh', 'ccs' => 'CS_' . $CS_GIO, 'cth' => '2026-07' ) );
teq( 'địa chỉ có tiền tố CS_ thì form khai ca vẫn gửi mã cơ sở ĐÃ CHUẨN HOÁ', $CS_GIO,
	vhcc_ccs_cuoi( $h_tien_to, 'name="viec" value="ca"' ) );
teq( 'và hàng bù cũng vậy', 'TUTU_BT',
	vhcc_ccs_cuoi( vhcc_web( '135791', array(),
		array( 'man' => 'cham', 'ccs' => 'CS_TUTU_BT', 'cth' => '2026-07',
			'gnd' => '2026-07-02', 'gma' => 'QTC1' ) ), 'value="bu"' ) );

// ====== 51. TRANG CHÀO + LINK GỬI BỘ PHẬN + CHẠY ĐƯỢC TRÊN ĐIỆN THOẠI
/* Anh Thắng 26/08: *"làm lại giao diện web chuẩn để anh gửi các bộ phận"*. Bốn hướng anh chốt:
   trang chào theo vai · phần nhìn gọn · chạy tốt trên điện thoại · link riêng từng bộ phận. */

$h_nha_ad = vhcc_web( '135791' );                       // Admin
$h_nha_nv = vhcc_web( '864202' );                       // Nhân viên
$h_nha_ch = vhcc_web( '357913' );                       // Cửa hàng trưởng

t( 'mở trang ra là vào Trang chính', strpos( $h_nha_ad, 'Việc anh/chị làm được' ) !== false, $h_nha_ad );
t( 'chào đúng tên người đang vào', strpos( $h_nha_ad, 'Chào Admin Soát Công' ) !== false, $h_nha_ad );
t( 'và nói rõ đang vào với vai gì', strpos( $h_nha_ad, 'Admin' ) !== false );
/* 🔴 Thẻ việc dựng theo QUYỀN. Hiện rồi chối là dạy người dùng rằng màn này hay nói dối, và từ
   đó họ không tin cái nút nào nữa. */
t( 'Nhân viên thấy việc chấm công', strpos( $h_nha_nv, 'Chấm công</b>' ) !== false, $h_nha_nv );
t( 'và thấy việc xem công của mình', strpos( $h_nha_nv, 'Công của tôi</b>' ) !== false, $h_nha_nv );
t( 'nhưng KHÔNG thấy việc nạp công', strpos( $h_nha_nv, 'Nạp công từ .csv</b>' ) === false, $h_nha_nv );
t( 'không thấy việc hồ sơ', strpos( $h_nha_nv, 'Hồ sơ &amp; tài khoản</b>' ) === false, $h_nha_nv );
/* Thẻ "Khai ca làm việc" đã đi cùng lượt gộp tab — khai ca nay nằm TRONG màn Bảng công, và
   lịch làm việc có tab riêng. Canh thẻ Lịch: nhân viên THẤY nó (xem lịch của mình) nhưng thẻ
   Cấu hình thì không. */
t( 'không thấy việc cấu hình', strpos( $h_nha_nv, 'Cấu hình</b>' ) === false, $h_nha_nv );
t( 'Cửa hàng trưởng thấy việc chấm công bù', strpos( $h_nha_ch, 'Chấm công bù</b>' ) !== false, $h_nha_ch );
t( 'và thấy việc lịch làm việc', strpos( $h_nha_ch, 'Lịch làm việc</b>' ) !== false, $h_nha_ch );
t( 'nhân viên cũng thấy thẻ Lịch (xem ca của mình)',
	strpos( $h_nha_nv, 'Lịch làm việc</b>' ) !== false, $h_nha_nv );
t( 'nhưng KHÔNG thấy việc nạp công (bậc Quản lý)',
	strpos( $h_nha_ch, 'Nạp công từ .csv</b>' ) === false, $h_nha_ch );
t( 'Admin thấy đủ, kể cả hồ sơ', strpos( $h_nha_ad, 'Hồ sơ &amp; tài khoản</b>' ) !== false, $h_nha_ad );

/* ---- MỤC "NHÂN SỰ" + LỐI TẮT "THÊM NHÂN SỰ MỚI" -------------------------------------------
   Anh Thắng 30/08/2026, gửi ảnh khối "Việc anh/chị làm được": *"bổ sung thêm mục nhân sự"*, rồi
   *"THÊM NHÂN SỰ MỚI"* — trang /nhan-su/ (VHCC_TrangNS) trước đây chỉ có đường vào từ nút 👥 ở
   thanh bên, không hiện ở khối tổng này nên dễ bị bỏ sót; và việc TẠO người mới (vừa được thêm ô
   ảnh thẻ + đẩy máy ở bản 3.7.0) cũng cần một lối vào riêng thay vì chìm sau tile danh sách. */
t( '🔴 Admin thấy mục "Nhân sự"', strpos( $h_nha_ad, 'Nhân sự</b>' ) !== false, $h_nha_ad );
t( '🔴 dẫn đúng tới trang /nhan-su/ (VHCC_TrangNS::url())',
	strpos( $h_nha_ad, 'href="' . esc_url( VHCC_TrangNS::url() ) . '"' ) !== false, $h_nha_ad );
t( '🔴 Admin thấy lối tắt "Thêm nhân sự mới"', strpos( $h_nha_ad, 'Thêm nhân sự mới</b>' ) !== false, $h_nha_ad );
t( '🔴 dẫn thẳng vào form tạo (man=ho_so&sua=+), không phải danh sách',
	strpos( $h_nha_ad, 'href="' . esc_url( add_query_arg(
		array( 'man' => 'ho_so', 'sua' => '+' ), VHCC_Web::url() ) ) . '"' ) !== false, $h_nha_ad );
t( 'Nhân viên KHÔNG thấy mục Nhân sự (cùng quyền ho_so như Hồ sơ & tài khoản)',
	strpos( $h_nha_nv, 'Nhân sự</b>' ) === false, $h_nha_nv );
t( 'Nhân viên cũng KHÔNG thấy lối tắt Thêm nhân sự mới',
	strpos( $h_nha_nv, 'Thêm nhân sự mới</b>' ) === false, $h_nha_nv );
/* Mỗi thẻ phải có một câu nói việc đó ĐỂ LÀM GÌ — chỉ có tên thì vẫn phải đoán. */
t( 'mỗi việc kèm một câu giải thích', substr_count( $h_nha_ad, '<span>' ) >= 5, $h_nha_ad );

/* ---- link gửi bộ phận ---- */
t( 'có khối Đường link gửi cho bộ phận', strpos( $h_nha_ad, 'id="guilink"' ) !== false, $h_nha_ad );
t( 'khối link thu gọn sẵn', strpos( $h_nha_ad, 'id="guilink"><details>' ) !== false, $h_nha_ad );
t( 'link mang sẵn cơ sở', strpos( $h_nha_ad, 'ccs=TUTU_BT' ) !== false, $h_nha_ad );
t( 'và mang sẵn tháng', preg_match( '/cth=\d{4}-\d{2}/', $h_nha_ad ) === 1, $h_nha_ad );
t( 'gom cơ sở theo bộ phận', strpos( $h_nha_ad, '<th>Bộ phận</th>' ) !== false, $h_nha_ad );
/* 🔴 Nói THẲNG rằng link không phải chìa khoá — kẻo người gửi tưởng ai cầm link cũng xem được,
   rồi ngại không dám gửi, hoặc tệ hơn là tưởng đã chia sẻ xong mà người nhận mở ra chẳng thấy gì. */
t( 'nói rõ link KHÔNG phải chìa khoá', strpos( $h_nha_ad, 'không phải chìa khoá' ) !== false, $h_nha_ad );
t( 'Nhân viên KHÔNG có khối link gửi bộ phận', strpos( $h_nha_nv, 'id="guilink"' ) === false, $h_nha_nv );

/* ---- đường sang trang khác của công ty ----
   Anh Thắng 26/08: *"làm 1 trang chủ ghép các trang chấm công chung lại… tạo 1 trang chủ công ty
   K&H để liên kết đến các trang con"*. Trang chào ghép xong phần chấm công; khối này là đường ra.
   🔴 CHƯA CÀI thì KHÔNG được in khung rỗng: một tiêu đề không có gì bên dưới trông y như hỏng. */
/* 🔴 VẬN HÀNH CHI PHÍ CÓ MẶT TỪ ĐẦU — anh Thắng 28/08/2026: *"https://khmatrix.com/chi-phi/
   liên kết trang vận hành chi phí vào nhé"*. Plugin chi phí luôn được nạp trong bài kiểm này,
   nên khối "Trang khác" KHÔNG còn rỗng ngay cả khi chưa cài Nội bộ / Cổng K&H. */
t( '🔴 trang chào có đường sang Vận hành chi phí',
	strpos( $h_nha_ad, 'Vận hành chi phí' ) !== false, $h_nha_ad );
/* ⚠️ Đường dẫn lấy TỪ CHÍNH plugin kia (`VHCP_App::app_url()`), không gõ cứng — gõ cứng là hôm
   nào đổi đường dẫn bên ấy, ô này vẫn trỏ về đường cũ và bấm vào ra 404. */
t( 'và lấy đúng đường dẫn của plugin chi phí',
	strpos( $h_nha_ad, esc_url( VHCP_App::app_url() ) ) !== false, $h_nha_ad );
/* 🔴 NÓI THẲNG LÀ BÊN ẤY ĐĂNG NHẬP RIÊNG. Chưa làm đăng nhập một lần sang đó; im lặng thì người
   bấm sang bị hỏi mật khẩu và tưởng hệ hỏng. */
t( '🔴 nói rõ bên ấy còn đăng nhập riêng',
	strpos( $h_nha_ad, 'đăng nhập riêng' ) !== false, $h_nha_ad );

/* ⚠️ Khai bằng eval() vì PHP NÂNG mọi khai báo lớp ở cấp cao nhất lên lúc biên dịch tệp — khai
   thẳng thì `class_exists` đã trả true ngay từ dòng đầu và phép thử "chưa cài" ở trên không bao
   giờ đúng được. */
/* 🔴 LỚP CÓ MÀ HÀM KHÔNG. Bốn plugin cài độc lập nên bản có thể lệch nhau, và gọi một hàm không
   tồn tại là Fatal error — TRẮNG CẢ TRANG, không phải một ô hỏng. Vết này đã xảy ra thật ở chân
   trang app chi phí ngày 23/08/2026. Nên dựng đúng cảnh đó: cổng K&H bản cũ, chưa có `url()`. */
eval( 'class VHTC_Trang { public static function ve() { return null; } }' );
$h_nha_cu = vhcc_web( '135791' );
t( 'cổng K&H bản cũ (lớp CÓ, hàm url KHÔNG) -> trang chào vẫn vẽ được, không trắng trang',
	strpos( $h_nha_cu, 'Việc anh/chị làm được' ) !== false, substr( $h_nha_cu, 0, 200 ) );
t( 'và KHÔNG dựng ô trỏ sang cổng K&H', strpos( $h_nha_cu, 'Cổng K&amp;H' ) === false, $h_nha_cu );
/* Cổng K&H bản cũ không dựng được ô của nó, nhưng khối vẫn còn ô Vận hành chi phí — nên khối
   có mặt là ĐÚNG ở đây. Chốt "không in khung rỗng" nay canh ở chính hàm: xem phá thử. */
t( 'khối vẫn còn vì Vận hành chi phí dùng được',
	strpos( $h_nha_cu, 'Vận hành chi phí' ) !== false, $h_nha_cu );

eval( 'class VHNB_Trang { public static function url() { return "https://khmatrix.com/noi-bo/"; } }' );
$h_nha_2 = vhcc_web( '135791' );
t( 'cài rồi thì trang chào có khối Trang khác của công ty',
	strpos( $h_nha_2, 'Trang khác của công ty' ) !== false, $h_nha_2 );
t( 'và trỏ sang bảng tin nội bộ', strpos( $h_nha_2, 'https://khmatrix.com/noi-bo/' ) !== false, $h_nha_2 );
t( 'ô cổng K&H vẫn vắng vì bản kia chưa có url()',
	strpos( $h_nha_2, 'Cổng K&amp;H' ) === false, $h_nha_2 );
/* 🔴 Đường dẫn lấy TỪ CHÍNH plugin kia, không gõ cứng: gõ cứng là hôm nào anh Thắng đổi đường
   dẫn bên ấy, ô này vẫn trỏ về đường cũ — bấm vào ra 404 mà không có gì báo. */
t( 'mã KHÔNG gõ cứng đường dẫn trang nội bộ',
	strpos( file_get_contents( VHCC_DIR . 'includes/class-vhcc-web.php' ), "'noi-bo'" ) === false );

/* ---- chạy được trên điện thoại ---- */
t( 'trang khai khổ màn hình', strpos( $h_nha_ad, 'name="viewport"' ) !== false, $h_nha_ad );
t( 'có luật riêng cho màn nhỏ', strpos( $h_nha_ad, '@media(max-width:640px)' ) !== false, $h_nha_ad );
/* 🔴 Ô nhập dưới 16px thì iPhone TỰ PHÓNG TO cả trang mỗi lần bấm vào ô, và không tự thu lại —
   người dùng phải vuốt ngang suốt phần còn lại. Đây là lỗi ai cũng gặp mà ít ai lần ra. */
t( 'ô nhập trên điện thoại đủ 16px (kẻo iPhone tự phóng to trang)',
	strpos( $h_nha_ad, 'input,select,textarea{font-size:16px}' ) !== false, $h_nha_ad );
t( 'thẻ việc xuống một cột trên màn nhỏ',
	strpos( $h_nha_ad, '.the-viec{grid-template-columns:1fr}' ) !== false, $h_nha_ad );
t( 'ô lọc cũng xuống một cột', strpos( $h_nha_ad, '.luoi{grid-template-columns:1fr}' ) !== false, $h_nha_ad );
/* Bảng ngang vẫn phải cuộn được — 31 cột không có cách nào nhét vừa màn 5 inch. */
t( 'bảng rộng vẫn cuộn ngang được trong khung riêng',
	strpos( $h_nha_ad, '.cuon{overflow-x:auto' ) !== false, $h_nha_ad );

/* ---- phần nhìn ---- */
t( 'đầu trang mang tên K&H', strpos( $h_nha_ad, '<b>K&amp;H</b> Chấm công' ) !== false, $h_nha_ad );
/* ⚠️ ĐO CÁI LIÊN KẾT, đừng đo TÊN LỚP. `class="hieu"` khớp hụt ngay khi thêm một lớp thứ hai
   (`class="hieu canh-hieu"`) — mà cái nút vẫn nằm đó và vẫn bấm về đúng chỗ. Đo tên lớp trần là
   phép thử đỏ vì chuyện trang trí, và xanh trở lại chỉ vì ai đó đổi lớp cho khớp. */
t( 'bấm tên là về trang chính',
	preg_match( '~<a[^>]*class="[^"]*\bhieu\b[^"]*"[^>]*href="[^"]*"~', $h_nha_ad ) === 1, $h_nha_ad );
t( 'trang chào KHÔNG dùng JavaScript',
	stripos( $h_nha_ad, '<script' ) === false && ! preg_match( '/\son[a-z]+\s*=\s*"/i', $h_nha_ad ),
	$h_nha_ad );

/* ---- MỌI FORM POST PHẢI MANG THẺ PHIÊN `ky` KHÁC RỖNG ---- */
/* 🔴 Bắt được lỗi thật: tab "Bảng công tháng" gọi `the_cong_vp( $toi )` mà bên trong lại dùng
   `$ky` — biến chưa hề được truyền vào. Form khai ca vì thế mang `ky=""`, và trên trang thật
   MỌI lượt lưu ca đều bị chối bằng câu "Phiên đã hết hoặc biểu mẫu không hợp lệ".
   Phép thử cũ không bắt vì nó gọi thẳng `lam_viec`, đi vòng qua cửa kiểm thẻ. Nên chốt này quét
   TẤT CẢ form của TẤT CẢ màn, thay vì canh từng form một. */
$man_thu = array(
	'cham'     => array( 'man' => 'cham', 'ccs' => 'TUTU_BT', 'cth' => '2026-07' ),
	'vp'       => array( 'man' => 'vp', 'ccs' => $CS_GIO, 'cth' => '2026-07' ),
	'nha'      => array( 'man' => 'nha' ),
	'cong_toi' => array( 'man' => 'cong_toi' ),
	'ho_so'    => array( 'man' => 'ho_so' ),
);
foreach ( $man_thu as $ten_man => $get_man ) {
	$h_man = vhcc_web( '135791', array(), $get_man );
	foreach ( array_slice( explode( '<form', $h_man ), 1 ) as $khuc_man ) {
		$het_man = strpos( $khuc_man, '</form>' );
		$than_man = ( false === $het_man ) ? $khuc_man : substr( $khuc_man, 0, $het_man );
		if ( false === stripos( $than_man, 'method="post"' ) ) { continue; }
		$viec_man = preg_match( '/name="viec" value="([^"]*)"/', $than_man, $m_man ) ? $m_man[1] : '(nút)';
		t( 'màn ' . $ten_man . ': form POST "' . $viec_man . '" mang thẻ phiên khác rỗng',
			preg_match( '/name="ky" value="[^"]+"/', $than_man ) === 1, trim( substr( $than_man, 0, 200 ) ) );
	}
}

/* ================================= 51b. THÔNG TIN CÔNG TY Ở CUỐI TRANG
   Anh Thắng 26/08: *"nhớ bổ sung thông tin công ty ở cuối trang nhé"* — kèm ảnh chính trang này. */

/* 🔴 MỘT CHỖ ĐÓNG TRANG, KHÔNG BẢY CHỖ.
   Trước đây bảy màn tự `echo '</div></body></html>'`. Thêm chân trang kiểu ấy là sửa bảy chỗ,
   quên một chỗ, rồi đúng màn bị quên thì thiếu thông tin công ty mà chẳng ai để ý. Canh thẳng
   vào MÃ: cả tệp chỉ được có đúng một dòng đóng trang. */
/* ⚠️ BỎ CHÚ THÍCH TRƯỚC KHI ĐẾM. Chốt này soi MÃ, không soi lời giải thích về mã: chính dòng
   chú thích kể VỀ cái lỗi cũ ("mỗi màn tự echo '</div></body></html>'") bị đếm thành một chỗ
   sót — phép thử đỏ trong khi mã đúng. Đúng vết đã cắn `kiem-goi-cheo.php` sáng nay. */
function vhcc_bo_chu_thich( $ma ) {
	$ra = '';
	foreach ( token_get_all( $ma ) as $tk ) {
		if ( is_array( $tk ) && in_array( $tk[0], array( T_COMMENT, T_DOC_COMMENT ), true ) ) { continue; }
		$ra .= is_array( $tk ) ? $tk[1] : $tk;
	}
	return $ra;
}
$ma_web = vhcc_bo_chu_thich( file_get_contents( VHCC_DIR . 'includes/class-vhcc-web.php' ) );
teq( '🔴 class-vhcc-web.php chỉ có ĐÚNG MỘT chỗ in </body></html>', 1,
	substr_count( $ma_web, "'</body></html>'" ) );
teq( 'và không còn dòng đóng trang gộp nào sót lại', 0,
	substr_count( $ma_web, "</div></body></html>'" ) );

/* Chưa ai khai công ty ở đâu -> KHÔNG bịa ra tên, địa chỉ, mã số thuế. Bịa còn tệ hơn để trống. */
delete_option( 'vhg_chan' );
teq( 'chưa khai gì thì thong_tin() trả rỗng', array(), VHCC_Cty::thong_tin() );
$_chan_trong = VHCC_Cty::html();
t( '🔴 nhưng KHÔNG bịa ra thông tin công ty nào',
	false === strpos( $_chan_trong, 'cty-ten' ) && false === strpos( $_chan_trong, 'Mã số thuế' ),
	$_chan_trong );
/* ⚠️ VẪN PHẢI CÒN SỐ PHIÊN BẢN. Anh Thắng bảo *"cuối MỌI trang"*, mà thông tin công ty là thứ
   khai được và site mới cài thì chắc chắn trống — để cả chân trang biến mất theo là đúng lúc
   cần số nhất (vừa cài xong, đang muốn biết bản nào đang chạy) thì lại không có. */
t( 'chân trang trống vẫn giữ nhãn phiên bản',
	false !== strpos( $_chan_trong, 'class="cty-pb"' ), $_chan_trong );
t( 'trang vẫn vẽ bình thường khi chưa khai công ty',
	strpos( vhcc_web( '135791' ), 'Việc anh/chị làm được' ) !== false );

/* Khai vào ô cài đặt dùng chung `vhg_chan` — đúng ô mà màn quản trị của plugin Ghế đang ghi. */
update_option( 'vhg_chan', array(
	'ten'        => 'CÔNG TY TNHH DỊCH VỤ VÀ GIẢI TRÍ K&H',
	'ten_qt'     => 'K&H SERVICES AND ENTERTAINMENT COMPANY LIMITED',
	'mst'        => '0106924989',
	'dia_chi'    => 'Thôn Mai Nội, Xã Sóc Sơn, Thành phố Hà Nội, Việt Nam',
	'dai_dien'   => 'Nguyễn Văn Kiên',
	'dien_thoai' => '0435961469',
	'email'      => '',
	'ngay_hd'    => '05/08/2015',
	'co_quan'    => 'Thuế cơ sở 18 thành phố Hà Nội',
	'chi_nhanh'  => "Đà Nẵng\nNha Trang",
	'hien'       => 0,
) );

/* 🔴 CHÂN TRANG PHẢI CÓ Ở **MỌI** MÀN, kể cả màn đăng nhập — nhất là màn đăng nhập, vì đó là
   thứ duy nhất người ngoài nhìn thấy. Quét lại đúng danh sách màn ở khối trên, không gõ riêng. */
$h_dnhap = vhcc_web( '000000' );        // PIN sai -> màn đăng nhập
t( 'màn ĐĂNG NHẬP có thông tin công ty',
	strpos( $h_dnhap, '0106924989' ) !== false, substr( $h_dnhap, -400 ) );
/* 🔴 VÀ NHÃN PHIÊN BẢN CŨNG PHẢI CÓ Ở CHÂN TRANG ĐẦY ĐỦ, không chỉ ở chân trang trống.
   Khối phép ở trên soi lúc CHƯA khai công ty, nên nó không với tới nhánh này — bỏ nhãn khỏi
   chân trang đầy đủ mà mọi phép vẫn xanh. Đã phá thử để thấy đúng chuyện đó. */
t( 'chân trang ĐẦY ĐỦ vẫn có nhãn phiên bản',
	strpos( $h_dnhap, 'class="cty-pb"' ) !== false, substr( $h_dnhap, -600 ) );
t( 'và số ấy đúng bằng hằng VHCC_VERSION',
	strpos( $h_dnhap, 'Chấm công ' . VHCC_VERSION ) !== false, VHCC_VERSION );
foreach ( $man_thu as $ten_man => $get_man ) {
	$h_ct = vhcc_web( '135791', array(), $get_man );
	t( 'màn ' . $ten_man . ' có tên công ty ở cuối trang',
		strpos( $h_ct, 'CÔNG TY TNHH DỊCH VỤ VÀ GIẢI TRÍ K&amp;H' ) !== false );
	t( 'màn ' . $ten_man . ' có mã số thuế', strpos( $h_ct, '0106924989' ) !== false );
	t( 'màn ' . $ten_man . ' có dòng bản quyền', strpos( $h_ct, '© ' . gmdate( 'Y' ) ) !== false );
}

$h_ct = vhcc_web( '135791' );
/* 🔴 CHÂN TRANG PHẢI NẰM TRONG KHUNG `.bo` CỦA TRANG.
   Anh Thắng 26/08: *"bị lệch"* — bản đầu in chân trang SAU khi đã đóng `.bo`, nên nó dính sát
   mép trái màn hình trong khi cả trang còn lại thụt vào. Bộ thử lúc ấy vẫn xanh vì nó chỉ hỏi
   "có chữ đó không", chưa hỏi "chữ đó nằm ở đâu". */
t( '🔴 chân trang nằm TRONG khung .bo, không lọt ra ngoài',
	strpos( $h_ct, '<div class="bo"><footer class="cty">' ) !== false,
	substr( $h_ct, strrpos( $h_ct, 'footer class="cty"' ) - 120, 160 ) );
/* ⚠️ Bỏ điều kiện `@media(max-width:…)` ra trước khi soi: đó là mốc màn hình, không phải bề
   ngang của khối. Bản đầu quét thẳng cả chuỗi nên chốt đỏ oan. */
$css_cty = preg_replace( '/@media\s*\([^)]*\)/', '', VHCC_Cty::css() );
t( 'và kiểu chữ của chân trang KHÔNG tự đặt max-width (kẻo hai khung chồng nhau)',
	strpos( $css_cty, 'max-width' ) === false, $css_cty );
t( 'số điện thoại bấm gọi được', strpos( $h_ct, 'href="tel:0435961469"' ) !== false, $h_ct );
t( 'có chi nhánh, nối bằng dấu chấm giữa',
	strpos( $h_ct, 'Đà Nẵng · Nha Trang' ) !== false, $h_ct );
/* Ô email đang trống -> bỏ hẳn dòng, không in nhãn treo lơ lửng. */
t( 'ô email trống thì KHÔNG in nhãn Email:', strpos( $h_ct, 'Email:' ) === false );
/* 🔴 KHÔNG đọc cờ `hien` của plugin Ghế (đang để 0 ở trên). Cờ ấy nói "có hiện trên trang Ghế
   không"; tắt nó để trang bán mã gọn hơn mà kéo theo trang chấm công mất phần giới thiệu công
   ty thì không ai đoán ra vì sao. */
t( 'tắt cờ `hien` bên plugin Ghế thì trang này VẪN có thông tin công ty',
	strpos( $h_ct, '0106924989' ) !== false );
/* Chân trang là CHỮ, không được kéo theo script hay thuộc tính on*= nào. */
t( 'chân trang không mang script nào',
	stripos( $h_ct, '<script' ) === false && ! preg_match( '/\son[a-z]+\s*=\s*"/i', $h_ct ) );
/* Kiểu chữ của chân trang phải nằm trong khối <style> DUY NHẤT của trang, không phải thẻ thứ hai. */
teq( 'cả trang chỉ có MỘT khối kiểu chữ', 1, substr_count( $h_ct, '<style>' ) );
t( 'và khối ấy có kiểu chữ của chân trang', strpos( $h_ct, '.cty-ten{' ) !== false );

/* Sửa ở ô cài đặt thì trang đổi theo ngay — không phải sửa mã, đóng gói, cài lại. */
$o_cty = get_option( 'vhg_chan' );
$o_cty['dia_chi'] = 'Số 1 Đường Mới, Hà Nội';
$o_cty['email']   = 'lienhe@khmatrix.com';
update_option( 'vhg_chan', $o_cty );
$h_ct2 = vhcc_web( '135791' );
t( 'sửa địa chỉ ở ô cài đặt thì trang đổi theo', strpos( $h_ct2, 'Số 1 Đường Mới' ) !== false );
t( 'và không còn địa chỉ cũ', strpos( $h_ct2, 'Thôn Mai Nội' ) === false );
t( 'khai email rồi thì dòng Email hiện ra',
	strpos( $h_ct2, 'href="mailto:lienhe@khmatrix.com"' ) !== false );

/* ---- bảng mặc định: HỎI PLUGIN KHÁC, không tự khai ----
   Plugin này KHÔNG giữ bản chép nào của thông tin công ty. Chưa ai lưu ô cài đặt thì nó hỏi
   `VHG_Chan` (plugin Ghế) rồi hỏi `VHTC_Trang` (cổng K&H). Không plugin nào có mặt thì thôi —
   đã thử ở đầu khối này. */
delete_option( 'vhg_chan' );
teq( 'lúc này quả thật chưa nạp plugin Ghế', false, class_exists( 'VHG_Chan' ) );
require_once $goc . '/wordpress/vhcp-ghe/includes/class-vhg-chan.php';
$t_md = VHCC_Cty::thong_tin();
t( '🔴 ô cài đặt trống thì lấy bảng mặc định TỪ plugin Ghế',
	isset( $t_md['mst'] ) && '0106924989' === $t_md['mst'], $t_md );
t( 'và trang hiện ra đúng thông tin ấy',
	strpos( vhcc_web( '135791' ), 'Thôn Mai Nội' ) !== false );

/* 🔴 Ô CỐ Ý ĐỂ TRỐNG PHẢI GIỮ ĐƯỢC TRẠNG THÁI TRỐNG.
   Anh Thắng xoá ô "Cơ quan quản lý thuế" đi vì không muốn hiện nữa. Nếu chỗ trộn dùng
   `! empty()` thay vì `array_key_exists()` thì giá trị mặc định nhảy vào lấp lại — xoá xong
   vẫn thấy, sửa mãi không mất, mà chẳng có gì giải thích vì sao. */
update_option( 'vhg_chan', array_merge( VHG_Chan::mac_dinh(), array( 'co_quan' => '' ) ) );
$h_ct3 = vhcc_web( '135791' );
t( 'xoá trắng ô Cơ quan quản lý thuế thì dòng đó BIẾN MẤT',
	strpos( $h_ct3, 'Cơ quan quản lý thuế' ) === false, $h_ct3 );
t( 'nhưng mấy ô khác vẫn còn', strpos( $h_ct3, '0106924989' ) !== false );

delete_option( 'vhg_chan' );

/* ---- màn mặc định phải KHAI THẲNG, không suy từ vị trí trong danh sách ---- */
/* 🔴 Bản trước lấy màn CUỐI danh sách làm mặc định. Thêm tab "Bảng công tháng" (cùng bậc quyền
   với "Bảng chấm công") là Cửa hàng trưởng đăng nhập vào bỗng rơi thẳng vào tab mới, chỉ vì nó
   được khai sau một dòng. Không gì báo, thanh nút trông y hệt. */
/* 🔴 ĐỔI Ý CÓ CHỦ Ý (anh Thắng 26/08: *"làm lại giao diện web chuẩn để anh gửi các bộ phận"*):
   MỌI vai giờ mở ra là vào TRANG CHÀO, không rơi thẳng vào bảng số. Người bộ phận mở link ra mà
   gặp ngay mấy trăm ô thì không biết mình được làm gì và bấm vào đâu. */
foreach ( array( 'Admin', 'Kế toán cá nhân', 'Quản lý', 'Cửa hàng trưởng', 'Nhân viên' ) as $vt_md ) {
	teq( $vt_md . ' mở ra là vào Trang chính', 'nha',
		VHCC_Web::man_mac_dinh( VHCC_Web::man_cua( array( 'role' => $vt_md ) ) ) );
}
/* Và canh cả MÀN THẬT SỰ HIỆN RA, không chỉ canh hàm trả về gì: hàm đúng mà chỗ gọi không dùng
   nó thì mọi phép trên vẫn xanh. Đã phá thử để thấy đúng chuyện đó. */
$h_cht_md = vhcc_web( '357913' );
t( 'Cửa hàng trưởng đăng nhập vào là thấy TRANG CHÀO',
	strpos( $h_cht_md, 'Việc anh/chị làm được' ) !== false, $h_cht_md );
t( 'chứ không rơi thẳng vào bảng số',
	strpos( $h_cht_md, 'Chi tiết từng lượt' ) === false
	&& strpos( $h_cht_md, 'là <b>số giờ làm</b>' ) === false, $h_cht_md );

/* Mọi màn khai được đều phải có tên trong bảng ưu tiên, kẻo thêm màn mới là lại rơi vào nhánh
   đoán mò ở cuối hàm. */
foreach ( array_keys( VHCC_Web::man_cua( array( 'role' => 'Admin' ) ) ) as $k_man ) {
	t( 'màn "' . $k_man . '" có tên trong bảng ưu tiên màn mặc định',
		in_array( $k_man, VHCC_Web::MAN_UU_TIEN, true ), VHCC_Web::MAN_UU_TIEN );
}

/* Nhân viên bậc 1 không mở được tab này. */
$h_vp_nv = vhcc_web( '864202', array(), $g_vp );
t( 'Nhân viên KHÔNG thấy tab Bảng công tháng', strpos( $h_vp_nv, '>Bảng công tháng<' ) === false, $h_vp_nv );
t( 'và gõ tay ?man=vp cũng không ra lưới', strpos( $h_vp_nv, '↳ ca đêm' ) === false, $h_vp_nv );

// ====== 50. MÃ TỰ SINH PHẢI KHÔNG ĐỤNG NHAU — lỗi im lặng làm mất cờ của người khác
/* Bài kiểm này CHẾT NGẪU NHIÊN khoảng 1/5 lượt chạy (UNIQUE constraint failed trên `ma_yc`),
   và lần lần ra thì đó là lỗi thật, có sẵn từ trước: ba nơi cùng sinh mã bằng
   `YmdHis . wp_rand(100, 999)` — cùng một giây chỉ có 900 giá trị.

   🔴 Chỗ nguy nhất KHÔNG phải chỗ làm bài kiểm chết. `VHCC_Cham::luu_ghi_chu` tra `flag_id`
      trước; trùng mã thì nó coi là "sửa cờ cũ" và ĐÈ LÊN cờ của người khác — khác ngày, khác
      người, khác nội dung — rồi vẫn trả `ok:true`. Trên MySQL thật `$wpdb->insert` chỉ trả về
      false chứ không ném lỗi, nên cả hai kiểu hỏng đều IM LẶNG. */

$U_MA = array( 'name' => 'Admin Mã', 'role' => 'Admin', 'coso' => '' );

/* Sinh nhiều mã LIÊN TIẾP trong cùng một giây — đúng cảnh mấy người bấm gửi cùng lúc.
   🔴 PHẢI GHI TỪNG MÃ VÀO BẢNG NGAY SAU KHI SINH, y như đường chạy thật.
   `ma_moi()` chống trùng bằng cách HỎI BẢNG. Sinh 200 mã mà không ghi mã nào vào bảng thì lớp
   chống trùng ấy không có gì để đọc, và cả phép thử tụt xuống thành "200 lần bốc ngẫu nhiên
   trong 900 nghìn giá trị có trùng không" — theo nghịch lý ngày sinh thì khoảng 2% số lần chạy
   sẽ trùng. Tức là bài kiểm ĐỎ NGẪU NHIÊN vài chục lượt một lần, trong khi mã chạy đúng. Đỏ
   ngẫu nhiên là thứ dạy người ta chạy lại bài kiểm cho tới lúc xanh. */
$ds_ma = array();
for ( $i_ma = 0; $i_ma < 200; $i_ma++ ) {
	$ma_x = VHCC_DB::ma_moi( 'YC', 'yeu_cau_nv', 'ma_yc' );
	$ds_ma[] = $ma_x;
	if ( '' !== $ma_x ) {
		$wpdb->insert( VHCC_DB::t( 'yeu_cau_nv' ), array( 'ma_yc' => $ma_x, 'ma_nv' => 'MA' . $i_ma ) );
	}
}
teq( '200 mã sinh liên tiếp thì KHÔNG mã nào rỗng', 0, count( array_filter( $ds_ma, function ( $x ) {
	return '' === $x; } ) ) );
teq( 'và không mã nào trùng mã nào', 200, count( array_unique( $ds_ma ) ) );

/* 🔴 Chốt gắn cờ: hai cờ gắn liên tiếp phải là HAI cờ, không phải một cờ bị đè. */
$co_a = VHCC_Cham::luu_ghi_chu( $U_MA, array( 'coso' => 'TUTU_BT', 'ngay' => '2026-07-11',
	'ma_nv' => 'MA1', 'ho_ten' => 'Người MA1', 'ghi_chu' => 'cờ của người thứ nhất' ) );
$co_b = VHCC_Cham::luu_ghi_chu( $U_MA, array( 'coso' => 'TUTU_BT', 'ngay' => '2026-07-12',
	'ma_nv' => 'MA2', 'ho_ten' => 'Người MA2', 'ghi_chu' => 'cờ của người thứ hai' ) );
t( 'gắn được cờ thứ nhất', ! empty( $co_a['ok'] ), $co_a );
t( 'gắn được cờ thứ hai', ! empty( $co_b['ok'] ), $co_b );
t( 'hai cờ mang HAI mã khác nhau', $co_a['flagId'] !== $co_b['flagId'],
	$co_a['flagId'] . ' vs ' . $co_b['flagId'] );
$ds_co_ma = VHCC_Cham::ds_ghi_chu( $U_MA, 'TUTU_BT', '2026-07' );
$noi_dung_co = array();
foreach ( $ds_co_ma as $c_ma ) { $noi_dung_co[] = $c_ma['ghi_chu']; }
t( 'cờ của người thứ nhất KHÔNG bị cờ thứ hai đè mất',
	in_array( 'cờ của người thứ nhất', $noi_dung_co, true )
	&& in_array( 'cờ của người thứ hai', $noi_dung_co, true ), $noi_dung_co );

/* Truyền sẵn flag_id thì vẫn phải SỬA đúng cờ đó, không đẻ ra cờ mới. */
$co_c = VHCC_Cham::luu_ghi_chu( $U_MA, array( 'flag_id' => $co_a['flagId'], 'coso' => 'TUTU_BT',
	'ngay' => '2026-07-11', 'ma_nv' => 'MA1', 'ho_ten' => 'Người MA1', 'ghi_chu' => 'đã sửa lại' ) );
teq( 'sửa cờ cũ thì giữ nguyên mã', $co_a['flagId'], $co_c['flagId'] );
teq( 'và KHÔNG đẻ thêm cờ', count( $ds_co_ma ),
	count( VHCC_Cham::ds_ghi_chu( $U_MA, 'TUTU_BT', '2026-07' ) ) );

/* Nới số ngẫu nhiên rồi thì cũng đừng ai lặng lẽ hạ nó xuống lại. */
$ma_mau = VHCC_DB::ma_moi( 'YC', 'yeu_cau_nv', 'ma_yc' );
t( 'mã có đủ 6 chữ số ngẫu nhiên ở đuôi (900 giá trị là quá ít cho một giây)',
	preg_match( '/^YC\d{14}\d{6}$/', $ma_mau ) === 1, $ma_mau );
/* Tên cột đi thẳng vào câu SQL -> chữ lạ phải bị chối, không được ghép vào câu lệnh. */
teq( 'tên cột lạ bị chối, không ghép vào SQL', '',
	VHCC_DB::ma_moi( 'YC', 'yeu_cau_nv', 'ma_yc; DROP TABLE x' ) );

/* 🔴 Chốt quét mã: không tệp nào được quay lại kiểu sinh mã cũ. */
$ma_tho = array();
foreach ( glob( $goc . '/wordpress/vhcp-cham-cong/includes/*.php' ) as $f_ma ) {
	foreach ( explode( "\n", file_get_contents( $f_ma ) ) as $i_d => $d_ma ) {
		if ( 0 === strpos( ltrim( $d_ma ), '*' ) || false !== strpos( $d_ma, '//' ) ) { continue; }
		if ( preg_match( "/wp_rand\(\s*100\s*,\s*999\s*\)/", $d_ma ) ) {
			$ma_tho[] = basename( $f_ma ) . ':' . ( $i_d + 1 );
		}
	}
}
t( 'không tệp nào còn tự sinh mã bằng wp_rand(100,999)', 0 === count( $ma_tho ), implode( ', ', $ma_tho ) );

/* ---- lưới người × ngày của bản cũ đã đi hẳn, không để lại hàm mồ côi ---- */
$than_web_qtc = file_get_contents( $goc . '/wordpress/vhcp-cham-cong/includes/class-vhcc-web.php' );
t( 've_luoi_cham (lưới cũ) đã bỏ hẳn, không còn nằm chết trong tệp',
	strpos( $than_web_qtc, 've_luoi_cham' ) === false );

/* ==========================================================================================
 *  60. TRANG QUẢN LÝ NHÂN SỰ — "AI VÀO ĐƯỢC TRANG NÀO"
 * ------------------------------------------------------------------------------------------
 *  Anh Thắng 26/08/2026: *"Giờ anh muốn tạo 1 trang Quản lý nhân sự riêng, để cấu hình nhân sự
 *  có thể xem những trang nào trong tất cả các trang anh làm"* — *"để điều phối nó dễ hơn"*.
 *
 *  🔴 CHỖ NGUY HIỂM NHẤT CỦA TÍNH NĂNG NÀY KHÔNG PHẢI LÀ "KHOÁ HỤT" MÀ LÀ "KHOÁ NHẦM".
 *  Một cái sổ quyền vào trang, viết ẩu, có ba cách giết cả công ty trong im lặng:
 *    1. Khai cả trang CÔNG KHAI vào sổ  -> khách quét QR ghế massage bị chối, tiền không vào.
 *    2. Mặc định là "chưa khai = cấm"   -> ngày bản mới lên là 240 người mất đường vào.
 *    3. Lưu một trang 50 người mà GHI ĐÈ cả sổ -> xoá sạch ngoại lệ của 190 người còn lại.
 *  Phần lớn phép thử dưới đây canh đúng ba chuyện đó.
 * ======================================================================================== */

/* ---- 60a. SỔ TRANG: chỉ những trang CÓ CỬA ĐĂNG NHẬP BẰNG PHIÊN CHẤM CÔNG ---- */
$ns_ds = VHCC_Cong::ds();
t( 'sổ trang dò được trang quản trị chấm công', isset( $ns_ds['cham_cong'] ) );
t( 'sổ trang dò được trạm chấm công',           isset( $ns_ds['tram'] ) );
/* 🔴 BỐN TRANG NÀY PHẢI VẮNG MẶT. Xem khối chú thích ở `VHCC_Cong::SO` — mỗi cái là một cách
   làm hỏng việc kinh doanh mà màn hình không nói được gì cho người bị chối. */
foreach ( array( 'ghe' => 'trang của KHÁCH quét QR ghế massage',
	'cong' => 'cửa trước công khai',
	'hop_dong' => 'giao diện Apps Script tự đăng nhập bên trong',
	'chi_phi' => 'app có sổ người dùng RIÊNG, không có Mã NV' ) as $ns_k => $ns_ly ) {
	t( '🔴 "' . $ns_k . '" KHÔNG được nằm trong sổ quyền — ' . $ns_ly,
		! isset( VHCC_Cong::SO[ $ns_k ] ) );
}
/* Sổ khai lớp nào thì lớp ấy phải có thật hàm `url()` — khai hụt là Fatal error, trắng trang. */
foreach ( VHCC_Cong::SO as $ns_k => $ns_t ) {
	t( 'lớp "' . $ns_t['lop'] . '" khai trong sổ có thật hàm url()',
		! class_exists( $ns_t['lop'] ) || method_exists( $ns_t['lop'], 'url' ) );
	t( 'quyền "' . $ns_t['quyen'] . '" của trang "' . $ns_k . '" có khai trong thang vai',
		isset( VHCC_Vai::QUYEN[ $ns_t['quyen'] ] ) );
}

/* ---- 60b. MẶC ĐỊNH LÀ THANG VAI, KHÔNG PHẢI BẢNG TRẮNG ---- */
delete_option( VHCC_Cong::O );
$ns_nv  = array( 'ma_nv' => 'QN1', 'role' => 'Nhân viên' );
$ns_ad  = array( 'ma_nv' => 'QN2', 'role' => 'Admin' );
$ns_kt  = array( 'ma_nv' => 'QN3', 'role' => 'Kế toán' );
t( '🔴 chưa khai gì thì nhân viên VẪN vào được trạm chấm công (không phải bảng trắng)',
	VHCC_Cong::duoc_vao( $ns_nv, 'tram' ) );
t( 'chưa khai gì thì Admin vẫn vào được màn quản trị', VHCC_Cong::duoc_vao( $ns_ad, 'cham_cong' ) );
/* Trang KHÔNG có trong sổ thì CHO QUA — sổ này để siết có chủ ý, không phải một cánh cửa mới. */
t( '🔴 trang lạ / chưa khai thì CHO QUA, không chặn', VHCC_Cong::duoc_vao( $ns_nv, 'mot_trang_chua_khai' ) );
teq( 'và không có câu chối nào cho trang lạ', '', VHCC_Cong::vi_sao_khong( $ns_nv, 'mot_trang_chua_khai' ) );

/* ---- 60b2. ĐẨY NGƯỜI SANG HỆ GHẾ -----------------------------------------------------------
   🔴 Anh Thắng 28/08/2026: *"anh muốn đẩy nhân sự liên kết hệ thống ghế"*, rồi chốt cách làm:
      *"để tránh mở vai trò thì mình làm từng hệ phân quyền mở / khóa như này"*.

   Cột thứ tư trông giống ba cột kia nhưng bên dưới là cơ chế KHÁC HẲN. `/ghe` có phiên riêng
   bằng PIN và không đọc `ma_nv`, nên ngoại lệ ở `VHCC_Cong` không bám vào đâu — "Mở" ở đây
   phải là ĐẨY NGƯỜI THẬT sang sổ người dùng của hệ ghế. */
/**
 * Nạp màn Quản lý nhân sự bằng một thẻ phiên.
 *
 * ⚠️ Trang này dùng CHUNG cookie với màn quản trị chấm công (`VHCC_Web::COOKIE`) — nó là một
 *    hệ, không phải hai. Đặt cookie khác là `toi()` trả rỗng và mọi phép thử dưới đây soi
 *    trang chối chứ không soi bảng.
 */
function vhcc_hr_ns( $tok, $get = array() ) {
	$_GET = $get; $_POST = array();
	$_COOKIE = array( VHCC_Web::COOKIE => $tok );
	ob_start(); VHCC_TrangNS::phuc_vu(); $h = ob_get_clean();
	$_GET = array(); $_COOKIE = array();
	return $h;
}

/* ⚠️ Nạp lớp thật của plugin ghế. `VHCC_DayGhe::co_he_ghe()` hỏi `class_exists('VHG_Auth')` —
   đúng như nó phải hỏi, vì site không cài plugin ghế thì cột kia đừng vẽ ra làm gì. Không nạp
   ở đây thì cả khối này chạy trên nhánh "chưa cài", và mọi phép thử đều xanh vì lý do sai. */
/* `VHG_Auth::users()` đọc bảng qua `VHG_DB` khi nguồn là 'chung' — nạp cả hai, không thì
   phép thử chuyển nguồn chết giữa đường vì thiếu lớp chứ không vì lỗi thật. */
require_once $goc . '/wordpress/vhcp-ghe/includes/class-vhg-db.php';
require_once $goc . '/wordpress/vhcp-ghe/includes/class-vhg-auth.php';
t( 'dựng cảnh: có plugin ghế trên site thì cột mới có nghĩa', VHCC_DayGhe::co_he_ghe() );

delete_option( VHCC_DayGhe::O_SO );
delete_option( VHCC_DayGhe::O_NGUON );
t( 'cột ghế cố ý KHÔNG nằm trong sổ trang của VHCC_Cong',
	! isset( VHCC_Cong::SO[ VHCC_DayGhe::COT ] ), VHCC_DayGhe::COT );

$g_ad = array( 'ma_nv' => 'GH_AD', 'role' => 'Admin' );
$g_kt = array( 'ma_nv' => 'GH_KT', 'role' => 'Kế toán' );

/* Dựng một người có PIN chấm công — PIN nằm ở bảng `phan_quyen`, không ở `nhan_vien`. */
vhcc_bo_phan( 'GHE_CS', 'Khu vui chơi' );
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHNV01', 'ho_ten' => 'Trần Ghế Một',
	'cua_hang' => 'GHE_CS', 'vai_tro' => 'Cửa hàng trưởng' ) );
$wpdb->insert( VHCC_DB::t( 'phan_quyen' ), array( 'pin' => '778899',
	'ho_ten' => 'Trần Ghế Một', 'vai_tro' => 'Cửa hàng trưởng',
	'cua_hang' => 'GHE_CS', 'ma_cc_online' => 'GHNV01', 'coso_cc_online' => 'GHE_CS' ) );

/* 🔴 CẢNH THẬT CỦA ANH THẮNG: PIN CẤP Ở MÀN HỒ SƠ, TỨC `nhan_vien.pin_dang_nhap`.
   28/08/2026, ngay lần đầu dùng cột này: *"Anh thấy lưu mà bên Posh chưa qua"* — kèm ảnh một
   hồ sơ vừa đổi PIN xong mà cột Ghế vẫn nằm nguyên ở «Gỡ». Bản đầu tra `phan_quyen`, là sổ cũ
   của app Apps Script — trên site đang chạy nó rỗng, hoặc có hàng mà `ma_cc_online` chưa ai
   điền. Dựng cảnh chỉ bằng `phan_quyen` là dựng đúng cái đường lui, và cả khối thử xanh trong
   khi đường CHÍNH chưa ai đi qua. */
/* ⚠️ `luu_ho_so()` KHÔNG ghi `vai_tro` — danh sách trắng của nó cố ý không có ô ấy, vì đổi vai
   là việc của `dat_vai_tro()` (có chốt bậc riêng). Dựng cảnh bằng `luu_ho_so` rồi tin là vai
   đã đổi thì phép thử canh một thứ chưa hề được đặt. */
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHNV10', 'ho_ten' => 'Trần Ghế Mười',
	'cua_hang' => 'GHE_CS', 'pin_dang_nhap' => '445566' ) );
VHCC_NhanSu::dat_vai_tro( $g_ad, 'GHNV10', 'Quản lý' );
$g_kq = VHCC_DayGhe::dat( $g_ad, 'GHNV10', 'mo' );
t( '🔴 PIN cấp ở màn hồ sơ thì đẩy được — không cần sổ phan_quyen', ! empty( $g_kq['ok'] ), $g_kq );
$g_m10 = null;
foreach ( VHCC_DayGhe::so() as $g_x ) { if ( 'GHNV10' === $g_x['maNV'] ) { $g_m10 = $g_x; } }
teq( 'và chép đúng PIN của hồ sơ', '445566', (string) $g_m10['pin'] );
teq( 'kèm vai trò của hồ sơ', 'Quản lý', (string) $g_m10['vaiTro'] );

/* ⚠️ HỒ SƠ THẮNG SỔ CŨ. Đảo thứ tự là ngày anh đổi PIN ở màn hồ sơ, hệ ghế vẫn nhận PIN cũ
   trong sổ Apps Script — hai bên lệch nhau mà không có gì báo, và người ta gõ PIN mới thì
   không vào được. */
$wpdb->insert( VHCC_DB::t( 'phan_quyen' ), array( 'pin' => '999000',
	'ho_ten' => 'Tên Cũ Trong Sổ Apps Script', 'vai_tro' => 'Nhân viên',
	'cua_hang' => 'CS_CU', 'ma_cc_online' => 'GHNV10', 'coso_cc_online' => 'CS_CU' ) );
VHCC_DayGhe::dat( $g_ad, 'GHNV10', 'mo' );
foreach ( VHCC_DayGhe::so() as $g_x ) { if ( 'GHNV10' === $g_x['maNV'] ) { $g_m10 = $g_x; } }
teq( '🔴 hồ sơ THẮNG sổ Apps Script cũ khi cả hai đều có PIN', '445566', (string) $g_m10['pin'] );
teq( 'và tên cũng lấy từ hồ sơ', 'Trần Ghế Mười', (string) $g_m10['ten'] );

/* ⚠️ VÀ PHẢI THỬ CẢ LÚC SỔ CŨ THẬT SỰ ĐƯỢC ĐỌC. Sổ cũ chỉ được tra khi hồ sơ còn ô TRỐNG; hồ
   sơ đầy đủ thì nhánh ấy không chạy, nên vết phá "sổ cũ đè lên hồ sơ" vẫn xanh vì lý do sai.
   Dựng người CÓ PIN mà CHƯA gán cơ sở — cảnh có thật, và là cảnh duy nhất canh được chuyện
   "bù ô trống" không biến thành "ghi đè". */
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHNV12', 'ho_ten' => 'Trần Ghế Mười Hai',
	'cua_hang' => '', 'pin_dang_nhap' => '778800' ) );
$wpdb->insert( VHCC_DB::t( 'phan_quyen' ), array( 'pin' => '000111',
	'ho_ten' => 'Tên Cũ', 'vai_tro' => 'Nhân viên',
	'cua_hang' => 'CS_TRONG_SO_CU', 'ma_cc_online' => 'GHNV12', 'coso_cc_online' => 'CS_TRONG_SO_CU' ) );
VHCC_DayGhe::dat( $g_ad, 'GHNV12', 'mo' );
$g_m12 = null;
foreach ( VHCC_DayGhe::so() as $g_x ) { if ( 'GHNV12' === $g_x['maNV'] ) { $g_m12 = $g_x; } }
teq( '🔴 sổ cũ chỉ BÙ ô trống, KHÔNG đè PIN của hồ sơ', '778800', (string) $g_m12['pin'] );
teq( 'nhưng ô cơ sở còn trống thì bù từ sổ cũ', 'CS_TRONG_SO_CU', (string) $g_m12['coso'] );
teq( 'và tên vẫn của hồ sơ', 'Trần Ghế Mười Hai', (string) $g_m12['ten'] );
VHCC_DayGhe::dat( $g_ad, 'GHNV12', '' );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'phan_quyen' ) . " WHERE ma_cc_online = 'GHNV12'" );

/* 🔴 RỬA ĐUÔI ".0" CỦA BẢNG TÍNH. Google Sheets coi PIN là SỐ nên `571394` xuất ra thành
   "571394.0" — tám KÝ TỰ chứ không phải tám CHỮ SỐ, nên trượt luật 4–8 chữ số của
   `VHG_Auth::login()` ngay dòng đầu. Đúng lỗi đã khoá cửa toàn bộ người dùng trang chấm công
   ngày 22/08/2026 — đẩy nguyên đuôi sang là dựng lại đúng cái bẫy ấy ở hệ ghế. */
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHNV11', 'ho_ten' => 'Trần Ghế Mười Một',
	'cua_hang' => 'GHE_CS', 'vai_tro' => 'Nhân viên', 'pin_dang_nhap' => '571394.0' ) );
VHCC_DayGhe::dat( $g_ad, 'GHNV11', 'mo' );
$g_m11 = null;
foreach ( VHCC_DayGhe::so() as $g_x ) { if ( 'GHNV11' === $g_x['maNV'] ) { $g_m11 = $g_x; } }
teq( '🔴 rửa sạch đuôi ".0" trước khi chép sang', '571394', (string) $g_m11['pin'] );
t( 'và PIN chép sang đăng nhập được ở hệ ghế (đúng 4–8 chữ số)',
	(bool) preg_match( '/^\d{4,8}$/', (string) $g_m11['pin'] ), $g_m11 );
VHCC_DayGhe::dat( $g_ad, 'GHNV10', '' );
VHCC_DayGhe::dat( $g_ad, 'GHNV11', '' );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'phan_quyen' ) . " WHERE ma_cc_online = 'GHNV10'" );

teq( 'chưa đẩy thì ô để trống', '', VHCC_DayGhe::o( 'GHNV01' ) );
$g_kq = VHCC_DayGhe::dat( $g_ad, 'GHNV01', 'mo' );
t( 'Admin đẩy được', ! empty( $g_kq['ok'] ), $g_kq );
teq( 'và ô thành «đã đẩy»', 'mo', VHCC_DayGhe::o( 'GHNV01' ) );

$g_so = VHCC_DayGhe::so();
teq( 'sổ ghế có đúng một hàng', 1, count( $g_so ) );
teq( '🔴 chép đúng PIN chấm công sang — anh Thắng chọn dùng chung một PIN',
	'778899', (string) $g_so[0]['pin'] );
teq( 'kèm họ tên', 'Trần Ghế Một', (string) $g_so[0]['ten'] );
teq( 'kèm cơ sở', 'GHE_CS', (string) $g_so[0]['coso'] );
/* 🔴 SỢI DÂY NỐI VỀ SỔ NHÂN SỰ. Thiếu `maNV` thì "gỡ người này ra" phải dò theo họ tên, mà hai
   người trùng tên là chuyện có thật trong 400 nhân sự. */
teq( '🔴 giữ mã NV làm sợi dây nối về sổ nhân sự', 'GHNV01', (string) $g_so[0]['maNV'] );

/* ⚠️ HAI HỆ HAI THANG VAI. Cửa hàng trưởng bên chấm công -> đúng vai ấy bên ghế. */
teq( 'vai trò dịch đúng sang thang của hệ ghế', 'Cửa hàng trưởng', (string) $g_so[0]['vaiTro'] );
teq( 'Admin -> Admin', 'Admin', VHCC_DayGhe::vai_ghe( 'Admin' ) );
teq( 'Quản lý -> Quản lý', 'Quản lý', VHCC_DayGhe::vai_ghe( 'Quản lý' ) );
teq( 'Kế toán -> Kế toán cá nhân', 'Kế toán cá nhân', VHCC_DayGhe::vai_ghe( 'Kế toán' ) );
/* 🔴 KHÔNG ĐOÁN RỘNG KHI KHÔNG KHỚP. Vai lạ rơi về vai HẸP NHẤT bên ghế — đoán rộng ra là trao
   quyền xem tiền cả chuỗi cho một người chỉ vì gõ sai một chữ trong ô vai trò. */
teq( '🔴 vai lạ rơi về vai HẸP NHẤT, không đoán rộng', 'Nhân viên',
	VHCC_DayGhe::vai_ghe( 'Một vai chưa ai nghe bao giờ' ) );
/* Và 'Hotline' bên ghế không có đối ứng bên chấm công — không bao giờ đẩy ra vai đó. */
$g_hot = array();
foreach ( array( 'Admin', 'Quản lý', 'Kế toán', 'Cửa hàng trưởng', 'Nhân viên', 'Lạ hoắc' ) as $g_v ) {
	$g_hot[] = VHCC_DayGhe::vai_ghe( $g_v );
}
t( '🔴 không bao giờ đẩy ai ra vai Hotline — vai ấy khai tay bên hệ ghế',
	! in_array( 'Hotline', $g_hot, true ), $g_hot );

/* 🔴 PHÉP THỬ CANH QUAN HỆ HAI BẬC. `vai_ghe()` có một đường lui cho bậc lạ, nhưng hôm nay
   `VHCC_Vai::ma()` luôn trả về đúng một trong năm bậc đã khai — nên đường lui ấy KHÔNG BAO GIỜ
   chạy, và vết phá "đổi đường lui thành Quản lý" vẫn xanh. Đường lui phải GIỮ (nó che một hàm
   ở lớp KHÁC, ngày mai `VHCC_Vai` thêm bậc thứ sáu là nó cứu), nhưng phải có thứ canh đúng cái
   quan hệ ấy: mọi bậc `ma()` trả ra đều phải có tên bên hệ ghế. */
foreach ( VHCC_Vai::TEN as $g_bac => $g_ten_vai ) {
	$g_ra = VHCC_DayGhe::vai_ghe( $g_ten_vai );
	t( 'bậc "' . $g_ten_vai . '" có tên tương ứng bên hệ ghế',
		in_array( $g_ra, VHG_Auth::VAI_TRO_TAT_CA, true ), $g_ra );
	/* ⚠️ VÀ KHÔNG ĐƯỢC RƠI XUỐNG ĐƯỜNG LUI. Rơi xuống nghĩa là bậc ấy chưa được khai trong
	   bảng ánh xạ — người mang vai đó bị hạ xuống Nhân viên mà không có gì báo. */
	if ( VHCC_Vai::NV !== $g_bac ) {
		t( '🔴 và KHÔNG rơi xuống đường lui "Nhân viên"', 'Nhân viên' !== $g_ra, $g_ten_vai . ' -> ' . $g_ra );
	}
}

/* ⚠️ ĐẨY LẠI = CẬP NHẬT, KHÔNG ĐẺ HÀNG THỨ HAI. Đổi vai rồi đẩy lại là chuyện thường; đẻ thêm
   hàng thì bên ghế có hai người trùng tên, và cái nào thắng lúc đăng nhập thì tuỳ thứ tự đọc. */
$wpdb->update( VHCC_DB::t( 'phan_quyen' ), array( 'vai_tro' => 'Quản lý' ),
	array( 'ma_cc_online' => 'GHNV01' ) );
VHCC_DayGhe::dat( $g_ad, 'GHNV01', 'mo' );
$g_so = VHCC_DayGhe::so();
teq( '🔴 đẩy lại KHÔNG đẻ hàng thứ hai', 1, count( $g_so ) );
teq( 'mà cập nhật vai mới', 'Quản lý', (string) $g_so[0]['vaiTro'] );

/* Gỡ ra. */
VHCC_DayGhe::dat( $g_ad, 'GHNV01', '' );
teq( 'gỡ thì sổ ghế rỗng lại', 0, count( VHCC_DayGhe::so() ) );
teq( 'và ô trở về trống', '', VHCC_DayGhe::o( 'GHNV01' ) );

/* 🔴 CHƯA CÓ PIN THÌ KHÔNG ĐẨY ĐƯỢC — VÀ PHẢI NÓI RA ĐÚNG LÝ DO. Lặng lẽ bỏ qua thì người đi
   khai tưởng mình bấm hụt, bấm lại mười lần vẫn thế. */
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHNV02', 'ho_ten' => 'Trần Ghế Hai',
	'cua_hang' => 'GHE_CS', 'vai_tro' => 'Nhân viên' ) );
$g_kq = VHCC_DayGhe::dat( $g_ad, 'GHNV02', 'mo' );
t( '🔴 chưa có PIN chấm công thì chối', empty( $g_kq['ok'] ), $g_kq );
/* ⚠️ HAI CẢNH KHÁC NHAU, PHẢI THỬ CẢ HAI: người CHƯA CÓ hàng trong sổ tài khoản, và người CÓ
   hàng nhưng ô PIN còn TRỐNG. Chỉ thử cảnh đầu thì chốt "PIN rỗng" thành mã không ai canh —
   bỏ nó đi vẫn xanh, mà bỏ nó là đẩy sang một người không đăng nhập nổi. */
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHNV03', 'ho_ten' => 'Trần Ghế Ba',
	'cua_hang' => 'GHE_CS', 'vai_tro' => 'Nhân viên' ) );
$wpdb->insert( VHCC_DB::t( 'phan_quyen' ), array( 'pin' => '',
	'ho_ten' => 'Trần Ghế Ba', 'vai_tro' => 'Nhân viên',
	'cua_hang' => 'GHE_CS', 'ma_cc_online' => 'GHNV03', 'coso_cc_online' => 'GHE_CS' ) );
$g_kq = VHCC_DayGhe::dat( $g_ad, 'GHNV03', 'mo' );
t( '🔴 có hàng tài khoản nhưng ô PIN còn TRỐNG: cũng chối', empty( $g_kq['ok'] ), $g_kq );
t( 'và nói rõ vì sao, kèm chỗ đi cấp PIN',
	strpos( (string) $g_kq['error'], 'chưa có PIN' ) !== false
	&& strpos( (string) $g_kq['error'], 'Hồ sơ' ) !== false, $g_kq );

/* 🔴 QUYỀN ĐẨY CAO HƠN QUYỀN KHAI BA CỘT KIA. Ba cột kia mở đường vào mấy màn xem giờ công;
   cột này mở đường vào màn có NGĂN TIỀN — và vì PIN dùng chung, đẩy nhầm một người là trao cho
   họ chìa khoá mà chính họ cũng không biết mình đang cầm. */
$g_kq = VHCC_DayGhe::dat( $g_kt, 'GHNV01', 'mo' );
t( '🔴 Kế toán khai được ba cột kia nhưng KHÔNG đẩy được sang hệ ghế', empty( $g_kq['ok'] ), $g_kq );
t( 'dựng cảnh: chính Kế toán ấy VẪN khai được cột thường',
	! empty( VHCC_Cong::dat( $g_kt, 'GHNV01', 'tram', 'khoa' )['ok'] ) );
VHCC_Cong::dat( $g_kt, 'GHNV01', 'tram', '' );

/* ---- Lưu cả cột một lượt: gom lỗi lại rồi trả hết ---- */
/* ⚠️ Anh Thắng tích 20 người rồi bấm Lưu; dừng ở người đầu tiên thiếu PIN là 19 người kia im
   lặng không đi đâu cả, mà màn hình chỉ kể một cái tên. */
delete_option( VHCC_DayGhe::O_SO );
/* ⚠️ ĐỂ NGƯỜI THIẾU PIN ĐỨNG TRƯỚC. Xếp họ đứng sau thì `break` và `continue` cho ra kết quả
   y hệt nhau, và vết phá "dừng ở người đầu tiên lỗi" vẫn xanh. */
$g_kq = VHCC_DayGhe::luu_nhieu( $g_ad, array( 'GHNV02' => 'mo', 'GHNV01' => 'mo' ) );
teq( '🔴 người có PIN vẫn đi, không dừng vì người kia thiếu PIN', 1, (int) $g_kq['doi'] );
teq( 'và lỗi của người thiếu PIN vẫn được kể ra', 1, count( (array) $g_kq['loi'] ) );

/* ---- NGUỒN NGƯỜI DÙNG CỦA HỆ GHẾ ---- */
/* 🔴 ĐẨY VÀO SỔ RIÊNG TRONG KHI HỆ GHẾ ĐANG ĐỌC SỔ CHUNG = ĐẨY VÀO HƯ KHÔNG. */
delete_option( VHCC_DayGhe::O_NGUON );
t( 'mặc định hệ ghế đọc SỔ CHUNG, nên đẩy chưa ăn', ! VHCC_DayGhe::nguon_dung() );
update_option( VHCC_DayGhe::O_NGUON, 'rieng' );
t( 'đổi sang sổ riêng thì đẩy mới ăn', VHCC_DayGhe::nguon_dung() );

/* 🔴 CHÉP TRƯỚC, ĐỔI SAU. Hệ ghế đang đọc sổ chung và trong đó có người đang dùng thật. Đổi cờ
   trần là ngay khoảnh khắc ấy KHÔNG AI vào được /ghe — kể cả người vừa bấm nút. Tự khoá mình
   ra ngoài một màn có doanh thu, giữa giờ làm. */
delete_option( VHCC_DayGhe::O_NGUON );
update_option( VHCC_DayGhe::O_SO, array() );
update_option( 'vhg_nguon_nguoidung_canh_thu', 1 );   // chỉ để nhớ đây là cảnh dựng tay
$g_kq = VHCC_DayGhe::chuyen_sang_rieng( $g_ad );
t( 'chuyển nguồn được', ! empty( $g_kq['ok'] ), $g_kq );
t( '🔴 và chuyển XONG thì hệ ghế đọc sổ riêng', VHCC_DayGhe::nguon_dung() );
/* Gọi lại lần nữa: không được chép chồng thêm lần thứ hai. */
$g_kq2 = VHCC_DayGhe::chuyen_sang_rieng( $g_ad );
t( 'gọi lại lần hai thì nói thẳng là vốn đã dùng sổ riêng',
	! empty( $g_kq2['ok'] ) && isset( $g_kq2['note'] ), $g_kq2 );
/* Kế toán không được đụng vào nguồn của một màn có doanh thu. */
$g_kq3 = VHCC_DayGhe::chuyen_sang_rieng( $g_kt );
t( '🔴 Kế toán KHÔNG đổi được nguồn người dùng của hệ ghế', empty( $g_kq3['ok'] ), $g_kq3 );

/* 🔴 CHÉP TRƯỚC, ĐỔI CỜ SAU — CANH BẰNG CHÍNH THỨ TỰ TRONG MÃ. Dựng cảnh thật cho chuyện này
   đòi một bảng `vhcp_cfg` có người trong đó; mà bất biến cần canh chỉ là THỨ TỰ HAI DÒNG, nên
   soi thẳng vào đấy trung thực hơn là dựng nửa vời rồi tưởng mình đã thử.
   Đảo thứ tự là: ngay khoảnh khắc đổi cờ, sổ riêng còn rỗng và KHÔNG AI vào được /ghe — kể cả
   người vừa bấm nút. Tự khoá mình ra ngoài một màn có doanh thu, giữa giờ làm. */
$g_ma = file_get_contents( $goc . '/wordpress/vhcp-cham-cong/includes/class-vhcc-day-ghe.php' );
$g_i_so   = strpos( $g_ma, "update_option( self::O_SO, \$so, false );" );
$g_i_nguon = strpos( $g_ma, "update_option( self::O_NGUON, 'rieng', false );" );
t( 'dựng cảnh: tìm thấy cả hai dòng ghi', false !== $g_i_so && false !== $g_i_nguon );
t( '🔴 chép người sang sổ riêng TRƯỚC, rồi mới đổi cờ nguồn',
	$g_i_so < $g_i_nguon, array( $g_i_so, $g_i_nguon ) );
delete_option( 'vhg_nguon_nguoidung_canh_thu' );

/* ---- CỘT THỨ TƯ TRÊN MÀN HÌNH ---- */
update_option( VHCC_DayGhe::O_NGUON, 'rieng' );
$g_tok = VHCC_Auth::phat_token( 'Anh Quản Trị', 'Admin', '', 'GH_AD' );
$g_h   = vhcc_hr_ns( $g_tok );
/* ⚠️ SOI CHUỖI RIÊNG CỦA ĐẦU CỘT, ĐỪNG SOI TÊN TRẦN. Chữ "Ghế massage" còn nằm trong khối
   "những trang không khai được" ở cuối trang — khối ấy hiện cho MỌI người, kể cả người không
   có quyền đẩy. Soi tên trần thì phép thử "Kế toán không thấy cột" bắt nhầm chuỗi ở khối kia
   và đỏ oan; mà vết phá đúng chỗ thì lại xanh. Đã vấp đúng vậy. */
t( '🔴 màn nhân sự có cột Ghế massage',
	strpos( $g_h, 'class="tr-doc">Ghế massage' ) !== false, $g_h );
/* HAI nút, không phải ba — bên ghế không có khái niệm "theo vai". */
t( 'ô cột ghế chỉ có Đẩy / Gỡ, không có «theo vai»',
	strpos( $g_h, 'Đẩy ✓' ) !== false && strpos( $g_h, 'name="o[GHNV01][ghe]"' ) !== false, $g_h );
/* ⚠️ Nút áp cả cột cũng phải có, kẻo đẩy 200 người là 200 lần bấm. */
t( 'có nút áp cả cột cho hệ ghế', strpos( $g_h, 'value="ghe|mo"' ) !== false, $g_h );

/* 🔴 KẾ TOÁN KHÔNG ĐƯỢC THẤY CỘT ẤY. Vẽ một cột mà người xem bấm vào là bị chối thì tệ hơn
   không vẽ — họ bấm, thấy câu chối, và tưởng hệ thống hỏng. */
$g_tok_kt = VHCC_Auth::phat_token( 'Chị Kế Toán', 'Kế toán', '', 'GH_KT' );
$g_h_kt   = vhcc_hr_ns( $g_tok_kt );
t( 'dựng cảnh: Kế toán vẫn vào được màn nhân sự',
	strpos( $g_h_kt, 'Quản lý nhân sự' ) !== false, $g_h_kt );
t( '🔴 nhưng KHÔNG thấy cột Ghế massage',
	strpos( $g_h_kt, 'class="tr-doc">Ghế massage' ) === false
	&& strpos( $g_h_kt, 'value="ghe|mo"' ) === false
	&& strpos( $g_h_kt, '][ghe]"' ) === false, $g_h_kt );

/* Đang đọc sổ chung thì phải cảnh báo TRƯỚC khi bấm, kèm nút chuyển. */
delete_option( VHCC_DayGhe::O_NGUON );
$g_h = vhcc_hr_ns( $g_tok );
t( '🔴 đọc sổ chung thì cảnh báo ngay đầu trang',
	strpos( $g_h, 'đang đọc SỔ CHUNG' ) !== false, $g_h );
t( 'kèm nút chuyển sang sổ riêng',
	strpos( $g_h, 'value="ghe_rieng"' ) !== false, $g_h );
/* ⚠️ Và nói rõ nút ấy CHÉP NGƯỜI TRƯỚC — không thì ai dám bấm giữa giờ làm. */
t( 'và nói rõ nút ấy chép sẵn người đang đăng nhập được sang trước',
	strpos( $g_h, 'chép sẵn' ) !== false, $g_h );
update_option( VHCC_DayGhe::O_NGUON, 'rieng' );
$g_h = vhcc_hr_ns( $g_tok );
t( 'đọc sổ riêng rồi thì thôi cảnh báo', strpos( $g_h, 'đang đọc SỔ CHUNG' ) === false, $g_h );

/* 🔴 KHỐI "NHỮNG TRANG KHÔNG KHAI ĐƯỢC" PHẢI THÔI NÓI NGƯỢC. Bản trước ghi gọn "Ghế massage —
   trang của khách", nên người đọc đi tìm cột Ghế, thấy dòng ấy, rồi tin rằng nó không thể có. */
/* ---- ĐẾM NGƯỜI MANG MỘT VAI: PHẢI CÙNG THƯỚC VỚI `ma()` ------------------------------------
   🔴 `xoa_them()` dùng `dem_nguoi()` để CHẶN xoá một vai còn người dùng — đó là chốt bảo vệ duy
      nhất. Bản trước so `vai_tro = <tên>` thẳng trong SQL, trong khi `ma()` — nơi quyết định
      một người thật sự hưởng quyền gì — nhận diện bằng `khoa_ten()`: bỏ dấu, gộp khoảng trắng.
      Hai thước đo khác nhau cho cùng một câu hỏi, và chỗ lệch rơi đúng vào chốt ấy:
        • `ma()` VẪN tra ra vai      -> người đó đang hưởng quyền, thật
        • `dem_nguoi()` trả 0         -> bảng ghi "chưa ai", nút Bỏ mở toang
        • bấm Bỏ -> họ rơi xuống Nhân viên, IM LẶNG
      Đúng cái chú thích của `xoa_them()` bảo phải tránh. */
VHCC_Vai::dat_them( $g_ad, 'Kế toán MTD', VHCC_Vai::KE_TOAN );
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHDEM1', 'ho_ten' => 'Người Đếm Một',
	'cua_hang' => 'GHE_CS' ) );
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Kế toán MTD' ),
	array( 'ma_nv' => 'GHDEM1' ) );
teq( 'dựng cảnh: viết y hệt thì đếm được', 1, VHCC_Vai::dem_nguoi( 'Kế toán MTD' ) );

/* Viết KHÔNG DẤU — `ma()` vẫn tra ra vai ấy, nên `dem_nguoi()` cũng phải thấy. */
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Ke toan MTD' ),
	array( 'ma_nv' => 'GHDEM1' ) );
teq( 'dựng cảnh: `ma()` vẫn nhận ra vai khi hồ sơ viết KHÔNG DẤU',
	VHCC_Vai::KE_TOAN, VHCC_Vai::ma( 'Ke toan MTD' ) );
teq( '🔴 nên `dem_nguoi()` cũng phải đếm được — cùng một thước', 1,
	VHCC_Vai::dem_nguoi( 'Kế toán MTD' ) );

/* Thừa khoảng trắng cũng vậy. */
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Kế  toán   MTD ' ),
	array( 'ma_nv' => 'GHDEM1' ) );
teq( '🔴 thừa/lặp khoảng trắng cũng đếm được', 1, VHCC_Vai::dem_nguoi( 'Kế toán MTD' ) );

/* 🔴 VÀ CHỐT XOÁ PHẢI CHẶN THẬT. Đây mới là chỗ con số ấy có giá. */
$g_kq = VHCC_Vai::xoa_them( $g_ad, 'Kế toán MTD' );
t( '🔴 còn người mang vai (viết lệch) thì KHÔNG xoá được vai',
	empty( $g_kq['ok'] ), $g_kq );
t( 'và câu chối nói rõ còn bao nhiêu người',
	strpos( (string) $g_kq['error'], 'Còn 1 người' ) !== false, $g_kq );

/* Đổi vai cho họ rồi thì xoá được. */
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Nhân viên' ),
	array( 'ma_nv' => 'GHDEM1' ) );
teq( 'đổi vai cho họ thì thôi đếm', 0, VHCC_Vai::dem_nguoi( 'Kế toán MTD' ) );
t( 'và lúc ấy xoá được', ! empty( VHCC_Vai::xoa_them( $g_ad, 'Kế toán MTD' )['ok'] ) );
/* ⚠️ Vai không ai mang mà cũng bị tính là "có người" thì không xoá nổi vai nào — đếm quá tay
   cũng là hỏng, chỉ hỏng theo chiều kia. */
teq( 'một vai chẳng ai mang thì đếm 0', 0, VHCC_Vai::dem_nguoi( 'Vai Chẳng Ai Mang' ) );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'nhan_vien' ) . " WHERE ma_nv = 'GHDEM1'" );

/* ---- VAI SÓT TỪ DỮ LIỆU CŨ ------------------------------------------------------------------
   🔴 Anh Thắng 28/08/2026, ảnh màn nhân sự sau một lần bấm Lưu bảng:
        Đã lưu 2 ô quyền vào trang.
        MNKT4CTY0001: Vai trò "Kế Toán MTD" không có trong hệ.
        Hệ ghế: đã đẩy/gỡ 1 người.
   Anh không hề định đổi vai ai. Hồ sơ ấy ĐANG mang chuỗi "Kế Toán MTD" — vai sót từ dữ liệu
   cũ. Ô xổ cố ý giữ nguyên chuỗi ấy (thả ra là ô nhảy về dòng đầu và một cú Lưu đổi vai cả
   trang), nên nó gửi lên và chốt danh sách trắng chối — mỗi lần bấm Lưu lại một dòng đỏ cho
   một việc KHÔNG xảy ra.
   ⚠️ Dòng đỏ kêu oan là thứ dạy người ta thôi đọc dòng đỏ. */
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHVAI1', 'ho_ten' => 'Người Vai Sót',
	'cua_hang' => 'GHE_CS' ) );
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Kế Toán MTD' ),
	array( 'ma_nv' => 'GHVAI1' ) );
$g_kq = VHCC_NhanSu::dat_vai_tro( $g_ad, 'GHVAI1', 'Kế Toán MTD' );
t( '🔴 gửi lên ĐÚNG vai đang có thì im lặng cho qua, dù vai ấy hệ không công nhận',
	! empty( $g_kq['ok'] ) && empty( $g_kq['doi'] ), $g_kq );
/* Danh sách trắng vẫn giữ nguyên hiệu lực cho mọi lần ĐỔI THẬT. */
$g_kq = VHCC_NhanSu::dat_vai_tro( $g_ad, 'GHVAI1', 'Một Vai Bịa Ra' );
t( '🔴 nhưng đổi sang một chuỗi lạ KHÁC thì vẫn bị chối', empty( $g_kq['ok'] ), $g_kq );
t( 'và câu chối gọi đúng tên chuỗi ấy',
	strpos( (string) $g_kq['error'], 'Một Vai Bịa Ra' ) !== false, $g_kq );
/* Đổi sang vai thật thì chạy bình thường. */
$g_kq = VHCC_NhanSu::dat_vai_tro( $g_ad, 'GHVAI1', 'Quản lý' );
t( 'đổi sang vai có thật thì đổi được', ! empty( $g_kq['ok'] ) && ! empty( $g_kq['doi'] ), $g_kq );
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Kế Toán MTD' ),
	array( 'ma_nv' => 'GHVAI1' ) );

/* 🔴 SỬA DÒNG ĐỎ KÊU OAN XONG THÌ PHẢI NÓI RA CHUYỆN THẬT NẰM SAU NÓ.
   ⚠️ VÀ CHUYỆN THẬT KHÔNG PHẢI "HỌ BỊ HẠ XUỐNG NHÂN VIÊN". Bản nháp của khối cảnh báo viết
      đúng câu ấy và nó SAI: `VHCC_Vai::ma('Kế Toán MTD')` trả KE_TOAN, vì nhánh đoán theo tên
      bắt được tiền tố "ke toan". Người ấy đang ở đúng bậc.
   🔴 Chuyện thật là BẬC ẤY DO ĐOÁN MÀ RA — đúng hôm nay không có nghĩa đúng mai. */
teq( 'dựng cảnh: "Kế Toán MTD" được ĐOÁN thành Kế toán, không rơi xuống Nhân viên',
	VHCC_Vai::KE_TOAN, VHCC_Vai::ma( 'Kế Toán MTD' ) );
teq( 'còn một tên hệ không đoán nổi thì rơi thật', VHCC_Vai::NV, VHCC_Vai::ma( 'Điều Phối POSH' ) );

$g_h = vhcc_hr_ns( $g_tok );
t( '🔴 màn hình kể ra ai đang mang vai hệ phải ĐOÁN',
	strpos( $g_h, 'người mang vai hệ phải ĐOÁN' ) !== false, $g_h );
t( 'kể đúng mã, chuỗi đang ghi, và BẬC hệ đang tính cho họ',
	strpos( $g_h, 'GHVAI1' ) !== false && strpos( $g_h, 'Kế Toán MTD' ) !== false
	&& strpos( $g_h, 'Hệ đang tính là' ) !== false, $g_h );
/* ⚠️ Đoán ra đúng bậc thì ĐỪNG doạ. Người này ở Kế toán — không có gì hỏng ngay. */
t( 'đoán ra đúng bậc thì không kêu "rơi xuống Nhân viên"',
	strpos( $g_h, 'rơi xuống Nhân viên' ) === false, $g_h );
t( 'và chỉ hai đường chữa',
	strpos( $g_h, 'vai tự tạo' ) !== false && strpos( $g_h, 'Vai trò</b> của họ' ) !== false, $g_h );

/* 🔴 CÒN NGƯỜI RƠI XUỐNG NHÂN VIÊN THÌ PHẢI NÓI NẶNG HƠN HẲN. Không ai đặt tên một vai rồi
   mong nó thành Nhân viên — đó gần như chắc là đoán trật, và họ đang bị hạ quyền thật. */
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHVAI2', 'ho_ten' => 'Người Rơi Bậc',
	'cua_hang' => 'GHE_CS' ) );
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Điều Phối POSH' ),
	array( 'ma_nv' => 'GHVAI2' ) );
$g_h = vhcc_hr_ns( $g_tok );
t( '🔴 người rơi xuống Nhân viên thì kêu hẳn lên',
	strpos( $g_h, 'rơi xuống Nhân viên' ) !== false, $g_h );
t( 'và nói rõ vì sao đó gần như chắc là đoán trật',
	strpos( $g_h, 'gần như chắc là đoán trật' ) !== false, $g_h );
/* ⚠️ Có người rơi bậc thì khối phải MỞ SẴN — thứ duy nhất nói ra chuyện ấy không được nằm sau
   một cú bấm. */
t( 'và khối mở sẵn, không gập lại',
	strpos( $g_h, '<details open><summary><b>2 người mang vai hệ phải ĐOÁN' ) !== false, $g_h );

/* Khai chuỗi ấy thành vai tự tạo thì người ấy thôi nằm trong danh sách. */
/* ⚠️ `dat_them()` nhận vai gốc bằng KHOÁ BẬC (`VHCC_Vai::QL`), không phải tên hiển thị. */
$g_kq = VHCC_Vai::dat_them( $g_ad, 'Điều Phối POSH', VHCC_Vai::QL );
t( 'dựng cảnh: khai được vai tự tạo', ! empty( $g_kq['ok'] ), $g_kq );
$g_h = vhcc_hr_ns( $g_tok );
t( '🔴 khai thành vai tự tạo rồi thì người ấy thôi nằm trong danh sách',
	strpos( $g_h, '1 người mang vai hệ phải ĐOÁN' ) !== false, $g_h );
t( 'và thôi kêu rơi bậc', strpos( $g_h, 'rơi xuống Nhân viên' ) === false, $g_h );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'nhan_vien' ) . " WHERE ma_nv IN ('GHVAI1','GHVAI2')" );

/* ---- BẢN SAO BÊN GHẾ PHẢI THEO BẢN GỐC -----------------------------------------------------
   🔴 Bản sao chỉ đúng vào đúng khoảnh khắc đẩy. Sau đó hồ sơ còn sống tiếp: đổi PIN, đổi vai,
      chuyển cơ sở. Không đồng bộ thì mỗi lần sửa là hai bên lệch thêm một chút, và không có gì
      báo — cho tới ngày người ấy đứng ở quầy, gõ PIN mới, và cửa không mở. */
update_option( VHCC_DayGhe::O_NGUON, 'rieng' );
delete_option( VHCC_DayGhe::O_SO );
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHNV20', 'ho_ten' => 'Trần Ghế Hai Mươi',
	'cua_hang' => 'GHE_CS', 'pin_dang_nhap' => '111222' ) );
VHCC_DayGhe::dat( $g_ad, 'GHNV20', 'mo' );

/* Người CHƯA đẩy thì đồng bộ không đụng tới — nó không được tự mở đường cho ai. */
t( '🔴 người chưa đẩy sang thì đồng bộ không đụng tới',
	false === VHCC_DayGhe::dong_bo( 'GHNV02' ) && ! VHCC_DayGhe::da_day( 'GHNV02' ) );

/* Đổi PIN qua đúng đường màn hình dùng: nút "Lưu hồ sơ này". */
$_POST = array( 'ma_nv' => 'GHNV20', 'pin_dang_nhap' => '333444' );
$g_bao = VHCC_TrangNS::lam_viec( 'sua_nhanh', $g_ad );
$_POST = array();
$g_m20 = null;
foreach ( VHCC_DayGhe::so() as $g_x ) { if ( 'GHNV20' === $g_x['maNV'] ) { $g_m20 = $g_x; } }
teq( '🔴 đổi PIN ở màn hồ sơ thì bên ghế đổi theo', '333444', (string) $g_m20['pin'] );
t( 'và màn hình nói ra là hệ ghế đã cập nhật',
	strpos( (string) wp_json_encode( $g_bao ), 'Hệ ghế đã cập nhật' ) !== false, $g_bao );

/* Đổi vai — qua ĐÚNG đường màn hình dùng (ô Vai trò trên bảng + nút Lưu bảng này). Gọi
   `dong_bo()` bằng tay ở đây thì phép thử canh chính nó, không canh cái móc trong `luu_vai()`. */
/* ⚠️ `viec_luu()` thoát sớm nếu bảng ô RỖNG ("Biểu mẫu không hợp lệ") — nên phải gửi ít nhất
   một ô thật, không thì `luu_vai()` không bao giờ chạy và phép thử canh hụt. */
$_POST = array( 'o' => array( 'GHNV20' => array( 'tram' => '' ) ),
	'vai' => array( 'GHNV20' => 'Quản lý' ) );
VHCC_TrangNS::lam_viec( 'luu_quyen', $g_ad );
$_POST = array();
foreach ( VHCC_DayGhe::so() as $g_x ) { if ( 'GHNV20' === $g_x['maNV'] ) { $g_m20 = $g_x; } }
teq( 'đổi vai thì bên ghế đổi theo', 'Quản lý', (string) $g_m20['vaiTro'] );

/* 🔴 HỒ SƠ MẤT PIN THÌ GỠ LUÔN. Xoá PIN của một người là hành động có chủ ý — thường là chặn
   họ đăng nhập; giữ nguyên bản sao bên ghế là để hở đúng cánh cửa vừa định đóng. */
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'pin_dang_nhap' => '' ),
	array( 'ma_nv' => 'GHNV20' ) );
VHCC_DayGhe::dong_bo( 'GHNV20' );
t( '🔴 hồ sơ bị xoá PIN thì GỠ luôn khỏi hệ ghế, không để lại PIN cũ',
	! VHCC_DayGhe::da_day( 'GHNV20' ), VHCC_DayGhe::so() );

/* ---- HÀNG SỬA NHANH: KHÔNG ĐƯỢC MỞ FORM LỒNG FORM -----------------------------------------
   🔴 Anh Thắng 28/08/2026: *"nút sửa nhanh này nó không lưu được"*.
   Bản trước mở một `<form>` thứ hai ngay trong `<td>`, mà cả bảng đã nằm trong một `<form>`.
   HTML CẤM form lồng form: trình duyệt bỏ thẻ mở bên trong, nhưng khớp thẻ `</form>` đóng của
   nó với form ĐANG mở — tức form của BẢNG. Hàng sửa nhanh chèn ở GIỮA bảng, nên từ chỗ ấy trở
   đi mọi thứ rơi ra ngoài form: nút "Lưu bảng này" ở cuối bảng thành mồ côi.
   ⚠️ HTML sai KHÔNG ném lỗi — nó chỉ lặng lẽ cho ra một cây DOM khác cái mình viết. Nên phép
      thử phải canh CHÍNH con số: cả trang có đúng bao nhiêu form, và mở/đóng có cân không. */
$g_h = vhcc_hr_ns( $g_tok, array( 'sua_o' => 'GHNV01', 'ncs' => 'GHE_CS' ) );
t( 'dựng cảnh: hàng sửa nhanh đang mở', strpos( $g_h, 'Sửa nhanh GHNV01' ) !== false, $g_h );
teq( '🔴 mở hàng sửa nhanh KHÔNG đẻ thêm form nào',
	substr_count( $g_h, '<form' ), substr_count( $g_h, '</form>' ) );
$g_h2 = vhcc_hr_ns( $g_tok, array( 'ncs' => 'GHE_CS' ) );
teq( '🔴 và số form ĐÚNG BẰNG lúc hàng ấy đóng',
	substr_count( $g_h2, '<form' ), substr_count( $g_h, '<form' ) );
/* Ô của hàng sửa nhanh phải nằm TRONG form của bảng — tức là trước thẻ `</form>` của nó. */
$g_i_ma  = strpos( $g_h, 'name="ma_nv"' );
$g_i_luu = strpos( $g_h, 'value="luu_quyen"' );
t( '🔴 ô sửa nhanh nằm TRƯỚC nút "Lưu bảng này", tức cùng một form',
	false !== $g_i_ma && false !== $g_i_luu && $g_i_ma < $g_i_luu, array( $g_i_ma, $g_i_luu ) );
/* Và `ky` không được khai lại lần hai trong cùng form — hai giá trị lệch nhau là chối phiên. */
teq( 'không khai lại ô ký lần hai trong hàng sửa nhanh',
	substr_count( $g_h2, 'name="ky"' ), substr_count( $g_h, 'name="ky"' ) );

/* 🔴 BẤM "LƯU HỒ SƠ NÀY" PHẢI LƯU LUÔN Ô QUYỀN ĐÃ TÍCH. Hàng sửa nhanh nằm TRONG form của
   bảng, nên mọi ô quyền / vai / cơ sở đã tích đều gửi lên cùng lượt. Không lưu chúng là chúng
   mất im lặng, mà màn hình vẫn báo "Đã lưu hồ sơ" nên người bấm tin là xong.
   ⚠️ Bản trước vá bằng một câu nhắc. Nhắc là bắt người ta nhớ, mà cái gì bắt nhớ thì sớm muộn
      có người quên — nhất là khi hai nút nằm cách nhau nửa màn hình. */
update_option( VHCC_DayGhe::O_NGUON, 'rieng' );
delete_option( VHCC_DayGhe::O_SO );
VHCC_NhanSu::luu_ho_so( $g_ad, array( 'ma_nv' => 'GHNV30', 'ho_ten' => 'Người Ba Mươi',
	'cua_hang' => 'GHE_CS', 'pin_dang_nhap' => '556677' ) );
VHCC_Cong::dat( $g_ad, 'GHNV30', 'tram', '' );
$_POST = array(
	'ma_nv'  => 'GHNV30',
	'ho_ten' => 'Người Ba Mươi Đã Sửa',
	'o'      => array( 'GHNV30' => array( 'tram' => 'khoa', 'ghe' => 'mo' ) ),
);
$g_bao = VHCC_TrangNS::lam_viec( 'sua_nhanh', $g_ad );
$_POST = array();
$g_hs30 = VHCC_NhanSu::ho_so( 'GHNV30' );
teq( 'ô hồ sơ vẫn lưu như cũ', 'Người Ba Mươi Đã Sửa', (string) $g_hs30['ho_ten'] );
teq( '🔴 và ô quyền tích cùng lượt KHÔNG mất im lặng', 'khoa', VHCC_Cong::o( 'GHNV30', 'tram' ) );
t( '🔴 cột Ghế tích cùng lượt cũng ăn', VHCC_DayGhe::da_day( 'GHNV30' ), VHCC_DayGhe::so() );
$g_txt = (string) wp_json_encode( $g_bao );
t( 'màn hình kể cả hai việc',
	strpos( $g_txt, 'Đã lưu hồ sơ' ) !== false && strpos( $g_txt, 'ô quyền' ) !== false, $g_bao );
/* ⚠️ Bảng không có gì đổi thì ĐỪNG kèm dòng "chưa lưu gì" — nó nói ngược lại dòng "Đã lưu hồ
   sơ" ngay trên, và người đọc không biết tin dòng nào. */
/* ⚠️ HAI CÁCH "BẢNG KHÔNG ĐỔI GÌ", VÀ `viec_luu()` TRẢ HAI CÂU KHÁC NHAU:
     • không gửi ô nào  -> "Biểu mẫu không hợp lệ."
     • gửi ô ĐÚNG như đang có -> "Không có ô nào đổi — chưa lưu gì."
   Chỉ dựng cảnh đầu thì nhánh lọc câu thứ hai thành mã không ai canh. */
$_POST = array( 'ma_nv' => 'GHNV30', 'ho_ten' => 'Người Ba Mươi Đã Sửa Lần Hai',
	'o' => array( 'GHNV30' => array( 'tram' => VHCC_Cong::o( 'GHNV30', 'tram' ) ) ) );
$g_bao = VHCC_TrangNS::lam_viec( 'sua_nhanh', $g_ad );
$_POST = array();
$g_txt = (string) wp_json_encode( $g_bao );
t( '🔴 gửi ô đúng như đang có: không kèm dòng "chưa lưu gì" nói ngược',
	strpos( $g_txt, 'chưa lưu gì' ) === false && strpos( $g_txt, 'Đã lưu hồ sơ' ) !== false, $g_bao );

$_POST = array( 'ma_nv' => 'GHNV30', 'ho_ten' => 'Người Ba Mươi Đã Sửa Lần Hai' );
$g_bao = VHCC_TrangNS::lam_viec( 'sua_nhanh', $g_ad );
$_POST = array();
$g_txt = (string) wp_json_encode( $g_bao );
t( '🔴 bảng không đổi gì thì không kèm dòng "chưa lưu gì" nói ngược',
	strpos( $g_txt, 'chưa lưu gì' ) === false && strpos( $g_txt, 'Đã lưu hồ sơ' ) !== false, $g_bao );
t( 'và cũng không kèm "Biểu mẫu không hợp lệ"',
	strpos( $g_txt, 'không hợp lệ' ) === false, $g_bao );
VHCC_DayGhe::dat( $g_ad, 'GHNV30', '' );
VHCC_Cong::dat( $g_ad, 'GHNV30', 'tram', '' );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'nhan_vien' ) . " WHERE ma_nv = 'GHNV30'" );

/* ---- ĐƯỜNG LƯU THẬT: BẤM LƯU / BẤM ÁP CẢ CỘT ----------------------------------------------
   🔴 Cột ghế đi CHUNG một biểu mẫu với ba cột kia cho tiện tay người bấm, nhưng bên dưới nó ghi
      sang một sổ khác hẳn. Không tách ra thì `VHCC_Cong::luu_nhieu()` gặp khoá "ghe", thấy nó
      không có trong sổ trang của mình, và BỎ QUA IM LẶNG — màn hình báo "đã lưu" trong khi
      không ai được đẩy đi đâu cả. Phép thử gọi thẳng `lam_viec()` để đi đúng đường ấy. */
update_option( VHCC_DayGhe::O_NGUON, 'rieng' );
delete_option( VHCC_DayGhe::O_SO );
$_POST = array( 'o' => array(
	'GHNV01' => array( 'ghe' => 'mo', 'tram' => 'khoa' ),
) );
$g_bao = VHCC_TrangNS::lam_viec( 'luu_quyen', $g_ad );
$_POST = array();
t( '🔴 bấm Lưu thì người tích cột ghế ĐƯỢC ĐẨY THẬT', VHCC_DayGhe::da_day( 'GHNV01' ),
	VHCC_DayGhe::so() );
t( 'và ô của ba cột kia trong cùng lượt vẫn lưu bình thường',
	'khoa' === VHCC_Cong::o( 'GHNV01', 'tram' ), VHCC_Cong::o( 'GHNV01', 'tram' ) );
/* ⚠️ VÀ PHẢI KỂ RA. Đẩy xong mà màn hình không nói gì thì người bấm không biết mình vừa làm gì. */
$g_txt = wp_json_encode( $g_bao );
t( '🔴 và màn hình kể lại việc đẩy', strpos( (string) $g_txt, 'Hệ ghế' ) !== false, $g_bao );
VHCC_Cong::dat( $g_ad, 'GHNV01', 'tram', '' );

/* Bấm Lưu lần nữa với ô ghế bỏ trống = gỡ ra. */
$_POST = array( 'o' => array( 'GHNV01' => array( 'ghe' => '' ) ) );
VHCC_TrangNS::lam_viec( 'luu_quyen', $g_ad );
$_POST = array();
t( 'bỏ tích rồi Lưu thì gỡ khỏi hệ ghế', ! VHCC_DayGhe::da_day( 'GHNV01' ), VHCC_DayGhe::so() );

/* ---- NÚT ÁP CẢ CỘT ---- */
/* ⚠️ Khoá "ghe" KHÔNG có trong sổ trang, nên để nó rơi xuống nhánh `VHCC_Cong::co()` là bị chối
   bằng một câu SAI HẲN ("Không có trang ghe trên site này") trong khi cột ấy đang hiện rành
   rành — người bấm sẽ đi tìm lỗi ở chỗ không có lỗi. */
$_POST = array( 'cot' => 'ghe|mo', 'o' => array(
	'GHNV01' => array( 'ghe' => '' ),
	'GHNV02' => array( 'ghe' => '' ),
) );
$g_bao = VHCC_TrangNS::lam_viec( 'ap_cot', $g_ad );
$_POST = array();
t( '🔴 áp cả cột đẩy được người có PIN', VHCC_DayGhe::da_day( 'GHNV01' ), VHCC_DayGhe::so() );
$g_txt = wp_json_encode( $g_bao );
t( '🔴 và KHÔNG chối bằng câu "không có trang ghe"',
	strpos( (string) $g_txt, 'Không có trang' ) === false, $g_bao );
t( 'người thiếu PIN vẫn được kể ra chứ không nuốt',
	strpos( (string) $g_txt, 'chưa có PIN' ) !== false, $g_bao );

/* Gỡ cả cột. */
$_POST = array( 'cot' => 'ghe|', 'o' => array( 'GHNV01' => array( 'ghe' => 'mo' ) ) );
VHCC_TrangNS::lam_viec( 'ap_cot', $g_ad );
$_POST = array();
t( 'áp cả cột «Gỡ» thì gỡ hết', ! VHCC_DayGhe::da_day( 'GHNV01' ), VHCC_DayGhe::so() );

/* 🔴 KẾ TOÁN BẤM ÁP CẢ CỘT GHẾ THÌ BỊ CHỐI — cửa thật nằm ở lõi, không phải ở chỗ giấu nút. */
$_POST = array( 'cot' => 'ghe|mo', 'o' => array( 'GHNV01' => array( 'ghe' => '' ) ) );
$g_bao = VHCC_TrangNS::lam_viec( 'ap_cot', $g_kt );
$_POST = array();
t( '🔴 Kế toán gọi thẳng đường áp cột ghế vẫn bị chối', ! VHCC_DayGhe::da_day( 'GHNV01' ), VHCC_DayGhe::so() );

t( '🔴 khối "không khai được" tách rõ MÀN KHÁCH khỏi màn quản trị',
	strpos( $g_h, 'Màn khách của Ghế massage' ) !== false, $g_h );
/* ⚠️ Nói "không khai được" thì phải nói luôn CHỖ khai được, không thì người đọc dừng ở nửa
   câu đầu và đi ra. */
t( 'và chỉ sang cột Ghế massage cho màn quản trị',
	strpos( $g_h, '<b>màn quản trị</b> của hệ ghế thì khai được' ) !== false
	&& strpos( $g_h, 'người thật</b> sang sổ người dùng của hệ ghế' ) !== false, $g_h );

/* ---- 60c. NGOẠI LỆ ĐÈ LÊN VAI, CẢ HAI CHIỀU ---- */
$ns_kq = VHCC_Cong::dat( $ns_kt, 'QN2', 'cham_cong', 'khoa' );
t( 'Kế toán khai được ngoại lệ', ! empty( $ns_kq['ok'] ), $ns_kq );
t( '🔴 khoá riêng CHẶN được cả Admin — vai cao không phá được ngoại lệ',
	! VHCC_Cong::duoc_vao( $ns_ad, 'cham_cong' ) );
t( 'và câu chối nói rõ là bị KHOÁ RIÊNG, không đổ cho vai',
	strpos( VHCC_Cong::vi_sao_khong( $ns_ad, 'cham_cong' ), 'khoá riêng' ) !== false,
	VHCC_Cong::vi_sao_khong( $ns_ad, 'cham_cong' ) );
/* Khoá một trang KHÔNG được lây sang trang khác của cùng người. */
t( 'khoá màn quản trị thì trạm chấm công vẫn vào được', VHCC_Cong::duoc_vao( $ns_ad, 'tram' ) );
/* ...và không lây sang NGƯỜI khác. */
t( 'khoá QN2 thì QN1 không bị ảnh hưởng', VHCC_Cong::duoc_vao( $ns_nv, 'cham_cong' ) );

VHCC_Cong::dat( $ns_kt, 'QN1', 'cham_cong', 'mo' );
t( 'mở riêng cho vào dù vai chưa tới', VHCC_Cong::duoc_vao( $ns_nv, 'cham_cong' ) );

/* ---- 60d. BA TRẠNG THÁI, KHÔNG PHẢI HAI: gỡ ngoại lệ phải về được "theo vai" ---- */
teq( 'ô đang là khoa', 'khoa', VHCC_Cong::o( 'QN2', 'cham_cong' ) );
VHCC_Cong::dat( $ns_kt, 'QN2', 'cham_cong', '' );
teq( '🔴 gỡ ngoại lệ thì ô về TRỐNG (theo vai), không kẹt lại ở 0',
	'', VHCC_Cong::o( 'QN2', 'cham_cong' ) );
t( 'và Admin vào lại được', VHCC_Cong::duoc_vao( $ns_ad, 'cham_cong' ) );
$ns_bang = get_option( VHCC_Cong::O );
t( '🔴 gỡ hết ngoại lệ của một người thì XOÁ HẲN người đó khỏi sổ, không để ô rỗng',
	! isset( $ns_bang['QN2'] ), $ns_bang );

/* ---- 60e. CHỐT QUYỀN KHAI ---- */
$ns_kq = VHCC_Cong::dat( $ns_nv, 'QN3', 'tram', 'khoa' );
t( '🔴 Nhân viên KHÔNG khai được quyền vào trang cho người khác', empty( $ns_kq['ok'] ), $ns_kq );
t( 'và sổ không bị đụng vào', '' === VHCC_Cong::o( 'QN3', 'tram' ) );
$ns_kq = VHCC_Cong::dat( $ns_kt, 'QN3', 'mot_trang_khong_co', 'khoa' );
t( 'khai cho một trang không có trên site thì bị chối', empty( $ns_kq['ok'] ), $ns_kq );
$ns_kq = VHCC_Cong::dat( $ns_kt, 'QN3', 'tram', 'nua_mo_nua_khoa' );
t( 'giá trị lạ bị chối, chỉ nhận mo / khoa / trống', empty( $ns_kq['ok'] ), $ns_kq );
$ns_kq = VHCC_Cong::dat( $ns_kt, '', 'tram', 'khoa' );
t( 'thiếu Mã NV thì chối', empty( $ns_kq['ok'] ), $ns_kq );

/* ---- 60f. 🔴 LƯU CẢ BẢNG CHỈ ĐỘNG VÀO NGƯỜI ĐANG HIỆN ----
   Đây là phép thử đắt nhất của cả khối. Màn hình có bộ lọc + phân trang, nên cái POST gửi lên
   luôn là một LÁT CẮT. Viết `update_option( O, $bang )` cho gọn thì lưu trang 1 là xoá sạch
   ngoại lệ của mọi người ở trang 2 trở đi — im lặng, và chỉ lộ ra khi có người kêu "sao tôi
   lại vào được trang đó". */
delete_option( VHCC_Cong::O );
VHCC_Cong::dat( $ns_kt, 'NGOAI_TRANG', 'tram', 'khoa' );      // người ở "trang 2", không gửi lên
$ns_kq = VHCC_Cong::luu_nhieu( $ns_kt, array(
	'QN1' => array( 'cham_cong' => 'mo',  'tram' => '' ),
	'QN2' => array( 'cham_cong' => 'khoa' ),
) );
t( 'lưu cả bảng chạy', ! empty( $ns_kq['ok'] ), $ns_kq );
teq( 'đếm ĐÚNG số ô thật sự đổi (ô để trống mà vốn đã trống thì không tính)', 2, $ns_kq['doi'] );
teq( '🔴 người KHÔNG có trong lát cắt vẫn giữ nguyên ngoại lệ', 'khoa',
	VHCC_Cong::o( 'NGOAI_TRANG', 'tram' ) );
teq( 'ô mở đã vào sổ', 'mo', VHCC_Cong::o( 'QN1', 'cham_cong' ) );
teq( 'ô khoá đã vào sổ', 'khoa', VHCC_Cong::o( 'QN2', 'cham_cong' ) );

/* Lưu lại y nguyên thì KHÔNG đổi ô nào — nếu không thì mỗi lần bấm Lưu đều báo "đã lưu N ô". */
$ns_kq = VHCC_Cong::luu_nhieu( $ns_kt, array( 'QN1' => array( 'cham_cong' => 'mo' ) ) );
teq( 'lưu lại y nguyên thì 0 ô đổi', 0, $ns_kq['doi'] );

/* Trang lạ và giá trị lạ bị BỎ QUA lặng lẽ (biểu mẫu bị sửa tay), không ghi vào sổ. */
$ns_kq = VHCC_Cong::luu_nhieu( $ns_kt, array(
	'QN1' => array( 'trang_ma' => 'khoa', 'tram' => 'xoa_het_di' ) ) );
teq( 'trang lạ + giá trị lạ không ghi được ô nào', 0, $ns_kq['doi'] );
$ns_bang = get_option( VHCC_Cong::O );
t( 'sổ không mọc thêm khoá lạ', ! isset( $ns_bang['QN1']['trang_ma'] ), $ns_bang );

/* Chốt quyền cũng phải có ở đường lưu hàng loạt, không riêng đường lưu một ô. */
$ns_kq = VHCC_Cong::luu_nhieu( $ns_nv, array( 'QN1' => array( 'cham_cong' => 'khoa' ) ) );
t( '🔴 Nhân viên không lưu được cả bảng', empty( $ns_kq['ok'] ), $ns_kq );
teq( 'và sổ giữ nguyên', 'mo', VHCC_Cong::o( 'QN1', 'cham_cong' ) );

/* ---- 60g. DANH SÁCH SOÁT LẠI ---- */
$ns_phang = VHCC_Cong::ngoai_le_phang();
$ns_thay  = array();
foreach ( $ns_phang as $ns_x ) { $ns_thay[ $ns_x['ma_nv'] . '|' . $ns_x['trang'] ] = $ns_x; }
t( 'khối soát thấy ngoại lệ của người ngoài lát cắt', isset( $ns_thay['NGOAI_TRANG|tram'] ) );
t( 'và thấy ngoại lệ vừa lưu', isset( $ns_thay['QN1|cham_cong'] ) );
/* Dòng trỏ vào trang đã gỡ khỏi sổ phải CÒN và bị đánh dấu — lọc đi thì sổ trông sạch trong
   khi vẫn còn rác, mà rác ấy sống lại đúng ngày plugin được cài lại. */
$ns_b2 = get_option( VHCC_Cong::O );
$ns_b2['QN9'] = array( 'mot_trang_da_go' => 'khoa' );
update_option( VHCC_Cong::O, $ns_b2 );
$ns_co = null;
foreach ( VHCC_Cong::ngoai_le_phang() as $ns_x ) {
	if ( 'QN9' === $ns_x['ma_nv'] ) { $ns_co = $ns_x; }
}
t( '🔴 ngoại lệ trỏ vào trang KHÔNG còn cài vẫn hiện ra', null !== $ns_co, $ns_co );
t( 'và bị đánh dấu là trang không còn', $ns_co && false === $ns_co['co'], $ns_co );
delete_option( VHCC_Cong::O );

/* ---- 60h. CHỐT ĐÃ ĐƯỢC NỐI VÀO CỬA VÀO TỪNG TRANG ----
   Khai một cái sổ mà không nơi nào hỏi nó thì màn hình cho tích, tích xong không có gì đổi, và
   người khai tưởng mình đã khoá. Ba trang trong sổ, ba chỗ phải gọi. */
foreach ( array(
	'wordpress/vhcp-cham-cong/includes/class-vhcc-web.php'  => "'cham_cong'",
	'wordpress/vhcp-cham-cong/includes/class-vhcc-tram.php' => "'tram'",
	'wordpress/vhcp-noi-bo/includes/class-vhnb-trang.php'   => "'noi_bo'",
) as $ns_f => $ns_khoa ) {
	$ns_ma = file_get_contents( $goc . '/' . $ns_f );
	t( '🔴 ' . basename( $ns_f ) . ' có gọi VHCC_Cong::duoc_vao(' . $ns_khoa . ')',
		strpos( $ns_ma, 'VHCC_Cong::duoc_vao' ) !== false && strpos( $ns_ma, $ns_khoa ) !== false );
	/* Gác `method_exists` phải nằm CÙNG TỆP với lời gọi — luật kiem-goi-cheo.php. */
	t( basename( $ns_f ) . ' gác method_exists trước khi gọi',
		strpos( $ns_ma, "method_exists( 'VHCC_Cong', 'duoc_vao' )" ) !== false );
}
/* ⚠️ BA PHÉP THỬ TRÊN CHỈ LÀ GREP, VÀ GREP KHÔNG ĐỦ. Bọc lời gọi trong `if ( false && … )` thì
   mã vẫn còn nguyên chữ mà chốt thì không còn — grep xanh, cửa mở toang. Nên mỗi cửa còn phải
   có một phép thử HÀNH VI: khoá một người rồi vẽ trang ra, xem có bị chối thật không.
   Trạm đã có ở 60i; nội bộ có ở `kiem-noi-bo.php`; màn quản trị nằm ngay dưới đây. */
delete_option( VHCC_Cong::O );
/* Dựng thẻ phiên thẳng, không đi qua PIN: PIN của mấy tài khoản mẫu đã bị chính các phép thử ở
   trên sửa đi nhiều lượt, mà phép thử này nói về CỬA VÀO chứ không nói về đăng nhập. */
/**
 * THÂN của lưới cả tháng — từ `<tbody>` ngay sau hàng tiêu đề tới `</tbody>` đầu tiên.
 *
 * 🔴 Soi thứ tự người trên CẢ TRANG là bắt nhầm: mấy khối khác (thiếu ảnh thẻ, cơ sở khác,
 *    chọn người…) cũng in đúng những cái tên ấy, và mỗi khối xếp một kiểu.
 */
function vhcc_than_luoi( $html ) {
	$i = strpos( $html, 'TỔNG</th>' );
	if ( false === $i ) { return ''; }
	$a = strpos( $html, '<tbody>', $i );
	if ( false === $a ) { return ''; }
	$b = strpos( $html, '</tbody>', $a );
	return ( false === $b ) ? substr( $html, $a ) : substr( $html, $a, $b - $a );
}

/** Như `vhcc_web_nhu` nhưng chọn được CƠ SỞ — cần cho các phép thử soi chốt cơ sở. */
