		if ( $post ) { $_POST['ky'] = VHCC_Web::chu_ky( $_COOKIE[ VHCC_Web::COOKIE ] ); }
	}
	ob_start(); VHCC_TrangNS::phuc_vu(); $h = ob_get_clean();
	$_GET = array(); $_POST = array(); $_COOKIE = array();
	return $h;
}

