$nt_h = vhcc_ns( 'Kế toán' );
/* ⚠️ SOI ĐÚNG Ô QUYỀN, ĐỪNG SOI TIỀN TỐ LỚP. Bản đầu kiểm `<select class="o-q` — mà cột Vai
   trò (thêm sau) dùng lớp `o-q-vai`, khớp luôn tiền tố ấy, nên phép thử đỏ oan trong khi ô
   quyền vẫn đúng là radio. Ô quyền nhận ra bằng TÊN TRƯỜNG `o[…]`, không phải bằng tên lớp. */
t( '🔴 ô quyền là radio, không còn ô xổ',
	preg_match( '/<select[^>]*name="o\[/', $nt_h ) === 0, $nt_h );
/* Cột Vai trò thì NGƯỢC LẠI — cố ý là ô xổ: vai có sáu giá trị chứ không phải ba, vẽ sáu nút
   cạnh nhau là mỗi hàng dài thêm một gang tay. Hai kiểu ô khác nhau ở đây là có chủ ý. */
t( 'cột Vai trò là ô xổ và sửa được',
	preg_match( '/<select[^>]*name="vai\[/', $nt_h ) === 1, $nt_h );
t( 'ô quyền dùng radio', strpos( $nt_h, 'type="radio"' ) !== false );
foreach ( array( 'value=""' => 'theo vai', 'value="mo"' => 'mở', 'value="khoa"' => 'khoá' ) as $nt_v => $nt_ten ) {
	t( 'vẫn đủ ba trạng thái — có nút "' . $nt_ten . '"', strpos( $nt_h, $nt_v ) !== false );
}
/* 🔴 Nút đầu phải NÓI RA theo vai là vào được hay không. Chỉ viết "vai" thì cả cột trông giống
   hệt nhau, và người khai không quyết được có cần đặt ngoại lệ hay không — đúng câu hỏi họ mở
   trang này ra để trả lời. */
t( '🔴 nút "theo vai" in ra ✓ hoặc ✕, không chỉ mỗi chữ "vai"',
	strpos( $nt_h, 'vai ✓' ) !== false || strpos( $nt_h, 'vai ✕' ) !== false, $nt_h );

/* ⚠️ `id` phải DUY NHẤT: `<label for=…>` mà trùng id thì bấm ở hàng 40 lại đổi hàng 1 — người
   dùng thấy có gì đó nhảy, nhưng không thấy mình vừa sửa nhầm hồ sơ của ai. */
if ( preg_match_all( '/<input type="radio" id="([^"]+)"/', $nt_h, $nt_m ) ) {
	teq( '🔴 mọi id của nút quyền đều DUY NHẤT trong trang',
		count( $nt_m[1] ), count( array_unique( $nt_m[1] ) ) );
	t( 'và có kha khá nút (bảng đang có người)', count( $nt_m[1] ) >= 3, count( $nt_m[1] ) );
	/* Mỗi <label for=…> phải trỏ tới một id CÓ THẬT — trỏ hụt là bấm vào chữ không ăn gì.
	   ⚠️ Gom id của MỌI ô nhập, không riêng nút radio. Gom mỗi radio thì trang có thêm một khối
	      dùng <select id=…> là phép thử báo hỏng oan — và cái đỏ ấy chẳng nói gì về nhãn cả. */
	$nt_thieu = 0;
	preg_match_all( '/<(?:input|select|textarea)[^>]*\bid="([^"]+)"/', $nt_h, $nt_ido );
	$nt_ids = isset( $nt_ido[1] ) ? $nt_ido[1] : array();
	if ( preg_match_all( '/<label for="([^"]+)"/', $nt_h, $nt_l ) ) {
		foreach ( $nt_l[1] as $nt_id ) { if ( ! in_array( $nt_id, $nt_ids, true ) ) { $nt_thieu++; } }
	}
	teq( 'mọi nhãn đều trỏ tới một ô có thật', 0, $nt_thieu );
} else {
	t( 'dò được nút quyền trong trang', false, $nt_h );
}

/* ---- 60o. NÚT ÁP CẢ CỘT ----
   Đổi ô xổ thành nút mới bớt được MỘT lần bấm mỗi ô; khoá cả một cơ sở cho một trang vẫn là 50
   lần bấm. Nút này làm cả cột trong một lần. */
t( 'đầu mỗi cột có nút áp cả cột', strpos( $nt_h, 'name="cot" value="tram|khoa"' ) !== false, $nt_h );
t( 'và nút đưa cả cột về theo vai', strpos( $nt_h, 'name="cot" value="tram|"' ) !== false );

/* 🔴 NÚT CỘT KHÔNG GỬI `viec`. Một biểu mẫu chỉ gửi tên/giá trị của ĐÚNG cái nút vừa bấm — bấm
   nút cột thì `viec` (của nút Lưu) không có mặt. Chỉ nghe mỗi `viec` là nút cột bấm xong không
   xảy ra gì cả, và không có gì báo. */
function vhcc_ns_cot( $cot, $o ) {
	$_GET = array(); $_POST = array();
	$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Người Khai', 'Kế toán', 'TUTU_BT', 'QN3' );
	$_POST = array( 'cot' => $cot, 'o' => $o, 'ky' => VHCC_Web::chu_ky( $_COOKIE[ VHCC_Web::COOKIE ] ) );
	ob_start(); VHCC_TrangNS::phuc_vu(); $h = ob_get_clean();
	$_POST = array(); $_COOKIE = array();
	return $h;
}
delete_option( VHCC_Cong::O );
VHCC_Cong::dat( array( 'role' => 'Admin' ), 'NGOAI', 'tram', 'mo' );   // người ở trang khác
vhcc_ns_cot( 'tram|khoa', array(
	'C1' => array( 'tram' => '', 'cham_cong' => '' ),
	'C2' => array( 'tram' => '', 'cham_cong' => '' ),
) );
teq( '🔴 bấm nút cột (không có `viec`) VẪN chạy — C1 bị khoá', 'khoa', VHCC_Cong::o( 'C1', 'tram' ) );
teq( 'và C2 cũng vậy', 'khoa', VHCC_Cong::o( 'C2', 'tram' ) );
teq( '🔴 người KHÔNG đang hiện thì không bị đụng', 'mo', VHCC_Cong::o( 'NGOAI', 'tram' ) );
teq( 'cột khác của chính người ấy cũng không bị đụng', '', VHCC_Cong::o( 'C1', 'cham_cong' ) );

/* 🔴 ĐÈ LÊN BẢNG VỪA GỬI, KHÔNG THAY NÓ. Người ta có thể đã bấm tay vài ô ở cột KHÁC rồi mới
   bấm nút cột. Bỏ `o[]` đi mà chỉ ghi mỗi cột được bấm thì mấy ô kia im lặng mất — mà nút vừa
   bấm thì chạy đúng, nên không ai nghĩ tới chuyện đi kiểm lại. */
delete_option( VHCC_Cong::O );
vhcc_ns_cot( 'tram|khoa', array( 'C3' => array( 'tram' => '', 'cham_cong' => 'mo' ) ) );
teq( 'nút cột áp đúng cột của nó', 'khoa', VHCC_Cong::o( 'C3', 'tram' ) );
teq( '🔴 và GIỮ ô người ta vừa bấm tay ở cột khác', 'mo', VHCC_Cong::o( 'C3', 'cham_cong' ) );

/* Đưa cả cột về theo vai — đường gỡ nhanh, phải xoá hẳn khoá chứ không để ô rỗng. */
vhcc_ns_cot( 'tram|', array( 'C3' => array( 'tram' => 'khoa', 'cham_cong' => 'mo' ) ) );
teq( 'nút "vai" đưa cả cột về mặc định', '', VHCC_Cong::o( 'C3', 'tram' ) );

/* ---- Trang lạ và giá trị lạ: PHÒNG THỦ HAI TẦNG, và mỗi tầng có việc RIÊNG ----
   ⚠️ Chỗ này em viết hụt một lần rồi, tìm ra khi phá thử. Bản đầu chỉ soi cuốn sổ: "bấm nút
   cột với trang lạ thì sổ vẫn sạch". Phép thử ấy XANH kể cả khi bỏ hẳn chốt ở `viec_cot` —
   vì `VHCC_Cong::luu_nhieu()` bên dưới cũng bỏ qua trang lạ, nên sổ sạch nhờ TẦNG DƯỚI chứ
   không nhờ cái chốt đang được kiểm. Phép thử khen nhầm người.

   Hai tầng đều cần, và mỗi tầng giữ một thứ khác nhau:
     • `luu_nhieu()` giữ CUỐN SỔ — không bao giờ ghi rác, dù ai gọi vào bằng đường nào.
     • `viec_cot()` giữ CÂU BÁO — nói thẳng "không có trang đó" thay vì "không có gì đổi".
   Bỏ chốt trên thì người khai bấm nút, nhận về "không có gì đổi", và không đoán ra vì sao.
   Nên soi cả hai: sổ sạch, VÀ câu báo đúng. */
delete_option( VHCC_Cong::O );
$nt_b = vhcc_ns_cot( 'trang_ma|khoa', array( 'C4' => array( 'tram' => '' ) ) );
teq( 'nút cột trỏ vào trang không có thì không ghi gì', '', VHCC_Cong::o( 'C4', 'tram' ) );
t( '🔴 và NÓI RÕ là không có trang đó, không phải "không có gì đổi"',
	strpos( $nt_b, 'Không có trang' ) !== false, $nt_b );
$nt_b = vhcc_ns_cot( 'tram|xoa_het', array( 'C4' => array( 'tram' => '' ) ) );
teq( 'giá trị lạ cũng không ghi gì', '', VHCC_Cong::o( 'C4', 'tram' ) );
t( '🔴 và nói rõ chỉ nhận mo · khoa · trống',
	strpos( $nt_b, 'Chỉ nhận' ) !== false, $nt_b );
$nt_bang = get_option( VHCC_Cong::O );
t( 'sổ vẫn sạch sau hai lượt sửa tay biểu mẫu', empty( $nt_bang ), $nt_bang );

/* Chốt quyền vẫn nguyên ở đường nút cột — không phải chỉ ở nút Lưu. */
$_GET = array(); $_POST = array();
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Nhân', 'Nhân viên', 'TUTU_BT', 'QN1' );
$_POST = array( 'cot' => 'tram|khoa', 'o' => array( 'C5' => array( 'tram' => '' ) ),
	'ky' => VHCC_Web::chu_ky( $_COOKIE[ VHCC_Web::COOKIE ] ) );
ob_start(); VHCC_TrangNS::phuc_vu(); ob_get_clean();
$_POST = array(); $_COOKIE = array();
teq( '🔴 Nhân viên bấm nút cột cũng không ghi được gì', '', VHCC_Cong::o( 'C5', 'tram' ) );
delete_option( VHCC_Cong::O );

/* ---- 60p. ĐỔI VAI TRÒ NGAY TẠI TRANG QUẢN LÝ NHÂN SỰ ----
   Anh Thắng 27/08/2026: *"chỗ cột vai trò vẫn đang khóa chưa đổi vai trò được"*.

   🔴 ĐỔI VAI LÀ ĐỔI QUYỀN, VÀ ĐÂY LÀ CHỖ MỘT NGƯỜI TỰ NÂNG MÌNH LÊN ADMIN.
   Cho Kế toán sửa ô vai mà không chốt gì thì việc đầu tiên làm được là mở ô của CHÍNH MÌNH,
   chọn Admin, bấm Lưu — xong là có PIN xem được PIN mọi người, máy chấm công, toàn bộ cài đặt.
   Không lỗi nào phát ra, không dòng nhật ký nào. Ba chốt dưới đây KHÁC NHAU, không phải một
   chốt viết ba lần — bỏ bất kỳ cái nào là hai cái kia trở nên vô dụng. */
vhcc_dung_bang();
foreach ( array(
	array( 'V_NV',  'Người NV',  'Nhân viên' ),
	array( 'V_CHT', 'Người CHT', 'Cửa hàng trưởng' ),
	array( 'V_KT',  'Người KT',  'Kế toán cá nhân' ),
	array( 'V_AD',  'Người AD',  'Admin' ),
) as $vv ) {
	$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => $vv[0], 'ho_ten' => $vv[1],
		'vai_tro' => $vv[2], 'cua_hang' => 'TUTU_BT' ) );
}
$vt_kt = array( 'name' => 'Kế', 'role' => 'Kế toán cá nhân', 'coso' => 'TUTU_BT', 'ma_nv' => 'V_KT' );
$vt_ad = array( 'name' => 'Quản', 'role' => 'Admin', 'coso' => 'TUTU_BT', 'ma_nv' => 'V_AD' );

/* Đường thường: Kế toán nâng một Nhân viên lên Cửa hàng trưởng. */
$r = VHCC_NhanSu::dat_vai_tro( $vt_kt, 'V_NV', 'Cửa hàng trưởng' );
t( 'Kế toán nâng Nhân viên lên Cửa hàng trưởng được', ! empty( $r['ok'] ), $r );
teq( 'và hồ sơ ghi đúng', 'Cửa hàng trưởng', VHCC_NhanSu::ho_so( 'V_NV' )['vai_tro'] );

/* CHỐT 1 — không đặt vai CAO HƠN bậc của chính mình. */
$r = VHCC_NhanSu::dat_vai_tro( $vt_kt, 'V_NV', 'Admin' );
t( '🔴 Kế toán KHÔNG nâng ai lên Admin được', empty( $r['ok'] ), $r );
t( 'câu chối nói rõ là vì vai của chính mình',
	isset( $r['error'] ) && stripos( $r['error'], 'cao hơn vai của chính mình' ) !== false, $r );
teq( 'và hồ sơ không bị đụng', 'Cửa hàng trưởng', VHCC_NhanSu::ho_so( 'V_NV' )['vai_tro'] );

/* CHỐT 2 — không ĐỤNG người đang ở bậc cao hơn.
   ⚠️ Thiếu chốt này thì chốt 1 vô dụng: không nâng được mình lên thì HẠ HẾT người trên xuống,
   kết quả y hệt — Kế toán thành người cao nhất còn lại. */
$r = VHCC_NhanSu::dat_vai_tro( $vt_kt, 'V_AD', 'Nhân viên' );
t( '🔴 Kế toán KHÔNG hạ được Admin xuống', empty( $r['ok'] ), $r );
t( 'câu chối nói rõ người đó đang ở bậc cao hơn',
	isset( $r['error'] ) && stripos( $r['error'], 'cao hơn vai của bạn' ) !== false, $r );
teq( 'Admin vẫn nguyên vai', 'Admin', VHCC_NhanSu::ho_so( 'V_AD' )['vai_tro'] );

/* CHỐT 3 — không tự đổi vai của CHÍNH MÌNH, kể cả hạ.
   ⚠️ Admin duy nhất tự hạ xuống Nhân viên là cả hệ không còn ai vào được màn cài đặt, và không
   có đường gỡ nào ngoài sửa thẳng CSDL. */
$r = VHCC_NhanSu::dat_vai_tro( $vt_ad, 'V_AD', 'Nhân viên' );
t( '🔴 Admin KHÔNG tự hạ vai mình được', empty( $r['ok'] ), $r );
t( 'và câu chối chỉ đường nhờ Admin khác',
	isset( $r['error'] ) && stripos( $r['error'], 'chính mình' ) !== false, $r );
$r = VHCC_NhanSu::dat_vai_tro( $vt_kt, 'V_KT', 'Admin' );
t( '🔴 Kế toán cũng không tự NÂNG mình', empty( $r['ok'] ), $r );
t( 'câu chối nói đúng chuyện đang xảy ra (tự sửa mình), không đổ nhầm cho bậc',
	isset( $r['error'] ) && stripos( $r['error'], 'chính mình' ) !== false, $r );
teq( 'vai của chính người khai vẫn nguyên', 'Kế toán cá nhân', VHCC_NhanSu::ho_so( 'V_KT' )['vai_tro'] );

/* Admin đổi được vai người khác, kể cả lên Admin. */
$r = VHCC_NhanSu::dat_vai_tro( $vt_ad, 'V_CHT', 'Quản lý' );
t( 'Admin đổi được vai người khác', ! empty( $r['ok'] ), $r );
teq( 'ghi đúng', 'Quản lý', VHCC_NhanSu::ho_so( 'V_CHT' )['vai_tro'] );

/* Chốt chung: bậc dưới Kế toán không đụng được gì.
   ⚠️ Phép thử này phải đặt vai NGANG BẬC người khai, không phải cao hơn. Bản đầu thử "Cửa hàng
   trưởng nâng ai đó lên Quản lý" — vẫn XANH kể cả khi bỏ hẳn chốt quyền `ho_so`, vì chốt "không
   đặt vai cao hơn bậc mình" đã chặn trước. Phép thử khen nhầm người, y như lần trước ở nút cột.
   Đặt đúng bậc của chính họ (Cửa hàng trưởng nâng một Nhân viên lên Cửa hàng trưởng) thì cả ba
   chốt bậc đều cho qua, và chỉ còn chốt quyền đứng đó — lúc ấy mới đo được nó. */
$vt_cht = array( 'name' => 'CHT', 'role' => 'Cửa hàng trưởng', 'coso' => 'TUTU_BT', 'ma_nv' => 'V_CHT' );
$r = VHCC_NhanSu::dat_vai_tro( $vt_cht, 'V_NV', 'Cửa hàng trưởng' );
t( '🔴 Cửa hàng trưởng KHÔNG đổi được vai ai, kể cả NGANG bậc mình', empty( $r['ok'] ), $r );
t( 'và câu chối nói rõ cần bậc Kế toán',
	isset( $r['error'] ) && stripos( $r['error'], 'Kế toán' ) !== false, $r );
t( 'Nhân viên lại càng không',
	empty( VHCC_NhanSu::dat_vai_tro( array( 'role' => 'Nhân viên', 'ma_nv' => 'V_X' ), 'V_NV', 'Nhân viên' )['ok'] ) );
t( 'Cửa hàng trưởng cũng không nâng ai lên bậc trên mình',
	empty( VHCC_NhanSu::dat_vai_tro( $vt_cht, 'V_NV', 'Quản lý' )['ok'] ) );

/* ⚠️ LƯU NGUYÊN CHUỖI, KHÔNG QUY VỀ TÊN CHUNG. Hệ chấm công gộp "Kế toán cá nhân" và "Kế toán
   NCC" vào một bậc, nhưng app Vận hành chi phí PHÂN BIỆT hai vai ấy. Ghi đè thành "Kế toán" là
   bên chi phí mất phân biệt, mà bên này không thấy gì khác cả. */
$r = VHCC_NhanSu::dat_vai_tro( $vt_ad, 'V_NV', 'Kế toán NCC' );
t( 'đặt được vai "Kế toán NCC"', ! empty( $r['ok'] ), $r );
teq( '🔴 và lưu NGUYÊN chuỗi, không quy về "Kế toán"',
	'Kế toán NCC', VHCC_NhanSu::ho_so( 'V_NV' )['vai_tro'] );

/* Vai lạ bị chối — nhận bừa thì `VHCC_Vai::ma()` đẩy nó về Nhân viên, tức ô vai trở thành một
   đường HẠ quyền người khác mà không ai gọi tên được việc vừa xảy ra. */
$r = VHCC_NhanSu::dat_vai_tro( $vt_ad, 'V_NV', 'Sếp Tổng' );
t( '🔴 vai không có trong hệ thì bị chối', empty( $r['ok'] ), $r );
teq( 'và hồ sơ giữ nguyên', 'Kế toán NCC', VHCC_NhanSu::ho_so( 'V_NV' )['vai_tro'] );
t( 'hồ sơ không có thì chối', empty( VHCC_NhanSu::dat_vai_tro( $vt_ad, 'KHONG_CO', 'Quản lý' )['ok'] ) );

/* Đặt lại đúng vai đang có thì KHÔNG tính là một lượt đổi — nếu không thì mỗi lần bấm Lưu đều
   báo "đã đổi vai cho 50 người". */
$r = VHCC_NhanSu::dat_vai_tro( $vt_ad, 'V_NV', 'Kế toán NCC' );
t( 'lưu lại y nguyên thì ok nhưng không tính là đổi', ! empty( $r['ok'] ) && empty( $r['doi'] ), $r );

/* ---- 60q. ĐỔI VAI QUA MÀN HÌNH ---- */
function vhcc_ns_luu( $vai_toi, $ma_toi, $post ) {
	$_GET = array(); $_POST = array();
	$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Khai', $vai_toi, 'TUTU_BT', $ma_toi );
	$_POST = array_merge( array( 'viec' => 'luu_quyen',
		'ky' => VHCC_Web::chu_ky( $_COOKIE[ VHCC_Web::COOKIE ] ) ), $post );
	ob_start(); VHCC_TrangNS::phuc_vu(); $h = ob_get_clean();
	$_POST = array(); $_COOKIE = array();
	return $h;
}
vhcc_ns_luu( 'Admin', 'V_AD', array( 'o' => array( 'V_NV' => array( 'tram' => '' ) ),
	'vai' => array( 'V_NV' => 'Nhân viên' ) ) );
teq( 'bấm Lưu trên màn hình thì vai vào hồ sơ thật', 'Nhân viên', VHCC_NhanSu::ho_so( 'V_NV' )['vai_tro'] );

/* 🔴 LỖI VAI PHẢI HIỆN RA, KHÔNG ĐƯỢC NUỐT. Ba chốt trên chỉ có tác dụng nếu người bấm ĐỌC
   ĐƯỢC câu chối. Nuốt đi thì màn báo "đã lưu", ô vai trở về giá trị cũ, và người ta tưởng hệ
   thống hỏng chứ không biết mình vừa bị chặn. */
$vq_h = vhcc_ns_luu( 'Kế toán cá nhân', 'V_KT', array( 'o' => array( 'V_NV' => array( 'tram' => '' ) ),
	'vai' => array( 'V_NV' => 'Admin' ) ) );
teq( 'Kế toán không nâng được ai lên Admin qua màn hình', 'Nhân viên', VHCC_NhanSu::ho_so( 'V_NV' )['vai_tro'] );
t( '🔴 và màn hình NÓI RA vì sao, không im lặng',
	strpos( $vq_h, 'cao hơn vai của chính mình' ) !== false, $vq_h );

/* Người khai không đổi được ai thì ô vai in ra CHỮ, không phải ô xổ — vẽ ô xổ cho hàng họ
   không đụng được là bấm xong bấm Lưu mới nhận câu chối, mà giữa một trang 50 người thì câu
   chối ấy trôi mất và người ta tưởng mình đã đổi. */
$_GET = array(); $_POST = array();
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Kế', 'Kế toán cá nhân', 'TUTU_BT', 'V_KT' );
ob_start(); VHCC_TrangNS::phuc_vu(); $vq_h2 = ob_get_clean();
$_COOKIE = array();
t( '🔴 hàng của CHÍNH người đang khai không có ô xổ vai',
	preg_match( '/<select[^>]*name="vai\[V_KT\]"/', $vq_h2 ) === 0, $vq_h2 );
t( 'và ghi rõ "(chính bạn)"', strpos( $vq_h2, 'chính bạn' ) !== false );
t( '🔴 hàng của người ở bậc CAO HƠN cũng không có ô xổ',
	preg_match( '/<select[^>]*name="vai\[V_AD\]"/', $vq_h2 ) === 0, $vq_h2 );
t( 'Kế toán KHÔNG thấy lựa chọn "Admin" trong ô xổ nào',
	strpos( $vq_h2, '<option value="Admin"' ) === false, $vq_h2 );

/* Đường sang hồ sơ đầy đủ — anh Thắng: *"cấu hình này nó thông với thông tin nhân viên"*. */
t( 'mỗi hàng có đường mở hồ sơ đầy đủ', strpos( $vq_h2, 'class="mo-hs"' ) !== false );
/* 🔴 PHẢI LÀ `sua=`, KHÔNG PHẢI `q=`. Anh Thắng 27/08/2026: *"Admin chưa sửa được thông tin
   nhân viên"* — bản trước trỏ `q=<mã>`, mà `q` là ô TÌM: nó chỉ LỌC danh sách chứ không mở biểu
   mẫu sửa. Bấm vào thấy đúng người mình cần mà không có ô nào nhập được, nên trông y như tính
   năng sửa bị hỏng. Phép thử cũ soi `man=ho_so` + `q=V_NV` nên nó XANH với cái đường sai ấy —
   nó chỉ kiểm "có đường dẫn", không kiểm "đường dẫn ấy mở được cái gì". */
t( '🔴 đường ấy trỏ tới BIỂU MẪU SỬA (sua=), không phải ô tìm (q=)',
	strpos( $vq_h2, 'man=ho_so' ) !== false && strpos( $vq_h2, 'sua=V_NV' ) !== false, $vq_h2 );
t( 'và không còn dùng ô tìm để giả làm đường sửa',
	strpos( $vq_h2, 'q=V_NV' ) === false, $vq_h2 );

/* ➕ THÊM NHÂN SỰ — anh Thắng: *"Chưa có chỗ bổ sung thêm nhân sự"*.
   `sua=+` là thứ `VHCC_Web::the_sua_ho_so()` hiểu là "hồ sơ mới" (biểu mẫu có ô Mã NV). */
$vq_ad = vhcc_ns( 'Admin' );
t( '🔴 có nút Thêm nhân sự', strpos( $vq_ad, 'Thêm nhân sự' ) !== false, $vq_ad );
t( 'và nó trỏ tới biểu mẫu HỒ SƠ MỚI (sua=+)',
	strpos( $vq_ad, 'sua=%2B' ) !== false || strpos( $vq_ad, 'sua=+' ) !== false, $vq_ad );
/* Tạo hồ sơ mới là cấp Mã NV dùng chung cả chuỗi -> Quản lý trở lên. Kế toán tuy bậc cao hơn
   Quản lý ở thang chung, nhưng `co_quan_tri_nv` hỏi `ngoai_coso` nên Kế toán vẫn qua. Người
   KHÔNG qua là Cửa hàng trưởng — mà họ cũng không vào nổi trang này. Nên chỉ cần chắc rằng nút
   được gác bằng CHÍNH hàm ấy, đừng vẽ cho người bấm vào rồi bị chối. */
t( 'nút Thêm gác bằng co_quan_tri_nv',
	strpos( file_get_contents( $goc . '/wordpress/vhcp-cham-cong/includes/class-vhcc-trang-ns.php' ),
		'VHCC_NhanSu::co_quan_tri_nv( $toi )' ) !== false );
vhcc_dung_bang();

/* ==========================================================================================
 *  61. BẢNG VAI TRÒ — vai riêng của công ty
 * ------------------------------------------------------------------------------------------
 *  Anh Thắng 27/08/2026: *"muốn thêm bảng vai trò: vì sau anh cần vai trò kế toán nhân sự,
 *  kế toán Posh"*.
 *
 *  🔴 KẾ THỪA MỘT VAI GỐC, KHÔNG KHAI LẠI TỪNG QUYỀN. Cách trông "đầy đủ" hơn là cho mỗi vai
 *  mới một bảng 19 ô tích — đừng. Thang năm bậc không có tổ hợp nào lệch được; mở ra ô tích rời
 *  thì tới vai thứ tư là có người tích cho một vai vừa xem được bảng lương vừa không xem được
 *  bảng công cơ sở mình, và không ai giải thích nổi vì sao.
 * ======================================================================================== */
vhcc_dung_bang();
delete_option( VHCC_Vai::O_THEM );
VHCC_Vai::quen_nho();
$vth_ad = array( 'name' => 'Ad', 'role' => 'Admin', 'coso' => 'TUTU_BT', 'ma_nv' => 'T_AD' );
$vth_kt = array( 'name' => 'Kt', 'role' => 'Kế toán cá nhân', 'coso' => 'TUTU_BT', 'ma_nv' => 'T_KT' );

$r = VHCC_Vai::dat_them( $vth_ad, 'Kế toán POSH', VHCC_Vai::KE_TOAN );
t( 'khai được vai "Kế toán POSH"', ! empty( $r['ok'] ), $r );
$r = VHCC_Vai::dat_them( $vth_ad, 'Kế toán nhân sự', VHCC_Vai::KE_TOAN );
t( 'khai được vai "Kế toán nhân sự"', ! empty( $r['ok'] ), $r );

/* 🔴 VAI MỚI PHẢI RA ĐÚNG BẬC CỦA VAI GỐC — đây là toàn bộ điểm của tính năng. */
teq( 'vai mới quy về đúng mã gốc', VHCC_Vai::KE_TOAN, VHCC_Vai::ma( 'Kế toán POSH' ) );
$u_posh = array( 'role' => 'Kế toán POSH' );
teq( 'và ra đúng bậc 4', 4, VHCC_Vai::bac( $u_posh ) );
t( 'nên làm được việc của Kế toán', VHCC_Vai::duoc( $u_posh, 'ho_so' ) );
t( 'và KHÔNG làm được việc của Admin', ! VHCC_Vai::duoc( $u_posh, 'he_thong' ) );
t( 'cũng không đổi được Mã NV', ! VHCC_Vai::duoc( $u_posh, 'doi_ma_nv' ) );

/* ⚠️ Nhận cả kiểu viết khác dấu / khác hoa thường — hồ sơ do người gõ tay. */
teq( 'nhận "ke toan posh" không dấu', VHCC_Vai::KE_TOAN, VHCC_Vai::ma( 'ke toan posh' ) );
teq( 'nhận "KẾ TOÁN POSH" viết hoa', VHCC_Vai::KE_TOAN, VHCC_Vai::ma( 'KẾ TOÁN POSH' ) );

/* 🔴 VAI TỰ TẠO TRA TRƯỚC BẢNG CỨNG. Đặt sau thì "Kế toán POSH" rơi vào nhánh
   `strpos($s,'ke toan')===0` và thành Kế toán — ĐÚNG BẬC, nhưng chỉ đúng tình cờ. Một vai tên
   "Điều phối POSH" gốc Quản lý thì nhánh ấy không nhận ra, và người mang vai rơi xuống Nhân
   viên mà không có gì báo. Nên phải thử bằng một cái tên KHÔNG dính chữ nào của vai gốc. */
$r = VHCC_Vai::dat_them( $vth_ad, 'Điều phối POSH', VHCC_Vai::QL );
t( 'khai được vai không giống tên vai gốc nào', ! empty( $r['ok'] ), $r );
teq( '🔴 và nó vẫn ra đúng bậc Quản lý', VHCC_Vai::QL, VHCC_Vai::ma( 'Điều phối POSH' ) );
teq( 'bậc 3', 3, VHCC_Vai::bac( array( 'role' => 'Điều phối POSH' ) ) );

/* 🔴 NGƯỜI MANG VAI TỰ TẠO PHẢI ĐĂNG NHẬP ĐƯỢC. `VHCC_Web::trang_dang_nhap` so vai với đúng
   `vai_tro_vao()`; quên gộp vai tự tạo vào đó là người ta gõ ĐÚNG PIN mà bị chối, kèm câu
   "vai trò không được vào hệ thống" — đổ cho vai trò trong khi lỗi nằm ở chỗ danh sách quên
   mất mấy vai vừa khai. Đúng loại lỗi không ai lần ra. */
t( '🔴 vai tự tạo có tên trong danh sách vai vào được',
	in_array( 'Kế toán POSH', VHCC_Auth::vai_tro_vao(), true ), VHCC_Auth::vai_tro_vao() );
t( 'và vai gốc vẫn còn nguyên trong danh sách',
	in_array( 'Admin', VHCC_Auth::vai_tro_vao(), true ) );

/* ---- CHỐT: KHÔNG TẠO VAI GỐC CAO HƠN BẬC MÌNH ----
   Thiếu chốt này thì một Kế toán tạo vai "Trợ lý" gốc Admin, gán cho người khác, rồi nhờ người
   ấy nâng mình lên — ba bước, không bước nào bị chối, không dòng nhật ký nào. */
$r = VHCC_Vai::dat_them( $vth_kt, 'Trợ lý', VHCC_Vai::ADMIN );
t( '🔴 Kế toán KHÔNG tạo được vai gốc Admin', empty( $r['ok'] ), $r );
t( 'câu chối nói rõ vì vai của chính mình',
	isset( $r['error'] ) && stripos( $r['error'], 'cao hơn vai của' ) !== false, $r );
t( 'Kế toán tạo được vai gốc Kế toán', ! empty( VHCC_Vai::dat_them( $vth_kt, 'Kế toán kho', VHCC_Vai::KE_TOAN )['ok'] ) );
t( '🔴 Cửa hàng trưởng không khai được vai nào',
	empty( VHCC_Vai::dat_them( array( 'role' => 'Cửa hàng trưởng' ), 'Vai X', VHCC_Vai::NV )['ok'] ) );

/* ---- CHỐT: TRÙNG TÊN VAI GỐC LÀ ĐÈ LÊN LUẬT GỐC ----
   🔴 `ma()` tra bảng tự tạo TRƯỚC, nên một dòng tên "Quản lý" gốc Nhân viên là hạ TOÀN BỘ Quản
   lý của công ty xuống bậc 1 — im lặng, và không ai nghĩ tới bảng vai khi đi tìm nguyên nhân. */
$r = VHCC_Vai::dat_them( $vth_ad, 'Quản lý', VHCC_Vai::NV );
t( '🔴 trùng tên vai gốc thì bị chối', empty( $r['ok'] ), $r );
teq( 'và Quản lý vẫn nguyên bậc 3', 3, VHCC_Vai::bac( array( 'role' => 'Quản lý' ) ) );
t( 'trùng kiểu không dấu cũng chối', empty( VHCC_Vai::dat_them( $vth_ad, 'quan ly', VHCC_Vai::NV )['ok'] ) );
t( 'trùng "Kế toán NCC" (vai gốc của app chi phí) cũng chối',
	empty( VHCC_Vai::dat_them( $vth_ad, 'Kế toán NCC', VHCC_Vai::NV )['ok'] ) );
/* ⚠️ "Kế toán" TRỐNG KHÔNG là tên chỉ có trong `VHCC_Vai::TEN`, KHÔNG có trong
   `VHCC_Auth::VAI_TRO_TAT_CA` (bên đó là "Kế toán cá nhân" / "Kế toán NCC"). Nên nó là cái tên
   DUY NHẤT đo được vòng chặn theo `VHCC_Vai::TEN`. Thiếu phép thử này thì bỏ hẳn vòng ấy đi mà
   bộ thử vẫn xanh — vòng kia đỡ giúp cho mọi tên khác. Đã thử phá đúng chỗ đó. */
$r = VHCC_Vai::dat_them( $vth_ad, 'Kế toán', VHCC_Vai::NV );
t( '🔴 trùng đúng tên hiển thị của một bậc ("Kế toán") cũng chối', empty( $r['ok'] ), $r );
teq( 'và ai ghi đúng chữ "Kế toán" trong hồ sơ vẫn giữ bậc 4',
	4, VHCC_Vai::bac( array( 'role' => 'Kế toán' ) ) );
t( 'trùng một vai TỰ TẠO khác cũng chối',
	empty( VHCC_Vai::dat_them( $vth_ad, 'ke toan posh', VHCC_Vai::NV )['ok'] ) );
teq( 'và "Kế toán POSH" vẫn giữ gốc Kế toán', VHCC_Vai::KE_TOAN, VHCC_Vai::ma( 'Kế toán POSH' ) );

/* Sửa lại gốc của một vai đã có thì được — đó là "sửa", không phải "trùng". */
t( 'sửa gốc của vai đã có', ! empty( VHCC_Vai::dat_them( $vth_ad, 'Kế toán kho', VHCC_Vai::QL )['ok'] ) );
teq( 'gốc mới có hiệu lực', VHCC_Vai::QL, VHCC_Vai::ma( 'Kế toán kho' ) );

/* Gốc lạ, tên rỗng, tên quá dài. */
t( 'gốc không hợp lệ thì chối', empty( VHCC_Vai::dat_them( $vth_ad, 'Vai Y', 'SIEU_NHAN' )['ok'] ) );
t( 'tên rỗng thì chối', empty( VHCC_Vai::dat_them( $vth_ad, '   ', VHCC_Vai::NV )['ok'] ) );
t( 'tên dài quá 40 ký tự thì chối',
	empty( VHCC_Vai::dat_them( $vth_ad, str_repeat( 'a', 41 ), VHCC_Vai::NV )['ok'] ) );

/* ---- CHỐT: XOÁ VAI ĐANG CÓ NGƯỜI DÙNG ----
   🔴 Xoá đi thì `ma()` không tra ra nữa và họ rơi xuống ĐÁY thang — mất sạch quyền, im lặng,
   và chỉ lộ ra khi từng người kêu lên. */
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'P1', 'ho_ten' => 'Người POSH',
	'vai_tro' => 'Kế toán POSH', 'cua_hang' => 'TUTU_BT' ) );
teq( 'đếm đúng số người đang mang vai', 1, VHCC_Vai::dem_nguoi( 'Kế toán POSH' ) );
$r = VHCC_Vai::xoa_them( $vth_ad, 'Kế toán POSH' );
t( '🔴 còn người mang vai thì KHÔNG xoá được', empty( $r['ok'] ), $r );
t( 'câu chối nói rõ còn bao nhiêu người và phải làm gì trước',
	isset( $r['error'] ) && strpos( $r['error'], '1 người' ) !== false
	&& stripos( $r['error'], 'đổi vai' ) !== false, $r );
teq( 'và người ấy vẫn giữ nguyên bậc', 4, VHCC_Vai::bac( array( 'role' => 'Kế toán POSH' ) ) );

/* Đổi vai cho họ rồi thì xoá được. */
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Nhân viên' ), array( 'ma_nv' => 'P1' ) );
t( 'đổi vai cho họ rồi thì xoá được', ! empty( VHCC_Vai::xoa_them( $vth_ad, 'Kế toán POSH' )['ok'] ) );
/* ⚠️ XOÁ XONG THÌ RƠI VỀ ĐÂU TUỲ CÁI TÊN — và phải thử bằng cái tên KHÔNG dính vai gốc nào.
   "Kế toán POSH" xoá đi vẫn ra Kế toán, vì bảng cứng có nhánh "mọi thứ bắt đầu bằng ke toan".
   Đó là hành vi ĐÚNG của bảng cứng, không phải sót. Nhưng nó cũng có nghĩa là phép thử dùng
   cái tên ấy KHÔNG đo được gì cả — nó xanh vì một lý do khác hẳn lý do mình tưởng. Dùng "Điều
   phối POSH": bảng cứng không nhận ra chữ nào, nên mới thấy được cú rơi thật. */
teq( 'xoá "Kế toán POSH" thì bảng cứng vẫn nhận ra chữ "kế toán"',
	VHCC_Vai::KE_TOAN, VHCC_Vai::ma( 'Kế toán POSH' ) );
t( 'xoá được vai không dính tên vai gốc nào',
	! empty( VHCC_Vai::xoa_them( $vth_ad, 'Điều phối POSH' )['ok'] ) );
teq( '🔴 xoá xong thì tên ấy rơi về ĐÁY thang (luật "lạ -> Nhân viên")',
	VHCC_Vai::NV, VHCC_Vai::ma( 'Điều phối POSH' ) );
t( 'xoá vai không có thì chối', empty( VHCC_Vai::xoa_them( $vth_ad, 'Không Có Vai Này' )['ok'] ) );
t( '🔴 Cửa hàng trưởng không xoá được vai',
	empty( VHCC_Vai::xoa_them( array( 'role' => 'Cửa hàng trưởng' ), 'Kế toán nhân sự' )['ok'] ) );

/* Trần số vai — quá con số này thì vấn đề không còn nằm ở chỗ thiếu vai nữa. */
delete_option( VHCC_Vai::O_THEM ); VHCC_Vai::quen_nho();
for ( $i = 1; $i <= VHCC_Vai::THEM_TOI_DA; $i++ ) {
	VHCC_Vai::dat_them( $vth_ad, 'Vai số ' . $i, VHCC_Vai::NV );
}
teq( 'khai đủ trần', VHCC_Vai::THEM_TOI_DA, count( VHCC_Vai::them() ) );
t( '🔴 quá trần thì chối', empty( VHCC_Vai::dat_them( $vth_ad, 'Vai số ' . ( VHCC_Vai::THEM_TOI_DA + 1 ), VHCC_Vai::NV )['ok'] ) );
t( 'nhưng SỬA một vai đã có thì vẫn được, không bị trần chặn',
	! empty( VHCC_Vai::dat_them( $vth_ad, 'Vai số 1', VHCC_Vai::CHT )['ok'] ) );

/* ---- QUA MÀN HÌNH ---- */
delete_option( VHCC_Vai::O_THEM ); VHCC_Vai::quen_nho();
vhcc_ns_luu( 'Admin', 'T_AD', array( 'viec' => 'them_vai',
	'vai_ten' => 'Kế toán POSH', 'vai_goc' => VHCC_Vai::KE_TOAN ) );
teq( 'khai vai qua màn hình thì vào sổ thật', VHCC_Vai::KE_TOAN, VHCC_Vai::ma( 'Kế toán POSH' ) );

$vth_h = vhcc_ns( 'Kế toán' );
t( 'trang có khối Bảng vai trò', strpos( $vth_h, 'Bảng vai trò' ) !== false );

/* ---- 🔴 CẢNH BÁO KHI ĐỔI VAI Ở ĐÂY KHÔNG CÓ HIỆU LỰC ĐĂNG NHẬP ----
   Hệ có BỐN kho người dùng; `VHCC_Auth::nguon()` quyết định lúc đăng nhập đọc kho nào. Cột Vai
   trò của bảng này ghi vào HỒ SƠ NHÂN SỰ. Khi nguồn đang đặt là kho khác thì bấm Lưu vẫn ghi
   thành công vào hồ sơ, màn hình vẫn báo "Đã đổi vai trò cho N người" — mà vai lúc đăng nhập
   đọc từ kho kia, không đổi gì cả.

   Đó là lời nói dối tệ nhất một màn quản trị có thể nói: BÁO THÀNH CÔNG CHO MỘT VIỆC KHÔNG XẢY
   RA. Người khai đóng trang, tin là xong, và chỉ phát hiện khi có người kêu "sao tôi vẫn không
   vào được" — lúc ấy không ai nối được hai chuyện với nhau. */
$vth_nguon_cu = get_option( 'vhcc_nguon_nguoidung' );
update_option( 'vhcc_nguon_nguoidung', 'chung' );
$vth_c = vhcc_ns( 'Kế toán' );
t( '🔴 nguồn KHÁC hồ sơ thì trang NÓI RA rằng đổi vai chưa có hiệu lực',
	strpos( $vth_c, 'chưa có hiệu lực ngay' ) !== false, $vth_c );
t( 'và nói rõ đang đọc từ sổ nào', strpos( $vth_c, 'Vận hành chi phí' ) !== false );
/* 🔴 KHÔNG PHẢI man=cau_hinh — tab đó không có ô Nguồn người dùng. Đường sửa đúng trỏ sang
   man=ho_so, khối 🔑 Tài khoản đăng nhập (xem phép thử "HỒ SƠ GHI MỘT VAI..." ở cuối tệp). */
t( 'kèm đường sang màn Hồ sơ & tài khoản để đổi nguồn (KHÔNG phải Cấu hình — tab đó không có mục này)',
	strpos( $vth_c, 'man=ho_so' ) !== false && strpos( $vth_c, 'man=cau_hinh' ) === false, $vth_c );
/* ⚠️ Nói ra cả cái KHÔNG bị ảnh hưởng, kẻo người đọc tưởng cả hệ đang hỏng. */
t( 'và trấn an rằng trạm chấm công không dính', strpos( $vth_c, 'Trạm chấm công không bị ảnh hưởng' ) !== false );

update_option( 'vhcc_nguon_nguoidung', 'ho_so' );
$vth_c = vhcc_ns( 'Kế toán' );
t( '🔴 nguồn ĐÚNG là hồ sơ thì KHÔNG cảnh báo gì — cảnh báo thừa là cảnh báo bị bỏ qua',
	strpos( $vth_c, 'chưa có hiệu lực ngay' ) === false, $vth_c );
update_option( 'vhcc_nguon_nguoidung', $vth_nguon_cu );
t( 'và ô khai vai mới', strpos( $vth_h, 'name="vai_ten"' ) !== false );
t( '🔴 vai vừa khai CÓ MẶT trong ô xổ vai của bảng người',
	strpos( $vth_h, '<option value="Kế toán POSH"' ) !== false, $vth_h );
/* ⚠️ Ô chọn vai gốc CẮT ở bậc người khai: Kế toán không thấy dòng "Admin" — tạo được vai gốc
   Admin là tạo ra một đường nâng quyền.
   🔴 SOI TRONG ĐÚNG Ô `vai_goc`, ĐỪNG SOI CẢ TRANG. Mã "ADMIN" còn nằm ở ô LỌC "Vai trò" phía
   trên (lọc bảng theo bậc — vô hại, và cần có). Soi cả trang là phép thử đỏ oan trong khi ô
   khai vai vẫn đúng, rồi lần sau có người "sửa" bằng cách bỏ ADMIN khỏi ô lọc — hỏng một thứ
   đang đúng để chiều một phép thử viết sai. */
$vth_o = '';
if ( preg_match( '/<select name="vai_goc">.*?<\/select>/s', $vth_h, $vth_m ) ) { $vth_o = $vth_m[0]; }
t( 'dò được ô chọn vai gốc', '' !== $vth_o, $vth_h );
t( '🔴 Kế toán không thấy lựa chọn gốc "Admin" trong ô khai vai',
	'' !== $vth_o && strpos( $vth_o, VHCC_Vai::ADMIN ) === false, $vth_o );
t( 'nhưng vẫn thấy các gốc từ Kế toán trở xuống',
	strpos( $vth_o, VHCC_Vai::KE_TOAN ) !== false && strpos( $vth_o, VHCC_Vai::NV ) !== false, $vth_o );

delete_option( VHCC_Vai::O_THEM ); VHCC_Vai::quen_nho();
vhcc_dung_bang();

/* ---- 62. HỒ SƠ TRÙNG TÊN / TRÙNG MÃ ĐƯA LÊN ĐẦU ----
   Anh Thắng 27/08/2026: *"Nhân viên nào trùng tên, trùng Mã NV thì đưa lên đầu nhé"*.

   🔴 MÃ LÀ KHOÁ. Hai hồ sơ của cùng một người mang hai mã là công của họ bị chẻ đôi, mỗi nửa
   một bảng lương. Hai người khác nhau lỡ mang cùng một mã là công người này cộng vào người kia.
   Cả hai kiểu hỏng đều IM LẶNG — không lỗi nào phát ra, chỉ có con số cuối tháng sai. */
vhcc_dung_bang();
foreach ( array(
	array( 'TR1', 'Nguyễn Thị Ánh Tuyết' ),
	array( 'TR2', 'NGUYỄN THỊ  ÁNH TUYẾT' ),   // trùng TÊN, khác hoa thường + thừa khoảng trắng
	array( 'TR3', 'Nguyệt Thị Ánh Tuyết' ),    // GẦN giống — KHÔNG được coi là trùng
	array( 'TR4', 'Lê Văn Bốn' ),
	array( 'tr4 ', 'Người Khác Hẳn' ),          // trùng MÃ sau chuẩn hoá (hoa thường + khoảng trắng)
	array( 'TR6', 'Trần Văn Sáu' ),
	/* ⚠️ CẶP NÀY LÀ ĐỂ ĐO VIỆC "XẾP LÊN ĐẦU", VÀ TÊN CỦA NÓ ĐƯỢC CHỌN CÓ CHỦ Ý.
	   Danh sách gốc đã `ORDER BY cua_hang, ho_ten`, nên nếu hồ sơ trùng tình cờ có tên đứng
	   trước theo bảng chữ cái thì nó vẫn ở đầu KỂ CẢ khi bỏ hẳn bước xếp — phép thử xanh mà
	   chẳng đo được gì. Đã vấp đúng chỗ đó: "Lê Văn Bốn" (trùng) vốn đứng trước "Trần Văn Sáu"
	   (sạch). Nên thêm một cặp trùng mang tên xếp CUỐI bảng chữ cái, và một người sạch mang tên
	   xếp ĐẦU — lúc ấy chỉ có bước xếp mới đảo được thứ tự. */
	array( 'ZZ1', 'Ưng Văn Cuối' ),
	array( 'ZZ2', 'Ưng Văn Cuối' ),            // trùng TÊN, mà tên lại xếp cuối bảng
	array( 'AA0', 'An Toàn Sạch' ),            // sạch, tên xếp đầu bảng
) as $tt ) {
	$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => $tt[0], 'ho_ten' => $tt[1],
		'vai_tro' => 'Nhân viên', 'cua_hang' => 'TUTU_BT' ) );
}
$ds_tt = VHCC_NhanSu::ds_nhan_vien( $U_AD );
$tt_tr = VHCC_NhanSu::dau_hieu_trung( $ds_tt );

t( '🔴 bắt được trùng tên dù khác hoa thường và thừa khoảng trắng',
	isset( $tt_tr['TR1'] ) && $tt_tr['TR1']['ten'], $tt_tr );
t( 'cả hai bên của cặp trùng đều được đánh dấu', isset( $tt_tr['TR2'] ) && $tt_tr['TR2']['ten'] );
/* 🔴 PHẢI BỎ DẤU TRƯỚC KHI LỌC KÝ TỰ. Bản nháp đầu hạ chữ mà không bỏ dấu, rồi
   `preg_replace('/[^a-z0-9]+/')` XOÁ sạch chữ có dấu: "Nguyễn" thành "nguy n", "Nguyệt" cũng
   thành "nguy t"… và "Nguyễn Thị Ánh Tuyết" đụng "Nguyệt Thị Ánh Tuyết". Hai người KHÁC NHAU
   bị báo trùng — báo động giả, mà báo động giả thì người ta tắt đi. */
t( '🔴 "Nguyệt" KHÔNG bị coi là trùng với "Nguyễn"',
	! isset( $tt_tr['TR3'] ) || ! $tt_tr['TR3']['ten'], $tt_tr );
teq( 'khoá so của hai tên ấy phải KHÁC nhau', false,
	VHCC_NhanSu::khoa_so( 'Nguyễn Thị Ánh Tuyết' ) === VHCC_NhanSu::khoa_so( 'Nguyệt Thị Ánh Tuyết' ) );
teq( 'và khoá so KHÔNG được nuốt mất chữ có dấu',
	'nguyen thi anh tuyet', VHCC_NhanSu::khoa_so( 'Nguyễn Thị  Ánh Tuyết' ) );

/* Trùng MÃ sau chuẩn hoá — đây là cặp nguy hiểm nhất: CSDL coi "TR4" và "tr4 " là hai dòng
   khác nhau nên KHÔNG hề chặn, còn người đọc thì thấy y hệt nhau. */
t( '🔴 bắt được trùng mã dù khác hoa thường + thừa khoảng trắng',
	isset( $tt_tr['TR4'] ) && $tt_tr['TR4']['ma'], $tt_tr );
t( 'bên kia của cặp cũng bị đánh dấu', isset( $tt_tr['tr4 '] ) && $tt_tr['tr4 ']['ma'] );
t( 'người không trùng gì thì KHÔNG bị đánh dấu', ! isset( $tt_tr['TR6'] ), $tt_tr );
t( 'và người trùng mã KHÔNG bị gắn nhầm nhãn trùng tên', empty( $tt_tr['TR4']['ten'] ) );

/* Xếp lên đầu — giữ nguyên thứ tự cũ trong từng nhóm. */
$tt_xep = VHCC_NhanSu::xep_trung_len_dau( $ds_tt, $tt_tr );
teq( 'không mất ai sau khi xếp', count( $ds_tt ), count( $tt_xep ) );
$tt_dau = array();
foreach ( array_slice( $tt_xep, 0, count( $tt_tr ) ) as $x ) { $tt_dau[] = (string) $x['ma_nv']; }
sort( $tt_dau );
$tt_mong = array_keys( $tt_tr ); sort( $tt_mong );
teq( '🔴 mọi hồ sơ trùng đều nằm ở đầu danh sách', $tt_mong, $tt_dau );
/* 🔴 PHÉP ĐO THẬT của việc xếp: hồ sơ trùng mang tên xếp CUỐI bảng chữ cái phải nhảy lên
   TRƯỚC người sạch mang tên xếp ĐẦU. Không có bước xếp thì thứ tự đúng ngược lại. */
$vt_zz = -1; $vt_aa = -1;
foreach ( $tt_xep as $i_x => $x ) {
	if ( 'ZZ1' === (string) $x['ma_nv'] ) { $vt_zz = $i_x; }
	if ( 'AA0' === (string) $x['ma_nv'] ) { $vt_aa = $i_x; }
}
t( '🔴 hồ sơ trùng (tên xếp cuối) nhảy lên TRƯỚC người sạch (tên xếp đầu)',
	$vt_zz >= 0 && $vt_aa >= 0 && $vt_zz < $vt_aa, array( 'ZZ1' => $vt_zz, 'AA0' => $vt_aa ) );

/* ⚠️ XẾP TRƯỚC KHI CẮT TRANG. Cắt rồi mới xếp thì hồ sơ trùng ở trang 4 vẫn ở trang 4 — mà
   "đưa lên đầu" chính là để khỏi lật từng trang đi tìm. Soi trên MÀN HÌNH, không soi hàm. */
$tt_h = vhcc_ns( 'Kế toán' );
t( 'màn hình báo có bao nhiêu hồ sơ trùng', strpos( $tt_h, 'trùng tên hoặc trùng' ) !== false, $tt_h );
t( 'và gắn nhãn "trùng mã" lên hàng', strpos( $tt_h, 'trùng mã' ) !== false );
t( 'và nhãn "trùng tên"', strpos( $tt_h, 'trùng tên' ) !== false, $tt_h );
t( 'hàng trùng có lớp riêng để tô nền', strpos( $tt_h, 'class="hang-trung"' ) !== false );
/* Nhãn phải có CHỮ, không chỉ có màu — người mù màu và bản in đen trắng vẫn phải đọc ra. */
t( 'nhãn là chữ chứ không chỉ là màu', strpos( $tt_h, '>trùng mã<' ) !== false );

/* Vị trí thật trên màn: hàng trùng phải đứng TRƯỚC hàng sạch. */
$vt_zz_h = strpos( $tt_h, '<b>ZZ1</b>' );
$vt_aa_h = strpos( $tt_h, '<b>AA0</b>' );
t( '🔴 trên MÀN HÌNH cũng vậy — và phải xếp TRƯỚC khi cắt trang, không phải sau',
	false !== $vt_zz_h && false !== $vt_aa_h && $vt_zz_h < $vt_aa_h, array( $vt_zz_h, $vt_aa_h ) );

/* 🔴 DÒ TRÊN TOÀN BỘ HỒ SƠ, KHÔNG TRÊN LÁT CẮT ĐANG LỌC.
   Hai người trùng tên ở HAI CƠ SỞ khác nhau: lọc theo một cơ sở thì mỗi bên chỉ thấy đúng một
   dòng, và cả hai cùng trông bình thường — đúng cặp nguy hiểm nhất lại là cặp lọt. Phải dựng
   cảnh có bộ lọc thì mới đo được, chứ danh sách không lọc thì hai cách viết cho kết quả y hệt. */
/* ⚠️ DỌN BẢNG TRƯỚC. Để nguyên mấy cặp trùng ở trên thì lọc cơ sở nào cũng còn một cặp trùng
   trong đó, và nhãn "trùng tên" xuất hiện bất kể hàm dò nhìn toàn bộ hay chỉ nhìn lát cắt —
   phép thử xanh mà không đo được gì. Chỉ để ĐÚNG một cặp, và cặp ấy nằm ở hai cơ sở khác nhau. */
vhcc_dung_bang();
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'CS1', 'ho_ten' => 'Hai Nơi Một Tên',
	'vai_tro' => 'Nhân viên', 'cua_hang' => 'TUTU_BT' ) );
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'CS2', 'ho_ten' => 'Hai Nơi Một Tên',
	'vai_tro' => 'Nhân viên', 'cua_hang' => 'JP_HCM' ) );
$tt_h = vhcc_ns( 'Kế toán', array( 'ncs' => 'TUTU_BT' ) );
t( 'lọc TUTU_BT thì chỉ thấy một trong hai người', strpos( $tt_h, '<b>CS2</b>' ) === false, $tt_h );
t( '🔴 nhưng VẪN báo người ấy trùng tên với người ở cơ sở KHÁC',
	strpos( $tt_h, 'trùng tên (khác cơ sở)' ) !== false, $tt_h );

/* 🔴 VÀ NÓI RÕ ĐÓ LÀ KIỂU NHẸ. Anh Thắng 28/08/2026: *"1 nhân viên mà làm 2 cơ sở, nên hệ
   thống báo trùng. có ảnh hưởng gì không"*. Hai người cùng tên ở hai cơ sở khác nhau thì mỗi
   người vẫn đứng một mình ở cơ sở của họ — bình thường, không phải lỗi. Gộp nó chung một nhãn
   đỏ với kiểu nặng là bắt người đọc tự phân loại 400 hồ sơ, mà cái gì bắt tự phân loại thì họ
   phân một lần rồi thôi đọc. */
t( 'và KHÔNG kêu đây là một người hai hồ sơ',
	strpos( $tt_h, 'một người hai hồ sơ' ) === false, $tt_h );

/* 🔴 CÙNG TÊN + CÙNG CƠ SỞ MỚI LÀ HỎNG THẬT: một người bị tạo hai hồ sơ. Với cả hệ, hai mã NV
   là hai người khác nhau — công chia đôi (không mã nào đủ ngày công chuẩn), lương tính theo
   hai nửa, mỗi hồ sơ một PIN nên đăng nhập bằng PIN nào chỉ thấy nửa ấy. */
vhcc_dung_bang();
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'MOT1', 'ho_ten' => 'Phạm Văn Công',
	'vai_tro' => 'Nhân viên', 'cua_hang' => 'TUTU_BT' ) );
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'MOT2', 'ho_ten' => 'Phạm Văn Công',
	'vai_tro' => 'Nhân viên', 'cua_hang' => 'TUTU_BT' ) );
$tt_h = vhcc_ns( 'Kế toán' );
t( '🔴 cùng tên VÀ cùng cơ sở: kêu là một người hai hồ sơ',
	strpos( $tt_h, 'một người hai hồ sơ' ) !== false, $tt_h );
t( 'và thôi dùng nhãn nhẹ "khác cơ sở" cho cặp ấy',
	strpos( $tt_h, 'trùng tên (khác cơ sở)' ) === false, $tt_h );
/* ⚠️ Nhãn nặng phải có lớp riêng để tô khác màu — nhãn nhẹ đỏ như báo động thì người ta tắt
   mắt với cả hai. */
/* ⚠️ SOI ĐÚNG THẺ, ĐỪNG SOI TÊN LỚP TRẦN — chuỗi "chip-nang" còn nằm trong khối CSS ở đầu
   trang, nên soi trần thì vết "bỏ lớp khỏi thẻ" vẫn xanh vì bắt nhầm sang CSS. */
t( 'nhãn nặng có lớp riêng trên THẺ',
	strpos( $tt_h, 'class="chip-t chip-nang"' ) !== false, $tt_h );
t( 'và có CSS cho lớp ấy', strpos( $tt_h, '.chip-nang{' ) !== false, $tt_h );
/* ⚠️ CƠ SỞ SO CÙNG THƯỚC VỚI CẢ HỆ: `strtoupper( chuan_coso() )`. Thước ấy bỏ qua hoa/thường
   nhưng KHÔNG gộp "TUTU_BT" với "tutu bt" — và đúng ra là không được gộp: phần còn lại của hệ
   (bảng công, chùm cơ sở, quyền theo cơ sở) cũng coi hai chuỗi ấy là HAI cơ sở. Nới riêng ở
   đây là màn này nói một đằng, bảng công tính một nẻo. */
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'cua_hang' => 'tutu_bt' ),
	array( 'ma_nv' => 'MOT2' ) );
$tt_h = vhcc_ns( 'Kế toán' );
t( '🔴 viết cơ sở lệch HOA/THƯỜNG vẫn nhận ra là cùng một chỗ',
	strpos( $tt_h, 'một người hai hồ sơ' ) !== false, $tt_h );

/* ---- "MỘT NGƯỜI HAI HỒ SƠ" — MÃ NÀO ĐANG HOẠT ĐỘNG, MÃ NÀO LÀ HỒ SƠ RÁC ---------------------
   Anh Thắng 29/08/2026, đứng trước đúng cặp MNNV2KVC0113/0177 (Trần Minh Chiến): *"giờ anh muốn
   xóa, nhưng không biết ai là thật, có ô nào hiện ra người có dữ liệu và người không có dữ liệu
   không — dữ liệu chấm công... để biết người đó có hoạt động"*.
   Dùng lại NGUYÊN CẢNH MOT1/MOT2 (Phạm Văn Công, cùng cơ sở TUTU_BT, đã bị gắn "một người hai hồ
   sơ" ở trên) — cho MOT1 có chấm công thật, để MOT2 trắng trơn, rồi soi đúng nhãn đó có nói ra
   sự khác biệt hay không. */
vhcc_cham( 'TUTU_BT', '2026-08-10', 'MOT1', '', '08:00', '17:00' );
vhcc_cham( 'TUTU_BT', '2026-08-20', 'MOT1', '', '08:00', '17:00' );
$dh = VHCC_NhanSu::dem_cham_cong_theo_ma( array( 'MOT1', 'MOT2' ) );
teq( '🔴 đếm đúng số lượt của mã có dữ liệu', 2, $dh['MOT1']['luot'], $dh );
teq( 'và đúng ngày sớm nhất', '2026-08-10', $dh['MOT1']['tu'], $dh );
teq( 'và đúng ngày muộn nhất', '2026-08-20', $dh['MOT1']['den'], $dh );
t( 'mã KHÔNG có dữ liệu thì không có khoá trong mảng trả về (0 lượt)',
	! isset( $dh['MOT2'] ), $dh );

$tt_h = vhcc_ns( 'Kế toán' );
t( '🔴 mã ĐANG hoạt động thì hiện số lượt chấm công ngay cạnh nhãn nghi',
	strpos( $tt_h, '2 lượt chấm công' ) !== false, $tt_h );
t( 'kèm khoảng ngày để đối chiếu nhanh, không phải mở hồ sơ',
	strpos( $tt_h, '2026-08-10' ) !== false && strpos( $tt_h, '2026-08-20' ) !== false, $tt_h );
t( '🔴 mã KHÔNG hoạt động thì nói thẳng là hồ sơ rác, an toàn để xoá',
	strpos( $tt_h, 'Chưa có lượt chấm công nào' ) !== false
	&& strpos( $tt_h, 'an toàn để xoá' ) !== false, $tt_h );

/* ---- "ĐANG CÓ N NGOẠI LỆ" — BỎ HẲN BẢNG SOÁT, GIỮ NGUYÊN CƠ CHẾ GỠ TỪNG Ô -------------------
   Anh Thắng 29/08/2026: "bỏ cái này đi" (chỉ đúng khối "Đang có N ngoại lệ — những chỗ khác mặc
   định theo vai"). Khối bị bỏ là BẢN TÓM TẮT/soát toàn sổ; cơ chế đặt/gỡ ngoại lệ TỪNG Ô ngay
   tại bảng chính (`ba_nut()`, viec `luu_quyen`) không đụng tới — chỉ dò trên trang render, không
   dò tên hàm, vì hàm PHP `the_ngoai_le()` đã xoá hẳn (không còn ai gọi). */
t( '🔴 KHÔNG còn khối tóm tắt "Đang có N ngoại lệ" trên trang',
	strpos( $tt_h, 'ngoại lệ</b> — những chỗ khác mặc định theo vai' ) === false, $tt_h );

/* ---- PHÂN QUYỀN TRANG NỘI BỘ, NGAY TẠI TRANG NGOÀI -----------------------------------------
   🔴 Anh Thắng 28/08/2026, ảnh một Quản lý bị chối ở trang Nội bộ: *"Trang nội bộ là trang
      chung thì ai vẫn được vào mà"*. Đúng — mặc định của `VHNB_Quyen::VIEC` là Nhân viên. Nhưng
      ô ấy trên host đang đặt Admin, và chỗ đổi lại nằm trong wp-admin.
   ⚠️ Trang này đã là nơi trả lời "ai vào được trang nào". Để một trang trong hệ khai quyền ở
      chỗ khác thì người đi tìm sẽ tìm ở đây trước, không thấy, rồi kết luận là không đổi được. */
require_once $goc . '/wordpress/vhcp-noi-bo/includes/class-vhnb-quyen.php';
delete_option( VHNB_Quyen::O );
$tt_h = vhcc_ns( 'Kế toán' );
t( '🔴 trang ngoài có bảng phân quyền Nội bộ',
	strpos( $tt_h, 'Phân quyền trang Nội bộ' ) !== false, $tt_h );
/* 🔴 KHÔNG CÒN Ô "VÀO TRANG" — ANH THẮNG BÁO CHUYỆN NÀY HAI LẦN.
   28/08/2026: *"Trang nội bộ là trang chung thì ai vẫn được vào mà"*. Bản vá lần ấy chỉ kéo ô
   xổ từ wp-admin ra đây rồi thêm một dòng cảnh báo — tức là để nguyên cái bẫy, chỉ dán thêm
   biển báo cạnh nó. 30/08/2026 anh vấp lại đúng chỗ đó: *"trang nội bộ là chung công ty nên ai
   cũng vào được hết, có mật khẩu là vào, đó là lý do anh đặt trang chủ mà"*.
   Nay 'vao' bị gỡ hẳn khỏi `VHNB_Quyen::VIEC`, nên bảng này không còn ô ấy. */
t( '🔴 KHÔNG còn ô xổ cho việc "vào trang" (ai có PIN là vào)',
	strpos( $tt_h, 'name="nb[vao]"' ) === false, $tt_h );
t( 'và nói thẳng ra luật ấy trên màn', strpos( $tt_h, 'ai có PIN là vào ' ) !== false, $tt_h );
t( 'và cho cả ba việc còn lại',
	strpos( $tt_h, 'name="nb[dang]"' ) !== false && strpos( $tt_h, 'name="nb[nhom]"' ) !== false
	&& strpos( $tt_h, 'name="nb[don]"' ) !== false, $tt_h );
/* ⚠️ Nói ra MẶC ĐỊNH ngay cạnh, để người khai biết mình đang lệch khỏi nó bao xa. */
t( 'nói rõ trang Nội bộ vốn là trang CHUNG',
	strpos( $tt_h, 'trang chung</b>' ) !== false, $tt_h );
/* 🔴 QUAN HỆ HAI BẬC — cùng bài với khối ghép mã. Chốt quyền trong `the_quyen_noi_bo()` chưa
   từng rẽ sang false (cửa vào màn cũng là `ho_so`), nên không dựng nổi cảnh và mọi vết phá đều
   xanh. Chốt vẫn giữ vì nó che thay đổi ở chỗ khác; canh chính quan hệ ấy. */
t( '🔴 quyền khai phân quyền Nội bộ không được cao hơn quyền VÀO trang',
	VHCC_Vai::BAC[ VHCC_Vai::QUYEN['ho_so'] ] <= VHCC_Vai::BAC[ VHCC_Vai::QUYEN['ho_so'] ] );

/* Lưu qua ĐÚNG đường màn hình dùng. Luật vẫn ở `VHNB_Quyen` — đây chỉ là ô xổ gọi vào nó. */
$_POST = array( 'nb' => array( 'dang' => 'CUA_HANG_TRUONG', 'don' => 'QUAN_LY' ) );
$tt_bao = VHCC_TrangNS::lam_viec( 'quyen_noi_bo', $U_AD );
$_POST = array();
$tt_c = VHNB_Quyen::cai_dat();
teq( '🔴 lưu được: siết đăng bài lên Cửa hàng trưởng', 'CUA_HANG_TRUONG', (string) $tt_c['dang'] );
teq( 'và ô khác cũng lưu theo', 'QUAN_LY', (string) $tt_c['don'] );

/* 🔴 GỬI 'vao' LÊN CŨNG KHÔNG ĐƯỢC ĂN. Một biểu mẫu dựng tay từ bên ngoài vẫn POST được ô ấy;
   nếu `VHNB_Quyen::dat()` nhận bừa thì bảng quyền lại mọc lại cái bẫy vừa gỡ, và không màn hình
   nào cho thấy nó đang có ở đó. */
$_POST = array( 'nb' => array( 'vao' => 'ADMIN' ) );
VHCC_TrangNS::lam_viec( 'quyen_noi_bo', $U_AD );
$_POST = array();
t( '🔴 POST tay ô "vao" KHÔNG lọt vào bảng quyền',
	! isset( VHNB_Quyen::cai_dat()['vao'] ), VHNB_Quyen::cai_dat() );

/* ⚠️ Bậc lạ thì `VHNB_Quyen::dat()` tự bỏ — trang này KHÔNG lọc lại, để luật nằm một chỗ. */
$_POST = array( 'nb' => array( 'dang' => 'MOT_BAC_BIA_RA' ) );
VHCC_TrangNS::lam_viec( 'quyen_noi_bo', $U_AD );
$_POST = array();
teq( '🔴 bậc lạ bị bỏ, giữ nguyên giá trị cũ', 'CUA_HANG_TRUONG',
	(string) VHNB_Quyen::cai_dat()['dang'] );

/* Cửa hàng trưởng gọi thẳng đường ấy vẫn bị chối — giấu khối không phải là chặn. */
$_POST = array( 'nb' => array( 'dang' => 'ADMIN' ) );
$tt_bao = VHCC_TrangNS::lam_viec( 'quyen_noi_bo',
	array( 'name' => 'CHT', 'role' => 'CUA_HANG_TRUONG', 'coso' => 'TUTU_BT' ) );
$_POST = array();
t( '🔴 Cửa hàng trưởng gọi thẳng vẫn bị chối', isset( $tt_bao[0]['loi'] ), $tt_bao );
teq( 'và quyền KHÔNG bị siết', 'CUA_HANG_TRUONG', (string) VHNB_Quyen::cai_dat()['dang'] );
delete_option( VHNB_Quyen::O );

/* ---- GHÉP HAI MÃ VỀ MỘT NGƯỜI — NĂNG LỰC MÁY CHỦ, MÀN HÌNH ĐÃ BỎ ---------------------------
   🔴 Anh Thắng 29/08/2026, sau ba lượt chỉnh chỗ đặt/khung khối "Ghép hai mã về một người" vẫn
      không đúng ý, chốt "xóa luôn" khi được hỏi lại rõ mất những gì. Màn hình (the_ghep_ma()) đã
      BỎ HẲN — không còn khối ấy trên trang, không còn form gõ tay, không còn bảng dò/danh sách
      44 cặp. NĂNG LỰC ở tầng máy chủ (khai_ma_song_song()/viec_ghep_ma()/viec_bo_ghep_ma()/
      viec_don_ma()/goi_y_ghep_ma()) GIỮ NGUYÊN — cùng cách go_ngoai_le/ngoai_le_phang() được
      giữ khi the_ngoai_le() bị bỏ trước đó. Các phép thử dưới đây vì vậy gọi THẲNG các hàm/viec
      đó, không còn qua vhcc_ns() để soi CHỮ trên màn — không có màn nào để soi nữa. */
/* ⚠️ Ghép ảnh hưởng CẢ CHUỖI (công của một mã chảy sang mã khác) nên cửa là `co_quan_tri_nv()`
   = quyền `ngoai_coso` = bậc Quản lý trở lên. Kế toán bậc 4 CAO HƠN Quản lý bậc 3 nên vẫn
   được — thang bậc, bậc trên làm được mọi việc bậc dưới. Người bị chối là Cửa hàng trưởng. */
t( 'và người đủ bậc vào trang thì cũng đủ bậc ghép',
	VHCC_NhanSu::co_quan_tri_nv( array( 'role' => 'Kế toán' ) ) );
t( '🔴 quyền GHÉP không được cao hơn quyền VÀO trang — nếu không, chốt ở khối ghép thành mã chết',
	VHCC_Vai::BAC[ VHCC_Vai::QUYEN['ngoai_coso'] ] <= VHCC_Vai::BAC[ VHCC_Vai::QUYEN['ho_so'] ],
	array( VHCC_Vai::QUYEN['ngoai_coso'], VHCC_Vai::QUYEN['ho_so'] ) );

/* Khai một cặp qua đúng viec máy chủ — không còn "đường màn hình dùng" để nói tới nữa. */
$_POST = array( 'ma_a' => 'MOT1', 'ma_b' => 'MOT2', 'gm_ten' => 'Phạm Văn Công',
	'gm_ly_do' => 'tạo hồ sơ hai lần' );
$tt_bao = VHCC_TrangNS::lam_viec( 'ghep_ma', $U_AD );
$_POST = array();
$tt_txt = (string) wp_json_encode( $tt_bao );
t( 'Admin ghép được', strpos( $tt_txt, 'Đã ghép' ) !== false, $tt_bao );
/* ⚠️ `ma_that()` CHỈ dịch khi mã ấy KHÔNG có hồ sơ — mã có hồ sơ là mã thật, trả chính nó.
   Đó là chốt đúng: dịch một mã đang có hồ sơ là ném công của người ta sang hồ sơ khác. Nên
   dựng cảnh dịch bằng một mã máy chưa có hồ sơ. */
teq( 'mã CÓ hồ sơ thì trả chính nó, không dịch', 'MOT2', VHCC_NhanSu::ma_that( 'MOT2' ) );
VHCC_NhanSu::khai_ma_song_song( $U_AD, 'MOT1', 'MAYCU9', 'Phạm Văn Công', 'mã cũ trên máy' );
teq( '🔴 mã máy chưa có hồ sơ thì chảy về mã chính', 'MOT1', VHCC_NhanSu::ma_that( 'MAYCU9' ) );
teq( 'cặp vừa khai nằm đúng trong sổ ma_song_song',
	1, count( array_filter( VHCC_NhanSu::ds_ma_song_song(),
		function ( $r ) { return 'tạo hồ sơ hai lần' === $r['ly_do']; } ) ) );

/* ---- NÚT "GHÉP VỚI HỒ SƠ KIA" NGAY TẠI DÒNG — không bắt gõ tay ở khối "Ghép hai mã" ----------
   Anh Thắng 29/08/2026, sau ba lượt chỉnh chỗ đặt/khung bảng "Ghép hai mã" vẫn chê: *"cùng 1 nv
   có khác gì đâu"*, *"chả khác gì, cùng mã thì ghép lại thôi"*. Dựng CẶP MÃ RIÊNG (GV1/GV2,
   "Đặng Duy Ghép") — không đụng MOT1/MOT2 đã dùng cho phép thử `ghep_ma` ở trên, vì
   khai_ma_song_song() từ chối một cặp ĐÃ khai; đụng vào MOT1/MOT2 sẽ làm hỏng phép thử đó nếu
   thứ tự file đổi sau này. KHÔNG gọi vhcc_dung_bang() ở đây — hàm đó XOÁ SẠCH MỌI BẢNG (kể cả
   `ma_song_song` của MOT1/MOT2 vừa khai xong ở trên), làm hỏng các phép thử "bỏ ghép" phía sau
   dựa vào đúng cặp đó. Mã GV1/GV2 mới toanh, chèn thêm không đụng gì tới dữ liệu đang có. */
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'GV1', 'ho_ten' => 'Đặng Duy Ghép',
	'vai_tro' => 'Nhân viên', 'cua_hang' => 'TUTU_BT' ) );
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'GV2', 'ho_ten' => 'Đặng Duy Ghép',
	'vai_tro' => 'Nhân viên', 'cua_hang' => 'TUTU_BT' ) );
/* GV1 có chấm công, GV2 không — nút phải tự chọn GV1 làm mã CHÍNH (nhiều lượt hơn), không phải
   cứ mã nào đứng trước trong bảng. */
vhcc_cham( 'TUTU_BT', '2026-08-05', 'GV1', '', '08:00', '17:00' );
vhcc_cham( 'TUTU_BT', '2026-08-06', 'GV1', '', '08:00', '17:00' );
vhcc_cham( 'TUTU_BT', '2026-08-07', 'GV1', '', '08:00', '17:00' );

$tt_h = vhcc_ns( 'Admin' );
t( '🔴 có nút "Ghép với GV2" ngay tại dòng, không phải mở bảng khác',
	strpos( $tt_h, 'Ghép với GV2' ) !== false, $tt_h );
t( '🔴 giá trị nút tự chọn mã NHIỀU chấm công hơn (GV1) làm mã CHÍNH',
	strpos( $tt_h, 'name="ghep_voi" value="GV1|GV2"' ) !== false, $tt_h );
t( 'không lộ chiều ngược (GV2 làm chính) ra nút nào',
	strpos( $tt_h, 'value="GV2|GV1"' ) === false, $tt_h );

/* ⚠️ Vai bậc thấp (Cửa hàng trưởng) gọi THẲNG đường ấy vẫn bị chối ở LÕI — cùng cách phép thử
   "Cửa hàng trưởng gọi thẳng đường ấy vẫn bị chối" của khối "Ghép hai mã" đầy đủ đang làm ngay
   bên dưới (mảng vai trò trần, không qua vhcc_ns()/token). Test TRƯỚC khi Admin ghép thật —
   sau đó cặp coi như đã ghép, gọi lại sẽ luôn bị chối vì "đã khai rồi" chứ không phải vì thiếu
   quyền, và hai lý do đó không được lẫn vào nhau. */
$_POST = array( 'ghep_voi' => 'GV1|GV2' );
$tt_bao_cht = VHCC_TrangNS::lam_viec( 'ghep_voi_nv',
	array( 'name' => 'CHT', 'role' => 'Cửa hàng trưởng', 'coso' => 'TUTU_BT' ) );
$_POST = array();
t( '🔴 Cửa hàng trưởng KHÔNG ghép được — chối vì THIẾU QUYỀN, không phải vì đã khai',
	isset( $tt_bao_cht[0]['loi'] ) && strpos( $tt_bao_cht[0]['loi'], 'chỉ Admin / Quản lý' ) !== false,
	$tt_bao_cht );

/* Bấm nút = gửi đúng POST `ghep_voi=GV1|GV2` — không qua ô nhập tay `ma_a`/`ma_b`. */
$_POST = array( 'ghep_voi' => 'GV1|GV2' );
$tt_bao = VHCC_TrangNS::lam_viec( 'ghep_voi_nv', $U_AD );
$_POST = array();
$tt_txt = (string) wp_json_encode( $tt_bao );
t( '🔴 bấm nút ghép được thật, không chỉ vẽ ra cho có',
	strpos( $tt_txt, 'Đã ghép' ) !== false, $tt_bao );
teq( 'và chảy đúng chiều: GV2 (phụ) dịch về GV1 (chính) khi GV2 hết hồ sơ',
	'GV1', ( function () {
		global $wpdb;
		$wpdb->delete( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'GV2' ) );
		return VHCC_NhanSu::ma_that( 'GV2' );
	} )() );
/* Bấm lần hai cùng cặp: khai_ma_song_song() phải từ chối (đã khai rồi) — không được âm thầm
   ghi đè hay tạo thêm một dòng trùng trong sổ ma_song_song. */
$_POST = array( 'ghep_voi' => 'GV1|GV2' );
$tt_bao2 = VHCC_TrangNS::lam_viec( 'ghep_voi_nv', $U_AD );
$_POST = array();
t( 'bấm lại cùng cặp thì bị chối, không ghi đè',
	isset( $tt_bao2[0]['loi'] ) && strpos( $tt_bao2[0]['loi'], 'đã khai rồi' ) !== false, $tt_bao2 );

/* Cửa hàng trưởng gọi THẲNG đường ấy vẫn bị chối — cửa thật ở lõi, không phải ở chỗ giấu khối.
   ⚠️ Giấu nút không phải là chặn: ai đọc được gói tin thì gọi thẳng được. */
$U_CHT_G = array( 'name' => 'CHT', 'role' => 'CUA_HANG_TRUONG', 'coso' => 'TUTU_BT' );
$_POST = array( 'ma_a' => 'MOT1', 'ma_b' => 'MOT9', 'gm_ten' => 'X', 'gm_ly_do' => 'y' );
$tt_bao = VHCC_TrangNS::lam_viec( 'ghep_ma', $U_CHT_G );
$_POST = array();
t( '🔴 Cửa hàng trưởng gọi thẳng đường ghép vẫn bị chối',
	isset( $tt_bao[0]['loi'] ), $tt_bao );
teq( 'và không có cặp nào thêm', 'MOT9', VHCC_NhanSu::ma_that( 'MOT9' ) );

/* ---- "SỬA LẠI TRÊN MÁY" / "GỠ KHỎI MÁY" — nút ở cột Họ tên --------------------------------
   Anh Thắng 29/08/2026: *"thêm tinh năng, xóa, sửa trường hợp lỗi hoặc nhân viên nghỉ việc"*.
   Sửa hồ sơ (tên/ảnh/giới tính) qua ô "sửa ▾" chỉ ghi lên WEB — máy chấm công không tự cập nhật
   theo, vì nó chỉ nhận lệnh đúng MỘT lần lúc TẠO hồ sơ (xem day_len_may()). Hai nút này đẩy lại
   / gỡ trên máy VẬT LÝ, không đụng gì tới hồ sơ hay lịch sử chấm công trên web.
   Dùng lại GV1 (còn hồ sơ; GV2 đã xoá ở khối trên khi ghép). Dựng RIÊNG một máy mang serial
   'SN-GV' cho TUTU_BT — không đụng máy của phép thử khác, và tự dọn (xoá 'SN-GV') ở cuối khối
   để không làm lệch số đếm máy của các phép thử phía sau. */
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'queue' ) );
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'SN-GV', 'mac' => '', 'cua_hang' => 'TUTU_BT' ) );
$may_cs_hien = VHCC_DB::rows( "SELECT * FROM " . VHCC_DB::t( 'may' ) . " WHERE cua_hang='TUTU_BT'" );
t( '(dàn cảnh) TUTU_BT có ít nhất máy vừa gán', count( $may_cs_hien ) > 0, $may_cs_hien );

$r_sua = VHCC_NhanSu::sua_lai_tren_may( $U_AD, 'GV1' );
