teq( 'chuyển 1 hàng', 1, (int) $kq_d['chuyen'] );
teq( 'gộp 1 hàng', 1, (int) $kq_d['gop'] );

teq( '🔴 mã phụ KHÔNG còn hàng nào — lưới thôi vẽ hai dòng', 0, (int) $wpdb->get_var(
