/* ---------------------------------------------------------------------------------------------
 * LƯỚI Ô TÍCH NHÌN QUA MẮT NGƯỜI KHAI CHỈ PHỤ TRÁCH MỘT VÀI CƠ SỞ
 * ---------------------------------------------------------------------------------------------
 * ⚠️ PHẢI KHOÁ `cong_tat_ca` CHO NGƯỜI KHAI THÌ MỚI THỬ ĐƯỢC BA NHÁNH DƯỚI ĐÂY. Vai Kế toán —
 *    bậc thấp nhất qua nổi cửa trang này — mặc định phụ trách MỌI cơ sở, nên `$duoc` luôn đúng
 *    và ba nhánh "cơ sở mình không phụ trách" không bao giờ chạy. Chúng sống cho ngày có kế
 *    toán vùng, và bảng chia đầu việc là đường tạo ra ngày ấy.
 */
/**
 * Cắt lấy đúng MỘT hàng `<tr>` — hàng chứa cái mốc truyền vào.
 *
 * 🔴 SOI CẢ TRANG LÀ XANH GIẢ. Một trang nhân sự có mấy chục hàng, mỗi hàng một lưới ô tích;
 *    `strpos( $ca_trang, 'disabled' )` khớp ở hàng bất kỳ, kể cả hàng của người khác. Phép thử
 *    ấy vẫn xanh khi đúng hàng ta quan tâm đã hỏng.
 */
function vhcc_khuc( $html, $moc ) {
	$i = strpos( $html, $moc );
	if ( false === $i ) { return ''; }
	$d = strrpos( substr( $html, 0, $i ), '<tr' );
	$c = strpos( $html, '</tr>', $i );
	if ( false === $d || false === $c ) { return ''; }
	return substr( $html, $d, $c - $d );
}

$cs_nl_cu = get_option( VHCC_Vai::O_NGOAI_LE );
$ns_ad = array( 'name' => 'Sếp NS', 'role' => 'Admin', 'coso' => '', 'ma_nv' => 'NSAD' );
VHCC_Vai::dat_ngoai_le( $ns_ad, 'nv:QN3', 'cong_tat_ca', 'khoa' );
/* CV1 làm ở TUTU_BT (người khai phụ trách) VÀ ở KHO_LA (không phụ trách). */
$wpdb->update( VHCC_DB::t( 'nhan_vien' ),
	array( 'cua_hang' => 'TUTU_BT', 'coso_phu' => 'KHO_LA' ), array( 'ma_nv' => 'CV1' ) );
/* Một cơ sở có trong danh mục mà người khai không quản, CV1 cũng không khai. */
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'CV_XA', 'ho_ten' => 'Người Xa',
	'cua_hang' => 'KHO_XA', 'vai_tro' => 'Nhân viên' ) );
$db_v = vhcc_ns( 'Kế toán' );
$hang_cv1 = vhcc_khuc( $db_v, 'name="cs[CV1][]"' );

t( 'ô cơ sở MÌNH phụ trách thì tích được',
	preg_match( '/name="cs\[CV1\]\[\]" value="TUTU_BT"(?![^>]*disabled)/', $hang_cv1 ) === 1, $hang_cv1 );
/* 🔴 Cơ sở người ta đang khai mà mình không phụ trách: BÀY RA nhưng KHOÁ. Giấu đi thì người
   khai không hiểu vì sao bảng công của người này lại có một cột lạ; mở ra thì một cửa hàng
   trưởng vùng gỡ được người khỏi cơ sở của vùng khác mà bên kia không hay. */
t( '🔴 ô cơ sở mình KHÔNG phụ trách thì bày ra nhưng KHOÁ',
	preg_match( '/name="cs\[CV1\]\[\]" value="KHO_LA"[^>]*disabled/', $hang_cv1 ) === 1, $hang_cv1 );
/* 🔴 Ô khoá KHÔNG gửi giá trị lên — phải có ô ẩn chở hộ, kẻo bấm Lưu là gỡ mất cơ sở ấy.
   Đây là cách hỏng tệ nhất trong cả khối: màn hình báo "đã lưu", không ai bấm nhầm gì cả, mà
   người ta lặng lẽ rơi khỏi một cửa hàng. */
t( '🔴 và có ô ẩn chở hộ giá trị của ô khoá',
	preg_match( '/<input type="hidden" name="cs\[CV1\]\[\]" value="KHO_LA">/', $hang_cv1 ) === 1, $hang_cv1 );
t( 'cơ sở mình không quản mà người ta cũng không khai thì KHÔNG bày ra',
	strpos( $hang_cv1, 'value="KHO_XA"' ) === false, $hang_cv1 );
/* Cơ sở khai trong `coso_phu` chưa từng xuất hiện ở cột `cua_hang` nào -> `ds_coso()` không
   biết nó. Lưới vẫn phải có, nếu không thì bấm Lưu là mất. */
t( '🔴 cơ sở người ta đang khai mà danh mục chưa biết vẫn có mặt trong lưới',
	substr_count( $hang_cv1, 'value="KHO_LA"' ) >= 1, $hang_cv1 );

/* 🔴 BỎ TÍCH HẾT QUA MÀN HÌNH: hàng vẫn phải được xử, và cơ sở KHOÁ vẫn phải ở lại.
   Trình duyệt không gửi `cs[CV1]` nào khi bỏ tích sạch; `cs_co[CV1]` là thứ duy nhất nói
   "hàng này có trên trang". Ở đây trang gửi lên ô ẩn của cơ sở khoá, nên KHO_LA còn. */
/* 🔴 GỬI LƯỢT NÀY **KHÔNG KÈM** BẢNG Ô QUYỀN — đó là nửa còn lại của phép thử.
   `viec_luu()` từng chối cả lượt khi riêng `$_POST['o']` rỗng, kèm câu "Biểu mẫu không hợp
   lệ": ba nhóm kia (vai, cơ sở, quyền trang Nội bộ) bị vứt sạch dù hoàn toàn hợp lệ. Trang
   thật luôn vẽ cột quyền nên `o` luôn có mặt và lỗi ấy không lộ ra — chỉ có phép thử này gọi
   thẳng mới thấy. Thêm `'o' => …` vào đây là phép thử tự bịt mắt mình. */
$cs_h = vhcc_ns_luu( 'Kế toán', 'QN3', array( 'cs' => array( 'CV1' => array( 'KHO_LA' ) ),
	'cs_co' => array( 'CV1' => '1' ) ) );
t( '🔴 lượt Lưu KHÔNG kèm bảng ô quyền vẫn chạy, không bị gạt là "biểu mẫu không hợp lệ"',
	strpos( $cs_h, 'Biểu mẫu không hợp lệ' ) === false
	&& strpos( $cs_h, 'sang cơ sở khác' ) !== false, $cs_h );
teq( '🔴 bỏ tích hết qua màn hình thì cơ sở phụ trách rụng, cơ sở khoá ở lại', 'KHO_LA',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'CV1' ) ) ) );


/* 🔴 BỎ TÍCH **SẠCH SÀNH SANH**: không một `cs[MA]` nào lên, chỉ còn ô ẩn `cs_co[MA]`.
   Đây là ca duy nhất phân biệt được "duyệt theo `cs_co`" với "duyệt theo `cs`" — phép trên
   không phân biệt nổi, vì ở đó ô khoá vẫn chở một giá trị lên nên `cs[CV1]` có mặt. Duyệt
   nhầm theo `cs` thì hàng này biến mất khỏi lượt lưu: người ta bỏ tích, bấm Lưu, thấy y
   nguyên, bấm lại mấy lượt rồi thôi — và không có câu lỗi nào để mà đi hỏi. */
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'CV_HET', 'ho_ten' => 'Bỏ Tích Hết',
	'cua_hang' => 'TUTU_BT', 'vai_tro' => 'Nhân viên' ) );
vhcc_ns_luu( 'Kế toán', 'QN3', array( 'cs_co' => array( 'CV_HET' => '1' ) ) );
teq( '🔴 bỏ tích SẠCH (không gửi cs[MA] nào) thì hồ sơ hết cơ sở', 0,
	count( VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'CV_HET' ) ) ) );

$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'nhan_vien' ) . " WHERE ma_nv IN ('CV_XA','CV_HET')" );
update_option( VHCC_Vai::O_NGOAI_LE, $cs_nl_cu );
VHCC_Vai::quen_nho_nl();
delete_option( VHCC_Cong::O );

/* =============================================================================================
 * MỘT Ô CHUNG: TÍCH CƠ SỞ NÀO LÀ LÀM VIỆC **VÀ** QUẢN Ở ĐÓ.
 * =============================================================================================
 * Anh Thắng 31/08/2026: *"thay vì cửa hàng trưởng làm ở 1 cơ sở đó, tích chọn quản lý các cơ sở
 * khác, thì có thể quản lý các nhân viên ở các cơ sở khác"* — và chốt **một ô chung**.
 *
 * Quyền đi theo VAI, phạm vi đi theo ô này: nhân viên tích 2 cơ sở thì chỉ là làm ở 2 nơi (họ
 * không có `cong_coso`); cửa hàng trưởng tích 3 thì quản người ở cả 3.
 */
vhcc_dung_bang();
$mo_ad = array( 'name' => 'Sếp', 'role' => 'Admin', 'coso' => '', 'ma_nv' => 'MOAD' );
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'MO1', 'ho_ten' => 'Một Nơi',
	'cua_hang' => 'CS_A', 'vai_tro' => 'Nhân viên' ) );

/* (a) Đặt ba cơ sở một lượt -> rải vào hai cột, đọc ra đủ ba. */
$r_mo = VHCC_NhanSu::dat_ds_coso( $mo_ad, 'MO1', array( 'KHU_A', 'KHU_B', 'KHU_C' ) );
t( 'đặt được nhiều cơ sở một lượt', ! empty( $r_mo['ok'] ) && ! empty( $r_mo['doi'] ), $r_mo );
teq( '🔴 đọc ra đủ ba cơ sở', 'KHU_A · KHU_B · KHU_C',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'MO1' ) ) ) );
teq( 'cơ sở đầu vào cột cua_hang', 'KHU_A', VHCC_NhanSu::ho_so( 'MO1' )['cua_hang'] );
teq( 'phần còn lại vào coso_phu', 'KHU_B, KHU_C', VHCC_NhanSu::ho_so( 'MO1' )['coso_phu'] );

/* (a2) Tích trùng một cơ sở (hai ô cùng tên, hoặc một ô chở sẵn chuỗi ghép) -> chỉ còn MỘT.
       Giữ cả hai thì `coso_phu` thành "KHU_B, KHU_B", bảng công đẻ hai hàng cho một nơi, và
       `ds_coso_hs()` đếm ra ba cơ sở cho người làm ở hai. */
VHCC_NhanSu::dat_ds_coso( $mo_ad, 'MO1', array( 'KHU_A', 'khu_b', 'KHU_B', 'KHU_A' ) );
teq( '🔴 tích trùng cơ sở thì chỉ còn MỘT', 'KHU_A · khu_b',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'MO1' ) ) ) );
teq( 'và coso_phu không đọng tên lặp', 'khu_b', VHCC_NhanSu::ho_so( 'MO1' )['coso_phu'] );
VHCC_NhanSu::dat_ds_coso( $mo_ad, 'MO1', array( 'KHU_A', 'KHU_B', 'KHU_C' ) );

/* (b) Gửi lại đúng bộ ấy nhưng ĐẢO THỨ TỰ -> không tính là đổi. Kéo lại thứ tự tích không phải
       là chuyển cơ sở của ai, mà mỗi lượt "đổi" đều reset quyền riêng. */
$r_dao = VHCC_NhanSu::dat_ds_coso( $mo_ad, 'MO1', array( 'KHU_C', 'KHU_A', 'KHU_B' ) );
t( '🔴 đảo thứ tự KHÔNG tính là đổi cơ sở',
	! empty( $r_dao['ok'] ) && empty( $r_dao['doi'] ), $r_dao );

/* (c) Bỏ tích hết -> thôi làm ở đâu cả, đúng ý người bấm. */
VHCC_NhanSu::dat_ds_coso( $mo_ad, 'MO1', array() );
teq( 'bỏ tích hết thì không còn cơ sở nào', 0,
	count( VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'MO1' ) ) ) );

/* (d) 🔴 PHẢI PHỤ TRÁCH CẢ CƠ SỞ CŨ LẪN CƠ SỞ MỚI.
       Thiếu vế "mới" là đẩy người sang cơ sở mình không có trách nhiệm; thiếu vế "cũ" là hút
       người của cơ sở khác về mình mà bên kia không hay biết. Hai chiều, hai phép.

   ⚠️ PHẢI KHOÁ `cong_tat_ca` THÌ HAI PHÉP NÀY MỚI CHẠM ĐƯỢC TỚI CHỐT. Vai Kế toán (bậc 4) là
      bậc thấp nhất qua được cửa `ho_so`, mà `cong_tat_ca` chỉ cần Quản lý (bậc 3) — nên theo
      thang mặc định, ai sửa được hồ sơ thì cũng phụ trách sẵn MỌI cơ sở, và chốt bên dưới
      không bao giờ nói. Nó sống nhờ bảng chia đầu việc: một kế toán vùng bị khoá
      `cong_tat_ca` là có thật, và cũng chính là ngày ta cần chốt ấy. Giữ chốt, và thử nó ở
      đúng hình dạng nó sống. */
$cs_ngoai_le = get_option( VHCC_Vai::O_NGOAI_LE );
VHCC_NhanSu::dat_ds_coso( $mo_ad, 'MO1', array( 'KHU_A', 'KHU_B' ) );
$cht_a = array( 'name' => 'Kế toán vùng A', 'role' => 'Kế toán', 'coso' => 'KHU_A', 'ma_nv' => 'TRA' );
$r_nl = VHCC_Vai::dat_ngoai_le( $mo_ad, 'nv:TRA', 'cong_tat_ca', 'khoa' );
t( 'khoá được "xem công mọi cơ sở" cho riêng một người', ! empty( $r_nl['ok'] ), $r_nl );
t( 'và người ấy hết phụ trách cơ sở lạ', ! VHCC_NhanSu::co_quyen_coso( $cht_a, 'KHU_LA' ) );

$r_them = VHCC_NhanSu::dat_ds_coso( $cht_a, 'MO1', array( 'KHU_A', 'KHU_B', 'KHU_LA' ) );
t( '🔴 thêm cơ sở mình KHÔNG phụ trách: bị chối',
	empty( $r_them['ok'] ) && stripos( $r_them['error'], 'không phụ trách' ) !== false, $r_them );
/* Vế "cũ": người này đang thuộc KHU_B mà mình không phụ trách -> gỡ họ về một mình KHU_A cũng
   bị chối. Thiếu vế ấy thì bất kỳ ai phụ trách MỘT cơ sở của người ta là kéo được họ ra khỏi
   mọi cơ sở còn lại. */
$r_bo = VHCC_NhanSu::dat_ds_coso( $cht_a, 'MO1', array( 'KHU_A' ) );
t( '🔴 GỠ người khỏi cơ sở mình không phụ trách: cũng bị chối',
	empty( $r_bo['ok'] ) && stripos( $r_bo['error'], 'không phụ trách' ) !== false, $r_bo );
teq( 'và hồ sơ không suy suyển', 'KHU_A · KHU_B',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'MO1' ) ) ) );
/* Nhưng cơ sở MÌNH phụ trách thì sửa được bình thường. */
$cht_ab = array( 'name' => 'Kế toán vùng AB', 'role' => 'Kế toán', 'coso' => 'KHU_A, KHU_B', 'ma_nv' => 'TRAB' );
VHCC_Vai::dat_ngoai_le( $mo_ad, 'nv:TRAB', 'cong_tat_ca', 'khoa' );
$r_ok = VHCC_NhanSu::dat_ds_coso( $cht_ab, 'MO1', array( 'KHU_A' ) );
t( 'phụ trách cả hai thì gỡ được', ! empty( $r_ok['ok'] ), $r_ok );
update_option( VHCC_Vai::O_NGOAI_LE, $cs_ngoai_le );
VHCC_Vai::quen_nho_nl();

/* (e) Bậc dưới Kế toán không đụng được — đổi cơ sở là chuyển công và lương. */
$r_cht = VHCC_NhanSu::dat_ds_coso(
	array( 'name' => 'CHT', 'role' => 'Cửa hàng trưởng', 'coso' => 'KHU_A' ), 'MO1', array( 'KHU_A', 'KHU_B' ) );
/* ⚠️ SOI CẢ CÂU CHỐI, KHÔNG CHỈ SOI `ok` RỖNG. Hai tầng gác cùng dẫn tới "bị chối" ở đây:
   cửa vai (`co_sua_ho_so`) và chốt từng cơ sở (`co_quyen_coso`) — Cửa hàng trưởng trượt cả
   hai. Chỉ soi `ok` thì gỡ mất cửa vai mà phép thử vẫn xanh, và ngày ấy một cửa hàng trưởng
   chuyển được người TRONG cơ sở mình sang cơ sở mình — tức tự sắp lại bảng lương của mình. */
t( '🔴 Cửa hàng trưởng KHÔNG tự đổi cơ sở của người khác', empty( $r_cht['ok'] ), $r_cht );
t( 'và bị chối ngay ở CỬA VAI, nói rõ cần Kế toán trở lên',
	stripos( isset( $r_cht['error'] ) ? $r_cht['error'] : '', 'Kế toán trở lên' ) !== false, $r_cht );

/* (f) 🔴 VÀ ĐÂY LÀ ĐIỀU ANH THẮNG CẦN: tích thêm cơ sở là quản được người ở đó.
       Chị trưởng tích KHU_A + KHU_B thì thấy và sửa được người của KHU_B, dù "chỗ làm chính" vẫn
       là KHU_A. Một ô chung, hai nghĩa. */
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'NVB', 'ho_ten' => 'Người Ở B',
	'cua_hang' => 'KHU_B', 'vai_tro' => 'Nhân viên' ) );
$tr_1 = array( 'name' => 'Trưởng Một Nơi', 'role' => 'CUA_HANG_TRUONG', 'coso' => 'KHU_A', 'ma_nv' => 'T1' );
$tr_2 = array( 'name' => 'Trưởng Hai Nơi', 'role' => 'CUA_HANG_TRUONG', 'coso' => 'KHU_A, KHU_B', 'ma_nv' => 'T2' );
t( 'trưởng chỉ tích KHU_A: KHÔNG quản được người của KHU_B',
	! VHCC_NhanSu::co_quyen_ho_so( $tr_1, VHCC_NhanSu::ho_so( 'NVB' ) ) );
t( '🔴 tích thêm KHU_B thì quản được người của KHU_B',
	VHCC_NhanSu::co_quyen_ho_so( $tr_2, VHCC_NhanSu::ho_so( 'NVB' ) ) );
$ds_b = VHCC_NhanSu::ds_nhan_vien( $tr_2, 'KHU_B' );
teq( 'và thấy họ trong danh sách nhân sự của KHU_B', 1, count( $ds_b ) );
/* ⚠️ NHÂN VIÊN tích nhiều cơ sở thì VẪN chỉ là làm ở nhiều nơi — quyền đi theo VAI. */
$nv_2 = array( 'name' => 'NV Hai Nơi', 'role' => 'Nhân viên', 'coso' => 'KHU_A, KHU_B', 'ma_nv' => 'N2' );
t( '🔴 nhân viên tích 2 cơ sở KHÔNG vì thế mà quản được ai',
	! VHCC_NhanSu::co_quyen_ho_so( $nv_2, VHCC_NhanSu::ho_so( 'NVB' ) ) );

vhcc_dung_bang();

/* ---- 64. SỬA NGAY TẠI HÀNG, KHÔNG NHẢY TRANG ----
   Anh Thắng 27/08/2026: *"thay vì nhảy ra 1 trang khác thì mình xổ xuống được không, chứ nhảy
   trang thì lại phải đi dò lại người 2, 3 rất lâu, sửa xong anh đóng nó gọn lại là được"*.

   🔴 Cái mất khi nhảy trang không chỉ là thời gian: mất bộ lọc, mất số trang, mất chỗ đang
   đứng — nên sửa xong người thứ nhất là phải làm lại từ đầu để tới người thứ hai. */
vhcc_dung_bang();
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'SN1', 'ho_ten' => 'Người Sửa',
	'sdt' => '0900000000', 'pin_dang_nhap' => '778899', 'vai_tro' => 'Nhân viên',
	'cua_hang' => 'TUTU_BT' ) );
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'SN2', 'ho_ten' => 'Người Khác',
	'vai_tro' => 'Nhân viên', 'cua_hang' => 'TUTU_BT' ) );

$sn_h = vhcc_ns( 'Admin' );
t( 'chưa mở thì KHÔNG có hàng sửa nào', strpos( $sn_h, 'value="sua_nhanh"' ) === false, $sn_h );
t( 'mỗi hàng có nút mở ô sửa', strpos( $sn_h, 'sửa ▾' ) !== false, $sn_h );
t( '🔴 nút ấy trỏ về CHÍNH trang này (sua_o), không sang trang khác',
	strpos( $sn_h, 'sua_o=SN1' ) !== false, $sn_h );
t( 'và vẫn giữ đường sang hồ sơ đầy đủ cho mấy trường ít dùng',
	strpos( $sn_h, 'đầy đủ ↗' ) !== false && strpos( $sn_h, 'sua=SN1' ) !== false );

$sn_h = vhcc_ns( 'Admin', array( 'sua_o' => 'SN1' ) );
t( '🔴 mở ra thì có hàng sửa ngay trong bảng', strpos( $sn_h, 'value="sua_nhanh"' ) !== false, $sn_h );
t( 'điền sẵn tên cũ', strpos( $sn_h, 'value="Người Sửa"' ) !== false );
t( 'điền sẵn SĐT cũ', strpos( $sn_h, 'value="0900000000"' ) !== false );
/* ⚠️ LẦN THỨ TƯ CÙNG CÁI BẪY (sau cty-bq, o-q, chip-t): soi tên lớp TRẦN thì luôn trúng luật
   CSS ở đầu trang. Soi thuộc tính `class="…"` của chỗ DÙNG. */
t( 'hàng của người ấy được đánh dấu để mắt tìm lại được',
	strpos( $sn_h, 'class="dang-sua"' ) !== false, $sn_h );
t( 'có mỏ neo để trình duyệt cuộn thẳng tới hàng đó',
	strpos( $sn_h, 'id="hs' . substr( md5( 'SN1' ), 0, 8 ) . '"' ) !== false, $sn_h );
t( 'có nút Đóng', strpos( $sn_h, '>Đóng</a>' ) !== false );
/* 🔴 NÚT ĐÓNG PHẢI QUAY VỀ CHÍNH TRANG NÀY, không nhảy sang trang khác — nếu không thì "đóng
   gọn lại" hoá ra lại là rời trang, đúng cái anh Thắng muốn tránh.
   ⚠️ Phép thử này TỪNG KHÔNG ĐO ĐƯỢC GÌ: bản giả `remove_query_arg()` trong `wp-stub.php` trả
      về một HẰNG SỐ CỨNG (`?vhcc_qt=1`), nên mọi đường dẫn đi qua nó đều ra cùng một chuỗi bất
      kể mã thật làm gì. Một bản giả sai còn tệ hơn không có bản giả: không có thì phép thử
      chết và mình biết ngay, còn sai thì nó xanh và mình tin. Đã sửa bản giả cho đúng. */
if ( preg_match( '/<a class="nut" href="([^"]+)">Đóng<\/a>/', $sn_h, $sn_d ) ) {
	t( '🔴 nút Đóng quay về CHÍNH trang nhân sự, không sang trang khác',
		strpos( $sn_d[1], 'vhcc_ns' ) !== false && strpos( $sn_d[1], 'vhcc_qt' ) === false, $sn_d[1] );
	t( 'và bỏ hẳn tham số sua_o (đóng thật, không mở lại)',
		strpos( $sn_d[1], 'sua_o' ) === false, $sn_d[1] );
} else {
	t( 'dò được đường dẫn của nút Đóng', false, $sn_h );
}

/* ---- 🔴 KHUNG KHÔNG ĐƯỢC LỆCH ----
   Anh Thắng 27/08/2026: *"lệch khung"*. Chỗ lệch: `<label>Họ tên<input></label>` thì `<input>`
   là inline, nên `width:100%` của nó bắt đầu NGAY SAU chữ "Họ tên" chứ không từ mép trái ô — ô
   rộng bằng cả ô lưới mà lại đẩy sang phải một đoạn bằng độ dài cái nhãn, thành ra tràn ra
   ngoài và đè lên nhãn kế bên. Nhãn dài bao nhiêu thì lệch bấy nhiêu, nên "Trạng thái làm việc"
   lệch nặng nhất còn "Họ tên" trông gần như bình thường — đó là lý do lỗi này lọt: nhìn ô đầu
   thì thấy ổn.

   ⚠️ PHÉP THỬ NÀY YẾU VÀ EM BIẾT THẾ. Bộ thử chạy bằng PHP, không dựng được bố cục để đo xem
      cái ô có tràn ra ngoài hay không. Nó chỉ canh được hai chuyện đã đủ để lỗi ấy không quay
      lại: luật `display:block` CÓ MẶT, và bề ngang không còn bị gõ tay rải rác trong HTML. */
t( '🔴 ô nhập trong hàng sửa được cho xuống dòng riêng (display:block)',
	strpos( $sn_h, 'tr.hang-sua .luoi label input{display:block' ) !== false, $sn_h );
t( 'và bề ngang do CSS lo, không gõ tay từng ô',
	preg_match( '/<tr class="hang-sua">.*?<\/tr>/s', $sn_h, $sn_m ) === 1
	&& strpos( $sn_m[0], 'style="width:100%"' ) === false,
	isset( $sn_m[0] ) ? $sn_m[0] : '' );
/* Ô ngày của trình duyệt có bề ngang riêng, không co theo ô lưới — không ghim lại thì riêng nó
   phình ra và đẩy lệch cả hàng. Đúng ô "Ngày vào làm" trong ảnh anh gửi. */
t( 'ô ngày bị ghim lại để không phình ra đẩy lệch cả hàng',
	strpos( $sn_h, 'input[type="date"]{max-width:100%' ) !== false, $sn_h );
/* 🔴 CHỈ MỞ ĐÚNG MỘT HÀNG. Mở hết là hàng sửa cao hơn cả màn hình và cái lợi "không rời trang"
   mất sạch. */
teq( '🔴 chỉ MỘT hàng sửa được mở', 1, substr_count( $sn_h, 'value="sua_nhanh"' ) );
t( 'người khác vẫn ở dạng hàng thường', strpos( $sn_h, '<b>SN2</b>' ) !== false );

/* 🔴 KHÔNG ĐIỀN SẴN PIN CŨ. Trang chạy ngoài internet, ảnh chụp màn hình đi khắp nơi — đúng
   luật màn Hồ sơ đang giữ. */
t( '🔴 KHÔNG in PIN cũ ra màn', strpos( $sn_h, '778899' ) === false, $sn_h );
t( 'chỉ cho biết PIN có mấy số', strpos( $sn_h, 'đang có 6 số' ) !== false, $sn_h );
/* KHÔNG có ô Mã NV: mã là khoá của mọi lượt chấm công, đổi nó là việc riêng chỉ Admin và có
   màn xem trước hẳn hoi. */
t( '🔴 hàng sửa KHÔNG có ô nhập Mã NV',
	preg_match( '/<input[^>]*name="ma_nv"[^>]*type="text"/', $sn_h ) === 0, $sn_h );

/* ---- Lưu ---- */
vhcc_ns_luu( 'Admin', 'ADM', array( 'viec' => 'sua_nhanh', 'ma_nv' => 'SN1',
	'ho_ten' => 'Tên Đã Sửa', 'sdt' => '0911111111', 'pin_dang_nhap' => '' ) );
$hs_sn = VHCC_NhanSu::ho_so( 'SN1' );
teq( 'lưu được tên mới', 'Tên Đã Sửa', $hs_sn['ho_ten'] );
teq( 'và SĐT mới', '0911111111', $hs_sn['sdt'] );
/* 🔴 Ô PIN ĐỂ TRỐNG = GIỮ NGUYÊN, KHÔNG PHẢI = XOÁ. Gửi chuỗi rỗng xuống `luu_ho_so()` là ghi
   đè thành rỗng — tức mỗi lần sửa tên một người là xoá luôn đường đăng nhập của họ, im lặng,
   và họ chỉ biết vào sáng hôm sau. */
teq( '🔴 để trống ô PIN thì GIỮ NGUYÊN PIN cũ', '778899', $hs_sn['pin_dang_nhap'] );
vhcc_ns_luu( 'Admin', 'ADM', array( 'viec' => 'sua_nhanh', 'ma_nv' => 'SN1',
	'ho_ten' => 'Tên Đã Sửa', 'pin_dang_nhap' => '445566' ) );
teq( 'gõ PIN mới thì đổi', '445566', VHCC_NhanSu::ho_so( 'SN1' )['pin_dang_nhap'] );

/* Cột cua_hang và vai_tro CỐ Ý không nhận ở đây — hai thứ ấy có cửa riêng, chốt riêng. */
vhcc_ns_luu( 'Admin', 'ADM', array( 'viec' => 'sua_nhanh', 'ma_nv' => 'SN1',
	'cua_hang' => 'JP_HCM', 'vai_tro' => 'Admin' ) );
$hs_sn = VHCC_NhanSu::ho_so( 'SN1' );
teq( '🔴 sửa nhanh KHÔNG đổi được cơ sở (có cửa riêng, reset quyền)', 'TUTU_BT', $hs_sn['cua_hang'] );
teq( '🔴 và KHÔNG đổi được vai trò (có cửa riêng, ba chốt)', 'Nhân viên', $hs_sn['vai_tro'] );

/* 🔴 Ô LƯƠNG CHỈ HIỆN VỚI NGƯỜI ĐƯỢC XEM LƯƠNG. Vẽ ra cho người khác thì số lương đi thẳng
   xuống HTML của máy họ — ẩn bằng CSS hay không vẽ nút Lưu đều vô nghĩa, ai mở công cụ nhà phát
   triển là đọc được. `luu_ho_so()` cũng chỉ nhận mấy ô ấy từ người có quyền, nên đây là hai
   tầng cho cùng một luật. Quản lý (bậc 3) KHÔNG có `xem_luong_hs` (bậc 4). */
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'luong_co_ban' => 12345678 ), array( 'ma_nv' => 'SN1' ) );
$sn_l = vhcc_ns( 'Kế toán', array( 'sua_o' => 'SN1' ) );
t( 'Kế toán thấy ô Lương cơ bản', strpos( $sn_l, 'name="luong_co_ban"' ) !== false, $sn_l );
/* ⚠️ CHỐT NÀY HIỆN CHƯA TỪNG KÍCH HOẠT — và đó KHÔNG phải lý do bỏ nó.
   Cửa vào trang là quyền `ho_so` (bậc 4); ô lương gác bằng `xem_luong_hs` (cũng bậc 4). Hai
   bậc BẰNG nhau, nên ai vào nổi trang này đều xem được lương, và nhánh `if ( $luong )` chưa
   bao giờ rẽ sang false. Phá thử phát hiện đúng chuyện đó.

   Khác hẳn cái chốt chết ở `dat_co_so()` mà bản trước đã bỏ: chốt kia nằm NGAY CẠNH một chốt
   chặt hơn trong cùng một hàm, nên nó không bảo vệ trước bất cứ thay đổi nào. Chốt này bảo vệ
   trước một thay đổi ở CHỖ KHÁC — ngày nào cửa vào trang được nới xuống (chẳng hạn cho Quản lý
   vào để chuyển cơ sở), nó tự đứng ra chặn mà không ai phải nhớ. Nên: GIỮ, và canh chính cái
   quan hệ hai bậc làm nó chưa chạy — mất quan hệ ấy là lúc nó bắt đầu có việc. */
teq( 'cửa vào trang và chốt ô lương hiện đang CÙNG một bậc',
	VHCC_Vai::BAC[ VHCC_Vai::QUYEN['ho_so'] ], VHCC_Vai::BAC[ VHCC_Vai::QUYEN['xem_luong_hs'] ] );
t( '🔴 và Quản lý không xem được lương — nới cửa trang xuống bậc 3 là chốt ấy vào việc ngay',
	! VHCC_Vai::duoc( array( 'role' => 'Quản lý' ), 'xem_luong_hs' ) );
/* Soi thẳng hàm dựng ô: vẽ ô lương cho người không được xem là số lương đi xuống HTML máy họ. */
t( 'hàng sửa gác ô lương bằng co_xem_luong',
	strpos( file_get_contents( $goc . '/wordpress/vhcp-cham-cong/includes/class-vhcc-trang-ns.php' ),
		'$luong = VHCC_NhanSu::co_xem_luong( $toi );' ) !== false );

/* Chốt quyền: sửa hồ sơ cần Kế toán trở lên — đi qua đúng `luu_ho_so()`. */
$_GET = array(); $_POST = array();
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'CHT', 'Cửa hàng trưởng', 'TUTU_BT', 'C9' );
$_POST = array( 'viec' => 'sua_nhanh', 'ma_nv' => 'SN1', 'ho_ten' => 'Bị Chối',
	'ky' => VHCC_Web::chu_ky( $_COOKIE[ VHCC_Web::COOKIE ] ) );
ob_start(); VHCC_TrangNS::phuc_vu(); ob_get_clean();
$_POST = array(); $_COOKIE = array();
teq( '🔴 Cửa hàng trưởng không sửa được hồ sơ qua đường này', 'Tên Đã Sửa',
	VHCC_NhanSu::ho_so( 'SN1' )['ho_ten'] );

/* ⚠️ Ô sửa phải SỐNG SÓT qua lượt lưu: `sua_o` nằm trong THAM_SO nên lưu xong hàng vẫn mở, sửa
   tiếp được ô khác. Thiếu nó thì mỗi lần bấm Lưu là hàng tự đóng. */
t( '🔴 sua_o có trong danh sách tham số chở qua lượt POST',
	in_array( 'sua_o', VHCC_TrangNS::THAM_SO, true ), VHCC_TrangNS::THAM_SO );
vhcc_dung_bang();

/* ==========================================================================================
 *  65. GIỜ & LƯƠNG — NẰM TRONG MÀN BẢNG CÔNG, KHÔNG PHẢI TAB RIÊNG
 * ------------------------------------------------------------------------------------------
 *  Anh Thắng chốt hai điều, cách nhau ít phút:
 *    1. *"mọi việc anh thao tác trên web… không làm bên trong wp-admin"* — nên màn Bảng công &
 *       Lương phải ra ngoài web (wp-admin đòi tài khoản WordPress mà kế toán không có, và cũng
 *       không nên có: tài khoản ấy mở ra cả website chứ không riêng chấm công).
 *    2. *"bảng công và giờ lương gộp lại thành 1 trang"* — và đây là lần THỨ HAI anh nói cùng
 *       một điều (lần trước là gộp Bảng chấm công với Bảng công tháng). Hai bảng nói về CÙNG
 *       một cơ sở, CÙNG một tháng, chỉ khác cách bày. Tách ra là bắt chọn cơ sở và tháng HAI
 *       LẦN — và chọn lệch một ô là hai bảng nói về hai chỗ khác nhau mà không có gì báo.
 *
 *  🔴 KHỐI NÀY CHỈ VẼ. Mọi phép tính tiền nằm ở `VHCC_Luong::bang_cong_va_luong()` — đúng hàm
 *  màn wp-admin vẫn gọi. Hai nơi cùng tính lương là hai nơi sớm muộn ra hai con số, mà không ai
 *  biết tin cái nào.
 * ======================================================================================== */
$lw_ma = file_get_contents( $goc . '/wordpress/vhcp-cham-cong/includes/class-vhcc-web.php' );
$lw_i  = strpos( $lw_ma, 'private static function the_khoi_luong' );
$lw_j  = strpos( $lw_ma, 'private static function the_man_cau_hinh' );
$lw_than = substr( $lw_ma, $lw_i, $lw_j - $lw_i );
t( 'khối lương gọi ĐÚNG hàm nghiệp vụ đang dùng ở wp-admin',
	strpos( $lw_than, 'VHCC_Luong::bang_cong_va_luong(' ) !== false );
/* 🔴 KHÔNG MỘT CÔNG THỨC NÀO Ở PHẦN VẼ. `number_format` thì được — đó là định dạng, không phải
   phép tính. Mẫu phải nuốt cả chuỗi chỉ số LỒNG (`$e['cong']['thuong']`): bản đầu chỉ bắt một
   tầng nên `$e['cong']['thuong'] * 100` lọt — phá thử tìm ra. */
t( '🔴 phần vẽ KHÔNG có phép nhân/chia nào (không tự tính tiền)',
	preg_match( '#\$[a-z_]+(\[[^]]+\])+\s*[*/]\s*#i', $lw_than ) === 0, $lw_than );

/* 🔴 PHÉP SO BỘ KHOÁ WEB ↔ WP-ADMIN ĐÃ BỎ CÙNG VỚI BẢNG NÓ CANH.
   Nó canh cái bẫy `congTangCa` gõ nhầm thành `tangCa`: `esc_html()` nhận null và in ra ô TRỐNG
   — không lỗi, không cảnh báo, chỉ là một cột trắng trơn trong bảng soi lương, mà cột trắng thì
   người đọc tưởng tháng ấy không ai tăng ca.
   Từ 27/08/2026 khối web không còn bảng người-theo-người nữa (anh Thắng: *"bỏ bảng này đi,
   không cần thiết"*), nên không còn chỗ nào bên web đọc bộ khoá ấy để mà so.
   ⚠️ NHƯNG CÁI BẪY THÌ CHƯA MẤT: `tach_cong()` ở cột TỔNG của lưới vẫn đọc `congNgay` ·
      `congTangCa` · `congDem` · `congBu`. Phép thử canh nó nằm ở khối lưới — cảnh dựng có một
      người CÓ tăng ca, đúng để gõ nhầm tên khoá là đỏ. Bỏ phép so này mà không có cái kia thì
      cái bẫy quay lại ngay, nên nói thẳng ra đây. */

/* ---- GỘP: không còn tab riêng ---- */
vhcc_dung_bang();
VHCC_NhanSu::xep_bo_phan( $U_AD, 'LW_VP', 'Văn phòng' );
vhcc_cham( 'LW_VP', '2026-08-03', 'LW1', '', '08:00:00', '17:00:00' );
vhcc_cham( 'POSH_HCM', '2026-08-03', 'LW2', '', '08:00:00', '17:00:00' );
vhcc_cham( 'LW_THO', '2026-08-03', 'LW3', '', '08:00:00', '17:00:00' );

t( '🔴 KHÔNG còn tab "Giờ & Lương" riêng — nó nằm trong Bảng công',
	! isset( VHCC_Web::man_cua( $U_KT )['luong'] ), VHCC_Web::man_cua( $U_KT ) );
t( 'Admin cũng không có tab riêng', ! isset( VHCC_Web::man_cua( $U_AD )['luong'] ) );
t( 'và Bảng công vẫn còn', isset( VHCC_Web::man_cua( $U_KT )['cham'] ) );

/* ⚠️ CƠ SỞ CỦA THẺ PHIÊN PHẢI KHỚP CƠ SỞ ĐANG XEM khi thử vai Cửa hàng trưởng — nếu không thì
   `co_quyen_coso()` chối trước, và phép thử "không thấy khối lương" xanh vì LÝ DO KHÁC HẲN lý
   do mình tưởng. Đã vấp đúng chỗ đó: bỏ hẳn chốt `luong` mà bộ thử vẫn xanh, vì chốt cơ sở đỡ
   giúp. Hai chốt che nhau thì phép thử chỉ đo được cái chốt chạy TRƯỚC. */
function vhcc_luong_web( $vai, $get = array(), $coso_the = 'TUTU_BT' ) {
	$_GET = array_merge( array( 'man' => 'cham' ), $get ); $_POST = array();
	$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Kế', $vai, $coso_the, 'KT9' );
	ob_start(); VHCC_Web::phuc_vu(); $h = ob_get_clean();
	$_GET = array(); $_COOKIE = array();
	return $h;
}

/* ---- Ba kiểu cơ sở, ba bảng khác nhau — dùng CHUNG bộ lọc của Bảng công (ccs/cth) ---- */
$lw_h = vhcc_luong_web( 'Kế toán', array( 'ccs' => 'LW_VP', 'cth' => '2026-08' ) );
/* ⚠️ Khối này ĐỔI TÊN từ "Giờ & Lương" thành "Lương" ở bản 2.63.0: bốn cột công (ngày · tăng
   ca · đêm · bù) đã dời lên cột TỔNG của lưới, nên nó không còn phần "giờ" nào nữa. */
t( '🔴 khối Lương hiện ngay trong màn Bảng công',
	strpos( $lw_h, '<b>Lương</b>' ) !== false, $lw_h );
/* 🔴 HAI BẢNG PHỤ ĐÃ BỎ — LƯỚI NÓI HẾT.
   Anh Thắng 27/08/2026, hai lượt liền: *"bỏ bảng này đi, không cần thiết"* (bảng lương
   người-theo-người) và *"này cũng bỏ đi, không cần thiết"* (Chi tiết từng ngày, 355 dòng cho
   một tháng). Chúng trả lời câu "vì sao ô kia ra con số đó" bằng hàng trăm dòng xếp theo NGÀY,
   trong khi người hỏi đang chỉ tay vào MỘT ô. */
t( '🔴 KHÔNG còn bảng lương người-theo-người', strpos( $lw_h, '<th>Đơn giá 1 công</th>' ) === false, $lw_h );
t( '🔴 KHÔNG còn khối Chi tiết từng ngày', strpos( $lw_h, 'Chi tiết từng ngày' ) === false, $lw_h );
/* Nhưng con số tổng của CẢ CƠ SỞ thì phải còn — bỏ hết là mất luôn chỗ biết tháng này ra bao
   nhiêu công, bao nhiêu tiền. */
t( 'nhưng còn con số tổng của cả cơ sở', strpos( $lw_h, '<b>Cả cơ sở:</b>' ) !== false, $lw_h );
t( 'và chỉ đường sang cột TỔNG của lưới',
	strpos( $lw_h, 'nằm ở cột <b>TỔNG</b> của lưới' ) !== false, $lw_h );
/* 🔴 BA DẢI CẢNH BÁO ĐÃ RỜI SANG MÀN CẤU HÌNH.
   Anh Thắng 27/08/2026, kèm hai ảnh: *"bỏ chỗ này"*. Chúng đúng, nhưng đứng nhầm chỗ: bảng công
   là màn người ta mở HẰNG NGÀY để ĐỌC, còn ba dải ấy nói về việc KHAI MỘT LẦN — và cái dài nhất
   dán tên hai mươi mấy người ra giữa màn, mỗi lần mở lại đọc lại. Người xem công không khai
   được gì với chúng: họ không có quyền, và cũng không phải việc của họ.
   ⚠️ KHÔNG XOÁ HẲN, chỉ dời. Xoá là chưa khai ngày công chuẩn thì cột Tiền hiện "—" mà không
      câu nào nói vì sao, và người kiểm lương đi tìm một lỗi không có thật. */
t( '🔴 màn Bảng công KHÔNG còn dải cảnh báo lương',
	strpos( $lw_h, 'Chưa khai số ngày công' ) === false, $lw_h );
t( 'cũng không còn dải ktMaNV', strpos( $lw_h, 'ktMaNV' ) === false, $lw_h );
t( 'và KHÔNG dán tên người chưa khai lương ra giữa màn',
	strpos( $lw_h, 'Chưa khai lương cơ bản' ) === false, $lw_h );
/* 🔴 KHÔNG ĐẺ RA Ô LỌC THỨ HAI. Hai ô cho cùng một thứ thì người ta sẽ chọn lệch, và cả hai
   bảng đều trông đúng. Đó là toàn bộ điểm của việc gộp. */
t( '🔴 khối lương KHÔNG có ô chọn cơ sở riêng', strpos( $lw_h, 'name="lcs"' ) === false, $lw_h );
t( 'và KHÔNG có ô chọn tháng riêng', strpos( $lw_h, 'name="lth"' ) === false, $lw_h );
t( 'tiêu đề khối nói rõ đang xem cơ sở nào, tháng nào',
	strpos( $lw_h, 'LW_VP' ) !== false && strpos( $lw_h, '2026-08' ) !== false );

$lw_h = vhcc_luong_web( 'Kế toán', array( 'ccs' => 'POSH_HCM', 'cth' => '2026-08' ) );
t( 'cơ sở Máy tự động ra bảng theo CÔNG + GIỜ',
	strpos( $lw_h, 'Công cuối tuần' ) !== false && strpos( $lw_h, 'Tiền giờ' ) !== false, $lw_h );

/* 🔴 CƠ SỞ CHƯA CÓ CÔNG THỨC thì KHÔNG bịa ra tiền. Bịa một công thức là đưa ra con số tiền mà
   không ai biết từ đâu — mà bảng thì vẫn có số nên chẳng ai nghi. */
$lw_h = vhcc_luong_web( 'Kế toán', array( 'ccs' => 'LW_THO', 'cth' => '2026-08' ) );
t( '🔴 cơ sở chưa khai bộ phận thì nói thẳng là CHƯA CÓ công thức lương',
	strpos( $lw_h, 'chưa có công thức lương' ) !== false, $lw_h );
t( 'và không có cột tiền nào',
	strpos( $lw_h, 'Đơn giá 1 công' ) === false && strpos( $lw_h, 'Tiền giờ' ) === false, $lw_h );

/* ---- 🔴 GỘP CHỖ BÀY, KHÔNG GỘP QUYỀN ----
   Màn Bảng công mở cho `cong_coso` (bậc Cửa hàng trưởng). Nếu khối lương đi theo cửa ấy thì
   gộp trang xong là mở bảng lương của CẢ CƠ SỞ cho người cùng cơ sở — đúng thứ mà tab riêng
   trước đây đang chặn. Nên khối phải gác RIÊNG bằng `luong`. */
/* Thẻ phiên mang ĐÚNG cơ sở đang xem — để chốt cơ sở không đỡ giúp, và phép thử đo đúng cái
   chốt `luong` mà nó nói là đang đo. */
$lw_h = vhcc_luong_web( 'Cửa hàng trưởng', array( 'ccs' => 'LW_VP', 'cth' => '2026-08' ), 'LW_VP' );
t( 'Cửa hàng trưởng vẫn vào được màn Bảng công', strpos( $lw_h, 'Chấm công' ) !== false, $lw_h );
t( 'và thật sự đọc được bảng công của cơ sở mình (chốt cơ sở KHÔNG chối họ)',
	strpos( $lw_h, 'LW_VP' ) !== false, $lw_h );
t( '🔴 nhưng KHÔNG thấy khối Giờ & Lương', strpos( $lw_h, 'Giờ &amp; Lương' ) === false, $lw_h );
t( '🔴 và không một con số tiền nào lọt xuống HTML của họ',
	strpos( $lw_h, 'Đơn giá 1 công' ) === false && strpos( $lw_h, 'Tiền công' ) === false, $lw_h );
$lw_h = vhcc_luong_web( 'Quản lý', array( 'ccs' => 'LW_VP', 'cth' => '2026-08' ), 'LW_VP' );
t( '🔴 Quản lý cũng KHÔNG thấy khối lương', strpos( $lw_h, 'Giờ &amp; Lương' ) === false, $lw_h );

/* Chưa chọn cơ sở thì KHÔNG vẽ khối lương — không có cơ sở thì lương của ai?
   ⚠️ Soi chính CÁI KHỐI, đừng soi mỗi tên cột. Bỏ chốt `$cs` rỗng thì
      `bang_cong_va_luong('')` trả lỗi "Thiếu cơ sở", khối vẫn vẽ ra một `<details>` mang câu
      lỗi ấy — không có cột "Đơn giá 1 công" nào, nên phép thử soi tên cột vẫn xanh trong khi
      màn đã mọc thêm một khối rỗng vô nghĩa. Phá thử tìm ra. */
$lw_h = vhcc_luong_web( 'Kế toán', array( 'cth' => '2026-08' ) );
t( '🔴 chưa chọn cơ sở thì KHÔNG mọc ra khối Giờ & Lương nào',
	strpos( $lw_h, 'Giờ &amp; Lương' ) === false, $lw_h );
t( 'và tất nhiên không có cột tiền nào', strpos( $lw_h, 'Đơn giá 1 công' ) === false, $lw_h );

/* ---- 🔴 LỖI THẬT TÌM RA KHI GỘP: Kế toán chỉ thấy ĐÚNG MỘT cơ sở ----
   `ds_coso_xem()` từng so vai bằng một mảng cứng `['Admin','Quản lý']`. Kế toán ở bậc 4, cao
   hơn Quản lý (bậc 3), có `cong_tat_ca`, và anh Thắng chốt kế toán "full quyền ngoài admin" —
   nhưng vì tên "Kế toán" không có trong mảng ấy, họ rơi xuống nhánh dưới và chỉ thấy cơ sở ghi
   trên thẻ phiên.

   Im lặng và khó lần: ô chọn cơ sở chỉ có một dòng, mà một dòng thì `the_bang_cham()` TỰ CHỌN
   luôn — nên màn vẫn có số, vẫn trông bình thường, chỉ là kế toán không bao giờ xem được cơ sở
   khác và cũng không thấy có gì để bấm. Lộ ra vì khối lương in tên cơ sở, và tên ấy không khớp
   ô chọn. Đúng loại lỗi mà cả `VHCC_Vai` sinh ra để dẹp: hỏi QUYỀN, đừng so TÊN VAI. */
$lw_kt = array( 'role' => 'Kế toán', 'coso' => 'TUTU_BT', 'ma_nv' => 'KT9' );
$lw_ds = VHCC_NhanSu::ds_coso();
t( 'sổ có nhiều hơn một cơ sở (nếu chỉ một thì phép thử dưới vô nghĩa)',
	count( $lw_ds ) > 1, $lw_ds );
$lw_h = vhcc_luong_web( 'Kế toán', array( 'cth' => '2026-08' ) );
preg_match_all( '/<option value="([^"]*)"[^>]*>[^<]*<\/option>/', $lw_h, $lw_op );
t( '🔴 Kế toán thấy ĐỦ cơ sở trong ô chọn, không phải mỗi cơ sở trên thẻ',
	count( array_intersect( $lw_ds, $lw_op[1] ) ) === count( $lw_ds ),
	array( 'sổ' => $lw_ds, 'ô chọn' => array_values( array_unique( $lw_op[1] ) ) ) );
/* Và chốt ngược lại: Cửa hàng trưởng vẫn CHỈ thấy cơ sở mình — nới cho kế toán không được
   kéo theo cả bậc dưới. */
t( 'Cửa hàng trưởng vẫn chỉ thấy cơ sở mình',
	! VHCC_Vai::duoc( array( 'role' => 'Cửa hàng trưởng' ), 'cong_tat_ca' ) );
t( 'và Kế toán thì có quyền xem mọi cơ sở',
	VHCC_Vai::duoc( array( 'role' => 'Kế toán' ), 'cong_tat_ca' ) );
t( 'ds_coso_xem hỏi QUYỀN chứ không so tên vai',
	strpos( $lw_ma, "VHCC_Vai::duoc( \$toi, 'cong_tat_ca' )" ) !== false
	&& strpos( $lw_ma, "if ( 'Admin' === \$vt || 'Quản lý' === \$vt )" ) === false );

/* Địa chỉ cũ `?man=luong` phải dẫn về Bảng công, đừng để ai đã lưu lại đường ấy rơi về màn mặc
   định mà không hiểu vì sao. */
$lw_h = vhcc_luong_web( 'Kế toán', array( 'man' => 'luong', 'ccs' => 'LW_VP', 'cth' => '2026-08' ) );
t( '🔴 địa chỉ cũ ?man=luong dẫn về Bảng công, không rơi về màn mặc định',
	strpos( $lw_h, '<b>Lương</b>' ) !== false && strpos( $lw_h, 'Chấm công' ) !== false, $lw_h );

/* ⚠️ Chốt cơ sở của khối: `bang_cong_va_luong()` không nhận người dùng nên nó không gác gì.
   Nhánh ấy hiện chưa từng chối ai (bậc `luong` = 4 đã có `cong_tat_ca` = 3), nhưng giữ — nó
   chặn ngay ngày nào `luong` được nới xuống. Canh chính quan hệ hai bậc, đúng bài học từ cái
   chốt chết ở `dat_co_so()`. */
t( '🔴 quyền "luong" phải CAO HƠN "cong_tat_ca" — chốt cơ sở của khối dựa vào chuyện đó',
	VHCC_Vai::BAC[ VHCC_Vai::QUYEN['luong'] ] > VHCC_Vai::BAC[ VHCC_Vai::QUYEN['cong_tat_ca'] ] );
/* ⚠️ SOI ĐÚNG THÂN `the_khoi_luong`, ĐỪNG SOI CẢ VÙNG TỚI `the_man_cau_hinh`.
   Vùng rộng ấy dài hơn 11.000 ký tự và ôm luôn mấy hàm khác — trong đó có một hàm cũng gọi
   `VHCC_Vai::duoc( $toi, 'luong' )`. Nên bỏ hẳn chốt trong `the_khoi_luong` thì `strpos` vẫn
   tìm thấy chuỗi ấy ở hàm kia và phép thử vẫn xanh: nó khen một cái chốt đã bị gỡ. Phá thử tìm
   ra — cắt vùng cho tới đúng hàm liền sau (`luong_tho`) là hết. */
$lw_j2   = strpos( $lw_ma, 'private static function luong_tho' );
$lw_than1 = substr( $lw_ma, $lw_i, $lw_j2 - $lw_i );
t( 'cắt được đúng thân hàm (nếu rỗng thì hai phép dưới vô nghĩa)',
	$lw_j2 > $lw_i && strlen( $lw_than1 ) > 200, strlen( $lw_than1 ) );
t( 'khối có gác cơ sở bằng co_quyen_coso',
	strpos( $lw_than1, 'VHCC_NhanSu::co_quyen_coso( $toi, $cs )' ) !== false, $lw_than1 );
t( '🔴 và gác riêng bằng quyền luong, không đi theo cửa của màn Bảng công',
	strpos( $lw_than1, "VHCC_Vai::duoc( \$toi, 'luong' )" ) !== false, $lw_than1 );
/* Chốt "chưa chọn cơ sở thì không vẽ" cũng phải nằm trong CHÍNH thân ấy — nó là hàng rào cuối
   nếu mai kia màn Bảng công đổi cách gọi và không còn return sớm nữa. */
t( '🔴 và không vẽ gì khi chưa có cơ sở',
	strpos( $lw_than1, "if ( '' === \$cs ) { return; }" ) !== false, $lw_than1 );

/* Màn quản trị KHÔNG có script — luật chung, khối mới không được phá lệ. */
t( '🔴 màn có khối lương vẫn không có thẻ script nào', stripos( $lw_h, '<script' ) === false );
t( 'và không có thuộc tính on...= nào', preg_match( '/\son[a-z]+\s*=\s*["\']/i', $lw_h ) === 0, $lw_h );
vhcc_dung_bang();

/* ==========================================================================================
 *  66. IN BẢNG CHẤM CÔNG — RA NGOÀI WEB
 * ------------------------------------------------------------------------------------------
 *  Màn cuối trong nhóm việc hằng ngày còn kẹt trong wp-admin. Anh Thắng: *"mọi việc anh thao
 *  tác trên web giao diện bên ngoài hết"* — mà cửa hàng trưởng thì không có tài khoản
 *  WordPress để vào wp-admin in bảng công cơ sở mình.
 *
 *  🔴 SỐ TRÊN TỜ GIẤY DO MÁY CHỦ TÍNH. Bản Apps Script cũ nhận số do trình duyệt tính rồi đẩy
 *  lên — tức ai sửa được yêu cầu là sửa được tờ giấy chấm công đem đi ký.
 * ======================================================================================== */
vhcc_dung_bang();
vhcc_cham( 'TUTU_BT', '2026-08-03', 'IN1', '', '08:00:00', '17:00:00' );
$U_IN_CHT = array( 'role' => 'Cửa hàng trưởng', 'coso' => 'TUTU_BT', 'ma_nv' => 'IC1' );

/* ---- Chốt cửa: tách khỏi `to_in()` vì hàm kia kết bằng `exit` ---- */
teq( 'Admin in được', '', VHCC_Web::vi_sao_khong_in( $U_AD, 'TUTU_BT', '2026-08-01', '2026-08-31' ) );
/* Tờ in là BẢNG CHẤM CÔNG, không phải bảng lương — cửa hàng trưởng phải in được bảng công cơ
   sở mình để dán lên bảng tin và cho người ta ký. */
teq( '🔴 Cửa hàng trưởng in được bảng công cơ sở MÌNH', '',
	VHCC_Web::vi_sao_khong_in( $U_IN_CHT, 'TUTU_BT', '2026-08-01', '2026-08-31' ) );
t( '🔴 nhưng KHÔNG in được cơ sở khác',
	'' !== VHCC_Web::vi_sao_khong_in( $U_IN_CHT, 'JP_HCM', '2026-08-01', '2026-08-31' ) );
$in_nv = VHCC_Web::vi_sao_khong_in( $U_NV, 'TUTU_BT', '2026-08-01', '2026-08-31' );
t( '🔴 Nhân viên không in được gì', '' !== $in_nv );
/* 🔴 CHỐT `cong_coso` Ở ĐẦU HÀM TRÔNG NHƯ THỪA — `co_quyen_coso()` bên dưới cũng bắt đầu
   bằng đúng chốt ấy, nên nó không bao giờ là chốt QUYẾT ĐỊNH. Giữ vì hai lẽ, và mỗi lẽ có một
   phép thử canh ở đây:
     1. Nó đổi CÂU TRẢ LỜI. Bỏ đi thì Nhân viên bị chối bằng câu "Không có quyền cơ sở này" —
        sai chuyện, người ta sẽ đi xin cấp thêm cơ sở trong khi thứ thiếu là bậc vai.
     2. `co_quyen_coso()` nằm ở LỚP KHÁC (`VHCC_NhanSu`). Ai nới nó ra một ngày nào đó — cho
        người xem được cơ sở mình chẳng hạn — thì cửa tờ in vẫn đóng. Khác hẳn chốt chết trong
        `dat_co_so()` đã bỏ: chốt ấy đứng CÙNG HÀM với chốt chặt hơn, không che được gì cả. */
t( 'và câu chối nói ĐÚNG chuyện thiếu bậc vai, không đổ oan cho cơ sở',
	strpos( $in_nv, 'Cửa hàng trưởng' ) !== false, $in_nv );
teq( 'canh quan hệ hai lớp: `co_quyen_coso` vẫn đang gói trong `cong_coso`',
	false, VHCC_NhanSu::co_quyen_coso( $U_NV, 'TUTU_BT' ) );
t( 'chưa chọn cơ sở thì chối',
	'' !== VHCC_Web::vi_sao_khong_in( $U_AD, '', '2026-08-01', '2026-08-31' ) );

/* 🔴 KHUÔN NGÀY PHẢI KIỂM. Hai chuỗi ấy đi thẳng vào câu SQL của `VHCC_Pdf::gom()` — thả một
   chuỗi tuỳ ý xuống đó là mở một cửa mà không ai gác. */
foreach ( array( '2026-8-1', '01/08/2026', 'hôm qua', '2026-08-01 OR 1=1', '' ) as $in_xau ) {
	t( '🔴 ngày sai khuôn "' . $in_xau . '" bị chối',
		'' !== VHCC_Web::vi_sao_khong_in( $U_AD, 'TUTU_BT', $in_xau, '2026-08-31' ) );
	t( 'và ở ô Đến ngày cũng vậy',
		'' !== VHCC_Web::vi_sao_khong_in( $U_AD, 'TUTU_BT', '2026-08-01', $in_xau ) );
}
/* Đảo ngày thì tờ giấy ra RỖNG mà không nói vì sao — người ta tưởng tháng ấy không ai đi làm. */
$in_ly = VHCC_Web::vi_sao_khong_in( $U_AD, 'TUTU_BT', '2026-08-31', '2026-08-01' );
t( '🔴 đảo ngày thì NÓI RÕ, đừng trả tờ giấy rỗng', '' !== $in_ly, $in_ly );
t( 'và câu chối nói đúng chuyện đảo ngày',
	strpos( $in_ly, 'trước ngày bắt đầu' ) !== false, $in_ly );

/* ---- Khối In trong màn Bảng công ---- */
$in_h = vhcc_luong_web( 'Kế toán', array( 'ccs' => 'TUTU_BT', 'cth' => '2026-08' ) );
t( '🔴 màn Bảng công có khối In', strpos( $in_h, 'In bảng chấm công' ) !== false, $in_h );
t( 'biểu mẫu trỏ đúng cửa tờ in', strpos( $in_h, 'name="to_in"' ) !== false );
/* ⚠️ KHÔNG ĐẺ Ô CHỌN CƠ SỞ RIÊNG — cơ sở lấy thẳng từ màn Bảng công, cùng luật với khối lương.
   Hai ô cho cùng một thứ thì người ta sẽ chọn lệch, và cả hai đều trông đúng. */
t( '🔴 khối In KHÔNG có ô chọn cơ sở riêng',
	preg_match( '/<select[^>]*name="ics"/', $in_h ) === 0, $in_h );
t( 'mà mang thẳng cơ sở đang xem',
	strpos( $in_h, 'name="ics" value="TUTU_BT"' ) !== false, $in_h );
/* Mặc định đầu và cuối THÁNG ĐANG XEM — phần lớn lượt chỉ việc bấm. */
t( 'ngày mặc định là đầu tháng đang xem',
	strpos( $in_h, 'name="itu" value="2026-08-01"' ) !== false, $in_h );
t( '🔴 và cuối tháng tính đúng số ngày của tháng ấy (không gõ cứng 31)',
	strpos( $in_h, 'name="iden" value="2026-08-31"' ) !== false, $in_h );
/* ⚠️ Mở ở THẺ MỚI: tờ in là trang HTML riêng khổ A4. Mở đè thì in xong phải bấm Back rồi chọn
   lại cơ sở + tháng — đúng cái phiền mà việc gộp trang vừa dẹp xong. */
t( '🔴 tờ in mở ở thẻ mới', strpos( $in_h, 'target="_blank"' ) !== false, $in_h );

/* Tháng 2 — chỗ mà "gõ cứng 31" sẽ đẻ ra một ngày không tồn tại và câu SQL trả rỗng. */
$in_h2 = vhcc_luong_web( 'Kế toán', array( 'ccs' => 'TUTU_BT', 'cth' => '2026-02' ) );
t( '🔴 tháng 2 ra ngày 28, không phải 31',
	strpos( $in_h2, 'name="iden" value="2026-02-28"' ) !== false, $in_h2 );

/* Chưa chọn cơ sở thì không vẽ khối In — không có cơ sở thì in của ai?
   ⚠️ PHẢI CÓ ÍT NHẤT HAI CƠ SỞ TRONG SỔ mới dựng được cảnh này: `the_bang_cham()` TỰ CHỌN khi
      danh sách chỉ còn đúng một dòng (tiện, và đúng). Sổ một cơ sở thì "chưa chọn" không tồn
      tại, và phép thử đo phải một cảnh không có thật. */
vhcc_cham( 'JP_HCM', '2026-08-04', 'IN2', '', '08:00:00', '17:00:00' );
t( 'sổ có từ hai cơ sở trở lên (nếu một thì phép thử dưới vô nghĩa)',
	count( VHCC_NhanSu::ds_coso() ) > 1, VHCC_NhanSu::ds_coso() );
$in_h3 = vhcc_luong_web( 'Kế toán', array( 'cth' => '2026-08' ) );
t( 'chưa chọn cơ sở thì không mọc ra khối In',
	strpos( $in_h3, 'In bảng chấm công' ) === false, $in_h3 );

/* ==========================================================================================
 * 🔴 XUẤT EXCEL CHẾT KHÔNG NÓI GÌ — anh Thắng 28/08/2026 gửi ảnh "Đã có một lỗi nghiêm trọng
 *    trên trang web của bạn" khi bấm Xuất Excel ở TUTU_BT.
 * ==========================================================================================
 * Lượt xuất giữ cả tháng của cả cơ sở trong bộ nhớ HAI lần (mảng dữ liệu + chuỗi XML dựng ra
 * từ nó). Vượt trần là PHP chết giữa chừng, và lúc ấy `loi_xuat()` không bao giờ được gọi tới.
 * Không chặn được cái chết, nhưng phải NÓI RA được vướng gì.
 */
$_GET = array( 'xuat' => 'ca', 'ccs' => 'TUTU_BT', 'cth' => '2026-08', 'thu' => '1' );
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Người Xuất', 'Kế toán', 'TUTU_BT', 'KTX' );
ob_start(); VHCC_Web::phuc_vu(); $x_cd = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( '🔴 có đường chẩn đoán đọc được bằng mắt',
	strpos( $x_cd, 'XUAT EXCEL: CHAN DOAN' ) !== false, substr( $x_cd, 0, 300 ) );
t( 'nói ra giới hạn bộ nhớ đang có', strpos( $x_cd, 'memory_limit' ) !== false, $x_cd );
t( 'và có ZipArchive hay không', strpos( $x_cd, 'ZipArchive' ) !== false, $x_cd );
t( 'kể ra bao nhiêu người, bao nhiêu lượt',
	strpos( $x_cd, 'so nguoi' ) !== false && strpos( $x_cd, 'so luot' ) !== false, $x_cd );
/* ⚠️ KHÔNG IN GÌ BÍ MẬT. Đường này ai gõ trúng cũng mở được — nó chỉ được nói về TÌNH TRẠNG
   MÁY, không nói về người. */
t( '🔴 đường chẩn đoán KHÔNG in tên người hay mã NV',
	strpos( $x_cd, 'Người X' ) === false && strpos( $x_cd, 'ho_ten' ) === false, $x_cd );
/* ⚠️ Và KHÔNG được đổ nguyên mảng dữ liệu ra: một `wp_json_encode( $b['hang'] )` đặt nhầm chỗ
   là in sạch họ tên + mã NV cả cơ sở lên một trang ai gõ trúng cũng mở được. Canh bằng hình
   dạng: trang này chỉ có dòng "khoá : giá trị", không có dấu ngoặc của JSON. */
t( '🔴 và không đổ nguyên mảng dữ liệu ra',
	strpos( $x_cd, '{' ) === false && strpos( $x_cd, '[' ) === false, $x_cd );
/* Mỗi dòng là một con số hoặc một chữ ngắn — không dòng nào dài quá một dòng màn hình. */
$x_dai = 0;
foreach ( explode( "\n", $x_cd ) as $x_d ) { $x_dai = max( $x_dai, strlen( $x_d ) ); }
t( 'mỗi dòng chẩn đoán đủ ngắn để đọc bằng mắt', $x_dai < 90, $x_dai );
/* Và nó vẫn phải qua đúng cửa quyền như lượt xuất thật — không thành một cửa sau. */
$_GET = array( 'xuat' => 'ca', 'ccs' => 'JP_HCM', 'cth' => '2026-08', 'thu' => '1' );
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'CHT', 'Cửa hàng trưởng', 'TUTU_BT', 'CHX' );
ob_start(); VHCC_Web::phuc_vu(); $x_cam = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( '🔴 đường chẩn đoán vẫn gác quyền cơ sở như lượt xuất thật',
	strpos( $x_cam, 'XUAT EXCEL: CHAN DOAN' ) === false, substr( $x_cam, 0, 300 ) );
/* ⚠️ VÀ PHẢI CHỐI ĐÚNG CÂU của cửa quyền, không phải rơi xuống một câu chối khác ở dưới. Hai
   chốt cùng chặn thì bỏ mất chốt trên vẫn "an toàn" — cho tới ngày chốt dưới đổi. */
t( 'và chối bằng đúng câu của cửa quyền cơ sở',
	strpos( $x_cam, 'Không có quyền cơ sở này' ) !== false, substr( $x_cam, 0, 600 ) );

/* Lớp chống chết phải có mặt trong mã — không dựng được cảnh hết bộ nhớ trong bài kiểm, nên
   canh bằng cách soi rằng ba thứ ấy tồn tại. */
$src_xuat = file_get_contents( $goc . '/wordpress/vhcp-cham-cong/includes/class-vhcc-web.php' );
t( '🔴 lượt xuất có nâng trần bộ nhớ trước',
	strpos( $src_xuat, 'wp_raise_memory_limit' ) !== false );
t( '🔴 và đón cái chết bằng register_shutdown_function',
	strpos( $src_xuat, 'register_shutdown_function' ) !== false );

/* 🔴 BẮT `Throwable` NGAY TẠI CHỖ. Anh Thắng 28/08/2026 cài bản có lớp đón-cái-chết mà VẪN
   thấy trang trắng: WordPress có bộ bắt lỗi riêng đăng ký shutdown TRƯỚC mình, in trang lỗi
   xong thì `headers_sent()` thành true và hàm của mình lặng lẽ bỏ qua.
   Chẩn đoán trên máy anh: bộ nhớ 2G mới dùng 6 MB, ZipArchive có — nên KHÔNG phải hết bộ nhớ,
   mà là lỗi MÃ lúc dựng tệp. `try/catch` bắt được loại ấy và nói ra tệp nào, dòng nào. */
t( '🔴 lượt xuất bọc trong try/catch Throwable',
	strpos( $src_xuat, 'catch ( \\Throwable $e )' ) !== false );
t( 'và câu báo chỉ thẳng tệp + dòng hỏng',
	strpos( $src_xuat, 'getLine()' ) !== false
	&& strpos( $src_xuat, 'basename( $e->getFile() )' ) !== false );
/* ⚠️ Không dựng được tệp mà KHÔNG ném lỗi thì cũng phải nói ra vì sao — trước đây chỉ có câu
   "Không dựng được tệp .xlsx." trống trơn, đọc xong không biết làm gì. */
t( 'không dựng được tệp thì nói ra có ZipArchive hay không',
	strpos( $src_xuat, 'nhờ hosting bật phần mở rộng zip' ) !== false );

/* ⚠️ Đón rồi phải NÓI ĐÚNG BỆNH: hết bộ nhớ thì bảo xuất từng tháng / nâng memory_limit, chứ
   không phải một câu chung chung mà người đọc không làm gì được. */
t( 'và nói đúng bệnh khi hết bộ nhớ',
	strpos( $src_xuat, 'Máy chủ hết bộ nhớ' ) !== false );

/* ---- Tờ in thật ---- */
$_GET = array( 'to_in' => '1', 'ics' => 'TUTU_BT', 'itu' => '2026-08-01', 'iden' => '2026-08-31' );
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Người In', 'Kế toán', 'TUTU_BT', 'KT9' );
ob_start(); VHCC_Web::phuc_vu(); $in_to = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( '🔴 tờ in là MỘT trang HTML hoàn chỉnh, không lồng trong màn quản trị',
	substr_count( $in_to, '<!DOCTYPE html>' ) === 1, substr( $in_to, 0, 200 ) );
t( 'và mang khuôn giấy A4', strpos( $in_to, '@page{size:A4' ) !== false );
t( 'không dính thanh điều hướng của màn quản trị',
	strpos( $in_to, 'class="hieu"' ) === false );
t( 'có tên người in để biết tờ giấy do ai xuất',
	strpos( $in_to, 'Người In' ) !== false, $in_to );
/* 🔴 QUA MÀN HÌNH CŨNG PHẢI GỌN — mặc định không có mục chi tiết, và `&ct=1` bật lại. Soi ở
   đây chứ không chỉ soi hàm: đường địa chỉ mới là thứ anh Thắng bấm. */
t( '🔴 tờ in qua màn hình mặc định KHÔNG kèm mục chi tiết',
	strpos( $in_to, 'Chi tiết theo từng nhân viên' ) === false, $in_to );
$_GET = array( 'to_in' => '1', 'ics' => 'TUTU_BT', 'itu' => '2026-08-01', 'iden' => '2026-08-31',
	'ct' => '1' );
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Người In', 'Kế toán', 'TUTU_BT', 'KT9' );
ob_start(); VHCC_Web::phuc_vu(); $in_to = ob_get_clean();
$_GET = array(); $_COOKIE = array();

/* 🔴 PHẦN CHI TIẾT GOM THEO NGƯỜI, KHÔNG THEO NGÀY.
   Anh Thắng 28/08/2026: *"in theo ngày hàng dọc theo 1 nhân viên cho dễ nhìn nhé em"*. Tờ này
   đưa cho nhân viên KÝ vào công của chính mình — các ngày của một người phải nằm liền khối. */
t( '🔴 mục 2 đổi tên thành theo từng nhân viên',
	strpos( $in_to, 'Chi tiết theo từng nhân viên' ) !== false, $in_to );
t( 'và không còn xếp theo ngày', strpos( $in_to, 'Chi tiết từng ngày' ) === false );
t( '🔴 có hàng gom tên người', strpos( $in_to, 'class="nhom"' ) !== false, $in_to );
/* ⚠️ Hàng tên người không được đứng lẻ ở cuối trang: tên ở tờ này, các ngày sang tờ sau, thì
   người đọc tưởng người ấy không có ngày nào. */
t( '🔴 hàng tên người không rơi lẻ cuối trang',
	strpos( $in_to, 'tr.nhom{page-break-after:avoid' ) !== false );
/* Gom rồi thì mỗi dòng ngày lặp lại mã + tên là thừa chỗ trên tờ A4. */
t( 'bảng chi tiết bỏ hai cột Mã NV / Họ tên khỏi từng dòng',
	substr_count( $in_to, '<th>Họ và tên</th>' ) === 1, $in_to );
/* Số ngày và tổng giờ của mỗi người in ngay ở hàng tên — đó là con số họ ký vào. */
t( 'hàng tên người kèm số ngày', preg_match( '/\d+ ngày<\/td>/', $in_to ) === 1, $in_to );

/* ---- Khối chi tiết là hàm THUẦN — thử bằng dữ liệu trần, không phải dựng 500 hồ sơ ---- */
$pdf_th = array(
	array( 'ma' => 'B02', 'ten' => 'Bê Hai', 'soNgay' => 2, 'thieuRa' => 0, 'phut' => 600 ),
	array( 'ma' => 'A01', 'ten' => 'A Một',  'soNgay' => 1, 'thieuRa' => 1, 'phut' => 300 ),
);
$pdf_ct = array(
	array( 'ngay' => '2026-08-01', 'ma' => 'A01', 'ten' => 'A Một', 'vao' => '08:00:00',
		'ra' => '', 'gio' => '5.00h' ),
	array( 'ngay' => '2026-08-01', 'ma' => 'B02', 'ten' => 'Bê Hai', 'vao' => '08:00:00',
		'ra' => '13:00:00', 'gio' => '5.00h' ),
	array( 'ngay' => '2026-08-02', 'ma' => 'B02', 'ten' => 'Bê Hai', 'vao' => '08:00:00',
		'ra' => '13:00:00', 'gio' => '5.00h' ),
	/* Người CHỈ có ở phần chi tiết — cảnh mục 1 bị cắt vì quá 500 người. */
	array( 'ngay' => '2026-08-03', 'ma' => 'C03', 'ten' => 'Xê Ba', 'vao' => '09:00:00',
		'ra' => '17:00:00', 'gio' => '8.00h' ),
);
$pdf_k = VHCC_PDF::khoi_theo_nguoi( $pdf_th, $pdf_ct );
/* 🔴 THỨ TỰ NGƯỜI ĐI THEO MỤC 1, không sắp lại: hai mục trên cùng tờ giấy mà xếp khác nhau thì
   người đọc phải dò lại từ đầu mỗi lần liếc qua liếc lại. Mục 1 để "Bê Hai" TRƯỚC "A Một". */
t( '🔴 thứ tự người bám theo mục 1, không tự sắp lại',
	strpos( $pdf_k, 'Bê Hai' ) < strpos( $pdf_k, 'A Một' ), $pdf_k );
/* 🔴 Người chỉ có ở chi tiết vẫn phải in — cắt im lặng là tờ giấy trông đầy đủ mà thiếu người. */
t( '🔴 người không có trong mục 1 vẫn được in ra',
	strpos( $pdf_k, 'Xê Ba' ) !== false, $pdf_k );
t( 'và xếp sau những người có trong mục 1',
	strpos( $pdf_k, 'Xê Ba' ) > strpos( $pdf_k, 'A Một' ), $pdf_k );
/* Tổng giờ là con số nhân viên KÝ VÀO — thiếu nó thì khối này chỉ là một danh sách ngày. */
t( '🔴 hàng tên người in tổng giờ của người ấy',
	strpos( $pdf_k, '>10.00h</td>' ) !== false && strpos( $pdf_k, '>5.00h</td>' ) !== false, $pdf_k );
t( 'người không có ở mục 1 thì tổng để 0h, không bịa',
	substr_count( $pdf_k, '>0.00h</td>' ) === 1, $pdf_k );
t( 'ngày của mỗi người nằm liền khối',
	strpos( $pdf_k, '02/08/2026' ) < strpos( $pdf_k, 'A Một' ), $pdf_k );
t( 'thiếu giờ ra vẫn đánh dấu THIẾU', strpos( $pdf_k, 'THIẾU' ) !== false, $pdf_k );
t( 'khối rỗng thì nói không có dữ liệu, không nổ',
	strpos( VHCC_PDF::khoi_theo_nguoi( array(), array() ), 'Không có dữ liệu' ) !== false );

/* Người không đủ quyền bấm thẳng đường ấy thì nhận màn chối, KHÔNG nhận tờ giấy. */
$_GET = array( 'to_in' => '1', 'ics' => 'JP_HCM', 'itu' => '2026-08-01', 'iden' => '2026-08-31' );
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'CHT', 'Cửa hàng trưởng', 'TUTU_BT', 'IC1' );
ob_start(); VHCC_Web::phuc_vu(); $in_choi = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( '🔴 gõ thẳng đường tờ in của cơ sở khác thì bị chối',
	strpos( $in_choi, '@page{size:A4' ) === false, substr( $in_choi, 0, 400 ) );
t( 'và nói rõ vì sao', strpos( $in_choi, 'Không có quyền cơ sở này' ) !== false, $in_choi );
vhcc_dung_bang();

/* ==========================================================================================
 *  67. KẾ TOÁN VĂN PHÒNG — LẤY THEO VAI TRÒ, KHÔNG GÕ TAY TỪNG MÃ
 * ------------------------------------------------------------------------------------------
 *  Anh Thắng 27/08/2026: *"Lấy theo vai trò nhân viên là kế toán. hoặc vai trò khác, mình kích
 *  vào"*.
 *
 *  🔴 VÌ SAO ĐÁNG ĐỔI. Danh sách mã gõ tay là CUỐN SỔ THỨ HAI về cùng một sự thật. Người mới
 *  vào làm kế toán mà quên thêm mã thì họ không được áp khung thứ Bảy 08:30–12:00 và luật Chủ
 *  nhật nghỉ — công thiếu, lương thiếu, im lặng, và chỉ lộ ra nếu chính họ ngồi đếm lại. Người
 *  nghỉ việc thì mã ở lại đó mãi. Hồ sơ đã có ô Vai trò rồi; đọc thẳng nó thì sổ còn một cuốn.
 * ======================================================================================== */
/* ⚠️ CẤU HÌNH CÔNG NẰM Ở BẢNG `cai_dat`, KHÔNG PHẢI Ở OPTION. `delete_option()` không chạm
   tới nó — dọn bằng lệnh sai thì cấu hình của các khối thử TRƯỚC còn nguyên, `ktVaiTro` cũ đè
   lên, và phép thử đo phải một cảnh mình không dựng. */
vhcc_dung_bang();
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'cai_dat' ) . " WHERE khoa='VP_CONG_CFG'" );
foreach ( array(
	array( 'KV1', 'Kế toán A',   'Kế toán cá nhân' ),
	array( 'KV2', 'Kế toán B',   'Kế toán NCC' ),
	array( 'KV3', 'Nhân viên C', 'Nhân viên' ),
	array( 'KV4', 'Lẻ D',        'Nhân viên' ),
) as $kv ) {
	$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => $kv[0], 'ho_ten' => $kv[1],
		'vai_tro' => $kv[2], 'cua_hang' => 'VP_KT' ) );
}

/* 🔴 SO BẰNG MÃ VAI, KHÔNG SO BẰNG TÊN. Hồ sơ do người gõ tay nên có đủ kiểu viết, và công ty
   còn có vai TỰ TẠO quy về cùng một bậc. `VHCC_Vai::ma()` nhận hết và trả một mã duy nhất. */
$kv_ds = VHCC_Luong::vp_ma_theo_vai( array( 'Kế toán' ) );
sort( $kv_ds );
teq( '🔴 chọn vai "Kế toán" thì bắt được CẢ hai kiểu ghi trong hồ sơ',
	array( 'kv1', 'kv2' ), $kv_ds );
teq( 'nhận cả kiểu viết không dấu', array( 'kv1', 'kv2' ),
	( function () { $x = VHCC_Luong::vp_ma_theo_vai( array( 'ke toan' ) ); sort( $x ); return $x; } )() );
teq( 'chọn vai Nhân viên thì ra đúng nhóm kia', 2,
	count( VHCC_Luong::vp_ma_theo_vai( array( 'Nhân viên' ) ) ) );
teq( 'không chọn vai nào thì rỗng', array(), VHCC_Luong::vp_ma_theo_vai( array() ) );
teq( 'vai lạ thì rơi về Nhân viên (luật đáy thang), không ra rỗng oan', 2,
	count( VHCC_Luong::vp_ma_theo_vai( array( 'Vai Không Có Thật' ) ) ) );

/* Vai TỰ TẠO cũng phải khớp — "Kế toán POSH" kế thừa Kế toán nên nằm cùng nhóm. */
VHCC_Vai::quen_nho();
VHCC_Vai::dat_them( $U_AD, 'Kế toán POSH', VHCC_Vai::KE_TOAN );
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'KV5', 'ho_ten' => 'Kế toán POSH E',
	'vai_tro' => 'Kế toán POSH', 'cua_hang' => 'VP_KT' ) );
t( '🔴 vai TỰ TẠO kế thừa Kế toán cũng vào nhóm',
	in_array( 'kv5', VHCC_Luong::vp_ma_theo_vai( array( 'Kế toán' ) ), true ),
	VHCC_Luong::vp_ma_theo_vai( array( 'Kế toán' ) ) );
/* ⚠️ XOÁ CẢ HỒ SƠ KV5, không chỉ xoá vai tự tạo. Xoá vai đi thì tên "Kế toán POSH" vẫn khớp
   nhánh "mọi thứ bắt đầu bằng ke toan" của bảng cứng — người ấy vẫn ở trong nhóm, và mấy phép
   thử đếm bên dưới lệch một người. Mã đúng; cảnh dựng thiếu một bước dọn.
   ⚠️ Và lệnh dọn phải chèn kèm NGỮ CẢNH RIÊNG: chuỗi `delete_option( VHCC_Vai::O_THEM )` có ở
      nhiều khối, sửa "lần đầu tiên" là dọn nhầm khối khác — đúng bài học vừa rút ra ở vết phá. */
delete_option( VHCC_Vai::O_THEM ); VHCC_Vai::quen_nho();
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'nhan_vien' ) . " WHERE ma_nv='KV5'" );

/* ---- Cộng dồn: vai + mã lẻ ---- */
VHCC_Luong::dat_vp_cfg( $U_AD, array( 'ktVaiTro' => array( 'Kế toán' ), 'ktMaNV' => array( 'KV4' ) ) );
$kv_cfg = VHCC_Luong::vp_cfg();
sort( $kv_cfg['ktMaTinh'] );
teq( '🔴 CỘNG DỒN vai và mã lẻ, không thay thế nhau',
	array( 'kv1', 'kv2', 'kv4' ), $kv_cfg['ktMaTinh'] );
teq( 'ô mã lẻ vẫn giữ đúng thứ người ta gõ, không lẫn mã suy từ vai',
	array( 'kv4' ), $kv_cfg['ktMaNV'] );

/* 🔴 KHÔNG ĐÓNG BĂNG. `dat_vp_cfg()` lưu lại chính kết quả `vp_cfg()` — gộp vai vào `ktMaNV`
   là mỗi lượt bấm Lưu lại chụp một bản danh sách mã vào cấu hình. Từ đó đổi vai của ai cũng
   không ăn nữa, người nghỉ việc vẫn nằm trong đó, mà màn hình vẫn hiện đúng mấy ô tích vai —
   nên trông như đang chạy theo vai trong khi thực ra chạy theo một bản chụp cũ. */
VHCC_Luong::dat_vp_cfg( $U_AD, array( 'ktChuNhatNghi' => true ) );   // một lượt Lưu bất kỳ
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Nhân viên' ), array( 'ma_nv' => 'KV1' ) );
$kv_cfg = VHCC_Luong::vp_cfg();
sort( $kv_cfg['ktMaTinh'] );
teq( '🔴 đổi vai của một người thì danh sách theo NGAY, không đóng băng',
	array( 'kv2', 'kv4' ), $kv_cfg['ktMaTinh'] );
teq( 'và ô mã lẻ vẫn nguyên', array( 'kv4' ), $kv_cfg['ktMaNV'] );

/* Bỏ hết tích = khai rỗng, KHÔNG phải "bỏ khai" — người ta bỏ tích là CÓ Ý nói không lấy theo
   vai nữa. Coi là bỏ khai thì giá trị cũ ở lại, bấm Lưu bao nhiêu lần cũng không gỡ được. */
VHCC_Luong::dat_vp_cfg( $U_AD, array( 'ktVaiTro' => array() ) );
$kv_cfg = VHCC_Luong::vp_cfg();
teq( '🔴 bỏ hết tích vai thì chỉ còn mã lẻ', array( 'kv4' ), $kv_cfg['ktMaTinh'] );

/* ---- Màn hình ---- */
/* ⚠️ HAI ĐIỀU KIỆN MỚI DỰNG ĐƯỢC CẢNH, cả hai đều đã làm em đỏ oan một lượt:
   1. Dựng THẺ PHIÊN thẳng, đừng đăng nhập bằng PIN mẫu — PIN của mấy tài khoản mẫu đã bị chính
      các khối thử ở trên sửa đi nhiều lượt, nên `vhcc_web('246813')` rơi vào màn nhập PIN.
   2. Phải truyền `ccs` là một cơ sở đang tính THEO CÔNG. Khối Công thức cố ý chỉ hiện cho cơ sở
      ấy — cơ sở tính theo GIỜ thì bộ công thức bậc thang/ca đêm không hề được dùng tới, bày ra
      chỉ mời người ta khai một bộ số không ăn vào đâu. Không truyền `ccs` thì cả khối không vẽ,
      và phép thử đỏ vì màn không có khối chứ không phải vì khối thiếu ô. */
VHCC_NhanSu::xep_bo_phan( $U_AD, 'VP_KT', 'Văn phòng' );
teq( 'cơ sở thử đang tính theo CÔNG', 'cong', VHCC_Luong::cach_tinh( 'VP_KT' ) );
$h_kv = vhcc_web_nhu( 'KTADM', 'Kế toán', array( 'man' => 'cau_hinh', 'ccs' => 'VP_KT' ) );
t( '🔴 ô vai là Ô TÍCH, không phải ô gõ chữ',
	strpos( $h_kv, 'name="ctv[ktVaiTro][]"' ) !== false, $h_kv );
t( 'và tích từ CHÍNH danh sách vai đang có',
	strpos( $h_kv, 'value="Kế toán cá nhân"' ) !== false, $h_kv );
t( 'ô mã lẻ vẫn còn, cho người không mang vai ấy',
	strpos( $h_kv, 'name="ct[ktMaNV]"' ) !== false, $h_kv );
t( 'nhãn ô mã nói rõ nó là phần THÊM, không phải nơi khai chính',
	strpos( $h_kv, 'Thêm Mã NV lẻ' ) !== false, $h_kv );

/* ---- 🔴 ĐI HẾT ĐƯỜNG: người mang VAI kế toán phải được áp khung thứ Bảy ----
   Mấy phép thử trên mới soi tới `vp_cfg()['ktMaTinh']`. Chỗ TÍNH lại là một dòng khác, và nó
   từng đọc nhầm sang `ktMaNV` mà cả bộ thử vẫn xanh: `ktMaNV` chỉ chứa mã GÕ TAY, nên người
   được nhận vào nhóm bằng VAI rơi ra ngoài — bảng vẫn ra số, chỉ là số của một người thường.
   Không có phép thử nào chạy hết đường từ hồ sơ → cấu hình → con số thì cái đọc nhầm ấy im. */
VHCC_Luong::dat_vp_cfg( $U_AD, array( 'ktVaiTro' => array( 'Kế toán' ), 'ktMaNV' => array() ) );
$kv_c = VHCC_Luong::vp_cfg();
t( 'dựng cảnh: KV2 vào nhóm kế toán BẰNG VAI, không có tên trong ô mã lẻ',
	in_array( 'kv2', $kv_c['ktMaTinh'], true ) && ! in_array( 'kv2', $kv_c['ktMaNV'], true ),
	$kv_c['ktMaTinh'] );
t( 'và KV3 (Nhân viên) thì không', ! in_array( 'kv3', $kv_c['ktMaTinh'], true ) );
/* 01/08/2026 là thứ Bảy. Chọn giờ RA 15:00 có chủ ý: khung thứ Bảy của kế toán đóng lúc 12:00
   nên người ấy được tính 3,5 tiếng — đủ mốc 3 tiếng, ra tròn 1 công; người thường thì khung
   mở tới 17:00 nên được 6,5 tiếng, THIẾU mốc 7 tiếng, ra công lẻ. Ra 17:00 thì cả hai đều đủ
   mốc của mình và cùng ra 1 công — phép thử xanh mà không chứng minh được gì. */
vhcc_cham( 'VP_KT', '2026-08-01', 'KV2', '', '08:00:00', '15:00:00' );
vhcc_cham( 'VP_KT', '2026-08-01', 'KV3', '', '08:00:00', '15:00:00' );
$kv_b = VHCC_Luong::vp_bang_cong_va_luong( 'VP_KT', '2026-08' );
$kv_h = array();
foreach ( $kv_b['rows'] as $kv_r ) { $kv_h[ $kv_r['ma'] ] = $kv_r; }
t( '🔴 người mang VAI kế toán được chỗ TÍNH nhận ra là kế toán',
	! empty( $kv_h['KV2']['laKeToan'] ), array_keys( $kv_h ) );
t( 'người vai Nhân viên thì không', empty( $kv_h['KV3']['laKeToan'] ) );
/* Và cái nhãn ấy phải ĂN VÀO SỐ, không chỉ là một ô boolean nằm chơi: thứ Bảy của kế toán
   dùng khung giờ riêng (`ktThu7Tu`/`ktThu7Den`) nên cùng một cặp giờ vào–ra ra công khác nhau. */
t( 'dựng cảnh: khung thứ Bảy của kế toán khác khung ngày thường',
	$kv_c['ktThu7Den'] !== $kv_c['ngayDen'] || $kv_c['ktThu7Tu'] !== $kv_c['ngayTu'],
	$kv_c['ktThu7Tu'] . '-' . $kv_c['ktThu7Den'] . ' / ' . $kv_c['ngayTu'] . '-' . $kv_c['ngayDen'] );
teq( '🔴 kế toán: đóng khung lúc 12:00, đủ mốc 3 tiếng -> tròn 1 công',
	1.0, $kv_h['KV2']['congNgay'] );
teq( 'người thường: khung tới 17:00, thiếu mốc 7 tiếng -> công lẻ',
	0.81, $kv_h['KV3']['congNgay'] );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'cham_cong' ) . " WHERE coso='VP_KT'" );


/* ======================================================================================
 *  60. NGƯỜI LÀM TỪ HAI CƠ SỞ TRỞ LÊN — ghép vào cùng một hàng
 *
 *  Anh Thắng 27/08/2026: *"nhân viên mà làm từ 2 cơ sở trở lên thì cũng nhớ ghép lại giúp anh"*.
 *
 *  Trước đó lưới chỉ đọc đúng một cơ sở, nên ở lưới cơ sở A những ngày người ta làm tại B là ô
 *  TRỐNG — mà dấu chấm ở lưới này có nghĩa rất cụ thể: *không có dữ liệu chấm công*. Người rà
 *  bảng đi tìm "sao hôm ấy nghỉ mà không xin phép", còn người ấy thì đang đứng ở cơ sở kia.
 *
 *  🔴 Chốt nặng nhất của khối này: BÀY RA MÀ KHÔNG CỘNG VÀO. Lương tính theo cơ sở — đơn giá,
 *     khung ca, cách tính công đều của riêng cơ sở đó — nên cộng giờ của B vào bảng A là trả
 *     sai tiền ở CẢ HAI nơi, mà bảng thì trông đầy đủ hơn trước.
 * ====================================================================================== */
vhcc_dung_bang();
$CS_A = 'HAI_CS_A';
$CS_B = 'HAI_CS_B';
/* HC1 làm cả hai nơi; HC2 chỉ làm ở A — để canh cả chiều ngược lại. */
vhcc_cham( $CS_A, '2026-07-01', 'HC1', '', '08:00:00', '17:00:00' );
vhcc_cham( $CS_B, '2026-07-02', 'HC1', '', '09:00:00', '15:00:00' );   /* 6h ở cơ sở KIA */
vhcc_cham( $CS_A, '2026-07-01', 'HC2', '', '08:00:00', '17:00:00' );

$hc = VHCC_Cham::ngay_o_coso_khac( array( 'HC1', 'HC2' ), $CS_A, '2026-07' );
t( '🔴 tìm ra ngày người ấy đứng ở cơ sở khác', isset( $hc['HC1'][2] ), $hc );
teq( 'và nói đúng là cơ sở nào', $CS_B, $hc['HC1'][2]['coso'] );
teq( 'kèm số phút của ngày ấy', 360, (int) $hc['HC1'][2]['phut'] );
t( '🔴 KHÔNG kể ngày làm ở CHÍNH cơ sở đang xem — nếu không thì ngày nào cũng có dòng thừa',
	! isset( $hc['HC1'][1] ), $hc );
t( 'người chỉ làm một nơi thì không có gì', ! isset( $hc['HC2'] ), $hc );
/* Chỉ tra ĐÚNG những mã được truyền vào. Truyền mã lạ mà nó trả về dữ liệu là một cửa rò: hàm
   này cố ý không gác quyền, chỗ gác nằm ở lưới (`co_quyen_coso`) trước khi gọi. */
teq( '🔴 mã không nằm trong danh sách truyền vào thì không trả gì', array(),
	VHCC_Cham::ngay_o_coso_khac( array( 'HC2' ), $CS_A, '2026-07' ) );
teq( 'danh sách mã rỗng -> rỗng, không phải quét cả bảng', array(),
	VHCC_Cham::ngay_o_coso_khac( array(), $CS_A, '2026-07' ) );
teq( 'tháng khác -> rỗng', array(), VHCC_Cham::ngay_o_coso_khac( array( 'HC1' ), $CS_A, '2026-08' ) );

/* ---- Trên lưới ---- */
/* ⚠️ DỰNG THẺ PHIÊN THẲNG, đừng đăng nhập bằng PIN mẫu: khối này mở đầu bằng `vhcc_dung_bang()`
   nên sổ nhân sự vừa bị dọn sạch — `vhcc_web('135791')` sẽ rơi vào màn nhập PIN, và mọi phép
   thử dưới đây đỏ vì không có lưới chứ không phải vì lưới thiếu dòng. Đã vấp đúng chuyện này. */
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Quản trị', 'Admin', $CS_A . ',' . $CS_B, 'HCAD' );
$_GET = array( 'man' => 'vp', 'ccs' => $CS_A, 'cth' => '2026-07' );
$_POST = array();
ob_start(); VHCC_Web::phuc_vu(); $h_hc = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( 'dựng cảnh: lưới cơ sở A vẽ ra được', strpos( $h_hc, 'Lưới cả tháng' ) !== false,
	substr( $h_hc, 0, 600 ) );
/* 🔴 MỖI CƠ SỞ MỘT BẢNG RIÊNG — KHÔNG GỘP, KHÔNG HÀNG PHỤ.
   Anh Thắng 31/08/2026: *"Việc 1 cửa hàng trưởng quản lý nhiều cửa hàng, và nhân viên làm việc
   nhiều cửa hàng. Thì cứ để mỗi cửa hàng 1 bảng công riêng.. đôi khi cách tính công riêng, việc
   gộp lại cũng không hợp lý"*, và *"Tách ra luôn cho anh"*, *"Để xem bảng công số 2 thì chọn cơ
   sở"*.

   Trước bản này công của cơ sở kia bị kéo vào đây thành một hàng phụ: tính bằng công thức của
   cơ sở kia, nằm trong bảng của cơ sở này, KHÔNG sửa được, KHÔNG cộng vào tổng. Ba chữ "không"
   cho một hàng — nó chỉ tổ bắt người đọc nhớ ba ngoại lệ. Nay bảng nào ra bảng ấy. */
t( '🔴 KHÔNG còn hàng phụ của cơ sở kia', strpos( $h_hc, 'class="hang-phu"' ) === false, $h_hc );
t( 'KHÔNG còn dòng xám nhét trong ô',
	strpos( $h_hc, '<div class="mdem ngoai"' ) === false, $h_hc );
t( 'và KHÔNG còn tổng của cơ sở kia trong ô TỔNG',
	strpos( $h_hc, 'class="tk-ngoai"' ) === false, $h_hc );

/* 🔴 THAY VÀO ĐÓ: MỘT ĐƯỜNG BẤM SANG BẢNG CƠ SỞ KIA. Không có nó thì người quản hai cửa hàng
   phải tự nhớ mình còn phải mở cơ sở nào — và một người làm hai nơi mà bảng này chỉ có ba ngày
   thì nhìn hàng ấy tưởng họ nghỉ gần hết tháng. */
t( '🔴 cạnh tên có đường bấm sang bảng cơ sở kia',
	preg_match( '~class="di-cs"[^>]*href="[^"]*ccs=HAI_CS_B[^"]*"~', $h_hc ) === 1, $h_hc );
t( 'đường ấy mở đúng màn Bảng công',
	preg_match( '~class="di-cs"[^>]*href="[^"]*man=cham~', $h_hc ) === 1, $h_hc );
t( 'và có chữ "còn làm ở" cho người đọc hiểu vì sao có đường ấy',
	strpos( $h_hc, 'còn làm ở' ) !== false, $h_hc );
/* 🔴 CHỈ NGƯỜI LÀM HAI NƠI MỚI CÓ. Gắn cho cả bảng là mời người ta bấm sang một cơ sở mà người
   kia chưa từng đặt chân tới. */
teq( 'người chỉ làm một nơi thì KHÔNG có đường ấy', 1,
	substr_count( $h_hc, 'class="duoi ngoai"' ) );

/* 🔴 TỔNG KHÔNG ĐỔI. Đây là con số ra tiền — bày thêm một dòng để nhìn mà làm nó nhích lên là
   hỏng đúng thứ khối này hứa không đụng tới. */
$hc_b = VHCC_Cham::bang_cham_cong( $U_AD, $CS_A, '2026-07' );
$hc_t = 0;
foreach ( $hc_b['hang'] as $hc_r ) {
	if ( 'HC1' === $hc_r['maNV'] ) { $hc_t += (int) $hc_r['phut']; }
}
teq( '🔴 tổng giờ của người ấy ở cơ sở này vẫn đúng 9 tiếng, không ăn thêm 6 tiếng của cơ sở kia',
	540, $hc_t );
t( 'và ô TỔNG trên lưới vẫn in đúng con số ấy',
	strpos( $h_hc, '<td class="tong"><b>9h</b>' ) !== false, $h_hc );
t( 'lưới KHÔNG in ra con số 15h (9h + 6h) ở bất cứ đâu',
	strpos( $h_hc, '>15h<' ) === false, $h_hc );

/* ---- 🔴 Ô TỔNG PHẢI TÁCH RA: cơ sở này bao nhiêu, cơ sở kia bao nhiêu ----
   Anh Thắng 27/08/2026: *"phải hiện rõ cơ sở chính bao nhiêu công, cơ sở thứ 2 bao nhiêu công"*.
   Mấy dòng xám trong ô mới trả lời được "hôm ấy người ta ở đâu" — chưa trả lời được câu này. */
$hc_t2 = VHCC_Cham::tong_o_coso_khac( array( 'HC1', 'HC2' ), $CS_A, '2026-07' );
t( '🔴 cộng được tổng của cơ sở kia', isset( $hc_t2['HC1'][ $CS_B ] ), $hc_t2 );
teq( 'đúng số ngày làm ở cơ sở kia', 1, (int) $hc_t2['HC1'][ $CS_B ]['soNgay'] );
teq( 'và đúng số giờ (09:00–15:00 = 6h)', 6.0, (float) $hc_t2['HC1'][ $CS_B ]['gio'] );
t( 'người chỉ làm một nơi thì không có dòng nào', ! isset( $hc_t2['HC2'] ), $hc_t2 );
/* 🔴 Cơ sở kia tính THEO GIỜ thì KHÔNG có "công" để mà nói — trả null, đừng trả 0. Số 0 ở ô ấy
   đọc thành "làm mà không được công", sai hẳn nghĩa. */
teq( 'dựng cảnh: cơ sở kia đang tính theo GIỜ', 'gio', VHCC_Luong::cach_tinh( $CS_B ) );
teq( 'đơn vị nói đúng là giờ', 'gio', $hc_t2['HC1'][ $CS_B ]['donVi'] );
teq( '🔴 và cong = null, KHÔNG phải 0', null, $hc_t2['HC1'][ $CS_B ]['cong'] );
/* ⚠️ HÀM LÕI `tong_o_coso_khac()` VẪN GIỮ, dù lưới thôi in con số ấy: nó là thứ cho biết người
   này còn làm ở đâu, và đó chính là dữ liệu dựng nên đường bấm sang bảng kia. Bỏ hàm là bỏ luôn
   đường bấm. */
t( '🔴 lưới KHÔNG còn in tổng của cơ sở kia — con số ấy thuộc bảng của cơ sở ấy',
	strpos( $h_hc, 'class="tk-ngoai"' ) === false, $h_hc );

/* 🔴 CƠ SỞ KIA TÍNH THEO CÔNG THÌ PHẢI RA CÔNG, và tính bằng CÔNG THỨC CỦA CHÍNH NÓ.
   Đem công thức cơ sở đang xem áp lên giờ của cơ sở kia là ra một con số trông rất giống công
   mà không phải công của ai cả — tệ hơn là nó cộng được, nên sẽ có người cộng. */
$CS_VPB = 'HAI_VP_B';
vhcc_bo_phan( $CS_VPB, 'Văn phòng' );
teq( 'dựng cảnh: cơ sở thứ hai này tính theo CÔNG', 'cong', VHCC_Luong::cach_tinh( $CS_VPB ) );
vhcc_cham( $CS_A,    '2026-07-15', 'HC9', '', '08:00:00', '17:00:00' );
vhcc_cham( $CS_VPB,  '2026-07-16', 'HC9', '', '08:30:00', '17:00:00' );
$hc_t3 = VHCC_Cham::tong_o_coso_khac( array( 'HC9' ), $CS_A, '2026-07' );
teq( 'đơn vị nói đúng là công', 'cong', $hc_t3['HC9'][ $CS_VPB ]['donVi'] );
teq( '🔴 và ra CÔNG thật, tính bằng công thức của chính cơ sở ấy',
	1.0, (float) $hc_t3['HC9'][ $CS_VPB ]['cong'] );
/* ---- 🔴 CÙNG LUẬT Ở LƯỚI CÔNG. Hai lưới là HAI HÀM khác nhau (`ve_luoi_gio` / `ve_luoi_vp`),
   nên thử một cái không nói gì về cái kia. Cơ sở A ở trên không khai bộ phận nên tính THEO GIỜ
   — cả khối trên chưa hề chạm `ve_luoi_vp`. Đã phá thử để thấy đúng chuyện đó: bỏ hẳn dòng cơ
   sở khác ra khỏi lưới CÔNG mà bộ thử vẫn xanh. ---- */
$CS_VPA = 'HAI_VP_A';
vhcc_bo_phan( $CS_VPA, 'Văn phòng' );
teq( 'dựng cảnh: cơ sở này tính THEO CÔNG', 'cong', VHCC_Luong::cach_tinh( $CS_VPA ) );
vhcc_cham( $CS_VPA, '2026-07-01', 'HV1', '', '08:30:00', '17:00:00' );
vhcc_cham( $CS_B,   '2026-07-02', 'HV1', '', '09:00:00', '15:00:00' );   /* ngày ở cơ sở KIA */
vhcc_cham( $CS_VPA, '2026-07-01', 'HV2', '', '08:30:00', '17:00:00' );   /* chỉ làm một nơi */
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Quản trị', 'Admin', $CS_VPA . ',' . $CS_B, 'HCAD' );
$_GET = array( 'man' => 'vp', 'ccs' => $CS_VPA, 'cth' => '2026-07' );
$_POST = array();
ob_start(); VHCC_Web::phuc_vu(); $h_hv = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( 'dựng cảnh: lưới CÔNG vẽ ra được', strpos( $h_hv, 'Ô là <b>số công</b>' ) !== false,
	substr( $h_hv, 0, 600 ) );
t( '🔴 lưới CÔNG cũng KHÔNG còn dòng xám ghi cơ sở kia',
	strpos( $h_hv, '<div class="mdem ngoai"' ) === false, $h_hv );
t( 'và cũng KHÔNG còn tổng của cơ sở kia',
	strpos( $h_hv, 'class="tk-ngoai"' ) === false, $h_hv );
t( '🔴 mà có đường bấm sang bảng cơ sở kia, y như lưới GIỜ',
	preg_match( '~class="di-cs"[^>]*href="[^"]*ccs=HAI_CS_B~', $h_hv ) === 1, $h_hv );
/* 🔴 Đường bấm gắn cho ĐÚNG NGƯỜI. Gắn cả hàng là mời người ta bấm sang một cơ sở người kia
   chưa từng đặt chân tới. */
teq( '🔴 chỉ MỘT người có đường ấy, không phải cả bảng', 1,
	substr_count( $h_hv, 'class="duoi ngoai"' ) );

/* ---- Lõi: mấy chỗ dễ sai mà nhìn màn hình không thấy ---- */
/* Một ngày chấm ở HAI nơi khác nữa: ô chỉ đủ chỗ một dòng, giữ nơi làm NHIỀU giờ hơn. Giữ nơi
   ít giờ thì dòng ấy nói một nửa sự thật mà nghe như cả sự thật. */
/* ⚠️ Phải thử CẢ HAI CHIỀU, và cả hai đều phải NGƯỢC thứ tự đọc của câu truy vấn:
     · nơi NHIỀU giờ hơn nằm SAU (C 8h sau B 6h)  -> "giữ cái đầu tiên" thì sai
     · nơi ÍT giờ hơn nằm SAU  (D 2h sau C 8h)    -> "giữ cái cuối cùng" thì sai
   Chỉ thử một chiều thì phép thử xanh với đúng cái lỗi nó định canh — bản đầu của khối này
   đặt nơi ít giờ hơn ở sau, mà thứ tự đọc lại vốn đã trả nơi đúng ra trước, nên vết phá "giữ
   cái đầu tiên" không đỏ. */
$CS_C = 'HAI_CS_C';
$CS_D = 'HAI_CS_D';
vhcc_cham( $CS_C, '2026-07-02', 'HC1', '', '07:00:00', '15:00:00' );   /* 8h, NHIỀU hơn 6h ở B */
vhcc_cham( $CS_D, '2026-07-02', 'HC1', '', '18:00:00', '20:00:00' );   /* 2h, ít nhất, vào sau chót */
$hc3 = VHCC_Cham::ngay_o_coso_khac( array( 'HC1' ), $CS_A, '2026-07' );
teq( '🔴 một ngày chấm ở nhiều nơi khác -> giữ nơi làm NHIỀU giờ nhất', $CS_C, $hc3['HC1'][2]['coso'] );
teq( 'và giữ luôn số phút của chính nơi ấy', 480, (int) $hc3['HC1'][2]['phut'] );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'cham_cong' )
	. " WHERE coso='" . $CS_C . "' OR coso='" . $CS_D . "'" );

/* 🔴 Mã NV trong sổ có đủ kiểu viết hoa thường — máy đẩy về một kiểu, người nạp .csv gõ kiểu
   khác. Tra không chuẩn hoá thì người có mã chữ thường rơi ra ngoài: lưới im lặng không có
   dòng nào, y hệt như người ấy chỉ làm một nơi. */
vhcc_cham( $CS_B, '2026-07-03', 'hc1', '', '08:00:00', '12:00:00' );
$hc_th = VHCC_Cham::ngay_o_coso_khac( array( 'HC1' ), $CS_A, '2026-07' );
t( '🔴 mã chữ thường trong sổ vẫn khớp với mã chữ hoa của lưới',
	isset( $hc_th['HC1'][3] ), $hc_th );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'cham_cong' ) . " WHERE ma_nv='hc1'" );

vhcc_dung_bang();


/* ======================================================================================
 *  61. MÀN MÁY & FIRMWARE TRÊN WEB — hai màn wp-admin cuối cùng ra ngoài
 *
 *  Anh Thắng 27/08/2026: *"Máy & Firmware · Cổng nhận từ máy"*.
 *
 *  🔴 Chốt nặng nhất: ở wp-admin cửa là `manage_options` — phải có tài khoản WordPress quản
 *     trị mới vào được. Đưa ra web là BỎ MẤT lớp gác ấy, nên phải dựng lại bằng bậc vai, và
 *     dựng ở CẢ HAI chỗ: lúc vẽ màn và lúc nhận việc POST. Chỉ gác lúc vẽ thì ai đoán ra tên
 *     `viec` là gửi thẳng POST được — mà một trong mấy việc ấy là đẩy firmware cho cả 26 máy,
 *     và đẩy nhầm một bản là mất luôn đường sửa từ xa của cả chuỗi.
 * ====================================================================================== */
vhcc_dung_bang();
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'WM-1', 'mac' => 'W1', 'cua_hang' => 'TUTU_BT' ) );
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'WM-2', 'mac' => 'W2', 'cua_hang' => '' ) );
$wm_id = (int) $wpdb->get_var( "SELECT id FROM " . VHCC_DB::t( 'may' ) . " WHERE serial='WM-1'" );
$wpdb->insert( VHCC_DB::t( 'cho_gan' ), array( 'nhan_luc' => '2026-08-20 08:00:00',
	'serial' => 'WM-2', 'mac' => 'W2', 'ma_nv' => 'WMX', 'ho_ten' => 'Chờ Gán Web',
	'thoi_diem' => '2026-08-20 08:00:00', 'da_chuyen' => '' ) );

/* ⚠️ Phải có MỘT LỆNH ĐANG CHỜ. Bảng lệnh chỉ vẽ khi hàng đợi khác rỗng, nên không có lệnh nào
   thì cả nhánh vẽ bảng ấy không chạy — và phép thử "không có dòng script nào" soi một trang
   thiếu mất nguyên một khối. Đã phá thử để thấy đúng chuyện đó: nhét một thẻ <script> vào giữa
   bảng lệnh mà bộ thử vẫn xanh. */
VHCC_May::yeu_cau_quet( $wm_id );

function vhcc_may_web( $vai, $get = array(), $post = array() ) {
	$_GET  = array_merge( array( 'man' => 'may' ), $get );
	$_POST = $post;
	$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Người Thử', $vai, 'TUTU_BT', 'WMA' );
	ob_start(); VHCC_Web::phuc_vu(); $h = ob_get_clean();
	$_GET = array(); $_POST = array(); $_COOKIE = array();
	return $h;
}

/* ---- Thanh tab ---- */
$wm_ad = vhcc_may_web( 'Admin' );
t( 'Admin có tab Máy & Firmware', strpos( $wm_ad, '>Máy &amp; Firmware<' ) !== false, $wm_ad );
t( '🔴 Kế toán KHÔNG có tab ấy',
	strpos( vhcc_may_web( 'Kế toán' ), '>Máy &amp; Firmware<' ) === false );
t( 'Cửa hàng trưởng cũng không', strpos( vhcc_may_web( 'Cửa hàng trưởng' ), '>Máy &amp; Firmware<' ) === false );

/* ---- Màn vẽ ra đủ chín khối ---- */
foreach ( array( 'Cổng nhận chấm công từ máy', 'Nhật ký cổng', 'Danh sách máy',
	'Tải lại sổ chấm công từ đầu đọc', 'Sổ mặt đang nằm trong đầu đọc', 'Lượt bấm chờ gán',
	'Lệnh đang chờ xuống máy', 'Cập nhật firmware' ) as $wm_k ) {
	t( 'màn có khối "' . $wm_k . '"', strpos( $wm_ad, $wm_k ) !== false, $wm_k );
}
t( 'máy hiện ra trong danh sách', strpos( $wm_ad, 'WM-1' ) !== false, $wm_ad );
/* ⚠️ Soi Ô CỦA BẢNG, không soi chuỗi '(chưa gán)' trần: ô xổ chọn máy ở ba khối dưới cũng in
   đúng chữ ấy, nên soi trần thì bỏ hẳn nhãn đỏ ở bảng đi phép thử vẫn xanh. */
t( '🔴 máy chưa gán cơ sở được kêu tên NGAY TRONG BẢNG, và bằng chữ đỏ',
	strpos( $wm_ad, '<span class="chu-hong">(chưa gán)</span>' ) !== false, $wm_ad );
t( 'lượt bấm chờ gán hiện ra', strpos( $wm_ad, 'Chờ Gán Web' ) !== false, $wm_ad );
/* Cả màn quản trị này không có lấy một dòng script — gập/xổ dùng <details> của chính HTML. */
t( '🔴 màn Máy KHÔNG có một dòng script nào',
	stripos( $wm_ad, '<script' ) === false
	&& ! preg_match( '/\son[a-z]+\s*=\s*["\']/i', $wm_ad ), $wm_ad );

/* ---- 🔴 KHÔNG IN KHOÁ RA MÀN HÌNH ----
   Trang này chạy ngoài internet và ảnh chụp màn hình đi khắp nơi. Lộ `VHCC_KHOA_MAY` là ai cũng
   đẩy được lượt chấm công GIẢ vào bảng lương — cùng lối với luật không bao giờ in PIN. */
/* ⚠️ `VHCC_KHOA_MAY` là HẰNG SỐ, và bộ thử đã khai nó ở đầu tệp — không gỡ ra được giữa chừng.
   Nên cảnh "chưa khai khoá" soi ở MÃ NGUỒN, còn cảnh "đã khai" soi ở màn thật. */
t( 'có khoá thì màn báo đã cấu hình', strpos( $wm_ad, 'Đã cấu hình khoá' ) !== false, $wm_ad );
t( '🔴 nhưng KHÔNG in giá trị khoá ra màn hình',
	strpos( $wm_ad, VHCC_KHOA_MAY ) === false, $wm_ad );
$wm_goc = file_get_contents( $goc . '/wordpress/vhcp-cham-cong/includes/class-vhcc-web-may.php' );
t( 'màn có nhánh kêu lên khi chưa khai khoá',
	strpos( $wm_goc, 'cổng đang ĐÓNG' ) !== false );
t( 'và nhánh ấy chỉ đúng chỗ khai: wp-config.php, không phải cơ sở dữ liệu',
	strpos( $wm_goc, 'wp-config.php' ) !== false );
/* 🔴 Và mã KHÔNG được có chỗ nào NỐI hằng số ấy vào chuỗi in ra. Phép thử trên chỉ soi màn ở
   đúng một nhánh; một dòng `echo '…' . VHCC_KHOA_MAY` nằm trong nhánh khác thì nó không thấy.
   ⚠️ Soi dạng NỐI CHUỖI (`. VHCC_KHOA_MAY`), không soi chữ `VHCC_KHOA_MAY` trần: cái tên ấy có
      mặt hợp lệ ở hai chỗ — trong `defined()` và trong câu chỉ đường "khai vào wp-config" — nên
      soi tên trần là đỏ oan, rồi có người "sửa" bằng cách bỏ câu chỉ đường đi. */
t( '🔴 mã màn không NỐI giá trị khoá vào chuỗi in ra ở bất kỳ nhánh nào',
	! preg_match( '/\.\s*(?:esc_\w+\(\s*)?(?:\(string\)\s*)?VHCC_KHOA_MAY/', $wm_goc ), $wm_goc );

/* ---- 🔴 CHỐT POST: không vẽ nút không có nghĩa là không gửi được ---- */
$wm_r = vhcc_goi_rieng( 'VHCC_WebMay', 'viec',
	array( 'may_ota', array( 'name' => 'KT', 'role' => 'Kế toán', 'coso' => 'TUTU_BT' ) ) );
t( '🔴 Kế toán POST thẳng việc đẩy firmware bị CHỐI',
	is_array( $wm_r ) && isset( $wm_r[0]['loi'] ), $wm_r );
foreach ( array( 'may_gan', 'may_quet', 'may_tai_lai', 'may_xoa_lenh', 'may_ota_mot',
	'may_go_ota', 'may_dung_tai_lai', 'may_sim' ) as $wm_v ) {
	$wm_x = vhcc_goi_rieng( 'VHCC_WebMay', 'viec',
		array( $wm_v, array( 'name' => 'Q', 'role' => 'Quản lý', 'coso' => 'TUTU_BT' ) ) );
	t( 'việc "' . $wm_v . '" cũng chối người dưới bậc Admin',
		is_array( $wm_x ) && isset( $wm_x[0]['loi'] ), $wm_v );
}
/* Và màn cũng phải chối, không chỉ việc — người mò được `?man=may` thì thấy gì. */
$wm_ke = vhcc_may_web( 'Kế toán', array( 'man' => 'may' ) );
t( 'Kế toán mò thẳng ?man=may cũng không thấy nút firmware',
	strpos( $wm_ke, 'may_ota' ) === false, $wm_ke );
/* 🔴 CHỐT LÚC VẼ MÀN PHẢI THỬ BẰNG CÁCH GỌI THẲNG HÀM.
   Đi qua `?man=may` thì `man_cua()` đã không khai màn ấy cho Kế toán, nên `$man` rơi về màn mặc
   định và hàm vẽ KHÔNG BAO GIỜ chạy — phép thử trên xanh vì một lý do khác hẳn thứ nó tưởng
   đang canh. Bỏ hẳn chốt trong `VHCC_WebMay::man()` mà bộ thử vẫn xanh; đã phá thử để thấy.
   Chốt ấy vẫn phải giữ và phải có phép thử: nó che một hàm ở LỚP KHÁC (`man_cua` bên
   `VHCC_Web`), nên ai nới bảng tab một ngày nào đó thì cửa này vẫn đóng. */
ob_start();
VHCC_WebMay::man( 'ky-thu', array( 'name' => 'KT', 'role' => 'Kế toán', 'coso' => 'TUTU_BT' ) );
$wm_ve = ob_get_clean();
t( '🔴 gọi thẳng hàm vẽ màn với bậc Kế toán: bị chối',
	strpos( $wm_ve, 'Không vào được màn này' ) !== false, $wm_ve );
t( 'và không vẽ ra một nút firmware nào', strpos( $wm_ve, 'may_ota' ) === false, $wm_ve );
t( 'cũng không lộ danh sách máy', strpos( $wm_ve, 'WM-1' ) === false, $wm_ve );

/* ---- Danh sách trắng của việc: tên lạ KHÔNG phải việc của màn này ---- */
t( '🔴 tên việc lạ không lọt vào màn Máy', ! VHCC_WebMay::la_viec( 'ota' ) );
t( 'và tên việc thật thì nhận', VHCC_WebMay::la_viec( 'may_ota' ) );
/* 🔴 DANH SÁCH TRẮNG, KHÔNG PHẢI SO TIỀN TỐ. So bằng tiền tố `may` thì mọi tên bịa bắt đầu bằng
   chữ ấy đều được nhận vào — và một việc được nhận vào nhưng không có nhánh xử là màn trả về
   rỗng, tức người bấm không thấy gì xảy ra và cũng không thấy lỗi. Tệ hơn: nó CHẶN mất nhánh
   xử của các màn khác nếu sau này có việc nào trùng tiền tố. */
foreach ( array( 'may_xoa_het', 'mayota', 'may_', 'may_ota_tat_ca' ) as $wm_la ) {
	t( 'tên bịa "' . $wm_la . '" KHÔNG được nhận là việc của màn Máy',
		! VHCC_WebMay::la_viec( $wm_la ), $wm_la );
}

/* ---- Việc chạy thật qua đúng cửa POST của trang ---- */
$wm_tok = VHCC_Auth::phat_token( 'Quản trị', 'Admin', 'TUTU_BT', 'WMA' );
$_COOKIE[ VHCC_Web::COOKIE ] = $wm_tok;
$_GET  = array( 'man' => 'may' );
$_POST = array( 'viec' => 'may_gan', 'ky' => VHCC_Web::chu_ky( $wm_tok ),
	'may_id' => (int) $wpdb->get_var( "SELECT id FROM " . VHCC_DB::t( 'may' ) . " WHERE serial='WM-2'" ),
	'coso' => 'POSH_HCM' );
ob_start(); VHCC_Web::phuc_vu(); ob_end_clean();
$_GET = array(); $_POST = array(); $_COOKIE = array();
teq( '🔴 gán cơ sở qua TRANG THẬT thì bảng máy đổi theo', 'POSH_HCM',
	$wpdb->get_var( "SELECT cua_hang FROM " . VHCC_DB::t( 'may' ) . " WHERE serial='WM-2'" ) );
t( 'và lượt bấm đang chờ tự vào bảng chấm công', null !== $wpdb->get_row(
	"SELECT * FROM " . VHCC_DB::t( 'cham_cong' ) . " WHERE ma_nv='WMX'", ARRAY_A ) );

/* ---- OTA: nút thử MỘT máy đứng trước, và không đòi gõ xác nhận ---- */
t( 'màn có nút thử riêng một máy', strpos( $wm_ad, 'may_ota_mot' ) !== false, $wm_ad );
t( 'và nút đẩy cả chuỗi', strpos( $wm_ad, 'may_ota"' ) !== false, $wm_ad );
/* 🔴 Nút THỬ MỘT MÁY phải đứng TRƯỚC nút đẩy cả chuỗi. Đây không phải chuyện bày biện: bản hỏng
   đẩy cho cả 26 máy thì không còn đường gọi về, phải đi từng cửa hàng cắm USB. Thứ tự trên màn
   là thứ quyết định người ta bấm cái nào trước. */
t( '🔴 nút thử một máy đứng TRƯỚC nút đẩy cả chuỗi',
	strpos( $wm_ad, 'may_ota_mot' ) < strpos( $wm_ad, 'value="may_ota"' ), $wm_ad );
t( 'và màn cảnh báo trước khi đẩy cả chuỗi',
	strpos( $wm_ad, 'Đọc trước khi đẩy' ) !== false, $wm_ad );
/* Đẩy cả chuỗi mà không gõ xác nhận thì phải chối — chốt nằm ở `dat_ota`, ở đây canh nó CÒN
   ĐƯỢC GỌI TỚI, kẻo màn web lặng lẽ bỏ qua tham số xác nhận. */
/* ⚠️ Phải truyền ver + url HỢP LỆ, không thì `dat_ota` chối vì THIẾU Ô chứ không phải vì thiếu
   xác nhận — và lúc ấy phép thử xanh cả khi màn web lặng lẽ tự điền "DONG Y" hộ người dùng.
   Đã phá thử để thấy đúng chuyện đó. */
$_POST = array( 'ver' => '9.9.9', 'url' => 'https://raw.githubusercontent.com/chu/repo/bin/fw.bin' );
$wm_ota = VHCC_WebMay::viec( 'may_ota', array( 'name' => 'A', 'role' => 'Admin' ) );
$_POST = array();
t( '🔴 đẩy cả chuỗi mà không gõ DONG Y thì chối',
	is_array( $wm_ota ) && empty( $wm_ota[0]['ok'] ), $wm_ota );
/* Còn nút THỬ MỘT MÁY thì cố ý KHÔNG đòi xác nhận — đây chính là bước nên làm trước, đừng dựng
   rào ở đúng cái việc mình muốn người ta làm. */
$_POST = array( 'ver' => '9.9.9', 'url' => 'https://raw.githubusercontent.com/chu/repo/bin/fw.bin',
	'may_id' => $wm_id );
$wm_ota1 = VHCC_WebMay::viec( 'may_ota_mot', array( 'name' => 'A', 'role' => 'Admin' ) );
$_POST = array();
t( '🔴 nhưng thử RIÊNG MỘT MÁY thì không cần gõ xác nhận',
	is_array( $wm_ota1 ) && ! empty( $wm_ota1[0]['ok'] ), $wm_ota1 );
vhcc_dung_bang();


/* ======================================================================================
 *  62. MÁY CHÍNH Ở CƠ SỞ ĐẨY VỀ CẢ LÔ
 *
 *  Anh Thắng 27/08/2026: *"máy chính tại cơ sở gửi dữ liệu công về"*.
 *
 *  Máy ZKTeco nằm trong mạng nội bộ (192.168.0.2x:4370) — website ngoài internet không có
 *  đường nào gọi vào, và không nên có. Nên giữ nguyên chiều "máy tự gọi ra": một máy CHÍNH
 *  đứng trong mạng ấy đọc log rồi đẩy về đúng cổng này, đúng khoá này, cả ngày một lần.
 * ====================================================================================== */
vhcc_dung_bang();
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'ZK-LR', 'mac' => '', 'cua_hang' => 'TUTU_BT' ) );
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'ZK-VP', 'mac' => '', 'cua_hang' => 'JP_HCM' ) );

/* 🔴 MỖI DÒNG MANG MÃ MÁY CON RIÊNG. Máy chính đại diện cho NHIỀU đầu đọc, mỗi đầu một phòng
   (Lắp Ráp · Lò Sấy · Sơ Chế · Văn Phòng · Đóng Gói). Lấy mã của máy CHÍNH để ghép cơ sở là
   dồn công của cả năm phòng vào một chỗ — bảng vẫn đầy số, chỉ là số của sai nơi. */
list( $lo_ma, $lo_kq ) = vhcc_may_gui( array(
	'macAddress' => 'PC:MAY:CHINH', 'stationName' => 'May chinh',
	'logs' => array(
		array( 'hikSerial' => 'ZK-LR', 'employeeNo' => 'ZA1', 'name' => 'Người A',
			'time' => '2026-07-06 08:00:00' ),
		array( 'hikSerial' => 'ZK-LR', 'employeeNo' => 'ZA1', 'name' => 'Người A',
			'time' => '2026-07-06 17:30:00' ),
		array( 'hikSerial' => 'ZK-VP', 'employeeNo' => 'ZB1', 'name' => 'Người B',
			'time' => '2026-07-06 09:00:00' ),
	),
) );
teq( 'cổng nhận lô: HTTP 200', 200, $lo_ma );
t( 'và trả về đúng dấu hiệu lô', ! empty( $lo_kq['lo'] ), $lo_kq );
teq( 'đếm đúng số dòng nhận được', 3, (int) $lo_kq['nhan'] );
teq( '🔴 dòng của máy Lắp Ráp vào ĐÚNG cơ sở của máy ấy', array( 8 * 3600, 17 * 3600 + 1800 ),
	array( (int) vhcc_hang( 'TUTU_BT', '2026-07-06', 'ZA1' )['gio_vao_giay'],
		(int) vhcc_hang( 'TUTU_BT', '2026-07-06', 'ZA1' )['gio_ra_giay'] ) );
t( '🔴 dòng của máy Văn Phòng vào cơ sở KHÁC, không dồn chung',
	null !== vhcc_hang( 'JP_HCM', '2026-07-06', 'ZB1' ) );
t( 'và KHÔNG lọt sang cơ sở của máy kia',
	null === vhcc_hang( 'TUTU_BT', '2026-07-06', 'ZB1' ) );

/* 🔴 DÒNG ĐÈ LÊN GÓI, KHÔNG PHẢI NGƯỢC LẠI. Máy chính có mã của chính nó, nhưng mã ghép ra cơ
   sở phải là mã của ĐẦU ĐỌC ở dòng ấy. Để gói đè lên dòng là dồn công của cả năm phòng vào một
   chỗ — bảng vẫn đầy số, chỉ là số của sai nơi, và không có gì báo. */
list( , $lo_de ) = vhcc_may_gui( array(
	'hikSerial' => 'ZK-LR',                                   // mã CHUNG của gói
	'logs' => array( array( 'hikSerial' => 'ZK-VP',           // dòng khai RIÊNG, phải thắng
		'employeeNo' => 'ZDE', 'time' => '2026-07-20 08:00:00' ) ),
) );
t( '🔴 mã máy của DÒNG thắng mã chung của gói',
	null !== vhcc_hang( 'JP_HCM', '2026-07-20', 'ZDE' ), $lo_de );
t( 'và KHÔNG vào cơ sở của mã chung', null === vhcc_hang( 'TUTU_BT', '2026-07-20', 'ZDE' ) );

/* Dòng thiếu mã máy thì lấy của gói — để máy chỉ có MỘT đầu đọc vẫn gửi gọn được. */
list( , $lo2 ) = vhcc_may_gui( array(
	'hikSerial' => 'ZK-LR',
	'logs' => array( array( 'employeeNo' => 'ZA2', 'time' => '2026-07-07 08:10:00' ) ),
) );
t( '🔴 dòng thiếu mã máy thì lấy mã CHUNG của gói',
	null !== vhcc_hang( 'TUTU_BT', '2026-07-07', 'ZA2' ), $lo2 );

/* 🔴 MỘT DÒNG HỎNG KHÔNG ĐƯỢC KÉO CẢ LÔ XUỐNG. Bỏ cả lô vì một dòng sai khuôn giờ là mất công
   thật của cả trăm người — mà cái sai ấy đẩy lại bao nhiêu lần cũng y vậy. */
list( $lo3_ma, $lo3 ) = vhcc_may_gui( array(
	'hikSerial' => 'ZK-LR',
	'logs' => array(
		array( 'employeeNo' => 'ZA3', 'time' => '2026-07-08 08:00:00' ),
		array( 'employeeNo' => 'ZA4', 'time' => 'hôm qua' ),          // sai khuôn giờ
		array( 'employeeNo' => '',    'time' => '2026-07-08 08:00:00' ), // thiếu mã NV
		'không phải mảng',
		array( 'employeeNo' => 'ZA5', 'time' => '2026-07-08 09:00:00' ),
	),
) );
teq( 'lô có dòng hỏng vẫn trả 200', 200, $lo3_ma );
t( '🔴 mấy dòng LÀNH vẫn vào sổ', null !== vhcc_hang( 'TUTU_BT', '2026-07-08', 'ZA3' )
	&& null !== vhcc_hang( 'TUTU_BT', '2026-07-08', 'ZA5' ), $lo3 );
teq( 'và đếm đúng số dòng bỏ qua', 3, (int) $lo3['boQua'] );
t( '🔴 kể ra SỐ THỨ TỰ dòng hỏng, để máy chính biết đẩy lại dòng nào',
	isset( $lo3['hong'][0]['i'] ) && 1 === (int) $lo3['hong'][0]['i'], $lo3 );
t( 'và nói vì sao hỏng', ! empty( $lo3['hong'][0]['vi_sao'] ), $lo3 );

/* Đẩy LẠI cả lô: giờ vào/ra chỉ được nới rộng nên chạy lại bao nhiêu lần cũng ra một kết quả.
   Đó là thứ làm cho "đẩy lại khi nghi ngờ" thành nước đi an toàn. */
$truoc = vhcc_hang( 'TUTU_BT', '2026-07-06', 'ZA1' );
vhcc_may_gui( array( 'hikSerial' => 'ZK-LR', 'logs' => array(
	array( 'employeeNo' => 'ZA1', 'time' => '2026-07-06 08:00:00' ),
	array( 'employeeNo' => 'ZA1', 'time' => '2026-07-06 17:30:00' ),
) ) );
$sau = vhcc_hang( 'TUTU_BT', '2026-07-06', 'ZA1' );
teq( '🔴 đẩy lại cả lô KHÔNG đổi giờ đã có',
	array( (int) $truoc['gio_vao_giay'], (int) $truoc['gio_ra_giay'] ),
	array( (int) $sau['gio_vao_giay'], (int) $sau['gio_ra_giay'] ) );
teq( 'và không đẻ thêm hàng', 1, (int) $wpdb->get_var( 'SELECT COUNT(*) FROM '
	. VHCC_DB::t( 'cham_cong' ) . " WHERE ma_nv='ZA1' AND ngay='2026-07-06'" ) );

/* Máy CHƯA gán cơ sở: giữ tạm, không bỏ — bỏ là mất công của người thật vì cái máy chưa khai. */
list( , $lo4 ) = vhcc_may_gui( array(
	'hikSerial' => 'ZK-LA-CHUA-KHAI',
	'logs' => array( array( 'employeeNo' => 'ZC1', 'time' => '2026-07-09 08:00:00' ) ),
) );
teq( '🔴 lượt của máy chưa gán cơ sở được GIỮ TẠM, không bỏ', 1, (int) $lo4['choGan'] );
teq( 'và nằm trong bảng chờ gán', 1, (int) $wpdb->get_var( 'SELECT COUNT(*) FROM '
	. VHCC_DB::t( 'cho_gan' ) . " WHERE ma_nv='ZC1'" ) );

/* Lô rỗng: không phải lỗi, chỉ là không có gì để ghi. */
list( $lo5_ma, $lo5 ) = vhcc_may_gui( array( 'hikSerial' => 'ZK-LR', 'logs' => array() ) );
teq( 'lô rỗng vẫn 200', 200, $lo5_ma );
teq( 'và nói rõ nhận 0 dòng', 0, (int) $lo5['nhan'] );

/* 🔴 TRẦN SỐ DÒNG — và CẮT THÌ PHẢI NÓI RA. Cắt im lặng là gói trông "xong" trong khi thiếu
   người, mà máy chính thì đã xoá phần chưa gửi khỏi sổ của nó. */
$lo_dai = array();
for ( $i_lo = 0; $i_lo < VHCC_Nhan::LO_TOI_DA + 5; $i_lo++ ) {
	$lo_dai[] = array( 'employeeNo' => 'ZD' . $i_lo, 'time' => '2026-07-10 08:00:00' );
}
list( , $lo6 ) = vhcc_may_gui( array( 'hikSerial' => 'ZK-LR', 'logs' => $lo_dai ) );
teq( 'lô quá dài: xử đúng tới trần', VHCC_Nhan::LO_TOI_DA, (int) $lo6['xu'] );
teq( '🔴 và NÓI RA còn bao nhiêu dòng chưa xử', 5, (int) $lo6['conLai'] );

/* 🔴 CƠ SỞ DỮ LIỆU HỎNG LÀ CA DUY NHẤT PHẢI KÊU LÊN.
   Mọi ca khác (sai khuôn giờ, thiếu mã NV) đẩy lại bao nhiêu lần cũng hỏng y vậy nên trả
   SUCCESS là đúng. Nhưng bảng hỏng thì đẩy lại SẼ khác — mà máy đọc thấy SUCCESS là xoá lượt
   khỏi sổ của nó, và lượt bấm ấy mất hẳn. Không có phép thử nào chạm nhánh này thì bỏ hẳn nó
   đi bộ thử vẫn xanh; đã phá thử để thấy.
   ⚠️ Dựng cảnh bằng cách THẢ BẢNG chấm công — cách duy nhất làm `ghi_gio` trả lỗi thật mà
      không phải bịa một lớp giả. Nhớ dựng lại ngay sau. */
$wpdb->query( 'DROP TABLE ' . VHCC_DB::t( 'cham_cong' ) );
list( $lo_h_ma, $lo_h ) = vhcc_may_gui( array( 'hikSerial' => 'ZK-LR', 'logs' => array(
	array( 'employeeNo' => 'ZH1', 'time' => '2026-07-12 08:00:00' ) ) ) );
t( '🔴 lô gặp bảng hỏng thì KHÔNG trả 200/SUCCESS', 200 !== $lo_h_ma, $lo_h_ma );
list( $don_h_ma ) = vhcc_may_gui( vhcc_goi( 'ZH2', '2026-07-12 08:00:00' ) );
t( '🔴 gói ĐƠN cũng vậy — bảng hỏng thì 500, không phải SUCCESS', 200 !== $don_h_ma, $don_h_ma );
vhcc_dung_bang();
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'ZK-LR', 'mac' => '', 'cua_hang' => 'TUTU_BT' ) );

/* Cổng vẫn phải đòi khoá — lô không phải cửa sau. */
list( $lo7_ma ) = vhcc_may_gui(
	array( 'hikSerial' => 'ZK-LR', 'logs' => array(
		array( 'employeeNo' => 'ZE1', 'time' => '2026-07-11 08:00:00' ) ) ), 'khoa-sai' );
teq( '🔴 lô mà sai khoá thì bị chối, không phải cửa sau', 401, $lo7_ma );
t( 'và KHÔNG ghi được gì', null === vhcc_hang( 'TUTU_BT', '2026-07-11', 'ZE1' ) );
vhcc_dung_bang();


/* ======================================================================================
 *  63. GHÉP BẢNG CÔNG CỦA HAI CƠ SỞ
 *
 *  Anh Thắng 27/08/2026: *"muốn ghép 2 bảng công lại thì như nào, vì VP_HCM có công SETUP
 *  (tức công đêm đó em), hay giờ add vào khó thì anh sửa tay"*.
 *
 *  Ca đêm của Văn phòng được chấm vào một MÃ CƠ SỞ RIÊNG, nên engine dựng cho nó một bảng
 *  riêng. Nhưng nó không phải nơi làm việc khác: cùng người, cùng bảng lương, chỉ khác ca.
 *
 *  🔴 KHÁC HẲN "CƠ SỞ KHÁC" (khối 60). Cơ sở khác thì bày ra mà KHÔNG cộng — lương tính theo
 *     cơ sở. Cơ sở GHÉP thì phải CỘNG VÀO. Trộn hai khái niệm là hoặc trả thiếu tiền, hoặc
 *     trả thừa — và cả hai đều ra một bảng đầy số trông rất bình thường.
 * ====================================================================================== */
vhcc_dung_bang();
$G_VP = 'GH_VP_HCM';
$G_SU = 'GH_SETUP_VP';
vhcc_bo_phan( $G_VP, 'Văn phòng' );
vhcc_bo_phan( $G_SU, 'Văn phòng' );
/* ⚠️ Một cơ sở ĐỨNG RIÊNG trong cảnh. Chỉ có một chính + một phụ thì mọi hàng đều mang nhãn,
   và vết phá "gắn nhãn cho MỌI hàng" — đúng cái làm nhãn hết nghĩa — vẫn xanh. */
$G_KHO = 'GH_KHO_RIENG';
vhcc_bo_phan( $G_KHO, 'Văn phòng' );
$u_gh = array( 'role' => 'Admin' );

/* ---- Lõi khai ghép ---- */
$r_gh = VHCC_Luong::dat_ghep( $u_gh, array( $G_SU => $G_VP ) );
t( 'khai ghép: xong', ! empty( $r_gh['ok'] ), $r_gh );
teq( 'cơ sở phụ biết mình ghép vào đâu', $G_VP, VHCC_Luong::ghep_vao( $G_SU ) );
teq( 'cơ sở chính biết ai ghép vào mình', array( $G_SU ), VHCC_Luong::phu_cua( $G_VP ) );
teq( '🔴 chùm của bảng chính gồm CẢ HAI mã', array( $G_VP, $G_SU ), VHCC_Luong::chum_cua( $G_VP ) );
teq( 'cơ sở đứng riêng thì chùm chỉ có chính nó', array( 'TUTU_BT' ), VHCC_Luong::chum_cua( 'TUTU_BT' ) );

/* 🔴 MỘT CẤP, KHÔNG DÂY CHUYỀN. A→B rồi B→C thì công của A rơi vào bảng nào là câu không ai
   trả lời chắc; khai vòng (A→B, B→A) thì bảng chạy vô hạn. */
$r_day = VHCC_Luong::dat_ghep( $u_gh, array( $G_VP => 'TUTU_BT' ) );
t( '🔴 cơ sở đang CÓ người ghép vào thì không được ghép tiếp',
	! empty( $r_day['bo_qua'] ), $r_day );
teq( 'và nó vẫn đứng nguyên là bảng chính', '', VHCC_Luong::ghep_vao( $G_VP ) );
$r_vong = VHCC_Luong::dat_ghep( $u_gh, array( 'TUTU_BT' => $G_SU ) );
t( '🔴 không ghép vào một cơ sở vốn đang ghép đi nơi khác', ! empty( $r_vong['bo_qua'] ), $r_vong );
teq( 'nên TUTU_BT vẫn đứng riêng', '', VHCC_Luong::ghep_vao( 'TUTU_BT' ) );
/* ⚠️ Dùng một cơ sở CHƯA ghép đi đâu. Lấy `$G_SU` (đang ghép vào `$G_VP`) thì chốt "ghép dây
   chuyền" bắt trước, và chốt "ghép vào chính nó" không bao giờ là chốt quyết định — bỏ hẳn nó
   đi phép thử vẫn xanh. Đã phá thử để thấy đúng chuyện đó. */
teq( 'dựng cảnh: TUTU_BT chưa ghép đi đâu', '', VHCC_Luong::ghep_vao( 'TUTU_BT' ) );
$r_minh = VHCC_Luong::dat_ghep( $u_gh, array( 'TUTU_BT' => 'TUTU_BT' ) );
t( '🔴 không ghép một cơ sở vào chính nó', ! empty( $r_minh['bo_qua'] ), $r_minh );
teq( 'và nó vẫn đứng riêng', '', VHCC_Luong::ghep_vao( 'TUTU_BT' ) );
/* 🔴 Bỏ dòng nào thì KÊU ĐÍCH DANH. Im lặng bỏ là cuối tháng thiếu công cả một ca, mà màn hình
   đã báo "đã lưu". */
t( 'và mỗi dòng bị bỏ đều nói rõ vì sao',
	is_string( $r_day['bo_qua'][0] ) && strlen( $r_day['bo_qua'][0] ) > 20, $r_day );
/* Quyền: đổi ghép là đổi con số ra tiền của cả cơ sở. */
$r_nv = VHCC_Luong::dat_ghep( array( 'role' => 'Cửa hàng trưởng' ), array( $G_SU => $G_VP ) );
t( '🔴 Cửa hàng trưởng KHÔNG khai ghép được', empty( $r_nv['ok'] ), $r_nv );

/* ---- Bảng công thật sự CỘNG cả hai mã ---- */
vhcc_cham( $G_VP, '2026-07-01', 'GN1', '', '08:30:00', '17:00:00' );   // ca ngày, mã chính
vhcc_cham( $G_SU, '2026-07-02', 'GN1', '', '08:30:00', '17:00:00' );   // ca "SETUP", mã phụ
$b_gh = VHCC_Luong::vp_bang_cong_va_luong( $G_VP, '2026-07' );
$h_gh = array();
foreach ( $b_gh['rows'] as $r_g ) { $h_gh[ $r_g['ma'] ] = $r_g; }
teq( '🔴 bảng của cơ sở CHÍNH gồm luôn công của cơ sở phụ (1 + 1 = 2)',
	2.0, (float) $h_gh['GN1']['tong'] );
/* Và ngày ấy phải còn dấu vết đến từ đâu — cộng đúng mà không soi lại được là con số không
   kiểm được. */
$tu_gh = '';
foreach ( $b_gh['detail'] as $d_g ) {
	if ( '2026-07-02' === $d_g['ngay'] && 'GN1' === $d_g['ma'] ) { $tu_gh = (string) $d_g['tuCoSo']; }
}
teq( '🔴 ngày đến từ cơ sở phụ còn giữ dấu vết mã cơ sở ấy', $G_SU, $tu_gh );

/* 🔴 CƠ SỞ ĐÃ GHÉP KHÔNG CÒN LÀ "CƠ SỞ KHÁC". Lọt vào đó là ngày ấy vừa được cộng vào TỔNG,
   vừa hiện thêm một dòng xám nói "chỗ khác" — người đọc thấy hai lần một ngày công. */
$ck_gh = VHCC_Cham::ngay_o_coso_khac( array( 'GN1' ), $G_VP, '2026-07' );
teq( '🔴 cơ sở đã ghép KHÔNG hiện ra như cơ sở khác', array(), $ck_gh );
$tk_gh = VHCC_Cham::tong_o_coso_khac( array( 'GN1' ), $G_VP, '2026-07' );
teq( 'và cũng không có dòng TỔNG cơ sở khác', array(), $tk_gh );

/* ---- 🔴 HẬU TỐ `-TC` (TĂNG CƯỜNG) PHẢI ĐƯỢC TÍNH ----
   Anh Thắng 27/08/2026: *"đã ghép nhưng sao bảng phụ không hiện ra"* — `SETUP_VP` ghép vào Văn
   phòng, dữ liệu vào đủ, mà lưới không có một ô nào của nó. Vì mã trong sổ ấy đều mang hậu tố
   `-TC`, và engine Văn phòng chỉ nhận `CD`/`CT`.
   `TC` là hậu tố CÓ THẬT, đã khai trong `class-vhcc-db.php`: *tăng cường (người của cơ sở khác
   sang làm)*. Người đi làm thật, giờ nằm trong sổ thật — bỏ nó là mất công của người thật, mà
   bảng vẫn đầy số nên không ai nghi. Đây là dữ liệu THẬT anh gửi: 21:30 → 04:00, tức ca đêm. */
vhcc_cham( $G_SU, '2026-07-05', 'GN2', 'TC', '21:30:00', '04:00:00' );
$b_tc = VHCC_Luong::vp_bang_cong_va_luong( $G_VP, '2026-07' );
$h_tc = array();
foreach ( $b_tc['rows'] as $r_t ) { $h_tc[ $r_t['ma'] ] = $r_t; }
t( '🔴 hàng -TC vào được bảng, không bị bỏ im lặng', isset( $h_tc['GN2'] ), array_keys( $h_tc ) );
t( 'và ra CÔNG ĐÊM — 21:30–04:00 nằm trong khung đêm, `vp_ca_hang2` phân theo GIỜ',
	(float) $h_tc['GN2']['congDem'] > 0, $h_tc['GN2'] );
teq( 'không có hàng chính nên công ngày là 0', 0.0, (float) $h_tc['GN2']['congNgay'] );

/* 🔴 NHƯNG `TT` (Thu Tiền) và `TG` (Trực Ghế) VẪN PHẢI LOẠI: hai cái đó là nhiệm vụ MTD, có
   engine riêng và đơn giá riêng — kéo vào bảng Văn phòng là tính hai lần. */
vhcc_cham( $G_SU, '2026-07-06', 'GN3', 'TT', '08:00:00', '17:00:00' );
vhcc_cham( $G_SU, '2026-07-06', 'GN4', 'TG', '08:00:00', '17:00:00' );
$b_tt = VHCC_Luong::vp_bang_cong_va_luong( $G_VP, '2026-07' );
$h_tt = array();
foreach ( $b_tt['rows'] as $r_2 ) { $h_tt[ $r_2['ma'] ] = $r_2; }
t( '🔴 hàng -TT (nhiệm vụ MTD) KHÔNG lọt vào bảng Văn phòng', ! isset( $h_tt['GN3'] ), array_keys( $h_tt ) );
t( 'hàng -TG cũng vậy', ! isset( $h_tt['GN4'] ), array_keys( $h_tt ) );
/* 🔴 BỎ THÌ PHẢI ĐẾM. Im lặng bỏ đúng là cái đã làm cả sổ SETUP_VP biến mất mà không ai biết. */
t( 'engine ĐẾM số hàng bị bỏ theo hậu tố', ! empty( $b_tt['boHauTo'] ), $b_tt['boHauTo'] );
teq( 'đếm đúng một hàng -TT', 1, (int) $b_tt['boHauTo']['TT'] );
teq( 'và một hàng -TG', 1, (int) $b_tt['boHauTo']['TG'] );
t( 'KHÔNG đếm -TC vào đó, vì nó ĐƯỢC tính', ! isset( $b_tt['boHauTo']['TC'] ), $b_tt['boHauTo'] );

/* ---- Trên màn ---- */
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Quản trị', 'Admin', $G_VP . ',' . $G_SU, 'GHAD' );
$_GET = array( 'man' => 'vp', 'ccs' => $G_VP, 'cth' => '2026-07' );
$_POST = array();
ob_start(); VHCC_Web::phuc_vu(); $h_ghw = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( '🔴 bảng ghép NÓI RA nó đang gồm những cơ sở nào',
	strpos( $h_ghw, 'Bảng này <b>đã gồm</b>' ) !== false, $h_ghw );
t( 'và kể tên cơ sở phụ', strpos( $h_ghw, $G_SU ) !== false, $h_ghw );
t( '🔴 ô đến từ cơ sở phụ có nhãn ngay trong ô',
	preg_match( '~<div class="mghep"[^>]*>' . preg_quote( $G_SU, '~' ) . '</div>~', $h_ghw ) === 1, $h_ghw );
t( 'nhãn ấy nói rõ công ĐÃ nằm trong cột TỔNG',
	strpos( $h_ghw, 'ĐÃ nằm trong cột TỔNG' ) !== false, $h_ghw );
/* 🔴 Và lưới KÊU LÊN số hàng bị bỏ vì hậu tố — thiếu câu này là cả một cơ sở biến mất mà bảng
   vẫn đầy số. Chính chỗ đã làm anh Thắng phải đi hỏi. */
t( '🔴 lưới kêu lên số hàng KHÔNG vào bảng vì hậu tố',
	strpos( $h_ghw, 'hàng KHÔNG vào bảng này' ) !== false, $h_ghw );
t( 'và kể ĐÍCH DANH hậu tố nào, bao nhiêu hàng',
	preg_match( '~<code>-TT</code> \(1 hàng\)~u', $h_ghw ) === 1, $h_ghw );
t( 'kèm câu chỉ đường: hậu tố lạ thì sửa mã trong tệp rồi nạp lại',
	strpos( $h_ghw, 'nạp lại' ) !== false, $h_ghw );
/* 🔴 Mở thẳng cơ sở PHỤ: vẫn xem được để soi, nhưng phải nói ngay là số ở đây ĐÃ tính vào bảng
   kia — không thì có người lấy cả hai bảng rồi cộng lại, và trả gấp đôi. */
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Quản trị', 'Admin', $G_VP . ',' . $G_SU, 'GHAD' );
$_GET = array( 'man' => 'vp', 'ccs' => $G_SU, 'cth' => '2026-07' );
ob_start(); VHCC_Web::phuc_vu(); $h_ghp = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( '🔴 mở thẳng cơ sở phụ thì màn CẢNH BÁO là số đã tính vào bảng kia',
	strpos( $h_ghp, 'đã được tính vào bảng kia' ) !== false, $h_ghp );
t( 'và cho đường sang bảng chính', strpos( $h_ghp, 'Mở bảng ' . $G_VP ) !== false, $h_ghp );

/* ---- Khối khai trên màn Cấu hình, và lưu qua đúng cửa POST ---- */
$tok_gh = VHCC_Auth::phat_token( 'Quản trị', 'Admin', $G_VP . ',' . $G_SU . ',TUTU_BT', 'GHAD' );
$_COOKIE[ VHCC_Web::COOKIE ] = $tok_gh;
$_GET = array( 'man' => 'cau_hinh' );
$_POST = array();
ob_start(); VHCC_Web::phuc_vu(); $h_ghc = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( 'màn Cấu hình có khối Ghép bảng công',
	strpos( $h_ghc, 'Ghép bảng công của hai cơ sở' ) !== false, $h_ghc );
t( '🔴 và nói rõ chỗ khác nhau với dòng xám "cơ sở khác"',
	strpos( $h_ghc, 'Chỉ ghép khi ĐÚNG LÀ MỘT BẢNG LƯƠNG' ) !== false, $h_ghc );

/* ---- 🔴 NHÌN LÀ BIẾT CÁI NÀO CHÍNH, CÁI NÀO PHỤ ----
   Anh Thắng 27/08/2026, sau khi khai xong: *"như cái này biết cái nào bảng chính, cái nào bảng
   phụ"*. Bảng CÓ nói — ở cột thứ ba. Nhưng xếp A-Z thì bảng chính và mấy cơ sở phụ của nó nằm
   rải rác cách nhau mấy hàng, nên muốn biết cái nào thuộc cái nào là phải đọc cả bảng rồi tự
   ghép trong đầu. */
t( '🔴 cơ sở PHỤ mang nhãn PHỤ ngay cạnh tên',
	strpos( $h_ghc, '<span class="duoi nhan-phu">PHỤ</span>' ) !== false, $h_ghc );
t( '🔴 cơ sở CHÍNH mang nhãn CHÍNH ngay cạnh tên',
	strpos( $h_ghc, '<span class="duoi nhan-chinh">CHÍNH</span>' ) !== false, $h_ghc );
/* ⚠️ CẮT ĐÚNG KHỐI GHÉP RỒI MỚI ĐO. Tên cơ sở xuất hiện ở CẢ khối "Cơ sở thuộc bộ phận" và
   "Cách tính công" phía trên, và hai khối ấy xếp A-Z — nên đo trên cả trang là đo nhầm sang
   bảng khác, và ra kết luận ngược hẳn. Đã vấp đúng chuyện đó. */
$kh_gh = preg_match( '~id="ghepcs".*?</details>~s', $h_ghc, $m_kg ) ? $m_kg[0] : '';
t( 'dựng cảnh: cắt được đúng khối Ghép bảng công', '' !== $kh_gh, substr( $h_ghc, 0, 200 ) );
/* Đếm nhãn trong THÂN BẢNG, không phải cả khối: câu "Cách đọc bảng dưới" cũng in hai nhãn ấy
   làm ví dụ — đó là chú thích, không phải hàng. */
$tb_gh = preg_match( '~<tbody>.*?</tbody>~s', $kh_gh, $m_tg ) ? $m_tg[0] : '';
/* ⚠️ Cảnh phải có MỘT CƠ SỞ ĐỨNG RIÊNG. Chỉ có một chính + một phụ thì mọi hàng đều mang nhãn,
   và "gắn nhãn cho mọi hàng" — đúng cái làm nhãn hết nghĩa — vẫn xanh. Đã phá thử để thấy.
   TUTU_BT ở trên đã thử ghép vào chính nó và bị chối, nên nó đứng riêng. */
t( 'dựng cảnh: có một cơ sở đứng riêng trong bảng',
	strpos( $tb_gh, '<b>' . $G_KHO . '</b>' ) !== false, $tb_gh );
teq( '🔴 cơ sở đứng riêng KHÔNG mang nhãn nào — nhãn cho mọi hàng thì nhãn hết nghĩa',
	2, substr_count( $tb_gh, 'class="duoi nhan-' ) );
t( 'và hàng của nó nói rõ là bảng lương riêng, đứng một mình',
	strpos( $tb_gh, 'đứng một mình' ) !== false, $tb_gh );
/* 🔴 XẾP THEO NHÓM: hàng phụ đứng NGAY DƯỚI bảng chính của nó, và thụt vào. */
t( 'hàng phụ được thụt vào và đánh dấu', strpos( $tb_gh, '<tr class="hang-phu">' ) !== false, $tb_gh );
/* ⚠️ SO THỨ TỰ HÀNG, đừng so vị trí chuỗi tên: tên cơ sở phụ còn xuất hiện trong CỘT THỨ BA
   của chính hàng CHÍNH ("Đã gồm công của: GH_SETUP_VP") và trong mọi ô xổ xuống — `strpos`
   bắt được cái gần nhất chứ không phải hàng của nó. Đã vấp đúng chuyện đó. */
preg_match_all( '~<tr[^>]*>.*?</tr>~s', $tb_gh, $m_hg );
$hg = $m_hg[0];
teq( 'dựng cảnh: bảng có ba hàng (1 chính + 1 phụ + 1 đứng riêng)', 3, count( $hg ) );
/* Tìm hàng của bảng CHÍNH, rồi soi hàng NGAY SAU nó. Không giả định nó đứng đầu bảng: mấy cơ
   sở đứng riêng vẫn xếp A-Z nên bảng chính có thể nằm ở giữa. Thứ cần canh là "phụ đi liền
   sau chính", không phải "chính đứng đầu". */
$i_chinh = -1;
foreach ( $hg as $i_h => $h_row ) {
	if ( strpos( $h_row, '<b>' . $G_VP . '</b>' ) !== false ) { $i_chinh = (int) $i_h; break; }
}
t( 'dựng cảnh: tìm được hàng của bảng chính', $i_chinh >= 0, $tb_gh );
t( '🔴 hàng ấy mang nhãn CHÍNH', strpos( $hg[ $i_chinh ], 'nhan-chinh' ) !== false, $hg[ $i_chinh ] );
t( 'dựng cảnh: có hàng đứng ngay sau nó', isset( $hg[ $i_chinh + 1 ] ), $tb_gh );
t( '🔴 hàng NGAY SAU là cơ sở phụ của nó, thụt vào — không rải rác theo bảng chữ cái',
	strpos( $hg[ $i_chinh + 1 ], '<b>' . $G_SU . '</b>' ) !== false
	&& strpos( $hg[ $i_chinh + 1 ], 'nhan-phu' ) !== false
	&& strpos( $hg[ $i_chinh + 1 ], 'hang-phu' ) !== false, $hg[ $i_chinh + 1 ] );
/* 🔴 CANH QUAN HỆ HAI LỚP. Bảng có một nhánh vớt "cơ sở phụ mà bảng CHÍNH của nó nằm ngoài
   tầm xem" — nhánh ấy HIỆN KHÔNG BAO GIỜ chạy, vì khối này đòi quyền `ngoai_coso` (bậc Quản
   lý) mà bậc ấy đã có `cong_tat_ca` nên `ds_coso_xem()` trả về MỌI cơ sở. Giữ nhánh là để
   phòng ngày `ds_coso_xem()` lọc theo cơ sở phụ trách đúng như tên nó gợi ý — lúc ấy thiếu
   nhánh này là cơ sở phụ biến mất khỏi màn và không ai gỡ ghép được nữa.
   Nói thẳng quan hệ ấy ra đây, kèm phép thử: quan hệ đổi thì phép thử đỏ, và người sửa biết
   phải xem lại nhánh vớt. */
t( '🔴 ai mở được khối Ghép thì thấy MỌI cơ sở (nên nhánh vớt hiện là phòng xa)',
	VHCC_Vai::duoc( array( 'role' => 'Quản lý' ), 'ngoai_coso' )
	&& VHCC_Vai::duoc( array( 'role' => 'Quản lý' ), 'cong_tat_ca' ) );
t( 'cột cuối nói bằng CÂU công chạy đi đâu, không bằng thuật ngữ',
	strpos( $h_ghc, 'cộng vào bảng ' . $G_VP ) !== false, $h_ghc );
t( 'và màn dạy cách đọc bảng ngay trên đầu',
	strpos( $h_ghc, 'Cách đọc bảng dưới' ) !== false, $h_ghc );
$_COOKIE[ VHCC_Web::COOKIE ] = $tok_gh;
$_POST = array( 'viec' => 'ghep_cs', 'ky' => VHCC_Web::chu_ky( $tok_gh ),
	'gh' => array( $G_SU => '' ) );                       // bỏ ghép
ob_start(); VHCC_Web::phuc_vu(); ob_end_clean();
$_POST = array(); $_COOKIE = array();
teq( '🔴 bỏ ghép qua TRANG THẬT thì cơ sở phụ về lại bảng riêng', '', VHCC_Luong::ghep_vao( $G_SU ) );
$b_bo = VHCC_Luong::vp_bang_cong_va_luong( $G_VP, '2026-07' );
$h_bo = array();
foreach ( $b_bo['rows'] as $r_b ) { $h_bo[ $r_b['ma'] ] = $r_b; }
teq( 'và bảng chính hết cộng công của cơ sở ấy (còn 1)', 1.0, (float) $h_bo['GN1']['tong'] );
vhcc_dung_bang();


/* ======================================================================================
 *  64. /cham-cong/ THÀNH TRANG DÙNG CHUNG · và hàng sửa hết lệch khung
 *
 *  Anh Thắng 27/08/2026: *"trang này là trang gì, không nhập pin được. Được chuyển nó trang
 *  trang dùng chung đi, mọi người truy cập vào link này"* — kèm ảnh ô PIN nền tối.
 *
 *  Trang ấy vốn kéo `Index.html` thẳng từ project Apps Script rồi chèn cầu nối. Từ 22/08/2026
 *  hệ đã bỏ Firebase và Apps Script, nên project ấy không còn được nuôi: trang còn vỏ mà không
 *  còn ruột, và ô PIN không vào được.
 * ====================================================================================== */
$GLOBALS['VHCP_CHUYEN'] = '';
$GLOBALS['VHCP_QVAR']['vhcc_app'] = 1;
$_GET = array();
VHCC_Trang::maybe_render();
$tc_di = (string) $GLOBALS['VHCP_CHUYEN'];
t( '🔴 /cham-cong/ CHUYỂN HƯỚNG, không kéo giao diện Apps Script nữa', '' !== $tc_di, $tc_di );
t( 'và dẫn về đúng trang dùng chung', strpos( $tc_di, VHCC_Web::url() ) === 0, $tc_di );

/* 🔴 CHỞ THEO THAM SỐ. Anh đã gửi cho các bộ phận những link kèm `?man=cham`; vứt tham số là
   người nhận bấm vào rơi về màn mặc định, không thấy thứ người gửi bảo họ xem. */
$GLOBALS['VHCP_CHUYEN'] = '';
$_GET = array( 'man' => 'cham', 'cth' => '2026-08' );
VHCC_Trang::maybe_render();
$tc_ts = (string) $GLOBALS['VHCP_CHUYEN'];
t( '🔴 chở theo tham số của link cũ', strpos( $tc_ts, 'man=cham' ) !== false, $tc_ts );
t( 'cả tháng đang xem', strpos( $tc_ts, 'cth=2026-08' ) !== false, $tc_ts );
t( 'nhưng KHÔNG chở theo mấy tham số của chính đường ấy',
	strpos( $tc_ts, 'vhcc_app' ) === false, $tc_ts );

/* ⚠️ CỬA API KHÔNG ĐƯỢC CHUYỂN HƯỚNG. Chuyển hướng một lời gọi API là đổi nó thành một trang
   HTML — bên gọi nhận về rác mà không hiểu vì sao. */
/* ⚠️ KHÔNG gọi thẳng nhánh ấy: `VHCC_API::trang()` kết bằng `exit`, gọi trong bộ thử là giết cả
   lượt chạy. Soi ở MÃ NGUỒN rằng nhánh API đứng TRƯỚC phần chuyển hướng — thứ tự ấy chính là
   thứ giữ cho lời gọi API không bị đổi thành một trang HTML. */
$tc_goc = file_get_contents( $goc . '/wordpress/vhcp-cham-cong/includes/class-vhcc-trang.php' );
$vt_api = strpos( $tc_goc, "isset( \$_GET['vhcc_api'] )" );
$vt_chuyen = strpos( $tc_goc, 'wp_safe_redirect' );
t( 'dựng cảnh: thấy cả hai nhánh trong mã', false !== $vt_api && false !== $vt_chuyen );
t( '🔴 nhánh API đứng TRƯỚC phần chuyển hướng — lời gọi API không bị đổi thành trang HTML',
	$vt_api < $vt_chuyen, $vt_api . ' vs ' . $vt_chuyen );
$_GET = array();
unset( $GLOBALS['VHCP_QVAR']['vhcc_app'] );

/* ---- 🔴 HÀNG SỬA HẾT LỆCH KHUNG ----
   Anh Thắng: *"lệch ô sửa"* — kèm ảnh khối vàng kéo dài sang phải và nút Lưu bị cắt ngoài mép.
   `colspan` phủ hết 33 cột nên ô ấy rộng bằng CẢ BẢNG; biểu mẫu bên trong trải theo, ô "Vì sao"
   dài mấy nghìn điểm ảnh và nút Lưu nằm ngoài tầm nhìn. Người ta thấy hàng sửa mở ra mà không
   thấy nút bấm, rồi tưởng hỏng. */
/* ⚠️ DỰNG THẺ PHIÊN THẲNG, đừng đăng nhập bằng PIN mẫu: PIN của mấy tài khoản mẫu đã bị chính
   các khối thử phía trên sửa đi nhiều lượt, nên `vhcc_web('135791')` rơi vào màn nhập PIN và
   phép thử đỏ vì không có lưới, chứ không phải vì hàng sửa lệch. Đã vấp đúng chuyện này. */
vhcc_cham( 'LS_CS', '2026-07-06', 'LS1', '', '08:00:00', '17:00:00' );
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Quản trị', 'Admin', 'LS_CS', 'LSAD' );
$_GET = array( 'man' => 'cham', 'ccs' => 'LS_CS', 'cth' => '2026-07',
	'sgn' => '2026-07-06', 'sgm' => 'LS1' );
$_POST = array();
ob_start(); VHCC_Web::phuc_vu(); $h_ls = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( 'dựng cảnh: hàng sửa mở ra', strpos( $h_ls, 'class="hang-sua"' ) !== false, substr( $h_ls, 0, 400 ) );
/* ⚠️ Neo `#suaday` nay nằm trên ĐÚNG Ô đang sửa (một `<td class="dang-sua">` trong hàng
   người), không trên hàng sửa (xem khối dưới) — nên đừng pin nó vào regex này, kẻo phép thử
   về chuyện GHIM BÊN TRÁI lại đỏ vì một chuyện về CUỘN. */
t( '🔴 ruột hàng sửa nằm trong khối GHIM BÊN TRÁI',
	preg_match( '~<tr class="hang-sua"[^>]*><td colspan="\d+"><div class="hs-in">~', $h_ls ) === 1,
	$h_ls );
/* 🔴 NEO ĐẶT TRÊN ĐÚNG Ô ĐANG SỬA (trong hàng của người), KHÔNG TRÊN HÀNG SỬA.
   Anh Thắng 27/08/2026: *"bấm vào nó vẫn cứ nhảy chỗ sửa"* — kèm ảnh hàng người đang sửa bị cắt
   mất nửa ở mép trên. Neo trên hàng sửa thì trình duyệt kéo đúng hàng ấy lên đỉnh và đẩy hàng
   người (cùng cái ô vừa bấm) khuất lên trên: mở biểu mẫu ra rồi mất luôn chỗ đứng.
   29/08/2026: neo còn dời tiếp từ CẢ HÀNG người xuống ĐÚNG Ô — neo trên cả hàng chỉ cuộn dọc
   (một hàng 31 cột luôn có mẩu "trong tầm nhìn" bất kể cuộn ngang đâu), nên khung `.cuon`
   không cuộn NGANG sang đúng cột ngày — đúng ca "nhảy loạn xạ" anh báo. Neo trên đúng ô (hẹp)
   thì trình duyệt bắt buộc cuộn cả hai chiều. */
t( '🔴 hàng SỬA không còn mang neo', strpos( $h_ls, 'class="hang-sua" id="suaday"' ) === false, $h_ls );
t( 'và neo nằm đúng một chỗ trong trang', 1 === substr_count( $h_ls, 'id="suaday"' ), $h_ls );
/* Neo phải đứng TRƯỚC hàng sửa trong luồng HTML — đứng sau thì cuộn tới nó là biểu mẫu nằm
   ngoài tầm nhìn phía trên, hỏng y như cũ, chỉ theo chiều ngược lại. */
$vt_neo = strpos( $h_ls, 'id="suaday"' );
$vt_sua = strpos( $h_ls, 'class="hang-sua"' );
t( '🔴 neo đứng TRƯỚC hàng sửa', false !== $vt_neo && false !== $vt_sua && $vt_neo < $vt_sua,
	$vt_neo . ' / ' . $vt_sua );
/* Và nó phải nằm TRONG ĐÚNG HÀNG của người đang sửa — neo trên ô của người khác thì cuộn tới
   sai người, mà biểu mẫu thì ở tận đâu. Kiểm bằng cách: tên "Người LS1" xuất hiện TRƯỚC neo, và
   neo xuất hiện TRƯỚC khi hàng của LS1 đóng lại (`</tr>` kế tiếp) — tức cùng một hàng. */
$vt_ten_ls1  = strpos( $h_ls, 'Người LS1' );
$vt_dong_tr  = ( false !== $vt_ten_ls1 ) ? strpos( $h_ls, '</tr>', $vt_ten_ls1 ) : false;
t( 'neo nằm TRONG hàng của ĐÚNG người đang sửa (không lọt sang hàng khác)',
	false !== $vt_ten_ls1 && false !== $vt_neo && false !== $vt_dong_tr
		&& $vt_ten_ls1 < $vt_neo && $vt_neo < $vt_dong_tr,
	$vt_ten_ls1 . ' / ' . $vt_neo . ' / ' . $vt_dong_tr );
t( 'và khối ấy được ghim thật trong bảng kiểu',
	strpos( $h_ls, '.hs-in{position:sticky;left:0;' ) !== false, $h_ls );
t( 'rộng theo KHUNG NHÌN, không theo bề rộng bảng',
	strpos( $h_ls, 'width:calc(100vw - 56px)' ) !== false, $h_ls );
/* 🔴 FORM Bù/Sửa PHẢI TỰ MANG NEO TRONG `action` — anh Thắng 29/08/2026: *"Bấm thêm bù thì
   thêm vào luôn chứ"*. Form không nêu `action` thì POST về đúng URL đang xem nhưng KHÔNG kèm
   phần neo (`#...` không bao giờ đi theo khi form tự nộp) — trang MỚI sau khi lưu tải lại từ
   đỉnh, người bấm Lưu/Bù giờ thấy trang nhảy lên đầu và phải tự cuộn xuống mới biết có ăn hay
   chưa. Nêu tay `action="...#suaday"` thì trình duyệt tự cuộn lại đúng chỗ sau khi lưu. */
t( '🔴 form sửa/bù tự nêu action mang sẵn #suaday (không để trống)',
	preg_match( '~<form method="post" action="[^"]*sgn=2026-07-06[^"]*sgm=LS1[^"]*#suaday"~', $h_ls ) === 1,
	$h_ls );
/* 🔴 "NHẢY LOẠN XẠ" — anh Thắng 29/08/2026: *"vẫn bị tình trạng nhảy loạn xạ khi sửa công"*.
   Neo `id="suaday"` PHẢI nằm trên đúng `<td class="...dang-sua...">` (một Ô hẹp, đúng cột
   ngày) — KHÔNG phải trên `<tr>` (cả hàng dài 31 cột). Neo trên cả hàng thì trình duyệt chỉ
   cần cuộn DỌC là coi như "đã trong tầm nhìn" (một hàng dài luôn có mẩu hiện ra dù cuộn ngang
   ở đâu), nên khung `.cuon` không cuộn NGANG sang đúng cột ngày đang sửa — tiêu đề cột phía
   trên và hàng sửa phía dưới nói về hai ngày khác nhau, đúng cảm giác "loạn xạ". */
t( '🔴 neo nằm trên ĐÚNG Ô (td.dang-sua), không phải trên cả hàng (tr)',
	preg_match( '~<td class="[^"]*dang-sua[^"]*" id="suaday"~', $h_ls ) === 1
		&& strpos( $h_ls, '<tr id="suaday">' ) === false,
	$h_ls );
/* 🔴 BẤM SỬA THÌ ĐỪNG NHẢY LÊN SÁT ĐỈNH. Anh Thắng 27/08/2026: *"khi bấm sửa công nó cứ nhảy
   lên như này, chỉnh đứng yên cho anh"*.
   Đường bấm mang neo `#suaday` nên trình duyệt cuộn hàng sửa lên sát đỉnh — mà đỉnh thì có
   thanh đầu trang DÍNH đè lên, và cả hàng của người đang sửa cũng bị đẩy khuất.
   `scroll-margin-top` bảo trình duyệt chừa sẵn khoảng ấy. */
t( '🔴 hàng sửa chừa chỗ cho thanh đầu trang khi nhảy tới',
	strpos( $h_ls, 'tr.hang-sua,table.cc td.dang-sua{scroll-margin-top:' ) !== false, $h_ls );
/* 🔴 Nhánh CHẤM BÙ nay CŨNG neo về `#suaday` (đổi 29/08/2026, xem khối "ô TRỐNG trỏ sang khối
   Chấm công bù" ở trên) — trước đó nhánh bù còn neo nhầm về `#bucong` (id của khối "Sổ nhật ký
   giờ công" ở tận cuối trang), nên `td.dang-sua` cũng phải chừa chỗ giống hệt hàng sửa. */
t( 'và ô đang sửa cũng chừa chỗ y hệt (cả nhánh sửa lẫn nhánh bù cùng neo về #suaday)',
	preg_match( '~td\.dang-sua\{scroll-margin-top:\d+px\}~', $h_ls ) === 1, $h_ls );

/* 🔴 "CÓ ĐÂU EM" — anh Thắng 29/08/2026, bấm Bù giờ (hoặc Lưu giờ) xong thì hàng đang sửa biến
 * mất, y hệt như chưa bấm gì.
 *
 * `action="...#suaday"` (khối test ngay trên) chỉ giữ đúng neo cho LƯỢT POST — nhưng máy chủ trả
 * lời một lượt POST bằng CHUYỂN HƯỚNG (POST → REDIRECT → GET, xem lý do ở `phuc_vu_that()`), và
 * cái `url_hien()` dùng để dựng địa chỉ chuyển hướng ấy CHỈ chở đúng danh sách `THAM_SO` (cơ sở,
 * tháng, ô Tìm, …) — `gnd/gma/sgn/sgm` không nằm trong đó, nên bị RỚT MẤT ngay khi tạo địa chỉ
 * chuyển hướng. Trang tải lại sau đó KHÔNG còn `gnd/gma` trong địa chỉ → `o_dang_sua()` không
 * còn khớp được ô nào → không `<td id="suaday">` nào được vẽ ra → hàng sửa cũng biến mất theo
 * (nó chỉ hiện khi `$dang`/`sg_n===$gnd` khớp) — trình duyệt vẫn giữ `#suaday` cũ trên thanh địa
 * chỉ nhưng nó trỏ vào một id không còn tồn tại, nên không cuộn tới đâu cả. Bấm Lưu xong mà y hệt
 * như chưa bấm: "có đâu em".
 *
 * Vá bằng `url_hien_sua()`: chuyển hướng sau POST giữ riêng bốn khoá `gnd/gma/sgn/sgm` (đọc từ
 * `$_GET` — chúng luôn có mặt ở đó vì nằm ngay trong địa chỉ `action` mà `hang_sua()` đã nêu,
 * POST không mang chúng trong thân nhưng cũng không xoá được chúng khỏi URL của chính request),
 * rồi tự nối thêm `#suaday`. Kiểm bằng cách đọc thẳng `$GLOBALS['VHCP_CHUYEN']` — đích chuyển
 * hướng thật sự mà `wp_safe_redirect()` (bản giả) nhận được. */
$GLOBALS['VHCP_CHUYEN'] = '';
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Quản trị', 'Admin', 'LS_CS', 'LSAD' );
$_GET = array( 'man' => 'cham', 'ccs' => 'LS_CS', 'cth' => '2026-07',
	'sgn' => '2026-07-06', 'sgm' => 'LS1' );
$_POST = array( 'ky' => VHCC_Web::chu_ky( (string) $_COOKIE[ VHCC_Web::COOKIE ] ),
	'viec' => 'sua_gio', 'ccs' => 'LS_CS', 'ngay' => '2026-07-06', 'ma_nv' => 'LS1',
	'sg_vao' => '08:30', 'sg_ra' => '17:30', 'ly_do' => 'doi chieu camera' );
ob_start(); VHCC_Web::phuc_vu(); ob_get_clean();
$_GET = array(); $_POST = array(); $_COOKIE = array();
$tc_sua = (string) $GLOBALS['VHCP_CHUYEN'];
t( '🔴 lưu giờ xong, chuyển hướng vẫn chở theo sgn/sgm — không "có đâu em"',
	strpos( $tc_sua, 'sgn=2026-07-06' ) !== false && strpos( $tc_sua, 'sgm=LS1' ) !== false, $tc_sua );
t( 'và tự nối #suaday để trình duyệt cuộn lại đúng chỗ',
	substr( $tc_sua, -7 ) === '#suaday', $tc_sua );

$GLOBALS['VHCP_CHUYEN'] = '';
$_COOKIE[ VHCC_Web::COOKIE ] = VHCC_Auth::phat_token( 'Quản trị', 'Admin', 'LS_CS', 'LSAD' );
$_GET = array( 'man' => 'cham', 'ccs' => 'LS_CS', 'cth' => '2026-07',
	'gnd' => '2026-07-08', 'gma' => 'LS2' );
$_POST = array( 'ky' => VHCC_Web::chu_ky( (string) $_COOKIE[ VHCC_Web::COOKIE ] ),
	'viec' => 'bu', 'ccs' => 'LS_CS', 'ngay' => '2026-07-08', 'ma_nv' => 'LS2',
	'bu_vao' => '08:00', 'bu_ra' => '17:00', 'ly_do' => 'may hong sang do, co camera' );
ob_start(); VHCC_Web::phuc_vu(); ob_get_clean();
$_GET = array(); $_POST = array(); $_COOKIE = array();
$tc_bu = (string) $GLOBALS['VHCP_CHUYEN'];
t( '🔴 cùng lỗi ở nhánh CHẤM BÙ: chuyển hướng chở theo gnd/gma',
	strpos( $tc_bu, 'gnd=2026-07-08' ) !== false && strpos( $tc_bu, 'gma=LS2' ) !== false, $tc_bu );
t( 'và cũng tự nối #suaday', substr( $tc_bu, -7 ) === '#suaday', $tc_bu );

/* ---- Gạch ngăn hai phần trong chú thích ô ----
   Anh Thắng: *"tách ra 2 ô, bằng gạch ngang, cho dễ nhìn"*. `title` là văn bản THUẦN — không tô
   màu, không kẻ khung được — nên phần ngăn phải là một gạch DÀI THẬT thì mắt mới tách được hai
   khối chữ; mấy dấu gạch ngắn kiểu "— ca đêm —" chìm ngay vào đám chữ quanh nó. */
t( '🔴 chú thích ô có ca đêm được ngăn bằng gạch DÀI',
	strpos( $h_vp, '────────────────' ) !== false, $h_vp );
t( 'và gọi tên phần thứ hai là CA ĐÊM', strpos( $h_vp, '🌙 CA ĐÊM' ) !== false, $h_vp );
t( 'không còn dấu gạch ngắn cũ', strpos( $h_vp, '— ca đêm —' ) === false, $h_vp );

$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'cai_dat' ) . " WHERE khoa='VP_CONG_CFG'" );
vhcc_dung_bang();

/* ======================================================================================
 *  65. SỬA GIỜ CẢ CHÙM CƠ SỞ TRONG MỘT LƯỢT · và ca đêm thiếu giờ thì KHÔNG cộng công
 *
 *  Hai việc anh Thắng giao 27/08/2026, nối nhau trong một buổi:
 *
 *  (A) *"nếu cơ sở được ghép từ 2 cơ sở, thì khi sửa sẽ sửa luôn được cả 2 là 4 giờ vào ra"*.
 *      Lưới nay gộp VP + SETUP thành một hàng, nhưng dòng ca đêm nằm ở cơ sở PHỤ. Hàng sửa cũ
 *      chỉ dựng một cặp ô cho cơ sở ĐANG XEM, nên bấm sửa một ngày có ca đêm thì máy chủ đáp
 *      "chưa có dòng chấm công nào để sửa" — trong khi ô ấy đang hiện số.
 *
 *  (B) *"thiếu có thể do bấm nhầm, không được cộng vào nhé, trừ khi có thêm giờ ra"* — kèm ảnh
 *      ô ca đêm `05:51 → —` mà chú thích vẫn ghi "vẫn tính đủ".
 *      🔴 ĐÂY LÀ ĐẢO CHÍNH SÁCH. Bản trước cộng đủ một công đêm cho lượt bấm lẻ, lý do là
 *         "không cắt tiền vì máy lỗi". Anh Thắng chỉ ra chiều ngược lại: MỘT LẦN BẤM LẺ KHÔNG
 *         CHỨNG MINH ĐƯỢC CÓ CA ĐÊM. Ai làm thật thì bù nốt giờ kia — mất một dòng giải thích,
 *         không mất công.
 * ====================================================================================== */
vhcc_dung_bang();
$S_VP = 'SU_VP_HCM';
$S_SU = 'SU_SETUP_VP';
vhcc_bo_phan( $S_VP, 'Văn phòng' );
vhcc_bo_phan( $S_SU, 'Văn phòng' );
$u_su = array( 'role' => 'Admin' );
$r_su = VHCC_Luong::dat_ghep( $u_su, array( $S_SU => $S_VP ) );
t( 'dựng cảnh: ghép SETUP vào VP', ! empty( $r_su['ok'] ), $r_su );

/* ⚠️ PHẢI CÓ HỒ SƠ. `VHCC_Bu` từ chối bù/sửa cho một mã không có hồ sơ — cố ý, vì bù cho một
   mã gõ nhầm là dựng ra một người không có thật và cái công ấy đi thẳng vào bảng lương. Cảnh
   dựng thiếu hồ sơ thì mọi lượt gửi đều rớt ở cửa đó, và phép thử đo nhầm sang chuyện khác. */
foreach ( array( 'SU1' => $S_VP, 'SU9' => 'TUTU_BT' ) as $ma_su => $cs_su ) {
	VHCC_NhanSu::luu_ho_so( $u_su, array( 'ma_nv' => $ma_su, 'ho_ten' => 'Người ' . $ma_su,
		'cua_hang' => $cs_su, 'sdt' => '0900' ) );
}

/* Ca chính ở cơ sở CHÍNH, ca đêm ở cơ sở PHỤ với hậu tố TC — đúng hình dạng thật của bảng
   anh Thắng (tệp CSV `CS_SETUP_VP` anh gửi 27/08 dùng hậu tố `-TC`). */
vhcc_cham( $S_VP, '2026-07-06', 'SU1', '', '08:30:00', '17:00:00' );
/* ⚠️ Giờ ra ca đêm lưu ở dạng TRẢI PHẲNG (05:30 hôm sau = 29h30), đúng như cổng online ghi.
   Gieo `05:30` thẳng là dựng một dòng KHÔNG GIỐNG dòng thật, và mọi phép đo sau đó đo trên
   một hình dạng dữ liệu không tồn tại ngoài đời. */
vhcc_cham( $S_SU, '2026-07-06', 'SU1', 'TC', '21:30:00', null );
$wpdb->query( 'UPDATE ' . VHCC_DB::t( 'cham_cong' ) . ' SET gio_ra_giay='
	. ( VHCC_DB::giay( '05:30:00' ) + VHCC_DB::NGAY_GIAY )
	. " WHERE coso='" . $S_SU . "' AND ngay='2026-07-06' AND hau_to='TC'" );

/* ---- Lõi: liệt kê mọi dòng thật trong chùm ---- */
$o_su = VHCC_Bu::cac_o( VHCC_Luong::chum_cua( $S_VP ), '2026-07-06', 'SU1' );
teq( '🔴 tìm được ĐỦ HAI dòng trên cả chùm, không chỉ cơ sở đang xem', 2, count( $o_su ) );
$co_chinh = false;
$co_dem   = false;
foreach ( $o_su as $x_su ) {
	if ( $x_su['coso'] === $S_VP && '' === $x_su['hauTo'] && '08:30' === $x_su['vao'] ) { $co_chinh = true; }
	if ( $x_su['coso'] === $S_SU && 'TC' === $x_su['hauTo'] && '21:30' === $x_su['vao'] ) { $co_dem = true; }
}
t( 'dòng ca chính đúng cơ sở, đúng giờ', $co_chinh, $o_su );
t( '🔴 dòng ca đêm ở CƠ SỞ PHỤ cũng có mặt, kèm hậu tố của nó', $co_dem, $o_su );
/* ⚠️ Mã trả về phải là mã ĐẦY ĐỦ (`SU1-TC`), vì đó là thứ `VHCC_Bu::sua()` dùng để tìm hàng.
   Trả mã gốc thì lượt sửa ca đêm rơi vào hàng ca chính — sửa nhầm ca là sửa nhầm tiền. */
$ma_dem_su = '';
foreach ( $o_su as $x_su ) {
	if ( 'TC' === $x_su['hauTo'] ) { $ma_dem_su = $x_su['ma']; }
}
