   chấm nhầm chỗ, và trải phẳng bừa cho nó là bịa ra một ca 20 tiếng. */
$h_chinh = vhcc_web_sua( array( 'man' => 'vp', 'ccs' => $S_VP, 'cth' => '2026-07' ), array(
	'viec'   => 'sua_gio',
	'ccs'    => $S_VP,
	'ngay'   => '2026-07-06',
	'ma_nv'  => 'SU1',
	'sg_vao' => array( $S_VP . '~' => '21:00' ),
	'sg_ra'  => array( $S_VP . '~' => '05:00' ),
	'ly_do'  => 'thử gõ giờ ca đêm vào hàng ca ngày',
) );
t( '🔴 hàng CHÍNH thì vẫn chối giờ ra sớm hơn giờ vào',
	strpos( $h_chinh, 'Giờ ra phải muộn hơn giờ vào' ) !== false, $h_chinh );

/* ---- (B) Ca đêm thiếu một đầu giờ: KHÔNG cộng công, và bày thật rõ trên lưới ---- */
vhcc_dung_bang();
/* ⚠️ `vhcc_dung_bang()` dựng lại kho, nên thẻ phiên cũ hết hiệu lực — phát lại, không thì mọi
   lượt sau rơi về màn nhập PIN và phép thử đo một trang trắng. */
$tok_su = VHCC_Auth::phat_token( 'Người Sửa', 'Admin', '', 'SUADM' );
$D_CS = 'SU_DEM_CS';
vhcc_bo_phan( $D_CS, 'Văn phòng' );
/* Đúng ô trong ảnh anh Thắng gửi: hàng 2 chỉ có MỘT giờ, và nó là giờ lúc 05:51 sáng. */
vhcc_cham( $D_CS, '2026-07-08', 'DEM1', 'CD', '05:51:00', null );
/* 🔴 CHIỀU NGƯỢC LẠI: chỉ có giờ RA, không có giờ vào — quên bấm lúc VÀO.
   Người về lúc 5 giờ sáng bấm một cái rồi đi ngủ. Bản trước chỉ bắt chiều "có vào, không ra",
   nên dòng này rơi thẳng khỏi bảng: không công, không dấu vết, không chỗ nào để bấm bù. Đã phá
   thử để thấy — thu `$thieu_ra` về một chiều mà bộ thử vẫn xanh. */
vhcc_cham( $D_CS, '2026-07-12', 'DEM3', 'CD', null, '05:00:00' );

/* Một người làm đêm ĐỦ CẶP để so — không có người này thì "không bao giờ cộng công đêm" cũng
   xanh, mà thế là cắt trắng ca đêm của cả công ty. */
vhcc_cham_dem( $D_CS, '2026-07-10', 'DEM2', '21:30:00', '05:30:00' );
$h_dem = vhcc_web_sua( array( 'man' => 'vp', 'ccs' => $D_CS, 'cth' => '2026-07' ) );
$o_dem1 = vp_o_dau_tien( $h_dem, 'Người DEM1' );
t( 'dựng cảnh: tìm được ô ca đêm thiếu giờ', '' !== $o_dem1, substr( $h_dem, 0, 300 ) );
t( '🔴 ô ấy ĐỎ', strpos( $o_dem1, 'class="oc hong' ) !== false, $o_dem1 );
/* `🌙` trơn nghĩa là "đêm đó có làm" và người đọc hiểu công nằm ở ô ngày mai. Để nó ở đây là
   hứa một công không tồn tại — phải là `🌙0`. */
t( '🔴 hiện 🌙0, không phải 🌙 trơn (đêm ấy KHÔNG ra công)',
	strpos( $o_dem1, '🌙0' ) !== false, $o_dem1 );
t( 'chú thích nói rõ KHÔNG tính công đêm',
	strpos( $o_dem1, 'KHÔNG tính công đêm' ) !== false, $o_dem1 );
t( 'và chỉ đường đi bù', strpos( $o_dem1, 'Bù nốt giờ còn thiếu' ) !== false, $o_dem1 );
/* ⚠️ Câu "vẫn tính đủ" của bản trước phải đi hẳn: engine nay KHÔNG cộng, mà câu ấy còn nguyên
   thì màn hình đang nói dối người kiểm lương. */
t( '🔴 KHÔNG còn câu "vẫn tính đủ" ở đâu trên màn',
	strpos( $h_dem, 'vẫn tính đủ' ) === false, $h_dem );
/* Và dòng CHỈ CÓ GIỜ RA cũng phải còn, cũng đỏ — cùng một chuyện, chỉ khác đầu giờ nào thiếu. */
$o_dem3 = vp_o_dau_tien( $h_dem, 'Người DEM3' );
t( '🔴 ca đêm chỉ có giờ RA: dòng VẪN CÒN trong bảng', '' !== $o_dem3, substr( $h_dem, 0, 300 ) );
t( '🔴 và ô ấy cũng ĐỎ', strpos( $o_dem3, 'class="oc hong' ) !== false, $o_dem3 );
t( 'chú thích gọi đúng tên chuyện: quên bấm lúc vào',
	strpos( $o_dem3, 'quên bấm lúc vào' ) !== false, $o_dem3 );

/* Người làm đêm ĐỦ CẶP vẫn được công như thường — chặn ở trên không được đụng tới họ. */
$o_dem2 = vp_o_dau_tien( $h_dem, 'Người DEM2' );
t( 'ca đêm đủ cặp: KHÔNG đỏ vì chuyện thiếu giờ',
	'' !== $o_dem2 && strpos( $o_dem2, '🌙0' ) === false, $o_dem2 );

$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'cai_dat' ) . " WHERE khoa='" . VHCC_Luong::GHEP_O . "'" );
vhcc_dung_bang();

/* ======================================================================================
 *  66. CHIA ĐẦU VIỆC THEO VAI · và vai Kỹ thuật setup máy mà không cần lên Admin
 *
 *  Anh Thắng 27/08/2026, khi chuyển `/cham-cong/` thành trang dùng chung, kể ra ba bộ phận đi
 *  chung một đường: *"Nhân viên thì vào chấm công và xem công mình · Kế toán thì vào check công
 *  tháng · Kỹ thuật thì vào setup máy chấm công online"*. Rồi chốt một câu:
 *  *"Chia bộ phận ai xem được từng đầu việc của mình"*.
 *
 *  🔴 CHỖ NÓ VỠ: quyền `he_thong` gộp MÁY CHẤM CÔNG với XOÁ SẠCH SỔ HỒ SƠ, ĐỔI MÃ NV, XEM PIN
 *     NGƯỜI KHÁC. Muốn cho người dựng máy vào được thì phải nâng họ lên Admin — tức trao luôn
 *     mấy việc kia. Hai chuyện chẳng liên quan gì nhau bị buộc vào một chìa khoá.
 *
 *  Cách chữa: tách `may` thành đầu việc riêng (mặc định VẪN Admin — không nới của ai), rồi
 *  thêm bảng NGOẠI LỆ để khai đúng chỗ lệch, có tên, có chỗ soát lại.
 * ====================================================================================== */
vhcc_dung_bang();
delete_option( VHCC_Vai::O_NGOAI_LE );
delete_option( VHCC_Vai::O_THEM );
VHCC_Vai::quen_nho();
VHCC_Vai::quen_nho_nl();

/* ---- Bảng tên đầu việc phải phủ ĐỦ bảng quyền ---- */
/* Thiếu một dòng thì đầu việc ấy vẫn gác thật nhưng KHÔNG hiện trên bảng chia — một quyền tồn
   tại mà không ai chia được, và cũng không ai biết là nó có. */
$dv_thieu = array();
foreach ( array_keys( VHCC_Vai::QUYEN ) as $q_x ) {
	if ( ! isset( VHCC_Vai::VIEC_TEN[ $q_x ] ) ) { $dv_thieu[] = $q_x; }
}
teq( '🔴 mọi đầu việc đều có tên đọc được', array(), $dv_thieu );
$dv_thua = array();
foreach ( array_keys( VHCC_Vai::VIEC_TEN ) as $q_x ) {
	if ( ! isset( VHCC_Vai::QUYEN[ $q_x ] ) ) { $dv_thua[] = $q_x; }
}
teq( 'và không có tên nào trỏ vào một đầu việc không tồn tại', array(), $dv_thua );

/* ---- `may` đã tách khỏi `he_thong`, nhưng mặc định KHÔNG nới của ai ---- */
$dv_ad  = array( 'role' => 'Admin', 'ma_nv' => 'DVAD' );
$dv_kt  = array( 'role' => 'Kế toán', 'ma_nv' => 'DVKT' );
$dv_nv  = array( 'role' => 'Nhân viên', 'ma_nv' => 'DVNV' );
$dv_cht_dv = array( 'role' => 'Cửa hàng trưởng', 'ma_nv' => 'DVCH' );
t( 'Admin vẫn làm được việc máy', VHCC_Vai::duoc( $dv_ad, 'may' ) );
t( '🔴 Kế toán vẫn KHÔNG — tách quyền không phải là nới quyền', ! VHCC_Vai::duoc( $dv_kt, 'may' ) );
t( 'và Nhân viên càng không', ! VHCC_Vai::duoc( $dv_nv, 'may' ) );

/* ---- Vai Kỹ thuật: gốc Nhân viên + MỞ đúng một đầu việc ---- */
VHCC_Vai::dat_them( $dv_ad, 'Kỹ thuật', VHCC_Vai::NV );
VHCC_Vai::quen_nho();
$dv_ky = array( 'role' => 'Kỹ thuật', 'ma_nv' => 'DVKY' );
teq( 'vai Kỹ thuật kế thừa bậc Nhân viên', 1, VHCC_Vai::bac( $dv_ky ) );
t( 'chưa khai gì thì Kỹ thuật KHÔNG làm được việc máy', ! VHCC_Vai::duoc( $dv_ky, 'may' ) );

$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'vai:Kỹ thuật', 'may', 'mo' );
t( 'khai được dòng ngoại lệ', ! empty( $r_dv['ok'] ), $r_dv );
t( '🔴 Kỹ thuật NAY làm được việc máy', VHCC_Vai::duoc( $dv_ky, 'may' ) );
/* 🔴 ĐÂY LÀ TOÀN BỘ LÝ DO TÁCH QUYỀN. Mở việc máy mà kéo theo xoá sổ hồ sơ thì đã chẳng cần
   tách — cứ nâng họ lên Admin cho nhanh. */
t( '🔴 nhưng KHÔNG kéo theo cài đặt hệ thống', ! VHCC_Vai::duoc( $dv_ky, 'he_thong' ) );
t( 'không kéo theo xem PIN người khác', ! VHCC_Vai::duoc( $dv_ky, 'xem_pin' ) );
t( 'không kéo theo xoá hồ sơ', ! VHCC_Vai::duoc( $dv_ky, 'xoa_ho_so' ) );
t( 'không kéo theo bảng lương', ! VHCC_Vai::duoc( $dv_ky, 'luong' ) );
t( 'và vẫn tự chấm công được như mọi người', VHCC_Vai::duoc( $dv_ky, 'cham_online' ) );

/* ⚠️ Ngoại lệ ăn theo TÊN VAI, không theo bậc. Hai vai cùng gốc Nhân viên là hai vai khác nhau
   — anh Thắng tạo vai riêng chính là để phân biệt. Ăn theo bậc thì mở cho Kỹ thuật là mở cho
   mọi Nhân viên trong công ty. */
VHCC_Vai::dat_them( $dv_ad, 'Tạp vụ', VHCC_Vai::NV );
VHCC_Vai::quen_nho();
t( '🔴 vai khác cùng bậc KHÔNG ăn theo',
	! VHCC_Vai::duoc( array( 'role' => 'Tạp vụ', 'ma_nv' => 'DVTV' ), 'may' ) );
t( 'và Nhân viên trơn cũng không', ! VHCC_Vai::duoc( $dv_nv, 'may' ) );
/* Gõ tên vai lệch dấu/hoa thường vẫn phải nhận ra — sổ sách người ta gõ lúc có dấu lúc không. */
t( 'tên vai lệch dấu vẫn khớp đúng dòng ngoại lệ',
	VHCC_Vai::duoc( array( 'role' => 'ky thuat', 'ma_nv' => 'DVKY2' ), 'may' ) );

/* ---- KHOÁ: chiều ngược lại, thu một đầu việc của một vai ---- */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'vai:Kế toán', 'luong', 'khoa' );
t( 'khoá được một đầu việc của cả vai', ! empty( $r_dv['ok'] ), $r_dv );
t( '🔴 Kế toán bị khoá thì KHÔNG xem được bảng lương nữa', ! VHCC_Vai::duoc( $dv_kt, 'luong' ) );
t( 'nhưng các việc khác của họ vẫn nguyên', VHCC_Vai::duoc( $dv_kt, 'ho_so' ) );

/* ---- NGƯỜI ĐÈ VAI ---- */
/* Dòng khai riêng cho một Mã NV là dòng người ta viết SAU khi đã nhìn thấy dòng của cả vai —
   nên nó phải thắng. Ngược lại thì gỡ quyền của đúng một người trong nhóm là không làm được. */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'nv:DVKT', 'luong', 'mo' );
t( 'khai riêng cho một Mã NV', ! empty( $r_dv['ok'] ), $r_dv );
t( '🔴 dòng theo NGƯỜI thắng dòng theo VAI', VHCC_Vai::duoc( $dv_kt, 'luong' ) );
t( 'người khác cùng vai vẫn theo dòng của vai',
	! VHCC_Vai::duoc( array( 'role' => 'Kế toán', 'ma_nv' => 'DVKT9' ), 'luong' ) );
/* Mã NV so KHÔNG phân biệt hoa thường — hồ sơ gõ tay thì lúc hoa lúc thường. */
t( 'Mã NV lệch hoa thường vẫn khớp',
	VHCC_Vai::duoc( array( 'role' => 'Kế toán', 'ma_nv' => 'dvkt' ), 'luong' ) );

/* ---- Gỡ dòng: về lại theo thang ---- */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'nv:DVKT', 'luong', '' );
t( 'gỡ được dòng', ! empty( $r_dv['ok'] ), $r_dv );
t( 'gỡ xong thì rơi lại vào dòng của vai (đang khoá)', ! VHCC_Vai::duoc( $dv_kt, 'luong' ) );
VHCC_Vai::dat_ngoai_le( $dv_ad, 'vai:Kế toán', 'luong', '' );
t( '🔴 gỡ nốt dòng của vai thì về đúng thang, không sót vết', VHCC_Vai::duoc( $dv_kt, 'luong' ) );

/* ---- Dữ liệu rác trong kho không được biến thành quyền ---- */
update_option( VHCC_Vai::O_NGOAI_LE, array(
	'vai:Kỹ thuật' => array( 'may' => 'mo', 'quyen_khong_co' => 'mo', 'luong' => 'bay_gio' ),
	'lung tung'    => array( 'he_thong' => 'mo' ),
	'nv:'          => array( 'he_thong' => 'mo' ),
) );
VHCC_Vai::quen_nho_nl();
t( 'dòng đúng vẫn ăn', VHCC_Vai::duoc( $dv_ky, 'may' ) );
/* 🔴 Quyền KHÔNG có trong bảng QUYEN thì bỏ hẳn khỏi kho — giữ lại là để một dòng gõ nhầm nằm
   mãi trong đó, và ngày có người khai đúng tên ấy thì nó bật lên mà chẳng ai nhớ đã khai. */
$nl_sach = VHCC_Vai::ngoai_le();
t( 'quyền lạ bị bỏ', ! isset( $nl_sach['vai:ky thuat']['quyen_khong_co'] ), $nl_sach );
t( 'giá trị lạ bị bỏ', ! isset( $nl_sach['vai:ky thuat']['luong'] ), $nl_sach );
/* ⚠️ ĐO BẰNG DANH SÁCH KHOÁ, không bằng `! isset( $nl['lung tung'] )`. Một đích rác được "nhận"
   thì nó vào kho dưới một khoá ĐÃ CHUẨN HOÁ (`nv:LUNG TUNG`), nên khoá gốc vẫn không tồn tại và
   phép thử kia xanh trơn. Đã phá thử để thấy. */
teq( '🔴 kho sạch chỉ còn ĐÚNG dòng hợp lệ — đích rác không lọt dưới bất kỳ tên nào',
	array( 'vai:ky thuat' ), array_keys( $nl_sach ) );
teq( 'và dòng ấy chỉ giữ đúng quyền hợp lệ', array( 'may' ), array_keys( $nl_sach['vai:ky thuat'] ) );
t( 'và Kế toán KHÔNG vì mấy dòng rác ấy mà có he_thong', ! VHCC_Vai::duoc( $dv_kt, 'he_thong' ) );

/* ---- Chốt an toàn ---- */
delete_option( VHCC_Vai::O_NGOAI_LE );
VHCC_Vai::quen_nho_nl();
/* 🔴 KHÔNG MỞ ĐƯỢC ĐẦU VIỆC CAO HƠN BẬC MÌNH. Thiếu chốt này thì một Kế toán mở `he_thong` cho
   một vai, gán vai đó cho mình, và thành Admin trong ba bước không bước nào bị chối. */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_kt, 'vai:Kỹ thuật', 'he_thong', 'mo' );
t( '🔴 Kế toán KHÔNG mở được đầu việc bậc Admin', empty( $r_dv['ok'] ), $r_dv );
t( 'và kho không có dòng nào được ghi', ! VHCC_Vai::duoc( $dv_ky, 'he_thong' ) );
/* ⚠️ Chốt bậc áp cho CẢ chiều KHOÁ. Chỉ chặn chiều mở thì một người bậc thấp khoá được
   `he_thong` của vai Admin — nhốt cả nhà bằng một quyền mà mình không có. */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_kt, 'vai:Admin', 'he_thong', 'khoa' );
t( '🔴 Kế toán cũng KHÔNG khoá được đầu việc bậc Admin', empty( $r_dv['ok'] ), $r_dv );
t( 'Admin vẫn vào được cài đặt hệ thống', VHCC_Vai::duoc( $dv_ad, 'he_thong' ) );
/* 🔴 KHÔNG KHOÁ ĐƯỢC `ho_so` — đó là chìa để mở lại chính bảng này. Khoá nó cho Admin rồi khoá
   nốt cho Kế toán là bảng tự khoá chính nó, không đường nào gỡ trừ vào thẳng cơ sở dữ liệu. */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'vai:Admin', 'ho_so', 'khoa' );
t( '🔴 không khoá được đầu việc Hồ sơ nhân sự', empty( $r_dv['ok'] ), $r_dv );
t( 'và nói rõ vì sao', strpos( isset( $r_dv['error'] ) ? $r_dv['error'] : '', 'chìa để mở lại' ) !== false, $r_dv );
t( 'Admin vẫn còn ho_so', VHCC_Vai::duoc( $dv_ad, 'ho_so' ) );
/* Mở `ho_so` thì vẫn được — chỉ chiều khoá mới là cái bẫy. */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'vai:Kỹ thuật', 'ho_so', 'mo' );
t( 'nhưng MỞ ho_so thì được', ! empty( $r_dv['ok'] ), $r_dv );
VHCC_Vai::dat_ngoai_le( $dv_ad, 'vai:Kỹ thuật', 'ho_so', '' );

/* 🔴 KHÔNG TỰ KHAI CHO CHÍNH MÌNH. Chốt bậc đã chặn leo lên cao hơn, nhưng vẫn còn đường tự
   khoá rồi tự mở lại để xoá một dòng khoá người khác đặt cho mình. Bắt đi qua người thứ hai. */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'nv:DVAD', 'may', 'mo' );
t( '🔴 không tự khai cho Mã NV của chính mình', empty( $r_dv['ok'] ), $r_dv );
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'vai:Admin', 'may', 'mo' );
t( '🔴 cũng không tự khai cho chính vai mình', empty( $r_dv['ok'] ), $r_dv );
/* Người khác thì khai bình thường — chốt trên không được chặn nhầm cả việc điều phối. */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'nv:DVKT', 'may', 'mo' );
t( 'khai cho người khác vẫn được', ! empty( $r_dv['ok'] ), $r_dv );
VHCC_Vai::dat_ngoai_le( $dv_ad, 'nv:DVKT', 'may', '' );

/* Nhân viên thì không tới được cửa này.
   ⚠️ Thử bằng một đầu việc BẬC 1 (`cham_online`). Thử bằng `cham_bu` (bậc 2) thì chốt BẬC bắt
      trước, và chốt "phải có ho_so mới khai được" gỡ đi vẫn xanh — tức cửa mở toang mà bộ thử
      không thấy. Đã phá thử để thấy. */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_nv, 'vai:Kỹ thuật', 'cham_online', 'khoa' );
t( '🔴 Nhân viên không khai được dòng nào, kể cả đầu việc bậc 1', empty( $r_dv['ok'] ), $r_dv );
t( 'và nói rõ cần vai nào', strpos( isset( $r_dv['error'] ) ? $r_dv['error'] : '', 'Kế toán' ) !== false, $r_dv );
t( 'Kỹ thuật vẫn tự chấm công được — không dòng nào lọt vào kho',
	VHCC_Vai::duoc( $dv_ky, 'cham_online' ) );
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_cht_dv, 'vai:Kỹ thuật', 'cham_online', 'khoa' );
t( '🔴 Cửa hàng trưởng cũng không', empty( $r_dv['ok'] ), $r_dv );

/* Trần số dòng — quá con số này thì cái sai không còn là thiếu ngoại lệ nữa. */
$nl_day = array();
for ( $i_dv = 0; $i_dv < VHCC_Vai::NGOAI_LE_TOI_DA; $i_dv++ ) {
	$nl_day[ 'nv:DAY' . $i_dv ] = array( 'cham_bu' => 'mo' );
}
update_option( VHCC_Vai::O_NGOAI_LE, $nl_day );
VHCC_Vai::quen_nho_nl();
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'nv:DVKT', 'cham_bu', 'mo' );
t( '🔴 tới trần thì chối, không ghi thêm', empty( $r_dv['ok'] ), $r_dv );
t( 'và nói ra con số trần', strpos( isset( $r_dv['error'] ) ? $r_dv['error'] : '',
	(string) VHCC_Vai::NGOAI_LE_TOI_DA ) !== false, $r_dv );
/* ⚠️ SỬA một dòng ĐÃ CÓ thì vẫn phải được, kể cả khi đang đầy — không thì tới trần là không gỡ
   nổi cái gì nữa, mà gỡ mới đúng là việc người ta cần làm lúc ấy. */
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'nv:DAY0', 'cham_bu', 'khoa' );
t( 'nhưng sửa dòng đã có thì vẫn được dù đang đầy', ! empty( $r_dv['ok'] ), $r_dv );
$r_dv = VHCC_Vai::dat_ngoai_le( $dv_ad, 'nv:DAY0', 'cham_bu', '' );
t( 'và gỡ dòng thì luôn được', ! empty( $r_dv['ok'] ), $r_dv );

/* ---- Màn khai trên trang /nhan-su/ ---- */
delete_option( VHCC_Vai::O_NGOAI_LE );
VHCC_Vai::quen_nho_nl();
VHCC_Vai::dat_ngoai_le( array( 'role' => 'Admin', 'ma_nv' => 'ZZAD' ), 'vai:Kỹ thuật', 'may', 'mo' );
$h_dv = vhcc_ns( 'Admin' );
t( 'màn Quản lý nhân sự có khối Chia đầu việc', strpos( $h_dv, 'Chia đầu việc' ) !== false, $h_dv );
t( 'khối ấy kể ra dòng đang có', strpos( $h_dv, 'Máy chấm công &amp; firmware' ) !== false, $h_dv );
t( 'và nói rõ nó cho vai nào', strpos( $h_dv, 'Kỹ thuật' ) !== false, $h_dv );
t( 'có ô chọn đầu việc', strpos( $h_dv, 'name="dv_quyen"' ) !== false, $h_dv );
t( 'có ô gõ riêng Mã NV', strpos( $h_dv, 'name="dv_ma"' ) !== false, $h_dv );
t( 'và có nút Gỡ từng dòng', strpos( $h_dv, 'value="dau_viec"' ) !== false, $h_dv );

/* 🔴 Ô CHỌN CẮT Ở BẬC NGƯỜI ĐANG KHAI. Vẽ ra rồi chối là mời người ta bấm vào một việc không
   làm được — mà lõi vẫn chặn ở tầng dưới, nên đây chỉ là chuyện không mời gọi. */
$h_dv_kt = vhcc_ns( 'Kế toán' );
t( 'Kế toán KHÔNG thấy dòng "Cài đặt hệ thống" trong ô chọn',
	strpos( $h_dv_kt, '>Cài đặt hệ thống, nguồn người dùng —' ) === false, $h_dv_kt );
t( 'nhưng vẫn thấy dòng của bậc mình', strpos( $h_dv_kt, 'Lịch nghỉ lễ' ) !== false, $h_dv_kt );
t( 'Admin thì thấy đủ', strpos( $h_dv, 'Cài đặt hệ thống, nguồn người dùng' ) !== false, $h_dv );

/* Gửi thật một lượt khai qua màn hình — lõi chạy đúng thì màn hình mới có nghĩa. */
$h_dv2 = vhcc_ns( 'Admin', array(), array( 'viec' => 'dau_viec', 'dv_dich' => 'vai:Tạp vụ',
	'dv_quyen' => 'cham_bu', 'dv_dat' => 'mo' ) );
t( 'khai qua màn hình: báo xong', strpos( $h_dv2, 'Đã MỞ đầu việc' ) !== false, $h_dv2 );
t( '🔴 và có hiệu lực thật ở lõi',
	VHCC_Vai::duoc( array( 'role' => 'Tạp vụ', 'ma_nv' => 'DVTV2' ), 'cham_bu' ) );
/* Ô Mã NV có gõ thì nó THẮNG ô chọn vai — người ta gõ mã vào đó là đã có ý riêng cho một người,
   im lặng khai cho cả vai là làm ngược hẳn ý họ. */
$h_dv3 = vhcc_ns( 'Admin', array(), array( 'viec' => 'dau_viec', 'dv_dich' => 'vai:Tạp vụ',
	'dv_ma' => 'DVRIENG', 'dv_quyen' => 'bao_loi', 'dv_dat' => 'mo' ) );
t( 'gõ Mã NV thì khai cho ĐÚNG người ấy', strpos( $h_dv3, 'Mã NV DVRIENG' ) !== false, $h_dv3 );
t( 'và cả vai KHÔNG bị khai lây',
	! VHCC_Vai::duoc( array( 'role' => 'Tạp vụ', 'ma_nv' => 'DVTV3' ), 'bao_loi' ) );

/* 🔴 MÀN QUẢN TRỊ KHÔNG CÓ MỘT DÒNG SCRIPT NÀO — luật của cả hệ. */
t( 'khối mới không kéo theo script nào', stripos( $h_dv, '<script' ) === false );
t( 'và không có thuộc tính onXxx=', preg_match( '/\son[a-z]+\s*=\s*["\']/i', $h_dv ) === 0 );

/* ---- Kỹ thuật vào được ĐÚNG tab Máy, không thêm gì ---- */
delete_option( VHCC_Vai::O_NGOAI_LE );
VHCC_Vai::quen_nho_nl();
VHCC_Vai::dat_ngoai_le( array( 'role' => 'Admin', 'ma_nv' => 'ZZAD' ), 'vai:Kỹ thuật', 'may', 'mo' );
function vhcc_web_vai( $vai, $ma, $get = array() ) {
	$_GET = $get; $_POST = array();
	$_COOKIE = array( VHCC_Web::COOKIE => VHCC_Auth::phat_token( 'Người ' . $ma, $vai, '', $ma ) );
	ob_start(); VHCC_Web::phuc_vu(); $h = ob_get_clean();
	$_GET = array(); $_COOKIE = array();
	return $h;
}
$h_ky = vhcc_web_vai( 'Kỹ thuật', 'KYT1', array( 'man' => 'may' ) );
/* 🔴 GỌI ĐÚNG TÊN VAI NGƯỜI TA ĐÃ KHAI. Đầu trang ghi "Nhân viên" cho người mang vai "Kỹ thuật"
   là hệ đang nói một đằng, hồ sơ ghi một nẻo — và câu bị chối cũng sẽ nói sai theo. Người đọc
   không nối được hai thứ ấy, rồi đi hỏi vì sao hệ đổi vai của mình. */
t( '🔴 đầu trang gọi đúng tên vai tự tạo, không phải tên vai gốc',
	strpos( $h_ky, 'Người KYT1 · Kỹ thuật' ) !== false, substr( $h_ky, 0, 900 ) );
teq( 'nhưng BẬC vẫn là bậc của vai gốc', 1, VHCC_Vai::bac( array( 'role' => 'Kỹ thuật' ) ) );
teq( 'vai gốc thì vẫn gọi tên gốc', 'Kế toán', VHCC_Vai::ten( array( 'role' => 'Kế toán' ) ) );
/* ⚠️ Soi chuỗi ĐÃ ESCAPE. Tên tab in ra là `Máy &amp; Firmware` — soi `Máy & Firmware` là phép
   thử đỏ vì dấu `&`, chẳng liên quan gì tới quyền. */
t( '🔴 Kỹ thuật vào được tab Máy & Firmware', strpos( $h_ky, 'Máy &amp; Firmware' ) !== false, $h_ky );
t( 'và thấy được ruột của nó', strpos( $h_ky, 'Cổng nhận từ máy' ) !== false
	|| strpos( $h_ky, 'Firmware' ) !== false, substr( $h_ky, 0, 400 ) );
/* 🔴 VÀ BẤM ĐƯỢC NÚT, không chỉ NHÌN được màn. Cửa POST gác riêng một lần nữa (nút không vẽ
   chỉ là không mời; POST thì ai gửi cũng tới) — nếu cửa ấy vẫn hỏi `he_thong` thì Kỹ thuật xem
   được mọi thứ mà bấm gì cũng bị đá ra, tức là mở cho họ một màn vô dụng. Đã phá thử để thấy:
   trả cửa POST về `he_thong` mà bộ thử vẫn xanh. */
$b_ky = VHCC_WebMay::viec( 'may_gan', array( 'role' => 'Kỹ thuật', 'ma_nv' => 'KYT1' ) );
t( '🔴 Kỹ thuật BẤM được nút ở màn Máy, không chỉ nhìn',
	! ( isset( $b_ky[0]['loi'] ) && strpos( $b_ky[0]['loi'], 'cần đầu việc' ) !== false ), $b_ky );
$b_tv = VHCC_WebMay::viec( 'may_gan', array( 'role' => 'Tạp vụ', 'ma_nv' => 'TVU1' ) );
t( 'vai không được khai thì cửa POST vẫn chối',
	isset( $b_tv[0]['loi'] ) && strpos( $b_tv[0]['loi'], 'cần đầu việc' ) !== false, $b_tv );
/* Câu chối phải chỉ đường: bảo người ta đi xin ở đâu, chứ không chỉ nói "cần bậc Admin" — nay
   không cần lên Admin nữa, mà câu cũ vẫn bảo thế thì người ta đi xin nhầm thứ. */
t( 'và chỉ đúng chỗ đi khai',
	strpos( $b_tv[0]['loi'], 'Chia đầu việc' ) !== false, $b_tv );

/* Người cùng bậc mà KHÔNG có dòng ngoại lệ thì vẫn bị chối — không thì cái mở ra là mở cho cả
   công ty chứ không phải cho một vai. */
$h_tv = vhcc_web_vai( 'Tạp vụ', 'TVU1', array( 'man' => 'may' ) );
t( '🔴 vai khác cùng bậc KHÔNG vào được tab Máy',
	strpos( $h_tv, 'Cổng nhận từ máy' ) === false, substr( $h_tv, 0, 400 ) );

delete_option( VHCC_Vai::O_NGOAI_LE );
delete_option( VHCC_Vai::O_THEM );
VHCC_Vai::quen_nho();
VHCC_Vai::quen_nho_nl();
vhcc_dung_bang();

/* ======================================================================================
 *  67. PHÂN LỊCH LÀM RA WEB · và tên đầy đủ cho mã cơ sở
 *
 *  Anh Thắng 27/08/2026, khi chuyển `/cham-cong/` thành trang dùng chung: *"mọi người truy cập
 *  vào link này"*. Phân lịch là màn wp-admin CUỐI CÙNG còn sót — mà nó lại thuộc về người ít có
 *  tài khoản WordPress nhất: **cửa hàng trưởng**. Mô hình năm bậc giao cho họ đúng bốn việc,
 *  trong đó có *"lên lịch làm cho cửa hàng"*; để màn ấy sau `manage_options` là giao một việc
 *  rồi khoá mất cửa vào.
 *
 *  🔴 HAI MẶT CỦA CÙNG MỘT MÀN. Người xếp lịch và người BỊ xếp lịch nhìn cùng một thứ theo hai
 *     hướng ngược nhau. Nhân viên vào tab này mà thấy "không đủ quyền" là câu trả lời vô ích:
 *     họ không định xếp lịch cho ai, họ hỏi "mai tôi làm ca nào".
 * ====================================================================================== */
vhcc_dung_bang();
$L_CS = 'LI_TUTU_BT';
$L_C2 = 'LI_KHAC';
vhcc_bo_phan( $L_CS, 'Khu vui chơi' );
vhcc_bo_phan( $L_C2, 'Khu vui chơi' );
$l_ad  = array( 'role' => 'Admin', 'name' => 'Anh Admin', 'ma_nv' => 'LADM' );

/* ---- Tên đầy đủ của mã cơ sở ---- */
/* Mã là thứ MÁY đọc và là KHOÁ của mọi bảng — nó không đổi. Tên chỉ là lớp hiện ra. */
teq( 'chưa khai thì nhãn chính là MÃ', $L_CS, VHCC_NhanSu::ten_coso( $L_CS ) );
$r_tc = VHCC_NhanSu::dat_ten_coso( $l_ad, array( $L_CS => 'Tutu Bình Tân' ) );
t( 'khai được tên', ! empty( $r_tc['ok'] ), $r_tc );
VHCC_NhanSu::quen_ten_coso();
/* 🔴 GIỮ CẢ MÃ, đừng thay hẳn bằng tên. Người đối chiếu với tệp .csv của máy, với bảng lương cũ,
   với cái nhãn dán trên máy chấm công — họ tra bằng MÃ. Thay hẳn là bắt họ dịch ngược. */
teq( '🔴 nhãn là MÃ — TÊN, không phải chỉ tên', $L_CS . ' — Tutu Bình Tân',
	VHCC_NhanSu::ten_coso( $L_CS ) );
teq( 'cơ sở chưa khai vẫn ra mã trơn', $L_C2, VHCC_NhanSu::ten_coso( $L_C2 ) );
/* Tên rỗng = GỠ dòng, không phải ghi một tên rỗng (nhãn sẽ thành "MÃ — "). */
VHCC_NhanSu::dat_ten_coso( $l_ad, array( $L_CS => '' ) );
VHCC_NhanSu::quen_ten_coso();
teq( 'để trống thì gỡ tên, nhãn về lại mã trơn', $L_CS, VHCC_NhanSu::ten_coso( $L_CS ) );
/* 🔴 GỠ HẲN KHỎI KHO, không để lại một dòng rỗng. Soi mỗi cái nhãn thì không thấy khác biệt —
   `ten_coso_bang()` cũng lọc dòng rỗng, nên hai lớp lọc che nhau và bỏ lớp trong vẫn xanh. Đã
   phá thử để thấy. Dòng rỗng nằm lại là rác tích dần, và ngày có ai đọc thẳng kho ấy (xuất
   .csv, đồng bộ sang app khác) thì nó thành một cơ sở tên rỗng. */
$kho_tc = (array) VHCC_Luong::cai_dat( VHCC_NhanSu::TEN_CS_O, array() );
t( '🔴 gỡ tên là gỡ hẳn dòng khỏi kho, không để lại dòng rỗng',
	! array_key_exists( $L_CS, $kho_tc ), $kho_tc );
VHCC_NhanSu::dat_ten_coso( $l_ad, array( $L_CS => 'Tutu Bình Tân' ) );
VHCC_NhanSu::quen_ten_coso();
/* Cửa hàng trưởng KHÔNG đặt tên: tên hiện trên bảng của MỌI cửa hàng, không phải việc riêng
   của một cửa hàng nào. */
$r_tc = VHCC_NhanSu::dat_ten_coso( array( 'role' => 'Cửa hàng trưởng', 'cua_hang' => $L_CS ),
	array( $L_CS => 'Tên bậy' ) );
t( '🔴 Cửa hàng trưởng KHÔNG đặt được tên cơ sở', empty( $r_tc['ok'] ), $r_tc );
VHCC_NhanSu::quen_ten_coso();
teq( 'và tên cũ còn nguyên', $L_CS . ' — Tutu Bình Tân', VHCC_NhanSu::ten_coso( $L_CS ) );

/* ---- Màn Phân lịch: mặt của NGƯỜI XẾP ---- */
$tok_l = VHCC_Auth::phat_token( 'Chị Trưởng', 'Cửa hàng trưởng', $L_CS, 'LCHT' );
function vhcc_lich_web( $tok, $get = array(), $post = array() ) {
	$_GET = array_merge( array( 'man' => 'lich' ), $get );
	$_POST = $post ? array_merge( array( 'ky' => VHCC_Web::chu_ky( $tok ) ), $post ) : array();
	$_COOKIE = array( VHCC_Web::COOKIE => $tok );
	ob_start(); VHCC_Web::phuc_vu(); $h = ob_get_clean();
	$_GET = array(); $_POST = array(); $_COOKIE = array();
	return $h;
}
$h_l = vhcc_lich_web( $tok_l, array( 'lcs' => $L_CS ) );
t( '🔴 Cửa hàng trưởng vào được tab Lịch làm việc',
	strpos( $h_l, 'Phân lịch làm việc' ) !== false, substr( $h_l, 0, 400 ) );
t( 'và có tab ấy trên thanh màn', strpos( $h_l, '>Lịch làm việc<' ) !== false, $h_l );
t( 'có khối xếp một ô lịch', strpos( $h_l, 'value="lich_xep"' ) !== false, $h_l );
/* 🔴 NÓI RÕ LỊCH ≠ CHẤM CÔNG. Trộn hai thứ là trả tiền theo dự định. */
t( 'nói rõ lịch là DỰ ĐỊNH, không ghi vào bảng chấm công',
	strpos( $h_l, 'không ghi gì' ) !== false, $h_l );
/* Ô chọn cơ sở hiện NHÃN có tên, để khỏi chọn nhầm cửa hàng. */
t( 'ô chọn cơ sở hiện tên đầy đủ', strpos( $h_l, 'Tutu Bình Tân' ) !== false, $h_l );

/* 🔴 Ô CHỌN CƠ SỞ CẮT THEO QUYỀN. Bày cả 21 cơ sở cho cửa hàng trưởng rồi chối khi họ chọn là
   một câu trả lời không giải thích được: vì sao tên ấy lại nằm trong ô chọn ngay từ đầu? */
/* ⚠️ Khoá cơ sở trong thẻ phiên là `coso`, không phải `cua_hang` (`cua_hang` là cột của bảng
   hồ sơ). Dựng cảnh bằng khoá sai thì `ds_coso_cua()` trả rỗng và phép thử đỏ vì một lý do
   chẳng liên quan gì tới thứ nó định đo. */
$ds_l = VHCC_WebLich::ds_coso_xep( array( 'role' => 'Cửa hàng trưởng', 'coso' => $L_CS ) );
t( '🔴 Cửa hàng trưởng chỉ thấy cơ sở của mình trong ô chọn',
	in_array( $L_CS, $ds_l, true ) && ! in_array( $L_C2, $ds_l, true ), $ds_l );
$ds_l2 = VHCC_WebLich::ds_coso_xep( $l_ad );
t( 'Admin thì thấy mọi cơ sở', in_array( $L_C2, $ds_l2, true ), $ds_l2 );

/* ---- Xếp một ô lịch qua màn hình ---- */
$h_l = vhcc_lich_web( $tok_l, array( 'lcs' => $L_CS ), array(
	'viec' => 'lich_xep', 'lcs' => $L_CS,
	'l_ngay' => '2026-09-03', 'l_ma' => 'LNV1', 'l_ten' => 'Bạn Một',
	'l_ca' => 'Sáng', 'l_viec' => 'Trực quầy' ) );
t( 'xếp được ô lịch', strpos( $h_l, 'Đã xếp ô lịch' ) !== false, $h_l );
$ds_o = VHCC_Lich::ds_lich( $L_CS, '2026-09-01', '2026-09-30' );
teq( '🔴 ô lịch vào kho thật', 1, count( $ds_o ) );
teq( 'đúng ca', 'Sáng', $ds_o[0]['ca'] );
/* ⚠️ Lịch KHÔNG được đụng vào bảng chấm công — ghi vào đó là bảng lương thấy ngày "có hàng mà
   không có giờ", trông y như đi làm mà quên chấm, và thành trả tiền theo dự định. */
global $wpdb;
teq( '🔴 xếp lịch KHÔNG sinh hàng nào trong bảng chấm công', '0',
	(string) $wpdb->get_var( 'SELECT COUNT(*) FROM ' . VHCC_DB::t( 'cham_cong' ) ) );

/* Thiếu ngày hoặc thiếu mã -> `xep_lich` bỏ qua ô ấy. Báo "đã lưu" cho một lượt không ghi gì là
   người ta đóng màn đi và tưởng lịch đã có. */
$h_l = vhcc_lich_web( $tok_l, array( 'lcs' => $L_CS ), array(
	'viec' => 'lich_xep', 'lcs' => $L_CS, 'l_ngay' => '2026-09-04', 'l_ma' => '' ) );
t( '🔴 thiếu Mã NV thì báo LỖI, không báo đã lưu',
	strpos( $h_l, 'Chưa ghi ô nào' ) !== false && strpos( $h_l, 'Đã xếp ô lịch' ) === false, $h_l );

/* ---- Nhân viên: thấy lịch CỦA MÌNH, không thấy nút xếp ---- */
$tok_n = VHCC_Auth::phat_token( 'Bạn Một', 'Nhân viên', $L_CS, 'LNV1' );
$h_n = vhcc_lich_web( $tok_n, array( 'ltu' => '2026-09-01', 'lden' => '2026-09-30' ) );
t( '🔴 Nhân viên cũng vào được tab Lịch', strpos( $h_n, 'Phân lịch làm việc' ) !== false, $h_n );
t( 'và thấy khối "Lịch của tôi"', strpos( $h_n, 'Lịch của tôi' ) !== false, $h_n );
t( '🔴 thấy đúng ô lịch của mình', strpos( $h_n, '2026-09-03' ) !== false, $h_n );
/* 🔴 KHÔNG thấy nút xếp lịch — thấy nút rồi bấm vào bị chối là mời người ta làm một việc không
   làm được, và câu chối chẳng nói được gì hơn. */
t( '🔴 KHÔNG có nút xếp lịch', strpos( $h_n, 'value="lich_xep"' ) === false, $h_n );
t( 'không có nút duyệt', strpos( $h_n, 'value="lich_duyet"' ) === false, $h_n );
t( 'nhưng CÓ khối xin đổi lịch', strpos( $h_n, 'value="lich_xin"' ) !== false, $h_n );

/* Người khác KHÔNG thấy lịch của người này — cùng cơ sở, khác mã. */
$tok_n2 = VHCC_Auth::phat_token( 'Bạn Hai', 'Nhân viên', $L_CS, 'LNV2' );
$h_n2 = vhcc_lich_web( $tok_n2, array( 'ltu' => '2026-09-01', 'lden' => '2026-09-30' ) );
t( '🔴 chỉ lọc ra lịch của CHÍNH MÌNH, không bày lịch người khác',
	strpos( $h_n2, 'Chưa có ô lịch nào' ) !== false, $h_n2 );

/* ---- Xin đổi lịch: mã NV lấy từ THẺ PHIÊN, không từ ô nhập ---- */
/* 🔴 `xin_doi_lich` cố ý không đòi quyền quản lý (chính họ xin cho họ), nên nó nhận `ma_nv` từ
   lời gọi. Lớp web phải ép mã ấy bằng mã trong thẻ — không ép thì ai cũng gửi được một yêu cầu
   đứng tên người khác, và người duyệt ký vào một chuyện người kia không hề xin. */
$h_n = vhcc_lich_web( $tok_n, array( 'lcs' => $L_CS ), array(
	'viec' => 'lich_xin', 'lcs' => $L_CS,
	'ma_nv' => 'LNV2', 'l_ma' => 'LNV2',          // <- cố tình gửi mã người KHÁC
	'l_ngay' => '2026-09-03', 'l_ca' => 'Sáng', 'l_sang' => '2026-09-05',
	'l_viec' => 'Trực quầy', 'l_ly_do' => 'nhà có việc, đã nhờ được người đổi ca' ) );
t( 'gửi được yêu cầu', strpos( $h_n, 'Đã gửi yêu cầu' ) !== false, $h_n );
$yc_l = VHCC_Lich::ds_doi_lich( $l_ad, true );
teq( 'có đúng một yêu cầu chờ duyệt', 1, count( $yc_l ) );
teq( '🔴 yêu cầu đứng tên CHÍNH NGƯỜI GỬI, không phải mã họ gõ vào', 'LNV1', $yc_l[0]['ma_nv'] );

/* ---- Duyệt: phải GHI THẬT vào lịch ---- */
$h_l = vhcc_lich_web( $tok_l, array( 'lcs' => $L_CS ), array(
	'viec' => 'lich_duyet', 'lcs' => $L_CS, 'l_ma_yc' => $yc_l[0]['ma_yc'] ) );
t( 'duyệt xong báo rõ là đã ghi thật', strpos( $h_l, 'ĐÃ GHI THẬT' ) !== false, $h_l );
$ds_o = VHCC_Lich::ds_lich( $L_CS, '2026-09-01', '2026-09-30' );
$o_cu = '';
$o_moi = '';
foreach ( $ds_o as $r_o ) {
	if ( '2026-09-03' === $r_o['ngay'] ) { $o_cu = (string) $r_o['viec']; }
	if ( '2026-09-05' === $r_o['ngay'] ) { $o_moi = (string) $r_o['viec']; }
}
/* ⚠️ CÓ "đổi sang ngày" thì phải ghi HAI ô: ngày cũ để TRỐNG việc, ngày mới nhận việc. Chỉ ghi
   ngày mới là người đó bị xếp cả hai ngày. */
teq( '🔴 ngày cũ được để TRỐNG việc', '', $o_cu );
teq( '🔴 ngày mới nhận việc', 'Trực quầy', $o_moi );
teq( 'không còn yêu cầu nào chờ duyệt', 0, count( VHCC_Lich::ds_doi_lich( $l_ad, true ) ) );

/* ---- Gác quyền ở CỬA POST, không chỉ ở chỗ vẽ nút ---- */
/* Ở wp-admin cửa là `manage_options`; ra web là mất lớp ấy. Chỉ gác lúc vẽ thì ai đoán ra tên
   `viec` là gửi thẳng POST được — mà xoá một ô lịch thì người ta mất ca làm hôm đó. */
$b_l = VHCC_WebLich::viec( 'lich_xep', array( 'role' => 'Nhân viên', 'ma_nv' => 'LNV1', 'coso' => $L_CS ) );
t( '🔴 Nhân viên gửi thẳng POST xếp lịch vẫn bị chối',
	isset( $b_l[0]['loi'] ) && strpos( $b_l[0]['loi'], 'Xếp lịch làm việc' ) !== false, $b_l );
$b_l = VHCC_WebLich::viec( 'lich_xoa', array( 'role' => 'Nhân viên', 'ma_nv' => 'LNV1', 'coso' => $L_CS ) );
t( 'và xoá ô lịch cũng bị chối', isset( $b_l[0]['loi'] ), $b_l );
teq( 'không ô nào bị xoá', 2, count( VHCC_Lich::ds_lich( $L_CS, '2026-09-01', '2026-09-30' ) ) );

/* 🔴 VIỆC CỦA MÀN LỊCH PHẢI ĐI QUA ĐƯỢC CHỐT "chỉ xem được bảng chấm công".
   Chốt ấy là danh sách trắng chống việc HỒ SƠ — đúng cho màn Hồ sơ, nhưng người cần màn lịch
   nhất lại chính là người KHÔNG có bậc hồ sơ. Để định tuyến sau chốt thì cửa hàng trưởng bị đá
   ra bằng một câu nói về màn Hồ sơ, mà họ không hề đụng tới hồ sơ. */
t( '🔴 câu chối (nếu có) KHÔNG phải câu nói về màn Hồ sơ',
	strpos( $h_l, 'Việc này thuộc màn Hồ sơ' ) === false, $h_l );

/* ---- Cấu hình lịch: dùng chung cả chuỗi nên gác cao hơn ---- */
$h_l = vhcc_lich_web( $tok_l, array( 'lcs' => $L_CS ), array(
	'viec' => 'lich_ca', 'lcs' => $L_CS, 'l_ds' => "Sáng\nChiều" ) );
t( '🔴 Cửa hàng trưởng KHÔNG sửa được danh sách ca (dùng chung mọi cơ sở)',
	strpos( $h_l, 'Không có quyền sửa danh sách ca' ) !== false, $h_l );
$tok_a = VHCC_Auth::phat_token( 'Anh Admin', 'Admin', '', 'LADM' );
$h_a = vhcc_lich_web( $tok_a, array( 'lcs' => $L_CS ), array(
	'viec' => 'lich_ca', 'lcs' => $L_CS, 'l_ds' => "Sáng\nChiều" ) );
t( 'Admin thì sửa được', strpos( $h_a, 'Đã lưu danh sách ca' ) !== false, $h_a );
/* 🔴 Ô LỊCH MỒ CÔI PHẢI ĐƯỢC KÊU RA. `ca` là một phần KHOÁ của ô lịch, nên bỏ tên "Tối" khỏi
   danh sách KHÔNG đổi những ô đã xếp bằng tên ấy — chúng giữ tên cũ và trông như ca lạ. */
VHCC_Lich::xep_lich( $l_ad, $L_CS, array( array( 'ngay' => '2026-09-09', 'ma_nv' => 'LNV3',
	'ho_ten' => 'Bạn Ba', 'ca' => 'Tối', 'viec' => 'Trực đêm' ) ) );
$h_a = vhcc_lich_web( $tok_a, array( 'lcs' => $L_CS ), array(
	'viec' => 'lich_ca', 'lcs' => $L_CS, 'l_ds' => "Sáng\nChiều" ) );
t( '🔴 bỏ một tên ca thì kêu ra số ô lịch đang dùng tên ấy',
	strpos( $h_a, 'Tối: 1 ô' ) !== false, $h_a );
t( 'và nói rõ đổi tên ca KHÔNG đổi ô đã xếp',
	strpos( $h_a, 'KHÔNG đổi' ) !== false, $h_a );

/* ---- Khoảng ngày: gõ bậy thì về mặc định, gõ ngược thì đảo lại ---- */
/* Bảng rỗng trông y hệt "chưa xếp lịch ngày nào" — người ta sẽ đi xếp lại lịch đã có. */
$_GET = array( 'ltu' => 'hom qua', 'lden' => '2026-09-30' );
list( $k_tu, $k_den ) = VHCC_WebLich::khoang();
teq( 'ngày gõ bậy rơi về mặc định (đầu tháng)', gmdate( 'Y-m-01' ), $k_tu );
$_GET = array( 'ltu' => '2026-09-30', 'lden' => '2026-09-01' );
list( $k_tu, $k_den ) = VHCC_WebLich::khoang();
teq( '🔴 gõ ngược đầu đuôi thì ĐẢO lại, không trả khoảng rỗng', '2026-09-01', $k_tu );
teq( 'và đuôi là ngày sau', '2026-09-30', $k_den );
$_GET = array();

/* ---- Khối khai tên cơ sở nằm ở màn Cấu hình ---- */
$h_cf = vhcc_lich_web( $tok_a, array( 'man' => 'cau_hinh' ) );
t( 'màn Cấu hình có khối Tên đầy đủ của cơ sở',
	strpos( $h_cf, 'Tên đầy đủ của cơ sở' ) !== false, $h_cf );
t( 'có ô nhập cho từng mã', strpos( $h_cf, 'name="tcs[' . $L_CS . ']"' ) !== false, $h_cf );
t( 'và nói rõ MÃ không đổi', strpos( $h_cf, 'nó không đổi' ) !== false, $h_cf );
/* Cửa hàng trưởng gõ thẳng `?man=cau_hinh` cũng không tới được: `phuc_vu()` đẩy mọi màn không
   nằm trong `man_cua()` về màn mặc định. */
$h_cf_cht = vhcc_lich_web( $tok_l, array( 'man' => 'cau_hinh' ) );
t( 'Cửa hàng trưởng gõ thẳng ?man=cau_hinh thì KHÔNG thấy khối tên cơ sở',
	strpos( $h_cf_cht, 'Tên đầy đủ của cơ sở' ) === false, $h_cf_cht );

/* ⚠️ CHỐT TRONG `the_ten_cs()` TRÔNG THỪA — VÀ VẪN GIỮ. Đã phá thử: bỏ nó đi mà bộ thử vẫn
   xanh, vì cửa màn Cấu hình ở trên đã chặt hơn (`ngoai_coso` mới có tab, và màn lạ bị đẩy về
   mặc định). Giữ vì hai lẽ: nó đứng cùng hàng với `the_bo_phan()` và `the_ghep_cs()` vốn cũng
   tự gác — bỏ đúng một khối là tạo ra ngoại lệ không ai nhớ; và ngày cửa trên được nới ra (đã
   nới một lần rồi, xem `nguoi_vao()`) thì khối này không đi theo.
   Thay vì canh cái vỏ, canh QUAN HỆ HAI BẬC: bậc để THẤY tab Cấu hình không được thấp hơn bậc
   để ĐẶT TÊN cơ sở. Lệch quan hệ ấy là khối lọt ra ngoài tầm gác của nó. */
/* ⚠️ `dat_ten_coso( $u, array() )` với người ĐỦ QUYỀN sẽ GHI một kho rỗng — tức xoá sạch tên
   đã khai. Đó là hành vi đúng của hàm (bảng gửi lên rỗng = không còn tên nào), nhưng ở đây nó
   là tác dụng phụ, nên khai lại ngay sau vòng lặp. */
$bac_cf = 0;
foreach ( array( 'Nhân viên', 'Cửa hàng trưởng', 'Quản lý', 'Kế toán', 'Admin' ) as $v_cf ) {
	$u_cf = array( 'role' => $v_cf, 'ma_nv' => 'CF' . $bac_cf );
	$thay_tab = isset( VHCC_Web::man_cua( $u_cf )['cau_hinh'] );
	$dat_duoc = ! empty( VHCC_NhanSu::dat_ten_coso( $u_cf, array() )['ok'] );
	t( 'vai "' . $v_cf . '": thấy tab Cấu hình và đặt được tên là MỘT, không lệch',
		$thay_tab === $dat_duoc, $v_cf . ' tab=' . ( $thay_tab ? 1 : 0 ) . ' dat=' . ( $dat_duoc ? 1 : 0 ) );
	$bac_cf++;
}
VHCC_NhanSu::dat_ten_coso( $l_ad, array( $L_CS => 'Tutu Bình Tân' ) );
VHCC_NhanSu::quen_ten_coso();
teq( 'khai lại xong thì tên còn nguyên', $L_CS . ' — Tutu Bình Tân', VHCC_NhanSu::ten_coso( $L_CS ) );
/* ⚠️ 21 ô nhập giống hệt nhau thì người dùng trình đọc màn hình nghe 21 lần "ô nhập" mà không
   biết ô nào của mã nào. Nhãn phải CÓ, chỉ là không hiện ra. */
t( '🔴 mỗi ô có nhãn cho trình đọc màn hình',
	strpos( $h_cf, 'class="an" for="tcs_' ) !== false, $h_cf );
t( 'và lớp ấy kéo ra ngoài khung nhìn chứ không display:none (display:none thì trình đọc bỏ qua)',
	strpos( $h_cf, '.an{position:absolute' ) !== false, $h_cf );
$h_cf = vhcc_lich_web( $tok_a, array( 'man' => 'cau_hinh' ), array(
	'viec' => 'ten_cs', 'tcs' => array( $L_C2 => 'Cơ sở Khác' ) ) );
t( 'lưu được tên qua màn hình', strpos( $h_cf, 'Đã đổi tên' ) !== false, $h_cf );
VHCC_NhanSu::quen_ten_coso();
teq( 'và có hiệu lực thật', $L_C2 . ' — Cơ sở Khác', VHCC_NhanSu::ten_coso( $L_C2 ) );

/* 🔴 MÀN QUẢN TRỊ KHÔNG CÓ MỘT DÒNG SCRIPT NÀO. */
t( 'màn lịch không kéo theo script nào', stripos( $h_n, '<script' ) === false );
t( 'và không có thuộc tính onXxx=', preg_match( '/\son[a-z]+\s*=\s*["\']/i', $h_n ) === 0 );

$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'cai_dat' ) . " WHERE khoa IN ('COSO_TEN','LICH_CA','LICH_LOAI_VIEC','LICH_CO_SO')" );
VHCC_NhanSu::quen_ten_coso();
vhcc_dung_bang();

/* ======================================================================================
 *  68. KHUNG QUẢN TRỊ THEO MẪU HR V5.2 — cột dọc, tiêu đề màn, thẻ có biểu tượng
 *
 *  Anh Thắng 27/08/2026, gửi ba ảnh phần mềm HR V5.2 của Mr Trung: *"Chỗ phần giao diện và
 *  tính năng của trang chấm công thiết kế đẹp mắt y như này"*.
 *
 *  🔴 THANH NÚT NGANG HỎNG DẦN THEO SỐ MÀN, VÀ HỎNG IM LẶNG. Nay đã tám mục; trên màn hẹp
 *     chúng xuống hai hàng và mục nào rơi hàng dưới thì mắt không quét tới. Người dùng không
 *     báo "thiếu nút" — họ chỉ không bao giờ bấm vào nó, và cái tính năng ấy coi như không có.
 * ====================================================================================== */
vhcc_dung_bang();
vhcc_bo_phan( 'HR_CS', 'Khu vui chơi' );
$tok_hr = VHCC_Auth::phat_token( 'Anh Quản Trị', 'Admin', '', 'HRAD' );
function vhcc_hr( $tok, $get = array() ) {
	$_GET = $get; $_POST = array();
	$_COOKIE = array( VHCC_Web::COOKIE => $tok );
	ob_start(); VHCC_Web::phuc_vu(); $h = ob_get_clean();
	$_GET = array(); $_COOKIE = array();
	return $h;
}
$h_hr = vhcc_hr( $tok_hr, array( 'man' => 'cham', 'ccs' => 'HR_CS', 'cth' => '2026-08' ) );

/* ---- Cột dọc ---- */
t( '🔴 có cột dọc bên trái', strpos( $h_hr, '<aside class="canh">' ) !== false, substr( $h_hr, 0, 400 ) );
t( 'và nó nằm trong khung lưới hai cột', strpos( $h_hr, '<div class="ung">' ) !== false, $h_hr );
t( 'vùng nội dung là <main>', strpos( $h_hr, '<main class="vung">' ) !== false, $h_hr );
/* 🔴 KHUNG PHẢI ĐÓNG LẠI. Thiếu thẻ đóng thì trình duyệt tự vá — không ai thấy gì, cho tới
   ngày một thẻ khác bị nuốt theo và nửa trang biến mất. */
teq( 'khung mở và đóng đúng một lần', 1, substr_count( $h_hr, '<main class="vung">' ) );
teq( 'và có đúng một </main>', 1, substr_count( $h_hr, '</main>' ) );

/* Mỗi màn một dòng, có biểu tượng, và mục ĐANG MỞ nổi hẳn lên — cột tám mục thì người ta liếc
   chứ không đọc. */
t( 'mỗi mục có biểu tượng riêng', strpos( $h_hr, '<span class="bt">' ) !== false, $h_hr );
t( '🔴 mục đang mở được đánh dấu', strpos( $h_hr, '<a class="dang"' ) !== false, $h_hr );
teq( '🔴 CHỈ MỘT mục được đánh dấu đang mở', 1, substr_count( $h_hr, '<a class="dang"' ) );
/* Đúng mục đang xem, không phải mục nào khác — đánh dấu nhầm còn tệ hơn không đánh dấu. */
t( 'và đúng là mục của màn đang xem',
	preg_match( '~<a class="dang" href="[^"]*man=cham"~', $h_hr ) === 1, $h_hr );

/* ⚠️ VẼ THEO QUYỀN, y như thanh cũ. Ai không mở được màn nào thì màn ấy KHÔNG có mặt — chứ
   không hiện rồi chối. Hiện rồi chối là dạy người dùng rằng màn này hay nói dối. */
$tok_nv_hr = VHCC_Auth::phat_token( 'Bạn Nhân Viên', 'Nhân viên', 'HR_CS', 'HRNV' );
$h_nv_hr = vhcc_hr( $tok_nv_hr );
t( '🔴 Nhân viên KHÔNG thấy mục Hồ sơ trong cột dọc',
	strpos( $h_nv_hr, 'man=ho_so' ) === false, $h_nv_hr );
t( 'không thấy mục Máy & Firmware', strpos( $h_nv_hr, 'man=may' ) === false, $h_nv_hr );
t( 'nhưng vẫn thấy mục Công của tôi', strpos( $h_nv_hr, 'man=cong_toi' ) !== false, $h_nv_hr );
t( 'Admin thì thấy mục Máy & Firmware', strpos( $h_hr, 'man=may' ) !== false, $h_hr );

/* Chân cột: ai đang đăng nhập · nút Thoát · phiên bản đang chạy. */
t( 'chân cột nói ai đang đăng nhập',
	strpos( $h_hr, 'Anh Quản Trị · Admin' ) !== false, $h_hr );
t( 'có nút Thoát', strpos( $h_hr, 'value="thoat"' ) !== false, $h_hr );
t( 'và phiên bản đang chạy nằm ngay trong tầm mắt',
	strpos( $h_hr, 'class="canh-pb"' ) !== false, $h_hr );
/* Tên hệ vẫn là ĐƯỜNG VỀ TRANG CHÍNH — người ta bấm logo để về nhà ở mọi trang web trên đời. */
t( '🔴 logo vẫn là liên kết về trang chính',
	preg_match( '~<a[^>]*class="[^"]*\bhieu\b[^"]*"[^>]*href="[^"]*"~', $h_hr ) === 1, $h_hr );
/* 🔴 VÀ LOGO KHÔNG ĐƯỢC GIÃN CAO. Anh Thắng 27/08/2026, kèm ảnh cột dọc: *"bị lệch"* — một
   khoảng đen mênh mông giữa logo và mục đầu tiên, menu bị đẩy xuống quá nửa cột.
   Logo mang cả hai lớp `hieu canh-hieu`, mà `.hieu{flex:1}` vốn dựng cho thanh đầu trang CŨ —
   một flex hàng NGANG, ở đó `flex:1` để logo ăn hết chỗ thừa và đẩy nút Thoát sang phải. Nay
   logo nằm trong flex CỘT, nên đúng cái `flex:1` ấy làm nó giãn theo CHIỀU CAO.
   ⚠️ Đây là bẫy của việc DÙNG LẠI MỘT LỚP ở ngữ cảnh khác: thuộc tính không đổi, nhưng nghĩa
      của nó đổi. Phép thử canh chính chỗ chữa. */
t( '🔴 logo trong cột dọc KHÔNG giãn cao (thôi ăn chỗ của menu)',
	strpos( $h_hr, 'a.canh-hieu{display:block;flex:0 0 auto' ) !== false, $h_hr );
/* Và menu phải đứng NGAY dưới logo trong luồng — không có gì chen vào giữa. */
$vt_logo = strpos( $h_hr, 'class="hieu canh-hieu"' );
$vt_nav  = strpos( $h_hr, '<nav class="canh-nav">' );
t( 'menu đứng ngay sau logo', false !== $vt_logo && false !== $vt_nav && $vt_logo < $vt_nav,
	$vt_logo . ' / ' . $vt_nav );

/* ---- Tiêu đề màn ---- */
/* 🔴 Không có nó thì tám màn mở ra trông giống hệt nhau — cùng nền, cùng thẻ trắng, cùng bảng.
   Bấm một mục ở cột dọc rồi không chắc mình đã sang màn khác chưa. */
t( '🔴 màn nào cũng tự xưng tên', strpos( $h_hr, '<div class="tieu-man">' ) !== false, $h_hr );
t( 'và đúng tên màn đang mở',
	preg_match( '~<div class="tieu-man"><h1>Bảng công</h1>~', $h_hr ) === 1, $h_hr );
$h_hs = vhcc_hr( $tok_hr, array( 'man' => 'ho_so' ) );
t( 'sang màn khác thì tiêu đề đổi theo',
	preg_match( '~<div class="tieu-man"><h1>Hồ sơ &amp; tài khoản</h1>~', $h_hs ) === 1, $h_hs );
t( 'kèm một câu nói màn ấy để làm gì',
	strpos( $h_hs, 'Khai người, cấp PIN' ) !== false, $h_hs );

/* Mọi màn khai được đều phải có biểu tượng và một câu mô tả — thiếu là mục ấy trơ ra giữa cột. */
$thieu_bt = array();
$thieu_ch = array();
foreach ( array_keys( VHCC_Web::man_cua( array( 'role' => 'Admin' ) ) ) as $k_hr ) {
	if ( '▪' === VHCC_Web::bieu_man( $k_hr ) ) { $thieu_bt[] = $k_hr; }
	if ( '' === VHCC_Web::chu_man( $k_hr ) )   { $thieu_ch[] = $k_hr; }
}
teq( '🔴 mọi màn đều có biểu tượng riêng', array(), $thieu_bt );
teq( 'và đều có một câu nói mình để làm gì', array(), $thieu_ch );

/* ---- Thẻ Truy cập nhanh ở Trang chính ---- */
$h_nha_hr = vhcc_hr( $tok_hr, array( 'man' => 'nha' ) );
/* ⚠️ CẮT ĐÚNG KHỐI THẺ rồi mới soi. Cột dọc cũng dùng `<span class="bt">`, nên soi cả trang là
   phép thử luôn xanh — kể cả khi thẻ chẳng còn vòng tròn nào. Đã phá thử để thấy. */
$khoi_the = preg_match( '~<div class="the-viec">.*?</div></div>~s', $h_nha_hr, $m_the ) ? $m_the[0] : '';
t( 'dựng cảnh: cắt được đúng khối thẻ', '' !== $khoi_the, substr( $h_nha_hr, 0, 300 ) );
t( 'thẻ có vòng tròn biểu tượng', strpos( $khoi_the, '<span class="bt">' ) !== false, $khoi_the );
teq( '🔴 mỗi thẻ đúng một vòng tròn',
	substr_count( $khoi_the, 'class="viec' ), substr_count( $khoi_the, '<span class="bt">' ) );
t( '🔴 và có dòng "Mở chức năng →" như mẫu',
	strpos( $h_nha_hr, 'Mở chức năng →' ) !== false, $h_nha_hr );
/* ⚠️ BIỂU TƯỢNG RA KHỎI TÊN. Trước đây tên là "📷 Chấm công" — hình dán liền chữ nên nó trôi
   theo chữ khi tên xuống dòng, và không xếp thẳng hàng với các thẻ khác. */
t( 'biểu tượng KHÔNG còn dính vào tên', strpos( $h_nha_hr, '<b>📷 Chấm công</b>' ) === false, $h_nha_hr );
t( 'mà tên là tên', strpos( $h_nha_hr, '<b>Chấm công</b>' ) !== false, $h_nha_hr );
/* Thẻ dựng theo QUYỀN, y như cột dọc. */
$h_nha_nv_hr = vhcc_hr( $tok_nv_hr, array( 'man' => 'nha' ) );
t( '🔴 Nhân viên KHÔNG thấy thẻ Máy & Firmware',
	strpos( $h_nha_nv_hr, 'Máy &amp; Firmware</b>' ) === false, $h_nha_nv_hr );
t( 'Admin thì thấy', strpos( $h_nha_hr, 'Máy &amp; Firmware</b>' ) !== false, $h_nha_hr );

/* ---- Chân trang nằm TRONG vùng nội dung ---- */
/* 🔴 Đóng khung trước khi in chân trang là chân trang rơi ra ngoài: trên màn rộng nó trải hết
   bề ngang, chui xuống dưới cả cột dọc, và lệch hẳn so với mọi thứ phía trên. Đúng cái anh
   Thắng đã bắt một lần rồi — *"bị lệch"*, 26/08 — chỉ khác chỗ lệch. */
$vt_cty  = strpos( $h_hr, 'class="cty"' );
$vt_dong = strpos( $h_hr, '</main>' );
t( '🔴 chân trang nằm TRƯỚC chỗ đóng khung, tức trong vùng nội dung',
	false !== $vt_cty && false !== $vt_dong && $vt_cty < $vt_dong, $vt_cty . ' / ' . $vt_dong );

/* ---- Màn ĐĂNG NHẬP không có cột dọc, và không thừa thẻ đóng ---- */
/* Chưa biết người là ai thì lấy gì vẽ menu. Đóng khung vô điều kiện là mỗi trang ấy thừa hai
   thẻ đóng — trình duyệt tự sửa nên không ai thấy, cho tới ngày một thẻ khác bị nuốt theo. */
$_GET = array(); $_POST = array(); $_COOKIE = array();
ob_start(); VHCC_Web::phuc_vu(); $h_pin = ob_get_clean();
t( 'màn nhập PIN KHÔNG có cột dọc', strpos( $h_pin, '<aside class="canh">' ) === false, $h_pin );
teq( '🔴 và KHÔNG thừa thẻ </main> nào', 0, substr_count( $h_pin, '</main>' ) );

/* ---- Dải kết quả có chấm tròn (mẫu ảnh 1) ---- */
t( 'dải báo có chấm tròn đầu dòng', strpos( $h_hr, '.bao::before' ) !== false, $h_hr );

/* ---- Cột dọc chỉ dựng cột trên MÀN RỘNG ---- */
/* ⚠️ Anh Thắng mở bằng điện thoại nhiều hơn máy tính, mà một cột 232px trên màn 390px là ăn
   hơn nửa bề ngang. Dưới 1000px thì nó nằm ngang trên đầu và cuộn ngang được. */
t( '🔴 cột dọc chỉ bật từ 1000px trở lên',
	strpos( $h_hr, '@media(min-width:1000px){.ung{display:grid' ) !== false, $h_hr );
t( 'mặc định (màn hẹp) thì KHÔNG phải lưới hai cột',
	strpos( $h_hr, '.ung{display:block}' ) !== false, $h_hr );

/* ---- Bấm 👁 xem PIN thì ĐỨNG NGUYÊN CHỖ ---- */
/* Anh Thắng 27/08/2026: *"bấm là hiện ra luôn nhé, đây nó hiện nhưng cứ nhảy lên đầu trang, xong
   phải kéo lại"*.
   Bấm 👁 là tải lại cả trang (màn này KHÔNG có một dòng script nào), nên trình duyệt về đỉnh.
   Bảng hồ sơ dài mấy trăm dòng: người ta cuộn tới hàng thứ 180, bấm 👁, rồi phải cuộn lại từ đầu
   để đọc con số vừa hiện ra. */
VHCC_NhanSu::luu_ho_so( array( 'role' => 'Admin', 'ma_nv' => 'HRAD' ), array(
	'ma_nv' => 'HRPIN1', 'ho_ten' => 'Người Có PIN', 'cua_hang' => 'HR_CS', 'sdt' => '0900',
	'pin_dang_nhap' => '779776' ) );
$h_pn = vhcc_hr( $tok_hr, array( 'man' => 'ho_so', 'q' => 'HRPIN1' ) );
t( 'dựng cảnh: thấy hàng của người có PIN', strpos( $h_pn, 'HRPIN1' ) !== false, substr( $h_pn, 0, 300 ) );
t( '🔴 hàng ấy mang neo riêng', strpos( $h_pn, 'id="hs-HRPIN1"' ) !== false, $h_pn );
t( '🔴 nút 👁 trỏ về đúng hàng ấy',
	preg_match( '~<a href="[^"]*pin=HRPIN1[^"]*#hs-HRPIN1"~', $h_pn ) === 1, $h_pn );
/* 🔴 NEO PHẢI KHỚP CHÍNH XÁC VỚI `id`. Lệch một ký tự là neo trỏ vào hư không, và trình duyệt
   lặng lẽ đứng yên ở đỉnh — y như chưa chữa gì, mà không có gì báo. */
if ( preg_match( '~href="[^"]*(#hs-[^"]*)"~', $h_pn, $m_pn ) ) {
	t( '🔴 neo trỏ tới một id CÓ THẬT trong trang',
		strpos( $h_pn, 'id="' . substr( $m_pn[1], 1 ) . '"' ) !== false, $m_pn[1] );
}
/* Bấm rồi thì PIN hiện ra, và nút "ẩn" cũng phải giữ chỗ — không thì đóng lại là nhảy lần nữa. */
$h_pn2 = vhcc_hr( $tok_hr, array( 'man' => 'ho_so', 'q' => 'HRPIN1', 'pin' => 'HRPIN1' ) );
t( '🔴 PIN hiện ra', strpos( $h_pn2, '779776' ) !== false, $h_pn2 );
t( 'và nút ẩn cũng trỏ về đúng hàng',
	preg_match( '~<a href="[^"]*#hs-HRPIN1">ẩn</a>~', $h_pn2 ) === 1, $h_pn2 );
/* Hàng hồ sơ phải chừa chỗ cho thanh đầu trang, không thì nó dừng ngay sau thanh và bị che. */
t( 'hàng hồ sơ chừa chỗ cho thanh đầu trang',
	strpos( $h_pn, 'tr[id^="hs-"]{scroll-margin-top' ) !== false, $h_pn );
/* ⚠️ KHÔNG IN PIN RA khi người xem không có quyền — trang này chạy ngoài internet và ảnh chụp
   màn hình đi khắp nơi.
   ⚠️ DỰNG CẢNH BẰNG **KẾ TOÁN**, không phải Cửa hàng trưởng. `xem_pin` ở bậc Admin còn `ho_so`
      ở bậc Kế toán — nên Kế toán VÀO ĐƯỢC màn hồ sơ mà KHÔNG xem được PIN, đúng khe cần canh.
      Cửa hàng trưởng thì cửa MÀN đã chặn từ trước: bỏ hẳn chốt PIN đi mà phép thử vẫn xanh, vì
      họ có thấy cái bảng nào đâu. Đã phá thử để thấy. */
$tok_kt_pn = VHCC_Auth::phat_token( 'Chị Kế Toán', 'Kế toán', '', 'HRKT' );
$h_pn3 = vhcc_hr( $tok_kt_pn, array( 'man' => 'ho_so', 'q' => 'HRPIN1', 'pin' => 'HRPIN1' ) );
t( 'dựng cảnh: Kế toán VÀO ĐƯỢC màn hồ sơ', strpos( $h_pn3, 'HRPIN1' ) !== false,
	substr( $h_pn3, 0, 300 ) );
t( '🔴 nhưng KHÔNG thấy con số PIN', strpos( $h_pn3, '779776' ) === false, $h_pn3 );
t( 'và cũng không có nút 👁 để bấm', strpos( $h_pn3, '>👁</a>' ) === false, $h_pn3 );

/* ---- Tên người trong lưới là ĐƯỜNG SANG HỒ SƠ ---- */
/* Anh Thắng 27/08/2026, chỉ vào cột Nhân viên: *"Khi bấm vào thông tin nhân sự chỗ này, nó sẽ
   nhảy sang tab thông tin nhân sự đó, để tiện chỉnh thông tin nhân, set cơ sở, hay liên kết các
   web khác lại theo cấu hình"*.
   🔴 Đường đi cũ dài và dễ lạc: sang tab Hồ sơ → gõ tên vào ô tìm → dò trong danh sách vài trăm
      người → bấm Sửa. Bước "gõ tên" là bước hay lạc nhất: tên trùng, dấu gõ khác nhau, người ta
      gõ "Thắng" mà sổ ghi "Thăng". Cái tên đang nằm sẵn trước mắt CHÍNH LÀ khoá. */
vhcc_cham( 'HR_CS', '2026-08-06', 'LNV1', '', '08:00:00', '17:00:00' );
$h_ln = vhcc_hr( $tok_hr, array( 'man' => 'cham', 'ccs' => 'HR_CS', 'cth' => '2026-08' ) );
t( 'dựng cảnh: lưới có người', strpos( $h_ln, 'Người LNV1' ) !== false, substr( $h_ln, 0, 300 ) );
t( '🔴 tên người là một liên kết', strpos( $h_ln, 'class="ten-nv"' ) !== false, $h_ln );
/* 🔴 TRỎ ĐÚNG NGƯỜI. Bỏ tham số `sua` thì mọi tên dẫn về cùng một danh sách trơn — vẫn là liên
   kết, vẫn bấm được, và vẫn phải đi tìm lại từ đầu. */
t( '🔴 và trỏ tới ĐÚNG hồ sơ của người ấy',
	preg_match( '~<a class="ten-nv" href="[^"]*man=ho_so[^"]*sua=LNV1[^"]*"~', $h_ln ) === 1, $h_ln );

/* ⚠️ CHỈ VẼ CHO NGƯỜI MỞ ĐƯỢC HỒ SƠ. Vẽ cho cả người không có quyền thì bấm vào chỉ nhận một
   câu chối — mà cái liên kết thì cứ nằm đó mời gọi mỗi ngày. Cùng luật với cột dọc và thẻ. */
$tok_cht_ln = VHCC_Auth::phat_token( 'Chị Trưởng', 'Cửa hàng trưởng', 'HR_CS', 'HRCHT' );
$h_ln_cht = vhcc_hr( $tok_cht_ln, array( 'man' => 'cham', 'ccs' => 'HR_CS', 'cth' => '2026-08' ) );
t( 'dựng cảnh: Cửa hàng trưởng cũng thấy lưới', strpos( $h_ln_cht, 'Người LNV1' ) !== false,
	substr( $h_ln_cht, 0, 300 ) );
t( '🔴 Cửa hàng trưởng KHÔNG thấy tên thành liên kết',
	strpos( $h_ln_cht, 'class="ten-nv"' ) === false, $h_ln_cht );
t( 'nhưng tên vẫn hiện đủ', strpos( $h_ln_cht, 'Người LNV1' ) !== false, $h_ln_cht );

/* ---- Nhãn khối (ảnh 2) ---- */
/* 🔴 Màn Máy & Firmware có CHÍN khối liền nhau, màn Cấu hình có năm. Không có nhãn thì chúng là
   chín cái thẻ trắng nối đuôi, tiêu đề chìm vào giữa đám chữ, và cuộn xuống là mất dấu mình
   đang ở khối nào — người trực một cửa hàng mất chấm công phải đọc từ đầu màn xuống. */
t( '🔴 tiêu đề khối được bôi thành NHÃN', strpos( $h_hr, '.the>h2,.the>h3{' ) !== false, $h_hr );
t( 'nhãn ấy là chữ hoa nền nhạt', strpos( $h_hr, 'text-transform:uppercase;color:#1e40af;background:#eff6ff' ) !== false, $h_hr );
/* ⚠️ CHỈ con TRỰC TIẾP của `.the`. Mấy `h3` nằm sâu bên trong (trong `<details>`, trong bảng) là
   tiêu đề phụ — bôi nhãn cho chúng nữa thì cả màn đầy nhãn, và nhãn hết nghĩa. */
t( '🔴 chọn con trực tiếp (`>`), không phải mọi con cháu',
	strpos( $h_hr, '.the h2,.the h3{font-size:13px' ) === false, $h_hr );

/* ---- Nút theo VIỆC (ảnh 2) ---- */
/* Màu là thứ mắt đọc trước chữ, nên nó phải nói đúng: xanh lá = thêm mới, cam = việc chạy lâu
   và chạm ra ngoài (đọc máy, nạp tệp), đỏ = việc không lùi được. */
t( 'có nút xanh lá cho việc THÊM', strpos( $h_hr, 'button.them{background:var(--luc)' ) !== false, $h_hr );
t( 'và nút cam cho việc CHẠY LÂU', strpos( $h_hr, 'button.chay{background:var(--vang)' ) !== false, $h_hr );

/* ---- Đánh số hàng (ảnh 1 và 2) ---- */
/* Bảng máy có 26 dòng, bảng lịch cả tháng có mấy trăm. Người trực gọi điện cho cửa hàng mà nói
   được "dòng 12" thì hai bên nhìn cùng một chỗ. */
t( '🔴 bảng danh sách được đánh số bằng CSS', strpos( $h_hr, 'table.stt tbody{counter-reset:d}' ) !== false, $h_hr );
/* ⚠️ ĐÁNH SỐ BẰNG CSS, không thêm cột `<td>`. Thêm cột thật là mỗi bảng phải sửa cả `<thead>`
   lẫn mọi `colspan` của hàng tổng — chỗ nào quên là bảng lệch một ô, im lặng. */
t( 'hàng TỔNG không bị đánh số (26 máy không hoá 27)',
	strpos( $h_hr, 'table.stt tbody tr.tong{counter-increment:none}' ) !== false, $h_hr );
/* 🔴 Và KHÔNG bôi cho mọi bảng: lưới cả tháng có cột đầu là TÊN NGƯỜI — chèn số vào đó là số
   dính vào giữa tên.
   ⚠️ Đo bằng chính LUẬT, đừng đo bằng cảnh: cảnh này không có ai chấm công nên lưới cả tháng
      chẳng in ra, và một regex tìm bảng lưới sẽ trượt vì KHÔNG CÓ BẢNG chứ không phải vì luật
      đúng. Luật ở đây là "chỉ bảng khai lớp `stt` mới bị đánh số". */
t( '🔴 quy tắc đánh số BUỘC phải có lớp stt',
	strpos( $h_hr, 'table.stt tbody td:first-child::before' ) !== false
	&& strpos( $h_hr, 'table tbody td:first-child::before' ) === false, $h_hr );
/* Và trên một màn CÓ lưới thật (cảnh hàng sửa ở khối 64), lưới ấy không mang lớp `stt`. */
t( '🔴 lưới cả tháng KHÔNG khai lớp stt',
	preg_match( '~<table class="cc"~', $h_ls ) === 1
	&& strpos( $h_ls, '<table class="cc stt"' ) === false, substr( $h_ls, 0, 300 ) );

/* 🔴 KHÔNG một dòng script — cùng luật với cả màn quản trị. */
t( 'khung mới không kéo theo script nào', stripos( $h_hr, '<script' ) === false );
t( 'và không có thuộc tính onXxx=', preg_match( '/\son[a-z]+\s*=\s*["\']/i', $h_hr ) === 0 );

vhcc_dung_bang();

/* ======================================================================================
 *  69. NẠP LẦN HAI KHÔNG ĐÈ LÊN GIỜ NGƯỜI TA ĐÃ SỬA HOẶC BÙ
 *
 *  Anh Thắng 27/08/2026: *"Nhớ bổ sung dữ liệu lên, chỉ đè dữ liệu khi nó trống, tránh đè lần 2"*.
 *
 *  `quyet_dinh_gio()` vốn đã lo phần "không thu hẹp": trùng thì bỏ, nằm giữa thì bỏ, chỉ nới ra
 *  hai đầu. Nhưng NỚI RA cũng là đè, khi cái nó đè lên là một quyết định của người — và cả hai
 *  đường dưới đây đều IM LẶNG, xoá mất một quyết định có lý do, có người ký, có nhật ký.
 * ====================================================================================== */
vhcc_dung_bang();
$D_CS2 = 'DE_CS';
vhcc_bo_phan( $D_CS2, 'Khu vui chơi' );
$u_de = array( 'role' => 'Admin', 'name' => 'Anh Admin', 'ma_nv' => 'DEAD' );
VHCC_NhanSu::luu_ho_so( $u_de, array( 'ma_nv' => 'DE1', 'ho_ten' => 'Người DE1',
	'cua_hang' => $D_CS2, 'sdt' => '0900' ) );
VHCC_NhanSu::luu_ho_so( $u_de, array( 'ma_nv' => 'DE2', 'ho_ten' => 'Người DE2',
	'cua_hang' => $D_CS2, 'sdt' => '0900' ) );

/* ---- Cảnh 1: Admin SỬA giờ ra, rồi máy đẩy lại lượt cũ ---- */
/* Máy ghi 08:00 và 22:00. Camera cho thấy người ấy về lúc 17:00 — máy lệch đồng hồ. */
VHCC_Nhan::ghi_gio( $D_CS2, '2026-07-06', 'DE1', 'Người DE1', VHCC_DB::giay( '08:00:00' ), '', 'may' );
VHCC_Nhan::ghi_gio( $D_CS2, '2026-07-06', 'DE1', 'Người DE1', VHCC_DB::giay( '22:00:00' ), '', 'may' );
$r_de = VHCC_Bu::sua( $u_de, array( 'coso' => $D_CS2, 'ngay' => '2026-07-06', 'ma_nv' => 'DE1',
	'ra' => '17:00', 'ly_do' => 'máy lệch đồng hồ 5 tiếng, đối chiếu camera' ) );
t( 'dựng cảnh: Admin sửa được giờ ra', ! empty( $r_de['ok'] ), $r_de );
$o_de = VHCC_Bu::cac_o( array( $D_CS2 ), '2026-07-06', 'DE1' );
teq( 'giờ ra nay là 17:00', '17:00', $o_de[0]['ra'] );

/* 🔴 NẠP LẠI tệp .csv cũ (hoặc máy đẩy lại lô cũ) có đúng lượt 22:00. */
VHCC_Nhan::ghi_gio( $D_CS2, '2026-07-06', 'DE1', 'Người DE1', VHCC_DB::giay( '22:00:00' ), '', 'sheet' );
$o_de = VHCC_Bu::cac_o( array( $D_CS2 ), '2026-07-06', 'DE1' );
teq( '🔴 lượt nạp lại KHÔNG đè lên giờ Admin vừa sửa', '17:00', $o_de[0]['ra'] );
teq( 'và giờ vào cũng nguyên', '08:00', $o_de[0]['vao'] );
/* Cổng phải NÓI RA là đã giữ, đừng im lặng — hoặc máy lệch đồng hồ thật, hoặc lượt sửa kia sai,
   và cả hai đều cần người nhìn. */
$kq_de = VHCC_Nhan::ghi_gio( $D_CS2, '2026-07-06', 'DE1', 'Người DE1',
	VHCC_DB::giay( '22:30:00' ), '', 'may' );
teq( '🔴 trả về loại RIÊNG "giu-tay", không gộp vào "trung"', 'giu-tay', $kq_de['loai'] );
t( 'và kể ra ô nào bị giữ', in_array( 'ra', (array) $kq_de['giuO'], true ), $kq_de );

/* ---- Cảnh 2: Cửa hàng trưởng BÙ giờ vào, rồi máy sống lại đẩy lô cũ ---- */
$u_cht_de = array( 'role' => 'Cửa hàng trưởng', 'name' => 'Chị Trưởng', 'coso' => $D_CS2, 'ma_nv' => 'DECHT' );
$r_de = VHCC_Bu::ghi( $u_cht_de, array( 'coso' => $D_CS2, 'ngay' => '2026-07-07', 'ma_nv' => 'DE2',
	'vao' => '08:00', 'ly_do' => 'máy hỏng sáng nay, có camera' ) );
t( 'dựng cảnh: bù được giờ vào', ! empty( $r_de['ok'] ), $r_de );
VHCC_Nhan::ghi_gio( $D_CS2, '2026-07-07', 'DE2', 'Người DE2', VHCC_DB::giay( '07:45:00' ), '', 'may' );
$o_de2 = VHCC_Bu::cac_o( array( $D_CS2 ), '2026-07-07', 'DE2' );
teq( '🔴 lượt máy sớm hơn KHÔNG đè lên giờ vừa bù', '08:00', $o_de2[0]['vao'] );

/* 🔴 VÀ MÁY KHÔNG ĐƯỢC DỰNG RA MỘT "GIỜ RA" TỪ CHÍNH CON SỐ NGƯỜI TA BÙ.
   Nhánh "đảo thứ tự" làm hai việc một lúc: đặt giờ vào mới, và ĐẨY GIỜ VÀO CŨ XUỐNG LÀM GIỜ RA
   khi ô ra còn trống. Giữ ô `vao` mà để nguyên ô `ra` thì ngày ấy hoá ra "vào 08:00, ra 08:00"
   — 0 giờ làm, mà nhìn bảng thì đủ cặp giờ nên KHÔNG ô nào đỏ, không ai đi tìm.
   Phá thử mới lộ ra: cả hai đường đều cho kết quả CUỐI giống nhau (17:10), nên phép thử ở dưới
   không phân biệt được. Phải đo ngay sau lượt 07:45, lúc ô ra còn đang trống. */
$o_de2 = VHCC_Bu::cac_o( array( $D_CS2 ), '2026-07-07', 'DE2' );
teq( '🔴 ô giờ ra vẫn TRỐNG — máy không tự bịa một giờ ra từ lượt bù', '—', $o_de2[0]['ra'] );

/* ---- 🔴 NHƯNG Ô CÒN TRỐNG THÌ VẪN PHẢI VÀO ---- */
/* Đúng chữ anh Thắng: *chỉ đè khi nó trống*. Bù giờ vào rồi máy gửi giờ ra thật thì giờ ra ấy
   VẪN PHẢI VÀO — chặn nó là bắt người ta bù tay cả cặp trong khi máy đã có sẵn con số đúng. */
VHCC_Nhan::ghi_gio( $D_CS2, '2026-07-07', 'DE2', 'Người DE2', VHCC_DB::giay( '17:10:00' ), '', 'may' );
$o_de2 = VHCC_Bu::cac_o( array( $D_CS2 ), '2026-07-07', 'DE2' );
teq( '🔴 ô giờ ra còn TRỐNG thì máy vẫn ghi được', '17:10', $o_de2[0]['ra'] );
teq( 'và giờ vào đã bù vẫn nguyên', '08:00', $o_de2[0]['vao'] );

/* ---- 🔴 XOÁ TRẮNG RỒI MÁY DỰNG LẠI ĐÚNG CON SỐ VỪA XOÁ ---- */
/* Ô có dấu tay mà đang TRỐNG là ô người ta cố ý xoá — Admin xoá một giờ ra sai chẳng hạn. Máy
   đẩy lại lô cũ rồi dựng đúng con số ấy là làm hỏng chính quyết định vừa rồi, và lần này còn
   khó thấy hơn: bảng lại đủ cặp giờ như chưa có chuyện gì.
   Nhánh "đảo thứ tự" là đường nó đi: lượt mới sớm hơn giờ vào thì giờ vào CŨ tụt xuống làm giờ
   ra — đúng vào ô vừa bị xoá. */
vhcc_cham( $D_CS2, '2026-07-11', 'DE1', '', '09:00:00', '18:00:00' );
$r_xt = VHCC_Bu::sua( $u_de, array( 'coso' => $D_CS2, 'ngay' => '2026-07-11', 'ma_nv' => 'DE1',
	'xoa_ra' => true, 'ly_do' => 'giờ ra 18:00 là của máy khác, xoá đi để bù lại' ) );
t( 'dựng cảnh: Admin xoá trắng được giờ ra', ! empty( $r_xt['ok'] ), $r_xt );
$o_xt = VHCC_Bu::cac_o( array( $D_CS2 ), '2026-07-11', 'DE1' );
teq( 'ô giờ ra đang trống', '—', $o_xt[0]['ra'] );
VHCC_Nhan::ghi_gio( $D_CS2, '2026-07-11', 'DE1', 'Người DE1', VHCC_DB::giay( '07:30:00' ), '', 'may' );
$o_xt = VHCC_Bu::cac_o( array( $D_CS2 ), '2026-07-11', 'DE1' );
teq( '🔴 máy KHÔNG dựng lại giờ ra vừa bị xoá', '—', $o_xt[0]['ra'] );
/* ⚠️ Nhưng ô `vao` thì KHÔNG có dấu tay, nên lượt 07:30 vẫn phải vào — đó là một lượt bấm
   thật, sớm hơn giờ vào đang có. Chốt chỉ giữ ô người ta ĐÃ ĐỘNG TỚI, không đóng băng cả
   ngày: đóng băng cả ngày là mỗi lượt sửa một ô làm cả ngày ấy thôi nhận giờ từ máy. */
teq( 'còn giờ vào vẫn được nới bình thường (ô ấy chưa ai động)', '07:30', $o_xt[0]['vao'] );

/* ---- Ngày KHÔNG ai động tay thì máy nới bình thường ---- */
/* Chốt này chỉ được cắn đúng chỗ nó phải cắn. Cắn cả những ngày bình thường là cổng thôi nhận
   giờ ra — mà đó là đường đi hằng ngày của cả chuỗi. */
VHCC_Nhan::ghi_gio( $D_CS2, '2026-07-08', 'DE1', 'Người DE1', VHCC_DB::giay( '08:05:00' ), '', 'may' );
VHCC_Nhan::ghi_gio( $D_CS2, '2026-07-08', 'DE1', 'Người DE1', VHCC_DB::giay( '17:20:00' ), '', 'may' );
VHCC_Nhan::ghi_gio( $D_CS2, '2026-07-08', 'DE1', 'Người DE1', VHCC_DB::giay( '22:40:00' ), '', 'may' );
$o_de3 = VHCC_Bu::cac_o( array( $D_CS2 ), '2026-07-08', 'DE1' );
teq( '🔴 ngày không ai động tay: máy vẫn NỚI giờ ra như cũ', '22:40', $o_de3[0]['ra'] );
teq( 'giờ vào giữ lượt sớm nhất', '08:05', $o_de3[0]['vao'] );

/* ---- Sổ chỉ nhớ ĐÚNG CƠ SỞ, đúng ngày ---- */
/* 🔴 Bỏ lọc cơ sở là một lượt sửa ở cửa hàng A khoá luôn ô cùng ngày cùng mã ở cửa hàng B —
   mà người làm hai cơ sở là chuyện thường (xem khối 60). Lúc ấy máy ở B im lặng không ghi
   được gì, và không câu nào nói vì sao. */
vhcc_bo_phan( 'DE_CS_B', 'Khu vui chơi' );
VHCC_Nhan::ghi_gio( 'DE_CS_B', '2026-07-06', 'DE1', 'Người DE1', VHCC_DB::giay( '08:10:00' ), '', 'may' );
VHCC_Nhan::ghi_gio( 'DE_CS_B', '2026-07-06', 'DE1', 'Người DE1', VHCC_DB::giay( '16:00:00' ), '', 'may' );
$tay_b = VHCC_Bu::o_da_dong_tay( 'DE_CS_B', '2026-07-06', 'DE1' );
t( '🔴 sổ KHÔNG nhớ nhầm sang cơ sở khác',
	empty( $tay_b['vao'] ) && empty( $tay_b['ra'] ), $tay_b );
VHCC_Nhan::ghi_gio( 'DE_CS_B', '2026-07-06', 'DE1', 'Người DE1', VHCC_DB::giay( '18:30:00' ), '', 'may' );
$o_b = VHCC_Bu::cac_o( array( 'DE_CS_B' ), '2026-07-06', 'DE1' );
teq( 'nên máy ở cơ sở kia vẫn nới giờ ra bình thường', '18:30', $o_b[0]['ra'] );
/* Sang NGÀY KHÁC cũng vậy — lượt sửa ngày 06 không được khoá ngày 09. */
$tay_n = VHCC_Bu::o_da_dong_tay( $D_CS2, '2026-07-09', 'DE1' );
t( 'và không nhớ nhầm sang ngày khác',
	empty( $tay_n['vao'] ) && empty( $tay_n['ra'] ), $tay_n );

/* ---- Sổ nhật ký là NGUỒN THẬT, không phải cột `nguon` ---- */
/* 🔴 Cột `nguon` bị NỚI thành `hon-hop` ngay khi một lượt máy chạm vào — dấu vết "ô này người ta
   đã sửa" tan mất sau đúng một lượt, và lượt thứ hai đè thoải mái. Bảng `cham_bu` thì ngược
   lại: mỗi lượt bù và mỗi lượt sửa đều ghi MỘT DÒNG CHO MỖI Ô, và bảng ấy không có đường xoá. */
$tay_de = VHCC_Bu::o_da_dong_tay( $D_CS2, '2026-07-06', 'DE1' );
t( '🔴 sổ nhớ đúng ô đã sửa', ! empty( $tay_de['ra'] ), $tay_de );
t( 'và KHÔNG nhớ nhầm ô kia', empty( $tay_de['vao'] ), $tay_de );
$tay_de = VHCC_Bu::o_da_dong_tay( $D_CS2, '2026-07-08', 'DE1' );
t( 'ngày không ai động tay thì sổ trống', empty( $tay_de['vao'] ) && empty( $tay_de['ra'] ), $tay_de );
/* Mã rỗng / cơ sở rỗng -> trả rỗng.
   ⚠️ Chốt `if ( '' === $coso || '' === $ma ) return` là PHÒNG XA, không phải chốt canh hành vi:
      truy vấn với khoá rỗng cũng trả rỗng, nên bỏ nó đi thì kết quả y hệt — chỉ tốn thêm một
      lượt hỏi cơ sở dữ liệu. Đã phá thử và ghi lại ở đây để người sau khỏi đi tìm phép thử
      canh nó: KHÔNG CÓ, và cố dựng một phép thử như thế là đo số truy vấn, thứ mà bản giả của
      bộ thử không đếm. Giữ chốt vì nó rẻ và nói ra ý định. */
$tay_de = VHCC_Bu::o_da_dong_tay( '', '2026-07-06', '' );
t( 'thiếu khoá thì trả rỗng', empty( $tay_de['vao'] ) && empty( $tay_de['ra'] ), $tay_de );

/* ---- Lô của máy chính: đếm RIÊNG số lượt bị giữ ---- */
/* ⚠️ GÁN MÁY VÀO CƠ SỞ TRƯỚC. Máy chưa gán thì mọi lượt rơi vào `choGan` và không lượt nào chạm
   tới bảng chấm công — phép thử sẽ đo một cái lô rỗng và kết luận sai về chốt. */
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'DE-MAY', 'mac' => '',
	'cua_hang' => $D_CS2 ) );
/* "Trùng" là gói lặp, chuyện thường, không ai cần biết. "Giữ tay" nghĩa là máy vừa MUỐN đè lên
   một quyết định của người và bị chặn — gộp vào một con số là không ai đi tìm. */
/* ⚠️ Đi qua ĐÚNG CỬA THẬT: `vhcc_may_gui()` dựng cả phương thức, đường dẫn, khoá và thân gói —
   gọi thẳng `phuc_vu()` là nó đọc `$_SERVER` của lượt trước và trả `null`. */
list( , $lo_de ) = vhcc_may_gui( array(
	'logs' => array(
		array( 'hikSerial' => 'DE-MAY', 'station' => $D_CS2, 'employeeNo' => 'DE1',
			'name' => 'Người DE1', 'time' => '2026-07-06 23:00:00' ),
		array( 'hikSerial' => 'DE-MAY', 'station' => $D_CS2, 'employeeNo' => 'DE1',
			'name' => 'Người DE1', 'time' => '2026-07-08 08:05:00' ),
	),
) );
t( 'dựng cảnh: cổng nhận được lô', is_array( $lo_de ) && ! empty( $lo_de['lo'] ), $lo_de );
teq( '🔴 lô kể riêng số lượt bị giữ vì ô đã có người sửa', 1, $lo_de['giuTay'] );
teq( 'và lượt trùng vẫn đếm riêng', 1, $lo_de['trung'] );

vhcc_dung_bang();

/* ======================================================================================
 *  70. MÃ TRÊN MÁY -> MÃ NHÂN SỰ THẬT — chỗ dữ liệu máy sẽ rơi hết nếu không có
 *
 *  Anh Thắng 27/08/2026: *"bắt đầu kết nối máy chấm công để tránh mất dữ liệu"*.
 *
 *  🔴 HAI BỘ MÃ KHÁC HẲN NHAU. Máy ZKTeco ở xưởng trả `employeeNo` dạng `20000601` — mã do
 *     người dựng máy gõ vào từng đầu đọc, không ai đối chiếu với sổ nhân sự (hồ sơ ở đây dùng
 *     `MNNV1CTY0002`). Ghi thẳng mã máy vào bảng chấm công thì cả tháng công của cả xưởng nằm
 *     dưới một dãy số không có hồ sơ nào: bảng đầy số mà không số nào ra lương của ai.
 *     Ảnh phần mềm HR V5.2 anh gửi cho thấy đúng chuyện ấy — cột Họ tên trống trơn, mỗi dòng
 *     ghi "Chưa phân phòng", và có hẳn một nút tên là *"Phân nhân viên vào phòng / ghép mã NV"*.
 * ====================================================================================== */
vhcc_dung_bang();
$M_CS = 'MAY_CS';
vhcc_bo_phan( $M_CS, 'Khu vui chơi' );
$u_ma = array( 'role' => 'Admin', 'name' => 'Anh Admin', 'ma_nv' => 'MAAD' );
VHCC_NhanSu::luu_ho_so( $u_ma, array( 'ma_nv' => 'MNNV1CTY0002', 'ho_ten' => 'Huỳnh Quang Thắng',
	'cua_hang' => $M_CS, 'sdt' => '0900' ) );
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'ZK-LAPRAP', 'mac' => '', 'cua_hang' => $M_CS ) );

/* ---- Lõi dịch mã ---- */
/* Mã ĐÃ CÓ hồ sơ thì giữ nguyên — đừng đi tra một bảng ghép không liên quan. */
teq( 'mã đã có hồ sơ: giữ nguyên', 'MNNV1CTY0002', VHCC_NhanSu::ma_that( 'MNNV1CTY0002' ) );
/* 🔴 Chưa khai ghép thì TRẢ LẠI CHÍNH NÓ, không trả rỗng: lượt ấy vẫn phải vào bảng và vẫn
   được kể ở khối "chưa có hồ sơ". Mất một lượt bấm là mất công của người thật. */
teq( 'chưa khai ghép: trả lại chính mã máy', '20000601', VHCC_NhanSu::ma_that( '20000601' ) );
teq( 'mã rỗng: trả rỗng', '', VHCC_NhanSu::ma_that( '' ) );

VHCC_NhanSu::khai_ma_song_song( $u_ma, '20000601', 'MNNV1CTY0002', 'Huỳnh Quang Thắng',
	'mã trên máy Lắp Ráp' );
teq( '🔴 khai xong thì mã máy dịch ra mã nhân sự', 'MNNV1CTY0002',
	VHCC_NhanSu::ma_that( '20000601' ) );

/* ⚠️ KHÔNG CẦN QUY ƯỚC CHIỀU `ma_a`/`ma_b`. Bảng ấy không nói bên nào là mã máy, và bắt người
   khai nhớ đúng chiều là sớm muộn có dòng khai ngược — im lặng. Luật tự suy ra: mã đến mà đã có
   hồ sơ thì giữ; không có thì tìm đầu kia, và chỉ nhận nếu đầu kia CÓ hồ sơ. */
VHCC_NhanSu::luu_ho_so( $u_ma, array( 'ma_nv' => 'MNNV1CTY0009', 'ho_ten' => 'Người Chín',
	'cua_hang' => $M_CS, 'sdt' => '0900' ) );
VHCC_NhanSu::khai_ma_song_song( $u_ma, 'MNNV1CTY0009', '20000999', 'Người Chín', 'khai ngược chiều' );
teq( '🔴 khai NGƯỢC CHIỀU vẫn dịch đúng', 'MNNV1CTY0009', VHCC_NhanSu::ma_that( '20000999' ) );

/* 🔴 MÃ ĐÃ CÓ HỒ SƠ THÌ GIỮ NGUYÊN, đừng đi tra bảng ghép.
   Cảnh thật: một người đổi mã, mã CŨ vẫn còn hồ sơ và được khai song song với mã MỚI. Nếu cứ
   thấy có cặp là dịch thì mọi lượt chấm dưới mã này chui hết sang hồ sơ kia — cả hai đều là
   người thật, nên bảng vẫn đầy số và không ô nào đỏ. Đã phá thử để thấy: bỏ chốt mà bộ thử
   vẫn xanh, vì cảnh cũ chưa có ai mang hai mã cùng có hồ sơ. */
VHCC_NhanSu::luu_ho_so( $u_ma, array( 'ma_nv' => 'MNNV1CTY0055', 'ho_ten' => 'Người Năm Năm',
	'cua_hang' => $M_CS, 'sdt' => '0900' ) );
VHCC_NhanSu::luu_ho_so( $u_ma, array( 'ma_nv' => 'MNNV1CTY0056', 'ho_ten' => 'Người Năm Sáu',
	'cua_hang' => $M_CS, 'sdt' => '0900' ) );
VHCC_NhanSu::khai_ma_song_song( $u_ma, 'MNNV1CTY0055', 'MNNV1CTY0056', 'Cùng một người',
	'mã cũ và mã mới, cả hai còn hồ sơ' );
teq( '🔴 cả hai đầu đều có hồ sơ: KHÔNG dịch, giữ nguyên mã đến',
	'MNNV1CTY0055', VHCC_NhanSu::ma_that( 'MNNV1CTY0055' ) );
teq( 'và chiều kia cũng giữ nguyên', 'MNNV1CTY0056', VHCC_NhanSu::ma_that( 'MNNV1CTY0056' ) );

/* Cặp mà CẢ HAI đầu đều không có hồ sơ -> không dịch. Dịch bừa là ghi công vào một mã cũng
   chẳng ai nhận, chỉ khác chỗ. */
VHCC_NhanSu::khai_ma_song_song( $u_ma, '20001111', '20002222', 'Không rõ', 'cặp mồ côi' );
teq( 'cặp mà đầu kia cũng không có hồ sơ: giữ nguyên', '20001111',
	VHCC_NhanSu::ma_that( '20001111' ) );

/* ---- Cổng nhận: lượt từ máy vào ĐÚNG hồ sơ ---- */
list( , $lo_ma ) = vhcc_may_gui( array(
	'macAddress' => 'PC:MAY:CHINH', 'stationName' => 'May chinh',
	'logs' => array(
		array( 'hikSerial' => 'ZK-LAPRAP', 'employeeNo' => '20000601', 'name' => 'HQTHANG',
			'time' => '2026-08-26 06:27:01' ),
		array( 'hikSerial' => 'ZK-LAPRAP', 'employeeNo' => '20000601', 'name' => 'HQTHANG',
			'time' => '2026-08-26 17:05:00' ),
	),
) );
teq( 'cổng nhận đủ hai lượt', 2, $lo_ma['ghi'] );
$h_ma = vhcc_hang( $M_CS, '2026-08-26', 'MNNV1CTY0002' );
t( '🔴 lượt máy vào ĐÚNG hàng của mã nhân sự, không phải mã máy', null !== $h_ma, $h_ma );
t( 'và KHÔNG đẻ ra hàng mang mã máy',
	null === vhcc_hang( $M_CS, '2026-08-26', '20000601' ), 'còn hàng mã máy' );
/* 🔴 DỊCH MÃ THÌ LẤY LUÔN TÊN TỪ HỒ SƠ. Tên trên máy do người dựng máy gõ — viết tắt, không
   dấu, có khi chỉ là "NV601". Giữ tên ấy là bảng công hiện một cái tên mà sổ nhân sự không có,
   và người đọc bảng không nối được nó với ai. */
teq( '🔴 tên lấy từ HỒ SƠ, không lấy tên viết tắt trên máy', 'Huỳnh Quang Thắng',
	(string) $h_ma['ho_ten'] );

/* Chưa khai ghép thì lượt ấy VẪN VÀO BẢNG, mang mã máy — để còn thấy mà đi khai. */
list( , $lo_ma2 ) = vhcc_may_gui( array(
	'macAddress' => 'PC:MAY:CHINH',
	'logs' => array(
		array( 'hikSerial' => 'ZK-LAPRAP', 'employeeNo' => '20007777', 'name' => 'AI DO',
			'time' => '2026-08-26 07:00:00' ),
	),
) );
teq( 'lượt chưa khai ghép vẫn được ghi', 1, $lo_ma2['ghi'] );
t( '🔴 và nằm dưới chính mã máy, không biến mất',
	null !== vhcc_hang( $M_CS, '2026-08-26', '20007777' ), 'mất lượt' );

/* ⚠️ DỊCH NGAY TRƯỚC KHI GHI, không dịch sớm hơn: nhật ký của mấy nhánh trên (gói thử, giờ sai
   khuôn, máy chưa gán) phải kể ra ĐÚNG cái mã máy gửi lên — người đi soi nhật ký đang cầm cái
   máy trong tay chứ không cầm sổ nhân sự. */
vhcc_may_gui( array(
	'logs' => array(
		array( 'hikSerial' => 'ZK-LAPRAP', 'employeeNo' => '20000601', 'name' => 'HQTHANG',
			'time' => 'gio bay ba' ),
	),
) );
/* ⚠️ Nhật ký cổng nằm trong `option`, không phải một bảng — đọc đúng chỗ nó ở. */
$nk_ma = (array) get_option( 'vhcc_nhat_ky_may', array() );
$nk_dong = '';
foreach ( $nk_ma as $x_nk ) {
	if ( 'GIO_SAI_KHUON' === $x_nk['ma'] ) { $nk_dong = (string) $x_nk['loi']; break; }
}
t( 'dựng cảnh: có dòng nhật ký giờ sai khuôn', '' !== $nk_dong, $nk_ma );
t( '🔴 nhật ký kể ĐÚNG mã máy, không kể mã nhân sự đã dịch',
	strpos( $nk_dong, '20000601' ) !== false && strpos( $nk_dong, 'MNNV1CTY0002' ) === false, $nk_dong );

/* ---- Màn chẩn đoán: cổng đang ở trạng thái nào ---- */
/* 🔴 Anh Thắng 27/08/2026, kèm ảnh màn Máy & Firmware: khoá đã cấu hình, "Chưa có máy nào", và
   nhật ký chỉ ba dòng `GET_VAO_CONG_MAY`. Người nhìn màn ấy kết luận sai gần như chắc chắn —
   "chắc firmware chưa nạp" — trong khi cổng còn mấy trạng thái khác trông y hệt từ bên ngoài mà
   chữa thì mỗi cái một đường. */
/* ⚠️ Khối này phải chạy SAU mấy phép thử cổng ở trên, và dựng lại bảng SẠCH cho riêng nó: ba
   trạng thái cần canh đều là trạng thái "chưa có gì", mà khối trên vừa đẩy dữ liệu thật vào.
   Đặt nó TRƯỚC khối kia thì `vhcc_dung_bang()` xoá mất cảnh của khối kia — đã vấp đúng vậy. */
vhcc_dung_bang();
delete_option( 'vhcc_nhat_ky_may' );
$M_CS2 = 'CD_CS';
vhcc_bo_phan( $M_CS2, 'Khu vui chơi' );
$tok_cd = VHCC_Auth::phat_token( 'Anh Quản Trị', 'Admin', '', 'CDAD' );
/* ⚠️ CẮT ĐÚNG KHỐI RỒI HÃY SOI. Cả màn này có mấy chỗ khác cũng in địa chỉ cổng (khối "Cổng
   nhận chấm công từ máy") và cũng in mốc giờ (bảng nhật ký). Soi cả trang thì phép thử bắt
   nhầm chuỗi ở khối khác, và vết phá đúng chỗ vẫn xanh — đã vấp đúng vậy. */
function vp_khoi_cd( $h ) {
	$i = strpos( $h, 'id="chandoan"' );
	if ( false === $i ) { return ''; }
	$j = strpos( $h, '<div class="the"', $i + 10 );
	return false === $j ? substr( $h, $i ) : substr( $h, $i, $j - $i );
}

$h_cd = vp_khoi_cd( vhcc_hr( $tok_cd, array( 'man' => 'may' ) ) );
t( 'có khối chẩn đoán', strpos( $h_cd, 'Cổng đang ở trạng thái nào' ) !== false, $h_cd );
t( '🔴 chưa gì cả: nói CỔNG CHƯA NHẬN ĐƯỢC LƯỢT NÀO',
	strpos( $h_cd, 'Cổng chưa nhận được lượt chấm công nào' ) !== false, $h_cd );
/* Nhật ký trống trơn = gói chưa ra khỏi cửa hàng. Khác hẳn "có gói mà hỏng". */
t( 'và nói rõ nhật ký trống nghĩa là gói chưa ra khỏi cửa hàng',
	strpos( $h_cd, 'chưa có lượt nào chạm tới cổng' ) !== false, $h_cd );

/* Có lượt GET -> nói ra HAI cách đọc và cách phân biệt, đừng chọn hộ: chính người quản trị mở
   địa chỉ ấy bằng trình duyệt cũng sinh ra đúng dòng ấy. */
vhcc_may_gui( array( 'logs' => array() ), 'khoa-thu-nghiem-123', 'GET' );
$h_cd = vp_khoi_cd( vhcc_hr( $tok_cd, array( 'man' => 'may' ) ) );
t( '🔴 có lượt GET thì kể ra', strpos( $h_cd, 'lượt GET</b> vào cổng' ) !== false, $h_cd );
t( 'nói cách đọc thứ nhất: người mở tay bằng trình duyệt',
	strpos( $h_cd, 'mở địa chỉ ấy bằng' ) !== false, $h_cd );
t( '🔴 và cách đọc thứ hai: firmware bị CHUYỂN HƯỚNG, mất trọn thân gói',
	strpos( $h_cd, 'mất trọn' ) !== false && strpos( $h_cd, 'chuyển hướng' ) !== false, $h_cd );
t( 'kèm cách phân biệt bằng NHỊP (rải rác vs dày đặc)',
	strpos( $h_cd, 'dày đặc' ) !== false, $h_cd );
/* Chỉ đường chữa: địa chỉ nạp vào máy phải đúng dạng. */
/* 🔴 CHỈ CHỖ CHỮA THÌ PHẢI CHỈ ĐỦ: đúng địa chỉ nào, và cấm cái gì. Câu "địa chỉ phải đúng
   dạng" không chữa được gì cho người đang cầm cái máy — họ cần đọc thấy chuỗi để dán vào. */
t( 'và chỉ đúng chỗ chữa: kể ra ĐÚNG địa chỉ cổng, và cấm dấu gạch chéo cuối',
	strpos( $h_cd, esc_html( home_url( '/' . VHCC_Nhan::DUONG ) ) ) !== false
	&& strpos( $h_cd, 'không thừa dấu' ) !== false
	&& strpos( $h_cd, '<code>/</code> cuối' ) !== false, $h_cd );

/* ⚠️ ĐẾM PHẢI ĐÚNG LOẠI DÒNG. Nhật ký cổng chứa đủ thứ: giờ sai khuôn, máy chưa gán, sai khoá.
   Đếm bừa cả nhật ký thành "lượt GET" là vẽ ra một cơn hỏng không có thật, rồi người ta đi
   sửa địa chỉ nạp máy trong khi địa chỉ vốn đúng. */
/* ⚠️ Sổ này MỚI NHẤT ĐỨNG ĐẦU (`ghi_loi` dùng `array_unshift`) — dựng cảnh ngược thứ tự là
   phép thử canh nhầm mốc, mà vẫn xanh. */
update_option( 'vhcc_nhat_ky_may', array(
	array( 'luc' => '2026-08-27 08:03:00', 'dau' => '2026-08-27 08:03:00', 'lan' => 1,
		'ma' => 'GET_VAO_CONG_MAY', 'loi' => '' ),
	array( 'luc' => '2026-08-27 08:02:00', 'ma' => 'MAY_CHUA_GAN', 'loi' => 'chua gan co so' ),
	array( 'luc' => '2026-08-27 08:01:00', 'ma' => 'GIO_SAI_KHUON', 'loi' => 'gio bay ba' ),
	array( 'luc' => '2026-08-27 08:00:00', 'dau' => '2026-08-27 08:00:00', 'lan' => 1,
		'ma' => 'GET_VAO_CONG_MAY', 'loi' => '' ),
) );
$h_cd = vp_khoi_cd( vhcc_hr( $tok_cd, array( 'man' => 'may' ) ) );
t( '🔴 đếm ĐÚNG 2 lượt GET, không đếm cả 4 dòng nhật ký',
	strpos( $h_cd, '<b>2 lượt GET</b>' ) !== false
	&& strpos( $h_cd, '<b>4 lượt GET</b>' ) === false, $h_cd );
t( 'và kể mốc GET gần nhất để còn soi nhịp',
	strpos( $h_cd, '2026-08-27 08:03:00' ) !== false, $h_cd );
t( 'thưa thì nói là thưa, không doạ người ta',
	strpos( $h_cd, 'nhiều khả năng là người mở tay' ) !== false, $h_cd );

/* 🔴 MỘT DÒNG GỘP CÓ THỂ LÀ HÀNG NGHÌN LƯỢT. `ghi_loi` gộp dòng liên tiếp giống hệt nhau để một
   máy hỏng cấu hình khỏi đẩy văng cả sổ 200 dòng. Đếm số DÒNG thay vì cộng `lan` là đọc "một
   máy đang bắn 40 phát mỗi giờ" thành "có một lượt lẻ". */
update_option( 'vhcc_nhat_ky_may', array(
	array( 'luc' => '2026-08-27 09:00:00', 'dau' => '2026-08-27 08:00:00', 'lan' => 40,
		'ma' => 'GET_VAO_CONG_MAY', 'loi' => '' ),
) );
$h_cd = vp_khoi_cd( vhcc_hr( $tok_cd, array( 'man' => 'may' ) ) );
t( '🔴 dòng gộp: cộng theo `lan`, không đếm số dòng',
	strpos( $h_cd, '<b>40 lượt GET</b>' ) !== false
	&& strpos( $h_cd, '<b>1 lượt GET</b>' ) === false, $h_cd );
t( '🔴 và ĐỌC HỘ cái nhịp: dày như vậy là firmware, không phải người bấm tay',
	strpos( $h_cd, 'giống firmware' ) !== false, $h_cd );
t( 'kèm khoảng cách trung bình, để còn cãi lại được',
	strpos( $h_cd, 'trung bình mỗi' ) !== false, $h_cd );
t( 'và nói ra NGƯỠNG đã dùng, chứ không phán trống không',
	strpos( $h_cd, 'Ngưỡng đang dùng' ) !== false, $h_cd );

/* 🔴 SAI KHOÁ LÀ CÂU TRẢ LỜI DỨT KHOÁT, VÀ PHẢI ĐỨNG TRƯỚC MỌI THỨ KHÁC. Nó trả lời đúng câu
   hỏi đắt nhất của màn này — "máy có chạy không" — và câu trả lời là CÓ: gói đã đi hết quãng
   đường từ cửa hàng về tới PHP. Để nó lẫn xuống dưới mấy khả năng "chưa nạp firmware" là chỉ
   người ta đi sai đường, mà đường ấy dài mấy ngày. */
update_option( 'vhcc_nhat_ky_may', array(
	array( 'luc' => '2026-08-27 09:00:00', 'dau' => '2026-08-27 08:00:00', 'lan' => 12,
		'ma' => 'SAI_KHOA', 'loi' => 'gói tới được cổng và CÓ mang khoá, nhưng không khớp' ),
	array( 'luc' => '2026-08-27 07:00:00', 'dau' => '2026-08-27 07:00:00', 'lan' => 3,
		'ma' => 'GET_VAO_CONG_MAY', 'loi' => '' ),
) );
$h_cd = vp_khoi_cd( vhcc_hr( $tok_cd, array( 'man' => 'may' ) ) );
t( '🔴 có sai khoá: nói TÌM RA RỒI, kèm số lượt',
	strpos( $h_cd, 'SAI KHOÁ' ) !== false && strpos( $h_cd, '12 lượt' ) !== false, $h_cd );
t( '🔴 và nói thẳng: máy VẪN CHẠY, đừng đi sửa ESP32',
	strpos( $h_cd, 'máy vẫn chạy và vẫn tới được cổng' ) !== false
	&& strpos( $h_cd, 'Không phải đi sửa ESP32' ) !== false, $h_cd );
t( 'kể lại đúng lời nhật ký, để biết hỏng kiểu gì',
	strpos( $h_cd, 'nhưng không khớp' ) !== false, $h_cd );
t( 'kèm lần đầu và lần gần nhất', strpos( $h_cd, '2026-08-27 08:00:00' ) !== false
	&& strpos( $h_cd, '2026-08-27 09:00:00' ) !== false, $h_cd );
/* ⚠️ VÀ TRẤN AN ĐÚNG CHỖ: lượt bấm chưa mất, còn nằm trong đầu đọc. Không nói thì người ta
   tưởng mất trắng mấy ngày công rồi đi khai tay cả bảng. */
t( 'nói rõ lượt bấm CHƯA MẤT, lấy lại được bằng lệnh Tải lại',
	strpos( $h_cd, 'Tải lại' ) !== false && strpos( $h_cd, 'chưa mất gì cả' ) !== false, $h_cd );
/* 🔴 Và ĐỪNG chỉ sang đường GET nữa — có sai khoá thì mấy lượt GET kia là chuyện phụ. */
t( '🔴 thôi chỉ đường chuyển hướng: đã có câu trả lời chắc chắn hơn',
	strpos( $h_cd, 'Hai cách đọc' ) === false, $h_cd );

/* Có dữ liệu thật RỒI mà vẫn còn máy sai khoá: 25 cửa hàng xanh không cứu được cửa hàng thứ 26. */
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'CD-MAY0', 'mac' => '', 'cua_hang' => $M_CS2 ) );
$h_cd = vp_khoi_cd( vhcc_hr( $tok_cd, array( 'man' => 'may' ) ) );
t( '🔴 đã có máy chạy nhưng còn máy sai khoá: vẫn phải kêu lên',
	strpos( $h_cd, 'Cổng ĐÃ nhận được dữ liệu thật' ) !== false
	&& strpos( $h_cd, 'bị chối vì SAI KHOÁ' ) !== false, $h_cd );
t( 'và nói rõ máy lẻ ấy đang KHÔNG lên được lượt nào',
	strpos( $h_cd, 'KHÔNG lên được lượt nào' ) !== false, $h_cd );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'may' ) . " WHERE serial = 'CD-MAY0'" );
/* Dựng lại cảnh CHỈ có lượt GET cho mấy phép thử dưới — bỏ hết dòng sai khoá. */
update_option( 'vhcc_nhat_ky_may', array(
	array( 'luc' => '2026-08-27 07:02:00', 'dau' => '2026-08-27 07:00:00', 'lan' => 3,
		'ma' => 'GET_VAO_CONG_MAY', 'loi' => '' ),
) );

/* 🔴 BẰNG CHỨNG DUY NHẤT ĐÁNG TIN LÀ BẢNG MÁY — anh Thắng 28/08/2026, ảnh chụp bản 2.74.0.
   Màn ấy báo "✓ Cổng ĐÃ nhận được dữ liệu thật. 0 máy đã tự hiện ra · 1 hàng chấm công mang
   nguồn máy", rồi ngay khối dưới lại nói "Chưa có máy nào". Hai câu mâu thuẫn trên cùng một
   màn, và câu XANH là câu sai — cổng chưa hề nhận được gì.

   Hàng trong bảng `may` chỉ sinh ra ở `ghi_nhan_may()`, tức là chỉ khi một gói POST hợp lệ đã
   đi trọn đường và qua được cửa khoá. Một hàng chấm công lẻ thì không: nó vào được bằng đường
   kéo về, nạp .csv, hay chuyển từ hệ cũ sang.

   ⚠️ Báo xanh nhầm ở đây đắt hơn báo đỏ nhầm nhiều: nó TẮT sạch mọi lời chỉ đường bên dưới,
      đúng lúc người ta mở màn này ra vì đang không biết đi đâu. */
$wpdb->insert( VHCC_DB::t( 'cham_cong' ), array(
	'coso' => $M_CS2, 'ngay' => '2026-08-27', 'ma_nv' => 'CDNV0001',
	'ho_ten' => 'Người Thử', 'gio_vao_giay' => 28800, 'gio_ra_giay' => 61200,
	'nguon' => 'may',
) );
$h_cd = vp_khoi_cd( vhcc_hr( $tok_cd, array( 'man' => 'may' ) ) );
t( '🔴 hàng công nguồn máy mà bảng máy TRỐNG: KHÔNG được báo đã nhận được dữ liệu thật',
	strpos( $h_cd, 'Cổng ĐÃ nhận được dữ liệu thật' ) === false, $h_cd );
t( '🔴 và vẫn chỉ đường như thường, đừng tắt hết',
	strpos( $h_cd, 'Cổng chưa nhận được lượt chấm công nào' ) !== false, $h_cd );
/* Vẫn phải KỂ RA con số ấy — giấu đi thì người đọc thấy nó ở màn Bảng công rồi tưởng đếm sai. */
t( 'nhưng có kể ra con số, kèm lý do vì sao không tính',
	strpos( $h_cd, 'không máy nào từng qua được cổng' ) !== false
	&& strpos( $h_cd, 'nạp <code>.csv</code>' ) !== false, $h_cd );

/* 🔴 `hon-hop` KHÔNG PHẢI BẰNG CHỨNG. Nó chỉ có nghĩa "hàng này có từ hai nguồn khác nhau" —
   chấm online rồi sửa tay cũng thành `hon-hop`, chẳng dính gì tới máy. Đếm nó là đếm khống. */
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'cham_cong' ) . " WHERE ma_nv = 'CDNV0001'" );
$wpdb->insert( VHCC_DB::t( 'cham_cong' ), array(
	'coso' => $M_CS2, 'ngay' => '2026-08-27', 'ma_nv' => 'CDNV0002',
	'ho_ten' => 'Người Thử Hai', 'gio_vao_giay' => 28800, 'gio_ra_giay' => 61200,
	'nguon' => 'hon-hop',
) );
$h_cd = vp_khoi_cd( vhcc_hr( $tok_cd, array( 'man' => 'may' ) ) );
t( '🔴 hàng `hon-hop` KHÔNG được tính là lượt của máy',
	strpos( $h_cd, 'Cổng ĐÃ nhận được dữ liệu thật' ) === false
	&& strpos( $h_cd, 'hàng chấm công mang nguồn' ) === false, $h_cd );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'cham_cong' ) . " WHERE ma_nv = 'CDNV0002'" );

/* Có dữ liệu THẬT rồi thì đổi giọng hẳn — đừng doạ người ta khi mọi thứ đang chạy. */
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'CD-MAY', 'mac' => '', 'cua_hang' => $M_CS2 ) );
$h_cd = vp_khoi_cd( vhcc_hr( $tok_cd, array( 'man' => 'may' ) ) );
t( '🔴 có máy rồi thì báo ĐÃ NHẬN ĐƯỢC dữ liệu thật',
	strpos( $h_cd, 'Cổng ĐÃ nhận được dữ liệu thật' ) !== false, $h_cd );
t( 'và thôi kêu chưa nhận được gì',
	strpos( $h_cd, 'Cổng chưa nhận được lượt chấm công nào' ) === false, $h_cd );
/* Mấy lượt GET lẫn vào lúc ấy chỉ là ghi chú, không phải cảnh báo. */
t( 'lượt GET lúc này chỉ là ghi chú', strpos( $h_cd, 'Chỉ đáng lo nếu' ) !== false, $h_cd );

/* 🔴 BẢNG NHẬT KÝ PHẢI HIỆN SỐ LẦN. Từ 2.75.0 một DÒNG ở đó có thể là hàng nghìn lượt đã gộp
   lại; giấu con số ấy đi là biến "một máy đang bắn 40 phát mỗi giờ" thành "có một lượt lẻ". */
update_option( 'vhcc_nhat_ky_may', array(
	array( 'luc' => '2026-08-27 09:00:00', 'dau' => '2026-08-27 08:00:00', 'lan' => 40,
		'ma' => 'SAI_KHOA', 'loi' => 'khoa khong khop' ),
) );
$h_nk = vhcc_hr( $tok_cd, array( 'man' => 'may' ) );
t( '🔴 bảng nhật ký hiện SỐ LẦN của dòng gộp',
	strpos( $h_nk, '<b>×40</b>' ) !== false, $h_nk );
t( 'và hiện cả mốc lần đầu, để đọc được quãng',
	strpos( $h_nk, 'từ 2026-08-27 08:00:00' ) !== false, $h_nk );
delete_option( 'vhcc_nhat_ky_may' );

vhcc_dung_bang();

/* ⚠️ KHỐI NÀY DỰNG LẠI BẢNG SẠCH, NÊN PHẢI ĐỨNG CUỐI. Đặt nó giữa file thì
   `vhcc_dung_bang()` của nó xoá cảnh của mọi khối bên dưới — đã vấp đúng vậy: 14 phép
   thử của khối vai trò và khối ghép mã cùng đỏ một lượt, mà lỗi thì nằm ở đây. */
/* ---- CỬA HÀNG TRƯỞNG XEM FULL THÁNG NHÂN VIÊN CÙNG CƠ SỞ ----------------------------------
   Anh Thắng 28/08/2026: *"cửa hàng trưởng sẽ xem được full tháng của nhân viên tại cửa hàng
   đang cùng cơ sở"*, rồi *"hiện tại chưa xem được"*. */
vhcc_dung_bang();
vhcc_bo_phan( 'CHT_CS', 'Khu vui chơi' );
vhcc_bo_phan( 'CHT_CS2', 'Khu vui chơi' );
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CHTNV1', 'ho_ten' => 'Nhân Viên Cùng Chỗ',
	'cua_hang' => 'CHT_CS' ) );
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CHTNV2', 'ho_ten' => 'Người Cơ Sở Khác',
	'cua_hang' => 'CHT_CS2' ) );
vhcc_may_gui( vhcc_goi( 'CHTNV1', '2026-08-03 08:00:00', 'CHT_CS' ) );
vhcc_may_gui( vhcc_goi( 'CHTNV1', '2026-08-03 17:30:00', 'CHT_CS' ) );
vhcc_may_gui( vhcc_goi( 'CHTNV2', '2026-08-03 08:00:00', 'CHT_CS2' ) );

$tok_cht = VHCC_Auth::phat_token( 'Chị Cửa Hàng Trưởng', 'Cửa hàng trưởng', 'CHT_CS', 'CHTSEP' );
$h_cht   = vhcc_hr( $tok_cht, array( 'man' => 'cham', 'ccs' => 'CHT_CS', 'cth' => '2026-08' ) );
t( '🔴 Cửa hàng trưởng có tab Bảng công', strpos( $h_cht, 'Bảng công' ) !== false, $h_cht );
t( '🔴 và thấy CẢ THÁNG của nhân viên cùng cơ sở',
	strpos( $h_cht, 'Nhân Viên Cùng Chỗ' ) !== false, $h_cht );
t( 'kèm lưới cả tháng', strpos( $h_cht, 'LƯỚI CẢ THÁNG' ) !== false
	|| strpos( $h_cht, 'Lưới cả tháng' ) !== false, $h_cht );
/* ⚠️ NHƯNG CHỈ CƠ SỞ MÌNH. Cửa hàng trưởng không phải quản lý chuỗi. */
$h_cht2 = vhcc_hr( $tok_cht, array( 'man' => 'cham', 'ccs' => 'CHT_CS2', 'cth' => '2026-08' ) );
t( '🔴 nhưng KHÔNG xem được cơ sở khác',
	strpos( $h_cht2, 'Người Cơ Sở Khác' ) === false, $h_cht2 );

/* ---- HỒ SƠ GHI MỘT VAI, PHIÊN LẠI MANG VAI KHÁC -------------------------------------------
   🔴 Đây là gốc của chuyện trên: hồ sơ chị Mỹ Tiên ghi Cửa hàng trưởng, mà thẻ phiên mang
      Nhân viên — nên cột dọc thiếu tab Bảng công, và không có gì báo. Vai lúc đăng nhập đọc từ
      NGUỒN NGƯỜI DÙNG; nguồn không phải `ho_so` thì đổi vai trong hồ sơ chẳng đi tới đâu. */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'LECH1', 'ho_ten' => 'Người Bị Lệch Vai',
	'cua_hang' => 'CHT_CS' ) );
VHCC_NhanSu::dat_vai_tro( $U_AD, 'LECH1', 'Cửa hàng trưởng' );
$tok_lech = VHCC_Auth::phat_token( 'Người Bị Lệch Vai', 'Nhân viên', 'CHT_CS', 'LECH1' );
$h_lech = vhcc_hr( $tok_lech, array( 'man' => 'cong_toi' ) );
t( '🔴 màn hình nói ngay là hồ sơ ghi vai khác',
	strpos( $h_lech, 'Hồ sơ của anh/chị ghi vai' ) !== false, $h_lech );
t( 'gọi đúng cả hai vai',
	strpos( $h_lech, 'Cửa hàng trưởng' ) !== false && strpos( $h_lech, 'Nhân viên' ) !== false, $h_lech );
/* ⚠️ Nói rõ HẬU QUẢ đang xảy ra, không chỉ "có gì đó lệch". */
t( 'và nói màn hình đang THIẾU mục của vai kia',
	strpos( $h_lech, 'đang thiếu những mục' ) !== false, $h_lech );

/* 🔴 CHỖ CHỮA PHẢI ĐÚNG THẬT, KHÔNG PHẢI "CẤU HÌNH → NGUỒN NGƯỜI DÙNG".
   Anh Thắng 29/08/2026, sau khi làm đúng theo câu chỉ dẫn CŨ mà vẫn *"chưa qua, nên phân quyền
   vẫn thấy là nhân viên"*: câu cũ trỏ sang tab Cấu hình của TRANG NÀY (`man=cau_hinh`), mà tab
   đó KHÔNG CÓ ô Nguồn người dùng nào — mục thật nằm ở tab Hồ sơ & tài khoản (`man=ho_so`), khối
   🔑 Tài khoản đăng nhập. Đi tìm một ô không tồn tại thì "chưa qua" là đúng, không phải anh thao
   tác sai. Phép thử này canh KHÔNG ĐƯỢC lặp lại đường trỏ sai đó. */
t( '🔴 KHÔNG còn trỏ sang tab Cấu hình (ô đó không tồn tại ở đó)',
	strpos( $h_lech, 'man=cau_hinh' ) === false, $h_lech );
t( '🔴 mà trỏ ĐÚNG sang tab Hồ sơ & tài khoản, khối 🔑 Tài khoản đăng nhập',
	strpos( $h_lech, 'man=ho_so' ) !== false && strpos( $h_lech, 'Tài khoản đăng nhập' ) !== false
	&& strpos( $h_lech, 'hồ sơ nhân sự' ) !== false, $h_lech );
/* ⚠️ Và nói rõ vì sao đổi vai trong hồ sơ lại chưa ăn — không thì người ta đổi vai lần nữa. */
t( 'nói rõ vai lúc đăng nhập đọc từ Nguồn người dùng',
	strpos( $h_lech, 'Vai lúc đăng nhập đọc từ' ) !== false, $h_lech );
t( 'và bảo đăng nhập lại sau khi đổi',
	strpos( $h_lech, 'đăng nhập lại' ) !== false, $h_lech );

/* ---- 🔴 NHÁNH THỨ HAI: NGUỒN ĐÃ ĐÚNG LÀ HỒ SƠ, LỆCH CHỈ VÌ PHIÊN CŨ ------------------------
   Đổi nguồn không giải quyết được gì nếu nguồn đã đúng sẵn — nói "đổi nguồn" trong ca này là
   chỉ đường tới một việc vô nghĩa. Chỗ lệch thật là phiên đăng nhập cũ, phát trước khi vai trong
   hồ sơ được sửa; cách chữa đúng là đăng xuất rồi vào lại, không phải đổi cấu hình. */
$vth_nguon_cu2 = get_option( 'vhcc_nguon_nguoidung' );
update_option( 'vhcc_nguon_nguoidung', 'ho_so' );
$h_lech2 = vhcc_hr( $tok_lech, array( 'man' => 'cong_toi' ) );
t( '🔴 nguồn ĐÃ đúng là hồ sơ: KHÔNG bảo đi đổi nguồn nữa (đổi cái đã đúng là vô nghĩa)',
	strpos( $h_lech2, 'Nhờ Admin vào tab' ) === false, $h_lech2 );
t( 'mà nói đúng nguyên nhân thật: phiên đăng nhập cũ, không phải cấu hình',
	strpos( $h_lech2, 'phiên đăng nhập cũ' ) !== false, $h_lech2 );
t( 'và bảo đúng cách chữa: thoát rồi đăng nhập lại',
	strpos( $h_lech2, 'Thoát' ) !== false && strpos( $h_lech2, 'đăng nhập lại' ) !== false, $h_lech2 );
update_option( 'vhcc_nguon_nguoidung', $vth_nguon_cu2 );

/* Vai phiên CAO hơn hồ sơ cũng là lệch, nhưng hậu quả ngược — nói đúng cái đang xảy ra. */
$tok_cao = VHCC_Auth::phat_token( 'Người Bị Lệch Vai', 'Quản lý', 'CHT_CS', 'LECH1' );
$h_cao = vhcc_hr( $tok_cao, array( 'man' => 'cong_toi' ) );
t( 'phiên cao hơn hồ sơ: nói là đang MỞ RỘNG hơn',
	strpos( $h_cao, 'mở rộng hơn' ) !== false, $h_cao );

/* 🔴 KHỚP BẬC THÌ IM. So TÊN vai thì "Kế toán" với "Kế toán cá nhân" thành lệch, mà hai cái ấy
   cùng bậc — kêu lên là báo động giả, và báo động giả thì người ta tắt đi. */
/* ⚠️ "Kế toán" TRẦN không có trong `VHCC_Auth::VAI_TRO_TAT_CA` nên `dat_vai_tro()` chối nó —
   dựng cảnh bằng tên ấy là hồ sơ không đổi, và phép thử đo nhầm một cảnh khác. Dùng hai tên
   THẬT khác nhau mà cùng bậc: "Kế toán cá nhân" và "Kế toán NCC". */
$r_kt2 = VHCC_NhanSu::dat_vai_tro( $U_AD, 'LECH1', 'Kế toán cá nhân' );
t( 'dựng cảnh: đổi được vai sang Kế toán cá nhân', ! empty( $r_kt2['ok'] ), $r_kt2 );
$tok_kt2 = VHCC_Auth::phat_token( 'Người Bị Lệch Vai', 'Kế toán NCC', 'CHT_CS', 'LECH1' );
$h_kt2 = vhcc_hr( $tok_kt2, array( 'man' => 'cong_toi' ) );
t( '🔴 hai tên khác nhau mà CÙNG BẬC thì KHÔNG kêu',
	strpos( $h_kt2, 'Hồ sơ của anh/chị ghi vai' ) === false, $h_kt2 );
/* 🔴 KHÔNG CÓ MÃ NV THÌ KHÔNG ĐỐI CHIẾU ĐƯỢC — VÀ SỔ CÓ HỒ SƠ MÃ RỖNG LÀ CHUYỆN THẬT
   (nạp .csv thiếu cột, tạo hồ sơ dở dang). Bỏ chốt mã rỗng thì `ho_so('')` móc đúng cái hồ sơ
   ấy ra, rồi đem vai của nó so với MỌI người chưa có mã — kêu bừa cho cả một đám người, mà
   không ai trong số đó sửa được gì. */
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => '', 'ho_ten' => 'Hồ Sơ Dở Dang',
	'vai_tro' => 'Admin', 'cua_hang' => 'CHT_CS' ) );
$tok_khong = VHCC_Auth::phat_token( 'Ai Đó', 'Nhân viên', 'CHT_CS', '' );
$h_khong = vhcc_hr( $tok_khong, array( 'man' => 'cong_toi' ) );
t( '🔴 không có Mã NV thì không kêu, dù sổ có hồ sơ mã rỗng mang vai khác',
	strpos( $h_khong, 'Hồ sơ của anh/chị ghi vai' ) === false, $h_khong );

vhcc_dung_bang();

/* ---- LẤY LẠI PIN BẰNG HỌ TÊN + CĂN CƯỚC ---------------------------------------------------
   Anh Thắng 28/08/2026: *"Thiếu phần lấy lại mã PIN ( Để lấy lại mã PIN nhập Họ Tên và số Căn
   Cước Công Dân )"*, chốt phạm vi: MỌI VAI, kể cả Admin.

   🔴 KHÔNG HIỆN PIN CŨ — luật của trang này từ đầu: trang chạy ngoài internet, ảnh chụp màn
      hình đi khắp nơi. "Lấy lại" ở đây là khớp danh tính rồi cho ĐẶT PIN MỚI.
   🔴 VÀ HỌ TÊN + CCCD LÀ DANH TÍNH, KHÔNG PHẢI BÍ MẬT. Họ tên công khai, CCCD lộ khắp nơi. Anh
      Thắng biết và chọn vậy — nên mấy chốt dưới đây là thứ DUY NHẤT còn lại. */
vhcc_dung_bang();
delete_option( VHCC_QuenPin::O_NHAT_KY );
VHCC_QuenPin::mo_khoa();
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'QP1', 'ho_ten' => 'Lê Thị Hồng Trinh',
	'vai_tro' => 'Admin', 'cua_hang' => 'TUTU_BT', 'cccd' => '079123456789',
	'pin_dang_nhap' => '334400' ) );

teq( 'dựng cảnh: có hồ sơ khai CCCD', 1, VHCC_QuenPin::so_co_cccd() );

/* Bước 1: khớp danh tính. Tên so bằng khoá BỎ DẤU, CCCD so bằng chữ số — bắt gõ đúng từng dấu
   là không ai qua nổi, còn CCCD thì người ta hay chèn khoảng trắng. */
$qp = VHCC_QuenPin::tra( 'le thi hong trinh', '079 123 456 789' );
t( '🔴 gõ không dấu và CCCD có khoảng trắng vẫn khớp', ! empty( $qp['ok'] ), $qp );
teq( 'và tra ra đúng người', 'QP1', (string) $qp['ma_nv'] );
t( 'phát thẻ cho bước 2', ! empty( $qp['the'] ), $qp );
/* 🔴 KHÔNG ĐƯỢC TRẢ PIN CŨ VỀ, DÙ CHỈ TRONG DỮ LIỆU. */
t( '🔴 kết quả tra KHÔNG mang PIN cũ',
	strpos( (string) wp_json_encode( $qp ), '334400' ) === false, $qp );

/* Bước 2: đặt PIN mới. */
$kq = VHCC_QuenPin::dat( $qp['the'], '778811' );
t( 'đặt được PIN mới', ! empty( $kq['ok'] ), $kq );
$hs_qp = VHCC_NhanSu::ho_so( 'QP1' );
teq( '🔴 PIN trong HỒ SƠ đã đổi — một nguồn, mọi trang đọc theo',
	'778811', (string) $hs_qp['pin_dang_nhap'] );

/* ⚠️ THẺ CHỈ SỐNG 5 PHÚT, VÀ KÝ CẢ MÃ LẪN HẠN. Ký mỗi mã thì thẻ sống mãi; ký mỗi hạn thì đổi
   mã trong thẻ là đặt lại PIN của người khác. */
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'QP2', 'ho_ten' => 'Người Khác',
	'vai_tro' => 'Nhân viên', 'cua_hang' => 'TUTU_BT', 'cccd' => '079999888777',
	'pin_dang_nhap' => '112233' ) );
$the_gia = 'QP2.' . ( time() + 300 ) . '.' . substr( (string) $qp['the'], strrpos( (string) $qp['the'], '.' ) + 1 );
$kq = VHCC_QuenPin::dat( $the_gia, '999000' );
t( '🔴 đổi mã trong thẻ mà giữ chữ ký cũ: bị chối', empty( $kq['ok'] ), $kq );
teq( 'và PIN người kia KHÔNG bị đụng', '112233',
	(string) VHCC_NhanSu::ho_so( 'QP2' )['pin_dang_nhap'] );

$the_het = 'QP1.' . ( time() - 10 ) . '.'
	. hash_hmac( 'sha256', 'QP1.' . ( time() - 10 ), wp_salt( 'auth' ) . '|vhcc-quen-pin' );
$kq = VHCC_QuenPin::dat( $the_het, '555000' );
t( '🔴 thẻ hết hạn thì chối', empty( $kq['ok'] ), $kq );
t( 'và nói rõ phải nhập lại họ tên + căn cước',
	strpos( (string) $kq['error'], 'hết hạn' ) !== false, $kq );

/* PIN trùng người khác = hai người chung một cửa: cổng tra theo PIN, ai gõ vào cũng rơi vào hồ
   sơ đứng trước, và người kia mất tài khoản mà không hiểu vì sao. */
$qp2 = VHCC_QuenPin::tra( 'Lê Thị Hồng Trinh', '079123456789' );
$kq  = VHCC_QuenPin::dat( $qp2['the'], '112233' );
t( '🔴 PIN trùng người khác: chối', empty( $kq['ok'] ), $kq );
t( 'và nói rõ vì sao', strpos( (string) $kq['error'], 'đã có người dùng' ) !== false, $kq );
/* PIN sai khuôn. */
$kq = VHCC_QuenPin::dat( $qp2['the'], '12' );
t( 'PIN dưới 4 chữ số: chối', empty( $kq['ok'] ), $kq );

/* 🔴 CÂU CHỐI GIỐNG NHAU CHO MỌI CA HỎNG. Nói "không có ai tên đó" khác với "tên đúng mà CCCD
   sai" là biến ô này thành máy dò xem một người có trong công ty hay không. */
VHCC_QuenPin::mo_khoa();
$a = VHCC_QuenPin::tra( 'Không Có Ai Tên Này', '111111111111' );
VHCC_QuenPin::mo_khoa();
$b = VHCC_QuenPin::tra( 'Lê Thị Hồng Trinh', '000000000000' );
teq( '🔴 tên lạ và CCCD sai cho ra ĐÚNG một câu chối', (string) $a['error'], (string) $b['error'] );

/* 🔴 HÃM DÒ. Không có nó thì quét CCCD là chuyện của một buổi chiều. */
VHCC_QuenPin::mo_khoa();
for ( $i_qp = 0; $i_qp < VHCC_QuenPin::SAI_TOI_DA; $i_qp++ ) {
	VHCC_QuenPin::tra( 'Ai Đó', '000000000' . $i_qp );
}
t( '🔴 sai quá số lần cho phép thì khoá', VHCC_QuenPin::bi_khoa() );
$kq = VHCC_QuenPin::tra( 'Lê Thị Hồng Trinh', '079123456789' );
t( 'và lúc bị khoá thì gõ ĐÚNG cũng không qua', empty( $kq['ok'] ), $kq );
t( 'câu chối nói rõ phải chờ', strpos( (string) $kq['error'], 'thử lại sau' ) !== false, $kq );

/* ⚠️ KHỚP RỒI THÌ XOÁ ĐẾM SAI — không thì người gõ nhầm hai lần rồi gõ đúng vẫn bị khoá ở lần
   sau, và hãm dò quay ra hãm chính người có quyền. */
VHCC_QuenPin::mo_khoa();
VHCC_QuenPin::tra( 'Ai Đó', '000000001' );
VHCC_QuenPin::tra( 'Ai Đó', '000000002' );
VHCC_QuenPin::tra( 'Lê Thị Hồng Trinh', '079123456789' );
for ( $i_qp = 0; $i_qp < VHCC_QuenPin::SAI_TOI_DA - 1; $i_qp++ ) {
	VHCC_QuenPin::tra( 'Ai Đó', '00000001' . $i_qp );
}
t( '🔴 tra khớp thì đếm sai về 0, không cộng dồn từ mấy lần gõ nhầm trước',
	! VHCC_QuenPin::bi_khoa() );

/* 🔴 HỒ SƠ CHƯA KHAI CCCD THÌ KHÔNG DÙNG ĐƯỢC ĐƯỜNG NÀY. Nhận hồ sơ CCCD rỗng là ai gõ đúng
   tên rồi để trống ô CCCD cũng qua. */
VHCC_QuenPin::mo_khoa();
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'QP3', 'ho_ten' => 'Chưa Khai Căn Cước',
	'vai_tro' => 'Nhân viên', 'cua_hang' => 'TUTU_BT', 'cccd' => '', 'pin_dang_nhap' => '445500' ) );
$kq = VHCC_QuenPin::tra( 'Chưa Khai Căn Cước', '' );
t( '🔴 CCCD để trống: chối', empty( $kq['ok'] ), $kq );

/* 🔴 NHẬT KÝ — đây là đường vào DUY NHẤT không cần biết PIN cũ. Không có sổ thì ngày ai đó
   dùng CCCD của người khác để chiếm tài khoản, không còn một dấu vết nào để lần. */
$nk_qp = VHCC_QuenPin::nhat_ky();
t( 'có ghi nhật ký mỗi lần đổi PIN qua đường này', count( $nk_qp ) >= 1, $nk_qp );
t( 'kể đúng người', 'QP1' === (string) $nk_qp[0]['ma_nv'], $nk_qp );
/* 🔴 VÀ KHÔNG GHI PIN VÀO SỔ. */
t( '🔴 nhật ký KHÔNG chứa PIN',
	strpos( (string) wp_json_encode( $nk_qp ), '778811' ) === false, $nk_qp );

/* ---- Trên MÀN ĐĂNG NHẬP ---- */
$h_qp = vhcc_hr( '', array() );
t( '🔴 màn đăng nhập có khối Quên PIN', strpos( $h_qp, 'Quên PIN?' ) !== false, $h_qp );
t( 'có ô họ tên và ô căn cước',
	strpos( $h_qp, 'name="qp_ten"' ) !== false && strpos( $h_qp, 'name="qp_cccd"' ) !== false, $h_qp );
t( '🔴 và nói thẳng là KHÔNG hiện PIN cũ',
	strpos( $h_qp, 'không hiện PIN cũ' ) !== false, $h_qp );
/* ⚠️ Màn đăng nhập TUYỆT ĐỐI không được rò một PIN nào ra. */
t( '🔴 màn đăng nhập không in PIN của ai',
	strpos( $h_qp, '778811' ) === false && strpos( $h_qp, '112233' ) === false, $h_qp );

/* 🔴 KHÔNG AI KHAI CCCD THÌ ĐƯỜNG NÀY VÔ DỤNG — NÓI RA, ĐỪNG BÀY Ô NHẬP.
   Bày ô ra rồi để người ta gõ đúng tên mình mà vẫn bị chối là kiểu tệ nhất: họ tin là mình gõ
   sai, gõ lại năm lần, rồi tự khoá mình mười phút. */
vhcc_dung_bang();
VHCC_QuenPin::mo_khoa();
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'QPX', 'ho_ten' => 'Không Có Căn Cước',
	'vai_tro' => 'Nhân viên', 'cua_hang' => 'TUTU_BT', 'cccd' => '', 'pin_dang_nhap' => '667700' ) );
teq( 'dựng cảnh: sổ không ai khai CCCD', 0, VHCC_QuenPin::so_co_cccd() );
$h_qp = vhcc_hr( '', array() );
t( '🔴 nói thẳng là chưa ai khai căn cước',
	strpos( $h_qp, 'Chưa hồ sơ nào khai' ) !== false, $h_qp );
t( '🔴 và KHÔNG bày ô nhập ra để người ta gõ vô ích',
	strpos( $h_qp, 'name="qp_ten"' ) === false, $h_qp );

vhcc_dung_bang();
VHCC_QuenPin::mo_khoa();
delete_option( VHCC_QuenPin::O_NHAT_KY );

/* ==========================================================================================
 * 🔴 HAI CLASS KHÁC NGHĨA TRÙNG TÊN — thanh bên `.canh` và thẻ cảnh báo `.bao canh`.
 * ==========================================================================================
 * Anh Thắng 28/08/2026 gửi ảnh khối cảnh báo cao vống gần hết màn hình: *"không có mã mà sao
 * ra rộng thế"*. Thẻ cảnh báo ăn phải `height:100vh` của thanh điều hướng bên, nên khối nào
 * cũng cao đúng một màn hình dù bên trong chỉ một dòng chữ.
 *
 * Lỗi CSS thì phép thử soi HTML không bắt được — nên soi thẳng bảng kiểu.
 */
$css_w = VHCC_Web::css();
t( '🔴 luật thanh bên buộc vào đúng thẻ <aside>, không phải mọi .canh',
	strpos( $css_w, 'aside.canh{position:sticky' ) !== false
	&& strpos( $css_w, 'aside.canh{background:#0f2744' ) !== false );
/* ⚠️ Canh cả chiều ngược: không còn luật `.canh{` TRẦN nào đặt chiều cao hay bố cục — một luật
   sót lại là thẻ cảnh báo lại cao vống, y như cũ. */
t( '🔴 không còn luật .canh trần nào đặt chiều cao',
	preg_match( '/(^|[};])\.canh\{[^}]*height:/', $css_w ) === 0 );
t( 'và không còn luật .canh trần nào đặt bố cục',
	preg_match( '/(^|[};])\.canh\{[^}]*(display:flex|position:sticky)/', $css_w ) === 0 );
/* Nhưng MÀU của thẻ cảnh báo thì vẫn phải còn — sửa chiều cao mà làm mất màu vàng là đổi một
   lỗi lấy một lỗi khác. */
t( 'thẻ cảnh báo vẫn giữ nền vàng',
	strpos( $css_w, '.bao.canh{background:#fffbeb' ) !== false );

/* ==========================================================================================
 * 🔴 CỬA HÀNG TRƯỞNG THÊM NGƯỜI MỚI VÀO CƠ SỞ MÌNH.
 * ==========================================================================================
 * Anh Thắng 28/08/2026: *"thêm phần cửa hàng trưởng bổ sung nhân sự cho cửa hàng mình"*, và
 * trước đó: *"tự tạo mã NV tạm (Admin sẽ sửa lại sau), để tài khoản có thể dùng được ngay và
 * đẩy lên máy chấm công"*.
 *
 * Đây là cửa DUY NHẤT cho phép bậc Cửa hàng trưởng mở một hồ sơ mới — nên nó phải hẹp đúng
 * bằng việc ấy, không rộng thêm một phân nào.
 */
vhcc_dung_bang();
$U_TN = array( 'name' => 'CHT Thêm', 'role' => 'CUA_HANG_TRUONG', 'coso' => 'TUTU_BT',
	'ma_nv' => 'CHTTN1' );

teq( '🔴 cửa hàng trưởng ĐƯỢC thêm người', true, VHCC_Vai::duoc( $U_TN, 'them_nv' ) );
teq( 'nhân viên thì KHÔNG', false, VHCC_Vai::duoc(
	array( 'role' => 'Nhân viên', 'coso' => 'TUTU_BT' ), 'them_nv' ) );
/* ⚠️ Cửa hẹp này KHÔNG được nới sang cửa rộng: thêm người ≠ sửa hồ sơ, ≠ cấp mã chuẩn. */
teq( '🔴 nhưng vẫn KHÔNG sửa được hồ sơ', false, VHCC_NhanSu::co_sua_ho_so( $U_TN ) );
teq( 'và vẫn KHÔNG cấp được mã chuẩn qua luu_ho_so', false,
	(bool) VHCC_NhanSu::luu_ho_so( $U_TN, array( 'ma_nv' => 'MNNV9XX0001',
		'ho_ten' => 'Lách Cửa', 'cua_hang' => 'TUTU_BT' ) )['ok'] );

/* ⚠️ SOI BẢNG QUYỀN LÀ CHƯA ĐỦ — phải gọi THẲNG hàm bằng vai không đủ bậc. Bảng khai đúng mà
   hàm quên hỏi bảng thì bảng chỉ là một tờ giấy. Phá thử bỏ chốt trong hàm vẫn xanh nếu ở đây
   chỉ hỏi `VHCC_Vai::duoc`. */
$r_tn_nv = VHCC_NhanSu::them_nv_cua_hang(
	array( 'name' => 'NV thường', 'role' => 'Nhân viên', 'coso' => 'TUTU_BT', 'ma_nv' => 'NVTN1' ),
	array( 'ho_ten' => 'Lách Bằng Vai', 'cccd' => '012345678909' ) );
t( '🔴 nhân viên gọi thẳng hàm cũng bị chối', empty( $r_tn_nv['ok'] ), $r_tn_nv );
/* ⚠️ CA NÀY MỚI TÁCH ĐƯỢC HAI CHỐT RA KHỎI NHAU. Nhân viên bị chối bởi CẢ `them_nv` LẪN chốt
   cơ sở (`co_quyen_coso` dừng ở bậc Cửa hàng trưởng), nên bỏ chốt `them_nv` đi mà thử bằng
   nhân viên thì vẫn xanh — chốt kia đỡ hộ. Khoá riêng `them_nv` cho một Cửa hàng trưởng thì
   chỉ còn đúng một chốt cắn: người ấy vẫn phụ trách cơ sở của mình như thường. */
VHCC_Vai::dat_ngoai_le( $U_AD, 'nv:CHTTN1', 'them_nv', 'khoa' );
$r_tn_kh = VHCC_NhanSu::them_nv_cua_hang( $U_TN,
	array( 'ho_ten' => 'Bị Khoá Riêng', 'cccd' => '012345678908' ) );
t( '🔴 khoá riêng đầu việc thì cửa hàng trưởng ấy cũng không thêm được',
	empty( $r_tn_kh['ok'] ), $r_tn_kh );
teq( 'và cơ sở vẫn là cơ sở của họ (chốt kia không phải thứ chặn)', true,
	VHCC_NhanSu::co_quyen_coso( $U_TN, 'TUTU_BT' ) );
VHCC_Vai::dat_ngoai_le( $U_AD, 'nv:CHTTN1', 'them_nv', '' );

$r_tn = VHCC_NhanSu::them_nv_cua_hang( $U_TN, array(
	'ho_ten' => 'Nguyễn Văn Mới', 'cccd' => '012345678901', 'sdt' => '0900000001',
	'gioi_tinh' => 'male', 'chuc_vu' => 'Nhân viên bán hàng' ) );
t( '🔴 thêm được người mới', ! empty( $r_tn['ok'] ), $r_tn );
/* Mã TẠM phải NHÌN LÀ BIẾT — mã tạm trông giống mã chuẩn thì không ai lọc ra để đổi. */
t( '🔴 mã cấp ra mang tiền tố TAM-',
	isset( $r_tn['ma_nv'] ) && strpos( $r_tn['ma_nv'], 'TAM-' ) === 0, $r_tn );
$hs_tn = VHCC_NhanSu::ho_so( $r_tn['ma_nv'] );
teq( 'hồ sơ vào đúng cơ sở của cửa hàng trưởng', 'TUTU_BT', (string) $hs_tn['cua_hang'] );
teq( 'giữ nguyên căn cước để còn tự lấy PIN', '012345678901', (string) $hs_tn['cccd'] );
teq( 'và ghi là đang làm', 'Đang làm', (string) $hs_tn['trang_thai_lam_viec'] );
/* 🔴 PHẢI ĐẶT VAI, KHÔNG ĐƯỢC ĐỂ TRỐNG. Anh Thắng 28/08/2026: *"cửa hàng đã thêm nhân viên mới,
   mà bên nhân sự chưa thấy thông tin nhân viên đó"* — kèm ảnh hàng mã tạm với cột Vai trò ghi
   «— chưa khai —». Hồ sơ CÓ sang, nhưng trống vai.
   Vai rỗng không phải "chưa quyết": nó là hồ sơ mà mọi cửa trong hệ đều phải ĐOÁN xem người ấy
   bậc mấy — và mỗi cửa đoán một kiểu. */
teq( '🔴 người mới có vai Nhân viên, không để trống', 'Nhân viên',
	(string) $hs_tn['vai_tro'] );
/* Và bảng Quản lý nhân sự phải thấy đúng vai ấy, không hiện «chưa khai». */
$h_vai_tn = vhcc_ns( 'Admin' );
t( '🔴 bảng nhân sự không hiện «chưa khai» cho người mới',
	false === strpos( $h_vai_tn, $r_tn['ma_nv'] . '</b>' )
	|| false === strpos( substr( $h_vai_tn, (int) strpos( $h_vai_tn, $r_tn['ma_nv'] ), 1200 ),
		'chưa khai' ), $r_tn['ma_nv'] );
/* 🔴 KHÔNG CẤP PIN QUA TAY AI. Người mới tự đặt PIN bằng họ tên + căn cước của chính mình. */
teq( '🔴 KHÔNG cấp sẵn PIN cho ai cầm hộ', '', trim( (string) $hs_tn['pin_dang_nhap'] ) );
$tra_tn = VHCC_QuenPin::tra( 'Nguyễn Văn Mới', '012345678901' );
t( '🔴 và người mới TỰ lấy được PIN ngay — tài khoản dùng được luôn',
	! empty( $tra_tn['ok'] ) && $tra_tn['ma_nv'] === $r_tn['ma_nv'], $tra_tn );

/* Cơ sở KHÁC thì chối — ô chọn trên màn hình không phải là chốt. */
$r_tn2 = VHCC_NhanSu::them_nv_cua_hang( $U_TN, array( 'ho_ten' => 'Người Cửa Khác',
	'cccd' => '012345678902', 'cua_hang' => 'POSH_HCM' ) );
t( '🔴 không thêm được vào cơ sở mình không phụ trách', empty( $r_tn2['ok'] ), $r_tn2 );

/* 🔴 CĂN CƯỚC LÀ BẮT BUỘC — thiếu nó là đường tự lấy PIN tắc, và hồ sơ thành hồ sơ chết. */
$r_tn3 = VHCC_NhanSu::them_nv_cua_hang( $U_TN, array( 'ho_ten' => 'Thiếu Căn Cước' ) );
t( '🔴 thiếu căn cước thì chối', empty( $r_tn3['ok'] ), $r_tn3 );
t( 'và nói ra vì sao cần nó',
	isset( $r_tn3['error'] ) && strpos( $r_tn3['error'], 'Quên PIN' ) !== false, $r_tn3 );
t( 'họ tên rỗng cũng chối', empty( VHCC_NhanSu::them_nv_cua_hang( $U_TN,
	array( 'ho_ten' => '  ', 'cccd' => '012345678903' ) )['ok'] ) );

/* 🔴 MỘT NGƯỜI MỘT HỒ SƠ. Người làm hai cơ sở thì khai Cơ sở phụ, không mở hồ sơ thứ hai —
   hai hồ sơ là bảng lương tính người ấy hai lần. */
$r_tn4 = VHCC_NhanSu::them_nv_cua_hang( $U_TN, array( 'ho_ten' => 'Nguyễn Văn Mới',
	'cccd' => '0123 4567 8901' ) );
t( '🔴 căn cước trùng thì chối, dù gõ có dấu cách', empty( $r_tn4['ok'] ), $r_tn4 );
t( 'và chỉ ra hồ sơ đang có',
	isset( $r_tn4['error'] ) && strpos( $r_tn4['error'], $r_tn['ma_nv'] ) !== false, $r_tn4 );
t( 'kèm lối đi đúng là ô Cơ sở phụ',
	isset( $r_tn4['error'] ) && strpos( $r_tn4['error'], 'Cơ sở phụ' ) !== false, $r_tn4 );
/* 🔴 VÀ HỒ SƠ TRONG SỔ CŨNG CÓ THỂ LƯU KÈM DẤU CÁCH — nạp .csv từ Excel ra đúng như thế. So
   chuỗi thô thì hai bên cùng một số mà không nhận ra nhau, và người ấy có hồ sơ thứ hai. */
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'cccd' => '0123-4567-8905' ),
	array( 'ma_nv' => $r_tn['ma_nv'] ) );
$r_tn4b = VHCC_NhanSu::them_nv_cua_hang( $U_TN, array( 'ho_ten' => 'Người Nữa',
	'cccd' => '012345678905' ) );
t( '🔴 sổ lưu kèm gạch nối vẫn nhận ra là trùng', empty( $r_tn4b['ok'] ), $r_tn4b );
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'cccd' => '012345678901' ),
	array( 'ma_nv' => $r_tn['ma_nv'] ) );

/* 🔴 MÃ TẠM KHÔNG CẤP TRÙNG MÃ ĐÃ CÓ LƯỢT CHẤM CÔNG — kể cả khi hồ sơ ấy đã bị xoá. Cấp trùng
   là công của người cũ chảy sang người mới, và không có gì báo. */
$ma_tam_1 = $r_tn['ma_nv'];
VHCC_NhanSu::xoa_ho_so( $U_AD, $ma_tam_1 );
$wpdb->insert( VHCC_DB::t( 'cham_cong' ), array( 'ma_nv' => $ma_tam_1, 'ho_ten' => 'Người Cũ',
	'coso' => 'TUTU_BT', 'ngay' => '2026-08-01', 'gio_vao_giay' => 28800, 'gio_ra_giay' => 61200,
	'hau_to' => '', 'nguon' => 'may' ) );
$r_tn5 = VHCC_NhanSu::them_nv_cua_hang( $U_TN, array( 'ho_ten' => 'Người Sau',
	'cccd' => '012345678904' ) );
t( 'vẫn thêm được người sau', ! empty( $r_tn5['ok'] ), $r_tn5 );
t( '🔴 nhưng KHÔNG cấp lại mã đã có lượt chấm công',
	$r_tn5['ma_nv'] !== $ma_tam_1, array( $ma_tam_1, $r_tn5['ma_nv'] ) );

/* ---- Trên MÀN HÌNH ---- */
$h_tn = vhcc_web_nhu( 'CHTTN1', 'Cửa hàng trưởng', array( 'man' => 'cham' ) );
t( '🔴 cửa hàng trưởng thấy khối thêm người',
	strpos( $h_tn, 'Thêm người mới vào cửa hàng' ) !== false, substr( $h_tn, 0, 600 ) );
t( 'có ô căn cước', strpos( $h_tn, 'name="tn_cccd"' ) !== false );
t( 'và nút gửi', strpos( $h_tn, 'value="them_nv"' ) !== false );
/* ⚠️ Người bấm phải biết BƯỚC TIẾP THEO, không thì họ đứng chờ một mã PIN không bao giờ tới. */
t( '🔴 và màn nói ra đường tự lấy PIN', strpos( $h_tn, 'Quên PIN' ) !== false );
/* 🔴 KHỐI GẬP, không bày sẵn giữa đường đọc hằng ngày. */
t( 'khối gập lại, không bày sẵn', strpos( $h_tn, '<details class="gap"' ) !== false );

/* 🔴 GỬI THẬT MỘT LƯỢT POST. Khối vẽ đúng mà bộ điều phối không khai việc thì bấm nút xong
   không có gì xảy ra — và phá thử bỏ dòng khai ấy vẫn xanh nếu ở đây chỉ soi HTML. */
$tok_tn = VHCC_Auth::phat_token( 'CHT Thêm', 'Cửa hàng trưởng', 'TUTU_BT', 'CHTTN1' );
$_COOKIE = array( VHCC_Web::COOKIE => $tok_tn );
$_GET  = array( 'man' => 'cham' );
$_POST = array( 'viec' => 'them_nv', 'ky' => VHCC_Web::chu_ky( $tok_tn ),
	'tn_ho_ten' => 'Gửi Qua Màn', 'tn_cccd' => '012345678910', 'tn_coso' => 'TUTU_BT' );
/* ⚠️ Trong bài kiểm `ve()` KHÔNG exit (xem chú thích ở đó), nên lượt POST này chuyển hướng
   xong vẫn vẽ tiếp — và tiêu thụ luôn câu báo. Đọc ngay ở lượt này, đừng đợi lượt sau. */
ob_start(); VHCC_Web::phuc_vu(); $h_tn_post = ob_get_clean();
$_POST = array(); $_GET = array(); $_COOKIE = array();
t( '🔴 bấm nút trên màn thì hồ sơ vào sổ thật',
	null !== VHCC_NhanSu::ho_so_theo_cccd( '012345678910' ),
	( preg_match( '#<div class="bao loi">(.{0,300}?)</div>#s', $h_tn_post, $m_tn )
		? trim( wp_strip_all_tags( $m_tn[1] ) ) : 'KHÔNG THẤY CÂU NÀO' ) );
t( 'và màn báo lại kèm đường tự lấy PIN',
	strpos( $h_tn_post, 'Quên PIN' ) !== false, substr( $h_tn_post, 0, 1500 ) );

/* 🔴 KHOÁ RIÊNG MỘT NGƯỜI THÌ KHỐI BIẾN MẤT, dù họ vẫn vào được màn Bảng công. Đây là phép duy
   nhất tách được "khối gác đúng" khỏi "cả màn không vẽ" — nhân viên không vào nổi màn này, nên
   họ không thấy khối vì lý do khác hẳn. */
VHCC_Vai::dat_ngoai_le( $U_AD, 'nv:CHTTN1', 'them_nv', 'khoa' );
$h_tn_kh = vhcc_web_nhu( 'CHTTN1', 'Cửa hàng trưởng', array( 'man' => 'cham' ) );
t( 'bị khoá riêng vẫn vào được màn Bảng công',
	strpos( $h_tn_kh, 'Chấm công' ) !== false, substr( $h_tn_kh, 0, 400 ) );
t( '🔴 nhưng KHÔNG còn khối thêm người',
	strpos( $h_tn_kh, 'Thêm người mới vào cửa hàng' ) === false );
VHCC_Vai::dat_ngoai_le( $U_AD, 'nv:CHTTN1', 'them_nv', '' );

/* ==========================================================================================
 * 🔴 ẢNH THẺ — KHÔNG ÉP, NHƯNG THIẾU THÌ PHẢI KÊU.
 * ==========================================================================================
 * Anh Thắng 28/08/2026: *"Bổ sung thêm ảnh thẻ để sau này đẩy lên máy chấm công và đưa vào quét
 * nhận diện khuôn mặt qua chấm công online (không ép buộc, nhưng không có là phải đưa ra cảnh
 * báo bù sau. hiện ảnh thẻ mẫu cho cửa hàng trưởng biết"*.
 */
/* ==========================================================================================
 * 🔴 CHỨC VỤ CHỌN SẴN TỪ SỔ, TỪ BẬC NGƯỜI ĐANG THÊM ĐỔ XUỐNG.
 * ==========================================================================================
 * Anh Thắng 28/08/2026: *"Thiếu chức vụ, lấy sẵn từ hệ thống (chức vụ lấy từ chức vụ của cửa
 * hàng trưởng đi xuống)"*. Gõ tay thì mỗi người một cách viết — "Thu ngân", "thu ngan", "TN" —
 * và bảng lương gom theo chức vụ ra ba nhóm cho cùng một việc.
 */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CVA1', 'ho_ten' => 'Bạn Thu Ngân',
	'cua_hang' => 'TUTU_BT', 'chuc_vu' => 'Thu ngân', 'trang_thai_lam_viec' => 'Đang làm' ) );
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CVA2', 'ho_ten' => 'Bạn Bán Hàng',
	'cua_hang' => 'TUTU_BT', 'chuc_vu' => 'Nhân viên bán hàng', 'trang_thai_lam_viec' => 'Đang làm' ) );
/* Chức vụ của người mang vai CAO HƠN thì cửa hàng trưởng không cấp được. */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CVA3', 'ho_ten' => 'Sếp Vùng',
	'cua_hang' => 'TUTU_BT', 'chuc_vu' => 'Giám sát vùng', 'trang_thai_lam_viec' => 'Đang làm' ) );
VHCC_NhanSu::dat_vai_tro( $U_AD, 'CVA3', 'Quản lý' );
/* Chức vụ ở CƠ SỞ KHÁC cũng không được bày ra — bày là mời chọn nhầm, và nó vào bảng lương. */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CVA4', 'ho_ten' => 'Người Xa',
	'cua_hang' => 'JP_HCM', 'chuc_vu' => 'Pha chế', 'trang_thai_lam_viec' => 'Đang làm' ) );

$cv = VHCC_NhanSu::chuc_vu_cho( $U_TN, 'TUTU_BT' );
t( '🔴 lấy được chức vụ đang có ở cơ sở', in_array( 'Thu ngân', $cv, true )
	&& in_array( 'Nhân viên bán hàng', $cv, true ), $cv );
t( '🔴 KHÔNG bày chức vụ của người mang vai cao hơn',
	! in_array( 'Giám sát vùng', $cv, true ), $cv );
/* ⚠️ "Pha chế" nay nằm trong danh sách KHAI SẴN, nên nó có mặt vì lý do khác — canh bằng một
   chức vụ chỉ có ở cơ sở kia. */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CVA6', 'ho_ten' => 'Người Xa Nữa',
	'cua_hang' => 'JP_HCM', 'chuc_vu' => 'Trực bãi xe', 'trang_thai_lam_viec' => 'Đang làm' ) );
$cv = VHCC_NhanSu::chuc_vu_cho( $U_TN, 'TUTU_BT' );
t( '🔴 và KHÔNG bày chức vụ của cơ sở khác', ! in_array( 'Trực bãi xe', $cv, true ), $cv );

/* ==========================================================================================
 * 🔴 "Nhầm chức vụ rồi" — anh Thắng 28/08/2026 nhìn ô gợi ý thấy "Khu vui chơi".
 * ==========================================================================================
 * Đúng dữ liệu, sai kỳ vọng: sổ thật nạp từ Sheets cũ có cột `chuc_vu` chứa lẫn TÊN BỘ PHẬN.
 * Lấy nguyên xi ra là dạy người dùng khai tiếp cái sai ấy cho người mới.
 */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CVBP', 'ho_ten' => 'Người Bộ Phận',
	'cua_hang' => 'TUTU_BT', 'chuc_vu' => 'Khu vui chơi', 'trang_thai_lam_viec' => 'Đang làm' ) );
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CVBP2', 'ho_ten' => 'Người Bộ Phận Hoa',
	'cua_hang' => 'TUTU_BT', 'chuc_vu' => 'MÁY TỰ ĐỘNG', 'trang_thai_lam_viec' => 'Đang làm' ) );
$cv_bp = VHCC_NhanSu::chuc_vu_cho( $U_TN, 'TUTU_BT' );
t( '🔴 tên BỘ PHẬN không được bày ra ô Chức vụ',
	! in_array( 'Khu vui chơi', $cv_bp, true ), $cv_bp );
/* ⚠️ `strtolower` của PHP không hạ được chữ CÓ DẤU — "MÁY TỰ ĐỘNG" viết hoa phải lọt lưới nếu
   so bằng nó. Đây là chỗ đã cắn một lần ở `da_nghi`. */
t( '🔴 kể cả viết HOA có dấu', ! in_array( 'MÁY TỰ ĐỘNG', $cv_bp, true ), $cv_bp );
teq( 'và hàm nhận diện nói đúng', true, VHCC_NhanSu::la_ten_bo_phan( 'khu vui chơi' ) );
teq( 'chức vụ thật thì không bị nhận nhầm', false, VHCC_NhanSu::la_ten_bo_phan( 'Thu ngân' ) );
teq( 'chuỗi rỗng không phải bộ phận', false, VHCC_NhanSu::la_ten_bo_phan( '  ' ) );

/* 🔴 CÓ DANH SÁCH KHAI SẴN, không chỉ dựa vào sổ — cửa hàng mới mở thì sổ chưa có gì để gợi ý. */
t( '🔴 luôn có danh sách chức vụ khai sẵn',
	in_array( 'Thu ngân', $cv_bp, true ) && in_array( 'Ca trưởng', $cv_bp, true ), $cv_bp );
/* Và chúng đứng TRƯỚC — người mở ô ra thấy ngay chức vụ đúng nghĩa, không phải cuộn qua mớ cũ. */
teq( '🔴 danh sách khai sẵn đứng đầu', 'Nhân viên', isset( $cv_bp[0] ) ? $cv_bp[0] : '' );
/* Không lặp: chức vụ vừa có trong sổ vừa có trong danh sách khai sẵn chỉ hiện MỘT lần. */
teq( 'không bày trùng một chức vụ hai lần', 1, count( array_filter( $cv_bp,
	function ( $x ) { return 'Thu ngân' === $x; } ) ) );
/* Admin đứng trên thì thấy đủ — luật là "từ bậc mình đổ xuống", không phải "giấu của Quản lý". */
t( 'Admin thì thấy cả chức vụ của Quản lý', in_array( 'Giám sát vùng',
	VHCC_NhanSu::chuc_vu_cho( $U_AD, 'TUTU_BT' ), true ) );
t( 'cơ sở rỗng thì trả rỗng, không nổ', array() === VHCC_NhanSu::chuc_vu_cho( $U_TN, '' ) );
/* Trùng cách viết hoa/thường thì gom làm một — đó chính là cái đang muốn dẹp. */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CVA5', 'ho_ten' => 'Bạn Nữa',
	'cua_hang' => 'TUTU_BT', 'chuc_vu' => 'THU NGÂN', 'trang_thai_lam_viec' => 'Đang làm' ) );
/* ⚠️ `strcasecmp` KHÔNG hạ được chữ CÓ DẤU — "THU NGÂN" và "thu ngân" so bằng nó ra khác nhau.
   Dùng đúng bộ hạ chữ của hệ (`chu_thuong`), y như chính hàm đang thử. */
$cv_lai = VHCC_NhanSu::chuc_vu_cho( $U_TN, 'TUTU_BT' );
teq( '🔴 "Thu ngân" và "THU NGÂN" gom làm MỘT dòng gợi ý', 1, count( array_filter( $cv_lai,
	function ( $x ) { return VHCC_NhanSu::chu_thuong( $x ) === VHCC_NhanSu::chu_thuong( 'Thu ngân' ); } ) ) );
/* Và giữ CÁCH VIẾT GẶP TRƯỚC — danh sách gợi ý không được đổi mặt mỗi lần có người nhập ẩu. */
t( 'giữ cách viết gặp trước, không để bản viết hoa đè',
	in_array( 'Thu ngân', $cv_lai, true ), $cv_lai );

$h_cv = vhcc_web_nhu( 'CHTTN1', 'Cửa hàng trưởng', array( 'man' => 'cham', 'ccs' => 'TUTU_BT' ) );
t( '🔴 màn bày danh sách gợi ý chức vụ',
	strpos( $h_cv, 'list="tn_cv_ds"' ) !== false
	&& strpos( $h_cv, '<datalist id="tn_cv_ds">' ) !== false, substr( $h_cv, 0, 400 ) );
t( 'và có chức vụ thật trong đó', strpos( $h_cv, 'value="Thu ngân"' ) !== false, $h_cv );
/* ⚠️ `<datalist>` chứ không phải `<select>`: cửa hàng mới mở thì sổ chưa có chức vụ nào, ô chọn
   rỗng mà không gõ được là bế tắc — người ta bỏ trống luôn ô ấy. */
t( '🔴 vẫn là ô GÕ ĐƯỢC, không phải ô chọn cứng',
	preg_match( '/<input id="tn_cv"[^>]*list="tn_cv_ds"/', $h_cv ) === 1, $h_cv );

t( '🔴 màn có ô tải ảnh thẻ', strpos( $h_tn, 'name="tn_anh"' ) !== false, $h_tn );
/* ⚠️ Thiếu `enctype` thì ô ảnh chỉ gửi lên cái TÊN TỆP — biểu mẫu vẫn chạy, vẫn báo "đã thêm",
   mà ảnh biến mất không dấu vết. Đây là lỗi im lặng nhất của cả khối này. */
t( '🔴 biểu mẫu khai enctype multipart, không thì ảnh mất im lặng',
	strpos( $h_tn, 'enctype="multipart/form-data"' ) !== false, $h_tn );
t( 'nói rõ ảnh KHÔNG bắt buộc', strpos( $h_tn, 'không bắt buộc' ) !== false );
/* 🔴 Ảnh mẫu VẼ bằng SVG, không nhúng mặt một người thật — dùng mặt nhân viên nào đó làm mẫu
   cho cả chuỗi là chuyện không xin phép được. */
t( '🔴 có ảnh thẻ mẫu vẽ sẵn', strpos( $h_tn, 'Ảnh thẻ mẫu' ) !== false
	&& strpos( $h_tn, '<svg' ) !== false, $h_tn );
/* 🔴 VẼ THEO ĐÚNG TẤM ANH THẮNG GỬI 28/08/2026: nền XANH, ngang vai, áo sơ mi. Nền xanh là chi
   tiết đáng vẽ nhất — nó nói ngay "ảnh thẻ chụp ở tiệm", không phải ảnh cắt từ điện thoại. */
/* ⚠️ Canh đúng thẻ NỀN, không canh mã màu trần: màu ấy còn dùng cho cổ áo, nên soi chuỗi
   không thôi thì đổi nền đi vẫn xanh. */
t( 'mẫu có nền xanh như ảnh thẻ thật',
	preg_match( '/<rect x="0" y="0" width="118" height="150" fill="#1f6fc4"/', $h_tn ) === 1, $h_tn );
/* ⚠️ VẼ, không nhúng ảnh người thật: dùng mặt một nhân viên làm mẫu cho cả chuỗi là chuyện
   không xin phép được. */
t( '🔴 mẫu là hình VẼ, không phải ảnh nhúng',
	strpos( $h_tn, 'data:image' ) === false, substr( $h_tn, 0, 200 ) );
/* Chỉ cách chụp bằng chữ nữa — hình nói bố cục, chữ nói mấy điều hình không nói được. */
t( 'nói rõ nền trơn một màu', strpos( $h_tn, 'nền trơn một màu' ) !== false );
t( 'và dặn đừng dùng ảnh nghiêng / selfie / cắt từ ảnh tập thể',
	strpos( $h_tn, 'ảnh cắt từ ảnh tập thể' ) !== false );
t( 'và nói ra vì sao nên có ảnh',
	strpos( $h_tn, 'tự nhận khuôn mặt' ) !== false, $h_tn );

/* ---- Rửa ảnh ---- */
$ra_trong = VHCC_NhanSu::rua_anh_the( array( 'error' => UPLOAD_ERR_NO_FILE ) );
t( '🔴 không gửi ảnh thì KHÔNG phải lỗi — ảnh là phần tuỳ chọn',
	! empty( $ra_trong['ok'] ) && '' === $ra_trong['anh'], $ra_trong );
$ra_rac = VHCC_NhanSu::rua_anh_the( array( 'error' => UPLOAD_ERR_OK,
	'tmp_name' => __FILE__ ) );
t( '🔴 tệp không phải ảnh thì chối', empty( $ra_rac['ok'] ), $ra_rac );
/* ⚠️ Câu chối phải CÓ CHỮ. Nuốt im là "đã thêm người xong" mà ảnh biến mất, không ai biết. */
t( 'và câu chối có chữ để người ta biết đường sửa',
	isset( $ra_rac['error'] ) && '' !== $ra_rac['error'], $ra_rac );
t( 'tệp không đọc được cũng chối, không nổ',
	empty( VHCC_NhanSu::rua_anh_the( array( 'error' => UPLOAD_ERR_OK,
		'tmp_name' => '/khong/co/duong/nay.jpg' ) )['ok'] ) );
/* ⚠️ Câu chối phải NÓI ĐÚNG BỆNH. "Không phải ảnh" và "không đọc được tệp" là hai việc phải làm
   khác nhau — gộp làm một câu chung thì người ta thử lại đúng cái vừa hỏng. */
t( 'và nói đúng bệnh: không đọc được tệp',
	strpos( (string) VHCC_NhanSu::rua_anh_the( array( 'error' => UPLOAD_ERR_OK,
		'tmp_name' => '/khong/co/duong/nay.jpg' ) )['error'], 'Không đọc được' ) !== false );
t( 'tệp có thật nhưng không phải ảnh thì nói đúng bệnh ấy',
	strpos( (string) $ra_rac['error'], 'không phải ảnh' ) !== false, $ra_rac );

/* 🔴 NHÁNH THÀNH CÔNG — ảnh THẬT, thu nhỏ THẬT. Nhánh này là nhánh duy nhất chạy trên máy thật;
   không thử được nó thì cả khối rửa ảnh chỉ có mấy câu chối là có người canh. */
$anh_to = imagecreatetruecolor( 1200, 1600 );
imagefill( $anh_to, 0, 0, imagecolorallocate( $anh_to, 200, 180, 160 ) );
$tep_to = tempnam( sys_get_temp_dir(), 'vhcc-thu' ) . '.jpg';
imagejpeg( $anh_to, $tep_to, 92 );
imagedestroy( $anh_to );
$ra_that = VHCC_NhanSu::rua_anh_the( array( 'error' => UPLOAD_ERR_OK, 'tmp_name' => $tep_to ) );
t( '🔴 ảnh thật thì nhận', ! empty( $ra_that['ok'] ), $ra_that );
t( 'và trả về data URI ảnh JPEG',
	strpos( (string) $ra_that['anh'], 'data:image/jpeg;base64,' ) === 0,
	substr( (string) $ra_that['anh'], 0, 40 ) );
/* ⚠️ THU NHỎ THẬT, không chỉ đổi tên. Ảnh 1200×1600 từ điện thoại mà giữ nguyên thì cột dữ liệu
   phình, và tấm ấy còn phải chui qua hàng đợi xuống một con ESP32 vài trăm KB bộ nhớ. */
$goc_anh = base64_decode( substr( (string) $ra_that['anh'], strlen( 'data:image/jpeg;base64,' ) ) );
$co_anh_that = getimagesizefromstring( $goc_anh );
t( '🔴 cạnh dài đã ép về mức khai trong ANH_CANH',
	max( $co_anh_that[0], $co_anh_that[1] ) <= VHCC_NhanSu::ANH_CANH,
	array( $co_anh_that[0], $co_anh_that[1] ) );
t( 'và giữ nguyên tỉ lệ 3:4, không bóp méo mặt người',
	abs( ( $co_anh_that[0] / $co_anh_that[1] ) - 0.75 ) < 0.02,
	array( $co_anh_that[0], $co_anh_that[1] ) );
t( 'chuỗi ảnh nằm dưới ngưỡng đã khai',
	strlen( (string) $ra_that['anh'] ) <= VHCC_NhanSu::ANH_TOI_DA );
@unlink( $tep_to );

/* ---- Ảnh có thì đi kèm LỆNH xuống máy ---- */
