$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'queue' ) );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'may' ) );

/* ---- ĐẨY XUỐNG MÁY + MẪU KHUÔN MẶT TỪ TAB ADMIN "HỒ SƠ & TÀI KHOẢN" -----------------------
   Anh Thắng 29/08/2026: *"hiện tại đẩy xuống chỉ có cửa hàng trưởng mới thấy, bổ sung bên tab
   admin cũng bổ sung được cho đợt đầu này"*. Trước bản này `VHCC_Web::luu_ho_so()` (màn "Hồ sơ
   & tài khoản") ghi thẳng vào bảng nhan_vien, không đụng gì máy chấm công hay mẫu khuôn mặt —
   khác hẳn `VHCC_NhanSu::them_nv_cua_hang()` (đường Cửa hàng trưởng) vốn đã có cả hai việc đó. */
$wpdb->insert( VHCC_DB::t( 'may' ), array( 'serial' => 'SN-ADMHS', 'mac' => '', 'cua_hang' => 'ADH_CS' ) );
$tok_adhs = VHCC_Auth::phat_token( 'Admin Hồ Sơ', 'Admin', '', 'ADMHS1' );

/* Vector giả 128 số — không cần đúng số thật của face-api, chỉ cần ĐỦ SỐ CHIỀU và toàn số hợp
   lệ để VHCC_Mat::doc_vector() nhận (kiem-mat.php có phép thử riêng cho chính hàm đọc dãy đó). */
$vec_adm = array();
for ( $i = 0; $i < 128; $i++ ) { $vec_adm[] = 0.3 + ( $i % 5 ) * 0.01; }

$anh_adm = imagecreatetruecolor( 600, 800 );
imagefill( $anh_adm, 0, 0, imagecolorallocate( $anh_adm, 200, 180, 160 ) );
$tep_adm = tempnam( sys_get_temp_dir(), 'vhcc-adm' ) . '.jpg';
imagejpeg( $anh_adm, $tep_adm, 90 );
imagedestroy( $anh_adm );

$_COOKIE = array( VHCC_Web::COOKIE => $tok_adhs );
$_GET    = array( 'man' => 'ho_so' );
$_POST   = array( 'viec' => 'sua_hs', 'ky' => VHCC_Web::chu_ky( $tok_adhs ),
	'ma_nv' => 'ADMHS_NEW', 'ho_ten' => 'Admin Tạo Mới', 'cua_hang' => 'ADH_CS',
	'hs_vector' => wp_json_encode( $vec_adm ) );
$_FILES  = array( 'hs_anh_the' => array( 'error' => UPLOAD_ERR_OK, 'tmp_name' => $tep_adm, 'name' => 'the.jpg' ) );
ob_start(); VHCC_Web::phuc_vu(); $h_adm = ob_get_clean();
$_POST = array(); $_GET = array(); $_COOKIE = array(); $_FILES = array();
@unlink( $tep_adm );

$hs_adm = VHCC_NhanSu::ho_so( 'ADMHS_NEW' );
t( '🔴 tạo được hồ sơ qua tab Admin', null !== $hs_adm, $h_adm );
t( '🔴 ảnh thẻ vào thẳng hồ sơ',
	$hs_adm && strpos( (string) $hs_adm['anh_the'], 'data:image/jpeg;base64,' ) === 0, $hs_adm );

$lenh_adm = VHCC_DB::rows( "SELECT * FROM " . VHCC_DB::t( 'queue' ) . " WHERE ma_nv='ADMHS_NEW'" );
t( '🔴 và đặt lệnh xuống máy của cơ sở', count( $lenh_adm ) === 1, $lenh_adm );
teq( '🔴 KHÔNG qua Admin duyệt — người tạo đã là Admin, đủ quyền duyệt lệnh của chính mình rồi',
	'cho', $lenh_adm ? (string) $lenh_adm[0]['trang_thai'] : '' );
t( '🔴 câu báo KHÔNG nói "chờ Admin duyệt" (khác đường Cửa hàng trưởng)',
	strpos( $h_adm, 'tới Admin để duyệt' ) === false, $h_adm );

$mau_adm = VHCC_Mat::mau( 'ADMHS_NEW' );
t( '🔴 ảnh thẻ cũng seed mẫu đối chiếu khuôn mặt cho chấm công online', null !== $mau_adm, $mau_adm );
if ( $mau_adm ) {
	teq( 'mẫu duyệt sẵn — cùng lý do với đường Cửa hàng trưởng', 'duyet', $mau_adm['trang_thai'] );
}
t( '🔴 màn báo có nhắc tới việc lấy ảnh thẻ làm mẫu',
	strpos( $h_adm, 'làm mẫu đối chiếu khuôn mặt' ) !== false, $h_adm );

/* Không ảnh / không vector thì vẫn tạo hồ sơ được, và không seed mẫu rác. */
$_COOKIE = array( VHCC_Web::COOKIE => $tok_adhs );
$_GET    = array( 'man' => 'ho_so' );
$_POST   = array( 'viec' => 'sua_hs', 'ky' => VHCC_Web::chu_ky( $tok_adhs ),
	'ma_nv' => 'ADMHS_KOANH', 'ho_ten' => 'Admin Không Ảnh', 'cua_hang' => 'ADH_CS' );
ob_start(); VHCC_Web::phuc_vu(); ob_get_clean();
$_POST = array(); $_GET = array(); $_COOKIE = array();
t( '🔴 không ảnh vẫn tạo được hồ sơ', null !== VHCC_NhanSu::ho_so( 'ADMHS_KOANH' ) );
t( 'không ảnh thì không seed mẫu rác', null === VHCC_Mat::mau( 'ADMHS_KOANH' ) );
$lenh_koanh = VHCC_DB::rows( "SELECT * FROM " . VHCC_DB::t( 'queue' ) . " WHERE ma_nv='ADMHS_KOANH'" );
t( 'vẫn đặt lệnh xuống máy dù không ảnh (mặt lấy trực tiếp tại máy)', count( $lenh_koanh ) === 1, $lenh_koanh );

/* SỬA hồ sơ CŨ (không phải tạo mới) thì KHÔNG đặt thêm lệnh máy/mẫu nào — nút riêng "sửa lại
   trên máy 🔄" ở trang Quản lý nhân sự đã lo việc đó, không lặp lại ở đây. */
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'queue' ) . " WHERE ma_nv='ADMHS_NEW'" );
$_COOKIE = array( VHCC_Web::COOKIE => $tok_adhs );
$_GET    = array( 'man' => 'ho_so' );
$_POST   = array( 'viec' => 'sua_hs', 'ky' => VHCC_Web::chu_ky( $tok_adhs ),
	'ma_nv' => 'ADMHS_NEW', 'ho_ten' => 'Admin Tạo Mới Sửa Tên' );
ob_start(); VHCC_Web::phuc_vu(); ob_get_clean();
$_POST = array(); $_GET = array(); $_COOKIE = array();
teq( 'sửa tên thành công', 'Admin Tạo Mới Sửa Tên', VHCC_NhanSu::ho_so( 'ADMHS_NEW' )['ho_ten'] );
$lenh_sua_lai = VHCC_DB::rows( "SELECT * FROM " . VHCC_DB::t( 'queue' ) . " WHERE ma_nv='ADMHS_NEW'" );
t( '🔴 SỬA hồ sơ cũ không tự đặt thêm lệnh máy nào', count( $lenh_sua_lai ) === 0, $lenh_sua_lai );

$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'queue' ) );
$wpdb->query( 'DELETE FROM ' . VHCC_DB::t( 'may' ) . " WHERE serial='SN-ADMHS'" );

$h_tn_nv = vhcc_web_nhu( 'NVTN1', 'Nhân viên', array( 'man' => 'cham' ) );
t( '🔴 nhân viên KHÔNG thấy khối ấy',
	strpos( $h_tn_nv, 'Thêm người mới vào cửa hàng' ) === false );
/* Người đã có tab Hồ sơ thì tạo ở đó — cấp được mã CHUẨN, đủ ô hơn. Bày thêm một cửa hẹp bên
   cạnh cửa rộng chỉ làm người ta phân vân chọn cửa nào. */
$h_tn_ad = vhcc_web_nhu( 'ADTN1', 'Admin', array( 'man' => 'cham' ) );
t( '🔴 Admin cũng không thấy — họ tạo hồ sơ ở tab Hồ sơ, cấp mã chuẩn',
	strpos( $h_tn_ad, 'Thêm người mới vào cửa hàng' ) === false );

vhcc_dung_bang();

/* ==========================================================================================
 * 🔴 "CÓ ĐI LÀ ĐƯỢC" — kiểu tính thứ ba.
 * ==========================================================================================
 * Anh Thắng 28/08/2026: *"1 số cửa hàng chấm công theo có đi là được, thêm giúp anh trạng thái
 * set cho cửa hàng đó, có giờ vào và giờ ra là được"*. Bảng công của anh đang ra 0.41, 0.14,
 * 0.03 ở những cửa hàng ấy — số giờ thật, nhưng vô nghĩa với kiểu trả công theo ngày.
 */
vhcc_dung_bang();
teq( '🔴 đủ vào + ra thì 1 công', 1, VHCC_Luong::cong_co_di( 28800, 61200 ) );
/* ⚠️ Thiếu giờ RA thì KHÔNG tính, dù có giờ vào — tính đại 1 công cho ngày quên check-out là
   biến một lỗi bấm máy thành tiền, và người ta sẽ thôi bấm giờ ra. */
teq( '🔴 thiếu giờ ra thì 0 công', 0, VHCC_Luong::cong_co_di( 28800, null ) );
teq( 'thiếu giờ vào cũng 0 công', 0, VHCC_Luong::cong_co_di( null, 61200 ) );
teq( 'không có gì cũng 0 công', 0, VHCC_Luong::cong_co_di( null, null ) );
teq( 'chuỗi rỗng tính như không có', 0, VHCC_Luong::cong_co_di( '', '' ) );
/* Làm 15 phút vẫn là 1 công — đó chính là ý "có đi là được". */
teq( '🔴 làm 15 phút vẫn đủ 1 công', 1, VHCC_Luong::cong_co_di( 28800, 29700 ) );

VHCC_Luong::dat_cach_tinh( $U_AD, array( 'CODI_CS' => 'ngay' ) );
teq( '🔴 khai được kiểu ngay', 'ngay', VHCC_Luong::cach_tinh( 'CODI_CS' ) );
teq( 'và tính là ĐÃ KHAI THẲNG', true, VHCC_Luong::cach_tinh_da_khai( 'CODI_CS' ) );
/* Kiểu lạ thì bỏ khai, quay về suy theo bộ phận — không nhận bừa. */
VHCC_Luong::dat_cach_tinh( $U_AD, array( 'CODI_CS' => 'linh-tinh' ) );
teq( '🔴 kiểu lạ thì không nhận', false, VHCC_Luong::cach_tinh_da_khai( 'CODI_CS' ) );
VHCC_Luong::dat_cach_tinh( $U_AD, array( 'CODI_CS' => 'ngay' ) );
/* Đổi cách tính vẫn là việc bậc Quản lý — nó đổi con số ra tiền của cả cơ sở. */
t( '🔴 cửa hàng trưởng KHÔNG đổi được cách tính', empty( VHCC_Luong::dat_cach_tinh(
	array( 'role' => 'Cửa hàng trưởng', 'coso' => 'CODI_CS' ),
	array( 'CODI_CS' => 'gio' ) )['ok'] ) );

/* ---- Trên LƯỚI ---- */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CODI1', 'ho_ten' => 'Người Có Đi',
	'cua_hang' => 'CODI_CS', 'trang_thai_lam_viec' => 'Đang làm' ) );
vhcc_cham( 'CODI_CS', '2026-08-03', 'CODI1', 'Người Có Đi', '08:00:00', '08:15:00' );
vhcc_cham( 'CODI_CS', '2026-08-04', 'CODI1', 'Người Có Đi', '08:00:00', '17:00:00' );
vhcc_cham( 'CODI_CS', '2026-08-05', 'CODI1', 'Người Có Đi', '08:00:00', '' );
$h_codi = vhcc_web_nhu( 'ADCODI', 'Admin',
	array( 'man' => 'cham', 'ccs' => 'CODI_CS', 'cth' => '2026-08' ) );
t( '🔴 lưới nói ra đang tính CÓ ĐI LÀ ĐƯỢC',
	strpos( $h_codi, 'CÓ ĐI LÀ ĐƯỢC' ) !== false, substr( $h_codi, 0, 300 ) );
/* ⚠️ Ba ngày: 15 phút, cả ngày, thiếu giờ ra → 1 + 1 + 0 = 2 công. Con số này là thứ ra tiền. */
t( '🔴 tổng ra SỐ CÔNG, không phải số giờ',
	strpos( $h_codi, '2 công' ) !== false, substr( $h_codi, -6000 ) );
/* ⚠️ Bảng "Tổng giờ làm theo nhân viên" ở dưới VẪN nói giờ — nó là bảng khác, và giờ thật thì
   vẫn phải tra được. Chỉ LƯỚI cả tháng đổi đơn vị. Nên canh đúng ô TỔNG của lưới. */
t( 'ô tổng của lưới mang đơn vị công',
	preg_match( '/<td class="tong"><b>\d+ công<\/b>/', $h_codi ) === 1, substr( $h_codi, -6000 ) );
/* Số giờ thật vẫn giữ trong chú thích rê chuột — đổi cách ĐỌC, không giấu dữ liệu. */
t( '🔴 giờ thật vẫn còn trong chú thích',
	strpos( $h_codi, '08:00:00 → 17:00:00' ) !== false, substr( $h_codi, -6000 ) );

/* Cơ sở tính THEO GIỜ thì không đổi gì — kiểu mới không được lây sang cơ sở khác. */
$h_gio_cu = vhcc_web_nhu( 'ADCODI', 'Admin',
	array( 'man' => 'cham', 'ccs' => 'TUTU_BT', 'cth' => '2026-08' ) );
t( '🔴 cơ sở theo giờ vẫn hiện số giờ như cũ',
	strpos( $h_gio_cu, 'CÓ ĐI LÀ ĐƯỢC' ) === false );

/* Màn Cấu hình phải bày kiểu thứ ba ra, không thì khai bằng gì. */
$h_ct = vhcc_web_nhu( 'ADCODI', 'Admin', array( 'man' => 'cau_hinh' ) );
t( '🔴 màn Cấu hình có ô chọn "Có đi là được"',
	strpos( $h_ct, 'Có đi là được' ) !== false, substr( $h_ct, 0, 300 ) );
t( 'và vẫn còn hai kiểu cũ', strpos( $h_ct, 'Theo giờ' ) !== false
	&& strpos( $h_ct, 'Theo công' ) !== false );
vhcc_dung_bang();


/* ==========================================================================================
 * 🔴 CẢ TRANG PHẢI NÓI RA ĐƯỢC LỖI, KHÔNG ĐỂ TRANG TRẮNG.
 * ==========================================================================================
 * Anh Thắng 28/08/2026 gặp "Đã có một lỗi nghiêm trọng" ba lần trong một ngày — nút Xuất Excel,
 * màn Bảng công, khối Thêm người mới. Lần đầu tìm ra chỗ hỏng CHỈ VÌ có try/catch ở đúng nút
 * ấy: câu lỗi nói thẳng tệp nào dòng nào, sửa xong trong một lượt.
 */
$src_pv = file_get_contents( $goc . '/wordpress/vhcp-cham-cong/includes/class-vhcc-web.php' );
t( '🔴 phuc_vu() bọc cả trang trong try/catch',
	preg_match( '/function phuc_vu\(\)\s*\{\s*try\s*\{/', $src_pv ) === 1 );
t( 'và bắt Throwable, không chỉ Exception',
	strpos( $src_pv, 'catch ( \\Throwable $e )' ) !== false );
/* ⚠️ Trang báo hỏng phải nói TỆP NÀO, DÒNG NÀO — đó là thứ duy nhất rút ngắn được một vòng
   đoán mò. Một câu "có lỗi xảy ra" thì y hệt trang trắng. */
t( '🔴 trang báo hỏng nói ra tệp và dòng',
	strpos( $src_pv, 'basename( $e->getFile() )' ) !== false
	&& strpos( $src_pv, '$e->getLine()' ) !== false );
t( 'và in bản đang chạy để biết máy đang dùng bản nào',
	strpos( $src_pv, 'VHCC_VERSION' ) !== false );
/* ⚠️ KHÔNG in dấu vết gọi hàm: dài, khó đọc, và lộ đường dẫn máy chủ. */
t( '🔴 KHÔNG in dấu vết gọi hàm ra trang',
	strpos( $src_pv, 'getTraceAsString' ) === false );

/* Chạy thật: ném một lỗi từ trong màn rồi xem trang có nói ra không. */
$_COOKIE = array( VHCC_Web::COOKIE => VHCC_Auth::phat_token( 'A', 'Admin', 'TUTU_BT', 'ADH' ) );
$_GET = array( 'man' => 'nem-loi-thu' );
ob_start(); VHCC_Web::phuc_vu(); $h_thu = ob_get_clean();
$_GET = array(); $_COOKIE = array();
t( 'màn không có thật thì vẫn vẽ được trang, không trắng', '' !== $h_thu );


/* ==========================================================================================
 * 🔴 ĐẨY NGƯỜI SANG HỆ VẬN HÀNH CHI PHÍ.
 * ==========================================================================================
 * Anh Thắng 28/08/2026: *"bên quản lý nhân sự chưa cho đẩy nhân sự sang vận hành chi phí"*, rồi
 * *"Đồng bộ nhân sự với hệ thống vận hành chi phí luôn nhé em"*.
 *
 * Khác hệ ghế ở một điểm cốt tử: sổ `CH_NguoiDung` bên chi phí ĐANG CHẠY, có người thật đang gõ
 * PIN hằng ngày. Nên mọi phép thử dưới đây xoay quanh một câu: đẩy một người có làm hỏng hàng
 * của người khác không.
 */
vhcc_dung_bang();
delete_option( VHCC_DayChiPhi::O_DA_DAY );
VHCP_Cfg::write( VHCP_Cfg::USER, array(
	array( 'Admin', '1111', 'Admin', '', '1411', 'NV001', '', 'HN', 'tất cả' ),
	array( 'Kế Toán Chị Nhân', '2222', 'Kế toán cá nhân', '', '1421', 'NV009', '', '', '' ),
) );
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CP1', 'ho_ten' => 'Người Đẩy Chi Phí',
	'cua_hang' => 'TUTU_BT', 'chuc_vu' => 'Thu ngân', 'pin_dang_nhap' => '778899',
	'trang_thai_lam_viec' => 'Đang làm' ) );

teq( 'chưa đẩy thì ô trống', '', VHCC_DayChiPhi::o( 'CP1' ) );
$r_cp = VHCC_DayChiPhi::dat( $U_AD, 'CP1', 'mo' );
t( '🔴 đẩy được sang chi phí', ! empty( $r_cp['ok'] ), $r_cp );
teq( 'và ô thành đã đẩy', 'mo', VHCC_DayChiPhi::o( 'CP1' ) );

$so_cp = VHCP_Cfg::read( VHCP_Cfg::USER );
teq( '🔴 sổ bên ấy thêm ĐÚNG một hàng', 3, count( $so_cp ) );
$hang_cp = null;
foreach ( $so_cp as $x ) { if ( 'Người Đẩy Chi Phí' === $x[0] ) { $hang_cp = $x; } }
t( 'hàng mới mang đúng tên', null !== $hang_cp, $so_cp );
teq( 'và đúng PIN chấm công', '778899', (string) $hang_cp[1] );
teq( 'cơ sở theo hồ sơ', 'TUTU_BT', (string) $hang_cp[3] );
/* 🔴 CỬA HÀNG TRƯỞNG -> 'Nhân viên', KHÔNG phải 'Quản lý': bên chi phí 'Quản lý' duyệt được chi
   của MỌI cơ sở, mà cửa hàng trưởng là người ĐỀ NGHỊ chi. */
teq( 'nhân viên sang vai Nhân viên', 'Nhân viên', (string) $hang_cp[2] );
VHCC_NhanSu::dat_vai_tro( $U_AD, 'CP1', 'Cửa hàng trưởng' );
VHCC_DayChiPhi::dong_bo( 'CP1' );
$hang_cp = null;
foreach ( VHCP_Cfg::read( VHCP_Cfg::USER ) as $x ) { if ( 'Người Đẩy Chi Phí' === $x[0] ) { $hang_cp = $x; } }
teq( '🔴 cửa hàng trưởng sang vai Nhân viên, KHÔNG phải Quản lý', 'Nhân viên', (string) $hang_cp[2] );
teq( 'Admin thì sang Admin', 'Admin', VHCC_DayChiPhi::vai_chi_phi( 'Admin' ) );
teq( 'Kế toán sang Kế toán cá nhân', 'Kế toán cá nhân', VHCC_DayChiPhi::vai_chi_phi( 'Kế toán' ) );
teq( 'Quản lý sang Quản lý', 'Quản lý', VHCC_DayChiPhi::vai_chi_phi( 'Quản lý' ) );

/* 🔴 KHÔNG ĐỤNG HÀNG CỦA NGƯỜI KHÁC. Ghi đè cả sổ là xoá sạch PIN của những người bên ấy tự
   khai — và họ chỉ phát hiện ra lúc đứng gõ PIN vào sáng hôm sau. */
$ad_cp = null;
foreach ( VHCP_Cfg::read( VHCP_Cfg::USER ) as $x ) { if ( 'Admin' === $x[0] ) { $ad_cp = $x; } }
teq( '🔴 hàng Admin bên ấy còn nguyên PIN', '1111', (string) $ad_cp[1] );
teq( 'và còn nguyên TK Có do kế toán khai', '1411', (string) $ad_cp[4] );
teq( 'và Mã đối tượng', 'NV001', (string) $ad_cp[5] );

/* 🔴 ĐỔI PIN BÊN NÀY THÌ BẢN SAO PHẢI THEO — không thì người ta gõ PIN mới và không vào được. */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CP1', 'pin_dang_nhap' => '990011' ) );
VHCC_DayChiPhi::dong_bo( 'CP1' );
$hang_cp = null;
foreach ( VHCP_Cfg::read( VHCP_Cfg::USER ) as $x ) { if ( 'Người Đẩy Chi Phí' === $x[0] ) { $hang_cp = $x; } }
teq( '🔴 bản sao bên chi phí theo PIN mới', '990011', (string) $hang_cp[1] );
/* 🔴 CẬP NHẬT PHẢI GIỮ NGUYÊN CỘT CỦA KẾ TOÁN. TK Có · Mã đối tượng · Đơn vị · Xem đơn vị là
   bảng khai bên ấy — sổ nhân sự không biết và không được đoán. Dựng lại cả hàng là kế toán mất
   bảng khai của mình mà không ai báo. */
$wpdb->query( 'SELECT 1' );
$so_ke = VHCP_Cfg::read( VHCP_Cfg::USER );
foreach ( $so_ke as $i_ke => $x_ke ) {
	if ( 'Người Đẩy Chi Phí' === $x_ke[0] ) {
		$so_ke[ $i_ke ][4] = '1388';
		$so_ke[ $i_ke ][5] = 'NV777';
		$so_ke[ $i_ke ][7] = 'HCM';
	}
}
VHCP_Cfg::write( VHCP_Cfg::USER, $so_ke );
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CP1', 'pin_dang_nhap' => '445566' ) );
VHCC_DayChiPhi::dong_bo( 'CP1' );
$hang_cp = null;
foreach ( VHCP_Cfg::read( VHCP_Cfg::USER ) as $x ) { if ( 'Người Đẩy Chi Phí' === $x[0] ) { $hang_cp = $x; } }
teq( 'PIN đã theo bản gốc', '445566', (string) $hang_cp[1] );
teq( '🔴 nhưng TK Có của kế toán còn nguyên', '1388', (string) $hang_cp[4] );
teq( 'và Mã đối tượng còn nguyên', 'NV777', (string) $hang_cp[5] );
teq( 'và Đơn vị còn nguyên', 'HCM', (string) $hang_cp[7] );

/* 🔴 PIN NẠP TỪ SHEETS CŨ RA "1234.0" — rửa đuôi, không thì bên kia nhận một chuỗi không ai gõ
   được, mà màn hình vẫn báo đã đẩy xong. */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CP1', 'pin_dang_nhap' => '223344.0' ) );
VHCC_DayChiPhi::dong_bo( 'CP1' );
$hang_cp = null;
foreach ( VHCP_Cfg::read( VHCP_Cfg::USER ) as $x ) { if ( 'Người Đẩy Chi Phí' === $x[0] ) { $hang_cp = $x; } }
teq( '🔴 PIN kiểu 223344.0 rửa thành 223344', '223344', (string) $hang_cp[1] );
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CP1', 'pin_dang_nhap' => '990011' ) );
VHCC_DayChiPhi::dong_bo( 'CP1' );
teq( 'và vẫn chỉ một hàng cho người ấy', 3, count( VHCP_Cfg::read( VHCP_Cfg::USER ) ) );

/* 🔴 PIN TRÙNG NGƯỜI KHÁC BÊN ẤY LÀ HAI NGƯỜI CHUNG MỘT CỬA — cổng đăng nhập tra theo PIN. */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CP2', 'ho_ten' => 'Người Trùng PIN',
	'cua_hang' => 'TUTU_BT', 'pin_dang_nhap' => '1111', 'trang_thai_lam_viec' => 'Đang làm' ) );
/* 🔴 SỔ NHÂN SỰ THẮNG, HÀNG BÊN KIA BỊ XOÁ PIN — anh Thắng chốt 28/08/2026:
   *"Sau khi đẩy qua sẽ lấy PIN bên nhân sự luôn"*, và khi được hỏi phải làm gì với hàng bị
   trùng thì anh chọn xoá PIN của hàng ấy.
   Vì sao không để hai hàng cùng PIN: cổng đăng nhập bên ấy tra THEO PIN, nên ai gõ vào cũng rơi
   vào hàng đứng trước — một trong hai người mất tài khoản mà không có gì báo. */
$r_trung = VHCC_DayChiPhi::dat( $U_AD, 'CP2', 'mo' );
t( '🔴 PIN trùng thì VẪN đẩy được', ! empty( $r_trung['ok'] ), $r_trung );
t( 'và kể tên người bị xoá PIN ra',
	in_array( 'Admin', (array) $r_trung['mat_pin'], true ), $r_trung );
$ad_mat = null;
foreach ( VHCP_Cfg::read( VHCP_Cfg::USER ) as $x ) { if ( 'Admin' === $x[0] ) { $ad_mat = $x; } }
teq( '🔴 hàng Admin bên ấy bị xoá PIN', '', (string) $ad_mat[1] );
/* ⚠️ XOÁ PIN, KHÔNG XOÁ HÀNG: hàng ấy mang TK Có / Mã đối tượng do kế toán khai — xoá hàng là
   mất bảng khai ấy, mà cấp lại PIN thì dùng lại được ngay. */
t( '🔴 nhưng HÀNG vẫn còn', null !== $ad_mat, VHCP_Cfg::read( VHCP_Cfg::USER ) );
teq( 'và TK Có của kế toán còn nguyên', '1411', (string) $ad_mat[4] );
$cp2 = null;
foreach ( VHCP_Cfg::read( VHCP_Cfg::USER ) as $x ) { if ( 'Người Trùng PIN' === $x[0] ) { $cp2 = $x; } }
teq( 'người vừa đẩy giữ đúng PIN bên nhân sự', '1111', (string) $cp2[1] );
/* ⚠️ VÀ KHÔNG ĐƯỢC KỂ TÊN CHÍNH NGƯỜI VỪA ĐẨY vào danh sách "bị xoá PIN". Hàng của họ có bị
   chạm qua trong lúc ghi cũng không sao — nhưng nói ra là câu báo bảo anh Thắng đi cấp PIN mới
   cho đúng người vừa được đẩy, tức là bảo anh đi sửa một thứ không hỏng. */
$r_lai = VHCC_DayChiPhi::dat( $U_AD, 'CP2', 'mo' );
teq( '🔴 đẩy lại người đã đẩy thì không ai bị xoá PIN', 0,
	count( (array) $r_lai['mat_pin'] ) );
$cp2b = null;
foreach ( VHCP_Cfg::read( VHCP_Cfg::USER ) as $x ) { if ( 'Người Trùng PIN' === $x[0] ) { $cp2b = $x; } }
teq( 'và PIN của chính họ còn nguyên', '1111', (string) $cp2b[1] );
VHCC_DayChiPhi::dat( $U_AD, 'CP2', '' );
/* Trả lại PIN cho Admin để những phép thử sau chạy trên cảnh cũ. */
$so_tl = VHCP_Cfg::read( VHCP_Cfg::USER );
foreach ( $so_tl as $i_tl => $x_tl ) { if ( 'Admin' === $x_tl[0] ) { $so_tl[ $i_tl ][1] = '1111'; } }
VHCP_Cfg::write( VHCP_Cfg::USER, $so_tl );

/* Chưa có PIN thì không đẩy được — bên ấy đăng nhập bằng PIN, hàng không PIN là hàng chết. */
VHCC_NhanSu::luu_ho_so( $U_AD, array( 'ma_nv' => 'CP3', 'ho_ten' => 'Người Không PIN',
	'cua_hang' => 'TUTU_BT', 'trang_thai_lam_viec' => 'Đang làm' ) );
t( '🔴 chưa có PIN thì chối, và nói ra phải cấp PIN ở đâu',
	empty( ( $r_kp = VHCC_DayChiPhi::dat( $U_AD, 'CP3', 'mo' ) )['ok'] )
	&& strpos( $r_kp['error'], 'Hồ sơ & tài khoản' ) !== false, $r_kp );

/* 🔴 GỠ thì lấy đúng hàng của người ấy ra, không đụng ai khác. */
$r_go = VHCC_DayChiPhi::dat( $U_AD, 'CP1', '' );
t( 'gỡ được', ! empty( $r_go['ok'] ), $r_go );
teq( '🔴 sổ bên ấy về lại hai hàng gốc', 2, count( VHCP_Cfg::read( VHCP_Cfg::USER ) ) );
teq( 'và ô về trống', '', VHCC_DayChiPhi::o( 'CP1' ) );

/* Bậc: đẩy sang màn có ngăn TIỀN nên cần Admin. */
t( '🔴 Kế toán KHÔNG đẩy được', empty( VHCC_DayChiPhi::dat(
	array( 'name' => 'KT', 'role' => 'Kế toán', 'coso' => '' ), 'CP1', 'mo' )['ok'] ) );
t( 'Cửa hàng trưởng càng không', empty( VHCC_DayChiPhi::dat(
	array( 'name' => 'CHT', 'role' => 'Cửa hàng trưởng', 'coso' => 'TUTU_BT' ), 'CP1', 'mo' )['ok'] ) );

/* ---- Trên MÀN Quản lý nhân sự ---- */
$h_cp = vhcc_ns( 'Admin' );
t( '🔴 bảng có cột Vận hành chi phí',
	strpos( $h_cp, 'Vận hành chi phí' ) !== false, substr( $h_cp, 0, 400 ) );
t( 'và có nút Đẩy / Gỡ áp cả cột',
	strpos( $h_cp, 'value="' . VHCC_DayChiPhi::COT . '|mo"' ) !== false
	&& strpos( $h_cp, 'value="' . VHCC_DayChiPhi::COT . '|"' ) !== false, $h_cp );
t( 'mỗi hàng có ô chọn của cột ấy',
	strpos( $h_cp, '][' . VHCC_DayChiPhi::COT . ']' ) !== false, $h_cp );
/* 🔴 CỘT NÀY KHÔNG PHẢI NGOẠI LỆ QUYỀN — phải tách khỏi bảng trước khi phần còn lại đi vào sổ
   ngoại lệ, không thì `VHCC_Cong::dat()` chối nó bằng câu "không có trang tên chi_phi" và người
   bấm không hiểu vì sao ô mình vừa chọn lại mất. */
$_POST = array( 'o' => array( 'CP1' => array( VHCC_DayChiPhi::COT => 'mo' ) ) );
list( $sach_t, $ghe_t, $cp_t ) = vhcc_goi_rieng( 'VHCC_TrangNS', 'tach_ghe',
	array( array( 'CP1' => array( VHCC_DayChiPhi::COT => 'mo', 'cham_cong' => 'khoa' ) ) ) );
$_POST = array();
teq( '🔴 cột chi phí tách ra khỏi bảng ngoại lệ', 'mo',
	isset( $cp_t['CP1'] ) ? $cp_t['CP1'] : '(thiếu)' );
t( 'và KHÔNG còn nằm trong phần đi vào sổ quyền',
	! isset( $sach_t['CP1'][ VHCC_DayChiPhi::COT ] ), $sach_t );
t( 'trong khi ô quyền thật vẫn đi tiếp',
	isset( $sach_t['CP1']['cham_cong'] ), $sach_t );

delete_option( VHCC_DayChiPhi::O_DA_DAY );
vhcc_dung_bang();


/* ==================================================================================
   XOÁ HẲN MỘT HỒ SƠ NGAY TRÊN TRANG QUẢN LÝ NHÂN SỰ

   Anh Thắng 28/08/2026, sau khi thử thêm một người từ màn cửa hàng rồi thấy hàng rác
   `TAM-…` nằm lại trong sổ: *"Giờ anh muốn xóa nhân viên đó đi"*.

   `VHCC_NhanSu::xoa_ho_so()` vốn đã có, nhưng lời gọi DUY NHẤT nằm ở wp-admin — tức là muốn
   xoá một hàng rác thì phải rời trang, vào bảng quản trị WordPress. Nay có nút ngay tại hàng.

   🔴 XOÁ ĐI HAI NHỊP. Nhịp một là một ĐƯỜNG DẪN (GET) chỉ mở ra lời hỏi — bấm nhầm không mất
      gì. Nhịp hai là nút gửi. Không dùng hộp thoại xác nhận bằng JavaScript: cả trang này
      không có lấy một dòng script, mà thứ bộ thử PHP không với tới thì không phải là chốt.
   ================================================================================== */
vhcc_dung_bang();
$xh_ad = array( 'name' => 'Sếp', 'role' => 'Admin', 'coso' => 'TUTU_BT' );
VHCC_NhanSu::luu_ho_so( $xh_ad, array( 'ma_nv' => 'XH1', 'ho_ten' => 'Người Bỏ',
	'cua_hang' => 'TUTU_BT', 'vai_tro' => 'Nhân viên' ) );
VHCC_NhanSu::luu_ho_so( $xh_ad, array( 'ma_nv' => 'XH2', 'ho_ten' => 'Người Có Công',
	'cua_hang' => 'TUTU_BT', 'vai_tro' => 'Nhân viên' ) );
$wpdb->insert( VHCC_DB::t( 'cham_cong' ), array( 'ma_nv' => 'XH2', 'ho_ten' => 'Người Có Công',
	'coso' => 'TUTU_BT', 'ngay' => '2026-07-01', 'hau_to' => '',
	'gio_vao_giay' => VHCC_DB::giay( '08:00' ), 'gio_ra_giay' => VHCC_DB::giay( '17:00' ) ) );

teq( 'đếm lượt chấm dùng CHUNG một phép với lời chối của xoa_ho_so', 1,
	VHCC_NhanSu::so_luot_cham( 'XH2' ) );
teq( 'người chưa chấm lần nào thì đếm ra 0', 0, VHCC_NhanSu::so_luot_cham( 'XH1' ) );

/* Nhịp một: bảng phải có đường "xoá", và chỉ Admin thấy. */
$h_xh_ad = vhcc_ns( 'Admin' );
t( 'Admin thấy đường xoá ở hàng người', strpos( $h_xh_ad, '>xoá 🗑</a>' ) !== false, $h_xh_ad );
$h_xh_kt = vhcc_ns( 'Kế toán' );
t( '🔴 Kế toán KHÔNG thấy đường xoá', strpos( $h_xh_kt, '>xoá 🗑</a>' ) === false, $h_xh_kt );
t( 'nhưng Kế toán vẫn vào được trang (chỉ mất đúng đường xoá)',
	strpos( $h_xh_kt, 'sửa ▾' ) !== false, $h_xh_kt );
/* 🔴 GIẤU ĐƯỜNG DẪN KHÔNG PHẢI LÀ GÁC CỬA. `?xoa_o=` gõ tay được, nên hàng hỏi phải TỰ hỏi
   quyền chứ không dựa vào việc người ta không tìm ra đường bấm. */
$h_kt_hoi = vhcc_ns( 'Kế toán', array( 'xoa_o' => 'XH1' ) );
t( '🔴 Kế toán gõ tay ?xoa_o= cũng KHÔNG mở được hàng hỏi',
	strpos( $h_kt_hoi, 'name="xoa_ma"' ) === false, $h_kt_hoi );

/* Nhịp hai: mở lời hỏi bằng `?xoa_o=` — chưa xoá gì cả. */
$h_hoi = vhcc_ns( 'Admin', array( 'xoa_o' => 'XH1' ) );
t( 'mở lời hỏi trước khi xoá', strpos( $h_hoi, 'Xoá hẳn hồ sơ XH1' ) !== false, $h_hoi );
t( 'lời hỏi nói rõ là không lấy lại được',
	strpos( $h_hoi, 'không lấy lại được' ) !== false, $h_hoi );
t( 'và chỉ ra đường ĐÚNG thay cho xoá: đổi trạng thái sang Đã nghỉ',
	strpos( $h_hoi, 'Đã nghỉ' ) !== false, $h_hoi );
t( 'có nút Thôi để rút lui', strpos( $h_hoi, 'Thôi, giữ lại' ) !== false, $h_hoi );
t( 'nút xoá mang THEO mã, không dùng ô ẩn dùng chung',
	strpos( $h_hoi, 'name="xoa_ma" value="XH1"' ) !== false, $h_hoi );
t( '🔴 chỉ MỞ lời hỏi thôi thì hồ sơ vẫn còn nguyên', (bool) VHCC_NhanSu::ho_so( 'XH1' ) );

/* Lời hỏi phải nói TRƯỚC con số sẽ khiến hệ chối — biết trước hơn bấm rồi mới đọc lời từ chối. */
$h_hoi2 = vhcc_ns( 'Admin', array( 'xoa_o' => 'XH2' ) );
t( 'người còn chấm công thì lời hỏi báo trước là sẽ bị chối',
	strpos( $h_hoi2, 'còn 1 lượt chấm công' ) !== false, $h_hoi2 );
t( 'người chưa chấm lần nào thì lời hỏi nói là xoá không bỏ rơi dữ liệu',
	strpos( $h_hoi, 'chưa có lượt chấm công nào' ) !== false, $h_hoi );

/* 🔴 CÒN CHẤM CÔNG THÌ CHỐI — bảng lương tháng cũ sẽ có mã mà không tra ra tên. */
$b_xh2 = VHCC_TrangNS::lam_viec( 'xoa_hs', $xh_ad );
$_POST = array( 'xoa_ma' => 'XH2' );
$b_xh2 = VHCC_TrangNS::lam_viec( 'xoa_hs', $xh_ad );
$_POST = array();
t( 'xoá người còn chấm công bị CHỐI', isset( $b_xh2[0]['loi'] ), $b_xh2 );
t( 'và hồ sơ ấy vẫn còn', (bool) VHCC_NhanSu::ho_so( 'XH2' ) );

/* 🔴 BẤM NÚT THẬT, KHÔNG CHỈ GỌI HÀM. Nút Xoá không gửi `viec` — nó mang tên riêng `xoa_ma`,
   nên bộ điều phối phải tự nhận ra. Quên khai một dòng ở đó thì nút bấm xong KHÔNG XẢY RA GÌ
   CẢ, mà mọi phép thử gọi thẳng `lam_viec('xoa_hs', …)` vẫn xanh. Đúng cái bẫy đã cắn một lần
   với nút Thêm nhân viên. */
VHCC_NhanSu::luu_ho_so( $xh_ad, array( 'ma_nv' => 'XH3', 'ho_ten' => 'Người Bấm Nút',
	'cua_hang' => 'TUTU_BT', 'vai_tro' => 'Nhân viên' ) );
vhcc_ns( 'Admin', array(), array( 'xoa_ma' => 'XH3' ) );
t( '🔴 bấm ĐÚNG cái nút trên trang thì hồ sơ mất thật', ! VHCC_NhanSu::ho_so( 'XH3' ) );

/* Kế toán bấm thẳng vào việc (gõ tay POST) cũng phải bị chối — chốt nằm ở lõi, không ở nút vẽ. */
$xh_kt = array( 'name' => 'KT', 'role' => 'Kế toán', 'coso' => 'TUTU_BT' );
$_POST = array( 'xoa_ma' => 'XH1' );
$b_xh_kt = VHCC_TrangNS::lam_viec( 'xoa_hs', $xh_kt );
$_POST = array();
t( '🔴 Kế toán gõ tay lệnh xoá cũng bị chối', isset( $b_xh_kt[0]['loi'] ), $b_xh_kt );
t( 'và hồ sơ vẫn còn nguyên', (bool) VHCC_NhanSu::ho_so( 'XH1' ) );

/* Thiếu mã thì nói thiếu mã, đừng xoá bừa. */
$_POST = array( 'xoa_ma' => '' );
$b_xh_r = VHCC_TrangNS::lam_viec( 'xoa_hs', $xh_ad );
$_POST = array();
t( 'thiếu mã thì báo thiếu mã', isset( $b_xh_r[0]['loi'] )
	&& strpos( $b_xh_r[0]['loi'], 'Thiếu Mã NV' ) !== false, $b_xh_r );

/* 🔴 XOÁ BỊ CHỐI THÌ KHÔNG ĐƯỢC GỠ GÌ HẾT. Gỡ bản sao trước khi biết xoá có đi qua được không
   thì gặp người còn chấm công: hồ sơ vẫn nguyên, mà đường đăng nhập của họ đã mất — im lặng,
   và họ chỉ biết vào sáng hôm sau. */
update_option( VHCC_DayChiPhi::O_DA_DAY, array( 'XH2' => 'Người Có Công' ) );
update_option( VHCC_DayGhe::O_SO, array( array( 'ten' => 'Người Có Công', 'pin' => '778899',
	'vaiTro' => 'Nhân viên', 'coso' => 'TUTU_BT', 'maNV' => 'XH2' ) ) );
$_POST = array( 'xoa_ma' => 'XH2' );
VHCC_TrangNS::lam_viec( 'xoa_hs', $xh_ad );
$_POST = array();
t( '🔴 xoá bị chối thì bản sao bên Vận hành chi phí VẪN CÒN', VHCC_DayChiPhi::da_day( 'XH2' ) );
t( '🔴 và bản sao bên hệ Ghế cũng vẫn còn', VHCC_DayGhe::da_day( 'XH2' ) );
delete_option( VHCC_DayGhe::O_SO );

/* Xoá thật — và gỡ luôn bản sao ở hai hệ kia, kẻo còn đường đăng nhập trỏ vào người đã mất hồ sơ. */
update_option( VHCC_DayChiPhi::O_DA_DAY, array( 'XH1' => 'Người Bỏ' ) );
update_option( VHCC_DayGhe::O_SO, array( array( 'ten' => 'Người Bỏ', 'pin' => '445566',
	'vaiTro' => 'Nhân viên', 'coso' => 'TUTU_BT', 'maNV' => 'XH1' ) ) );
t( 'dựng sẵn: XH1 đang có bản sao bên hệ Ghế', VHCC_DayGhe::da_day( 'XH1' ) );
$_POST = array( 'xoa_ma' => 'XH1' );
$b_xh1 = VHCC_TrangNS::lam_viec( 'xoa_hs', $xh_ad );
$_POST = array();
t( 'Admin xoá được hồ sơ chưa có chấm công', isset( $b_xh1[0]['ok'] ), $b_xh1 );
t( 'lời báo nhắc luôn tên người vừa xoá', isset( $b_xh1[0]['ok'] )
	&& strpos( $b_xh1[0]['ok'], 'Người Bỏ' ) !== false, $b_xh1 );
t( '🔴 hồ sơ biến mất thật', ! VHCC_NhanSu::ho_so( 'XH1' ) );
t( '🔴 và bản sao bên Vận hành chi phí cũng được gỡ', ! VHCC_DayChiPhi::da_day( 'XH1' ),
	get_option( VHCC_DayChiPhi::O_DA_DAY ) );
t( '🔴 bản sao bên hệ Ghế cũng được gỡ', ! VHCC_DayGhe::da_day( 'XH1' ),
	get_option( VHCC_DayGhe::O_SO ) );
t( 'và lời báo kể ra đã gỡ khỏi những đâu', isset( $b_xh1[0]['ok'] )
	&& strpos( $b_xh1[0]['ok'], 'hệ Ghế' ) !== false
	&& strpos( $b_xh1[0]['ok'], 'Vận hành chi phí' ) !== false, $b_xh1 );

delete_option( VHCC_DayGhe::O_SO );
delete_option( VHCC_DayChiPhi::O_DA_DAY );
vhcc_dung_bang();


/* ==================================================================================
   LÀM TRÒN GIỜ CÔNG THEO KHUNG CA

   Anh Thắng 28/08/2026, gửi ảnh lưới đầy 5.1 · 6.9 · 8.2 · 13.1: *"Chưa làm tròn giờ theo
   ca"*. Và 27/08 đã nói luật: *"lấy giờ ca làm giờ công, cứ chấm trong ca (bao gồm vào ra)
   phần công đủ giờ (nhưng nếu bạn nào chấm thiếu giờ thì hiện cảnh báo ô vàng)"*.

   🔴 Phần lõi là HÀM THUẦN `VHCC_Ca::lam_tron` — thử được bằng con số trần, không cần dựng
      bảng, không cần đăng nhập. Chỗ nào tính ra tiền mà chỉ soi được qua HTML thì sớm muộn
      không ai dám sửa.
   ================================================================================== */
$lt_ca = array(
	array( 'ten' => 'Ca 1', 'tu' => '06:00', 'den' => '14:00', 'tuW' => '', 'denW' => '' ),
	array( 'ten' => 'Ca 2', 'tu' => '14:00', 'den' => '22:00', 'tuW' => '', 'denW' => '' ),
	array( 'ten' => 'Ca 3', 'tu' => '22:00', 'den' => '06:00', 'tuW' => '', 'denW' => '' ),
);
teq( 'độ dài ca thường tính đúng', 480, VHCC_Ca::dai_ca( $lt_ca[0] ) );
teq( '🔴 ca QUA NỬA ĐÊM cũng ra 8 tiếng, không ra số âm', 480, VHCC_Ca::dai_ca( $lt_ca[2] ) );

/* Vào sớm 3 phút, về muộn 3 phút -> giờ thô 8.1, giờ theo ca đúng 8. */
$lt = VHCC_Ca::lam_tron( $lt_ca, VHCC_DB::giay( '05:57' ), VHCC_DB::giay( '14:03' ), false, 15 );
teq( '🔴 bấm sớm/muộn vài phút vẫn đúng MỘT ca, không thành 8.1', 480, $lt['phut'] );
t( 'và không kêu thiếu giờ', ! $lt['thieu'] );

/* Vào trễ 10 phút, ngưỡng 15 -> vẫn đủ ca, không cảnh báo. */
$lt = VHCC_Ca::lam_tron( $lt_ca, VHCC_DB::giay( '06:10' ), VHCC_DB::giay( '14:00' ), false, 15 );
teq( 'trễ TRONG ngưỡng thì làm tròn lên đủ ca', 480, $lt['phut'] );
t( 'có ghi nhận là đã làm tròn', ! empty( $lt['tron'] ) );
t( 'và không kêu thiếu', ! $lt['thieu'] );

/* Vào trễ 40 phút, ngưỡng 15 -> tính đúng phần có mặt, VÀ kêu thiếu. */
$lt = VHCC_Ca::lam_tron( $lt_ca, VHCC_DB::giay( '06:40' ), VHCC_DB::giay( '14:00' ), false, 15 );
teq( '🔴 trễ QUÁ ngưỡng thì KHÔNG được làm tròn lên', 440, $lt['phut'] );
teq( 'và kêu đúng một ca thiếu', 1, count( $lt['thieu'] ) );
teq( 'nói đúng ca nào', 'Ca 1', $lt['thieu'][0]['ten'] );
teq( 'và thiếu bao nhiêu phút', 40, $lt['thieu'][0]['phut'] );

/* 🔴 BIÊN: thiếu ĐÚNG BẰNG ngưỡng vẫn là "đủ ca". Ngưỡng 15 nghĩa là *"trễ tới 15 phút thì
   thôi"*, không phải *"trễ tới 14 phút"* — đổi `<=` thành `<` là mỗi ngày trễ đúng 15 phút của
   mỗi người bị trừ một ca, và không ai nhìn ra vì con số trông vẫn hợp lý. */
$lt = VHCC_Ca::lam_tron( $lt_ca, VHCC_DB::giay( '06:15' ), VHCC_DB::giay( '14:00' ), false, 15 );
teq( 'thiếu ĐÚNG BẰNG ngưỡng vẫn tính đủ ca', 480, $lt['phut'] );
t( 'và không kêu thiếu', ! $lt['thieu'] );
$lt = VHCC_Ca::lam_tron( $lt_ca, VHCC_DB::giay( '06:16' ), VHCC_DB::giay( '14:00' ), false, 15 );
teq( 'quá ngưỡng một phút là hết đủ ca', 464, $lt['phut'] );

/* Ngưỡng 0 = "phải đủ giờ mới là đủ ca" — con số 0 là một lựa chọn thật, không phải chưa khai. */
$lt = VHCC_Ca::lam_tron( $lt_ca, VHCC_DB::giay( '06:05' ), VHCC_DB::giay( '14:00' ), false, 0 );
teq( 'ngưỡng 0 thì thiếu 5 phút cũng là thiếu', 475, $lt['phut'] );
t( 'và kêu lên', (bool) $lt['thieu'] );

/* ==================================================================================
   🔴 CHẠM VÀO MỘT CA KHÔNG PHẢI LÀ NHẬN CA ĐÓ — ca thật anh Thắng gửi ảnh 28/08/2026.

   Khung ca của cửa hàng ấy: Ca 1 09–14 · Ca 2 14–17 · Ca 3 17–22. Bạn LÊ PHẠM THUỲ VÂN vào
   13:01, ra 21:28. Bản trước tách ra ba ca rồi kêu *"thiếu 4h 1m của Ca 1"*.

   Anh nói thẳng: *"giờ như này là bạn đang làm từ ca 2 đến ca 3. lấy giờ ca tính đầu và đuôi
   thì biết bạn đó bắt đầu từ ca nào"*. Đúng: 59 phút chạm đuôi Ca 1 là VÀO SỚM trước Ca 2,
   không phải một ca làm dở. Kêu thiếu ở đó là biến người đi sớm thành người đi thiếu — và cái
   ô vàng ấy sai tới mức chỉ vài ngày là không ai nhìn nó nữa.
   ================================================================================== */
$ca_vn = array(
	array( 'ten' => 'Ca 1', 'tu' => '09:00', 'den' => '14:00', 'tuW' => '', 'denW' => '' ),
	array( 'ten' => 'Ca 2', 'tu' => '14:00', 'den' => '17:00', 'tuW' => '', 'denW' => '' ),
	array( 'ten' => 'Ca 3', 'tu' => '17:00', 'den' => '22:00', 'tuW' => '', 'denW' => '' ),
);
$vn = VHCC_Ca::lam_tron( $ca_vn, VHCC_DB::giay( '13:01' ), VHCC_DB::giay( '21:28' ), false, 15 );
teq( '🔴 nhận ca ĐẦU là Ca 2, không phải Ca 1', 'Ca 2', $vn['ca_dau'] );
teq( 'và ca CUỐI là Ca 3', 'Ca 3', $vn['ca_cuoi'] );
teq( '🔴 KHÔNG còn kêu thiếu 4h1m của Ca 1 — chỉ còn một chỗ thiếu', 1, count( $vn['thieu'] ) );
teq( 'và chỗ thiếu ấy là của Ca 3', 'Ca 3', $vn['thieu'][0]['ten'] );
teq( 'thiếu đúng 32 phút', 32, $vn['thieu'][0]['phut'] );
/* Ca 2 trọn 3h + Ca 3 có mặt 4h28m = 7h28m. 59 phút chạm Ca 1 KHÔNG cộng — đây là "lấy giờ ca
   làm giờ công", mà ca ấy người ta không nhận. */
teq( 'giờ công = Ca 2 trọn + phần có mặt của Ca 3', 448, $vn['phut'] );
teq( 'và 59 phút chạm rìa được kể riêng, không nuốt', 59, $vn['ngoai_dai'] );
teq( 'kể đúng tên ca bị chạm', 'Ca 1', $vn['ria'][0]['ten'] );

/* Hàm chọn dải là hàm THUẦN — hỏi thẳng được bằng con số trần. */
$tc_vn = VHCC_Ca::tach( $ca_vn, VHCC_DB::giay( '13:01' ), VHCC_DB::giay( '21:28' ) );
teq( 'lượt ấy vẫn CHẠM cả ba ca', 3, count( $tc_vn['ds'] ) );
$dai_vn = VHCC_Ca::dai_nhan( $tc_vn, VHCC_DB::giay( '13:01' ), VHCC_DB::giay( '21:28' ) );
teq( 'nhưng dải NHẬN bắt đầu từ ca thứ hai', 1, $dai_vn[0] );
teq( 'và kết thúc ở ca thứ ba', 2, $dai_vn[1] );

/* 🔴 CA KHAI KHÔNG THEO THỨ TỰ THỜI GIAN LÀ CHUYỆN CÓ THẬT — người khai gõ ca chiều trước ca
   sáng, và không có gì bắt họ gõ đúng thứ tự. Lúc ấy ca đầu có chỉ số LỚN HƠN ca cuối; không
   đảo lại thì dải thành rỗng, mọi ca rơi ra "ngoài dải", và cả ngày công của người ta thành 0
   — trong khi bảng vẫn trông bình thường. */
$ca_nguoc = array(
	array( 'ten' => 'Ca chiều', 'tu' => '14:00', 'den' => '22:00', 'tuW' => '', 'denW' => '' ),
	array( 'ten' => 'Ca sáng',  'tu' => '06:00', 'den' => '14:00', 'tuW' => '', 'denW' => '' ),
);
$vn_ng = VHCC_Ca::lam_tron( $ca_nguoc, VHCC_DB::giay( '06:00' ), VHCC_DB::giay( '22:00' ), false, 15 );
teq( '🔴 ca khai ngược thứ tự vẫn ra đủ 16 tiếng, không thành 0', 960, $vn_ng['phut'] );
teq( 'và không có giờ nào bị đẩy ra ngoài dải', 0, $vn_ng['ngoai_dai'] );

/* Người nhận ĐÚNG Ca 1 thì vẫn phải kêu như thường — chốt mới không được nuốt cảnh báo thật. */
$vn2 = VHCC_Ca::lam_tron( $ca_vn, VHCC_DB::giay( '09:00' ), VHCC_DB::giay( '13:00' ), false, 15 );
teq( 'người nhận Ca 1 mà về sớm thì VẪN kêu', 1, count( $vn2['thieu'] ) );
teq( 'đúng tên ca', 'Ca 1', $vn2['thieu'][0]['ten'] );
teq( 'và đúng số phút thiếu', 60, $vn2['thieu'][0]['phut'] );

/* 🔴 CA ĐÊM: người vào 21:30 ra 05:30 chạm 30 phút vào Ca 2, nhưng nhận Ca 3. */
$vn3 = VHCC_Ca::lam_tron( $lt_ca, VHCC_DB::giay( '21:30' ), VHCC_DB::giay( '05:30' ) + 86400, false, 15 );
teq( 'ca đêm: nhận ca đầu là Ca 3', 'Ca 3', $vn3['ca_dau'] );
teq( '🔴 KHÔNG kêu thiếu của Ca 2 — 30 phút ấy là vào sớm, không phải ca làm dở',
	'Ca 3', $vn3['thieu'][0]['ten'] );
teq( 'chỉ còn đúng một chỗ thiếu', 1, count( $vn3['thieu'] ) );
/* Vào 21:30 (sớm 30') và ra 05:30 (sớm 30') — họ thiếu đúng 30 phút CUỐI ca đêm. Đó là cảnh
   báo thật, phải giữ. */
teq( 'và đó là 30 phút cuối ca đêm', 30, $vn3['thieu'][0]['phut'] );
teq( 'giờ công là phần có mặt trong ca đêm', 450, $vn3['phut'] );
teq( '30 phút chạm Ca 2 kể riêng, không cộng', 30, $vn3['ngoai_dai'] );

/* Vắt hai ca: 06:00 -> 22:00 là trọn Ca 1 + trọn Ca 2. */
$lt = VHCC_Ca::lam_tron( $lt_ca, VHCC_DB::giay( '05:58' ), VHCC_DB::giay( '22:01' ), false, 15 );
teq( 'vắt hai ca thì cộng trọn cả hai', 960, $lt['phut'] );

/* 🔴 KHUNG CA KHAI LỆCH: cả lượt rơi ra ngoài. KHÔNG được trả 0 — trả 0 là cả tháng của cả cửa
   hàng thành số không, mà bảng vẫn trông bình thường. */
$ca_lech = array( array( 'ten' => 'Ca sáng', 'tu' => '06:00', 'den' => '10:00', 'tuW' => '', 'denW' => '' ) );
$lt = VHCC_Ca::lam_tron( $ca_lech, VHCC_DB::giay( '14:00' ), VHCC_DB::giay( '22:00' ), false, 15 );
teq( '🔴 lượt nằm ngoài mọi ca thì GIỮ NGUYÊN giờ thật, không thành 0', 480, $lt['phut'] );
t( 'và kêu lên là ngoài mọi ca', ! empty( $lt['ngoai_moi_ca'] ) );

/* Lượt chấm hỏng (thiếu giờ ra) thì không có gì để kêu. */
$lt = VHCC_Ca::lam_tron( $lt_ca, VHCC_DB::giay( '06:00' ), null, false, 15 );
teq( 'thiếu giờ ra thì ra 0 phút', 0, $lt['phut'] );
t( 'và KHÔNG kêu "ngoài mọi ca" (không có gì để kêu)', empty( $lt['ngoai_moi_ca'] ) );

/* Ca cuối tuần khai riêng thì độ dài lấy theo giờ cuối tuần. */
$ca_ct = array( array( 'ten' => 'Ca 1', 'tu' => '06:00', 'den' => '14:00',
	'tuW' => '08:00', 'denW' => '12:00' ) );
teq( 'cuối tuần lấy độ dài của khung cuối tuần', 240, VHCC_Ca::dai_ca( $ca_ct[0], true ) );
$lt = VHCC_Ca::lam_tron( $ca_ct, VHCC_DB::giay( '08:03' ), VHCC_DB::giay( '12:00' ), true, 15 );
teq( 'và làm tròn theo khung cuối tuần', 240, $lt['phut'] );

/* ---- Trên MÀN: cơ sở khai "Theo khung ca" thì ô hết số lẻ, thiếu giờ thì ô vàng ---- */
$cs_tron = 'FZ_SC_TRON';
VHCC_Ca::luu( $ADMIN_W, $cs_tron, $lt_ca );
VHCC_Tre::dat( $ADMIN_W, $cs_tron, 15 );
VHCC_Luong::dat_cach_tinh( $ADMIN_W, array( $cs_tron => 'ca' ) );
teq( 'cơ sở khai được kiểu "theo khung ca"', 'ca', VHCC_Luong::cach_tinh( $cs_tron ) );
vhcc_cham( $cs_tron, '2026-07-01', 'TR1', '', '05:57', '14:03' );  /* thô 8.1 -> đúng 8 */
vhcc_cham( $cs_tron, '2026-07-02', 'TR1', '', '06:40', '14:00' );  /* trễ 40 phút -> 7.3 + ô vàng */
vhcc_cham( $cs_tron, '2026-07-03', 'TR1', '', '06:10', '14:00' );  /* trễ 10 phút -> vẫn đủ 8 */
/* ⚠️ Vào bằng TOKEN, không bằng PIN. Khối trước vừa `vhcc_dung_bang()` nên sổ nhân sự trắng —
   đăng nhập bằng PIN lúc này rơi ra màn đăng nhập, và mọi phép thử dưới soi nhầm một trang
   không có bảng nào. */
$h_tron = vhcc_web_nhu2( 'TRAD1', 'Admin', $cs_tron,
	array( 'man' => 'cham', 'ccs' => $cs_tron, 'cth' => '2026-07' ) );
t( '🔴 ô hết số lẻ: 8.1 thành 8', strpos( $h_tron, '>8.1<' ) === false, $h_tron );
t( 'và in ra đúng 8', strpos( $h_tron, '<b>8</b>' ) !== false, $h_tron );
/* Bấm sớm/về muộn: ô bị CẮT xuống đúng ca — chú thích phải nói ra, để còn đối chiếu được với
   giờ máy ghi. */
t( 'chú thích nói giờ công theo ca khác giờ chấm thật',
	strpos( $h_tron, 'giờ công theo ca: 8h (giờ chấm thật 8h 6m)' ) !== false, $h_tron );
/* Trễ 10 phút, ngưỡng 15: ô được làm TRÒN LÊN đủ ca. */
t( 'chú thích nói đã làm tròn lên đủ ca', strpos( $h_tron, 'đã làm tròn lên đủ ca' ) !== false, $h_tron );
/* ⚠️ SOI ĐÚNG CÁI Ô, đừng soi chữ "vang" trong cả trang — bảng màu ở đầu trang có biến
   `--vang`, nên `strpos($html,'vang')` luôn tìm thấy và phép thử xanh vĩnh viễn. */
t( '🔴 ngày trễ quá ngưỡng thì Ô vàng lên',
	preg_match( '/class="oc ca1 vang"/', $h_tron ) === 1, $h_tron );
t( 'còn ngày đủ giờ thì ô KHÔNG vàng',
	preg_match( '/class="oc ca1"[^>]*title="[^"]*8h \(giờ chấm thật 8h 6m\)/', $h_tron ) === 1, $h_tron );
t( 'và chú thích nói thiếu bao nhiêu, của ca nào',
	strpos( $h_tron, 'thiếu 0h 40m của Ca 1' ) !== false, $h_tron );
t( 'khối Cách tính công bày ra lựa chọn mới',
	strpos( vhcc_web_nhu2( 'TRAD1', 'Admin', $cs_tron, array( 'man' => 'cau_hinh' ) ),
		'Theo khung ca (làm tròn)' ) !== false );

/* 🔴 ĐỔI KIỂU LÀ ĐỔI CÁCH ĐỌC, KHÔNG ĐỔI DỮ LIỆU. Trả về "theo giờ" thì số lẻ quay lại y như cũ
   — nếu không thì việc "làm tròn" đã ghi đè lên giờ máy chấm, và giờ gốc mất luôn. */
VHCC_Luong::dat_cach_tinh( $ADMIN_W, array( $cs_tron => 'gio' ) );
$h_tho = vhcc_web_nhu2( 'TRAD1', 'Admin', $cs_tron,
	array( 'man' => 'cham', 'ccs' => $cs_tron, 'cth' => '2026-07' ) );
t( 'trả về theo giờ thì số lẻ quay lại nguyên vẹn', strpos( $h_tho, '>8.1<' ) !== false, $h_tho );


/* ==================================================================================
   XUẤT BẢNG CÔNG RA MỘT TẤM ẢNH (.svg), KÈM GIỜ VÀO – GIỜ RA

   Anh Thắng 28/08/2026: *"Thêm xuất dạng ảnh ra ( kèm thêm giờ vào ra nữa nhé )"*.

   🔴 SOI TỪNG Ô CỦA TẤM ẢNH, KHÔNG CHỈ ĐẾM BYTE. `VHCC_Anh::svg` là hàm THUẦN nên phép thử
      hỏi thẳng nó bằng dữ liệu dựng tay — một tấm ảnh "có dựng ra" mà số trong ô sai thì
      không khác gì không có.
   ================================================================================== */
$anh_ca = array(
	array( 'ten' => 'Ca 1', 'tu' => '06:00', 'den' => '14:00', 'tuW' => '', 'denW' => '' ),
	array( 'ten' => 'Ca 2', 'tu' => '14:00', 'den' => '22:00', 'tuW' => '', 'denW' => '' ),
);
$anh_b = array(
	'ok' => true, 'thang' => '2026-07', 'coSo' => 'K&H_TEST',
	'hang' => array(
		array( 'maNV' => 'A1', 'hoTen' => 'NGUYỄN HUỲNH TƯỜNG VY', 'hauTo' => '',
			'ngay' => '2026-07-01', 'vao' => '05:57:12', 'ra' => '14:03:40',
			'vaoGiay' => VHCC_DB::giay( '05:57' ), 'raGiay' => VHCC_DB::giay( '14:03' ), 'phut' => 486 ),
		array( 'maNV' => 'A1', 'hoTen' => 'NGUYỄN HUỲNH TƯỜNG VY', 'hauTo' => '',
			'ngay' => '2026-07-02', 'vao' => '06:40:00', 'ra' => '14:00:00',
			'vaoGiay' => VHCC_DB::giay( '06:40' ), 'raGiay' => VHCC_DB::giay( '14:00' ), 'phut' => 440 ),
		array( 'maNV' => 'A2', 'hoTen' => 'LÊ PHẠM THUỲ VÂN', 'hauTo' => '',
			'ngay' => '2026-07-01', 'vao' => '14:00:00', 'ra' => '',
			'vaoGiay' => VHCC_DB::giay( '14:00' ), 'raGiay' => null, 'phut' => null ),
	),
);
$anh = VHCC_Anh::svg( $anh_b, $anh_ca, 'gio', 15, '28/08/2026 10:00' );

t( 'dựng ra một tấm SVG', strpos( $anh, '<svg' ) !== false && strpos( $anh, '</svg>' ) !== false );
t( 'có khai bề ngang và chiều cao (thiếu là trình xem bỏ trắng)',
	preg_match( '/<svg[^>]*width="\d+"[^>]*height="\d+"/', $anh ) === 1, substr( $anh, 0, 300 ) );
/* 🔴 Dấu `&` trong tên cơ sở là đủ để cả tệp thành XML hỏng — trình duyệt bỏ trắng, không báo. */
t( '🔴 dấu & trong tên cơ sở được rào lại', strpos( $anh, 'K&amp;H_TEST' ) !== false, $anh );
t( 'và KHÔNG còn dấu & trần nào', preg_match( '/&(?!amp;|lt;|gt;|quot;|#39;|#\d+;)/', $anh ) === 0, $anh );
t( 'tên tiếng Việt có dấu giữ nguyên', strpos( $anh, 'NGUYỄN HUỲNH TƯỜNG VY' ) !== false, $anh );

/* 🔴 ĐÚNG THỨ ANH DẶN: mỗi ô có giờ vào–giờ ra, cắt bỏ giây cho vừa ô. */
t( '🔴 ô có giờ vào–giờ ra', strpos( $anh, '05:57–14:03' ) !== false, $anh );
t( 'và bỏ giây đi cho vừa ô', strpos( $anh, '05:57:12' ) === false, $anh );
t( 'ngày thiếu giờ ra thì ghi rõ là thiếu', strpos( $anh, '14:00–?' ) !== false, $anh );
t( 'và ô ấy mang dấu ?', strpos( $anh, '>?</text>' ) !== false, $anh );
t( 'tấm ảnh nói tháng nào, cơ sở nào', strpos( $anh, 'Tháng 2026-07' ) !== false, $anh );
t( 'và nói mình được xuất lúc nào', strpos( $anh, '28/08/2026 10:00' ) !== false, $anh );
t( 'có chú giải nói ô vàng nghĩa là gì', strpos( $anh, 'Ô vàng' ) !== false, $anh );

/* Kiểu 'gio': in đúng giờ thô 8.1, KHÔNG làm tròn. */
t( 'kiểu theo giờ in đúng số thô 8.1', strpos( $anh, '>8.1</text>' ) !== false, $anh );

/* Kiểu 'ca': cùng dữ liệu ấy phải ra 8, và ngày trễ 40 phút thì ô VÀNG. */
$anh_ct = VHCC_Anh::svg( $anh_b, $anh_ca, 'ca', 15, '' );
t( '🔴 kiểu theo khung ca thì ô thành 8, hết số lẻ', strpos( $anh_ct, '>8</text>' ) !== false, $anh_ct );
t( 'và 8.1 biến mất', strpos( $anh_ct, '>8.1</text>' ) === false, $anh_ct );
t( '🔴 ngày chấm thiếu giờ thì ô VÀNG', strpos( $anh_ct, 'fill="#fffbeb"' ) !== false, $anh_ct );
t( 'ảnh nói rõ đang dùng ngưỡng trễ mấy phút',
	strpos( $anh_ct, 'ngưỡng trễ 15 phút' ) !== false, $anh_ct );
/* 🔴 GIỜ VÀO–RA VẪN LÀ GIỜ THẬT, kể cả khi con số đã làm tròn. Giấu giờ thật đi thì tấm ảnh
   chỉ còn là một bảng số không ai kiểm được. */
t( '🔴 làm tròn rồi thì giờ vào–ra vẫn là giờ máy ghi',
	strpos( $anh_ct, '05:57–14:03' ) !== false, $anh_ct );

/* Tháng không đọc được thì trả rỗng, đừng dựng một tấm ảnh vô nghĩa. */
teq( 'tháng hỏng thì không dựng ảnh', '',
	VHCC_Anh::svg( array( 'ok' => true, 'thang' => 'xxxx', 'coSo' => 'X', 'hang' => array() ), $anh_ca ) );
/* Tên quá dài bị cắt — cột tên rộng cố định, chữ tràn là đè lên cột ngày đầu. */
teq( 'tên dài bị cắt kèm dấu ba chấm', 'ABCD…', VHCC_Anh::cat( 'ABCDEFGH', 5 ) );
teq( 'tên vừa thì để nguyên', 'ABC', VHCC_Anh::cat( 'ABC', 5 ) );
teq( '🔴 cắt theo KÝ TỰ chứ không theo byte (tiếng Việt mỗi chữ nhiều byte)',
	'NGUYỄ…', VHCC_Anh::cat( 'NGUYỄN VĂN A', 6 ) );

/* ---- Trên trang: nút xuất ảnh, và đường xuất chạy thật ---- */
$cs_anh = 'FZ_SC_ANH';
VHCC_Ca::luu( $ADMIN_W, $cs_anh, $anh_ca );
vhcc_cham( $cs_anh, '2026-07-01', 'AN1', '', '05:57', '14:03' );
$h_anh = vhcc_web_nhu2( 'ANAD1', 'Admin', $cs_anh,
	array( 'man' => 'cham', 'ccs' => $cs_anh, 'cth' => '2026-07' ) );
t( 'màn Bảng công có nút Xuất ảnh', strpos( $h_anh, 'xuat=anh' ) !== false, $h_anh );
t( 'và nói rõ ảnh có kèm giờ vào–giờ ra',
	strpos( $h_anh, 'giờ vào–giờ ra' ) !== false, $h_anh );

/* ⚠️ `vhcc_web_nhu2` đã tự hứng đầu ra rồi TRẢ VỀ — bọc thêm một lớp `ob_start()` ở ngoài thì
   bắt được đúng chuỗi rỗng, và phép thử đỏ về một chỗ chẳng có gì sai. */
$tep_anh = vhcc_web_nhu2( 'ANAD1', 'Admin', $cs_anh,
	array( 'xuat' => 'anh', 'ccs' => $cs_anh, 'cth' => '2026-07' ) );
t( '🔴 bấm nút thì ra một tấm SVG thật, không phải trang lỗi',
	strpos( $tep_anh, '<svg' ) !== false, substr( $tep_anh, 0, 400 ) );
t( 'và trong đó có giờ vào–giờ ra của ngày đã chấm',
	strpos( $tep_anh, '05:57–14:03' ) !== false, substr( $tep_anh, 0, 4000 ) );

/* 🔴 XUẤT ẢNH KHÔNG ĐƯỢC ĐI QUA CHỐT ZipArchive. Ảnh là chuỗi chữ máy chủ tự ghép; bắt nó qua
   chốt của Excel là hosting thiếu `php-zip` thì mất luôn đường xuất duy nhất còn chạy được. */
$u_anh = array( 'name' => 'Sếp', 'role' => 'Admin', 'coso' => $cs_anh );
teq( 'xuất ảnh không bị chối', '', VHCC_Web::vi_sao_khong_xuat( $u_anh, 'anh', $cs_anh ) );
t( 'lời chối của xuất ảnh KHÔNG nhắc tới ZipArchive',
	strpos( VHCC_Web::vi_sao_khong_xuat( $u_anh, 'anh', $cs_anh ), 'ZipArchive' ) === false );
/* 🔴 Máy nào chạy bộ thử cũng CÓ ZipArchive, nên phải hỏi thẳng hàm quyết định — chứ soi lời
   chối thì trên máy này không bao giờ phân biệt được có chốt hay không. */
t( '🔴 xuất ảnh KHÔNG cần ZipArchive', ! VHCC_Web::xuat_can_zip( 'anh' ) );
t( 'còn xuất Excel thì có', VHCC_Web::xuat_can_zip( 'ca' ) );

/* Kiểu MIME cũng vậy: `header()` gọi trong CLI chẳng ghi lại đâu cả, nên hỏi thẳng hàm thuần. */
teq( '🔴 ảnh gửi đi dưới đúng MIME của SVG', 'image/svg+xml', VHCC_Xuat::mime( 'image/svg+xml' ) );
t( 'còn để trống thì vẫn là MIME của .xlsx',
	strpos( VHCC_Xuat::mime( '' ), 'spreadsheetml' ) !== false, VHCC_Xuat::mime( '' ) );
/* Và lượt gửi THẬT phải mang đúng MIME ấy — không phải chỉ hàm tính ra đúng rồi thân `gui()`
   lại gửi một thứ khác. */
VHCC_Xuat::$mime_da_gui = '';
vhcc_web_nhu2( 'ANAD1', 'Admin', $cs_anh,
	array( 'xuat' => 'anh', 'ccs' => $cs_anh, 'cth' => '2026-07' ) );
teq( '🔴 lượt gửi thật mang MIME của SVG', 'image/svg+xml', VHCC_Xuat::$mime_da_gui );
/* Và soi NGUYÊN VĂN dòng đầu tệp sắp truyền cho `header()` — hàm tính đúng mà thân `gui()`
   truyền đi một chuỗi khác thì trình duyệt vẫn nhận nhầm, và không ai thấy. */
t( '🔴 dòng Content-Type gửi đi đúng là của SVG',
	in_array( 'Content-Type: image/svg+xml', VHCC_Xuat::$dau_da_gui, true ), VHCC_Xuat::$dau_da_gui );
t( 'tên tệp gửi kèm có đuôi .svg',
	(bool) preg_grep( '/^Content-Disposition:.*\.svg"$/', VHCC_Xuat::$dau_da_gui ),
	VHCC_Xuat::$dau_da_gui );

/* 🔴 DỰNG LẠI ĐÚNG HOÀN CẢNH ĐƯỜNG XUẤT ẢNH SINH RA ĐỂ CỨU: hosting thiếu `php-zip`.
   Máy chạy bộ thử luôn có ZipArchive, nên không ép thì nhánh này không bao giờ được đi qua —
   và chốt "ảnh không cần zip" là chốt bỏ đi vẫn xanh. */
VHCC_Xuat::$ep_khong_zip = true;
t( '🔴 hosting thiếu php-zip thì Excel bị chối',
	strpos( VHCC_Web::vi_sao_khong_xuat( $u_anh, 'ca', $cs_anh ), 'ZipArchive' ) !== false,
	VHCC_Web::vi_sao_khong_xuat( $u_anh, 'ca', $cs_anh ) );
teq( '🔴 nhưng xuất ẢNH vẫn chạy — đó là cả điểm của nó', '',
	VHCC_Web::vi_sao_khong_xuat( $u_anh, 'anh', $cs_anh ) );
$tep_khong_zip = vhcc_web_nhu2( 'ANAD1', 'Admin', $cs_anh,
	array( 'xuat' => 'anh', 'ccs' => $cs_anh, 'cth' => '2026-07' ) );
t( 'và vẫn ra một tấm SVG thật', strpos( $tep_khong_zip, '<svg' ) !== false,
	substr( $tep_khong_zip, 0, 300 ) );
VHCC_Xuat::$ep_khong_zip = false;
t( '🔴 nhân viên thường không xuất ảnh được',
	'' !== VHCC_Web::vi_sao_khong_xuat(
		array( 'name' => 'NV', 'role' => 'Nhân viên', 'coso' => $cs_anh ), 'anh', $cs_anh ) );
t( '🔴 và không xuất được ảnh của cơ sở KHÁC',
	'' !== VHCC_Web::vi_sao_khong_xuat(
		array( 'name' => 'CHT', 'role' => 'Cửa hàng trưởng', 'coso' => 'CO_SO_KHAC' ), 'anh', $cs_anh ) );
t( 'kiểu xuất lạ vẫn bị chối',
	'' !== VHCC_Web::vi_sao_khong_xuat( $u_anh, 'linh_tinh', $cs_anh ) );

vhcc_dung_bang();


/* ==================================================================================
   ĐI TRỄ: MỨC CHO PHÉP · ĐƠN XIN PHÉP · CỬA HÀNG TRƯỞNG DUYỆT · Ô VÀNG TẮT

   Anh Thắng 27/08/2026, nguyên văn: *"nếu bạn nào chấm thiếu giờ thì hiện cảnh báo ô vàng cho
   cửa hàng trưởng biết (để khỏi bị cảnh báo, thì tại trang chấm công online nhân viên sẽ chọn
   Xin Phép đi trễ TRƯỚC KHI TỚI cửa hàng. lúc này bên tài khoản cửa hàng trưởng sẽ hiện trong
   phần Lệnh đi trễ, cửa hàng trưởng duyệt đơn thì cảnh báo đó sẽ bỏ"*; và *"trễ tầm bao nhiêu
   phút (do cửa hàng trưởng set)"*.
   ================================================================================== */
vhcc_dung_bang();
$xt_ca = array(
	array( 'ten' => 'Ca 1', 'tu' => '06:00', 'den' => '14:00', 'tuW' => '', 'denW' => '' ),
);
$cs_xt  = 'FZ_SC_TRE';
$xt_ad  = array( 'name' => 'Sếp', 'role' => 'Admin', 'coso' => $cs_xt, 'ma_nv' => 'XTAD' );
$xt_cht = array( 'name' => 'CHT trễ', 'role' => 'Cửa hàng trưởng', 'coso' => $cs_xt, 'ma_nv' => 'XTCHT' );
$xt_nv  = array( 'name' => 'Bạn Trễ', 'role' => 'Nhân viên', 'coso' => $cs_xt, 'ma_nv' => 'XT1' );
VHCC_Ca::luu( $xt_ad, $cs_xt, $xt_ca );
VHCC_Luong::dat_cach_tinh( $xt_ad, array( $cs_xt => 'ca' ) );
VHCC_NhanSu::luu_ho_so( $xt_ad, array( 'ma_nv' => 'XT1', 'ho_ten' => 'Bạn Trễ',
	'cua_hang' => $cs_xt, 'vai_tro' => 'Nhân viên' ) );

/* ---- 1. MỨC TRỄ DO CỬA HÀNG TRƯỞNG ĐẶT ---- */
teq( 'chưa khai thì dùng mức mặc định', VHCC_Tre::MAC_DINH, VHCC_Tre::cua( $cs_xt ) );
teq( 'và nguồn là mặc định', 'mac_dinh', VHCC_Tre::nguon( $cs_xt ) );
$r_mt = VHCC_Tre::dat( $xt_cht, $cs_xt, 30 );
t( '🔴 Cửa hàng trưởng đặt được mức trễ cho cửa hàng MÌNH', ! empty( $r_mt['ok'] ), $r_mt );
teq( 'mức mới ăn ngay', 30, VHCC_Tre::cua( $cs_xt ) );
teq( 'và nguồn thành riêng', 'rieng', VHCC_Tre::nguon( $cs_xt ) );
t( '🔴 nhưng KHÔNG đặt được cho cửa hàng khác',
	empty( VHCC_Tre::dat( $xt_cht, 'CS_LA', 30 )['ok'] ) );
t( '🔴 nhân viên thường không đặt được', empty( VHCC_Tre::dat( $xt_nv, $cs_xt, 30 )['ok'] ) );
/* 🔴 SỐ 0 LÀ LỰA CHỌN THẬT — "trễ một phút cũng kêu" — không phải "chưa khai". */
VHCC_Tre::dat( $xt_cht, $cs_xt, 0 );
teq( 'mức 0 giữ được, không bị hiểu là chưa khai', 0, VHCC_Tre::cua( $cs_xt ) );
teq( 'và vẫn là mức RIÊNG', 'rieng', VHCC_Tre::nguon( $cs_xt ) );
/* Để trống rồi lưu = bỏ mức riêng, quay về mặc định. Khác hẳn với đặt 0. */
$r_bo = VHCC_Tre::dat( $xt_cht, $cs_xt, '' );
t( 'để trống thì bỏ mức riêng', ! empty( $r_bo['bo_khai'] ), $r_bo );
teq( 'và quay về mặc định', VHCC_Tre::MAC_DINH, VHCC_Tre::cua( $cs_xt ) );
t( 'mức quá trần bị chối', empty( VHCC_Tre::dat( $xt_cht, $cs_xt, VHCC_Tre::TOI_DA + 1 )['ok'] ) );
VHCC_Tre::dat( $xt_cht, $cs_xt, 15 );

/* ---- 2. NHÂN VIÊN NỘP ĐƠN ---- */
$hom_nay = substr( (string) current_time( 'Y-m-d' ), 0, 10 );
/* 🔴 NGÀY THỬ PHẢI BÁM THEO HÔM NAY, KHÔNG ĐƯỢC GÕ CỨNG.
   Đơn xin phép có hai cái trần thật: xin trước tối đa 31 ngày, nộp muộn tối đa 14 ngày. Gõ
   cứng "2026-07-02" thì bài thử chạy được đúng vài tuần rồi tự đỏ khi lịch trôi qua — mà lúc
   ấy trông y như tính năng hỏng. Lấy ba ngày khác nhau NGAY TRONG THÁNG NÀY, đủ gần hôm nay
   để lọt cả hai trần. */
$xt_d   = (int) substr( $hom_nay, 8, 2 );
$xt_th  = substr( $hom_nay, 0, 7 );
$xt_huong = ( $xt_d <= 25 ) ? 1 : -1;
$xt_ng = function ( $b ) use ( $xt_th, $xt_d, $xt_huong ) {
	return sprintf( '%s-%02d', $xt_th, $xt_d + $xt_huong * $b );
};
$ng1 = $xt_ng( 1 );
$ng2 = $xt_ng( 2 );
$ng3 = $xt_ng( 3 );
$r_nop = VHCC_XinTre::nop( $xt_nv, array( 'ngay' => $hom_nay, 'so_phut' => 40,
	'ly_do' => 'kẹt xe cầu Sài Gòn' ) );
t( 'nhân viên nộp được đơn', ! empty( $r_nop['ok'] ), $r_nop );
teq( 'đơn về đúng cửa hàng của người ấy', $cs_xt, $r_nop['coSo'] );
$don = VHCC_XinTre::cua_ngay( 'XT1', $hom_nay );
teq( 'đơn nằm ở trạng thái chờ duyệt', VHCC_XinTre::CHO, $don['trang_thai'] );
teq( 'và ghi đúng tên người nộp', 'Bạn Trễ', $don['ho_ten'] );

/* 🔴 MÃ NV LẤY TỪ PHIÊN, KHÔNG TỪ BIỂU MẪU. Để người gửi tự khai mã là ai cũng nộp được đơn
   đứng tên người khác — và đơn ấy được duyệt thì cảnh báo của người khác biến mất. */
$r_gia = VHCC_XinTre::nop( $xt_nv, array( 'ngay' => $hom_nay, 'so_phut' => 40,
	'ly_do' => 'thử mạo danh', 'ma_nv' => 'XTCHT' ) );
t( 'nộp đơn vẫn đứng tên chính mình', ! empty( $r_gia['ok'] ) );
t( '🔴 không tạo ra đơn nào đứng tên người khác',
	null === VHCC_XinTre::cua_ngay( 'XTCHT', $hom_nay ) );

/* Tài khoản chưa có Mã NV thì nói rõ thiếu ở đâu, đừng lặng lẽ tạo đơn rỗng. */
$r_khong_ma = VHCC_XinTre::nop( array( 'name' => 'Vô danh', 'role' => 'Nhân viên',
	'coso' => $cs_xt ), array( 'ngay' => $hom_nay, 'so_phut' => 10, 'ly_do' => 'x' ) );
t( 'chưa có Mã NV thì bị chối, và nói rõ vì sao', empty( $r_khong_ma['ok'] )
	&& strpos( $r_khong_ma['error'], 'Mã NV' ) !== false, $r_khong_ma );

/* Thiếu lý do thì chối — cửa hàng trưởng duyệt theo lý do, không theo số phút. */
t( 'thiếu lý do thì chối', empty( VHCC_XinTre::nop( $xt_nv,
	array( 'ngay' => $hom_nay, 'so_phut' => 10, 'ly_do' => '' ) )['ok'] ) );
t( 'xin trễ 0 phút là không xin gì — chối', null === VHCC_XinTre::phut( '0' ) );
teq( 'xin 1 phút thì được', 1, VHCC_XinTre::phut( '1' ) );
t( 'quá trần thì chối', null === VHCC_XinTre::phut( (string) ( VHCC_Tre::TOI_DA + 1 ) ) );

/* Hàm đếm ngày là hàm THUẦN — thử được bằng con số trần, không phải chờ tới mai mới biết. */
teq( 'ngày mai là +1', 1, VHCC_XinTre::cach_hom_nay( '2026-08-29', '2026-08-28' ) );
teq( 'hôm qua là -1', -1, VHCC_XinTre::cach_hom_nay( '2026-08-27', '2026-08-28' ) );
teq( 'chính hôm nay là 0', 0, VHCC_XinTre::cach_hom_nay( '2026-08-28', '2026-08-28' ) );

/* 🔴 MỘT NGƯỜI MỘT NGÀY MỘT ĐƠN — nộp lại là ĐÈ, không xếp thêm. */
$so_truoc = count( VHCC_XinTre::cua_nguoi( 'XT1', 50 ) );
$r_lai = VHCC_XinTre::nop( $xt_nv, array( 'ngay' => $hom_nay, 'so_phut' => 25,
	'ly_do' => 'đổi lý do' ) );
t( 'nộp lại được', ! empty( $r_lai['ok'] ) && ! empty( $r_lai['lai'] ), $r_lai );
teq( '🔴 và KHÔNG sinh thêm đơn thứ hai', $so_truoc, count( VHCC_XinTre::cua_nguoi( 'XT1', 50 ) ) );
teq( 'đơn nay mang số phút mới', 25, (int) VHCC_XinTre::cua_ngay( 'XT1', $hom_nay )['so_phut'] );

/* ---- 3. CỬA HÀNG TRƯỞNG DUYỆT ---- */
$don_id = (int) VHCC_XinTre::cua_ngay( 'XT1', $hom_nay )['id'];
t( 'đơn hiện trong danh sách chờ duyệt của cửa hàng',
	(bool) VHCC_XinTre::cho_duyet( $cs_xt ), VHCC_XinTre::cho_duyet( $cs_xt ) );
t( '🔴 nhân viên thường KHÔNG duyệt được',
	empty( VHCC_XinTre::duyet( $xt_nv, $don_id )['ok'] ) );
/* 🔴 HAI CHỐT CÙNG CHẶN MỘT CA THÌ KHÔNG PHÉP THỬ NÀO PHÂN BIỆT ĐƯỢC. `lich_lam` và `cong_coso`
   (cửa của `co_quyen_coso`) cùng đứng ở bậc Cửa hàng trưởng, nên nhân viên bị chặn hai lần và
   bỏ đi một chốt vẫn không lộ. Dựng đúng một người ở giữa: MỞ `cong_coso`, KHOÁ `lich_lam`. */
$ma_giua_t = 'TREGIUA1';
VHCC_Vai::dat_ngoai_le( $xt_ad, 'nv:' . $ma_giua_t, 'cong_coso', 'mo' );
VHCC_Vai::dat_ngoai_le( $xt_ad, 'nv:' . $ma_giua_t, 'lich_lam', 'khoa' );
$u_giua_t = array( 'name' => 'Người giữa', 'role' => 'Nhân viên',
	'coso' => $cs_xt, 'ma_nv' => $ma_giua_t );
t( 'người giữa QUA được cửa cơ sở', VHCC_NhanSu::co_quyen_coso( $u_giua_t, $cs_xt ) );
t( 'nhưng KHÔNG có quyền duyệt đơn', ! VHCC_Vai::duoc( $u_giua_t, 'lich_lam' ) );
t( '🔴 nên vẫn không duyệt được đơn nào',
	empty( VHCC_XinTre::duyet( $u_giua_t, $don_id )['ok'] ),
	VHCC_XinTre::duyet( $u_giua_t, $don_id ) );
t( 'và cũng không đặt được mức trễ', empty( VHCC_Tre::dat( $u_giua_t, $cs_xt, 40 )['ok'] ) );
VHCC_Vai::dat_ngoai_le( $xt_ad, 'nv:' . $ma_giua_t, 'cong_coso', '' );
VHCC_Vai::dat_ngoai_le( $xt_ad, 'nv:' . $ma_giua_t, 'lich_lam', '' );
/* Chốt cơ sở đọc từ CHÍNH ĐƠN: id gõ tay được, và một cửa hàng trưởng gõ đúng id là duyệt được
   đơn của cửa hàng khác. */
$cht_la = array( 'name' => 'CHT khác', 'role' => 'Cửa hàng trưởng', 'coso' => 'CS_HOAN_TOAN_KHAC' );
t( '🔴 Cửa hàng trưởng cửa hàng KHÁC cũng không duyệt được',
	empty( VHCC_XinTre::duyet( $cht_la, $don_id )['ok'] ) );
$r_duyet = VHCC_XinTre::duyet( $xt_cht, $don_id );
t( 'Cửa hàng trưởng của cửa hàng ấy duyệt được', ! empty( $r_duyet['ok'] ), $r_duyet );
teq( 'đơn thành ĐÃ DUYỆT', VHCC_XinTre::DUYET,
	VHCC_XinTre::cua_ngay( 'XT1', $hom_nay )['trang_thai'] );
t( 'và ghi lại ai duyệt', 'CHT trễ' === VHCC_XinTre::cua_ngay( 'XT1', $hom_nay )['nguoi_duyet'] );
t( 'đơn đã duyệt thì rời khỏi danh sách chờ', ! VHCC_XinTre::cho_duyet( $cs_xt ) );

/* 🔴 NỘP LẠI SAU KHI ĐÃ DUYỆT THÌ VỀ CHỜ DUYỆT. Xin 10 phút, được duyệt, rồi sửa thành 90 mà
   vẫn còn dấu "đã duyệt" là không ai duyệt cái 90 ấy cả. */
VHCC_XinTre::nop( $xt_nv, array( 'ngay' => $hom_nay, 'so_phut' => 90, 'ly_do' => 'sửa to lên' ) );
teq( '🔴 sửa đơn đã duyệt thì quay về chờ duyệt', VHCC_XinTre::CHO,
	VHCC_XinTre::cua_ngay( 'XT1', $hom_nay )['trang_thai'] );
VHCC_XinTre::duyet( $xt_cht, $don_id );

/* Không duyệt: ghi lại lý do chối để người nộp đọc được. */
VHCC_XinTre::nop( $xt_nv, array( 'ngay' => $ng1, 'so_phut' => 30, 'ly_do' => 'ngủ quên' ) );
$id_choi = (int) VHCC_XinTre::cua_ngay( 'XT1', $ng1 )['id'];
VHCC_XinTre::duyet( $xt_cht, $id_choi, VHCC_XinTre::TU_CHOI, 'tuần này trễ ba lần rồi' );
$d_choi = VHCC_XinTre::cua_ngay( 'XT1', $ng1 );
teq( 'ghi được KHÔNG duyệt', VHCC_XinTre::TU_CHOI, $d_choi['trang_thai'] );
teq( 'và giữ lý do chối để người nộp đọc', 'tuần này trễ ba lần rồi', $d_choi['ly_do_choi'] );

/* ---- 4. Ô VÀNG TẮT KHI ĐƠN ĐÃ DUYỆT ---- */
/* Hàm quyết định là hàm THUẦN, nhận sẵn bản đồ — lưới hơn 600 ô, để mỗi ô tự hỏi CSDL một câu
   là 600 lượt truy vấn cho một lần mở trang. */
$bd = VHCC_XinTre::ban_do_thang( $cs_xt, substr( $hom_nay, 0, 7 ) );
t( '🔴 ngày có đơn ĐÃ DUYỆT thì trả đúng', VHCC_XinTre::da_duyet( $bd, 'XT1', $hom_nay ), $bd );
t( 'ngày không có đơn thì không', ! VHCC_XinTre::da_duyet( $bd, 'XT1', '2026-01-01' ) );
t( 'người khác thì không', ! VHCC_XinTre::da_duyet( $bd, 'XTCHT', $hom_nay ) );
$bd7 = VHCC_XinTre::ban_do_thang( $cs_xt, $xt_th );
t( '🔴 đơn BỊ TỪ CHỐI thì KHÔNG tính là đã duyệt',
	! VHCC_XinTre::da_duyet( $bd7, 'XT1', $ng1 ), $bd7 );

/* Trên lưới thật: ngày trễ 40 phút (ngưỡng 15) mà CHƯA có đơn -> ô vàng. */
vhcc_cham( $cs_xt, $ng2, 'XT1', '', '06:40', '14:00' );
$h_xt = vhcc_web_nhu2( 'XTAD', 'Admin', $cs_xt,
	array( 'man' => 'cham', 'ccs' => $cs_xt, 'cth' => $xt_th ) );
t( '🔴 chưa có đơn thì ô VÀNG', preg_match( '/class="oc ca1 vang"/', $h_xt ) === 1, $h_xt );

/* Nộp đơn cho đúng ngày ấy rồi DUYỆT -> ô thôi vàng, nhưng SỐ KHÔNG ĐỔI. */
VHCC_XinTre::nop( $xt_nv, array( 'ngay' => $ng2, 'so_phut' => 40, 'ly_do' => 'kẹt xe' ) );
$h_cho = vhcc_web_nhu2( 'XTAD', 'Admin', $cs_xt,
	array( 'man' => 'cham', 'ccs' => $cs_xt, 'cth' => $xt_th ) );
t( '🔴 đơn mới CHỜ duyệt thì ô VẪN vàng — chưa ai chịu trách nhiệm',
	preg_match( '/class="oc ca1 vang"/', $h_cho ) === 1, $h_cho );
VHCC_XinTre::duyet( $xt_cht, (int) VHCC_XinTre::cua_ngay( 'XT1', $ng2 )['id'] );
$h_sau = vhcc_web_nhu2( 'XTAD', 'Admin', $cs_xt,
	array( 'man' => 'cham', 'ccs' => $cs_xt, 'cth' => $xt_th ) );
t( '🔴 duyệt xong thì ô THÔI VÀNG', strpos( $h_sau, 'class="oc ca1 vang"' ) === false, $h_sau );
t( 'và mang dấu riêng để còn nhìn ra chỗ nào là do đơn',
	strpos( $h_sau, 'xin-tre' ) !== false, $h_sau );
/* 🔴 BỎ CẢNH BÁO, KHÔNG BỎ SỐ. Nếu đơn cộng bù giờ thì nó thành một cửa cấp công không qua
   chấm công, và cửa ấy không có ai gác. 06:40–14:00 = 7h20m, làm tròn không được vì trễ quá
   ngưỡng -> ô vẫn phải là 7.3. */
t( '🔴 số giờ trong ô KHÔNG đổi vì có đơn', strpos( $h_sau, '<b>7.3</b>' ) !== false, $h_sau );
t( 'chú thích nói rõ là nhờ đơn được duyệt',
	strpos( $h_sau, 'đã có đơn xin phép đi trễ được duyệt' ) !== false, $h_sau );

/* ---- 5. TRÊN MÀN: khối Lệnh đi trễ của cửa hàng trưởng ---- */
VHCC_XinTre::nop( $xt_nv, array( 'ngay' => $ng3, 'so_phut' => 20, 'ly_do' => 'xe hỏng' ) );
$h_lenh = vhcc_web_nhu2( 'XTCHT', 'Cửa hàng trưởng', $cs_xt,
	array( 'man' => 'cham', 'ccs' => $cs_xt, 'cth' => $xt_th ) );
t( 'Cửa hàng trưởng thấy khối Lệnh đi trễ', strpos( $h_lenh, 'id="lenhtre"' ) !== false, $h_lenh );
t( '🔴 có đơn chờ thì khối MỞ SẴN — đơn gập kín là đơn chờ mãi',
	preg_match( '/id="lenhtre"><details open>/', $h_lenh ) === 1, $h_lenh );
t( 'khối nói có mấy đơn đang chờ', strpos( $h_lenh, 'đơn đang chờ duyệt' ) !== false, $h_lenh );
t( 'hiện lý do người ta xin', strpos( $h_lenh, 'xe hỏng' ) !== false, $h_lenh );
t( 'có nút Duyệt', strpos( $h_lenh, 'value="duyet_tre"' ) !== false, $h_lenh );
t( 'và nút Không duyệt', strpos( $h_lenh, 'value="choi_tre"' ) !== false, $h_lenh );
t( 'có ô đặt mức trễ ngay tại đó', strpos( $h_lenh, 'name="muc"' ) !== false, $h_lenh );
t( 'và nói rõ đây là cảnh báo, không phải trừ tiền',
	strpos( $h_lenh, 'không phải máy tự trừ tiền' ) !== false, $h_lenh );
/* 🔴 SOI THẲNG VÀO KHỐI, KHÔNG SOI QUA CẢ TRANG. Nhân viên bị hàng rào của TẦNG TRÊN chặn từ
   trước khi tới đây, nên "trang không có khối" là chuyện đúng vì lý do khác — bỏ chốt trong
   khối đi thì phép thử vẫn xanh. Hỏi thẳng khối là hỏi được: *mày có tự giữ cửa không?* */
ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_lenh_tre', array( $cs_xt, 'ky', $xt_cht ) );
$k_lenh_cht = ob_get_clean();
t( 'gọi thẳng: Cửa hàng trưởng thấy khối Lệnh đi trễ',
	strpos( $k_lenh_cht, 'id="lenhtre"' ) !== false, $k_lenh_cht );

ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_lenh_tre', array( $cs_xt, 'ky', $xt_nv ) );
$k_lenh_nv = ob_get_clean();
t( '🔴 gọi thẳng: nhân viên KHÔNG mở được khối duyệt đơn của cả cửa hàng',
	'' === trim( $k_lenh_nv ), $k_lenh_nv );

ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_lenh_tre', array( 'CS_HOAN_TOAN_KHAC', 'ky', $xt_cht ) );
$k_lenh_lac = ob_get_clean();
t( '🔴 gọi thẳng: Cửa hàng trưởng KHÔNG mở được Lệnh đi trễ của cửa hàng khác',
	'' === trim( $k_lenh_lac ), $k_lenh_lac );

ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_lenh_tre', array( '', 'ky', $xt_cht ) );
t( 'gọi thẳng: cơ sở rỗng thì không vẽ gì', '' === trim( ob_get_clean() ) );

/* Và trên trang thật cũng vậy. */
$h_lenh_nv = vhcc_web_nhu2( 'XT1', 'Nhân viên', $cs_xt,
	array( 'man' => 'cham', 'ccs' => $cs_xt, 'cth' => $xt_th ) );
t( '🔴 nhân viên KHÔNG thấy khối Lệnh đi trễ',
	strpos( $h_lenh_nv, 'id="lenhtre"' ) === false, $h_lenh_nv );

/* ---- 6. BẤM NÚT THẬT trên trang, không chỉ gọi hàm ---- */
$id_bam = (int) VHCC_XinTre::cua_ngay( 'XT1', $ng3 )['id'];
vhcc_web_nhu2( 'XTCHT', 'Cửa hàng trưởng', $cs_xt, array() );   /* dựng phiên để lấy chữ ký */
$_POST = array( 'viec' => 'duyet_tre', 'don' => $id_bam, 'ccs' => $cs_xt );
$b_duyet = vhcc_goi_rieng( 'VHCC_Web', 'lam_viec', array( 'duyet_tre', $xt_cht ) );
$_POST = array();
t( '🔴 bấm nút Duyệt trên trang thì đơn đổi trạng thái thật',
	VHCC_XinTre::DUYET === VHCC_XinTre::cua_ngay( 'XT1', $ng3 )['trang_thai'], $b_duyet );
t( 'và lời báo nói ra hậu quả: ô vàng thôi kêu, số giữ nguyên',
	isset( $b_duyet[0]['xong'] ) && strpos( $b_duyet[0]['xong'], 'số giờ giữ nguyên' ) !== false,
	$b_duyet );

$_POST = array( 'viec' => 'muc_tre', 'muc' => '25', 'ccs' => $cs_xt );
$b_muc = vhcc_goi_rieng( 'VHCC_Web', 'lam_viec', array( 'muc_tre', $xt_cht ) );
$_POST = array();
teq( '🔴 bấm nút Lưu mức trễ thì mức đổi thật', 25, VHCC_Tre::cua( $cs_xt ) );
t( 'và báo lại mức mới', isset( $b_muc[0]['xong'] )
	&& strpos( $b_muc[0]['xong'], '25 phút' ) !== false, $b_muc );

$_POST = array( 'viec' => 'xin_tre', 'xt_ngay' => $ng1, 'xt_phut' => '35',
	'xt_ly_do' => 'đưa con đi học' );
$b_xin = vhcc_goi_rieng( 'VHCC_Web', 'lam_viec', array( 'xin_tre', $xt_nv ) );
$_POST = array();
t( '🔴 bấm nút Gửi đơn trên trang thì đơn vào sổ thật',
	null !== VHCC_XinTre::cua_ngay( 'XT1', $ng1 ), $b_xin );
teq( 'đúng số phút đã xin', 35, (int) VHCC_XinTre::cua_ngay( 'XT1', $ng1 )['so_phut'] );

/* ---- 7. Màn Công của tôi: chỗ nhân viên nộp đơn ---- */
$h_toi = vhcc_web_nhu2( 'XT1', 'Nhân viên', $cs_xt, array( 'man' => 'cong_toi' ) );
t( 'nhân viên có khối Xin phép đi trễ', strpos( $h_toi, 'id="xintre"' ) !== false, $h_toi );
t( 'có ô ngày, ô số phút, ô lý do',
	strpos( $h_toi, 'name="xt_ngay"' ) !== false && strpos( $h_toi, 'name="xt_phut"' ) !== false
	&& strpos( $h_toi, 'name="xt_ly_do"' ) !== false, $h_toi );
/* 🔴 KHÔNG CÓ Ô MÃ NV — mã lấy từ phiên. Có ô ấy là mở cửa cho mạo danh. */
t( '🔴 KHÔNG có ô Mã NV trong biểu mẫu xin phép',
	preg_match( '/id="xintre".*?name="ma_nv"/s', $h_toi ) !== 1, $h_toi );
t( 'ngày mặc định là hôm nay', strpos( $h_toi, 'value="' . $hom_nay . '"' ) !== false, $h_toi );
t( 'thấy lại đơn mình đã nộp và kết quả', strpos( $h_toi, 'đưa con đi học' ) !== false, $h_toi );
t( 'và nói rõ đơn không cộng bù giờ cho ai',
	strpos( $h_toi, 'không cộng bù giờ' ) !== false, $h_toi );
/* 🔴 CHƯA CÓ MÃ NV THÌ KHÔNG BÀY BIỂU MẪU. Mã lấy từ phiên, nên người chưa có mã bấm Gửi là
   nhận một câu chối — bày ra một cái nút chỉ để chối là mời người ta gõ xong rồi mất công. */
ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_xin_tre',
	array( array( 'name' => 'Vô danh', 'role' => 'Nhân viên', 'coso' => $cs_xt ), 'ky' ) );
t( '🔴 người chưa có Mã NV thì không thấy biểu mẫu xin phép', '' === trim( ob_get_clean() ) );
ob_start(); vhcc_goi_rieng( 'VHCC_Web', 'the_xin_tre', array( $xt_nv, 'ky' ) );
$k_xin = ob_get_clean();
t( 'còn người có mã thì thấy', strpos( $k_xin, 'id="xintre"' ) !== false, $k_xin );

vhcc_dung_bang();


/* ==================================================================================
   CHỜ TRẢ VỀ NHÂN SỰ

   Anh Thắng 28/08/2026: *"Thêm dấu tích, nhân viên nghỉ việc, trong tháng đó không phát sinh
   công, nó tự đẩy ngược về nhân sự. Khi tích thì trong cửa hàng đó vẫn có, nhưng nằm phía là
   chờ trả về nhân sự"*.
   ================================================================================== */
vhcc_dung_bang();
$cs_tv  = 'FZ_SC_TRAVE';
$tv_ad  = array( 'name' => 'Sếp', 'role' => 'Admin', 'coso' => $cs_tv, 'ma_nv' => 'TVAD' );
$tv_cht = array( 'name' => 'CHT', 'role' => 'Cửa hàng trưởng', 'coso' => $cs_tv, 'ma_nv' => 'TVCHT' );
$tv_nv  = array( 'name' => 'NV',  'role' => 'Nhân viên', 'coso' => $cs_tv, 'ma_nv' => 'TV1' );
foreach ( array( 'TV1' => 'Người Nghỉ', 'TV2' => 'Người Ở Lại' ) as $m_tv => $t_tv ) {
	VHCC_NhanSu::luu_ho_so( $tv_ad, array( 'ma_nv' => $m_tv, 'ho_ten' => $t_tv,
		'cua_hang' => $cs_tv, 'vai_tro' => 'Nhân viên' ) );
}

/* ---- 1. TÍCH / BỎ TÍCH ---- */
t( 'chưa tích thì không ai đang chờ trả', ! VHCC_TraVe::ds_cho( $cs_tv ) );
$r_tv = VHCC_TraVe::dat( $tv_cht, 'TV1', true );
t( '🔴 Cửa hàng trưởng tích được người của cửa hàng mình', ! empty( $r_tv['ok'] ), $r_tv );
t( 'người ấy vào danh sách chờ trả', isset( VHCC_TraVe::ds_cho( $cs_tv )['TV1'] ) );
t( 'và hồ sơ mang dấu ấy', VHCC_TraVe::dang_cho( VHCC_NhanSu::ho_so( 'TV1' ) ) );
/* 🔴 TÍCH KHÔNG PHẢI LÀ XOÁ, VÀ CŨNG KHÔNG PHẢI LÀ TRẢ NGAY. */
teq( '🔴 tích xong người ấy VẪN Ở TRONG CỬA HÀNG', $cs_tv,
	VHCC_NhanSu::chuan_coso( VHCC_NhanSu::ho_so( 'TV1' )['cua_hang'] ) );
t( 'người kia không bị đụng tới', ! VHCC_TraVe::dang_cho( VHCC_NhanSu::ho_so( 'TV2' ) ) );

t( '🔴 nhân viên thường KHÔNG tích được', empty( VHCC_TraVe::dat( $tv_nv, 'TV2', true )['ok'] ) );
/* 🔴 HAI CHỐT CÙNG BẬC CÙNG CHẶN MỘT CA. `lich_lam` và `cong_coso` (cửa của `co_quyen_coso`)
   đều đứng ở bậc Cửa hàng trưởng, nên nhân viên bị chặn hai lần — bỏ một chốt đi vẫn không
   lộ. Dựng đúng một người ở giữa: MỞ `cong_coso`, KHOÁ `lich_lam`. */
$ma_giua_tv = 'TVGIUA1';
VHCC_Vai::dat_ngoai_le( $tv_ad, 'nv:' . $ma_giua_tv, 'cong_coso', 'mo' );
VHCC_Vai::dat_ngoai_le( $tv_ad, 'nv:' . $ma_giua_tv, 'lich_lam', 'khoa' );
$u_giua_tv = array( 'name' => 'Người giữa', 'role' => 'Nhân viên',
	'coso' => $cs_tv, 'ma_nv' => $ma_giua_tv );
t( 'người giữa QUA được cửa cơ sở', VHCC_NhanSu::co_quyen_coso( $u_giua_tv, $cs_tv ) );
t( 'nhưng KHÔNG có quyền đánh dấu', ! VHCC_Vai::duoc( $u_giua_tv, 'lich_lam' ) );
t( '🔴 nên vẫn không tích được ai', empty( VHCC_TraVe::dat( $u_giua_tv, 'TV2', true )['ok'] ),
	VHCC_TraVe::dat( $u_giua_tv, 'TV2', true ) );
VHCC_Vai::dat_ngoai_le( $tv_ad, 'nv:' . $ma_giua_tv, 'cong_coso', '' );
VHCC_Vai::dat_ngoai_le( $tv_ad, 'nv:' . $ma_giua_tv, 'lich_lam', '' );
/* Cơ sở đọc từ CHÍNH HỒ SƠ, không từ biểu mẫu — mã gõ tay được. */
$cht_la_tv = array( 'name' => 'CHT khác', 'role' => 'Cửa hàng trưởng', 'coso' => 'CS_KHAC_HAN' );
t( '🔴 Cửa hàng trưởng cửa hàng khác cũng không tích được người này',
	empty( VHCC_TraVe::dat( $cht_la_tv, 'TV1', true )['ok'] ) );
t( 'mã không có hồ sơ thì báo rõ',
	empty( VHCC_TraVe::dat( $tv_cht, 'KHONG_CO', true )['ok'] ) );

VHCC_TraVe::dat( $tv_cht, 'TV1', false );
t( 'bỏ tích được', ! VHCC_TraVe::dang_cho( VHCC_NhanSu::ho_so( 'TV1' ) ) );
VHCC_TraVe::dat( $tv_cht, 'TV1', true );

/* ---- 2. QUYẾT ĐỊNH TRẢ VỀ LÀ HÀM THUẦN ---- */
t( '🔴 chưa tích thì không trả, dù tháng đã hết và không có công',
	! VHCC_TraVe::nen_tra( false, 0, '2026-01', '2026-08-28' ) );
t( '🔴 tháng ấy CÓ công thì không trả',
	! VHCC_TraVe::nen_tra( true, 3, '2026-01', '2026-08-28' ) );
/* 🔴 "Trong tháng đó không phát sinh công" đọc vào tháng ĐANG CHẠY thì luôn đúng vào ngày mùng
   một — và cả cửa hàng bị trả về nhân sự sạch trong một buổi sáng. */
t( '🔴 tháng ĐANG CHẠY thì KHÔNG trả, dù chưa ai chấm ngày nào',
	! VHCC_TraVe::nen_tra( true, 0, '2026-08', '2026-08-01' ) );
t( 'tháng đã hết + không công + đã tích -> trả',
	VHCC_TraVe::nen_tra( true, 0, '2026-07', '2026-08-01' ) );
t( 'tháng sau nữa cũng không trả (chưa tới)',
	! VHCC_TraVe::nen_tra( true, 0, '2026-09', '2026-08-28' ) );
t( 'tháng viết sai thì không trả', ! VHCC_TraVe::nen_tra( true, 0, 'xxx', '2026-08-28' ) );
t( 'tháng trước đã hết', VHCC_TraVe::thang_da_het( '2026-07', '2026-08-01' ) );
t( 'tháng này chưa', ! VHCC_TraVe::thang_da_het( '2026-08', '2026-08-31' ) );

/* ---- 3. QUÉT THẬT ---- */
$thang_nay_tv = substr( (string) current_time( 'Y-m-d' ), 0, 7 );
teq( '🔴 quét tháng ĐANG CHẠY thì không trả ai', 0,
	count( VHCC_TraVe::quet( $cs_tv, $thang_nay_tv ) ) );
t( 'và người ấy vẫn ở cửa hàng', '' !== VHCC_NhanSu::ho_so( 'TV1' )['cua_hang'] );

$thang_cu = '2026-01';
$da_tra = VHCC_TraVe::quet( $cs_tv, $thang_cu, 'Sếp' );
teq( '🔴 quét tháng ĐÃ HẾT, không công, đã tích -> trả về nhân sự', 1, count( $da_tra ) );
teq( 'đúng người', 'TV1', $da_tra[0]['ma_nv'] );
/* 🔴 TRẢ VỀ = GỠ KHỎI CỬA HÀNG, KHÔNG PHẢI XOÁ HỒ SƠ. */
t( '🔴 hồ sơ VẪN CÒN trong sổ nhân sự', (bool) VHCC_NhanSu::ho_so( 'TV1' ) );
teq( 'chỉ ô Cửa hàng được xoá trắng', '', VHCC_NhanSu::ho_so( 'TV1' )['cua_hang'] );
/* 🔴 VỀ KHO THÌ BỎ LUÔN CÁI TÍCH — để nguyên là lần sau xếp họ vào cửa hàng mới, cái tích cũ
   lại âm thầm đẩy họ ra. */
t( '🔴 và dấu chờ trả được gỡ theo', ! VHCC_TraVe::dang_cho( VHCC_NhanSu::ho_so( 'TV1' ) ) );
t( 'người không tích thì không bị đụng',
	'' !== VHCC_NhanSu::ho_so( 'TV2' )['cua_hang'] );

/* Người có công trong tháng ấy thì giữ lại, dù đã tích. */
VHCC_NhanSu::luu_ho_so( $tv_ad, array( 'ma_nv' => 'TV3', 'ho_ten' => 'Người Có Công',
	'cua_hang' => $cs_tv, 'vai_tro' => 'Nhân viên' ) );
VHCC_TraVe::dat( $tv_cht, 'TV3', true );
vhcc_cham( $cs_tv, '2026-01-15', 'TV3', '', '08:00', '17:00' );
teq( '🔴 tháng ấy có công thì KHÔNG trả, dù đã tích', 0,
	count( VHCC_TraVe::quet( $cs_tv, $thang_cu ) ) );
t( 'và người ấy còn nguyên ở cửa hàng', '' !== VHCC_NhanSu::ho_so( 'TV3' )['cua_hang'] );

/* ---- 4. TRÊN MÀN ---- */
VHCC_TraVe::dat( $tv_cht, 'TV2', true );
/* 🔴 NGƯỜI DỰNG RIÊNG ĐỂ SO THỨ TỰ: tên bắt đầu bằng "Z" nên xếp theo bảng chữ cái thì đứng
   CUỐI — nhưng vì không tích, họ phải đứng TRÊN hai người đã tích. Lấy một người tên vần đầu
   thì không phân biệt được: họ đứng trên là do bảng chữ cái, không phải do luật mới. */
VHCC_NhanSu::luu_ho_so( $tv_ad, array( 'ma_nv' => 'TV4', 'ho_ten' => 'Zz Người Thường',
	'cua_hang' => $cs_tv, 'vai_tro' => 'Nhân viên' ) );
$h_tv = vhcc_web_nhu2( 'TVCHT', 'Cửa hàng trưởng', $cs_tv,
	array( 'man' => 'cham', 'ccs' => $cs_tv, 'cth' => $thang_nay_tv ) );
t( 'Cửa hàng trưởng thấy dấu tích chờ trả về',
	strpos( $h_tv, 'value="cho_tra"' ) !== false, $h_tv );
t( 'người đã tích hiện dấu đã tích', strpos( $h_tv, '☑ chờ trả về' ) !== false, $h_tv );
t( 'người chưa tích hiện ô trống', strpos( $h_tv, '☐ chờ trả về' ) !== false, $h_tv );
t( 'hàng của người chờ trả có nền riêng', strpos( $h_tv, 'class="cho-tra"' ) !== false, $h_tv );
/* 🔴 XUỐNG CUỐI BẢNG, KHÔNG BIẾN MẤT — bảng lương tháng ấy vẫn phải tra ra tên họ. */
t( '🔴 người chờ trả VẪN CÓ trong bảng', strpos( $h_tv, 'Người Ở Lại' ) !== false, $h_tv );
/* ⚠️ CẮT ĐÚNG THÂN LƯỚI RỒI MỚI SO THỨ TỰ. Soi cả trang thì bắt trúng tên ở khối KHÁC —
   khối "thiếu ảnh thẻ" cũng liệt kê đúng những người này, và nó xếp theo bảng chữ cái, nên
   phép thử đỏ oan về một chỗ chẳng có gì sai. Cùng cái bẫy đã cắn nhiều lần. */
$than_tv = vhcc_than_luoi( $h_tv );
$vt_2 = strpos( $than_tv, 'Người Ở Lại' );
$vt_4 = strpos( $than_tv, 'Zz Người Thường' );
t( '🔴 và nằm SAU người bình thường — dù người kia tên vần Z, xếp abc thì lẽ ra đứng cuối',
	$vt_4 !== false && $vt_2 !== false && $vt_4 < $vt_2, array( $vt_4, $vt_2 ) );

/* Nhân viên thường vẫn THẤY ai đang chờ trả (đọc bảng mới hiểu), nhưng không bấm được. */
ob_start(); echo vhcc_goi_rieng( 'VHCC_Web', 'o_cho_tra', array( 'TV2', true, 'ky', $tv_nv, $cs_tv ) );
$o_nv = ob_get_clean();
t( '🔴 nhân viên KHÔNG có nút tích', strpos( $o_nv, 'value="cho_tra"' ) === false, $o_nv );
t( 'nhưng vẫn thấy nhãn chờ trả về', strpos( $o_nv, 'chờ trả về' ) !== false, $o_nv );
ob_start(); echo vhcc_goi_rieng( 'VHCC_Web', 'o_cho_tra', array( 'TV2', false, 'ky', $tv_nv, $cs_tv ) );
teq( 'người không chờ trả thì nhân viên chẳng thấy gì', '', trim( ob_get_clean() ) );

/* ---- 5. BẤM NÚT THẬT ---- */
$_POST = array( 'viec' => 'cho_tra', 'tv_ma' => 'TV3', 'tv_bat' => '0', 'ccs' => $cs_tv );
$b_tv = vhcc_goi_rieng( 'VHCC_Web', 'lam_viec', array( 'cho_tra', $tv_cht ) );
$_POST = array();
t( '🔴 bấm bỏ tích trên trang thì dấu mất thật',
	! VHCC_TraVe::dang_cho( VHCC_NhanSu::ho_so( 'TV3' ) ), $b_tv );
$_POST = array( 'viec' => 'cho_tra', 'tv_ma' => 'TV3', 'tv_bat' => '1', 'ccs' => $cs_tv );
$b_tv2 = vhcc_goi_rieng( 'VHCC_Web', 'lam_viec', array( 'cho_tra', $tv_cht ) );
$_POST = array();
t( 'bấm tích lại cũng vậy', VHCC_TraVe::dang_cho( VHCC_NhanSu::ho_so( 'TV3' ) ) );
t( 'và lời báo nói rõ người ấy VẪN ở cửa hàng', isset( $b_tv2[0]['xong'] )
	&& strpos( $b_tv2[0]['xong'], 'VẪN ở ' . $cs_tv ) !== false, $b_tv2 );

vhcc_dung_bang();


/* ==================================================================================
   CƠ SỞ PHỤ: DANH SÁCH ĐỦ, VÀ CHỌN ĐƯỢC NHIỀU CƠ SỞ

   Anh Thắng 28/08/2026, gửi ảnh ô Cơ sở phụ xổ xuống chỉ có mười mục trong khi sổ có nhiều cơ
   sở hơn hẳn: *"Cơ sở phụ sao cơ sở có, cơ sở không"*. Rồi ngay sau: *"Nếu lÀM 2,3 cơ sở phụ
   thì sao chọn"*.
   ================================================================================== */
vhcc_dung_bang();
$cp_ad = array( 'name' => 'Sếp', 'role' => 'Admin', 'coso' => 'FZ_ADV_TP', 'ma_nv' => 'CPAD' );
/* Ba cơ sở chỉ xuất hiện ở cột CỬA HÀNG CHÍNH, chưa ai khai chúng làm cơ sở phụ bao giờ. */
VHCC_NhanSu::luu_ho_so( $cp_ad, array( 'ma_nv' => 'CP1', 'ho_ten' => 'Người Một',
	'cua_hang' => 'FZ_ADV_TP', 'vai_tro' => 'Nhân viên' ) );
VHCC_NhanSu::luu_ho_so( $cp_ad, array( 'ma_nv' => 'CP2', 'ho_ten' => 'Người Hai',
	'cua_hang' => 'TUTU_BT', 'vai_tro' => 'Nhân viên' ) );
VHCC_NhanSu::luu_ho_so( $cp_ad, array( 'ma_nv' => 'CP3', 'ho_ten' => 'Người Ba',
	'cua_hang' => 'VR_TA', 'vai_tro' => 'Nhân viên', 'coso_phu' => 'FARM_NT' ) );

$h_cp = vhcc_web_nhu2( 'CPAD', 'Admin', 'FZ_ADV_TP', array( 'man' => 'ho_so' ) );
/* ⚠️ Cắt đúng datalist `dl_cp` rồi mới soi — cả trang có hàng chục chỗ in tên cơ sở. */
$dl_cp = '';
$i_dl  = strpos( $h_cp, '<datalist id="dl_cp">' );
if ( false !== $i_dl ) {
	$j_dl  = strpos( $h_cp, '</datalist>', $i_dl );
	$dl_cp = substr( $h_cp, $i_dl, $j_dl - $i_dl );
}
t( 'có danh sách gợi ý cơ sở phụ', '' !== $dl_cp, substr( $h_cp, 0, 200 ) );
/* 🔴 CƠ SỞ CHƯA AI KHAI PHỤ VẪN PHẢI CÓ MẶT. Bản trước gom `DISTINCT coso_phu`, nên danh sách
   chỉ lớn lên được nếu ai đó gõ tay đúng chính tả một lần đầu — và đúng lúc người khai cần nó
   nhất lại là lúc chưa ai khai. */
t( '🔴 cơ sở mới chỉ có ở cột Cửa hàng vẫn nằm trong gợi ý cơ sở phụ',
	strpos( $dl_cp, 'value="FZ_ADV_TP"' ) !== false, $dl_cp );
t( 'cả cơ sở của người khác nữa', strpos( $dl_cp, 'value="TUTU_BT"' ) !== false, $dl_cp );
t( 'và cơ sở đang được khai làm phụ cũng còn nguyên',
	strpos( $dl_cp, 'value="FARM_NT"' ) !== false, $dl_cp );
/* Ô Cửa hàng đi cùng một nguồn — hai ô hỏi cùng một câu mà xổ ra hai danh sách khác nhau thì
   người khai phải tự nhớ mã nào gõ được ở ô nào. */
$i_ch = strpos( $h_cp, '<datalist id="dl_ch">' );
$dl_ch = ( false === $i_ch ) ? ''
	: substr( $h_cp, $i_ch, strpos( $h_cp, '</datalist>', $i_ch ) - $i_ch );
t( 'ô Cửa hàng cũng thấy cơ sở chỉ tồn tại ở cột phụ',
	strpos( $dl_ch, 'value="FARM_NT"' ) !== false, $dl_ch );

/* ---- CHỌN NHIỀU CƠ SỞ: lưới ô tích ở màn Sửa đủ ---- */
$h_sua = vhcc_web_nhu2( 'CPAD', 'Admin', 'FZ_ADV_TP',
	array( 'man' => 'ho_so', 'sua' => 'CP3' ) );
/* 🔴 CA PHÂN BIỆT cho nguồn của lưới ô tích: `FARM_NT` chỉ tồn tại ở cột PHỤ của CP3, không
   cửa hàng nào mang mã ấy. Mở hồ sơ CP1 — người KHÔNG khai cơ sở phụ nào — thì `FARM_NT` chỉ
   có thể tới từ vế UNION. Soi trên hồ sơ CP3 không phân biệt được: cơ sở ấy đã nằm sẵn trong
   danh sách đang tích của chính họ. */
$h_sua_1 = vhcc_web_nhu2( 'CPAD', 'Admin', 'FZ_ADV_TP',
	array( 'man' => 'ho_so', 'sua' => 'CP1' ) );
t( '🔴 lưới ô tích thấy cả cơ sở chỉ tồn tại ở cột phụ của NGƯỜI KHÁC',
	strpos( $h_sua_1, 'name="coso_o[]" value="FARM_NT"' ) !== false, $h_sua_1 );
t( 'và người này chưa tích cơ sở ấy',
	strpos( $h_sua_1, 'value="FARM_NT" checked' ) === false, $h_sua_1 );

t( '🔴 màn Sửa đủ dùng Ô TÍCH cho cơ sở, không phải một ô gõ chữ',
	strpos( $h_sua, 'name="coso_o[]"' ) !== false, $h_sua );
t( 'mỗi cơ sở một ô tích', substr_count( $h_sua, 'type="checkbox" name="coso_o[]"' ) >= 3,
	substr_count( $h_sua, 'type="checkbox" name="coso_o[]"' ) );
/* 🔴 MỘT LƯỚI CHO CẢ HAI CỘT — anh Thắng 31/08/2026 bỏ hẳn khái niệm "cơ sở phụ".
   `VR_TA` là cột `cua_hang` của CP3, `FARM_NT` là cột `coso_phu`. Cả hai phải tích sẵn trong
   CÙNG một lưới; tích sẵn mỗi cái thì mở hồ sơ ra là thấy mất một cơ sở, và bấm Lưu là mất
   thật. */
t( 'cơ sở ở cột chính được tích sẵn',
	preg_match( '/name="coso_o\[\]" value="VR_TA" checked/', $h_sua ) === 1, $h_sua );
t( 'cơ sở ở cột phụ CŨNG được tích sẵn, cùng một lưới',
	preg_match( '/name="coso_o\[\]" value="FARM_NT" checked/', $h_sua ) === 1, $h_sua );
t( 'cơ sở chưa khai thì không tích',
	preg_match( '/name="coso_o\[\]" value="TUTU_BT" checked/', $h_sua ) !== 1, $h_sua );
/* 🔴 KHÔNG CÒN Ô "Cơ sở phụ" RIÊNG. Còn nó là còn dạy người dùng rằng cơ sở thứ hai là hạng
   dưới, đúng cái "lẫn lộn" anh vừa bảo bỏ. */
t( '🔴 biểu mẫu KHÔNG còn ô gõ chữ tên `coso_phu`',
	preg_match( '/name="coso_phu"[^>]*>/', $h_sua ) !== 1, $h_sua );
t( 'và nhãn ô cơ sở không còn chữ "phụ"',
	strpos( $h_sua, 'Cơ sở phụ' ) === false && strpos( $h_sua, 'Cửa hàng chính' ) === false, $h_sua );
/* ⚠️ Vẫn giữ MỘT ô gõ chữ cho cơ sở chưa có trong sổ — lưới ô tích dựng từ dữ liệu đang có. */
/* 🔴 Ô GÕ TAY PHẢI MANG ĐÚNG TÊN `coso_phu_o[]`. Mang tên khác thì nó vẫn hiện ra, vẫn gõ
   được, mà giá trị không bao giờ tới nơi — và người khai chỉ biết khi mở lại hồ sơ. Soi cả
   chuỗi `name=… placeholder=…` chứ không soi riêng placeholder. */
t( 'còn một ô gõ tay cho cơ sở chưa có trong sổ, mang đúng tên gửi lên',
	preg_match( '/name="coso_o\[\]"[^>]*placeholder="cơ sở khác/', $h_sua ) === 1, $h_sua );
/* 🔴 KHÔNG dùng `<select multiple>`: nó đòi giữ Ctrl, thứ không ai đoán ra nếu chưa được dạy,
   và trên điện thoại gần như không bấm nổi. */
t( '🔴 KHÔNG dùng select multiple', strpos( $h_sua, '<select multiple' ) === false, $h_sua );

/* ---- LƯU: lưới ô tích -> danh sách cơ sở bình đẳng ----
   ⚠️ Soi bằng `ds_coso_hs()` chứ KHÔNG đọc thẳng một cột. Câu cần canh là "người này làm ở
      những cơ sở nào", và nó phải đúng dù mai kia hai cột có gộp làm một. Cách RẢI vào hai cột
      được canh riêng ở phép ngay dưới — một phép cho một câu. */
$_POST = array( 'ma_nv' => 'CP3', 'coso_o' => array( 'FARM_NT', 'TUTU_BT', '' ) );
$r_cp = vhcc_goi_rieng( 'VHCC_Web', 'luu_ho_so', array() );
$_POST = array();
t( 'lưu được', ! empty( $r_cp['ok'] ), $r_cp );
teq( '🔴 hai ô tích thành hai cơ sở bình đẳng', 'FARM_NT · TUTU_BT',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'CP3' ) ) ) );
/* 🔴 CÁCH RẢI: cơ sở ĐẦU vào `cua_hang`, phần còn lại vào `coso_phu`. Hệ ghế, sổ lương và bản
   kéo từ sheet đang đọc hai cột này, nên hình dạng lưu phải cố định chứ không tuỳ hứng. */
teq( 'cơ sở đầu danh sách nằm ở cột cua_hang', 'FARM_NT',
	VHCC_NhanSu::ho_so( 'CP3' )['cua_hang'] );
teq( 'phần còn lại nằm ở cột coso_phu', 'TUTU_BT',
	VHCC_NhanSu::ho_so( 'CP3' )['coso_phu'] );

/* Ba cơ sở, trong đó một cái gõ tay ở ô cuối. */
$_POST = array( 'ma_nv' => 'CP3', 'coso_o' => array( 'FARM_NT', 'TUTU_BT', 'CO_SO_MOI' ) );
vhcc_goi_rieng( 'VHCC_Web', 'luu_ho_so', array() );
$_POST = array();
teq( '🔴 ba cơ sở cùng lúc, kể cả cái gõ tay ở ô cuối', 'FARM_NT · TUTU_BT · CO_SO_MOI',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'CP3' ) ) ) );

/* 🔴 BỎ TRÙNG THEO CHỮ THƯỜNG CÓ DẤU. Tích một cơ sở rồi gõ lại chính nó ở ô cuối là chuyện
   thường, mà "FZ_LTVT, FZ_LTVT" thì mọi phép đếm cơ sở đều lệch. */
$_POST = array( 'ma_nv' => 'CP3', 'coso_o' => array( 'FARM_NT', 'farm_nt', ' FARM_NT ' ) );
vhcc_goi_rieng( 'VHCC_Web', 'luu_ho_so', array() );
$_POST = array();
teq( '🔴 gõ trùng thì chỉ còn một', 'FARM_NT',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'CP3' ) ) ) );
teq( 'và cột phụ trống hẳn, không còn rác', '', VHCC_NhanSu::ho_so( 'CP3' )['coso_phu'] );

/* Ô cuối gõ luôn cả chuỗi có dấu phẩy (dán từ chỗ khác) cũng phải tách ra đúng. */
/* ⚠️ Dán chuỗi KHÔNG CÓ khoảng trắng sau dấu phẩy — đây mới là ca phân biệt. Chuỗi đã có sẵn
   ", " thì tách hay không tách cũng ra y hệt, nên nó không hỏi được gì. */
$_POST = array( 'ma_nv' => 'CP3', 'coso_o' => array( 'JP_HCM,POSH_HCM' ) );
vhcc_goi_rieng( 'VHCC_Web', 'luu_ho_so', array() );
$_POST = array();
teq( '🔴 dán cả chuỗi có dấu phẩy thì tách ra thành hai cơ sở', 'JP_HCM · POSH_HCM',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'CP3' ) ) ) );

/* 🔴 Ô TÍCH THẮNG CẢ HAI Ô GÕ CHỮ CŨ. Một biểu mẫu cũ còn trong bộ nhớ trình duyệt (hoặc một
   lượt gửi tay) vẫn có thể kèm `cua_hang` và `coso_phu` kiểu cũ; để chúng chạy tiếp trong vòng
   lặp cột là ghi đè mất kết quả vừa gom, và người bấm thấy "Đã lưu" trong khi cơ sở vừa chọn
   biến mất. */
$_POST = array( 'ma_nv' => 'CP3', 'coso_phu' => 'CU_KY_LAM_SAO', 'cua_hang' => 'CU_KY_HON',
	'coso_o' => array( 'FARM_NT', 'TUTU_BT' ) );
vhcc_goi_rieng( 'VHCC_Web', 'luu_ho_so', array() );
$_POST = array();
teq( '🔴 gửi kèm hai ô gõ chữ cũ thì ô tích vẫn thắng', 'FARM_NT · TUTU_BT',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'CP3' ) ) ) );

/* 🔴 TÊN Ô CŨ VẪN NHẬN ĐƯỢC. Người ta không tải lại trang chỉ vì mình vừa nâng cấp plugin —
   một tab đang mở dở gửi lên `coso_phu_o[]` thì lượt lưu ấy vẫn phải đúng, không được lặng lẽ
   rơi về nhánh "không gửi gì" và giữ nguyên dữ liệu cũ. */
$_POST = array( 'ma_nv' => 'CP3', 'coso_phu_o' => array( 'JP_HCM', 'VR_TA' ) );
vhcc_goi_rieng( 'VHCC_Web', 'luu_ho_so', array() );
$_POST = array();
teq( '🔴 biểu mẫu bản cũ gửi lên vẫn lưu đúng', 'JP_HCM · VR_TA',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'CP3' ) ) ) );

/* 🔴 BỎ TÍCH HẾT RỒI LƯU = THÔI LÀM Ở CƠ SỞ NÀO. Ô gõ tay ở cuối luôn có mặt trong biểu mẫu
   nên `coso_o` luôn được gửi lên, kể cả khi không tích ô nào. */
$_POST = array( 'ma_nv' => 'CP3', 'coso_o' => array( '' ) );
vhcc_goi_rieng( 'VHCC_Web', 'luu_ho_so', array() );
$_POST = array();
teq( '🔴 bỏ tích hết thì không còn cơ sở nào', 0,
	count( VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'CP3' ) ) ) );

/* Cơ sở người này đang khai mà không cửa hàng nào mang mã ấy vẫn phải hiện ra và tích sẵn —
   `ds_moi_coso()` quét cả cột phụ nên nó tới từ chính hồ sơ này. */
VHCC_NhanSu::luu_ho_so( $cp_ad, array( 'ma_nv' => 'CP3', 'coso_phu' => 'CO_SO_DA_DONG' ) );
$h_sua2 = vhcc_web_nhu2( 'CPAD', 'Admin', 'FZ_ADV_TP',
	array( 'man' => 'ho_so', 'sua' => 'CP3' ) );
t( 'cơ sở không cửa hàng nào mang mã ấy vẫn hiện ra và vẫn được tích',
	preg_match( '/name="coso_o\[\]" value="CO_SO_DA_DONG" checked/', $h_sua2 ) === 1, $h_sua2 );

/* =============================================================================================
 * TÍCH CƠ SỞ NÀO LÀ CÓ MẶT ĐẦY ĐỦ Ở CHI NHÁNH ĐÓ.
 * =============================================================================================
 * Anh Thắng 31/08/2026: *"việc phân thêm cơ sở phụ nó đang bị lẫn lộn. Thay vì việc cơ sở phụ.
 * Thì nhân viên sẽ được tích vào cơ sở nào thì sẽ được có mặt làm việc đầy đủ tại chi nhánh
 * đó"*.
 *
 * Trước bản này, `cua_hang` là cơ sở "thật" còn `coso_phu` chỉ là ghi chú: mọi câu lọc theo cơ
 * sở đều hỏi mỗi `cua_hang`. Nên tích thêm một cơ sở mà KHÔNG hiện ở đâu cả — danh sách nhân
 * sự của chi nhánh ấy không có họ, cửa hàng trưởng ở đấy không thấy họ, bảng "ai chưa khai
 * lương" cũng bỏ sót. Mục này canh từng cửa một.
 */
vhcc_dung_bang();
$ad_cs = array( 'name' => 'Sếp', 'role' => 'Admin', 'coso' => '', 'ma_nv' => 'CSAD' );
VHCC_NhanSu::luu_ho_so( $ad_cs, array( 'ma_nv' => 'CSA', 'ho_ten' => 'Chỉ A',
	'cua_hang' => 'ALPHA', 'vai_tro' => 'Nhân viên' ) );
VHCC_NhanSu::luu_ho_so( $ad_cs, array( 'ma_nv' => 'CSB', 'ho_ten' => 'Chỉ B',
	'cua_hang' => 'BETA', 'vai_tro' => 'Nhân viên' ) );
/* Người chạy giữa hai nơi: ALPHA đứng đầu, BETA tích thêm. */
VHCC_NhanSu::luu_ho_so( $ad_cs, array( 'ma_nv' => 'CSAB', 'ho_ten' => 'Cả Hai',
	'cua_hang' => 'ALPHA', 'coso_phu' => 'BETA', 'vai_tro' => 'Nhân viên' ) );

/* (a) Danh sách cơ sở của một hồ sơ: gộp hai cột, bình đẳng, không trùng. */
$hs_ab = VHCC_NhanSu::ho_so( 'CSAB' );
teq( 'hồ sơ hai cơ sở ra đúng hai', 'ALPHA · BETA',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( $hs_ab ) ) );
teq( 'khai trùng ở cả hai cột chỉ tính một', 1,
	count( VHCC_NhanSu::ds_coso_hs( array( 'cua_hang' => 'ALPHA', 'coso_phu' => 'alpha' ) ) ) );
teq( 'bỏ tiền tố CS_ như mọi nơi khác', 'ALPHA',
	implode( ',', VHCC_NhanSu::ds_coso_hs( array( 'cua_hang' => 'CS_ALPHA', 'coso_phu' => '' ) ) ) );
t( 'hs_thuoc_coso không phân biệt hoa thường',
	VHCC_NhanSu::hs_thuoc_coso( $hs_ab, 'beta' ) );
t( 'và trả false với cơ sở không liên quan',
	! VHCC_NhanSu::hs_thuoc_coso( $hs_ab, 'GAMMA' ) );

/* (b) 🔴 CỬA CHÍNH: lọc nhân sự theo cơ sở B phải có người tích thêm B. */
$ds_b = VHCC_NhanSu::ds_nhan_vien( $ad_cs, 'BETA' );
$ma_b = array();
foreach ( $ds_b as $x ) { $ma_b[] = $x['ma_nv']; }
sort( $ma_b );
teq( '🔴 danh sách nhân sự của BETA có cả người tích thêm BETA', 'CSAB,CSB', implode( ',', $ma_b ) );
$ds_a = VHCC_NhanSu::ds_nhan_vien( $ad_cs, 'ALPHA' );
$ma_a = array();
foreach ( $ds_a as $x ) { $ma_a[] = $x['ma_nv']; }
sort( $ma_a );
teq( 'và ALPHA vẫn đúng người của ALPHA', 'CSA,CSAB', implode( ',', $ma_a ) );

/* (c) 🔴 CỬA HÀNG TRƯỞNG CỦA B PHẢI THẤY HỌ. Không thấy thì không xếp lịch được, không sửa
       giờ được, không duyệt đơn được — tức là người ấy làm ở B mà B không quản được. */
$cht_b = array( 'name' => 'Trưởng B', 'role' => 'CUA_HANG_TRUONG', 'coso' => 'BETA', 'ma_nv' => 'TB' );
$ds_tb = VHCC_NhanSu::ds_nhan_vien( $cht_b, 'BETA' );
$ma_tb = array();
foreach ( $ds_tb as $x ) { $ma_tb[] = $x['ma_nv']; }
sort( $ma_tb );
teq( '🔴 cửa hàng trưởng BETA thấy cả người tích thêm BETA', 'CSAB,CSB', implode( ',', $ma_tb ) );
t( 'co_quyen_ho_so: trưởng BETA có quyền với hồ sơ ấy',
	VHCC_NhanSu::co_quyen_ho_so( $cht_b, $hs_ab ) );
t( 'nhưng KHÔNG có quyền với người chỉ làm ở ALPHA',
	! VHCC_NhanSu::co_quyen_ho_so( $cht_b, VHCC_NhanSu::ho_so( 'CSA' ) ) );

/* (d) 🔴 CA PHÂN BIỆT CỦA "NỚI RỒI LỌC".
       Mệnh đề SQL chỉ nới được bằng `LIKE %X%`, nên mã cơ sở là KHÚC của mã khác sẽ bị bắt
       thừa. Không lọc lại bằng PHP thì lọc "TA" kéo về cả người của "BETA" — sai im lặng, và
       sai theo hướng lộ hồ sơ người của chi nhánh khác. */
VHCC_NhanSu::luu_ho_so( $ad_cs, array( 'ma_nv' => 'CSTA', 'ho_ten' => 'Chỉ TA',
	'cua_hang' => 'TA', 'vai_tro' => 'Nhân viên' ) );
VHCC_NhanSu::luu_ho_so( $ad_cs, array( 'ma_nv' => 'CSX', 'ho_ten' => 'Có BETA phụ',
	'cua_hang' => 'ALPHA', 'coso_phu' => 'BETA', 'vai_tro' => 'Nhân viên' ) );
$ds_ta = VHCC_NhanSu::ds_nhan_vien( $ad_cs, 'TA' );
$ma_ta = array();
foreach ( $ds_ta as $x ) { $ma_ta[] = $x['ma_nv']; }
sort( $ma_ta );
teq( '🔴 lọc "TA" KHÔNG kéo nhầm người của "BETA"', 'CSTA', implode( ',', $ma_ta ) );

/* (d2) 🔴 MÃ CƠ SỞ CÓ DẤU GẠCH DƯỚI — mã THẬT của K&H đều thế (`POSH_HCM`, `FZ_SC_VIVO_T`).
       Bản đầu dùng `$wpdb->esc_like()`, biến `_` thành `\_`. Dấu `\` là ký tự thoát của LIKE
       trên MySQL nhưng KHÔNG trên SQLite, nên cùng một câu cho hai kết quả: hosting khớp, máy
       chạy thử không. Bộ thử và thật nói ngược nhau mà chẳng bên nào kêu — nên mục này dùng
       đúng hình dạng mã thật, để cái lệch ấy không quay lại. */
VHCC_NhanSu::luu_ho_so( $ad_cs, array( 'ma_nv' => 'CSU1', 'ho_ten' => 'Gạch Dưới',
	'cua_hang' => 'POSH_HCM', 'coso_phu' => 'FZ_SC_VIVO_T', 'vai_tro' => 'Nhân viên' ) );
$ds_u = VHCC_NhanSu::ds_nhan_vien( $ad_cs, 'FZ_SC_VIVO_T' );
$ma_u = array();
foreach ( $ds_u as $x ) { $ma_u[] = $x['ma_nv']; }
teq( '🔴 lọc theo mã có dấu gạch dưới vẫn tìm ra người', 'CSU1', implode( ',', $ma_u ) );

/* (e) Cờ "chờ trả về" cũng phải hiện ở lưới của cơ sở tích thêm — người bấm nút đang đứng ở đó. */
global $wpdb;
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'cho_tra_ve' => 1 ), array( 'ma_nv' => 'CSAB' ) );
$cho_b = VHCC_TraVe::ds_cho( 'BETA' );
t( '🔴 chờ trả về hiện ở cơ sở tích thêm', isset( $cho_b['CSAB'] ), array_keys( $cho_b ) );
$cho_ta = VHCC_TraVe::ds_cho( 'TA' );
t( 'và KHÔNG lẫn sang cơ sở có mã là khúc của mã khác',
	! isset( $cho_ta['CSAB'] ), array_keys( $cho_ta ) );

/* (e2) 🔴 MÀN HỒ SƠ CŨNG PHẢI LỌC LẠI, KHÔNG CHỈ HÀM ĐỌC.
       Màn này dựng câu SQL riêng chứ không gọi `ds_nhan_vien()`, nên nó có đường vấp riêng:
       nới bằng `LIKE %TA%` rồi in thẳng là bảng "nhân sự cơ sở TA" hiện luôn người của BETA —
       tức lộ hồ sơ (có cả lương) của chi nhánh khác cho người chỉ quản TA. */
$h_ta = vhcc_web_nhu2( 'CSAD', 'Admin', '', array( 'man' => 'ho_so', 'cs' => 'TA' ) );
t( 'màn Hồ sơ lọc cơ sở TA có người của TA', strpos( $h_ta, 'Chỉ TA' ) !== false, $h_ta );
t( '🔴 và KHÔNG lẫn người của BETA vào', strpos( $h_ta, 'Cả Hai' ) === false, $h_ta );
$h_beta = vhcc_web_nhu2( 'CSAD', 'Admin', '', array( 'man' => 'ho_so', 'cs' => 'BETA' ) );
t( '🔴 lọc BETA thì thấy cả người tích thêm BETA',
	strpos( $h_beta, 'Cả Hai' ) !== false, $h_beta );

/* (f) 🔴 ÁP VAI TRÒ HÀNG LOẠT: nới để GHI là đổi vai trò người ngoài bộ lọc.
       Đây là chỗ nguy nhất của cách "nới rồi lọc" — đọc thừa thì bỏ đi được, ghi thừa thì
       không lấy lại được. */
/* ⚠️ Đặt vai trò thẳng vào bảng, không qua `luu_ho_so()` — hàm ấy không nhận ô `vai_tro`
   (vai trò đi đường riêng), nên dựa vào nó thì phép dưới so với chuỗi rỗng và không phân biệt
   được "không bị đổi lây" với "chưa bao giờ có vai trò". */
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Nhân viên' ), array( 'ma_nv' => 'CSAB' ) );
$wpdb->update( VHCC_DB::t( 'nhan_vien' ), array( 'vai_tro' => 'Nhân viên' ), array( 'ma_nv' => 'CSTA' ) );
$_POST = array( 'cs' => 'TA', 'q' => '', 'loc' => '' );
$n_ap = vhcc_goi_rieng( 'VHCC_Web', 'vai_tro_hang_loat', array( 'Quản lý' ) );
$_POST = array();
teq( 'áp vai trò cho cơ sở TA chỉ đụng đúng 1 người', 1, (int) $n_ap );
teq( 'người của TA đã đổi vai trò', 'Quản lý', VHCC_NhanSu::ho_so( 'CSTA' )['vai_tro'] );
teq( '🔴 người của BETA KHÔNG bị đổi lây', 'Nhân viên', VHCC_NhanSu::ho_so( 'CSAB' )['vai_tro'] );

/* (g) Và áp theo BETA thì phải trúng cả người tích thêm. */
$_POST = array( 'cs' => 'BETA', 'q' => '', 'loc' => '' );
$n_ap2 = vhcc_goi_rieng( 'VHCC_Web', 'vai_tro_hang_loat', array( 'Kế toán' ) );
$_POST = array();
teq( 'áp theo BETA trúng 3 người (1 chính + 2 tích thêm)', 3, (int) $n_ap2 );
teq( '🔴 người tích thêm BETA cũng được áp', 'Kế toán', VHCC_NhanSu::ho_so( 'CSAB' )['vai_tro'] );

vhcc_dung_bang();

vhcc_dung_bang();

/* ==========================================================================================
 *  68. CỬA HÀNG TRƯỞNG QUẢN NHIỀU GIAN HÀNG — BẢNG CÔNG HIỆN HẾT, KHỎI CHỌN TỪNG CÁI
 * ------------------------------------------------------------------------------------------
 *  Anh Thắng 29/08/2026, sau khi cơ sở phụ đã đẩy đúng cả hai cơ sở vào `ds_coso_xem()`:
 *  *"nếu nhân viên làm cửa hàng trưởng 2 gian hàng thì sẽ hiện 2 bảng công của 2 cửa hàng mình
 *  quản lý"*. Trước bản này, `ds_coso_xem()` đã trả đủ hai cơ sở, nhưng `the_bang_cham()` vẫn
 *  bắt CHỌN MỘT qua ô lọc rồi mới vẽ bảng — cơ sở phụ có tới cũng như không, vì không ai đi bấm
 *  chọn cái mình còn chưa biết là có.
 * ======================================================================================== */
vhcc_cham( 'HT_BC1', '2026-08-05', 'HTB1', '', '08:00:00', '17:00:00' );
vhcc_cham( 'HT_BC2', '2026-08-06', 'HTB2', '', '08:00:00', '17:00:00' );
$u_2cs = 'HT_BC1,HT_BC2';

$h_2cs = vhcc_web_nhu2( 'HTBCHT', 'CUA_HANG_TRUONG', $u_2cs,
	array( 'man' => 'cham', 'cth' => '2026-08' ) );
t( '🔴 CHT 2 cơ sở, CHƯA chọn ô lọc: hiện HẾT, không bắt chọn từng cái',
	strpos( $h_2cs, 'Chọn một cơ sở rồi bấm Xem.' ) === false, $h_2cs );
t( 'thấy tên CẢ HAI cơ sở làm tiêu đề',
	strpos( $h_2cs, 'HT_BC1' ) !== false && strpos( $h_2cs, 'HT_BC2' ) !== false, $h_2cs );
t( 'và thấy mã người ở CẢ HAI cơ sở (dữ liệu thật, không phải chỉ tên)',
	strpos( $h_2cs, 'HTB1' ) !== false && strpos( $h_2cs, 'HTB2' ) !== false, $h_2cs );

/* Bấm chọn ĐÚNG MỘT cơ sở ở ô lọc thì vẫn phải ra đúng MỘT bảng — ô lọc không được trở thành
   vô tác dụng chỉ vì tính năng "hiện hết" vừa thêm. */
$h_2cs_1 = vhcc_web_nhu2( 'HTBCHT', 'CUA_HANG_TRUONG', $u_2cs,
	array( 'man' => 'cham', 'cth' => '2026-08', 'ccs' => 'HT_BC1' ) );
t( 'chọn đúng một cơ sở ở ô lọc thì CHỈ ra đúng cơ sở đó',
	strpos( $h_2cs_1, 'HTB1' ) !== false && strpos( $h_2cs_1, 'HTB2' ) === false, $h_2cs_1 );

/* 🔴 CONG_TAT_CA (Admin/Quản lý/Kế toán) KHÔNG ĐƯỢC "hiện hết" DÙ SỔ CHỈ ĐANG CÓ 2 CƠ SỞ —
   họ quản lý có thể hàng chục cơ sở, tính năng này chỉ dành cho CHT một-vài-cửa-hàng. Đúng lúc
   này sổ (toàn hệ) chỉ có 2 cơ sở (HT_BC1/HT_BC2) — nếu thiếu chốt `cong_tat_ca` thì Kế toán
   cũng rơi vào nhánh "hiện hết" y hệt CHT, và phép thử dưới đây bắt đúng chỗ đó. */
t( 'sổ (toàn hệ) đúng 2 cơ sở lúc này (nếu khác thì phép thử dưới vô nghĩa)',
	count( VHCC_NhanSu::ds_coso() ) === 2, VHCC_NhanSu::ds_coso() );
$h_kt_2cs = vhcc_web_nhu2( 'HTBKT', 'Kế toán', $u_2cs, array( 'man' => 'cham', 'cth' => '2026-08' ) );
/* ⚠️ CANH CÓ VẼ BẢNG HAY KHÔNG, ĐỪNG CANH CÂU CHỮ. Bản trước dò đúng câu "Chọn một cơ sở rồi
   bấm Xem." — rồi 01/09/2026 câu ấy đổi thành lời chỉ đường sang dải Bộ phận, và phép thử gãy
   dù luật không đổi tí nào. Thứ đang canh là: chưa chọn gì thì KHÔNG có bảng nào được dựng. */
t( '🔴 Kế toán (cong_tat_ca) chưa chọn bộ phận/cơ sở thì KHÔNG tự vẽ bảng nào, dù sổ chỉ 2 cơ sở',
	strpos( $h_kt_2cs, 'HTB1' ) === false && strpos( $h_kt_2cs, 'HTB2' ) === false, $h_kt_2cs );

/* 🔴 NHƯNG BẤM MỘT BỘ PHẬN LÀ RA LUÔN TỪNG CƠ SỞ TRONG ĐÓ.
   Anh Thắng 01/09/2026: *"Khi kế toán bấm vào bộ phận, từng cơ sở 1 bảng công sẽ hiện ra sẵn
   luôn"*. HT_BC1/HT_BC2 chưa xếp bộ phận nào nên chúng nằm ở nhóm "Chưa xếp". */
$h_kt_bp = vhcc_web_nhu2( 'HTBKT', 'Kế toán', $u_2cs,
	array( 'man' => 'cham', 'cth' => '2026-08', 'cbp' => VHCC_Luong::BP_CHUA_XEP ) );
t( '🔴 Kế toán bấm một bộ phận -> hiện SẴN bảng của từng cơ sở trong đó',
	strpos( $h_kt_bp, 'HTB1' ) !== false && strpos( $h_kt_bp, 'HTB2' ) !== false, $h_kt_bp );
t( 'và có tên cả hai cơ sở làm tiêu đề',
	strpos( $h_kt_bp, 'HT_BC1' ) !== false && strpos( $h_kt_bp, 'HT_BC2' ) !== false, $h_kt_bp );
/* Nhiều bảng thì phải có dải nhảy tới — sáu lưới cả tháng là một trang rất dài, dựng sẵn hết mà
   không có cách nhảy thì thứ vừa tiết kiệm được lại mất vào việc cuộn tìm. */
t( 'kèm dải "Nhảy tới" để khỏi cuộn tìm', strpos( $h_kt_bp, 'Nhảy tới' ) !== false, $h_kt_bp );
/* Chọn đúng MỘT cơ sở trong khi vẫn đang lọc bộ phận thì vẫn ra đúng một bảng — ô lọc không
   được thành vô tác dụng chỉ vì "bấm bộ phận là hiện hết". */
$h_kt_bp1 = vhcc_web_nhu2( 'HTBKT', 'Kế toán', $u_2cs,
	array( 'man' => 'cham', 'cth' => '2026-08', 'cbp' => VHCC_Luong::BP_CHUA_XEP, 'ccs' => 'HT_BC1' ) );
t( '🔴 chọn một cơ sở khi đang lọc bộ phận thì CHỈ ra cơ sở đó',
	strpos( $h_kt_bp1, 'HTB1' ) !== false && strpos( $h_kt_bp1, 'HTB2' ) === false, $h_kt_bp1 );

/* 🔴 QUÁ 3 CƠ SỞ THÌ QUAY LẠI LUẬT CHỌN MỘT — coi như một vai vận hành rộng hơn CHT một-vài-
   cửa-hàng, dựng hết một lượt là một trang không ai cuộn nổi. */
vhcc_cham( 'HT_BC3', '2026-08-07', 'HTB3', '', '08:00:00', '17:00:00' );
vhcc_cham( 'HT_BC4', '2026-08-08', 'HTB4', '', '08:00:00', '17:00:00' );
$u_4cs = 'HT_BC1,HT_BC2,HT_BC3,HT_BC4';
$h_4cs = vhcc_web_nhu2( 'HTBCHT2', 'CUA_HANG_TRUONG', $u_4cs,
	array( 'man' => 'cham', 'cth' => '2026-08' ) );
t( '🔴 quá 3 cơ sở, CHƯA lọc bộ phận: không tự vẽ bảng nào',
	strpos( $h_4cs, 'HTB1' ) === false && strpos( $h_4cs, 'HTB4' ) === false, $h_4cs );

/* =============================================================================================
 * 🔴 TRẦN SỐ BẢNG DỰNG SẴN KHI BẤM MỘT BỘ PHẬN ĐÔNG CƠ SỞ
 * =============================================================================================
 * Mỗi bảng là lưới CẢ THÁNG của cả một cơ sở — một lượt đọc `cham_cong` cộng một lượt tính.
 * Bộ phận "Khu vui chơi" thật đang 15 cơ sở; dựng hết một lượt là trang không ai chờ nổi. Nên
 * vẽ `TRAN_BANG` bảng đầu, phần dư thành đường tắt một dòng mỗi cơ sở.
 *
 * ⚠️ CẮT MÀ IM LẶNG LÀ TỆ HƠN KHÔNG CẮT: người đọc tưởng bộ phận chỉ có ngần ấy cơ sở, hoặc
 *    tưởng số còn lại chưa nạp dữ liệu. Cả hai đều dẫn tới kết luận SAI về con số.
 */
$ds_tran = array();
for ( $i = 1; $i <= 8; $i++ ) {
	$cs_t = 'HT_TRAN' . $i;
	vhcc_cham( $cs_t, '2026-08-1' . ( $i % 10 ), 'HTT' . $i, '', '08:00:00', '17:00:00' );
	VHCC_NhanSu::xep_bo_phan( array( 'name' => 'Người Thử', 'vai_tro' => 'Admin' ), $cs_t, 'Khu vui chơi' );
	$ds_tran[] = $cs_t;
}
$u_tran = implode( ',', $ds_tran );
$h_tran = vhcc_web_nhu2( 'HTBKT2', 'Kế toán', $u_tran,
	array( 'man' => 'cham', 'cth' => '2026-08', 'cbp' => 'Khu vui chơi' ) );
t( 'dựng đúng TRAN_BANG bảng đầu', strpos( $h_tran, 'HTT1' ) !== false
	&& strpos( $h_tran, 'HTT' . VHCC_Web::TRAN_BANG ) !== false, null );
t( '🔴 cơ sở thứ (TRAN_BANG+1) KHÔNG bị dựng bảng',
	strpos( $h_tran, 'HTT' . ( VHCC_Web::TRAN_BANG + 1 ) ) === false, null );
t( '🔴 nhưng phải NÓI RA còn bao nhiêu, không lặng lẽ cắt',
	strpos( $h_tran, 'Đang dựng sẵn' ) !== false, $h_tran );
t( 'và cho đường vào thẳng từng cơ sở còn lại',
	strpos( $h_tran, 'HT_TRAN' . ( VHCC_Web::TRAN_BANG + 1 ) ) !== false, null );
t( 'kèm nút vẽ hết cho ai thật sự cần', strpos( $h_tran, 'cbp_het' ) !== false, null );

/* Bấm "Vẽ hết" thì phải ra ĐỦ — nút mà không làm đúng điều nó hứa còn tệ hơn không có nút. */
$h_het = vhcc_web_nhu2( 'HTBKT2', 'Kế toán', $u_tran,
	array( 'man' => 'cham', 'cth' => '2026-08', 'cbp' => 'Khu vui chơi', 'cbp_het' => '1' ) );
t( '🔴 bấm "Vẽ hết" thì dựng đủ cả 8 cơ sở',
	strpos( $h_het, 'HTT1' ) !== false && strpos( $h_het, 'HTT8' ) !== false, null );
t( 'và thôi hiện khối "còn lại"', strpos( $h_het, 'Đang dựng sẵn' ) === false, null );

/* Màn quản trị KHÔNG có script — luật chung, nhánh "hiện hết" không được phá lệ dù vẽ nhiều bảng. */
t( '🔴 màn "hiện hết" vẫn không có thẻ script nào', stripos( $h_2cs, '<script' ) === false );
t( 'và không có thuộc tính on...= nào', preg_match( '/\son[a-z]+\s*=\s*["\']/i', $h_2cs ) === 0, $h_2cs );

/* =============================================================================================
 * MÀN "CÔNG CỦA TÔI" VỚI THẺ PHIÊN MANG HAI CƠ SỞ.
 * =============================================================================================
 * Anh Thắng 30/08/2026, ảnh màn Công của tôi: dòng đầu in
 * `POSH_HCM, (PART TIME )_POSH+JP · POSH_HCM · (PART TIME )_POSH+JP` — người 2 cơ sở hiện ra 3,
 * vì chuỗi ghép của thẻ phiên bị đếm thành một cơ sở nữa.
 *
 * ⚠️ Mã NV ở đây CỐ Ý không có hồ sơ trong bảng `nhan_vien`. Có hồ sơ thì `ds_coso_cua_nv()`
 *    vá lại được chỗ thiếu và phép thử xanh kể cả khi màn này cắt thẻ trước lúc tra — tức là
 *    canh mà không canh gì. Không hồ sơ thì thẻ phiên là nguồn duy nhất.
 */
vhcc_dung_bang();
$h_2ten = vhcc_web_nhu2( 'CTNV01', 'Nhân viên', 'MOT_CS, HAI_CS', array( 'man' => 'cong_toi' ) );
/* ⚠️ BỐC RIÊNG DÒNG CƠ SỞ CỦA MÀN, không tìm trên cả trang.
   Bản đầu của mục này tìm chuỗi 'HAI_CS' trong toàn bộ HTML và XANH GIẢ: nó khớp phải mã NV
   `CT_HAI_CS` ở thanh đầu trang, nên phá thử bỏ hẳn bản vá mà phép thử vẫn xanh. Mã NV nay
   đổi thành `CTNV01` — không chứa tên cơ sở nào — và chỉ soi đúng dòng cần soi. */
if ( ! preg_match( '~mã <b>CTNV01</b> · (.*?)</p>~', $h_2ten, $m_cs ) ) { $m_cs = array( '', '(không tìm thấy dòng cơ sở)' ); }
$dong_cs = $m_cs[1];
t( 'Công của tôi: hiện cơ sở thứ nhất', strpos( $dong_cs, 'MOT_CS' ) !== false, $dong_cs );
t( 'Công của tôi: hiện cả cơ sở thứ hai', strpos( $dong_cs, 'HAI_CS' ) !== false, $dong_cs );
t( '🔴 và KHÔNG in chuỗi ghép như một cơ sở thứ ba',
	strpos( $dong_cs, 'MOT_CS, HAI_CS' ) === false, $dong_cs );

/* =============================================================================================
 * DỌN NHỮNG HÀNG ĐÃ LỠ GHI VÀO CƠ SỞ GHÉP.
 * =============================================================================================
 * Bịt cửa ghi không sửa được cái đã nằm trong sổ. Trên hosting thật đã có hàng như vậy rồi, và
 * chừng nào còn thì ô xổ cơ sở của màn quản trị vẫn hiện một cơ sở không có thật.
 *
 * ⚠️ Chèn thẳng bằng `$wpdb->insert` — CỐ Ý đi vòng qua `ghi_gio()`, vì lưới ở đó nay chặn
 *    đúng hình dạng mà mục này cần dựng lại. Đây là dữ liệu CŨ, sinh ra trước bản vá.
 */
vhcc_dung_bang();
$t_cc = VHCC_DB::t( 'cham_cong' );

/* (1) Cơ sở đúng CHƯA có hàng -> đổi tên tại chỗ, giữ nguyên giờ và ghi chú. */
$wpdb->insert( $t_cc, array( 'coso' => 'AA_CS, BB_CS', 'ngay' => '2026-08-10', 'ma_nv' => 'D1',
	'hau_to' => '', 'ho_ten' => 'Một', 'gio_vao_giay' => 8 * 3600, 'gio_ra_giay' => 17 * 3600,
	'nguon' => 'online', 'ghi_chu' => 'gps 10.7' ) );
/* (2) Cơ sở đúng ĐÃ có hàng, nguồn thường -> gộp: nới khung [vào, ra] rồi bỏ hàng ghép. */
$wpdb->insert( $t_cc, array( 'coso' => 'CC_CS', 'ngay' => '2026-08-11', 'ma_nv' => 'D2',
	'hau_to' => '', 'ho_ten' => 'Hai', 'gio_vao_giay' => 9 * 3600, 'gio_ra_giay' => 16 * 3600,
	'nguon' => 'may' ) );
$wpdb->insert( $t_cc, array( 'coso' => 'CC_CS, DD_CS', 'ngay' => '2026-08-11', 'ma_nv' => 'D2',
	'hau_to' => '', 'ho_ten' => 'Hai', 'gio_vao_giay' => 8 * 3600, 'gio_ra_giay' => 18 * 3600,
	'nguon' => 'online' ) );
/* (3) Cơ sở đúng đã được CHỈNH TAY -> không đụng, kể tên ra. */
$wpdb->insert( $t_cc, array( 'coso' => 'EE_CS', 'ngay' => '2026-08-12', 'ma_nv' => 'D3',
	'hau_to' => '', 'ho_ten' => 'Ba', 'gio_vao_giay' => 9 * 3600, 'gio_ra_giay' => 17 * 3600,
	'nguon' => 'sua' ) );
$wpdb->insert( $t_cc, array( 'coso' => 'EE_CS, FF_CS', 'ngay' => '2026-08-12', 'ma_nv' => 'D3',
	'hau_to' => '', 'ho_ten' => 'Ba', 'gio_vao_giay' => 7 * 3600, 'gio_ra_giay' => 19 * 3600,
	'nguon' => 'online' ) );

/* --- Xem trước: đếm đúng, và KHÔNG đổi gì --- */
$xem = VHCC_Nhan::don_coso_ghep( false );
teq( 'xem trước: 1 hàng đổi tên', 1, (int) $xem['doi_ten'] );
teq( 'xem trước: 1 hàng gộp', 1, (int) $xem['gop'] );
teq( 'xem trước: 1 hàng để lại vì đã chỉnh tay', 1, count( $xem['de_lai'] ) );
teq( 'xem trước: kể đủ 3 tên cơ sở ma', 3, count( $xem['cs'] ), implode( ' | ', $xem['cs'] ) );
teq( '🔴 xem trước KHÔNG đổi gì trong sổ', 3,
	(int) $wpdb->get_var( "SELECT COUNT(*) FROM $t_cc WHERE coso LIKE '%,%'" ) );

/* --- Làm thật --- */
$that = VHCC_Nhan::don_coso_ghep( true );
teq( 'dọn thật: đổi tên 1 hàng', 1, (int) $that['doi_ten'] );
teq( 'dọn thật: gộp 1 hàng', 1, (int) $that['gop'] );

$h1 = vhcc_hang( 'AA_CS', '2026-08-10', 'D1' );
t( '(1) hàng nay nằm ở cơ sở đúng', null !== $h1 );
teq( '(1) giờ vào giữ nguyên', 8 * 3600, (int) $h1['gio_vao_giay'] );
teq( '(1) giờ ra giữ nguyên', 17 * 3600, (int) $h1['gio_ra_giay'] );
teq( '(1) ghi chú không mất', 'gps 10.7', (string) $h1['ghi_chu'] );
t( '(1) không còn hàng cơ sở ghép', null === vhcc_hang( 'AA_CS, BB_CS', '2026-08-10', 'D1' ) );

$h2 = vhcc_hang( 'CC_CS', '2026-08-11', 'D2' );
teq( '(2) gộp NỚI giờ vào ra sớm hơn', 8 * 3600, (int) $h2['gio_vao_giay'] );
teq( '(2) gộp NỚI giờ ra ra muộn hơn', 18 * 3600, (int) $h2['gio_ra_giay'] );
teq( '(2) ô "thời gian trong ngày" tính lại', '08:00 18:00', (string) $h2['chuan'] );
t( '(2) hàng ghép đã bị bỏ', null === vhcc_hang( 'CC_CS, DD_CS', '2026-08-11', 'D2' ) );

$h3 = vhcc_hang( 'EE_CS', '2026-08-12', 'D3' );
teq( '🔴 (3) hàng đã chỉnh tay KHÔNG bị đè', 9 * 3600, (int) $h3['gio_vao_giay'] );
t( '🔴 (3) và hàng ghép được GIỮ LẠI để xử tay, không lặng lẽ xoá',
	null !== vhcc_hang( 'EE_CS, FF_CS', '2026-08-12', 'D3' ) );

/* Nút bảo trì chỉ hiện khi còn việc — và biến mất khi dọn sạch. */
$GLOBALS['VHCP_CO_QUYEN'] = true;
ob_start(); VHCC_Admin::page(); $h_don = ob_get_clean();
t( 'còn hàng ghép thì màn Cài đặt hiện nút dọn',
	strpos( $h_don, 'Dọn cơ sở ghép' ) !== false );
$wpdb->query( "DELETE FROM $t_cc WHERE coso LIKE '%,%'" );
ob_start(); VHCC_Admin::page(); $h_sach = ob_get_clean();
t( '🔴 dọn sạch rồi thì nút biến mất hẳn, không nằm lại giữa màn',
	strpos( $h_sach, 'Dọn cơ sở ghép' ) === false );

/* =============================================================================================
 * LƯỚI CÔNG THÁNG Ở MÀN "CÔNG CỦA TÔI" — MỖI CƠ SỞ MỘT HÀNG.
 * =============================================================================================
 * Anh Thắng 31/08/2026: *"Chuyển dữ liệu nhìn công tháng của nhân viên cũng như bản tổng.
 * 1 bảng tính ra công, 1 bảng ghi giờ vào ra, tách 2 hàng, vì 1 nhân viên chỉ có 2 hàng, thì
 * làm 2 hàng cho nhân viên dễ đối soát"*.
 *
 * `luoi_thang()` là hàm THUẦN, nên mục này thử bằng con số trần — không dựng bảng, không dựng
 * màn. Ba chỗ đếm dễ sai nằm cả ở đây.
 */
$dong_thu = array(
	array( 'ngay' => '2026-08-03', 'coSo' => 'G_CS', 'hauTo' => '',   'vao' => '08:00:00', 'ra' => '17:00:00', 'phut' => 540 ),
	array( 'ngay' => '2026-08-03', 'coSo' => 'G_CS', 'hauTo' => 'CD', 'vao' => '22:00:00', 'ra' => '23:00:00', 'phut' => 60 ),
	array( 'ngay' => '2026-08-04', 'coSo' => 'G_CS', 'hauTo' => '',   'vao' => '08:00:00', 'ra' => '',         'phut' => null ),
	array( 'ngay' => '2026-08-05', 'coSo' => 'N_CS', 'hauTo' => '',   'vao' => '09:00:00', 'ra' => '18:00:00', 'phut' => 540 ),
	array( 'ngay' => '2026-08-06', 'coSo' => 'N_CS', 'hauTo' => '',   'vao' => '09:00:00', 'ra' => '',         'phut' => null ),
	array( 'ngay' => '2026-09-01', 'coSo' => 'G_CS', 'hauTo' => '',   'vao' => '08:00:00', 'ra' => '17:00:00', 'phut' => 540 ),
);
$kieu_thu = array( 'G_CS' => 'gio', 'N_CS' => 'ngay', 'R_CS' => 'gio' );

/* (a) Người 3 cơ sở -> ĐÚNG 3 hàng, kể cả cơ sở tháng này không có công nào. */
$lg = VHCC_Online::luoi_thang( $dong_thu, array( 'G_CS', 'N_CS', 'R_CS' ), '2026-08', $kieu_thu );
teq( 'mỗi cơ sở đúng một hàng', 3, count( $lg['hang'] ) );
teq( 'thứ tự hàng theo danh sách cơ sở đưa vào', 'G_CS', $lg['hang'][0]['coSo'] );
teq( '🔴 cơ sở KHÔNG có công tháng này vẫn có hàng', 'R_CS', $lg['hang'][2]['coSo'] );
teq( 'và hàng ấy tổng bằng 0', 0, (int) $lg['hang'][2]['tong'] );
teq( 'số ngày của tháng 8', 31, (int) $lg['soNgay'] );

/* (b) 🔴 HẬU TỐ KHÔNG ĐẺ THÊM HÀNG — nằm trong ô của ngày ấy.
       Không có phép này thì người 2 cơ sở kiêm trực ghế bỗng có 4 hàng, đúng cái anh bảo đừng. */
$g = $lg['hang'][0];
teq( 'hàng chính ngày 3: 9 tiếng', 540, (int) $g['o'][3]['chinh'] );
teq( 'hậu tố CD nằm TRONG ô ngày 3', 60, (int) $g['o'][3]['phu']['CD'] );
teq( 'tổng riêng của hậu tố CD', 60, (int) $g['tongPhu']['CD'] );
teq( '🔴 tổng hàng chính KHÔNG cộng hậu tố vào', 540, (int) $g['tong'] );

/* (c) Ngày thiếu giờ ra: cắm cờ, và với kiểu 'ngay' thì KHÔNG tính công. */
t( 'ngày thiếu giờ ra được cắm cờ', true === $g['o'][4]['thieuRa'] );
teq( 'đếm số lượt thiếu giờ ra của hàng', 1, (int) $g['thieuRa'] );
$n = $lg['hang'][1];
teq( 'kiểu "ngay": ngày đủ giờ = 1 công', 1, (int) $n['o'][5]['chinh'] );
teq( '🔴 kiểu "ngay": ngày thiếu giờ ra = 0 công, không tính đại', 0, (int) $n['o'][6]['chinh'] );
teq( 'nên tổng công của cơ sở ấy là 1', 1, (int) $n['tong'] );

/* (d) Lượt của tháng khác bị bỏ — không thì ô ngày 1 tháng sau đè lên ngày 1 tháng này. */
t( 'lượt tháng 9 không lọt vào lưới tháng 8', ! isset( $g['o'][1] ) );

/* (e) 🔴 LƯỢT Ở CƠ SỞ KHÔNG CÓ TRONG DANH SÁCH VẪN PHẢI HIỆN.
       Bỏ lặng lẽ thì tổng của lưới lệch với bảng giờ ngay bên dưới, mà không ai biết mất ở đâu
       — đúng loại lệch làm người ta thôi tin cả hai bảng. */
$lg2 = VHCC_Online::luoi_thang( $dong_thu, array( 'N_CS' ), '2026-08', $kieu_thu );
teq( 'cơ sở lạ được thêm hàng chứ không bị bỏ', 2, count( $lg2['hang'] ) );

/* (f) Màn thật: hai bảng, và lưới có đúng hai hàng cơ sở. */
vhcc_dung_bang();
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'LT01', 'ho_ten' => 'Lưới A',
	'cua_hang' => 'LT_CHINH', 'coso_phu' => 'LT_PHU' ) );
$wpdb->insert( VHCC_DB::t( 'cham_cong' ), array( 'coso' => 'LT_CHINH', 'ngay' => '2026-08-03',
	'ma_nv' => 'LT01', 'hau_to' => '', 'ho_ten' => 'Lưới A', 'gio_vao_giay' => 8 * 3600,
	'gio_ra_giay' => 17 * 3600, 'nguon' => 'may' ) );
$h_lt = vhcc_web_nhu2( 'LT01', 'Nhân viên', 'LT_CHINH, LT_PHU', array( 'man' => 'cong_toi', 'cth' => '2026-08' ) );
t( 'màn có bảng tính công', strpos( $h_lt, '>Công tháng<' ) !== false, $h_lt );
t( 'và bảng giờ vào ra', strpos( $h_lt, 'Giờ vào — giờ ra từng lượt' ) !== false, $h_lt );
t( '🔴 lưới có hàng cơ sở chính', strpos( $h_lt, '<b>LT_CHINH</b>' ) !== false, $h_lt );
t( '🔴 và hàng cơ sở phụ, dù tháng này chưa có công',
	strpos( $h_lt, '<b>LT_PHU</b>' ) !== false, $h_lt );
teq( 'đúng HAI hàng cơ sở, không đẻ thêm', 2,
	substr_count( $h_lt, 'tính theo ' ) );
t( 'lưới KHÔNG có ô sửa giờ — màn này chỉ đọc',
	strpos( $h_lt, 'name="sg_vao"' ) === false && strpos( $h_lt, 'suaday' ) === false, $h_lt );

/* --- Màn wp-admin cũng phải nói cùng một câu ---
   Hai màn khác hình dạng (ngoài: lưới ô tích; wp-admin: một ô gõ, vì màn quản trị KHÔNG có
   JavaScript theo luật chung), nhưng cùng một khái niệm và cùng một cách lưu. Để wp-admin còn
   ô "Cơ sở phụ" là cái lẫn lộn anh Thắng vừa bảo bỏ vẫn còn nguyên một nửa. */
vhcc_dung_bang();
$GLOBALS['VHCP_CO_QUYEN'] = true;
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'AD1', 'ho_ten' => 'Quản Trị',
	'cua_hang' => 'MOT', 'coso_phu' => 'HAI' ) );
$_GET = array( 'page' => 'vhcc-nhan-su', 'sua' => 'AD1' );
ob_start(); VHCC_Admin::trang_nhan_su(); $h_ad = ob_get_clean();
$_GET = array();
t( 'wp-admin: có ô "Cơ sở làm việc"', strpos( $h_ad, 'Cơ sở làm việc' ) !== false, $h_ad );
/* Bảng liệt kê cũng một cột gộp: hai cột riêng ở bảng là vẫn còn dạy "chính/phụ" bằng mắt,
   và cột thứ hai thì ai cũng lướt qua. */
$_GET = array( 'page' => 'vhcc-nhan-su' );
ob_start(); VHCC_Admin::trang_nhan_su(); $h_bang = ob_get_clean();
$_GET = array();
t( 'bảng wp-admin có cột "Cơ sở làm việc"',
	strpos( $h_bang, '<th>Cơ sở làm việc</th>' ) !== false, $h_bang );
t( '🔴 và ô của người hai cơ sở in ĐỦ cả hai',
	strpos( $h_bang, '<td>MOT, HAI</td>' ) !== false, $h_bang );
t( '🔴 và ô ấy điền sẵn CẢ HAI cơ sở', strpos( $h_ad, 'value="MOT, HAI"' ) !== false, $h_ad );
t( '🔴 KHÔNG còn ô "Cửa hàng chính" / "Cơ sở phụ" riêng',
	strpos( $h_ad, 'Cửa hàng chính' ) === false && strpos( $h_ad, 'Cơ sở phụ' ) === false, $h_ad );

/* Lưu từ wp-admin: một ô -> rải vào hai cột, đúng như màn ngoài. */
$_POST = array( 'vhcc_ns' => 'luu', 'ma_nv' => 'AD1', 'ho_ten' => 'Quản Trị',
	'cac_coso' => 'BA, BON, ba' );
$_GET = array( 'page' => 'vhcc-nhan-su' );
ob_start(); VHCC_Admin::trang_nhan_su(); ob_get_clean();
$_POST = array(); $_GET = array();
teq( '🔴 wp-admin lưu: rải đúng và bỏ trùng', 'BA · BON',
	implode( ' · ', VHCC_NhanSu::ds_coso_hs( VHCC_NhanSu::ho_so( 'AD1' ) ) ) );
teq( 'cơ sở đầu vào cột cua_hang', 'BA', VHCC_NhanSu::ho_so( 'AD1' )['cua_hang'] );

/* =============================================================================================
 * KHU NHÂN SỰ CỦA CỬA HÀNG.
 * =============================================================================================
 * Anh Thắng 31/08/2026: *"Mỗi cơ sở sẽ có thêm 1 hệ thống quản lý nhân sự con của mình. Để tại
 * cửa hàng trực tiếp quản lý dễ hơn"*, và chốt: cửa hàng trưởng sửa được thông tin liên lạc +
 * cấp PIN; người làm hai nơi thì CẢ HAI cửa hàng sửa được.
 *
 * Cửa `sua_ho_so_coso()` là một DANH SÁCH TRẮNG bốn ô liên lạc cộng ô PIN. Mục này canh cả hai
 * chiều: mở đúng cái phải mở, và KHÔNG mở cái gì khác.
 */
vhcc_dung_bang();
$ns_ad  = array( 'name' => 'Sếp', 'role' => 'Admin', 'coso' => '', 'ma_nv' => 'NSAD' );
$ns_cht = array( 'name' => 'Trưởng Một', 'role' => 'CUA_HANG_TRUONG', 'coso' => 'CH_MOT', 'ma_nv' => 'NSTR' );
$ns_nv  = array( 'name' => 'Nhân Viên', 'role' => 'Nhân viên', 'coso' => 'CH_MOT', 'ma_nv' => 'NSNV' );
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'N1', 'ho_ten' => 'Người Một',
	'cua_hang' => 'CH_MOT', 'sdt' => '0900000001', 'luong_co_ban' => 7000000,
	'so_tai_khoan' => '111', 'vai_tro' => 'Nhân viên', 'chuc_vu' => 'Bán hàng' ) );
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'N2', 'ho_ten' => 'Người Hai',
	'cua_hang' => 'CH_HAI', 'sdt' => '0900000002', 'vai_tro' => 'Nhân viên' ) );
/* Người làm hai nơi — cả hai cửa hàng sửa được. */
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'N12', 'ho_ten' => 'Người Hai Nơi',
	'cua_hang' => 'CH_HAI', 'coso_phu' => 'CH_MOT', 'sdt' => '0900000012', 'vai_tro' => 'Nhân viên' ) );

/* --- (a) Cửa mở đúng bốn ô liên lạc --- */
$r_ns = VHCC_NhanSu::sua_ho_so_coso( $ns_cht, 'N1', array(
	'sdt' => '0911111111', 'dia_chi' => 'Số 1 Lê Lợi',
	'nguoi_lien_he_khan' => 'Mẹ', 'sdt_khan' => '0922222222' ) );
t( 'cửa hàng trưởng sửa được liên lạc', ! empty( $r_ns['ok'] ), $r_ns );
$hs_n1 = VHCC_NhanSu::ho_so( 'N1' );
teq( 'SĐT đã đổi', '0911111111', $hs_n1['sdt'] );
teq( 'địa chỉ đã đổi', 'Số 1 Lê Lợi', $hs_n1['dia_chi'] );
teq( 'người liên hệ khẩn đã đổi', 'Mẹ', $hs_n1['nguoi_lien_he_khan'] );

/* --- (b) 🔴 VÀ KHÔNG MỞ GÌ KHÁC. Danh sách trắng, nên ô lạ bị bỏ lặng lẽ chứ không ghi. --- */
VHCC_NhanSu::sua_ho_so_coso( $ns_cht, 'N1', array(
	'luong_co_ban' => 99000000, 'so_tai_khoan' => 'HACK', 'vai_tro' => 'Admin',
	'cua_hang' => 'CH_KHAC', 'coso_phu' => 'CH_KHAC_2', 'ma_nv' => 'N999',
	'ho_ten' => 'Tên Khác', 'trang_thai_lam_viec' => 'Đã nghỉ' ) );
$hs_n1 = VHCC_NhanSu::ho_so( 'N1' );
teq( '🔴 lương KHÔNG đụng được', '7000000', (string) (int) $hs_n1['luong_co_ban'] );
teq( '🔴 số tài khoản KHÔNG đụng được', '111', $hs_n1['so_tai_khoan'] );
teq( '🔴 vai trò KHÔNG tự nâng được', 'Nhân viên', $hs_n1['vai_tro'] );
teq( '🔴 cơ sở KHÔNG đổi được (chuyển công + lương sang nơi khác)', 'CH_MOT', $hs_n1['cua_hang'] );
teq( 'và họ tên cũng không', 'Người Một', $hs_n1['ho_ten'] );
teq( 'trạng thái làm việc cũng không — cho nghỉ là việc bậc trên', '', $hs_n1['trang_thai_lam_viec'] );

/* --- (c) Chặn theo cơ sở và theo bậc --- */
$r_xa = VHCC_NhanSu::sua_ho_so_coso( $ns_cht, 'N2', array( 'sdt' => '0999' ) );
t( '🔴 không sửa được người của cơ sở khác',
	empty( $r_xa['ok'] ) && stripos( $r_xa['error'], 'không thuộc cơ sở' ) !== false, $r_xa );
teq( 'và hồ sơ ấy không suy suyển', '0900000002', VHCC_NhanSu::ho_so( 'N2' )['sdt'] );
$r_nv = VHCC_NhanSu::sua_ho_so_coso( $ns_nv, 'N1', array( 'sdt' => '0999' ) );
t( '🔴 nhân viên bậc 1 KHÔNG sửa được hồ sơ ai', empty( $r_nv['ok'] ), $r_nv );

/* --- (d) 🔴 NGƯỜI HAI NƠI: CẢ HAI CỬA HÀNG SỬA ĐƯỢC (anh Thắng chốt 31/08) --- */
$cht2 = array( 'name' => 'Trưởng Hai', 'role' => 'CUA_HANG_TRUONG', 'coso' => 'CH_HAI', 'ma_nv' => 'NSTR2' );
$r_a = VHCC_NhanSu::sua_ho_so_coso( $ns_cht, 'N12', array( 'sdt' => '0933333333' ) );
t( 'cửa hàng CH_MOT sửa được người tích thêm CH_MOT', ! empty( $r_a['ok'] ), $r_a );
$r_b = VHCC_NhanSu::sua_ho_so_coso( $cht2, 'N12', array( 'dia_chi' => 'Chỗ mới' ) );
t( 'và cửa hàng CH_HAI cũng sửa được', ! empty( $r_b['ok'] ), $r_b );

/* --- (e) 🔴 HAI NƠI CÙNG SỬA THÌ PHẢI CÓ SỔ, và sổ ghi rõ AI, TỪ ĐÂU --- */
$sk = VHCC_NhanSu::nhat_ky_ho_so( 'N12' );
teq( 'sổ ghi đủ hai lượt sửa', 2, count( $sk ) );
$ai = array();
foreach ( $sk as $x ) { $ai[] = $x['ai'] . '@' . $x['tu_coso']; }
sort( $ai );
teq( '🔴 sổ nói rõ ai sửa và sửa từ cửa hàng nào',
	'Trưởng Hai@CH_HAI,Trưởng Một@CH_MOT', implode( ',', $ai ) );
$dia = null;
foreach ( $sk as $x ) { if ( 'dia_chi' === $x['o'] ) { $dia = $x; } }
teq( 'sổ giữ cả giá trị cũ để đối chiếu', '', (string) $dia['cu'] );
teq( 'và giá trị mới', 'Chỗ mới', (string) $dia['moi'] );

/* --- (f) 🔴 PIN: cấp được, nhưng SỔ KHÔNG BAO GIỜ CHỨA SỐ PIN --- */
VHCC_NhanSu::sua_ho_so_coso( $ns_cht, 'N1', array( 'pin_dang_nhap' => '778899' ) );
teq( 'PIN đã được cấp', '778899', VHCC_NhanSu::ho_so( 'N1' )['pin_dang_nhap'] );
$sk1 = VHCC_NhanSu::nhat_ky_ho_so( 'N1' );
$co_so_pin = false;
foreach ( $sk1 as $x ) {
	if ( false !== strpos( $x['cu'] . '|' . $x['moi'], '778899' ) ) { $co_so_pin = true; }
}
t( '🔴 SỔ KHÔNG chứa số PIN — sổ này người trong công ty đọc được', ! $co_so_pin, $sk1 );
$dong_pin = null;
foreach ( $sk1 as $x ) { if ( 'pin_dang_nhap' === $x['o'] ) { $dong_pin = $x; } }
teq( 'chỉ ghi rằng đã đổi', 'đã đổi', (string) $dong_pin['moi'] );

/* Ô PIN để TRỐNG = giữ nguyên, không phải xoá — cùng luật với mọi ô PIN khác trong hệ. */
VHCC_NhanSu::sua_ho_so_coso( $ns_cht, 'N1', array( 'pin_dang_nhap' => '' ) );
teq( '🔴 ô PIN trống thì GIỮ NGUYÊN, không xoá mất đường đăng nhập',
	'778899', VHCC_NhanSu::ho_so( 'N1' )['pin_dang_nhap'] );

/* 🔴 PIN TRÙNG NGƯỜI KHÁC BỊ CHẶN. Hai người cùng PIN là đăng nhập nhầm người — và người dùng
   tưởng mình bấm nhầm, nên không ai báo. */
$r_trung = VHCC_NhanSu::sua_ho_so_coso( $cht2, 'N12', array( 'pin_dang_nhap' => '778899' ) );
t( '🔴 PIN trùng người khác: bị chối',
	empty( $r_trung['ok'] ) && stripos( $r_trung['error'], 'người khác' ) !== false, $r_trung );
teq( 'và người kia vẫn giữ PIN của mình', '778899', VHCC_NhanSu::ho_so( 'N1' )['pin_dang_nhap'] );

/* --- (g) Màn: tab, danh sách, và KHÔNG in PIN --- */
$ds_man_tr = VHCC_Web::man_cua( $ns_cht );
t( 'cửa hàng trưởng có tab Nhân sự cửa hàng', isset( $ds_man_tr['ns_coso'] ) );
t( '🔴 nhân viên bậc 1 KHÔNG có tab ấy',
	! isset( VHCC_Web::man_cua( $ns_nv )['ns_coso'] ) );

/* 🔴 KHÔNG CÓ TAB KHÔNG CÓ NGHĨA LÀ KHÔNG GÕ ĐƯỢC ĐỊA CHỈ. Người ta gõ thật — bookmark cũ,
   link ai đó gửi. Luật chung của trang: màn không có quyền thì đưa về màn mình dùng được
   (`trang_chinh()`), không phải ném một trang lỗi. Mục này canh điều PHẢI đúng dù đi đường
   nào: KHÔNG một cái tên nào của cơ sở lọt ra.

   ⚠️ Gác trong `VHCC_WebNS::man()` là TẦNG HAI, cố ý giữ dù luật chung đã chặn ở tầng một:
      hai thứ ấy là hai bảng khác nhau (`man_cua()` và `VHCC_Vai`), và ngày chúng lệch nhau là
      ngày tầng hai đỡ. */
$h_nv_ns = vhcc_web_nhu2( 'NSNV', 'Nhân viên', 'CH_MOT', array( 'man' => 'ns_coso' ) );
t( '🔴 nhân viên gõ thẳng địa chỉ: KHÔNG lọt tên ai của cơ sở ra màn',
	strpos( $h_nv_ns, 'Người Một' ) === false
	&& strpos( $h_nv_ns, 'Người Hai Nơi' ) === false, $h_nv_ns );
t( 'và không có bảng nhân sự cửa hàng nào được vẽ',
	strpos( $h_nv_ns, 'Sổ sửa hồ sơ' ) === false
	&& strpos( $h_nv_ns, 'có PIN' ) === false, $h_nv_ns );
/* Gọi THẲNG vào màn (bỏ qua luật chung) để canh tầng hai. */
ob_start(); VHCC_WebNS::man( '', $ns_nv ); $h_thang = ob_get_clean();
t( '🔴 tầng hai: gọi thẳng màn bằng tài khoản nhân viên vẫn bị chối',
	stripos( $h_thang, 'Quản lý nhân sự cửa hàng' ) !== false, $h_thang );
t( 'và tầng hai cũng không vẽ ra tên ai', strpos( $h_thang, 'Người Một' ) === false, $h_thang );

$h_ns = vhcc_web_nhu2( 'NSTR', 'CUA_HANG_TRUONG', 'CH_MOT',
	array( 'man' => 'ns_coso', 'ncs' => 'CH_MOT' ) );
t( 'màn hiện người của cơ sở', strpos( $h_ns, 'Người Một' ) !== false, $h_ns );
t( '🔴 và hiện cả người TÍCH THÊM cơ sở này',
	strpos( $h_ns, 'Người Hai Nơi' ) !== false, $h_ns );
t( 'không hiện người của cơ sở khác', strpos( $h_ns, '>Người Hai<' ) === false, $h_ns );
t( '🔴 KHÔNG in PIN ra màn — chỉ nói có hay chưa',
	strpos( $h_ns, '778899' ) === false, 'có số PIN trong HTML' );
t( 'có nói là đã có PIN', strpos( $h_ns, 'có PIN' ) !== false, $h_ns );
/* 🔴 LƯƠNG KHÔNG RA TỚI MÀN NÀY — không phải ẩn bằng CSS, mà không đọc lên. */
t( '🔴 số lương KHÔNG có trong HTML của màn', strpos( $h_ns, '7000000' ) === false, 'lộ lương' );
t( 'người hai nơi được đánh dấu rõ',
	strpos( $h_ns, 'CH_HAI · CH_MOT' ) !== false || strpos( $h_ns, 'CH_MOT · CH_HAI' ) !== false, $h_ns );

/* Khối sửa: đúng bốn ô liên lạc + ô PIN, không có ô lương/cơ sở/vai trò. */
$h_sua_ns = vhcc_web_nhu2( 'NSTR', 'CUA_HANG_TRUONG', 'CH_MOT',
	array( 'man' => 'ns_coso', 'ncs' => 'CH_MOT', 'nma' => 'N1' ) );
foreach ( array( 'sdt', 'dia_chi', 'nguoi_lien_he_khan', 'sdt_khan' ) as $o_ns ) {
	t( 'khối sửa có ô ' . $o_ns, strpos( $h_sua_ns, 'name="' . $o_ns . '"' ) !== false, $h_sua_ns );
}
t( 'có ô PIN', strpos( $h_sua_ns, 'name="pin_dang_nhap"' ) !== false, $h_sua_ns );
/* 🔴 CHỮ KÝ PHẢI LÀ Ô ẨN, KHÔNG PHẢI CHỮ IN RA MÀN.
   `$ky` là chuỗi băm THÔ. `echo $ky;` trần in nguyên 64 ký tự ra giữa biểu mẫu — đè lên nhãn ô
   đầu tiên — và lượt gửi thì thiếu `name="ky"` nên bị chối, tức nút Lưu không bao giờ ăn. Bắt
   được lỗi này khi dựng thật màn ra ảnh, chứ 4400 phép trước đó không thấy: chúng chỉ hỏi "có
   ô tên X không", mà ô ấy vẫn có. */
t( '🔴 chữ ký nằm trong ô ẩn name="ky"',
	preg_match( '/<input type="hidden" name="ky" value="[0-9a-f]{64}"/', $h_sua_ns ) === 1, $h_sua_ns );
t( '🔴 và KHÔNG có chuỗi băm nào in trần ra ngoài thẻ',
	preg_match( '/>\s*[0-9a-f]{64}\s*</', $h_sua_ns ) !== 1, $h_sua_ns );
t( '🔴 ô PIN KHÔNG điền sẵn số cũ',
	strpos( $h_sua_ns, 'value="778899"' ) === false, $h_sua_ns );
foreach ( array( 'luong_co_ban', 'so_tai_khoan', 'vai_tro', 'cua_hang', 'coso_o' ) as $o_cam ) {
	t( '🔴 khối sửa KHÔNG có ô ' . $o_cam,
		strpos( $h_sua_ns, 'name="' . $o_cam . '"' ) === false, $h_sua_ns );
}
t( 'màn này không có lấy một dòng script', stripos( $h_sua_ns, '<script' ) === false, $h_sua_ns );

/* Người hai nơi: nói TRƯỚC khi gõ rằng sửa ở đây là đổi cho cả cửa hàng kia. */
$h_sua_2 = vhcc_web_nhu2( 'NSTR', 'CUA_HANG_TRUONG', 'CH_MOT',
	array( 'man' => 'ns_coso', 'ncs' => 'CH_MOT', 'nma' => 'N12' ) );
t( '🔴 báo trước rằng sửa ở đây là đổi cho cả cửa hàng kia',
	strpos( $h_sua_2, 'đổi cho <b>cả</b>' ) !== false, $h_sua_2 );
t( 'và có sổ sửa hồ sơ ngay dưới', strpos( $h_sua_2, 'Sổ sửa hồ sơ' ) !== false, $h_sua_2 );

/* =============================================================================================
 * XEM PIN Ở TRANG QUẢN LÝ NHÂN SỰ.
 * =============================================================================================
 * Anh Thắng 31/08/2026, kèm ảnh dãy nút dưới tên người: *"Bổ sung xem PIn được tại vị trí này"*.
 *
 * 🔴 LUẬT CŨ CỦA CẢ HỆ LÀ KHÔNG IN PIN RA MÀN — trang chạy ngoài internet, ảnh chụp bảng nhân
 *    sự đi khắp nơi (chính tấm ảnh kèm yêu cầu này là một ví dụ: cả bảng ra ngoài chat). Nên
 *    đường xem là BẤM MỚI HIỆN, và chỉ hiện ĐÚNG MỘT NGƯỜI. Mục này canh cả hai chiều: mở đúng
 *    người được bấm, và KHÔNG lộ ai khác.
 */
vhcc_dung_bang();
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'XP1', 'ho_ten' => 'Người Có PIN',
	'cua_hang' => 'TUTU_BT', 'pin_dang_nhap' => '246800', 'vai_tro' => 'Nhân viên' ) );
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'XP2', 'ho_ten' => 'Người Khác',
	'cua_hang' => 'TUTU_BT', 'pin_dang_nhap' => '135700', 'vai_tro' => 'Nhân viên' ) );
$wpdb->insert( VHCC_DB::t( 'nhan_vien' ), array( 'ma_nv' => 'XP3', 'ho_ten' => 'Chưa Có PIN',
	'cua_hang' => 'TUTU_BT', 'pin_dang_nhap' => '', 'vai_tro' => 'Nhân viên' ) );

/* --- (a) Bảng thường: KHÔNG một số PIN nào lọt ra --- */
$h_xp0 = vhcc_ns( 'Admin', array( 'ncs' => 'TUTU_BT' ) );
t( 'bảng có nút "xem PIN" cho Admin', strpos( $h_xp0, 'xem PIN' ) !== false, $h_xp0 );
t( '🔴 nhưng KHÔNG in sẵn số PIN nào',
	strpos( $h_xp0, '246800' ) === false && strpos( $h_xp0, '135700' ) === false, 'lộ PIN ở bảng' );

/* --- (b) Bấm xem một người: hiện ĐÚNG người ấy, không lộ ai khác --- */
$h_xp1 = vhcc_ns( 'Admin', array( 'ncs' => 'TUTU_BT', 'pin_o' => 'XP1' ) );
t( '🔴 bấm xem XP1 thì hiện PIN của XP1', strpos( $h_xp1, '246800' ) !== false, $h_xp1 );
t( '🔴 và KHÔNG lộ PIN của người khác trên cùng bảng',
	strpos( $h_xp1, '135700' ) === false, 'lộ PIN người khác' );
t( 'có nút đóng lại', strpos( $h_xp1, 'ẩn PIN' ) !== false, $h_xp1 );
t( 'và nhắc rằng lượt xem đã vào sổ', strpos( $h_xp1, 'đã vào sổ' ) !== false, $h_xp1 );

/* Người chưa có PIN: nói rõ, đừng để một ô trống trông như hỏng. */
$h_xp3 = vhcc_ns( 'Admin', array( 'ncs' => 'TUTU_BT', 'pin_o' => 'XP3' ) );
t( 'người chưa có PIN thì nói "chưa có PIN"',
	strpos( $h_xp3, 'chưa có PIN' ) !== false, $h_xp3 );
/* 🔴 VÀ KHÔNG GHI SỔ — không có gì để xem thì không có gì để ghi. Ghi cả những lượt ấy là sổ
   đầy dòng vô nghĩa, và lượt xem THẬT chìm lẫn vào giữa. */
teq( '🔴 xem người chưa có PIN thì không vào sổ', 0,
	count( VHCC_NhanSu::nhat_ky_ho_so( 'XP3' ) ) );

/* --- (c) 🔴 BẬC: Kế toán vào được TRANG nhưng KHÔNG xem được PIN --- */
$h_kt = vhcc_ns( 'Kế toán', array( 'ncs' => 'TUTU_BT' ) );
t( 'Kế toán vẫn vào được trang', strpos( $h_kt, 'Người Có PIN' ) !== false, $h_kt );
t( '🔴 nhưng KHÔNG thấy nút xem PIN', strpos( $h_kt, 'xem PIN' ) === false, $h_kt );
/* 🔴 KHÔNG CÓ NÚT KHÔNG PHẢI LÀ KHÔNG GÕ ĐƯỢC ĐỊA CHỈ. Chốt thật nằm ở tầng dưới. */
$h_kt2 = vhcc_ns( 'Kế toán', array( 'ncs' => 'TUTU_BT', 'pin_o' => 'XP1' ) );
t( '🔴 Kế toán gõ thẳng địa chỉ pin_o vẫn KHÔNG thấy PIN',
	strpos( $h_kt2, '246800' ) === false, 'lộ PIN cho bậc dưới' );

$r_kt = VHCC_NhanSu::xem_pin(
	array( 'name' => 'KT', 'role' => 'Kế toán', 'coso' => 'TUTU_BT' ), 'XP1' );
t( 'gọi thẳng hàm bằng bậc Kế toán: bị chối', empty( $r_kt['ok'] ), $r_kt );
$r_nv = VHCC_NhanSu::xem_pin(
	array( 'name' => 'NV', 'role' => 'Nhân viên', 'coso' => 'TUTU_BT' ), 'XP1' );
t( 'nhân viên thì càng không', empty( $r_nv['ok'] ), $r_nv );

/* --- (d) 🔴 MỖI LƯỢT XEM PHẢI VÀO SỔ. Biết PIN người khác là đăng nhập thay họ được mà màn
       hình của họ không có gì đổi — không ghi lại thì không còn dấu vết nào để lần. --- */
$sk_xp = VHCC_NhanSu::nhat_ky_ho_so( 'XP1' );
$dong_xem = null;
foreach ( $sk_xp as $x ) { if ( 'xem_pin' === $x['o'] ) { $dong_xem = $x; } }
t( '🔴 sổ có ghi lượt xem PIN', null !== $dong_xem, $sk_xp );
teq( 'sổ ghi tên người xem', 'Người Khai', (string) $dong_xem['ai'] );
teq( 'và chỉ ghi "đã xem"', 'đã xem', (string) $dong_xem['moi'] );
/* ⚠️ SỔ KHÔNG BAO GIỜ CHỨA SỐ PIN — sổ này người trong công ty đọc được. */
$co_so_pin = false;
foreach ( $sk_xp as $x ) {
	if ( false !== strpos( $x['cu'] . '|' . $x['moi'], '246800' ) ) { $co_so_pin = true; }
}
t( '🔴 sổ KHÔNG chứa số PIN', ! $co_so_pin, $sk_xp );
teq( 'tên ô trong sổ đọc được, không phải mã cột', 'XEM số PIN',
	VHCC_NhanSu::ten_o_nhat_ky( 'xem_pin' ) );

/* Bậc dưới bị chối thì KHÔNG được ghi sổ — ghi cả lượt trượt là sổ đầy rác và lượt xem thật
   chìm lẫn vào đó. */
$truoc = count( VHCC_NhanSu::nhat_ky_ho_so( 'XP2' ) );
VHCC_NhanSu::xem_pin( array( 'name' => 'KT', 'role' => 'Kế toán', 'coso' => 'TUTU_BT' ), 'XP2' );
teq( 'lượt bị chối KHÔNG vào sổ', $truoc, count( VHCC_NhanSu::nhat_ky_ho_so( 'XP2' ) ) );

/* --- (e) Không mở hai khối cùng lúc: bấm xem PIN thì đóng ô sửa --- */
$h_ca_hai = vhcc_ns( 'Admin', array( 'ncs' => 'TUTU_BT', 'sua_o' => 'XP2', 'pin_o' => 'XP1' ) );
t( '🔴 địa chỉ nút xem PIN gỡ luôn sua_o — hai khối chèn cùng lúc thì đẩy nhau đi',
	strpos( $h_ca_hai, 'pin_o=XP1' ) !== false
	|| strpos( $h_ca_hai, 'pin_o=XP2' ) !== false, $h_ca_hai );
t( 'trang này vẫn không có lấy một dòng script', stripos( $h_xp1, '<script' ) === false, $h_xp1 );

vhcc_dung_bang();


if ( count( $truot ) ) {
	echo "HỎNG: " . count( $truot ) . "\n";
	foreach ( $truot as $x ) { echo '  ✗ ' . $x . "\n"; }
	echo "ĐẠT: $dat\n";
	exit( 1 );
}
echo "ĐẠT: $dat phép thử — chấm công chạy thẳng trên host, máy nói chuyện với đúng một nơi.\n";
